-- fr course generated from content/fr/ (60 lessons) by scripts/generate-course-sql.mjs
-- Replaces every existing module and lesson for this language.

delete from lessons where module_id in (select id from modules where language_code = 'fr');
delete from modules where language_code = 'fr';

-- Leçon 1: Saluer et dire au revoir
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-01', 'Saluer et dire au revoir', '👋', 'Saludar y despedirse', 1, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"salut","translation":"hi / bye (informal)","translations":{"es":"hola / chao (informal)"}},{"id":"2","word":"bonjour","translation":"hello / good morning","translations":{"es":"hola / buenos días"}},{"id":"3","word":"bon après-midi","translation":"good afternoon","translations":{"es":"buenas tardes"}},{"id":"4","word":"bonsoir","translation":"good evening","translations":{"es":"buenas noches (al saludar)"}},{"id":"5","word":"bonne nuit","translation":"good night","translations":{"es":"buenas noches (al irse a dormir)"}},{"id":"6","word":"enchanté / enchantée","translation":"nice to meet you","translations":{"es":"encantado / encantada"}},{"id":"7","word":"au revoir","translation":"goodbye","translations":{"es":"adiós"}},{"id":"8","word":"bonne journée","translation":"have a nice day","translations":{"es":"que tengas un buen día"}},{"id":"9","word":"adieu","translation":"farewell (for good)","translations":{"es":"adiós (para siempre)"}},{"id":"10","word":"à plus tard","translation":"see you later","translations":{"es":"hasta luego"}},{"id":"11","word":"à tout à l''heure","translation":"see you in a bit","translations":{"es":"hasta dentro de un rato"}},{"id":"12","word":"à demain","translation":"see you tomorrow","translations":{"es":"hasta mañana"}},{"id":"13","word":"à la semaine prochaine","translation":"see you next week","translations":{"es":"hasta la próxima semana"}},{"id":"14","word":"à un de ces jours","translation":"see you one of these days","translations":{"es":"hasta un día de estos"}},{"id":"15","word":"à la prochaine","translation":"until next time","translations":{"es":"hasta la próxima"}},{"id":"16","word":"une connaissance","translation":"an acquaintance","translations":{"es":"un conocido / una conocida"}}],"grammar":[{"structure":"présent de l''indicatif","example":"Elle étudie le français à Bordeaux.","en":"Present tense","es":"Presente de indicativo"},{"structure":"inversion interrogative","example":"Comment vas-tu ? / Quand pars-tu ?","en":"Questions with subject–verb inversion","es":"Preguntas con inversión sujeto–verbo"},{"structure":"attendre que + subjonctif","example":"J''attends que le bus arrive.","en":"\"attendre que\" + subjunctive","es":"«attendre que» + subjuntivo"},{"structure":"avoir peur que / craindre que + subjonctif","example":"J''ai peur que la journée soit longue.","en":"Expressing fear + subjunctive","es":"Expresar temor + subjuntivo"},{"structure":"passé composé (négation)","example":"Je n''ai pas dormi.","en":"Past tense (passé composé), negative","es":"Pretérito perfecto (passé composé) en negativo"}],"tips":[{"en":"Say \"bonjour\" in the morning and afternoon, \"bonsoir\" from about 6 p.m., and \"bonne nuit\" only when someone is going to bed.","es":"Se dice «bonjour» por la mañana y por la tarde, «bonsoir» a partir de las 6 de la tarde aproximadamente, y «bonne nuit» solo cuando alguien se va a dormir."},{"en":"Use \"Comment vas-tu ?\" with friends and acquaintances, and \"Comment allez-vous ?\" with people you don''t know or in formal situations.","es":"Usa «Comment vas-tu ?» con amigos y conocidos, y «Comment allez-vous ?» con desconocidos o en situaciones formales."},{"en":"To introduce someone: \"Je vous présente…\" (formal) or \"Voici…\" (neutral).","es":"Para presentar a alguien: «Je vous présente…» (formal) o «Voici…» (neutro)."},{"en":"To send greetings to someone: \"Dis bonjour à … de ma part\" or \"Tu salueras …\".","es":"Para mandar saludos a alguien: «Dis bonjour à … de ma part» o «Tu salueras …»."},{"en":"\"Adieu\" is a final farewell; in everyday life, say \"au revoir\", \"à plus tard\" or \"à la prochaine\".","es":"«Adieu» es una despedida definitiva; en el día a día se dice «au revoir», «à plus tard» o «à la prochaine»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Comment ça va ?","translation":"How''s it going?","translations":{"es":"¿Qué tal?"}},{"phrase":"Ça va ?","translation":"All good?","translations":{"es":"¿Todo bien?"}},{"phrase":"Comment vas-tu ?","translation":"How are you? (informal)","translations":{"es":"¿Cómo estás?"}},{"phrase":"Comment allez-vous ?","translation":"How are you? (formal)","translations":{"es":"¿Cómo está usted?"}},{"phrase":"Quoi de neuf ?","translation":"What''s new?","translations":{"es":"¿Qué hay de nuevo?"}},{"phrase":"Comment ça se passe ?","translation":"How are things going?","translations":{"es":"¿Cómo te va?"}},{"phrase":"Bien, merci. Et toi ?","translation":"Fine, thanks. And you?","translations":{"es":"Bien, gracias. ¿Y tú?"}},{"phrase":"Pas très bien.","translation":"Not very well.","translations":{"es":"No muy bien."}},{"phrase":"Je vous présente Madame Leroy.","translation":"Let me introduce Mrs. Leroy.","translations":{"es":"Le presento a la señora Leroy."}},{"phrase":"Voici mon ami Lucas.","translation":"This is my friend Lucas.","translations":{"es":"Este es mi amigo Lucas."}},{"phrase":"Dis bonjour à ta mère de ma part.","translation":"Say hello to your mother for me.","translations":{"es":"Saluda a tu madre de mi parte."}},{"phrase":"Bonne chance ! — Merci, toi aussi.","translation":"Good luck! — Thanks, you too.","translations":{"es":"¡Buena suerte! — Gracias, tú también."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"It''s 8 p.m. and you arrive at a dinner. What do you say?","options":["Bonjour !","Bonne nuit !","Adieu !","Bonsoir !"],"correct":3,"explanation":"After about 6 p.m. you greet with \"bonsoir\". \"Bonne nuit\" is only said when going to bed.","translations":{"es":{"question":"Son las 8 de la noche y llegas a una cena. ¿Qué dices?","explanation":"A partir de las 6 de la tarde se saluda con «bonsoir». «Bonne nuit» solo se dice al irse a dormir."}}},{"id":"2","question":"You meet your new boss for the first time. Which question fits best?","options":["Salut, ça va ?","Quoi de neuf ?","Ça va ?","Comment allez-vous ?"],"correct":3,"explanation":"With people you don''t know, or in formal situations, use \"vous\": \"Comment allez-vous ?\"","translations":{"es":{"question":"Conoces a tu nueva jefa por primera vez. ¿Qué pregunta es la más adecuada?","explanation":"Con personas que no conoces o en situaciones formales se usa «vous»: «Comment allez-vous ?»"}}},{"id":"3","question":"What does \"à tout à l''heure\" mean?","options":["goodbye forever","good night","see you tomorrow","see you in a bit"],"correct":3,"explanation":"You say it when you''ll see the person again later the same day.","translations":{"es":{"question":"¿Qué significa «à tout à l''heure»?","explanation":"Se dice cuando volverás a ver a la persona más tarde, el mismo día.","options":["adiós para siempre","buenas noches","hasta mañana","hasta dentro de un rato"]}}},{"id":"4","question":"A friend asks you \"Quoi de neuf ?\". What are they asking?","options":["Where are you going?","What''s your name?","What time is it?","What''s new?"],"correct":3,"explanation":"\"Neuf\" means \"new\" here: \"Quoi de neuf ?\" = What''s new?","translations":{"es":{"question":"Un amigo te pregunta «Quoi de neuf ?». ¿Qué te está preguntando?","explanation":"Aquí «neuf» significa «nuevo»: «Quoi de neuf ?» = ¿Qué hay de nuevo?","options":["¿Adónde vas?","¿Cómo te llamas?","¿Qué hora es?","¿Qué hay de nuevo?"]}}},{"id":"5","question":"Which farewell means you won''t see the person again?","options":["À plus tard","Au revoir","À la prochaine","Adieu"],"correct":3,"explanation":"\"Adieu\" is a final farewell. In everyday life, use \"au revoir\".","translations":{"es":{"question":"¿Qué despedida indica que no volverás a ver a la persona?","explanation":"«Adieu» es una despedida definitiva. En el día a día se usa «au revoir»."}}},{"id":"6","question":"How do you introduce someone formally?","options":["Au revoir, Madame Leroy.","Je m''appelle Madame Leroy.","Comment allez-vous, Madame Leroy ?","Je vous présente Madame Leroy."],"correct":3,"explanation":"\"Je vous présente…\" introduces someone formally. Informally: \"Voici…\" or \"Je te présente…\".","translations":{"es":{"question":"¿Cómo presentas a alguien de manera formal?","explanation":"«Je vous présente…» sirve para presentar a alguien formalmente. De manera informal: «Voici…» o «Je te présente…»."}}},{"id":"7","question":"Someone asks \"Comment vas-tu ?\" and you feel bad. What do you answer?","options":["Enchanté.","À demain.","Bonne journée.","Pas très bien."],"correct":3,"explanation":"\"Pas très bien\" = not very well. If you''re fine: \"Bien, merci.\"","translations":{"es":{"question":"Alguien te pregunta «Comment vas-tu ?» y te sientes mal. ¿Qué respondes?","explanation":"«Pas très bien» = no muy bien. Si estás bien: «Bien, merci.»"}}},{"id":"8","question":"How do you say \"Say hello to your sister for me\"?","options":["Ta sœur va bien.","Je te présente ma sœur.","Comment va ta sœur ?","Dis bonjour à ta sœur de ma part."],"correct":3,"explanation":"\"De ma part\" = from me / for me.","translations":{"es":{"question":"¿Cómo se dice «Saluda a tu hermana de mi parte»?","explanation":"«De ma part» = de mi parte."}}}]}'::jsonb, 3),
  ('story', 'À l''arrêt de bus', '{"text":"Lucía est mexicaine. Cet automne, elle étudie le français à Bordeaux. Ce matin, elle attend le bus quand un garçon s''approche. « Salut ! Ça va ? Je m''appelle Hugo. » « Bonjour Hugo, enchantée. Moi, c''est Lucía. J''attends que le bus arrive pour aller à l''école. » « Tu apprends le français ? Comment ça se passe ? » « Pour l''instant, bien. Et toi, quoi de neuf ? » « Pas grand-chose. Je travaille dans une librairie près d''ici. Mais j''ai peur que la journée soit longue : je n''ai pas dormi cette nuit ! » Le bus arrive. « Courage, et bonne journée ! » « Merci, toi aussi. À la prochaine ! »","translation":"Lucía is Mexican. This autumn, she is studying French in Bordeaux. This morning, she is waiting for the bus when a young man comes up to her. “Hi! How''s it going? My name is Hugo.” “Hello Hugo, nice to meet you. I''m Lucía. I''m waiting for the bus to come so I can go to school.” “You''re learning French? How is it going?” “So far, so good. And you, what''s new?” “Not much. I work in a bookshop near here. But I''m afraid the day will be long: I didn''t sleep last night!” The bus arrives. “Hang in there, and have a nice day!” “Thanks, you too. Until next time!”","translations":{"es":"Lucía es mexicana. Este otoño estudia francés en Burdeos. Esta mañana está esperando el autobús cuando un chico se le acerca. «¡Hola! ¿Qué tal? Me llamo Hugo.» «Hola, Hugo, encantada. Yo soy Lucía. Estoy esperando a que llegue el autobús para ir a la escuela.» «¿Estás aprendiendo francés? ¿Cómo te va?» «Por ahora, bien. Y tú, ¿qué hay de nuevo?» «No mucho. Trabajo en una librería cerca de aquí. Pero me temo que el día va a ser largo: ¡no he dormido esta noche!» Llega el autobús. «¡Ánimo, y que tengas un buen día!» «Gracias, tú también. ¡Hasta la próxima!»"},"highlighted_words":["Salut","Ça va","enchantée","attends que","Comment ça se passe","quoi de neuf","peur que","bonne journée","À la prochaine"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Comment","allez-vous","aujourd''hui"],"translation":"How are you today","translations":{"es":"¿Cómo está usted hoy?"}},{"words":["Je","vous","présente","mon","ami","Lucas"],"translation":"Let me introduce my friend Lucas","translations":{"es":"Le presento a mi amigo Lucas"}},{"words":["Bien","merci","et","toi"],"translation":"Fine thanks and you","translations":{"es":"Bien, gracias, ¿y tú?"}},{"words":["Dis","bonjour","à","ta","mère"],"translation":"Say hello to your mother","translations":{"es":"Saluda a tu madre"}},{"words":["On","se","voit","la","semaine","prochaine"],"translation":"See you next week","translations":{"es":"Nos vemos la próxima semana"}},{"words":["Je","n''ai","pas","révisé","pour","l''examen"],"translation":"I didn''t study for the exam","translations":{"es":"No he estudiado para el examen"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Good evening, sir","translations":{"es":"Buenas noches, señor"},"answer":"Bonsoir, monsieur"},{"prompt":"See you tomorrow!","translations":{"es":"¡Hasta mañana!"},"answer":"À demain !"},{"prompt":"How are you? (informal, \"tu\")","translations":{"es":"¿Cómo estás? (informal, «tu»)"},"answer":"Comment vas-tu ?"},{"prompt":"What''s new?","translations":{"es":"¿Qué hay de nuevo?"},"answer":"Quoi de neuf ?"},{"prompt":"Have a nice day!","translations":{"es":"¡Que tengas un buen día!"},"answer":"Bonne journée !"},{"prompt":"I am waiting for the class to start","translations":{"es":"Estoy esperando a que empiece la clase"},"answer":"J''attends que le cours commence"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 2: Que dire ? Les formules de politesse
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-02', 'Que dire ? Les formules de politesse', '🙏', '¿Qué decir? Fórmulas de cortesía', 2, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"s''il vous plaît","translation":"please (formal)","translations":{"es":"por favor (formal)"}},{"id":"2","word":"s''il te plaît","translation":"please (informal)","translations":{"es":"por favor (informal)"}},{"id":"3","word":"merci beaucoup","translation":"thank you very much","translations":{"es":"muchas gracias"}},{"id":"4","word":"de rien","translation":"you''re welcome","translations":{"es":"de nada"}},{"id":"5","word":"ce n''est rien","translation":"it''s nothing","translations":{"es":"no es nada"}},{"id":"6","word":"avec plaisir","translation":"with pleasure","translations":{"es":"con mucho gusto"}},{"id":"7","word":"pardon","translation":"sorry / pardon","translations":{"es":"perdón"}},{"id":"8","word":"excusez-moi","translation":"excuse me","translations":{"es":"disculpe"}},{"id":"9","word":"je suis désolé / désolée","translation":"I''m sorry","translations":{"es":"lo siento"}},{"id":"10","word":"bien sûr","translation":"of course","translations":{"es":"por supuesto"}},{"id":"11","word":"aimable","translation":"kind","translations":{"es":"amable"}},{"id":"12","word":"joyeux anniversaire","translation":"happy birthday","translations":{"es":"feliz cumpleaños"}},{"id":"13","word":"joyeux Noël","translation":"merry Christmas","translations":{"es":"feliz Navidad"}},{"id":"14","word":"joyeuses Pâques","translation":"happy Easter","translations":{"es":"felices Pascuas"}},{"id":"15","word":"bonne année","translation":"happy new year","translations":{"es":"feliz año nuevo"}},{"id":"16","word":"un cadeau","translation":"a gift","translations":{"es":"un regalo"}},{"id":"17","word":"offrir","translation":"to give (as a gift)","translations":{"es":"regalar"}},{"id":"18","word":"s''excuser","translation":"to apologize","translations":{"es":"disculparse"}},{"id":"19","word":"répondre","translation":"to answer","translations":{"es":"responder"}},{"id":"20","word":"comprendre","translation":"to understand","translations":{"es":"entender"}},{"id":"21","word":"répéter","translation":"to repeat","translations":{"es":"repetir"}},{"id":"22","word":"déranger","translation":"to bother","translations":{"es":"molestar"}},{"id":"23","word":"s''amuser","translation":"to have fun","translations":{"es":"divertirse"}},{"id":"24","word":"le téléphone","translation":"the telephone","translations":{"es":"el teléfono"}}],"grammar":[{"structure":"impératif (vous / tu)","example":"Entrez, asseyez-vous. / Entre, s''il te plaît.","en":"Imperative (formal and informal)","es":"Imperativo (formal e informal)"},{"structure":"impératif négatif","example":"Ne vous inquiétez pas.","en":"Negative imperative","es":"Imperativo negativo"},{"structure":"venir de + infinitif","example":"Elle vient d''arriver à Nantes.","en":"Recent past: \"to have just done\"","es":"Pasado reciente: «acabar de»"},{"structure":"puis-je / pourrais-je + infinitif","example":"Pourrais-je avoir un thé ?","en":"Polite requests (inversion, conditional)","es":"Peticiones corteses (inversión, condicional)"},{"structure":"est-ce que + question","example":"Est-ce que vous me comprenez ?","en":"Questions with \"est-ce que\"","es":"Preguntas con «est-ce que»"},{"structure":"passé composé","example":"Qu''est-ce que vous avez dit ?","en":"Past tense (passé composé)","es":"Pretérito perfecto (passé composé)"}],"tips":[{"en":"Use \"s''il vous plaît\" with people you address as \"vous\", and \"s''il te plaît\" with friends and family.","es":"Usa «s''il vous plaît» con quien tratas de «vous» y «s''il te plaît» con amigos y familia."},{"en":"To answer \"merci\": \"de rien\", \"ce n''est rien\", \"avec plaisir\" or, more formally, \"je vous en prie\".","es":"Para responder a «merci»: «de rien», «ce n''est rien», «avec plaisir» o, más formal, «je vous en prie»."},{"en":"To return a wish (\"Bonne année !\"), answer \"Vous aussi !\", \"Toi aussi !\" or \"De même !\".","es":"Para devolver un deseo («Bonne année !»), responde «Vous aussi !», «Toi aussi !» o «De même !»."},{"en":"\"Pâques\" is feminine plural in greetings: \"Joyeuses Pâques !\". But \"Joyeux Noël\" and \"Joyeux anniversaire\".","es":"«Pâques» es femenino plural en las felicitaciones: «Joyeuses Pâques !». Pero «Joyeux Noël» y «Joyeux anniversaire»."},{"en":"\"Ça vous dérange si… ?\" means \"Do you mind if…?\". Answering \"Oui\" means it DOES bother you.","es":"«Ça vous dérange si… ?» significa «¿Le molesta si…?». Responder «Oui» quiere decir que SÍ molesta."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Puis-je vous aider ?","translation":"May I help you?","translations":{"es":"¿Puedo ayudarle?"}},{"phrase":"Pourrais-je avoir un thé, s''il vous plaît ?","translation":"Could I have a tea, please?","translations":{"es":"¿Podría tomar un té, por favor?"}},{"phrase":"Pardon, qu''est-ce que vous avez dit ?","translation":"Sorry, what did you say?","translations":{"es":"Perdón, ¿qué ha dicho?"}},{"phrase":"Excusez-moi, mais je ne comprends pas.","translation":"Excuse me, but I don''t understand.","translations":{"es":"Disculpe, pero no entiendo."}},{"phrase":"Pouvez-vous répéter, s''il vous plaît ?","translation":"Can you repeat, please?","translations":{"es":"¿Puede repetir, por favor?"}},{"phrase":"Est-ce que vous me comprenez ?","translation":"Do you understand me?","translations":{"es":"¿Me entiende?"}},{"phrase":"Où y a-t-il une pharmacie, s''il vous plaît ?","translation":"Where is there a pharmacy, please?","translations":{"es":"¿Dónde hay una farmacia, por favor?"}},{"phrase":"C''est un cadeau pour toi. — Merci beaucoup !","translation":"It''s a gift for you. — Thank you very much!","translations":{"es":"Es un regalo para ti. — ¡Muchas gracias!"}},{"phrase":"Joyeux Noël et bonne année ! — Vous aussi !","translation":"Merry Christmas and happy new year! — You too!","translations":{"es":"¡Feliz Navidad y feliz año nuevo! — ¡Igualmente!"}},{"phrase":"Entrez, je vous en prie. Asseyez-vous.","translation":"Come in, please. Have a seat.","translations":{"es":"Pase, por favor. Siéntese."}},{"phrase":"Ça vous dérange si j''ouvre la fenêtre ?","translation":"Do you mind if I open the window?","translations":{"es":"¿Le molesta si abro la ventana?"}},{"phrase":"Ne vous inquiétez pas.","translation":"Don''t worry.","translations":{"es":"No se preocupe."}},{"phrase":"Vous êtes chez vous.","translation":"Make yourself at home.","translations":{"es":"Está usted en su casa."}},{"phrase":"Bonne soirée ! — Merci, amuse-toi bien !","translation":"Have a nice evening! — Thanks, have fun!","translations":{"es":"¡Buena noche! — ¡Gracias, diviértete!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Someone says \"Merci beaucoup !\". What do you answer?","options":["Pardon.","De rien.","Bien sûr.","Bonne année."],"correct":1,"explanation":"\"De rien\" (or \"Ce n''est rien\", \"Avec plaisir\") answers a thank-you.","translations":{"es":{"question":"Alguien te dice «Merci beaucoup !». ¿Qué respondes?","explanation":"«De rien» (o «Ce n''est rien», «Avec plaisir») responde a un agradecimiento."}}},{"id":"2","question":"You didn''t hear what someone said. What do you say?","options":["Pardon, qu''est-ce que vous avez dit ?","Vous êtes chez vous.","Ne vous inquiétez pas.","Puis-je vous aider ?"],"correct":0,"explanation":"\"Qu''est-ce que vous avez dit ?\" uses the passé composé: \"What did you say?\"","translations":{"es":{"question":"No has oído lo que alguien dijo. ¿Qué dices?","explanation":"«Qu''est-ce que vous avez dit ?» usa el passé composé: «¿Qué ha dicho?»"}}},{"id":"3","question":"Which is the most polite way to ask for a coffee?","options":["Voulez-vous un café ?","Pourrais-je avoir un café, s''il vous plaît ?","C''est un café pour vous.","Prenez un café."],"correct":1,"explanation":"\"Pourrais-je…\" (conditional + inversion) is a very polite request.","translations":{"es":{"question":"¿Cuál es la forma más cortés de pedir un café?","explanation":"«Pourrais-je…» (condicional + inversión) es una petición muy cortés."}}},{"id":"4","question":"Which Easter greeting is correct?","options":["Joyeuse Pâque !","Joyeuses Pâques !","Bonne Pâques !","Joyeux Pâques !"],"correct":1,"explanation":"\"Pâques\" is feminine plural here, so the adjective is \"joyeuses\".","translations":{"es":{"question":"¿Qué felicitación de Pascua es correcta?","explanation":"Aquí «Pâques» es femenino plural, así que el adjetivo es «joyeuses»."}}},{"id":"5","question":"Your host says \"Entrez, asseyez-vous.\" What form is this?","options":["Formal imperative (vous)","The past tense","A question","Informal imperative (tu)"],"correct":0,"explanation":"With \"tu\" it would be \"Entre, assieds-toi.\"","translations":{"es":{"question":"Tu anfitrión dice «Entrez, asseyez-vous.» ¿Qué forma es?","explanation":"Con «tu» sería «Entre, assieds-toi.»","options":["Imperativo formal (vous)","El pasado","Una pregunta","Imperativo informal (tu)"]}}},{"id":"6","question":"How do you say \"Do you mind if I open the window?\"","options":["Ça vous dérange si j''ouvre la fenêtre ?","Puis-je fermer la fenêtre ?","Ouvrez la fenêtre !","Vous ouvrez la fenêtre ?"],"correct":0,"explanation":"\"Ça vous dérange si…\" + present tense.","translations":{"es":{"question":"¿Cómo se dice «¿Le molesta si abro la ventana?»?","explanation":"«Ça vous dérange si…» + presente."}}},{"id":"7","question":"What does \"Il vient d''arriver\" mean?","options":["He arrives every day.","He will arrive.","He has just arrived.","He is coming to arrive."],"correct":2,"explanation":"\"Venir de\" + infinitive expresses something that has just happened.","translations":{"es":{"question":"¿Qué significa «Il vient d''arriver»?","explanation":"«Venir de» + infinitivo expresa algo que acaba de ocurrir.","options":["Llega todos los días.","Llegará.","Acaba de llegar.","Viene a llegar."]}}},{"id":"8","question":"A friend says \"Désolé, je suis en retard !\". How do you reassure them?","options":["Joyeux anniversaire !","Je ne comprends pas.","Ne t''inquiète pas.","Bonne chance !"],"correct":2,"explanation":"Negative imperative with \"tu\": \"Ne t''inquiète pas.\" With \"vous\": \"Ne vous inquiétez pas.\"","translations":{"es":{"question":"Un amigo dice «Désolé, je suis en retard !». ¿Cómo lo tranquilizas?","explanation":"Imperativo negativo con «tu»: «Ne t''inquiète pas.» Con «vous»: «Ne vous inquiétez pas.»"}}}]}'::jsonb, 3),
  ('story', 'La nouvelle voisine', '{"text":"Nadia vient d''arriver à Nantes pour son nouveau travail. Sa voisine, Madame Morel, l''invite à prendre le thé dimanche. Nadia sonne à la porte. « Bonjour, je suis Nadia, votre nouvelle voisine. » « Bonjour Nadia ! Entrez, je vous en prie. Asseyez-vous. Qu''est-ce que vous voulez boire ? » « Un thé, s''il vous plaît. C''est très gentil. » « Mon mari est dans le jardin, il prépare un gâteau. » « Puis-je vous aider ? » « Oui, merci. Apportez ces tasses dans le jardin, s''il vous plaît. » Dans le jardin, Monsieur Morel sourit : « Voilà, Nadia, un bon thé bien chaud. » « Vous êtes très aimable, merci. » « Ce n''est rien, avec plaisir ! Ici, vous êtes chez vous. »","translation":"Nadia has just arrived in Nantes for her new job. Her neighbor, Mrs. Morel, invites her for tea on Sunday. Nadia rings the doorbell. “Hello, I''m Nadia, your new neighbor.” “Hello Nadia! Come in, please. Have a seat. What would you like to drink?” “A tea, please. That''s very kind.” “My husband is in the garden, he''s making a cake.” “May I help you?” “Yes, thank you. Take these cups to the garden, please.” In the garden, Mr. Morel smiles: “Here you are, Nadia, a nice hot tea.” “You are very kind, thank you.” “It''s nothing, with pleasure! Make yourself at home here.”","translations":{"es":"Nadia acaba de llegar a Nantes por su nuevo trabajo. Su vecina, la señora Morel, la invita a tomar el té el domingo. Nadia toca el timbre. «Hola, soy Nadia, su nueva vecina.» «¡Hola, Nadia! Pase, por favor. Siéntese. ¿Qué quiere tomar?» «Un té, por favor. Es muy amable.» «Mi marido está en el jardín, está preparando un pastel.» «¿Puedo ayudarle?» «Sí, gracias. Lleve estas tazas al jardín, por favor.» En el jardín, el señor Morel sonríe: «Aquí tiene, Nadia, un buen té bien caliente.» «Es usted muy amable, gracias.» «¡No es nada, con mucho gusto! Aquí está usted en su casa.»"},"highlighted_words":["vient d''arriver","Entrez","je vous en prie","Asseyez-vous","s''il vous plaît","Puis-je","aimable","Ce n''est rien","avec plaisir"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Pourrais-je","avoir","un","café","s''il","vous","plaît"],"translation":"Could I have a coffee please","translations":{"es":"¿Podría tomar un café, por favor?"}},{"words":["Je","suis","désolé","pour","le","retard"],"translation":"I''m sorry for being late","translations":{"es":"Siento el retraso"}},{"words":["Entrez","et","asseyez-vous"],"translation":"Come in and sit down","translations":{"es":"Pase y siéntese"}},{"words":["Merci","beaucoup","pour","le","cadeau"],"translation":"Thank you very much for the gift","translations":{"es":"Muchas gracias por el regalo"}},{"words":["Je","ne","comprends","pas","très","bien"],"translation":"I don''t understand very well","translations":{"es":"No entiendo muy bien"}},{"words":["Elle","vient","d''arriver","en","ville"],"translation":"She has just arrived in town","translations":{"es":"Acaba de llegar a la ciudad"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"You''re welcome","translations":{"es":"De nada"},"answer":"De rien"},{"prompt":"Can you repeat, please?","translations":{"es":"¿Puede repetir, por favor?"},"answer":"Pouvez-vous répéter, s''il vous plaît ?"},{"prompt":"Happy birthday!","translations":{"es":"¡Feliz cumpleaños!"},"answer":"Joyeux anniversaire !"},{"prompt":"Excuse me, I don''t understand","translations":{"es":"Disculpe, no entiendo"},"answer":"Excusez-moi, je ne comprends pas"},{"prompt":"Don''t worry (formal)","translations":{"es":"No se preocupe"},"answer":"Ne vous inquiétez pas"},{"prompt":"He has just arrived","translations":{"es":"Acaba de llegar"},"answer":"Il vient d''arriver"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 3: Les jours, les mois et le temps
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-03', 'Les jours, les mois et le temps', '📅', 'Los días, los meses y el tiempo', 3, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"lundi","translation":"Monday","translations":{"es":"lunes"}},{"id":"2","word":"mardi","translation":"Tuesday","translations":{"es":"martes"}},{"id":"3","word":"mercredi","translation":"Wednesday","translations":{"es":"miércoles"}},{"id":"4","word":"jeudi","translation":"Thursday","translations":{"es":"jueves"}},{"id":"5","word":"vendredi","translation":"Friday","translations":{"es":"viernes"}},{"id":"6","word":"samedi","translation":"Saturday","translations":{"es":"sábado"}},{"id":"7","word":"dimanche","translation":"Sunday","translations":{"es":"domingo"}},{"id":"8","word":"janvier","translation":"January","translations":{"es":"enero"}},{"id":"9","word":"février","translation":"February","translations":{"es":"febrero"}},{"id":"10","word":"mars","translation":"March","translations":{"es":"marzo"}},{"id":"11","word":"avril","translation":"April","translations":{"es":"abril"}},{"id":"12","word":"mai","translation":"May","translations":{"es":"mayo"}},{"id":"13","word":"juin","translation":"June","translations":{"es":"junio"}},{"id":"14","word":"juillet","translation":"July","translations":{"es":"julio"}},{"id":"15","word":"août","translation":"August","translations":{"es":"agosto"}},{"id":"16","word":"septembre","translation":"September","translations":{"es":"septiembre"}},{"id":"17","word":"octobre","translation":"October","translations":{"es":"octubre"}},{"id":"18","word":"novembre","translation":"November","translations":{"es":"noviembre"}},{"id":"19","word":"décembre","translation":"December","translations":{"es":"diciembre"}},{"id":"20","word":"le jour","translation":"the day","translations":{"es":"el día"}},{"id":"21","word":"la semaine","translation":"the week","translations":{"es":"la semana"}},{"id":"22","word":"le mois","translation":"the month","translations":{"es":"el mes"}},{"id":"23","word":"l''année","translation":"the year","translations":{"es":"el año"}},{"id":"24","word":"le matin","translation":"the morning","translations":{"es":"la mañana"}},{"id":"25","word":"l''après-midi","translation":"the afternoon","translations":{"es":"la tarde"}},{"id":"26","word":"le soir","translation":"the evening","translations":{"es":"la noche (temprano)"}},{"id":"27","word":"la nuit","translation":"the night","translations":{"es":"la noche"}},{"id":"28","word":"midi","translation":"noon","translations":{"es":"mediodía"}},{"id":"29","word":"minuit","translation":"midnight","translations":{"es":"medianoche"}},{"id":"30","word":"hier","translation":"yesterday","translations":{"es":"ayer"}},{"id":"31","word":"demain","translation":"tomorrow","translations":{"es":"mañana"}},{"id":"32","word":"avant-hier","translation":"the day before yesterday","translations":{"es":"anteayer"}},{"id":"33","word":"après-demain","translation":"the day after tomorrow","translations":{"es":"pasado mañana"}},{"id":"34","word":"la veille","translation":"the day before / the eve","translations":{"es":"la víspera"}},{"id":"35","word":"une quinzaine","translation":"about two weeks","translations":{"es":"unos quince días"}},{"id":"36","word":"le siècle","translation":"the century","translations":{"es":"el siglo"}},{"id":"37","word":"l''époque","translation":"the era / the time","translations":{"es":"la época"}},{"id":"38","word":"le lever du jour","translation":"daybreak","translations":{"es":"el amanecer"}},{"id":"39","word":"le coucher du soleil","translation":"sunset","translations":{"es":"la puesta de sol"}},{"id":"40","word":"prochain / prochaine","translation":"next","translations":{"es":"próximo / próxima"}},{"id":"41","word":"dernier / dernière","translation":"last","translations":{"es":"último / última"}},{"id":"42","word":"jamais","translation":"never","translations":{"es":"nunca"}},{"id":"43","word":"avant","translation":"before","translations":{"es":"antes"}},{"id":"44","word":"après","translation":"after","translations":{"es":"después"}}],"grammar":[{"structure":"passé composé","example":"Hier, j''ai parlé avec elle.","en":"Past tense (completed actions)","es":"Pretérito perfecto (acciones terminadas)"},{"structure":"imparfait","example":"À cette époque, les gens se levaient au lever du jour.","en":"Imperfect (past habits and descriptions)","es":"Imperfecto (hábitos y descripciones en el pasado)"},{"structure":"futur simple","example":"Nous partirons demain matin. / Je t''aimerai toujours.","en":"Simple future","es":"Futuro simple"},{"structure":"penser + infinitif","example":"La semaine prochaine, je pense recommencer.","en":"\"To plan to\" + infinitive","es":"«Pensar» + infinitivo"},{"structure":"verbes pronominaux","example":"Je me réveille au lever du jour.","en":"Reflexive verbs","es":"Verbos pronominales"},{"structure":"n''est-ce pas ? / si","example":"Les Français n''aiment pas manger, n''est-ce pas ? — Si !","en":"Tag questions; \"si\" to contradict a negative","es":"Preguntas de confirmación; «si» para contradecir una negación"},{"structure":"prépositions + pays","example":"au Canada, en Espagne, aux États-Unis, du Mexique","en":"Prepositions with countries","es":"Preposiciones con países"}],"tips":[{"en":"Days and months are written in lowercase in French: \"lundi\", \"janvier\".","es":"En francés, los días y los meses se escriben en minúscula: «lundi», «janvier»."},{"en":"\"Lundi\" = this (coming) Monday; \"le lundi\" = every Monday.","es":"«Lundi» = este lunes; «le lundi» = todos los lunes."},{"en":"Dates use \"le\" + number: \"le 22 juin\". The first day is \"le premier\": \"le 1er mai\".","es":"Las fechas usan «le» + número: «le 22 juin». El día uno es «le premier»: «le 1er mai»."},{"en":"Answer \"si\" (not \"oui\") to contradict a negative question.","es":"Responde «si» (no «oui») para contradecir una pregunta negativa."},{"en":"Countries: \"au\" + masculine (au Canada), \"en\" + feminine (en France), \"aux\" + plural (aux États-Unis).","es":"Países: «au» + masculino (au Canada), «en» + femenino (en France), «aux» + plural (aux États-Unis)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Quelle date sommes-nous aujourd''hui ? — Le 14 juillet.","translation":"What''s the date today? — July 14th.","translations":{"es":"¿A qué fecha estamos hoy? — A 14 de julio."}},{"phrase":"Quel jour sommes-nous ? — Nous sommes mercredi.","translation":"What day is it? — It is Wednesday.","translations":{"es":"¿Qué día es hoy? — Es miércoles."}},{"phrase":"Une année bissextile a 366 jours.","translation":"A leap year has 366 days.","translations":{"es":"Un año bisiesto tiene 366 días."}},{"phrase":"Hier, j''ai parlé avec mon frère.","translation":"Yesterday, I spoke with my brother.","translations":{"es":"Ayer hablé con mi hermano."}},{"phrase":"La semaine prochaine, je pense recommencer.","translation":"Next week, I plan to start again.","translations":{"es":"La semana que viene pienso volver a empezar."}},{"phrase":"À midi, on déjeune.","translation":"At noon, we have lunch.","translations":{"es":"A mediodía almorzamos."}},{"phrase":"Je me réveille au lever du jour.","translation":"I wake up at daybreak.","translations":{"es":"Me despierto al amanecer."}},{"phrase":"Demain, nous partirons au lever du jour.","translation":"Tomorrow, we will leave at daybreak.","translations":{"es":"Mañana saldremos al amanecer."}},{"phrase":"Je suis payé tous les quinze jours.","translation":"I get paid every two weeks.","translations":{"es":"Me pagan cada quince días."}},{"phrase":"Le lundi de Pâques est férié.","translation":"Easter Monday is a public holiday.","translations":{"es":"El lunes de Pascua es festivo."}},{"phrase":"Il est arrivé une minute en retard.","translation":"He arrived one minute late.","translations":{"es":"Llegó un minuto tarde."}},{"phrase":"D''où viens-tu ? — Je viens du Mexique.","translation":"Where are you from? — I come from Mexico.","translations":{"es":"¿De dónde eres? — Vengo de México."}},{"phrase":"Où se trouve Montréal ? — Au Canada.","translation":"Where is Montreal? — In Canada.","translations":{"es":"¿Dónde está Montreal? — En Canadá."}},{"phrase":"En Espagne, on parle espagnol, et au Brésil, on parle portugais.","translation":"In Spain, people speak Spanish, and in Brazil, Portuguese.","translations":{"es":"En España se habla español, y en Brasil, portugués."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"What does \"avant-hier\" mean?","options":["yesterday evening","the day before yesterday","the day after tomorrow","last week"],"correct":1,"explanation":"\"Avant-hier\" = the day before yesterday; \"après-demain\" = the day after tomorrow.","translations":{"es":{"question":"¿Qué significa «avant-hier»?","explanation":"«Avant-hier» = anteayer; «après-demain» = pasado mañana.","options":["ayer por la noche","anteayer","pasado mañana","la semana pasada"]}}},{"id":"2","question":"How do you ask for the date?","options":["Quelle date sommes-nous aujourd''hui ?","Quelle heure est-il ?","Quel âge as-tu ?","Quel temps fait-il ?"],"correct":0,"explanation":"The answer uses \"le\" + number: \"Le 22 juin.\"","translations":{"es":{"question":"¿Cómo preguntas la fecha?","explanation":"La respuesta usa «le» + número: «Le 22 juin.»"}}},{"id":"3","question":"Which sentence is in the past (passé composé)?","options":["Demain, je parle avec elle.","Hier, j''ai parlé avec elle.","Je parlerai avec elle.","Je parle avec elle."],"correct":1,"explanation":"Passé composé = avoir/être + past participle: \"j''ai parlé\".","translations":{"es":{"question":"¿Qué frase está en pasado (passé composé)?","explanation":"Passé composé = avoir/être + participio: «j''ai parlé»."}}},{"id":"4","question":"Which sentence is in the future?","options":["Nous sommes partis hier.","Nous partirons au lever du jour.","Nous partons maintenant.","Nous partions souvent."],"correct":1,"explanation":"Simple future: infinitive + endings (-ai, -as, -a, -ons, -ez, -ont): \"nous partirons\".","translations":{"es":{"question":"¿Qué frase está en futuro?","explanation":"Futuro simple: infinitivo + terminaciones (-ai, -as, -a, -ons, -ez, -ont): «nous partirons»."}}},{"id":"5","question":"\"Les Français n''aiment pas manger, n''est-ce pas ?\" They actually love food. What do you answer?","options":["Non, ils aiment bien manger.","Oui, ils aiment bien manger.","Si, ils aiment bien manger.","Si, ils n''aiment pas manger."],"correct":2,"explanation":"To contradict a negative question, answer \"si\".","translations":{"es":{"question":"«Les Français n''aiment pas manger, n''est-ce pas ?» En realidad les encanta comer. ¿Qué respondes?","explanation":"Para contradecir una pregunta negativa se responde «si»."}}},{"id":"6","question":"Complete: \"Montréal est ___ Canada.\"","options":["aux","en","au","à"],"correct":2,"explanation":"\"Canada\" is masculine, so \"au Canada\". Feminine countries take \"en\": \"en France\".","translations":{"es":{"question":"Completa: «Montréal est ___ Canada.»","explanation":"«Canada» es masculino, por eso «au Canada». Los países femeninos llevan «en»: «en France»."}}},{"id":"7","question":"Complete: \"Il vient ___ Portugal.\"","options":["de la","des","du","en"],"correct":2,"explanation":"\"Venir de\" + masculine country = \"du\": \"du Portugal\", \"du Mexique\".","translations":{"es":{"question":"Completa: «Il vient ___ Portugal.»","explanation":"«Venir de» + país masculino = «du»: «du Portugal», «du Mexique»."}}},{"id":"8","question":"What does \"le lundi\" mean in \"Le lundi, je travaille\"?","options":["next Monday only","last Monday","every Monday","one Monday"],"correct":2,"explanation":"With \"le\", the day expresses a habit.","translations":{"es":{"question":"¿Qué significa «le lundi» en «Le lundi, je travaille»?","explanation":"Con «le», el día expresa un hábito.","options":["solo el próximo lunes","el lunes pasado","todos los lunes","un lunes"]}}}]}'::jsonb, 3),
  ('story', 'Le temps de mon arrière-grand-mère', '{"text":"Mon arrière-grand-mère est née en 1920 dans un petit village de Bretagne. À cette époque, la vie était très différente. Les gens n''avaient pas d''électricité et tout le monde se levait au lever du jour. Le matin, elle aidait ses parents à la ferme. À midi, la famille mangeait ensemble, puis l''après-midi, on travaillait jusqu''au coucher du soleil. Le soir, on se réunissait autour du feu et on racontait les nouvelles de la journée. Au XXe siècle, le monde a beaucoup changé : les voitures, la radio et la télévision sont arrivées. Aujourd''hui, nous avons tout, mais nous n''avons jamais le temps. Demain, je lui demanderai de me raconter encore ses souvenirs.","translation":"My great-grandmother was born in 1920 in a small village in Brittany. At that time, life was very different. People had no electricity and everyone got up at daybreak. In the morning, she helped her parents on the farm. At noon, the family ate together, then in the afternoon, people worked until sunset. In the evening, they gathered around the fire and talked about the news of the day. In the 20th century, the world changed a lot: cars, the radio and television arrived. Today, we have everything, but we never have time. Tomorrow, I will ask her to tell me her memories again.","translations":{"es":"Mi bisabuela nació en 1920 en un pueblecito de Bretaña. En aquella época, la vida era muy diferente. La gente no tenía electricidad y todos se levantaban al amanecer. Por la mañana, ella ayudaba a sus padres en la granja. A mediodía, la familia comía junta y, por la tarde, se trabajaba hasta la puesta de sol. Por la noche, se reunían alrededor del fuego y contaban las noticias del día. En el siglo XX, el mundo cambió mucho: llegaron los coches, la radio y la televisión. Hoy lo tenemos todo, pero nunca tenemos tiempo. Mañana le pediré que me vuelva a contar sus recuerdos."},"highlighted_words":["époque","lever du jour","matin","midi","l''après-midi","coucher du soleil","soir","siècle","jamais","Demain"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Aujourd''hui","c''est","mercredi"],"translation":"Today is Wednesday","translations":{"es":"Hoy es miércoles"}},{"words":["Mon","anniversaire","est","en","octobre"],"translation":"My birthday is in October","translations":{"es":"Mi cumpleaños es en octubre"}},{"words":["Hier","j''ai","parlé","avec","elle"],"translation":"Yesterday I spoke with her","translations":{"es":"Ayer hablé con ella"}},{"words":["Nous","partirons","demain","matin"],"translation":"We will leave tomorrow morning","translations":{"es":"Saldremos mañana por la mañana"}},{"words":["Je","me","réveille","au","lever","du","jour"],"translation":"I wake up at daybreak","translations":{"es":"Me despierto al amanecer"}},{"words":["À","cette","époque","la","vie","était","difficile"],"translation":"At that time life was hard","translations":{"es":"En aquella época la vida era difícil"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"June 22nd","translations":{"es":"El 22 de junio"},"answer":"Le 22 juin"},{"prompt":"The day after tomorrow","translations":{"es":"Pasado mañana"},"answer":"Après-demain"},{"prompt":"Yesterday, I spoke with her","translations":{"es":"Ayer hablé con ella"},"answer":"Hier, j''ai parlé avec elle"},{"prompt":"Next week","translations":{"es":"La semana que viene"},"answer":"La semaine prochaine"},{"prompt":"At noon, we have lunch","translations":{"es":"A mediodía almorzamos"},"answer":"À midi, on déjeune"},{"prompt":"I come from Mexico","translations":{"es":"Vengo de México"},"answer":"Je viens du Mexique"}]}'::jsonb, 6)
) as v(type, title, content, ord);

