insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"onze","translation":"eleven","translations":{"es":"once"}},{"id":"2","word":"douze","translation":"twelve","translations":{"es":"doce"}},{"id":"3","word":"treize","translation":"thirteen","translations":{"es":"trece"}},{"id":"4","word":"quatorze","translation":"fourteen","translations":{"es":"catorce"}},{"id":"5","word":"quinze","translation":"fifteen","translations":{"es":"quince"}},{"id":"6","word":"seize","translation":"sixteen","translations":{"es":"dieciséis"}},{"id":"7","word":"dix-sept","translation":"seventeen","translations":{"es":"diecisiete"}},{"id":"8","word":"vingt","translation":"twenty","translations":{"es":"veinte"}},{"id":"9","word":"vingt et un","translation":"twenty-one","translations":{"es":"veintiuno"}},{"id":"10","word":"trente","translation":"thirty","translations":{"es":"treinta"}},{"id":"11","word":"quarante","translation":"forty","translations":{"es":"cuarenta"}},{"id":"12","word":"cinquante","translation":"fifty","translations":{"es":"cincuenta"}},{"id":"13","word":"soixante","translation":"sixty","translations":{"es":"sesenta"}},{"id":"14","word":"soixante-dix","translation":"seventy","translations":{"es":"setenta"}},{"id":"15","word":"quatre-vingts","translation":"eighty","translations":{"es":"ochenta"}},{"id":"16","word":"quatre-vingt-dix","translation":"ninety","translations":{"es":"noventa"}},{"id":"17","word":"cent","translation":"one hundred","translations":{"es":"cien"}},{"id":"18","word":"deux cents","translation":"two hundred","translations":{"es":"doscientos"}},{"id":"19","word":"mille","translation":"one thousand","translations":{"es":"mil"}},{"id":"20","word":"un million","translation":"a million","translations":{"es":"un millón"}},{"id":"21","word":"un milliard","translation":"a billion","translations":{"es":"mil millones"}},{"id":"22","word":"premier / première","translation":"first","translations":{"es":"primero / primera"}},{"id":"23","word":"deuxième","translation":"second","translations":{"es":"segundo"}},{"id":"24","word":"troisième","translation":"third","translations":{"es":"tercero"}},{"id":"25","word":"dixième","translation":"tenth","translations":{"es":"décimo"}},{"id":"26","word":"la moitié","translation":"half","translations":{"es":"la mitad"}},{"id":"27","word":"un tiers","translation":"a third","translations":{"es":"un tercio"}},{"id":"28","word":"un quart","translation":"a quarter","translations":{"es":"un cuarto"}},{"id":"29","word":"une douzaine","translation":"a dozen","translations":{"es":"una docena"}},{"id":"30","word":"une demi-douzaine","translation":"half a dozen","translations":{"es":"media docena"}}],"grammar":[{"structure":"nombres cardinaux","example":"soixante-dix, quatre-vingts, quatre-vingt-dix","en":"Cardinal numbers","es":"Números cardinales"},{"structure":"nombres ordinaux","example":"premier, deuxième, troisième… vingtième","en":"Ordinal numbers","es":"Números ordinales"},{"structure":"fractions","example":"la moitié, un tiers, un quart","en":"Fractions","es":"Fracciones"},{"structure":"être en train de + infinitif","example":"Il est en train de compter.","en":"Action in progress","es":"Acción en curso («estar» + gerundio)"},{"structure":"c''est la … fois que","example":"C''est la troisième fois que je te le dis.","en":"\"It''s the … time that\"","es":"«Es la … vez que»"},{"structure":"passé composé avec être","example":"Je suis née en 1990.","en":"Past tense with \"être\" (agreement)","es":"Passé composé con «être» (concordancia)"},{"structure":"impératif","example":"Coupe-le en quatre, s''il te plaît.","en":"Imperative with an object pronoun","es":"Imperativo con pronombre"}],"tips":[{"en":"70 = soixante-dix (60 + 10), 80 = quatre-vingts (4 × 20), 90 = quatre-vingt-dix (4 × 20 + 10). In Belgium and Switzerland: septante, (huitante), nonante.","es":"70 = soixante-dix (60 + 10), 80 = quatre-vingts (4 × 20), 90 = quatre-vingt-dix (4 × 20 + 10). En Bélgica y Suiza: septante, (huitante), nonante."},{"en":"Use \"et\" in 21, 31, 41, 51, 61 and 71 (vingt et un, soixante et onze), but not in 81 or 91 (quatre-vingt-un).","es":"Se usa «et» en 21, 31, 41, 51, 61 y 71 (vingt et un, soixante et onze), pero no en 81 ni 91 (quatre-vingt-un)."},{"en":"\"Quatre-vingts\" and \"deux cents\" take an -s only when nothing follows: quatre-vingt-trois, deux cent dix. \"Mille\" never takes -s.","es":"«Quatre-vingts» y «deux cents» llevan -s solo si no les sigue otro número: quatre-vingt-trois, deux cent dix. «Mille» nunca lleva -s."},{"en":"Ordinals add -ième (deuxième, dixième), except \"premier / première\".","es":"Los ordinales añaden -ième (deuxième, dixième), excepto «premier / première»."},{"en":"Birthdays use ordinals: \"mon cinquantième anniversaire\". Big amounts: \"un million de\", \"un milliard de\".","es":"Los cumpleaños usan ordinales: «mon cinquantième anniversaire». Cantidades grandes: «un million de», «un milliard de»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Deux plus deux est égal à quatre.","translation":"Two plus two equals four.","translations":{"es":"Dos más dos es igual a cuatro."}},{"phrase":"Six moins trois est égal à trois.","translation":"Six minus three equals three.","translations":{"es":"Seis menos tres es igual a tres."}},{"phrase":"Sept fois huit est égal à cinquante-six.","translation":"Seven times eight equals fifty-six.","translations":{"es":"Siete por ocho es igual a cincuenta y seis."}},{"phrase":"Cent divisé par deux est égal à cinquante.","translation":"One hundred divided by two equals fifty.","translations":{"es":"Cien entre dos es igual a cincuenta."}},{"phrase":"C''est la troisième fois que je te le dis !","translation":"It''s the third time I''m telling you!","translations":{"es":"¡Es la tercera vez que te lo digo!"}},{"phrase":"Elle arrive toujours à la deuxième place.","translation":"She always comes in second place.","translations":{"es":"Siempre llega en segundo lugar."}},{"phrase":"Je reviens dans un quart d''heure.","translation":"I''ll be back in a quarter of an hour.","translations":{"es":"Vuelvo en un cuarto de hora."}},{"phrase":"Un tiers de la classe parle espagnol.","translation":"A third of the class speaks Spanish.","translations":{"es":"Un tercio de la clase habla español."}},{"phrase":"Tu es la première personne à qui je parle.","translation":"You are the first person I talk to.","translations":{"es":"Eres la primera persona con la que hablo."}},{"phrase":"C''est combien ? — Trois euros.","translation":"How much is it? — Three euros.","translations":{"es":"¿Cuánto es? — Tres euros."}},{"phrase":"En quelle année êtes-vous né ? — Je suis né en 1985.","translation":"What year were you born? — I was born in 1985.","translations":{"es":"¿En qué año nació? — Nací en 1985."}},{"phrase":"Quand est ton anniversaire ? — Le 17 mars.","translation":"When is your birthday? — March 17th.","translations":{"es":"¿Cuándo es tu cumpleaños? — El 17 de marzo."}},{"phrase":"Je voudrais une demi-douzaine d''œufs, s''il vous plaît.","translation":"I would like half a dozen eggs, please.","translations":{"es":"Quisiera media docena de huevos, por favor."}},{"phrase":"Il est en train de compter les invités.","translation":"He is counting the guests.","translations":{"es":"Está contando a los invitados."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you say 70 in France?","options":["sept-dix","septante-dix","soixante-sept","soixante-dix"],"correct":3,"explanation":"70 = 60 + 10. In Belgium and Switzerland people say \"septante\".","translations":{"es":{"question":"¿Cómo se dice 70 en Francia?","explanation":"70 = 60 + 10. En Bélgica y Suiza se dice «septante»."}}},{"id":"2","question":"How do you say 80?","options":["quatre-dix","huit-dix","soixante-vingt","quatre-vingts"],"correct":3,"explanation":"80 = 4 × 20: \"quatre-vingts\".","translations":{"es":{"question":"¿Cómo se dice 80?","explanation":"80 = 4 × 20: «quatre-vingts»."}}},{"id":"3","question":"How do you say \"7 × 8 = 56\"?","options":["Sept plus huit est égal à cinquante-six.","Sept divisé par huit est égal à cinquante-six.","Sept moins huit est égal à cinquante-six.","Sept fois huit est égal à cinquante-six."],"correct":3,"explanation":"plus (+), moins (−), fois (×), divisé par (÷).","translations":{"es":{"question":"¿Cómo se dice «7 × 8 = 56»?","explanation":"plus (+), moins (−), fois (×), divisé par (÷)."}}},{"id":"4","question":"What is \"la moitié\"?","options":["a third","a quarter","a dozen","half"],"correct":3,"explanation":"\"La moitié\" = 1/2, \"un tiers\" = 1/3, \"un quart\" = 1/4.","translations":{"es":{"question":"¿Qué es «la moitié»?","explanation":"«La moitié» = 1/2, «un tiers» = 1/3, «un quart» = 1/4.","options":["un tercio","un cuarto","una docena","la mitad"]}}},{"id":"5","question":"You want 6 eggs. What do you ask for?","options":["deux douzaines d''œufs","une douzaine d''œufs","un quart d''œufs","une demi-douzaine d''œufs"],"correct":3,"explanation":"Une douzaine = 12, une demi-douzaine = 6.","translations":{"es":{"question":"Quieres 6 huevos. ¿Qué pides?","explanation":"Une douzaine = 12, une demi-douzaine = 6."}}},{"id":"6","question":"How do you talk about a 50th birthday?","options":["mon cinquième anniversaire","mon cinquante anniversaire","ma cinquantaine anniversaire","mon cinquantième anniversaire"],"correct":3,"explanation":"Birthdays use ordinal numbers: cinquante → cinquantième.","translations":{"es":{"question":"¿Cómo hablas de un 50.º cumpleaños?","explanation":"Los cumpleaños usan ordinales: cinquante → cinquantième."}}},{"id":"7","question":"What does \"Il est en train de compter\" mean?","options":["He counted.","He can count.","He will count.","He is counting (right now)."],"correct":3,"explanation":"\"Être en train de\" + infinitive = an action in progress.","translations":{"es":{"question":"¿Qué significa «Il est en train de compter»?","explanation":"«Être en train de» + infinitivo = una acción en curso.","options":["Contó.","Sabe contar.","Contará.","Está contando (ahora mismo)."]}}},{"id":"8","question":"Which number is written correctly?","options":["quatre-vingtrois","quatre-vingt-et-trois","quatre-vingts-trois","quatre-vingt-trois"],"correct":3,"explanation":"\"Quatre-vingts\" loses its -s when another number follows.","translations":{"es":{"question":"¿Qué número está bien escrito?","explanation":"«Quatre-vingts» pierde la -s cuando le sigue otro número."}}}]}'::jsonb, 3),
  ('story', 'Léo compte tout', '{"text":"Léo a dix ans et il adore compter. Ce matin, il est en train de compter les marches de l''escalier : il y en a quarante-deux ! Au marché, sa mère achète une douzaine d''œufs et une demi-douzaine de pommes. Léo calcule : « Six pommes à deux euros, ça fait douze euros ! » L''après-midi, il regarde le lancement d''une fusée à la télévision avec son grand-père. Ensemble, ils font le compte à rebours : « Dix, neuf, huit, sept, six, cinq, quatre, trois, deux, un, zéro ! » Ce soir, c''est le soixante-dixième anniversaire de son grand-père. « Coupe le gâteau en quatre, s''il te plaît », dit sa mère. Un quart pour chacun : c''est la première fois que Léo fait des fractions à table !","translation":"Léo is ten years old and he loves counting. This morning, he is counting the steps of the staircase: there are forty-two! At the market, his mother buys a dozen eggs and half a dozen apples. Léo calculates: “Six apples at two euros, that makes twelve euros!” In the afternoon, he watches a rocket launch on TV with his grandfather. Together, they do the countdown: “Ten, nine, eight, seven, six, five, four, three, two, one, zero!” Tonight is his grandfather''s seventieth birthday. “Cut the cake into four, please,” says his mother. A quarter each: it''s the first time Léo has done fractions at the table!","translations":{"es":"Léo tiene diez años y le encanta contar. Esta mañana está contando los escalones de la escalera: ¡hay cuarenta y dos! En el mercado, su madre compra una docena de huevos y media docena de manzanas. Léo calcula: «Seis manzanas a dos euros, ¡son doce euros!». Por la tarde, ve el lanzamiento de un cohete en la televisión con su abuelo. Juntos hacen la cuenta atrás: «¡Diez, nueve, ocho, siete, seis, cinco, cuatro, tres, dos, uno, cero!». Esta noche es el septuagésimo cumpleaños de su abuelo. «Corta el pastel en cuatro, por favor», dice su madre. Un cuarto para cada uno: ¡es la primera vez que Léo hace fracciones en la mesa!"},"highlighted_words":["en train de compter","quarante-deux","douzaine","demi-douzaine","soixante-dixième","quart","première fois"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Deux","plus","deux","est","égal","à","quatre"],"translation":"Two plus two equals four","translations":{"es":"Dos más dos es igual a cuatro"}},{"words":["C''est","la","troisième","fois"],"translation":"It''s the third time","translations":{"es":"Es la tercera vez"}},{"words":["Je","voudrais","une","douzaine","d''œufs"],"translation":"I would like a dozen eggs","translations":{"es":"Quisiera una docena de huevos"}},{"words":["Il","est","en","train","de","compter"],"translation":"He is counting","translations":{"es":"Está contando"}},{"words":["Mon","anniversaire","est","le","dix-sept","mars"],"translation":"My birthday is March seventeenth","translations":{"es":"Mi cumpleaños es el diecisiete de marzo"}},{"words":["J''habite","au","cinquième","étage"],"translation":"I live on the fifth floor","translations":{"es":"Vivo en el quinto piso"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"A quarter of an hour","translations":{"es":"Un cuarto de hora"},"answer":"Un quart d''heure"},{"prompt":"One hundred divided by two equals fifty","translations":{"es":"Cien entre dos es igual a cincuenta"},"answer":"Cent divisé par deux est égal à cinquante"},{"prompt":"He was born in 1990","translations":{"es":"Nació en 1990"},"answer":"Il est né en 1990"},{"prompt":"Half a dozen apples","translations":{"es":"Media docena de manzanas"},"answer":"Une demi-douzaine de pommes"},{"prompt":"How much is it?","translations":{"es":"¿Cuánto es?"},"answer":"C''est combien ?"},{"prompt":"She is working (right now)","translations":{"es":"Está trabajando (ahora mismo)"},"answer":"Elle est en train de travailler"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 5: Les prénoms, les couleurs et le caractère
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-05', 'Les prénoms, les couleurs et le caractère', '🎨', 'Los nombres, los colores y el carácter', 5, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le prénom","translation":"the first name","translations":{"es":"el nombre de pila"}},{"id":"2","word":"bleu / bleue","translation":"blue","translations":{"es":"azul"}},{"id":"3","word":"jaune","translation":"yellow","translations":{"es":"amarillo"}},{"id":"4","word":"vert / verte","translation":"green","translations":{"es":"verde"}},{"id":"5","word":"blanc / blanche","translation":"white","translations":{"es":"blanco / blanca"}},{"id":"6","word":"noir / noire","translation":"black","translations":{"es":"negro / negra"}},{"id":"7","word":"rouge","translation":"red","translations":{"es":"rojo"}},{"id":"8","word":"orange","translation":"orange","translations":{"es":"naranja"}},{"id":"9","word":"marron","translation":"brown","translations":{"es":"marrón"}},{"id":"10","word":"rose","translation":"pink","translations":{"es":"rosa"}},{"id":"11","word":"gris / grise","translation":"grey","translations":{"es":"gris"}},{"id":"12","word":"violet / violette","translation":"purple","translations":{"es":"morado / morada"}},{"id":"13","word":"mauve","translation":"mauve","translations":{"es":"malva"}},{"id":"14","word":"bleu ciel","translation":"sky blue","translations":{"es":"azul celeste"}},{"id":"15","word":"bordeaux","translation":"burgundy","translations":{"es":"burdeos"}},{"id":"16","word":"châtain","translation":"light brown (hair)","translations":{"es":"castaño (pelo)"}},{"id":"17","word":"roux / rousse","translation":"red-haired","translations":{"es":"pelirrojo / pelirroja"}},{"id":"18","word":"foncé","translation":"dark (color)","translations":{"es":"oscuro"}},{"id":"19","word":"clair","translation":"light (color)","translations":{"es":"claro"}},{"id":"20","word":"pâle","translation":"pale","translations":{"es":"pálido"}},{"id":"21","word":"heureux / heureuse","translation":"happy","translations":{"es":"feliz"}},{"id":"22","word":"souriant / souriante","translation":"smiling","translations":{"es":"sonriente"}},{"id":"23","word":"fatigué / fatiguée","translation":"tired","translations":{"es":"cansado / cansada"}},{"id":"24","word":"loyal / loyale","translation":"loyal","translations":{"es":"leal"}},{"id":"25","word":"paresseux / paresseuse","translation":"lazy","translations":{"es":"perezoso / perezosa"}},{"id":"26","word":"égoïste","translation":"selfish","translations":{"es":"egoísta"}},{"id":"27","word":"déprimé / déprimée","translation":"depressed / down","translations":{"es":"deprimido / deprimida"}},{"id":"28","word":"digne de confiance","translation":"trustworthy","translations":{"es":"de confianza"}}],"grammar":[{"structure":"accord des adjectifs de couleur","example":"Marie a les yeux bleus. / une chemise blanche","en":"Color adjective agreement","es":"Concordancia de los adjetivos de color"},{"structure":"couleurs invariables","example":"des chaussettes orange, les cheveux marron foncé","en":"Invariable colors (marron, orange, compound colors)","es":"Colores invariables (marron, orange, colores compuestos)"},{"structure":"comparatif","example":"Cécile est plus petite que Victoire.","en":"Comparatives (plus / moins / aussi … que)","es":"Comparativos (plus / moins / aussi … que)"},{"structure":"superlatif","example":"Sarah est la plus sérieuse de la maison.","en":"Superlatives","es":"Superlativos"},{"structure":"pronom « le » (attribut)","example":"Est-ce qu''il est fatigué ? — Non, il ne l''est pas.","en":"\"le\" replacing an adjective","es":"«le» que sustituye a un adjetivo"},{"structure":"être à (possession)","example":"Le blouson violet est à Jean.","en":"Possession with \"être à\"","es":"Posesión con «être à»"},{"structure":"pronoms possessifs","example":"Et les tiens, comment sont-ils ?","en":"Possessive pronouns","es":"Pronombres posesivos"}],"tips":[{"en":"Colors usually go after the noun and agree with it: \"une voiture verte\", \"des yeux verts\".","es":"Los colores suelen ir después del sustantivo y concuerdan con él: «une voiture verte», «des yeux verts»."},{"en":"\"Marron\" and \"orange\" never change: \"des chaussures marron\". Compound colors don''t change either: \"des yeux bleu clair\".","es":"«Marron» y «orange» nunca cambian: «des chaussures marron». Los colores compuestos tampoco: «des yeux bleu clair»."},{"en":"For hair, French says \"châtain\" (light brown), \"brun\" (dark) or \"roux\" (red); for eyes, \"marron\".","es":"Para el pelo se dice «châtain» (castaño), «brun» (moreno) o «roux» (pelirrojo); para los ojos, «marron»."},{"en":"Answer \"Est-ce qu''il est grand ?\" with \"Oui, il l''est\" / \"Non, il ne l''est pas\" — \"le\" replaces the adjective.","es":"Responde a «Est-ce qu''il est grand ?» con «Oui, il l''est» / «Non, il ne l''est pas»: «le» sustituye al adjetivo."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Hugo et Malik sont amis.","translation":"Hugo and Malik are friends.","translations":{"es":"Hugo y Malik son amigos."}},{"phrase":"Emma a les yeux bleus.","translation":"Emma has blue eyes.","translations":{"es":"Emma tiene los ojos azules."}},{"phrase":"Lina a les cheveux châtains.","translation":"Lina has light-brown hair.","translations":{"es":"Lina tiene el pelo castaño."}},{"phrase":"Paul a les cheveux marron foncé.","translation":"Paul has dark-brown hair.","translations":{"es":"Paul tiene el pelo castaño oscuro."}},{"phrase":"Antoine porte une cravate noire.","translation":"Antoine is wearing a black tie.","translations":{"es":"Antoine lleva una corbata negra."}},{"phrase":"La voiture rose est à Julie.","translation":"The pink car belongs to Julie.","translations":{"es":"El coche rosa es de Julie."}},{"phrase":"Où est Théo en ce moment ? — Il est à la fac.","translation":"Where is Théo right now? — He is at university.","translations":{"es":"¿Dónde está Théo ahora? — Está en la universidad."}},{"phrase":"Est-ce que Nathan est plus grand qu''Adam ? — Non, il ne l''est pas.","translation":"Is Nathan taller than Adam? — No, he isn''t.","translations":{"es":"¿Nathan es más alto que Adam? — No, no lo es."}},{"phrase":"Est-ce que Chloé est plus petite que Manon ? — Oui, elle l''est.","translation":"Is Chloé shorter than Manon? — Yes, she is.","translations":{"es":"¿Chloé es más baja que Manon? — Sí, lo es."}},{"phrase":"Qui êtes-vous ? — Je suis Camille, la nouvelle directrice.","translation":"Who are you? — I am Camille, the new manager.","translations":{"es":"¿Quién es usted? — Soy Camille, la nueva directora."}},{"phrase":"Ils ne sont pas là : ils sont en vacances.","translation":"They aren''t here: they are on vacation.","translations":{"es":"No están: están de vacaciones."}},{"phrase":"Léa est la meilleure danseuse de la classe.","translation":"Léa is the best dancer in the class.","translations":{"es":"Léa es la mejor bailarina de la clase."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Emma a les yeux ___.\" (blue)","options":["bleu","bleus","bleue","bleues"],"correct":1,"explanation":"\"Yeux\" is masculine plural, so \"bleus\".","translations":{"es":{"question":"Completa: «Emma a les yeux ___.» (azules)","explanation":"«Yeux» es masculino plural, por eso «bleus»."}}},{"id":"2","question":"Complete: \"Elle porte une chemise ___.\" (white)","options":["blanches","blanc","blanche","blancs"],"correct":2,"explanation":"\"Blanc\" becomes \"blanche\" in the feminine.","translations":{"es":{"question":"Completa: «Elle porte une chemise ___.» (blanca)","explanation":"«Blanc» se convierte en «blanche» en femenino."}}},{"id":"3","question":"Which is correct?","options":["des chaussures marrons","des chaussures marronne","des chaussures marron","des chaussures marronnes"],"correct":2,"explanation":"\"Marron\" (like \"orange\") is invariable.","translations":{"es":{"question":"¿Cuál es correcta?","explanation":"«Marron» (como «orange») es invariable."}}},{"id":"4","question":"\"Est-ce que Paul est fatigué ?\" — \"Non, il ne ___ est pas.\"","options":["le","les","l''","la"],"correct":2,"explanation":"\"Le\" replaces the adjective \"fatigué\"; it becomes \"l''\" before \"est\".","translations":{"es":{"question":"«Est-ce que Paul est fatigué ?» — «Non, il ne ___ est pas.»","explanation":"«Le» sustituye al adjetivo «fatigué»; se convierte en «l''» delante de «est»."}}},{"id":"5","question":"Complete: \"Chloé est ___ petite ___ Manon.\"","options":["plus … que","le plus … que","plus … de","très … que"],"correct":0,"explanation":"Comparative: plus / moins / aussi + adjective + que.","translations":{"es":{"question":"Completa: «Chloé est ___ petite ___ Manon.»","explanation":"Comparativo: plus / moins / aussi + adjetivo + que."}}},{"id":"6","question":"How do you say \"the most intelligent in the class\"?","options":["la plus intelligente de la classe","la très intelligente de la classe","la plus intelligente que la classe","plus intelligente de la classe"],"correct":0,"explanation":"Superlative: le / la / les plus + adjective + de.","translations":{"es":{"question":"¿Cómo se dice «la más inteligente de la clase»?","explanation":"Superlativo: le / la / les plus + adjetivo + de."}}},{"id":"7","question":"What does \"Le blouson violet est à Jean\" mean?","options":["Jean wants a purple jacket.","The purple jacket belongs to Jean.","The purple jacket is at Jean''s house.","Jean is wearing a purple jacket."],"correct":1,"explanation":"\"Être à quelqu''un\" expresses possession.","translations":{"es":{"question":"¿Qué significa «Le blouson violet est à Jean»?","explanation":"«Être à quelqu''un» expresa posesión.","options":["Jean quiere una chaqueta morada.","La chaqueta morada es de Jean.","La chaqueta morada está en casa de Jean.","Jean lleva una chaqueta morada."]}}},{"id":"8","question":"What does \"paresseux\" mean?","options":["lazy","selfish","loyal","happy"],"correct":0,"explanation":"Feminine: \"paresseuse\".","translations":{"es":{"question":"¿Qué significa «paresseux»?","explanation":"Femenino: «paresseuse».","options":["perezoso","egoísta","leal","feliz"]}}}]}'::jsonb, 3),
  ('story', 'Mes colocataires', '{"text":"Je m''appelle Inès. J''étudie le droit à Lille et j''habite avec quatre colocataires. Je voudrais vous parler d''eux. Karim est le plus drôle de la maison : il porte toujours des chaussettes orange. Élodie est rousse et elle a les yeux verts ; elle est toujours souriante et j''adore sa compagnie. Thomas est gentil, mais il est un peu paresseux : on ne peut pas compter sur lui pour faire la vaisselle ! Sarah est la plus sérieuse de nous tous : elle étudie la médecine et elle est toujours fatiguée. Moi, j''essaie de ne pas juger mes amis, mais ce n''est pas facile ! Ma vraie confidente, c''est Élodie, même si elle n''aime pas mon chat noir. Voilà mes colocataires. Et les tiens, comment sont-ils ?","translation":"My name is Inès. I study law in Lille and I live with four roommates. I would like to tell you about them. Karim is the funniest in the house: he always wears orange socks. Élodie has red hair and green eyes; she is always smiling and I love her company. Thomas is nice, but he is a bit lazy: you can''t count on him to do the dishes! Sarah is the most serious of us all: she studies medicine and she is always tired. As for me, I try not to judge my friends, but it isn''t easy! My true confidant is Élodie, even if she doesn''t like my black cat. Those are my roommates. And yours, what are they like?","translations":{"es":"Me llamo Inès. Estudio Derecho en Lille y vivo con cuatro compañeros de piso. Me gustaría hablarles de ellos. Karim es el más gracioso de la casa: siempre lleva calcetines naranja. Élodie es pelirroja y tiene los ojos verdes; siempre está sonriente y me encanta su compañía. Thomas es amable, pero un poco perezoso: ¡no se puede contar con él para fregar los platos! Sarah es la más seria de todos: estudia Medicina y siempre está cansada. Yo intento no juzgar a mis amigos, ¡pero no es fácil! Mi verdadera confidente es Élodie, aunque no le guste mi gato negro. Estos son mis compañeros de piso. Y los tuyos, ¿cómo son?"},"highlighted_words":["le plus drôle","orange","rousse","verts","souriante","paresseux","la plus sérieuse","fatiguée","noir","les tiens"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Marie","a","les","yeux","bleus"],"translation":"Marie has blue eyes","translations":{"es":"Marie tiene los ojos azules"}},{"words":["Le","blouson","violet","est","à","Jean"],"translation":"The purple jacket belongs to Jean","translations":{"es":"La chaqueta morada es de Jean"}},{"words":["Elle","est","plus","petite","que","moi"],"translation":"She is shorter than me","translations":{"es":"Es más baja que yo"}},{"words":["Il","est","le","plus","drôle","de","la","classe"],"translation":"He is the funniest in the class","translations":{"es":"Es el más gracioso de la clase"}},{"words":["Non","il","ne","l''est","pas"],"translation":"No he isn''t","translations":{"es":"No, no lo es"}},{"words":["Ils","sont","en","vacances"],"translation":"They are on vacation","translations":{"es":"Están de vacaciones"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"My car is red","translations":{"es":"Mi coche es rojo"},"answer":"Ma voiture est rouge"},{"prompt":"She has light-brown hair","translations":{"es":"Tiene el pelo castaño"},"answer":"Elle a les cheveux châtains"},{"prompt":"He is taller than his brother","translations":{"es":"Es más alto que su hermano"},"answer":"Il est plus grand que son frère"},{"prompt":"No, he isn''t","translations":{"es":"No, no lo es"},"answer":"Non, il ne l''est pas"},{"prompt":"She''s the most intelligent","translations":{"es":"Es la más inteligente"},"answer":"C''est la plus intelligente"},{"prompt":"The black cat is mine","translations":{"es":"El gato negro es mío"},"answer":"Le chat noir est à moi"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 6: La famille
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-06', 'La famille', '👨‍👩‍👧‍👦', 'La familia', 6, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la famille","translation":"the family","translations":{"es":"la familia"}},{"id":"2","word":"les parents","translation":"the parents","translations":{"es":"los padres"}},{"id":"3","word":"les grands-parents","translation":"the grandparents","translations":{"es":"los abuelos"}},{"id":"4","word":"le grand-père","translation":"the grandfather","translations":{"es":"el abuelo"}},{"id":"5","word":"la grand-mère","translation":"the grandmother","translations":{"es":"la abuela"}},{"id":"6","word":"le père","translation":"the father","translations":{"es":"el padre"}},{"id":"7","word":"la mère","translation":"the mother","translations":{"es":"la madre"}},{"id":"8","word":"le fils","translation":"the son","translations":{"es":"el hijo"}},{"id":"9","word":"la fille","translation":"the daughter","translations":{"es":"la hija"}},{"id":"10","word":"l''époux / l''épouse","translation":"the husband / the wife","translations":{"es":"el esposo / la esposa"}},{"id":"11","word":"le frère","translation":"the brother","translations":{"es":"el hermano"}},{"id":"12","word":"la sœur","translation":"the sister","translations":{"es":"la hermana"}},{"id":"13","word":"les frères et sœurs","translation":"siblings","translations":{"es":"los hermanos"}},{"id":"14","word":"le fiancé / la fiancée","translation":"the fiancé / the fiancée","translations":{"es":"el prometido / la prometida"}},{"id":"15","word":"l''oncle","translation":"the uncle","translations":{"es":"el tío"}},{"id":"16","word":"la tante","translation":"the aunt","translations":{"es":"la tía"}},{"id":"17","word":"le cousin / la cousine","translation":"the cousin","translations":{"es":"el primo / la prima"}},{"id":"18","word":"le neveu","translation":"the nephew","translations":{"es":"el sobrino"}},{"id":"19","word":"la nièce","translation":"the niece","translations":{"es":"la sobrina"}},{"id":"20","word":"le beau-père","translation":"the father-in-law / stepfather","translations":{"es":"el suegro / el padrastro"}},{"id":"21","word":"la belle-mère","translation":"the mother-in-law / stepmother","translations":{"es":"la suegra / la madrastra"}},{"id":"22","word":"le beau-frère","translation":"the brother-in-law","translations":{"es":"el cuñado"}},{"id":"23","word":"la belle-sœur","translation":"the sister-in-law","translations":{"es":"la cuñada"}},{"id":"24","word":"le gendre","translation":"the son-in-law","translations":{"es":"el yerno"}},{"id":"25","word":"la belle-fille","translation":"the daughter-in-law","translations":{"es":"la nuera"}},{"id":"26","word":"le parrain","translation":"the godfather","translations":{"es":"el padrino"}},{"id":"27","word":"la marraine","translation":"the godmother","translations":{"es":"la madrina"}},{"id":"28","word":"le filleul / la filleule","translation":"the godson / the goddaughter","translations":{"es":"el ahijado / la ahijada"}},{"id":"29","word":"l''aîné / l''aînée","translation":"the eldest","translations":{"es":"el mayor / la mayor"}},{"id":"30","word":"le cadet / la cadette","translation":"the youngest","translations":{"es":"el menor / la menor"}}],"grammar":[{"structure":"adjectifs possessifs","example":"mon père, ma mère, mes grands-parents","en":"Possessive adjectives","es":"Adjetivos posesivos"},{"structure":"s''appeler","example":"Ma mère s''appelle Anne.","en":"Saying names with \"s''appeler\"","es":"Decir el nombre con «s''appeler»"},{"structure":"avoir + âge","example":"Mon père a cinquante ans.","en":"Age with \"avoir\"","es":"La edad con «avoir»"},{"structure":"futur proche","example":"Son fils va se marier en juin.","en":"Near future (aller + infinitive)","es":"Futuro próximo (aller + infinitivo)"},{"structure":"superlatif","example":"Je suis la plus bavarde de ses nièces.","en":"Superlatives","es":"Superlativos"},{"structure":"pronoms possessifs","example":"Parlez-moi de la vôtre.","en":"Possessive pronouns","es":"Pronombres posesivos"},{"structure":"qu''est-ce que + inversion","example":"Qu''est-ce que fait ton père ?","en":"Asking what someone does","es":"Preguntar a qué se dedica alguien"}],"tips":[{"en":"Possessives agree with the thing possessed, not the owner: \"sa mère\" = his OR her mother.","es":"Los posesivos concuerdan con lo poseído, no con el poseedor: «sa mère» = la madre de él O de ella."},{"en":"Before a vowel, \"ma / ta / sa\" become \"mon / ton / son\": \"mon amie\", \"son épouse\".","es":"Delante de vocal, «ma / ta / sa» pasan a «mon / ton / son»: «mon amie», «son épouse»."},{"en":"\"Beau-\" / \"belle-\" covers both in-laws and step-family: \"belle-mère\" = mother-in-law or stepmother.","es":"«Beau-» / «belle-» sirve para la familia política y para padrastros: «belle-mère» = suegra o madrastra."},{"en":"French uses \"avoir\" for age: \"J''ai vingt ans\" (never \"je suis vingt ans\").","es":"En francés la edad se dice con «avoir»: «J''ai vingt ans» (nunca «je suis vingt ans»)."},{"en":"\"L''aîné(e)\" = the eldest child; \"le cadet / la cadette\" = the younger one.","es":"«L''aîné(e)» = el hijo mayor; «le cadet / la cadette» = el menor."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Mon père s''appelle Marc. Il est architecte.","translation":"My father is called Marc. He is an architect.","translations":{"es":"Mi padre se llama Marc. Es arquitecto."}},{"phrase":"Ma mère est infirmière. Elle est patiente et drôle.","translation":"My mother is a nurse. She is patient and funny.","translations":{"es":"Mi madre es enfermera. Es paciente y divertida."}},{"phrase":"Ma sœur est l''aînée. Elle est très intelligente.","translation":"My sister is the eldest. She is very intelligent.","translations":{"es":"Mi hermana es la mayor. Es muy inteligente."}},{"phrase":"Mon frère est le cadet et il joue au foot.","translation":"My brother is the youngest and he plays soccer.","translations":{"es":"Mi hermano es el menor y juega al fútbol."}},{"phrase":"Mon beau-frère est l''époux de ma sœur.","translation":"My brother-in-law is my sister''s husband.","translations":{"es":"Mi cuñado es el esposo de mi hermana."}},{"phrase":"Je suis le neveu de ma tante Claire.","translation":"I am my aunt Claire''s nephew.","translations":{"es":"Soy el sobrino de mi tía Claire."}},{"phrase":"Où habites-tu ? — J''habite en Bretagne.","translation":"Where do you live? — I live in Brittany.","translations":{"es":"¿Dónde vives? — Vivo en Bretaña."}},{"phrase":"Comment s''appelle ta mère ? — Elle s''appelle Anne.","translation":"What''s your mother''s name? — Her name is Anne.","translations":{"es":"¿Cómo se llama tu madre? — Se llama Anne."}},{"phrase":"Qu''est-ce que fait ton père ? — Il est architecte.","translation":"What does your father do? — He is an architect.","translations":{"es":"¿A qué se dedica tu padre? — Es arquitecto."}},{"phrase":"Voici mon frère Paul et ma belle-sœur Léa.","translation":"This is my brother Paul and my sister-in-law Léa.","translations":{"es":"Este es mi hermano Paul y mi cuñada Léa."}},{"phrase":"Ma marraine vient nous voir aujourd''hui.","translation":"My godmother is coming to see us today.","translations":{"es":"Mi madrina viene a vernos hoy."}},{"phrase":"Laissez-moi vous présenter ma famille.","translation":"Let me introduce my family to you.","translations":{"es":"Permítanme presentarles a mi familia."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Your mother''s brother is your…","options":["cousin","neveu","oncle","grand-père"],"correct":2,"explanation":"\"L''oncle\" = uncle; his wife is \"la tante\".","translations":{"es":{"question":"El hermano de tu madre es tu…","explanation":"«L''oncle» = el tío; su esposa es «la tante»."}}},{"id":"2","question":"Your sister''s daughter is your…","options":["tante","cousine","nièce","filleule"],"correct":2,"explanation":"Nephew = \"le neveu\", niece = \"la nièce\".","translations":{"es":{"question":"La hija de tu hermana es tu…","explanation":"Sobrino = «le neveu», sobrina = «la nièce»."}}},{"id":"3","question":"Your sister''s husband is your…","options":["beau-père","frère","beau-frère","gendre"],"correct":2,"explanation":"\"Beau-frère\" = brother-in-law.","translations":{"es":{"question":"El esposo de tu hermana es tu…","explanation":"«Beau-frère» = cuñado."}}},{"id":"4","question":"What does \"l''aînée\" mean?","options":["the godmother","the eldest","the youngest","the twin"],"correct":1,"explanation":"The youngest is \"la cadette\".","translations":{"es":{"question":"¿Qué significa «l''aînée»?","explanation":"La menor es «la cadette».","options":["la madrina","la mayor","la menor","la gemela"]}}},{"id":"5","question":"How do you ask what someone''s father does for a living?","options":["Qu''est-ce que fait ton père ?","Comment va ton père ?","Où est ton père ?","Comment s''appelle ton père ?"],"correct":0,"explanation":"The answer is a job: \"Il est avocat\", \"Il est architecte\"…","translations":{"es":{"question":"¿Cómo preguntas a qué se dedica el padre de alguien?","explanation":"La respuesta es una profesión: «Il est avocat», «Il est architecte»…"}}},{"id":"6","question":"How do you say \"He is 45 years old\"?","options":["Il a quarante-cinq ans.","Il fait quarante-cinq ans.","Il est quarante-cinq ans.","Il a quarante-cinq années."],"correct":0,"explanation":"Age always uses \"avoir\" + \"ans\".","translations":{"es":{"question":"¿Cómo se dice «Tiene 45 años»?","explanation":"La edad siempre usa «avoir» + «ans»."}}},{"id":"7","question":"\"Sa fille va se marier.\" What tense is this?","options":["past","near future","present habit","conditional"],"correct":1,"explanation":"Aller (present) + infinitive = near future.","translations":{"es":{"question":"«Sa fille va se marier.» ¿Qué tiempo es?","explanation":"Aller (presente) + infinitivo = futuro próximo.","options":["pasado","futuro próximo","presente habitual","condicional"]}}},{"id":"8","question":"Complete: \"___ sœur et ___ frère\" (my)","options":["ma … mon","mon … ma","mes … mon","ma … ma"],"correct":0,"explanation":"Sœur is feminine (ma), frère is masculine (mon).","translations":{"es":{"question":"Completa: «___ sœur et ___ frère» (mi)","explanation":"Sœur es femenino (ma), frère es masculino (mon)."}}}]}'::jsonb, 3),
  ('story', 'Ma famille à Marseille', '{"text":"Laissez-moi vous présenter ma famille. Mon père s''appelle Marc Rivière. Il a cinquante ans et il est cuisinier dans un restaurant du port. Ma mère s''appelle Sophie. Elle a quarante-sept ans, elle est médecin et elle s''occupe beaucoup de nous. Au fait, je m''appelle Camille Rivière, j''ai dix-neuf ans et je suis étudiante à Marseille, où nous habitons. Mon frère aîné, Julien, suit des études d''informatique à Lyon. Ma petite sœur, Zoé, est la cadette. Elle a douze ans et c''est une très bonne danseuse. Nous avons aussi un chat gris qui s''appelle Moustache. Mes grands-parents sont toujours en vie et ils habitent à la campagne, près d''Aix. Ma tante Hélène, du côté de mon père, habite à Nice, à deux heures d''ici. Elle a deux fils : ce sont mes cousins. Ma tante pense que je suis la plus bavarde de ses nièces ! Son fils aîné va se marier en juin. Voilà ma famille. Parlez-moi de la vôtre !","translation":"Let me introduce my family to you. My father is called Marc Rivière. He is fifty years old and he is a cook in a restaurant at the harbor. My mother is called Sophie. She is forty-seven, she is a doctor and she takes great care of us. By the way, my name is Camille Rivière, I am nineteen and I am a student in Marseille, where we live. My older brother, Julien, is studying computer science in Lyon. My little sister, Zoé, is the youngest. She is twelve and she is a very good dancer. We also have a grey cat called Moustache. My grandparents are still alive and they live in the countryside, near Aix. My aunt Hélène, on my father''s side, lives in Nice, two hours from here. She has two sons: they are my cousins. My aunt thinks I am the most talkative of her nieces! Her eldest son is going to get married in June. That''s my family. Tell me about yours!","translations":{"es":"Permítanme presentarles a mi familia. Mi padre se llama Marc Rivière. Tiene cincuenta años y es cocinero en un restaurante del puerto. Mi madre se llama Sophie. Tiene cuarenta y siete años, es médica y nos cuida mucho. Por cierto, me llamo Camille Rivière, tengo diecinueve años y soy estudiante en Marsella, donde vivimos. Mi hermano mayor, Julien, estudia Informática en Lyon. Mi hermana pequeña, Zoé, es la menor. Tiene doce años y es una bailarina muy buena. También tenemos un gato gris que se llama Moustache. Mis abuelos todavía viven y están en el campo, cerca de Aix. Mi tía Hélène, por parte de mi padre, vive en Niza, a dos horas de aquí. Tiene dos hijos: son mis primos. ¡Mi tía piensa que soy la más charlatana de sus sobrinas! Su hijo mayor se va a casar en junio. Esta es mi familia. ¡Háblenme de la suya!"},"highlighted_words":["ma famille","s''appelle","a cinquante ans","aîné","cadette","grands-parents","tante","cousins","nièces","va se marier","la vôtre"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Mon","père","a","quarante-cinq","ans"],"translation":"My father is forty-five years old","translations":{"es":"Mi padre tiene cuarenta y cinco años"}},{"words":["Ma","sœur","est","l''aînée"],"translation":"My sister is the eldest","translations":{"es":"Mi hermana es la mayor"}},{"words":["Mes","grands-parents","habitent","près","de","chez","nous"],"translation":"My grandparents live near us","translations":{"es":"Mis abuelos viven cerca de nosotros"}},{"words":["Mon","cousin","va","se","marier","en","juin"],"translation":"My cousin is going to get married in June","translations":{"es":"Mi primo se va a casar en junio"}},{"words":["Laissez-moi","vous","présenter","ma","famille"],"translation":"Let me introduce my family to you","translations":{"es":"Permítanme presentarles a mi familia"}},{"words":["Ma","tante","est","la","sœur","de","ma","mère"],"translation":"My aunt is my mother''s sister","translations":{"es":"Mi tía es la hermana de mi madre"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"My mother''s name is Anne","translations":{"es":"Mi madre se llama Anne"},"answer":"Ma mère s''appelle Anne"},{"prompt":"I have two brothers and a sister","translations":{"es":"Tengo dos hermanos y una hermana"},"answer":"J''ai deux frères et une sœur"},{"prompt":"My uncle lives in Bordeaux","translations":{"es":"Mi tío vive en Burdeos"},"answer":"Mon oncle habite à Bordeaux"},{"prompt":"She is forty years old","translations":{"es":"Tiene cuarenta años"},"answer":"Elle a quarante ans"},{"prompt":"This is my sister-in-law","translations":{"es":"Esta es mi cuñada"},"answer":"Voici ma belle-sœur"},{"prompt":"Tell me about your family","translations":{"es":"Háblenme de su familia"},"answer":"Parlez-moi de votre famille"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 7: Chez moi
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-07', 'Chez moi', '🏠', 'En mi casa', 7, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la maison","translation":"the house","translations":{"es":"la casa"}},{"id":"2","word":"le séjour","translation":"the living room","translations":{"es":"la sala de estar"}},{"id":"3","word":"le salon","translation":"the lounge","translations":{"es":"el salón"}},{"id":"4","word":"la salle à manger","translation":"the dining room","translations":{"es":"el comedor"}},{"id":"5","word":"la cuisine","translation":"the kitchen / cooking","translations":{"es":"la cocina"}},{"id":"6","word":"la salle de bains","translation":"the bathroom","translations":{"es":"el baño"}},{"id":"7","word":"les toilettes","translation":"the toilet","translations":{"es":"el inodoro / el aseo"}},{"id":"8","word":"la chambre","translation":"the bedroom","translations":{"es":"el dormitorio"}},{"id":"9","word":"la buanderie","translation":"the laundry room","translations":{"es":"el lavadero"}},{"id":"10","word":"le garage","translation":"the garage","translations":{"es":"el garaje"}},{"id":"11","word":"la cour","translation":"the yard","translations":{"es":"el patio"}},{"id":"12","word":"le canapé","translation":"the sofa","translations":{"es":"el sofá"}},{"id":"13","word":"le lit","translation":"the bed","translations":{"es":"la cama"}},{"id":"14","word":"la bibliothèque","translation":"the bookcase / the library","translations":{"es":"la estantería / la biblioteca"}},{"id":"15","word":"la moquette","translation":"the carpet","translations":{"es":"la moqueta"}},{"id":"16","word":"le réfrigérateur","translation":"the refrigerator","translations":{"es":"el refrigerador"}},{"id":"17","word":"la machine à laver","translation":"the washing machine","translations":{"es":"la lavadora"}},{"id":"18","word":"le repas","translation":"the meal","translations":{"es":"la comida"}},{"id":"19","word":"la vaisselle","translation":"the dishes","translations":{"es":"los platos"}},{"id":"20","word":"nettoyer","translation":"to clean","translations":{"es":"limpiar"}},{"id":"21","word":"faire le ménage","translation":"to do the housework","translations":{"es":"hacer las tareas de la casa"}},{"id":"22","word":"passer l''aspirateur","translation":"to vacuum","translations":{"es":"pasar la aspiradora"}},{"id":"23","word":"faire cuire","translation":"to cook (food)","translations":{"es":"cocinar (un alimento)"}},{"id":"24","word":"laver","translation":"to wash","translations":{"es":"lavar"}},{"id":"25","word":"sécher","translation":"to dry","translations":{"es":"secar"}},{"id":"26","word":"dormir","translation":"to sleep","translations":{"es":"dormir"}},{"id":"27","word":"lire","translation":"to read","translations":{"es":"leer"}},{"id":"28","word":"propre","translation":"clean / own","translations":{"es":"limpio / propio"}},{"id":"29","word":"sale","translation":"dirty","translations":{"es":"sucio"}},{"id":"30","word":"à l''aise","translation":"comfortable / at ease","translations":{"es":"a gusto / cómodo"}},{"id":"31","word":"accueillant / accueillante","translation":"welcoming","translations":{"es":"acogedor / acogedora"}}],"grammar":[{"structure":"être en train de + infinitif","example":"Il est en train de dormir sur le canapé.","en":"Action in progress","es":"Acción en curso"},{"structure":"devoir + infinitif","example":"Je dois passer l''aspirateur.","en":"Obligation with \"devoir\"","es":"Obligación con «devoir»"},{"structure":"impératif","example":"Fais la vaisselle !","en":"Imperative (tu)","es":"Imperativo (tu)"},{"structure":"jusqu''à ce que + subjonctif","example":"La cuisine était propre jusqu''à ce que tu commences à cuisiner.","en":"\"until\" + subjunctive","es":"«hasta que» + subjuntivo"},{"structure":"imparfait / futur simple","example":"La cuisine était propre. / Le vent séchera tes vêtements.","en":"Imperfect and simple future","es":"Imperfecto y futuro simple"},{"structure":"se sentir / se souvenir de","example":"Je me sens à l''aise. / Te souviens-tu de moi ?","en":"Reflexive verbs","es":"Verbos pronominales"},{"structure":"ni … ni","example":"Nous ne sommes ni riches ni pauvres.","en":"\"neither … nor\"","es":"«ni … ni»"},{"structure":"comparatif avec un verbe","example":"Elle aime la lecture plus que moi.","en":"Comparing actions (plus que)","es":"Comparar acciones (plus que)"}],"tips":[{"en":"\"Faire le ménage\" = to do the housework; \"faire la vaisselle\" = to do the dishes; \"faire la cuisine\" = to cook.","es":"«Faire le ménage» = hacer las tareas de la casa; «faire la vaisselle» = fregar los platos; «faire la cuisine» = cocinar."},{"en":"\"Chez moi / chez toi / chez nous\" means \"at my / your / our place\" — no need for \"maison\".","es":"«Chez moi / chez toi / chez nous» significa «en mi / tu / nuestra casa», sin necesidad de decir «maison»."},{"en":"\"Les toilettes\" and \"les WC\" are always plural in French.","es":"«Les toilettes» y «les WC» van siempre en plural en francés."},{"en":"\"Sens dessus dessous\" = upside down / in a total mess.","es":"«Sens dessus dessous» = patas arriba / todo desordenado."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Rentrons à la maison. Ici, je me sens à l''aise.","translation":"Let''s go home. Here, I feel at ease.","translations":{"es":"Volvamos a casa. Aquí me siento a gusto."}},{"phrase":"La moquette est sale.","translation":"The carpet is dirty.","translations":{"es":"La moqueta está sucia."}},{"phrase":"Cette maison est très accueillante.","translation":"This house is very welcoming.","translations":{"es":"Esta casa es muy acogedora."}},{"phrase":"Ils sont en train de nettoyer le sol.","translation":"They are cleaning the floor.","translations":{"es":"Están limpiando el suelo."}},{"phrase":"Le chat est en train de dormir sur le canapé.","translation":"The cat is sleeping on the sofa.","translations":{"es":"El gato está durmiendo en el sofá."}},{"phrase":"La voiture est dans le garage.","translation":"The car is in the garage.","translations":{"es":"El coche está en el garaje."}},{"phrase":"Mon fils passe toujours l''aspirateur le samedi.","translation":"My son always vacuums on Saturdays.","translations":{"es":"Mi hijo siempre pasa la aspiradora los sábados."}},{"phrase":"La cuisine était propre jusqu''à ce que tu commences à cuisiner !","translation":"The kitchen was clean until you started cooking!","translations":{"es":"¡La cocina estaba limpia hasta que empezaste a cocinar!"}},{"phrase":"Tes vêtements sont sur le lit.","translation":"Your clothes are on the bed.","translations":{"es":"Tu ropa está en la cama."}},{"phrase":"Fais la vaisselle, s''il te plaît.","translation":"Do the dishes, please.","translations":{"es":"Friega los platos, por favor."}},{"phrase":"Étends tes vêtements dans la cour : le soleil les séchera.","translation":"Hang your clothes in the yard: the sun will dry them.","translations":{"es":"Tiende tu ropa en el patio: el sol la secará."}},{"phrase":"Te souviens-tu de moi ? — Oui, je me souviens.","translation":"Do you remember me? — Yes, I remember.","translations":{"es":"¿Te acuerdas de mí? — Sí, me acuerdo."}},{"phrase":"Qu''as-tu dans ton salon ? — Un canapé, deux fauteuils et une table basse.","translation":"What do you have in your living room? — A sofa, two armchairs and a coffee table.","translations":{"es":"¿Qué tienes en tu salón? — Un sofá, dos sillones y una mesa baja."}},{"phrase":"Préfères-tu cuisiner ou faire la vaisselle ? — Peu importe, j''aime les deux.","translation":"Do you prefer cooking or doing the dishes? — It doesn''t matter, I like both.","translations":{"es":"¿Prefieres cocinar o fregar los platos? — Me da igual, me gustan las dos cosas."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Where do you usually find the washing machine?","options":["dans le garage","dans le salon","dans la buanderie","dans la chambre"],"correct":2,"explanation":"\"La buanderie\" is the laundry room.","translations":{"es":{"question":"¿Dónde suele estar la lavadora?","explanation":"«La buanderie» es el lavadero."}}},{"id":"2","question":"How do you say \"to do the dishes\"?","options":["faire la vaisselle","faire la cuisine","faire le lit","faire le ménage"],"correct":0,"explanation":"Faire le ménage = housework, faire la cuisine = to cook, faire le lit = to make the bed.","translations":{"es":{"question":"¿Cómo se dice «fregar los platos»?","explanation":"Faire le ménage = tareas de la casa, faire la cuisine = cocinar, faire le lit = hacer la cama."}}},{"id":"3","question":"\"Il est en train de dormir.\" What does it mean?","options":["He slept on the train.","He is sleeping (right now).","He will sleep.","He has to sleep."],"correct":1,"explanation":"\"Être en train de\" has nothing to do with trains: it means \"in the middle of\".","translations":{"es":{"question":"«Il est en train de dormir.» ¿Qué significa?","explanation":"«Être en train de» no tiene nada que ver con trenes: significa «estar haciendo algo».","options":["Durmió en el tren.","Está durmiendo (ahora).","Dormirá.","Tiene que dormir."]}}},{"id":"4","question":"Complete: \"La cuisine était propre jusqu''à ce que tu ___ à cuisiner.\"","options":["commenceras","commences","as commencé","commençais"],"correct":1,"explanation":"\"Jusqu''à ce que\" is always followed by the subjunctive.","translations":{"es":{"question":"Completa: «La cuisine était propre jusqu''à ce que tu ___ à cuisiner.»","explanation":"«Jusqu''à ce que» siempre va seguido de subjuntivo."}}},{"id":"5","question":"\"Êtes-vous riches ?\" — \"Nous ne sommes ___ riches ___ pauvres.\"","options":["ni … ni","et … et","ou … ou","pas … pas"],"correct":0,"explanation":"\"Ne … ni … ni\" = neither … nor.","translations":{"es":{"question":"«Êtes-vous riches ?» — «Nous ne sommes ___ riches ___ pauvres.»","explanation":"«Ne … ni … ni» = ni … ni."}}},{"id":"6","question":"How do you say \"I have to vacuum\"?","options":["Je dois passer l''aspirateur.","Je vais passer à l''aspirateur.","J''ai passé l''aspirateur.","Je passe l''aspirateur."],"correct":0,"explanation":"\"Devoir\" + infinitive expresses obligation.","translations":{"es":{"question":"¿Cómo se dice «Tengo que pasar la aspiradora»?","explanation":"«Devoir» + infinitivo expresa obligación."}}},{"id":"7","question":"Answer to \"Te souviens-tu de moi ?\" if you don''t remember:","options":["Non, je souviens pas me.","Non, je ne me souviens pas.","Non, je me ne souviens pas.","Non, je ne souviens pas."],"correct":1,"explanation":"With reflexive verbs, \"ne\" goes before the pronoun: je ne me souviens pas.","translations":{"es":{"question":"Respuesta a «Te souviens-tu de moi ?» si no te acuerdas:","explanation":"Con verbos pronominales, «ne» va antes del pronombre: je ne me souviens pas."}}},{"id":"8","question":"What does \"Je me sens à l''aise\" mean?","options":["I feel comfortable.","I feel lazy.","I feel sick.","I feel lonely."],"correct":0,"explanation":"The opposite is \"Je me sens mal à l''aise\" (uncomfortable).","translations":{"es":{"question":"¿Qué significa «Je me sens à l''aise»?","explanation":"Lo contrario es «Je me sens mal à l''aise» (incómodo).","options":["Me siento a gusto.","Me siento perezoso.","Me siento mal.","Me siento solo."]}}}]}'::jsonb, 3),
  ('story', 'La colocation de Yasmine', '{"text":"Salut, tu te souviens de moi ? Je suis Yasmine. J''adore être chez moi, dans mon petit appartement de Montpellier. J''habite avec mon amie Clara et notre chien, Biscotte. Le soir, nous aimons regarder des films sur le canapé et préparer des repas ensemble. Clara cuisine mieux que moi, mais j''aime plus la pâtisserie qu''elle ! Nous ne sommes ni riches ni pauvres, mais nous sommes heureuses. Chaque semaine, nous avons des tâches : je dois passer l''aspirateur et sortir le chien ; Clara doit faire la vaisselle et nettoyer la salle de bains. Hier, l''appartement était propre jusqu''à ce que Biscotte rentre de la cour avec les pattes sales. Maintenant, il est en train de dormir sur mon lit ! Demain, nous laverons tout. Chez nous, je me sens toujours à l''aise.","translation":"Hi, do you remember me? I''m Yasmine. I love being at home, in my little apartment in Montpellier. I live with my friend Clara and our dog, Biscotte. In the evening, we like watching movies on the sofa and making meals together. Clara cooks better than me, but I like baking more than she does! We are neither rich nor poor, but we are happy. Every week, we have chores: I have to vacuum and walk the dog; Clara has to do the dishes and clean the bathroom. Yesterday, the apartment was clean until Biscotte came back from the yard with dirty paws. Now he is sleeping on my bed! Tomorrow, we will wash everything. At home, I always feel at ease.","translations":{"es":"Hola, ¿te acuerdas de mí? Soy Yasmine. Me encanta estar en casa, en mi pequeño apartamento de Montpellier. Vivo con mi amiga Clara y nuestro perro, Biscotte. Por la noche nos gusta ver películas en el sofá y preparar comidas juntas. Clara cocina mejor que yo, ¡pero a mí me gusta más la repostería que a ella! No somos ni ricas ni pobres, pero somos felices. Cada semana tenemos tareas: yo tengo que pasar la aspiradora y sacar al perro; Clara tiene que fregar los platos y limpiar el baño. Ayer el apartamento estaba limpio hasta que Biscotte volvió del patio con las patas sucias. ¡Ahora está durmiendo en mi cama! Mañana lo lavaremos todo. En casa siempre me siento a gusto."},"highlighted_words":["tu te souviens","chez moi","canapé","ni riches ni pauvres","passer l''aspirateur","faire la vaisselle","jusqu''à ce que","en train de dormir","laverons","à l''aise"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","me","sens","à","l''aise","chez","moi"],"translation":"I feel at ease at home","translations":{"es":"Me siento a gusto en casa"}},{"words":["Le","chien","est","dans","la","cour"],"translation":"The dog is in the yard","translations":{"es":"El perro está en el patio"}},{"words":["Ils","sont","en","train","de","nettoyer","la","cuisine"],"translation":"They are cleaning the kitchen","translations":{"es":"Están limpiando la cocina"}},{"words":["Tu","dois","faire","ton","lit"],"translation":"You have to make your bed","translations":{"es":"Tienes que hacer tu cama"}},{"words":["Nous","ne","sommes","ni","riches","ni","pauvres"],"translation":"We are neither rich nor poor","translations":{"es":"No somos ni ricos ni pobres"}},{"words":["Le","soleil","séchera","tes","vêtements"],"translation":"The sun will dry your clothes","translations":{"es":"El sol secará tu ropa"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Do the dishes","translations":{"es":"Friega los platos"},"answer":"Fais la vaisselle"},{"prompt":"The car is in the garage","translations":{"es":"El coche está en el garaje"},"answer":"La voiture est dans le garage"},{"prompt":"I am in the living room","translations":{"es":"Estoy en el salón"},"answer":"Je suis dans le salon"},{"prompt":"Do you remember me?","translations":{"es":"¿Te acuerdas de mí?"},"answer":"Te souviens-tu de moi ?"},{"prompt":"The carpet is dirty","translations":{"es":"La moqueta está sucia"},"answer":"La moquette est sale"},{"prompt":"I have to vacuum","translations":{"es":"Tengo que pasar la aspiradora"},"answer":"Je dois passer l''aspirateur"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 8: Les pays et les nationalités
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-08', 'Les pays et les nationalités', '🌍', 'Los países y las nacionalidades', 8, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''Argentine","translation":"Argentina","translations":{"es":"Argentina"}},{"id":"2","word":"l''Allemagne","translation":"Germany","translations":{"es":"Alemania"}},{"id":"3","word":"l''Angleterre","translation":"England","translations":{"es":"Inglaterra"}},{"id":"4","word":"l''Autriche","translation":"Austria","translations":{"es":"Austria"}},{"id":"5","word":"la Belgique","translation":"Belgium","translations":{"es":"Bélgica"}},{"id":"6","word":"le Brésil","translation":"Brazil","translations":{"es":"Brasil"}},{"id":"7","word":"le Canada","translation":"Canada","translations":{"es":"Canadá"}},{"id":"8","word":"le Chili","translation":"Chile","translations":{"es":"Chile"}},{"id":"9","word":"la Chine","translation":"China","translations":{"es":"China"}},{"id":"10","word":"la Colombie","translation":"Colombia","translations":{"es":"Colombia"}},{"id":"11","word":"l''Écosse","translation":"Scotland","translations":{"es":"Escocia"}},{"id":"12","word":"l''Équateur","translation":"Ecuador","translations":{"es":"Ecuador"}},{"id":"13","word":"l''Espagne","translation":"Spain","translations":{"es":"España"}},{"id":"14","word":"les États-Unis","translation":"the United States","translations":{"es":"Estados Unidos"}},{"id":"15","word":"la Grèce","translation":"Greece","translations":{"es":"Grecia"}},{"id":"16","word":"l''Inde","translation":"India","translations":{"es":"India"}},{"id":"17","word":"l''Irlande","translation":"Ireland","translations":{"es":"Irlanda"}},{"id":"18","word":"l''Italie","translation":"Italy","translations":{"es":"Italia"}},{"id":"19","word":"le Japon","translation":"Japan","translations":{"es":"Japón"}},{"id":"20","word":"le Mexique","translation":"Mexico","translations":{"es":"México"}},{"id":"21","word":"les Pays-Bas","translation":"the Netherlands","translations":{"es":"los Países Bajos"}},{"id":"22","word":"le Pérou","translation":"Peru","translations":{"es":"Perú"}},{"id":"23","word":"le Portugal","translation":"Portugal","translations":{"es":"Portugal"}},{"id":"24","word":"la Russie","translation":"Russia","translations":{"es":"Rusia"}},{"id":"25","word":"la Suède","translation":"Sweden","translations":{"es":"Suecia"}},{"id":"26","word":"la Suisse","translation":"Switzerland","translations":{"es":"Suiza"}},{"id":"27","word":"la Turquie","translation":"Turkey","translations":{"es":"Turquía"}},{"id":"28","word":"l''Europe","translation":"Europe","translations":{"es":"Europa"}},{"id":"29","word":"l''Asie","translation":"Asia","translations":{"es":"Asia"}},{"id":"30","word":"l''Afrique","translation":"Africa","translations":{"es":"África"}},{"id":"31","word":"l''Amérique du Sud","translation":"South America","translations":{"es":"América del Sur"}},{"id":"32","word":"Londres","translation":"London","translations":{"es":"Londres"}},{"id":"33","word":"Venise","translation":"Venice","translations":{"es":"Venecia"}},{"id":"34","word":"américain / américaine","translation":"American","translations":{"es":"estadounidense"}},{"id":"35","word":"anglais / anglaise","translation":"English","translations":{"es":"inglés / inglesa"}},{"id":"36","word":"allemand / allemande","translation":"German","translations":{"es":"alemán / alemana"}},{"id":"37","word":"brésilien / brésilienne","translation":"Brazilian","translations":{"es":"brasileño / brasileña"}},{"id":"38","word":"chinois / chinoise","translation":"Chinese","translations":{"es":"chino / china"}},{"id":"39","word":"colombien / colombienne","translation":"Colombian","translations":{"es":"colombiano / colombiana"}},{"id":"40","word":"espagnol / espagnole","translation":"Spanish","translations":{"es":"español / española"}},{"id":"41","word":"français / française","translation":"French","translations":{"es":"francés / francesa"}},{"id":"42","word":"grec / grecque","translation":"Greek","translations":{"es":"griego / griega"}},{"id":"43","word":"italien / italienne","translation":"Italian","translations":{"es":"italiano / italiana"}},{"id":"44","word":"japonais / japonaise","translation":"Japanese","translations":{"es":"japonés / japonesa"}},{"id":"45","word":"mexicain / mexicaine","translation":"Mexican","translations":{"es":"mexicano / mexicana"}},{"id":"46","word":"russe","translation":"Russian","translations":{"es":"ruso / rusa"}},{"id":"47","word":"suisse","translation":"Swiss","translations":{"es":"suizo / suiza"}},{"id":"48","word":"turc / turque","translation":"Turkish","translations":{"es":"turco / turca"}}],"grammar":[{"structure":"genre des pays","example":"la France, le Japon, les États-Unis","en":"Gender of countries","es":"Género de los países"},{"structure":"prépositions de lieu","example":"en France, au Japon, aux États-Unis, à Paris","en":"Prepositions: in / to countries and cities","es":"Preposiciones: en / a países y ciudades"},{"structure":"venir de / d'' / du / des","example":"Je viens d''Italie. / Il vient du Pérou.","en":"Saying where you come from","es":"Decir de dónde vienes"},{"structure":"accord des nationalités","example":"Il est mexicain. / Elle est mexicaine.","en":"Nationality agreement","es":"Concordancia de las nacionalidades"},{"structure":"superlatif","example":"Le Brésil est le plus grand pays d''Amérique du Sud.","en":"Superlatives with \"de\"","es":"Superlativo con «de»"},{"structure":"impératif (nous)","example":"Allons en Chine ! Parcourons le pays !","en":"Imperative \"let''s\"","es":"Imperativo de 1.ª persona plural"},{"structure":"passé composé / imparfait","example":"As-tu visité l''Irlande ? / Carlos Gardel était argentin.","en":"Past tenses","es":"Tiempos del pasado"},{"structure":"si + présent, présent","example":"Si nous regardons autour du monde, nous pouvons trouver…","en":"Real condition (si + present)","es":"Condición real (si + presente)"},{"structure":"pour que + subjonctif","example":"Les trains relient les pays pour que le voyage soit plus facile.","en":"\"so that\" + subjunctive","es":"«para que» + subjuntivo"}],"tips":[{"en":"Countries ending in -e are usually feminine (la France, l''Espagne) — exceptions: le Mexique, le Cambodge.","es":"Los países terminados en -e suelen ser femeninos (la France, l''Espagne). Excepciones: le Mexique, le Cambodge."},{"en":"In / to: \"en\" + feminine or vowel (en France, en Iran), \"au\" + masculine (au Japon), \"aux\" + plural (aux États-Unis), \"à\" + city (à Rome).","es":"En / a: «en» + femenino o vocal (en France, en Iran), «au» + masculino (au Japon), «aux» + plural (aux États-Unis), «à» + ciudad (à Rome)."},{"en":"Nationality adjectives are lowercase (il est français), but the people are capitalized (les Français).","es":"Los adjetivos de nacionalidad van en minúscula (il est français), pero los habitantes en mayúscula (les Français)."},{"en":"Languages are masculine and lowercase: \"le portugais\", \"l''arabe\". After \"parler\", the article is optional: \"Il parle (le) grec\".","es":"Los idiomas son masculinos y van en minúscula: «le portugais», «l''arabe». Después de «parler», el artículo es opcional: «Il parle (le) grec»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Je suis colombienne, et toi ? — Je suis irlandais.","translation":"I''m Colombian, and you? — I''m Irish.","translations":{"es":"Soy colombiana, ¿y tú? — Soy irlandés."}},{"phrase":"D''où viens-tu ? — Je viens d''Italie.","translation":"Where are you from? — I come from Italy.","translations":{"es":"¿De dónde vienes? — Vengo de Italia."}},{"phrase":"Où habites-tu ? — J''habite au Japon.","translation":"Where do you live? — I live in Japan.","translations":{"es":"¿Dónde vives? — Vivo en Japón."}},{"phrase":"Tu es d''Espagne ? — Non, je suis du Pérou.","translation":"Are you from Spain? — No, I am from Peru.","translations":{"es":"¿Eres de España? — No, soy de Perú."}},{"phrase":"L''Espagne est en Europe.","translation":"Spain is in Europe.","translations":{"es":"España está en Europa."}},{"phrase":"Le Brésil est le plus grand pays d''Amérique du Sud.","translation":"Brazil is the largest country in South America.","translations":{"es":"Brasil es el país más grande de América del Sur."}},{"phrase":"L''Autriche est à côté de la Suisse.","translation":"Austria is next to Switzerland.","translations":{"es":"Austria está al lado de Suiza."}},{"phrase":"Mes amis sont de Hong Kong.","translation":"My friends are from Hong Kong.","translations":{"es":"Mis amigos son de Hong Kong."}},{"phrase":"Je vais voyager à travers l''Europe.","translation":"I am going to travel across Europe.","translations":{"es":"Voy a viajar por Europa."}},{"phrase":"As-tu visité l''Irlande ? — Oui, l''année dernière.","translation":"Have you visited Ireland? — Yes, last year.","translations":{"es":"¿Has visitado Irlanda? — Sí, el año pasado."}},{"phrase":"Il est londonien, n''est-ce pas ? — Oui, je crois.","translation":"He''s from London, isn''t he? — Yes, I think so.","translations":{"es":"Es londinense, ¿verdad? — Sí, creo que sí."}},{"phrase":"Ma grand-mère était grecque.","translation":"My grandmother was Greek.","translations":{"es":"Mi abuela era griega."}},{"phrase":"Allons au Portugal cet été !","translation":"Let''s go to Portugal this summer!","translations":{"es":"¡Vamos a Portugal este verano!"}},{"phrase":"Il est né en Turquie, mais il habite aux États-Unis.","translation":"He was born in Turkey, but he lives in the United States.","translations":{"es":"Nació en Turquía, pero vive en Estados Unidos."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"J''habite ___ Japon.\"","options":["à","au","en","aux"],"correct":1,"explanation":"\"Japon\" is masculine: \"au Japon\".","translations":{"es":{"question":"Completa: «J''habite ___ Japon.»","explanation":"«Japon» es masculino: «au Japon»."}}},{"id":"2","question":"Complete: \"Elle travaille ___ États-Unis.\"","options":["aux","à","au","en"],"correct":0,"explanation":"Plural countries take \"aux\".","translations":{"es":{"question":"Completa: «Elle travaille ___ États-Unis.»","explanation":"Los países en plural llevan «aux»."}}},{"id":"3","question":"Complete: \"Je viens ___ Italie.\"","options":["des","d''","du","de la"],"correct":1,"explanation":"Feminine countries: \"de\" → \"d''\" before a vowel.","translations":{"es":{"question":"Completa: «Je viens ___ Italie.»","explanation":"Países femeninos: «de» → «d''» delante de vocal."}}},{"id":"4","question":"Which is correct for a woman from Mexico?","options":["Elle est mexicain.","Elle est mexicaine.","Elle est mexicane.","Elle est Mexicaine."],"correct":1,"explanation":"Nationalities agree and are lowercase as adjectives.","translations":{"es":{"question":"¿Qué es correcto para una mujer de México?","explanation":"Las nacionalidades concuerdan y van en minúscula como adjetivos."}}},{"id":"5","question":"What is the feminine of \"grec\"?","options":["grecque","grecte","greque","grèce"],"correct":0,"explanation":"Irregular: grec → grecque, turc → turque.","translations":{"es":{"question":"¿Cuál es el femenino de «grec»?","explanation":"Irregular: grec → grecque, turc → turque."}}},{"id":"6","question":"How do you say \"Let''s go to China!\"?","options":["Allons en Chine !","Nous allons à Chine !","Va au Chine !","Allez en Chine !"],"correct":0,"explanation":"Imperative \"nous\": allons, parcourons, visitons.","translations":{"es":{"question":"¿Cómo se dice «¡Vamos a China!»?","explanation":"Imperativo con «nous»: allons, parcourons, visitons."}}},{"id":"7","question":"Which country is feminine?","options":["le Brésil","le Portugal","la Suède","le Mexique"],"correct":2,"explanation":"Most countries ending in -e are feminine, but \"le Mexique\" is an exception.","translations":{"es":{"question":"¿Qué país es femenino?","explanation":"La mayoría de los países terminados en -e son femeninos, pero «le Mexique» es una excepción."}}},{"id":"8","question":"Complete: \"Les trains relient les pays pour que le voyage ___ plus facile.\"","options":["était","est","soit","sera"],"correct":2,"explanation":"\"Pour que\" is always followed by the subjunctive.","translations":{"es":{"question":"Completa: «Les trains relient les pays pour que le voyage ___ plus facile.»","explanation":"«Pour que» siempre va seguido de subjuntivo."}}}]}'::jsonb, 3),
  ('story', 'Le tour du monde de Maya', '{"text":"Maya est canadienne. Elle est née à Montréal, mais sa mère est indienne et son père est chilien. L''année dernière, elle a fait le tour du monde. D''abord, elle est allée au Japon : la technologie l''a beaucoup étonnée. Ensuite, elle a visité l''Inde, le pays de sa mère, où elle a goûté une cuisine délicieuse. En Europe, elle a pris le train pour traverser la France, la Suisse, l''Italie et l''Autriche. Les trains européens relient beaucoup de pays pour que le voyage soit plus facile. Quand elle était petite, Maya rêvait de voir la forêt amazonienne ; alors, elle a fini son voyage au Brésil et au Pérou. Si nous regardons autour de nous, nous pouvons trouver des merveilles partout. Maya dit toujours : « Allons découvrir le monde ! »","translation":"Maya is Canadian. She was born in Montreal, but her mother is Indian and her father is Chilean. Last year, she traveled around the world. First, she went to Japan: the technology amazed her. Then, she visited India, her mother''s country, where she tasted delicious food. In Europe, she took the train to cross France, Switzerland, Italy and Austria. European trains connect many countries so that traveling is easier. When she was little, Maya dreamed of seeing the Amazon rainforest; so she ended her trip in Brazil and Peru. If we look around us, we can find wonders everywhere. Maya always says: “Let''s go and discover the world!”","translations":{"es":"Maya es canadiense. Nació en Montreal, pero su madre es india y su padre es chileno. El año pasado dio la vuelta al mundo. Primero fue a Japón: la tecnología la asombró mucho. Después visitó la India, el país de su madre, donde probó una comida deliciosa. En Europa tomó el tren para atravesar Francia, Suiza, Italia y Austria. Los trenes europeos conectan muchos países para que viajar sea más fácil. Cuando era pequeña, Maya soñaba con ver la selva amazónica; así que terminó su viaje en Brasil y en Perú. Si miramos a nuestro alrededor, podemos encontrar maravillas en todas partes. Maya siempre dice: «¡Vamos a descubrir el mundo!»"},"highlighted_words":["canadienne","indienne","chilien","au Japon","l''Inde","En Europe","pour que","soit","au Brésil","Si nous regardons","Allons"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","viens","d''Italie"],"translation":"I come from Italy","translations":{"es":"Vengo de Italia"}},{"words":["Elle","habite","au","Mexique"],"translation":"She lives in Mexico","translations":{"es":"Vive en México"}},{"words":["L''Espagne","est","en","Europe"],"translation":"Spain is in Europe","translations":{"es":"España está en Europa"}},{"words":["Mon","père","est","chilien"],"translation":"My father is Chilean","translations":{"es":"Mi padre es chileno"}},{"words":["Allons","en","Chine","cet","été"],"translation":"Let''s go to China this summer","translations":{"es":"Vamos a China este verano"}},{"words":["As-tu","visité","l''Irlande"],"translation":"Have you visited Ireland","translations":{"es":"¿Has visitado Irlanda?"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I am from Peru","translations":{"es":"Soy de Perú"},"answer":"Je suis du Pérou"},{"prompt":"She is Brazilian","translations":{"es":"Es brasileña"},"answer":"Elle est brésilienne"},{"prompt":"He lives in the United States","translations":{"es":"Vive en Estados Unidos"},"answer":"Il habite aux États-Unis"},{"prompt":"My sister lives in Bogotá","translations":{"es":"Mi hermana vive en Bogotá"},"answer":"Ma sœur habite à Bogota"},{"prompt":"I am going to travel in Europe","translations":{"es":"Voy a viajar por Europa"},"answer":"Je vais voyager en Europe"},{"prompt":"I am not French","translations":{"es":"No soy francés"},"answer":"Je ne suis pas français"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 9: Expressions courantes (1)
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-09', 'Expressions courantes (1)', '💬', 'Expresiones habituales (1)', 9, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"qui","translation":"who","translations":{"es":"quién"}},{"id":"2","word":"quoi","translation":"what","translations":{"es":"qué"}},{"id":"3","word":"où","translation":"where","translations":{"es":"dónde"}},{"id":"4","word":"quand","translation":"when","translations":{"es":"cuándo"}},{"id":"5","word":"comment","translation":"how","translations":{"es":"cómo"}},{"id":"6","word":"pourquoi","translation":"why","translations":{"es":"por qué"}},{"id":"7","word":"l''entrée","translation":"the entrance","translations":{"es":"la entrada"}},{"id":"8","word":"la sortie","translation":"the exit","translations":{"es":"la salida"}},{"id":"9","word":"attention","translation":"watch out / careful","translations":{"es":"cuidado"}},{"id":"10","word":"interdit / interdite","translation":"forbidden","translations":{"es":"prohibido / prohibida"}},{"id":"11","word":"l''arrêt","translation":"the stop","translations":{"es":"la parada"}},{"id":"12","word":"permettre","translation":"to allow","translations":{"es":"permitir"}},{"id":"13","word":"pouvoir","translation":"to be able to / can","translations":{"es":"poder"}},{"id":"14","word":"savoir","translation":"to know (a fact)","translations":{"es":"saber"}},{"id":"15","word":"connaître","translation":"to know (a person, a place)","translations":{"es":"conocer"}},{"id":"16","word":"fermer","translation":"to close","translations":{"es":"cerrar"}},{"id":"17","word":"ouvrir","translation":"to open","translations":{"es":"abrir"}},{"id":"18","word":"entrer","translation":"to enter","translations":{"es":"entrar"}},{"id":"19","word":"traverser","translation":"to cross","translations":{"es":"cruzar"}},{"id":"20","word":"pousser","translation":"to push","translations":{"es":"empujar"}},{"id":"21","word":"tirer","translation":"to pull","translations":{"es":"tirar"}},{"id":"22","word":"écouter","translation":"to listen","translations":{"es":"escuchar"}},{"id":"23","word":"prononcer","translation":"to pronounce","translations":{"es":"pronunciar"}},{"id":"24","word":"signifier","translation":"to mean","translations":{"es":"significar"}},{"id":"25","word":"écrire","translation":"to write","translations":{"es":"escribir"}},{"id":"26","word":"la langue","translation":"the language / the tongue","translations":{"es":"el idioma / la lengua"}},{"id":"27","word":"libre","translation":"free / vacant","translations":{"es":"libre"}},{"id":"28","word":"sûr / sûre","translation":"sure","translations":{"es":"seguro / segura"}},{"id":"29","word":"vrai / vraie","translation":"true","translations":{"es":"verdadero"}},{"id":"30","word":"faux / fausse","translation":"false / wrong","translations":{"es":"falso / falsa"}},{"id":"31","word":"évidemment","translation":"obviously","translations":{"es":"evidentemente"}},{"id":"32","word":"peut-être","translation":"maybe","translations":{"es":"quizás"}},{"id":"33","word":"probablement","translation":"probably","translations":{"es":"probablemente"}},{"id":"34","word":"complètement","translation":"completely","translations":{"es":"completamente"}},{"id":"35","word":"lentement","translation":"slowly","translations":{"es":"despacio"}},{"id":"36","word":"bienvenue","translation":"welcome","translations":{"es":"bienvenido"}}],"grammar":[{"structure":"mots interrogatifs","example":"Qui ? Quoi ? Où ? Quand ? Comment ? Pourquoi ?","en":"Question words","es":"Palabras interrogativas"},{"structure":"impératif (consignes)","example":"Fermez la porte. Arrêtez-vous tout de suite !","en":"Imperative for instructions","es":"Imperativo para instrucciones"},{"structure":"ne pas + infinitif (panneaux)","example":"Ne pas fumer. Ne pas entrer.","en":"Negative infinitive on signs","es":"Infinitivo negativo en carteles"},{"structure":"conditionnel de politesse","example":"Pourriez-vous me dire où se trouve la gare ?","en":"Polite conditional","es":"Condicional de cortesía"},{"structure":"il vaut mieux que + subjonctif","example":"Il vaut mieux que vous demandiez à quelqu''un d''autre.","en":"\"It''s better that\" + subjunctive","es":"«Es mejor que» + subjuntivo"},{"structure":"futur simple","example":"Nous nous reverrons probablement.","en":"Simple future","es":"Futuro simple"},{"structure":"pronom « le » (COD)","example":"Tu parles français ? — Oui, je le parle un peu.","en":"Direct object pronoun","es":"Pronombre de complemento directo"},{"structure":"avoir raison / avoir tort","example":"Peut-être avez-vous raison et c''est moi qui ai tort.","en":"\"To be right / wrong\" with avoir","es":"«Tener razón / estar equivocado» con avoir"}],"tips":[{"en":"Signs often use the infinitive: \"Ne pas fumer\", \"Ne pas toucher\", \"Tirer / Pousser\" (pull / push).","es":"Los carteles suelen usar el infinitivo: «Ne pas fumer», «Ne pas toucher», «Tirer / Pousser» (tirar / empujar)."},{"en":"\"Qu''est-ce que ça veut dire ?\" = What does it mean? \"Qu''est-ce que tu veux dire ?\" = What do you mean?","es":"«Qu''est-ce que ça veut dire ?» = ¿Qué significa eso? «Qu''est-ce que tu veux dire ?» = ¿Qué quieres decir?"},{"en":"After \"peut-être\" at the start of a sentence, formal French inverts: \"Peut-être avez-vous raison.\" Everyday: \"Peut-être que vous avez raison.\"","es":"Tras «peut-être» al inicio de la frase, el francés formal invierte: «Peut-être avez-vous raison.» En el día a día: «Peut-être que vous avez raison.»"},{"en":"\"Ce ne sont pas vos oignons !\" = It''s none of your business! (very familiar, a bit rude).","es":"«Ce ne sont pas vos oignons !» = ¡No es asunto suyo! (muy coloquial, algo grosero)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Où est l''entrée ? Et la sortie ?","translation":"Where is the entrance? And the exit?","translations":{"es":"¿Dónde está la entrada? ¿Y la salida?"}},{"phrase":"Stationnement interdit. — Où puis-je me garer, alors ?","translation":"No parking. — Where can I park, then?","translations":{"es":"Prohibido aparcar. — ¿Dónde puedo aparcar, entonces?"}},{"phrase":"Fermez la porte et ouvrez la fenêtre, s''il vous plaît.","translation":"Close the door and open the window, please.","translations":{"es":"Cierre la puerta y abra la ventana, por favor."}},{"phrase":"Parlez-vous italien ? — Oui, je le parle un peu.","translation":"Do you speak Italian? — Yes, I speak it a little.","translations":{"es":"¿Habla usted italiano? — Sí, lo hablo un poco."}},{"phrase":"Tu me comprends maintenant ? — Oui, je te comprends.","translation":"Do you understand me now? — Yes, I understand you.","translations":{"es":"¿Me entiendes ahora? — Sí, te entiendo."}},{"phrase":"Parle plus lentement, s''il te plaît.","translation":"Speak more slowly, please.","translations":{"es":"Habla más despacio, por favor."}},{"phrase":"Où est l''arrêt de bus le plus proche ? — Au coin de la rue.","translation":"Where is the nearest bus stop? — At the corner of the street.","translations":{"es":"¿Dónde está la parada de autobús más cercana? — En la esquina."}},{"phrase":"Pourriez-vous me dire où se trouve la gare ?","translation":"Could you tell me where the station is?","translations":{"es":"¿Podría decirme dónde está la estación?"}},{"phrase":"Peut-être avez-vous raison et c''est moi qui ai tort.","translation":"Maybe you are right and I''m the one who is wrong.","translations":{"es":"Quizás usted tenga razón y sea yo quien se equivoca."}},{"phrase":"Nous nous reverrons probablement. Au revoir !","translation":"We will probably see each other again. Goodbye!","translations":{"es":"Probablemente nos volveremos a ver. ¡Adiós!"}},{"phrase":"Comment dit-on « merci » en allemand ? Comment ça se prononce ?","translation":"How do you say \"thank you\" in German? How do you pronounce it?","translations":{"es":"¿Cómo se dice «gracias» en alemán? ¿Cómo se pronuncia?"}},{"phrase":"Qu''est-ce que ça veut dire ? — Ça veut dire « sortie ».","translation":"What does it mean? — It means \"exit\".","translations":{"es":"¿Qué significa eso? — Significa «salida»."}},{"phrase":"Attention, peinture fraîche ! Ne pas toucher.","translation":"Careful, wet paint! Do not touch.","translations":{"es":"¡Cuidado, recién pintado! No tocar."}},{"phrase":"Arrêtez-vous tout de suite !","translation":"Stop right now!","translations":{"es":"¡Deténgase ahora mismo!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Which word asks \"why\"?","options":["quoi","comment","pour quoi","pourquoi"],"correct":3,"explanation":"\"Pourquoi\" = why; the answer often starts with \"parce que\".","translations":{"es":{"question":"¿Qué palabra pregunta «por qué»?","explanation":"«Pourquoi» = por qué; la respuesta suele empezar con «parce que»."}}},{"id":"2","question":"A sign says \"Ne pas fumer\". What does it mean?","options":["Do not enter","Smoking area","Do not eat","No smoking"],"correct":3,"explanation":"Signs use \"ne pas\" + infinitive.","translations":{"es":{"question":"Un cartel dice «Ne pas fumer». ¿Qué significa?","explanation":"Los carteles usan «ne pas» + infinitivo.","options":["Prohibido entrar","Zona de fumadores","Prohibido comer","Prohibido fumar"]}}},{"id":"3","question":"\"Tu parles anglais ?\" — \"Oui, je ___ parle bien.\"","options":["la","en","lui","le"],"correct":3,"explanation":"\"Le\" replaces \"l''anglais\" (direct object, masculine).","translations":{"es":{"question":"«Tu parles anglais ?» — «Oui, je ___ parle bien.»","explanation":"«Le» sustituye a «l''anglais» (complemento directo, masculino)."}}},{"id":"4","question":"Which is the most polite way to ask for directions?","options":["Où est la gare ?","La gare, où ?","Dis-moi où est la gare.","Pourriez-vous me dire où se trouve la gare ?"],"correct":3,"explanation":"The conditional \"pourriez-vous\" is very polite.","translations":{"es":{"question":"¿Cuál es la forma más cortés de pedir indicaciones?","explanation":"El condicional «pourriez-vous» es muy cortés."}}},{"id":"5","question":"Complete: \"Il vaut mieux que vous ___ à quelqu''un d''autre.\"","options":["demanderez","demandez","avez demandé","demandiez"],"correct":3,"explanation":"\"Il vaut mieux que\" + subjunctive.","translations":{"es":{"question":"Completa: «Il vaut mieux que vous ___ à quelqu''un d''autre.»","explanation":"«Il vaut mieux que» + subjuntivo."}}},{"id":"6","question":"\"Savoir\" or \"connaître\"? \"Je ne ___ pas cette ville.\"","options":["savoir","sais","connaître","connais"],"correct":3,"explanation":"\"Connaître\" for people and places; \"savoir\" for facts and skills.","translations":{"es":{"question":"¿«Savoir» o «connaître»? «Je ne ___ pas cette ville.»","explanation":"«Connaître» para personas y lugares; «savoir» para datos y habilidades."}}},{"id":"7","question":"What does \"avoir tort\" mean?","options":["to be right","to be hurt","to be late","to be wrong"],"correct":3,"explanation":"Avoir raison = to be right; avoir tort = to be wrong.","translations":{"es":{"question":"¿Qué significa «avoir tort»?","explanation":"Avoir raison = tener razón; avoir tort = estar equivocado.","options":["tener razón","estar herido","llegar tarde","estar equivocado"]}}},{"id":"8","question":"How do you ask someone to speak more slowly (tu)?","options":["Tu parles lentement.","Parlez plus vite.","Je parle lentement, s''il te plaît.","Parle plus lentement, s''il te plaît."],"correct":3,"explanation":"Imperative of \"parler\" with tu: \"parle\" (no -s).","translations":{"es":{"question":"¿Cómo pides a alguien que hable más despacio (tu)?","explanation":"Imperativo de «parler» con tu: «parle» (sin -s)."}}}]}'::jsonb, 3),
  ('story', 'Au guichet de la gare', '{"text":"Ana est espagnole. Elle arrive à la gare de Lille et elle va au guichet. « Bonjour, monsieur. Je voudrais un billet pour Bruges, s''il vous plaît. » « Quoi ? Parlez plus fort ! » « Pardon. Un billet pour Bruges. Pourriez-vous parler plus lentement ? Je ne parle pas très bien français. » « Ce n''est pas mon problème, madame. Il vaut mieux que vous achetiez votre billet sur la machine. » « Mais la machine est en panne ! » « Alors, attendez. Je suis très occupé. » Un homme derrière Ana dit : « Excusez-moi, je peux vous aider ? Je connais bien cette gare. » « Oh, merci beaucoup ! Vous êtes très aimable. » « Avec plaisir. Venez, il y a un autre guichet à côté de la sortie. » Ana sourit. « Peut-être avez-vous raison : tout le monde n''est pas désagréable ! »","translation":"Ana is Spanish. She arrives at Lille station and goes to the ticket office. “Hello, sir. I would like a ticket to Bruges, please.” “What? Speak louder!” “Sorry. A ticket to Bruges. Could you speak more slowly? I don''t speak French very well.” “That''s not my problem, madam. You had better buy your ticket from the machine.” “But the machine is out of order!” “Then wait. I''m very busy.” A man behind Ana says: “Excuse me, can I help you? I know this station well.” “Oh, thank you very much! You are very kind.” “With pleasure. Come, there is another ticket office next to the exit.” Ana smiles. “Maybe you''re right: not everyone is unpleasant!”","translations":{"es":"Ana es española. Llega a la estación de Lille y va a la taquilla. «Buenos días, señor. Quisiera un billete para Brujas, por favor.» «¿Qué? ¡Hable más fuerte!» «Perdón. Un billete para Brujas. ¿Podría hablar más despacio? No hablo muy bien francés.» «Ese no es mi problema, señora. Es mejor que compre su billete en la máquina.» «¡Pero la máquina está averiada!» «Entonces espere. Estoy muy ocupado.» Un hombre detrás de Ana dice: «Disculpe, ¿puedo ayudarla? Conozco bien esta estación.» «¡Oh, muchas gracias! Es usted muy amable.» «Con mucho gusto. Venga, hay otra taquilla al lado de la salida.» Ana sonríe. «Quizás tenga usted razón: ¡no todo el mundo es desagradable!»"},"highlighted_words":["Quoi","Parlez plus fort","Pourriez-vous","lentement","Il vaut mieux que","achetiez","attendez","connais","sortie","raison"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Où","est","la","sortie","s''il","vous","plaît"],"translation":"Where is the exit please","translations":{"es":"¿Dónde está la salida, por favor?"}},{"words":["Fermez","la","porte"],"translation":"Close the door","translations":{"es":"Cierre la puerta"}},{"words":["Je","ne","comprends","pas","ce","mot"],"translation":"I don''t understand this word","translations":{"es":"No entiendo esta palabra"}},{"words":["Pourriez-vous","parler","plus","lentement"],"translation":"Could you speak more slowly","translations":{"es":"¿Podría hablar más despacio?"}},{"words":["Il","vaut","mieux","que","tu","partes"],"translation":"It''s better that you leave","translations":{"es":"Es mejor que te vayas"}},{"words":["Vous","avez","raison"],"translation":"You are right","translations":{"es":"Tiene razón"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Why not?","translations":{"es":"¿Por qué no?"},"answer":"Pourquoi pas ?"},{"prompt":"Where is the entrance?","translations":{"es":"¿Dónde está la entrada?"},"answer":"Où est l''entrée ?"},{"prompt":"What does it mean?","translations":{"es":"¿Qué significa eso?"},"answer":"Qu''est-ce que ça veut dire ?"},{"prompt":"I don''t know","translations":{"es":"No lo sé"},"answer":"Je ne sais pas"},{"prompt":"No smoking","translations":{"es":"Prohibido fumar"},"answer":"Ne pas fumer"},{"prompt":"Can you help me?","translations":{"es":"¿Puedes ayudarme?"},"answer":"Peux-tu m''aider ?"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 10: Expressions courantes (2)
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-10', 'Expressions courantes (2)', '🗨️', 'Expresiones habituales (2)', 10, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"au sujet de / à propos de","translation":"about","translations":{"es":"acerca de / a propósito de"}},{"id":"2","word":"l''adresse","translation":"the address","translations":{"es":"la dirección"}},{"id":"3","word":"admirable","translation":"admirable","translations":{"es":"admirable"}},{"id":"4","word":"avoir peur","translation":"to be afraid","translations":{"es":"tener miedo"}},{"id":"5","word":"gênant / gênante","translation":"embarrassing","translations":{"es":"incómodo / vergonzoso"}},{"id":"6","word":"étonner","translation":"to surprise / amaze","translations":{"es":"asombrar"}},{"id":"7","word":"horrible","translation":"horrible","translations":{"es":"horrible"}},{"id":"8","word":"mauvais / mauvaise","translation":"bad","translations":{"es":"malo / mala"}},{"id":"9","word":"félicitations","translation":"congratulations","translations":{"es":"felicidades"}},{"id":"10","word":"le doute","translation":"the doubt","translations":{"es":"la duda"}},{"id":"11","word":"drôle","translation":"funny","translations":{"es":"gracioso"}},{"id":"12","word":"content / contente","translation":"glad","translations":{"es":"contento / contenta"}},{"id":"13","word":"reconnaissant / reconnaissante","translation":"grateful","translations":{"es":"agradecido / agradecida"}},{"id":"14","word":"l''aide","translation":"help","translations":{"es":"la ayuda"}},{"id":"15","word":"avoir hâte","translation":"to look forward / be eager","translations":{"es":"tener ganas / estar deseando"}},{"id":"16","word":"attendre","translation":"to wait","translations":{"es":"esperar"}},{"id":"17","word":"l''idée","translation":"the idea","translations":{"es":"la idea"}},{"id":"18","word":"incroyable","translation":"incredible","translations":{"es":"increíble"}},{"id":"19","word":"magnifique","translation":"magnificent","translations":{"es":"magnífico"}},{"id":"20","word":"la faute","translation":"the mistake","translations":{"es":"el error / la falta"}},{"id":"21","word":"dommage","translation":"a pity","translations":{"es":"una lástima"}},{"id":"22","word":"faire confiance","translation":"to trust","translations":{"es":"confiar"}},{"id":"23","word":"triste","translation":"sad","translations":{"es":"triste"}},{"id":"24","word":"bizarre","translation":"strange","translations":{"es":"raro"}},{"id":"25","word":"la surprise","translation":"the surprise","translations":{"es":"la sorpresa"}},{"id":"26","word":"énervant / énervante","translation":"annoying","translations":{"es":"irritante"}},{"id":"27","word":"urgent / urgente","translation":"urgent","translations":{"es":"urgente"}},{"id":"28","word":"se tromper","translation":"to be mistaken","translations":{"es":"equivocarse"}}],"grammar":[{"structure":"subjonctif après un sentiment","example":"C''est dommage que tu partes. / Je suis heureuse qu''elle soit venue.","en":"Subjunctive after feelings","es":"Subjuntivo tras sentimientos"},{"structure":"vouloir que / il est urgent que + subjonctif","example":"Je veux que tu le saches. / Il est urgent que j''apprenne l''italien.","en":"Subjunctive after wishes and necessity","es":"Subjuntivo tras deseos y necesidad"},{"structure":"si + imparfait → conditionnel","example":"Je serais très heureux si je pouvais parler italien.","en":"Hypothesis (unreal present)","es":"Hipótesis (presente irreal)"},{"structure":"passé composé des verbes pronominaux","example":"Je me suis bien amusé. / Que s''est-il passé ?","en":"Past tense of reflexive verbs (être)","es":"Pasado de los verbos pronominales (être)"},{"structure":"imparfait","example":"Hier, tu étais très heureuse.","en":"Imperfect (description)","es":"Imperfecto (descripción)"},{"structure":"futur simple","example":"Tu seras surpris. / J''irai en Italie l''année prochaine.","en":"Simple future","es":"Futuro simple"},{"structure":"avoir peur de / avoir l''air","example":"J''ai peur de faire des fautes. / Tu as l''air triste.","en":"Fixed expressions with avoir","es":"Expresiones con avoir"},{"structure":"infinitif passé","example":"Ravi de t''avoir rencontré !","en":"Past infinitive","es":"Infinitivo compuesto"}],"tips":[{"en":"Feelings + \"que\" trigger the subjunctive: \"Je suis content que tu sois là\", \"C''est dommage qu''il parte\".","es":"Sentimiento + «que» exige subjuntivo: «Je suis content que tu sois là», «C''est dommage qu''il parte»."},{"en":"Hypothesis: \"si\" + imparfait, then conditional. Never the conditional right after \"si\".","es":"Hipótesis: «si» + imperfecto y luego condicional. Nunca condicional justo después de «si»."},{"en":"\"Ça m''est égal\" = I don''t mind / I don''t care (neutral). Avoid the vulgar \"je m''en fous\".","es":"«Ça m''est égal» = me da igual (neutro). Evita el vulgar «je m''en fous»."},{"en":"\"Je suis à ta disposition\" / \"Tu peux compter sur moi\" are warm ways to offer help.","es":"«Je suis à ta disposition» / «Tu peux compter sur moi» son formas cálidas de ofrecer ayuda."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Je peux te demander quelque chose ? — Oui, bien sûr.","translation":"Can I ask you something? — Yes, of course.","translations":{"es":"¿Puedo preguntarte algo? — Sí, claro."}},{"phrase":"Quelle est ton actrice préférée ? — Juliette Binoche.","translation":"Who is your favorite actress? — Juliette Binoche.","translations":{"es":"¿Cuál es tu actriz favorita? — Juliette Binoche."}},{"phrase":"À vrai dire, ça m''est égal.","translation":"To be honest, I don''t mind.","translations":{"es":"A decir verdad, me da igual."}},{"phrase":"Tu t''es bien amusé à Rome ? — Oui, mais je me suis plus amusé à Lisbonne.","translation":"Did you have fun in Rome? — Yes, but I had more fun in Lisbon.","translations":{"es":"¿Te divertiste en Roma? — Sí, pero me divertí más en Lisboa."}},{"phrase":"Tu as l''air triste. Que s''est-il passé ?","translation":"You look sad. What happened?","translations":{"es":"Pareces triste. ¿Qué ha pasado?"}},{"phrase":"C''est dommage que tu partes, tu es quelqu''un d''incroyable.","translation":"It''s a pity you''re leaving, you''re an incredible person.","translations":{"es":"Es una lástima que te vayas, eres una persona increíble."}},{"phrase":"Merci ! — De rien. Tu peux toujours compter sur moi.","translation":"Thanks! — You''re welcome. You can always count on me.","translations":{"es":"¡Gracias! — De nada. Siempre puedes contar conmigo."}},{"phrase":"Je suis à ta disposition. Que puis-je faire pour toi ?","translation":"I am at your service. What can I do for you?","translations":{"es":"Estoy a tu disposición. ¿Qué puedo hacer por ti?"}},{"phrase":"Désolé de vous déranger. — Il n''y a pas de problème.","translation":"Sorry to bother you. — No problem.","translations":{"es":"Perdone que le moleste. — No hay problema."}},{"phrase":"Quel dommage !","translation":"What a pity!","translations":{"es":"¡Qué lástima!"}},{"phrase":"J''ai une idée !","translation":"I have an idea!","translations":{"es":"¡Tengo una idea!"}},{"phrase":"Tu te trompes.","translation":"You are mistaken.","translations":{"es":"Te equivocas."}},{"phrase":"Je veux que tu le saches.","translation":"I want you to know it.","translations":{"es":"Quiero que lo sepas."}},{"phrase":"Appelle-moi demain !","translation":"Call me tomorrow!","translations":{"es":"¡Llámame mañana!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"C''est dommage que tu ___.\"","options":["es parti","partes","partiras","pars"],"correct":1,"explanation":"\"C''est dommage que\" expresses a feeling → subjunctive.","translations":{"es":{"question":"Completa: «C''est dommage que tu ___.»","explanation":"«C''est dommage que» expresa un sentimiento → subjuntivo."}}},{"id":"2","question":"Complete: \"Je serais heureux si je ___ parler italien.\"","options":["pouvais","pourrai","peux","pourrais"],"correct":0,"explanation":"After \"si\": imparfait (pouvais), never the conditional.","translations":{"es":{"question":"Completa: «Je serais heureux si je ___ parler italien.»","explanation":"Después de «si»: imperfecto (pouvais), nunca condicional."}}},{"id":"3","question":"Which past form is correct?","options":["Je me suis bien amusé.","Je suis me bien amusé.","Je me suis bien amuser.","Je m''ai bien amusé."],"correct":0,"explanation":"Reflexive verbs use \"être\" in the passé composé.","translations":{"es":{"question":"¿Qué forma del pasado es correcta?","explanation":"Los verbos pronominales usan «être» en el passé composé."}}},{"id":"4","question":"What does \"Tu as l''air fatigué\" mean?","options":["You were tired.","You are tired of the air.","You look tired.","You need air."],"correct":2,"explanation":"\"Avoir l''air\" + adjective = to look / seem.","translations":{"es":{"question":"¿Qué significa «Tu as l''air fatigué»?","explanation":"«Avoir l''air» + adjetivo = parecer.","options":["Estabas cansado.","Estás cansado del aire.","Pareces cansado.","Necesitas aire."]}}},{"id":"5","question":"Neutral way to say \"I don''t mind\":","options":["C''est horrible.","Tu te trompes.","Ça m''est égal.","Je m''en fous."],"correct":2,"explanation":"\"Je m''en fous\" means the same but is vulgar.","translations":{"es":{"question":"Forma neutra de decir «me da igual»:","explanation":"«Je m''en fous» significa lo mismo pero es vulgar."}}},{"id":"6","question":"Complete: \"Il est urgent que j''___ l''anglais.\"","options":["apprendrai","apprenais","apprenne","apprends"],"correct":2,"explanation":"\"Il est urgent que\" + subjunctive (apprendre → que j''apprenne).","translations":{"es":{"question":"Completa: «Il est urgent que j''___ l''anglais.»","explanation":"«Il est urgent que» + subjuntivo (apprendre → que j''apprenne)."}}},{"id":"7","question":"How do you say \"Nice to have met you!\"?","options":["Ravi rencontrer toi !","Ravi que je t''ai rencontré !","Ravi de t''avoir rencontré !","Ravi de te rencontrer demain !"],"correct":2,"explanation":"Past infinitive: avoir + past participle.","translations":{"es":{"question":"¿Cómo se dice «¡Encantado de haberte conocido!»?","explanation":"Infinitivo compuesto: avoir + participio."}}},{"id":"8","question":"What does \"J''ai hâte de te voir\" mean?","options":["I can''t wait to see you.","I saw you in a hurry.","I must see you.","I hate seeing you."],"correct":0,"explanation":"\"Avoir hâte de\" = to look forward to (false friend with \"hate\"!).","translations":{"es":{"question":"¿Qué significa «J''ai hâte de te voir»?","explanation":"«Avoir hâte de» = estar deseando (¡falso amigo del inglés «hate»!).","options":["Tengo muchas ganas de verte.","Te vi con prisa.","Tengo que verte.","Odio verte."]}}}]}'::jsonb, 3),
  ('story', 'Une rencontre à l''anniversaire', '{"text":"« Bonsoir ! Comment tu t''appelles ? » « Je m''appelle Élise. Je suis la cousine de Mathieu, c''est son anniversaire. Et toi ? » « Moi, c''est Karim. Je suis un collègue de Mathieu. Il m''a gentiment invité. » « Super, tu es le bienvenu ! Qu''est-ce que tu fais dans la vie ? » « Je suis photographe pour un journal régional. Et toi ? » « Je suis professeure d''italien au lycée. » « C''est vrai ? J''ai toujours voulu apprendre l''italien, mais j''ai peur de faire des fautes. » « Ce n''est pas si difficile, tu sais. » « Je serais très heureux si je pouvais le parler. En fait, il est urgent que je l''apprenne : j''irai probablement à Rome l''année prochaine pour le travail. » « Alors, je peux te donner quelques cours. Fais-moi confiance, tu seras surpris ! » « Merci, c''est très gentil. Oh, il est tard, je dois partir. C''est dommage que la soirée finisse déjà ! Ravi de t''avoir rencontrée. » « Moi aussi. Appelle-moi ! »","translation":"“Good evening! What''s your name?” “My name is Élise. I''m Mathieu''s cousin, it''s his birthday. And you?” “I''m Karim. I''m a colleague of Mathieu''s. He kindly invited me.” “Great, you''re welcome here! What do you do for a living?” “I''m a photographer for a regional newspaper. And you?” “I teach Italian at a high school.” “Really? I''ve always wanted to learn Italian, but I''m afraid of making mistakes.” “It''s not that difficult, you know.” “I would be very happy if I could speak it. Actually, it''s urgent that I learn it: I''ll probably go to Rome next year for work.” “Then I can give you a few lessons. Trust me, you''ll be surprised!” “Thanks, that''s very kind. Oh, it''s late, I have to go. It''s a pity the party is already ending! Nice to have met you.” “Me too. Call me!”","translations":{"es":"«¡Buenas noches! ¿Cómo te llamas?» «Me llamo Élise. Soy la prima de Mathieu, es su cumpleaños. ¿Y tú?» «Yo soy Karim. Soy un compañero de trabajo de Mathieu. Me invitó muy amablemente.» «¡Genial, bienvenido! ¿A qué te dedicas?» «Soy fotógrafo de un periódico regional. ¿Y tú?» «Soy profesora de italiano en un instituto.» «¿De verdad? Siempre he querido aprender italiano, pero me da miedo cometer errores.» «No es tan difícil, ¿sabes?» «Sería muy feliz si pudiera hablarlo. De hecho, es urgente que lo aprenda: probablemente iré a Roma el año que viene por trabajo.» «Entonces puedo darte algunas clases. ¡Confía en mí, te sorprenderás!» «Gracias, es muy amable. Oh, es tarde, tengo que irme. ¡Qué lástima que la fiesta ya termine! Encantado de haberte conocido.» «Yo también. ¡Llámame!»"},"highlighted_words":["bienvenu","j''ai peur de","serais","si je pouvais","il est urgent que","irai","Fais-moi confiance","seras surpris","C''est dommage que","Ravi de t''avoir rencontrée"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["J''ai","peur","de","faire","des","fautes"],"translation":"I''m afraid of making mistakes","translations":{"es":"Me da miedo cometer errores"}},{"words":["C''est","dommage","que","tu","partes"],"translation":"It''s a pity you''re leaving","translations":{"es":"Es una lástima que te vayas"}},{"words":["Tu","peux","compter","sur","moi"],"translation":"You can count on me","translations":{"es":"Puedes contar conmigo"}},{"words":["Je","me","suis","bien","amusé","hier"],"translation":"I had a lot of fun yesterday","translations":{"es":"Me divertí mucho ayer"}},{"words":["Je","serais","content","si","tu","venais"],"translation":"I would be glad if you came","translations":{"es":"Me alegraría si vinieras"}},{"words":["Je","veux","que","tu","le","saches"],"translation":"I want you to know it","translations":{"es":"Quiero que lo sepas"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"What a pity!","translations":{"es":"¡Qué lástima!"},"answer":"Quel dommage !"},{"prompt":"I have an idea","translations":{"es":"Tengo una idea"},"answer":"J''ai une idée"},{"prompt":"What happened?","translations":{"es":"¿Qué ha pasado?"},"answer":"Que s''est-il passé ?"},{"prompt":"Congratulations!","translations":{"es":"¡Felicidades!"},"answer":"Félicitations !"},{"prompt":"You are mistaken","translations":{"es":"Te equivocas"},"answer":"Tu te trompes"},{"prompt":"Call me tomorrow","translations":{"es":"Llámame mañana"},"answer":"Appelle-moi demain"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 11: Le corps humain
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-11', 'Le corps humain', '🫀', 'El cuerpo humano', 11, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la tête","translation":"the head","translations":{"es":"la cabeza"}},{"id":"2","word":"les cheveux","translation":"hair","translations":{"es":"el pelo"}},{"id":"3","word":"le visage","translation":"the face","translations":{"es":"la cara"}},{"id":"4","word":"la barbe","translation":"the beard","translations":{"es":"la barba"}},{"id":"5","word":"la bouche","translation":"the mouth","translations":{"es":"la boca"}},{"id":"6","word":"les dents","translation":"teeth","translations":{"es":"los dientes"}},{"id":"7","word":"la langue","translation":"the tongue","translations":{"es":"la lengua"}},{"id":"8","word":"les lèvres","translation":"lips","translations":{"es":"los labios"}},{"id":"9","word":"le menton","translation":"the chin","translations":{"es":"la barbilla"}},{"id":"10","word":"les oreilles","translation":"ears","translations":{"es":"las orejas"}},{"id":"11","word":"le nez","translation":"the nose","translations":{"es":"la nariz"}},{"id":"12","word":"les yeux","translation":"eyes","translations":{"es":"los ojos"}},{"id":"13","word":"les sourcils","translation":"eyebrows","translations":{"es":"las cejas"}},{"id":"14","word":"les cils","translation":"eyelashes","translations":{"es":"las pestañas"}},{"id":"15","word":"le front","translation":"the forehead","translations":{"es":"la frente"}},{"id":"16","word":"le cou","translation":"the neck","translations":{"es":"el cuello"}},{"id":"17","word":"la gorge","translation":"the throat","translations":{"es":"la garganta"}},{"id":"18","word":"les joues","translation":"cheeks","translations":{"es":"las mejillas"}},{"id":"19","word":"la poitrine","translation":"the chest","translations":{"es":"el pecho"}},{"id":"20","word":"les épaules","translation":"shoulders","translations":{"es":"los hombros"}},{"id":"21","word":"le bras","translation":"the arm","translations":{"es":"el brazo"}},{"id":"22","word":"le coude","translation":"the elbow","translations":{"es":"el codo"}},{"id":"23","word":"le poignet","translation":"the wrist","translations":{"es":"la muñeca"}},{"id":"24","word":"la main","translation":"the hand","translations":{"es":"la mano"}},{"id":"25","word":"les doigts","translation":"fingers","translations":{"es":"los dedos"}},{"id":"26","word":"le pouce","translation":"the thumb","translations":{"es":"el pulgar"}},{"id":"27","word":"les ongles","translation":"nails","translations":{"es":"las uñas"}},{"id":"28","word":"le ventre","translation":"the belly","translations":{"es":"la barriga"}},{"id":"29","word":"l''estomac","translation":"the stomach","translations":{"es":"el estómago"}},{"id":"30","word":"le dos","translation":"the back","translations":{"es":"la espalda"}},{"id":"31","word":"les hanches","translation":"hips","translations":{"es":"las caderas"}},{"id":"32","word":"la jambe","translation":"the leg","translations":{"es":"la pierna"}},{"id":"33","word":"le genou","translation":"the knee","translations":{"es":"la rodilla"}},{"id":"34","word":"la cheville","translation":"the ankle","translations":{"es":"el tobillo"}},{"id":"35","word":"le pied","translation":"the foot","translations":{"es":"el pie"}},{"id":"36","word":"le cœur","translation":"the heart","translations":{"es":"el corazón"}},{"id":"37","word":"les poumons","translation":"lungs","translations":{"es":"los pulmones"}},{"id":"38","word":"le cerveau","translation":"the brain","translations":{"es":"el cerebro"}},{"id":"39","word":"les os","translation":"bones","translations":{"es":"los huesos"}},{"id":"40","word":"le sang","translation":"blood","translations":{"es":"la sangre"}},{"id":"41","word":"la peau","translation":"skin","translations":{"es":"la piel"}},{"id":"42","word":"la vue","translation":"sight","translations":{"es":"la vista"}},{"id":"43","word":"l''ouïe","translation":"hearing","translations":{"es":"el oído"}},{"id":"44","word":"l''odorat","translation":"smell","translations":{"es":"el olfato"}},{"id":"45","word":"le goût","translation":"taste","translations":{"es":"el gusto"}},{"id":"46","word":"le toucher","translation":"touch","translations":{"es":"el tacto"}}],"grammar":[{"structure":"avoir mal à / au / aux","example":"J''ai mal à la tête. / J''ai mal au bras. / J''ai mal aux pieds.","en":"Saying where it hurts","es":"Decir dónde duele"},{"structure":"avoir l''air + adjectif","example":"Tu as l''air fatiguée.","en":"To look / seem","es":"Parecer"},{"structure":"devoir (probabilité)","example":"Ils sont pâles, ils doivent être malades.","en":"\"devoir\" for probability","es":"«devoir» para expresar probabilidad"},{"structure":"futur proche / futur simple","example":"Elle va avoir la grippe. / Tes os seront forts.","en":"Near future and simple future","es":"Futuro próximo y futuro simple"},{"structure":"impératif","example":"Prends ce médicament.","en":"Imperative (advice)","es":"Imperativo (consejos)"},{"structure":"comparatif","example":"Tu es plus grande que moi.","en":"Comparatives","es":"Comparativos"},{"structure":"se trouver","example":"Les oreilles se trouvent de chaque côté de la tête.","en":"Locating with \"se trouver\"","es":"Ubicar con «se trouver»"},{"structure":"passé composé","example":"J''ai beaucoup joué au volley.","en":"Past tense","es":"Pretérito perfecto"}],"tips":[{"en":"\"Avoir mal à\" contracts: à + le = au (au dos), à + les = aux (aux dents).","es":"«Avoir mal à» se contrae: à + le = au (au dos), à + les = aux (aux dents)."},{"en":"French uses the article, not the possessive, with body parts: \"Je me lave les mains\" (not \"mes mains\").","es":"En francés se usa el artículo, no el posesivo, con las partes del cuerpo: «Je me lave les mains» (no «mes mains»)."},{"en":"Idioms: \"donner un coup de main\" (to lend a hand), \"avoir le cœur sur la main\" (to be generous), \"coûter les yeux de la tête\" (to cost a fortune).","es":"Expresiones: «donner un coup de main» (echar una mano), «avoir le cœur sur la main» (ser generoso), «coûter les yeux de la tête» (costar un ojo de la cara)."},{"en":"Height: \"Combien tu mesures ? — Je mesure 1,70 m\" (un mètre soixante-dix).","es":"Estatura: «Combien tu mesures ? — Je mesure 1,70 m» (un mètre soixante-dix)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"J''ai mal à la tête.","translation":"I have a headache.","translations":{"es":"Me duele la cabeza."}},{"phrase":"Tu as l''air fatiguée.","translation":"You look tired.","translations":{"es":"Pareces cansada."}},{"phrase":"Elle a mal aux oreilles.","translation":"Her ears hurt.","translations":{"es":"Le duelen los oídos."}},{"phrase":"Il va sûrement avoir la grippe.","translation":"He''s surely going to get the flu.","translations":{"es":"Seguro que va a tener gripe."}},{"phrase":"Mon bébé a de la fièvre. Que pourrais-je faire ?","translation":"My baby has a fever. What could I do?","translations":{"es":"Mi bebé tiene fiebre. ¿Qué podría hacer?"}},{"phrase":"J''ai mal au bras gauche : j''ai beaucoup joué au volley.","translation":"My left arm hurts: I played a lot of volleyball.","translations":{"es":"Me duele el brazo izquierdo: he jugado mucho al vóley."}},{"phrase":"Prends ce médicament et repose-toi.","translation":"Take this medicine and rest.","translations":{"es":"Toma este medicamento y descansa."}},{"phrase":"J''ai rendez-vous chez le médecin.","translation":"I have a doctor''s appointment.","translations":{"es":"Tengo cita con el médico."}},{"phrase":"Bois du lait tous les jours et tes os seront forts.","translation":"Drink milk every day and your bones will be strong.","translations":{"es":"Bebe leche todos los días y tus huesos estarán fuertes."}},{"phrase":"Tu as mal aux dents ? Tu dois aller chez le dentiste.","translation":"Do you have toothache? You must go to the dentist.","translations":{"es":"¿Te duelen las muelas? Tienes que ir al dentista."}},{"phrase":"De quelle couleur sont tes yeux ? — Ils sont verts.","translation":"What color are your eyes? — They are green.","translations":{"es":"¿De qué color son tus ojos? — Son verdes."}},{"phrase":"Combien tu mesures ? — Je mesure un mètre soixante-cinq.","translation":"How tall are you? — I am 1.65 m.","translations":{"es":"¿Cuánto mides? — Mido un metro sesenta y cinco."}},{"phrase":"Ils sont pâles, ils doivent être malades.","translation":"They are pale, they must be ill.","translations":{"es":"Están pálidos, deben de estar enfermos."}},{"phrase":"Peux-tu me donner un coup de main ?","translation":"Can you give me a hand?","translations":{"es":"¿Puedes echarme una mano?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"J''ai mal ___ dos.\"","options":["à la","au","aux","à"],"correct":1,"explanation":"\"Le dos\" is masculine: à + le = au.","translations":{"es":{"question":"Completa: «J''ai mal ___ dos.»","explanation":"«Le dos» es masculino: à + le = au."}}},{"id":"2","question":"Complete: \"Elle a mal ___ dents.\"","options":["à la","au","aux","des"],"correct":2,"explanation":"Plural: à + les = aux.","translations":{"es":{"question":"Completa: «Elle a mal ___ dents.»","explanation":"Plural: à + les = aux."}}},{"id":"3","question":"\"Ils sont pâles, ils doivent être malades.\" What does \"doivent\" express here?","options":["the past","obligation","probability","a wish"],"correct":2,"explanation":"\"Devoir\" can mean \"must be / probably are\".","translations":{"es":{"question":"«Ils sont pâles, ils doivent être malades.» ¿Qué expresa aquí «doivent»?","explanation":"«Devoir» puede significar «deben de estar / probablemente están».","options":["el pasado","obligación","probabilidad","un deseo"]}}},{"id":"4","question":"What does \"donner un coup de main\" mean?","options":["to hit someone","to shake hands","to lend a hand","to wave"],"correct":2,"explanation":"It''s an idiom: to help someone.","translations":{"es":{"question":"¿Qué significa «donner un coup de main»?","explanation":"Es una expresión: ayudar a alguien.","options":["pegar a alguien","dar la mano","echar una mano","saludar con la mano"]}}},{"id":"5","question":"Which sense is \"l''odorat\"?","options":["taste","hearing","smell","touch"],"correct":2,"explanation":"La vue, l''ouïe, l''odorat, le goût, le toucher.","translations":{"es":{"question":"¿Qué sentido es «l''odorat»?","explanation":"La vue, l''ouïe, l''odorat, le goût, le toucher.","options":["el gusto","el oído","el olfato","el tacto"]}}},{"id":"6","question":"How do you ask someone''s height?","options":["Combien tu mesures ?","Quel âge as-tu ?","Combien tu pèses ?","Comment es-tu ?"],"correct":0,"explanation":"\"Mesurer\" = to measure; \"peser\" = to weigh.","translations":{"es":{"question":"¿Cómo preguntas la estatura de alguien?","explanation":"«Mesurer» = medir; «peser» = pesar."}}},{"id":"7","question":"Which sentence is correct in French?","options":["Je lave mes mains à moi.","Je me lave les mains.","Je me lave mes mains.","Je me lave la main mes."],"correct":1,"explanation":"With body parts, use the article with a reflexive verb.","translations":{"es":{"question":"¿Qué frase es correcta en francés?","explanation":"Con partes del cuerpo se usa el artículo y un verbo pronominal."}}},{"id":"8","question":"Where is the brain?","options":["dans la tête","dans le ventre","dans la poitrine","dans le dos"],"correct":0,"explanation":"Le cerveau se trouve dans la tête; le cœur et les poumons, dans la poitrine.","translations":{"es":{"question":"¿Dónde está el cerebro?","explanation":"Le cerveau se trouve dans la tête; le cœur et les poumons, dans la poitrine."}}}]}'::jsonb, 3),
  ('story', 'Le cours de yoga', '{"text":"Ce matin, Nora va à son premier cours de yoga. Elle a l''air un peu nerveuse. Le professeur, Bastien, sourit : « Bienvenue ! Asseyez-vous sur le tapis et fermez les yeux. » Il explique : « Respirez lentement. L''air entre par le nez et va jusqu''aux poumons. Maintenant, levez les bras au-dessus de la tête. Baissez les épaules et tournez le cou doucement. » Nora a mal au dos : hier, elle a beaucoup travaillé devant l''ordinateur. « Pliez les genoux et touchez vos pieds avec les mains. » Une autre élève rit : « Je ne peux pas, mes jambes sont trop longues ! » À la fin du cours, Bastien dit : « Si vous pratiquez tous les jours, votre corps sera plus fort et votre tête plus tranquille. » Nora se sent mieux. Elle doit être plus détendue, car son cœur bat plus lentement. « Merci pour le coup de main, Bastien. Je reviendrai la semaine prochaine ! »","translation":"This morning, Nora is going to her first yoga class. She looks a bit nervous. The teacher, Bastien, smiles: “Welcome! Sit down on the mat and close your eyes.” He explains: “Breathe slowly. The air comes in through the nose and goes down to the lungs. Now, raise your arms above your head. Lower your shoulders and turn your neck gently.” Nora''s back hurts: yesterday, she worked a lot at the computer. “Bend your knees and touch your feet with your hands.” Another student laughs: “I can''t, my legs are too long!” At the end of the class, Bastien says: “If you practice every day, your body will be stronger and your mind calmer.” Nora feels better. She must be more relaxed, because her heart is beating more slowly. “Thanks for the help, Bastien. I''ll come back next week!”","translations":{"es":"Esta mañana, Nora va a su primera clase de yoga. Parece un poco nerviosa. El profesor, Bastien, sonríe: «¡Bienvenida! Siéntese en la esterilla y cierre los ojos.» Explica: «Respire despacio. El aire entra por la nariz y llega hasta los pulmones. Ahora, levante los brazos por encima de la cabeza. Baje los hombros y gire el cuello suavemente.» A Nora le duele la espalda: ayer trabajó mucho delante del ordenador. «Doble las rodillas y tóquese los pies con las manos.» Otra alumna se ríe: «¡No puedo, tengo las piernas demasiado largas!» Al final de la clase, Bastien dice: «Si practican todos los días, su cuerpo estará más fuerte y su mente más tranquila.» Nora se siente mejor. Debe de estar más relajada, porque su corazón late más despacio. «Gracias por la ayuda, Bastien. ¡Volveré la semana que viene!»"},"highlighted_words":["a l''air","yeux","nez","poumons","bras","tête","épaules","cou","mal au dos","genoux","pieds","mains","jambes","cœur","doit être","coup de main"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["J''ai","mal","à","la","tête"],"translation":"I have a headache","translations":{"es":"Me duele la cabeza"}},{"words":["Tu","as","l''air","fatigué"],"translation":"You look tired","translations":{"es":"Pareces cansado"}},{"words":["Prends","ce","médicament"],"translation":"Take this medicine","translations":{"es":"Toma este medicamento"}},{"words":["Il","doit","être","malade"],"translation":"He must be ill","translations":{"es":"Debe de estar enfermo"}},{"words":["Elle","a","les","yeux","verts"],"translation":"She has green eyes","translations":{"es":"Tiene los ojos verdes"}},{"words":["Je","me","lave","les","mains"],"translation":"I wash my hands","translations":{"es":"Me lavo las manos"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"My back hurts","translations":{"es":"Me duele la espalda"},"answer":"J''ai mal au dos"},{"prompt":"She has a fever","translations":{"es":"Tiene fiebre"},"answer":"Elle a de la fièvre"},{"prompt":"I have to go to the doctor","translations":{"es":"Tengo que ir al médico"},"answer":"Je dois aller chez le médecin"},{"prompt":"His eyes are blue","translations":{"es":"Sus ojos son azules"},"answer":"Ses yeux sont bleus"},{"prompt":"He has black hair","translations":{"es":"Tiene el pelo negro"},"answer":"Il a les cheveux noirs"},{"prompt":"Can you give me a hand?","translations":{"es":"¿Puedes echarme una mano?"},"answer":"Peux-tu me donner un coup de main ?"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 12: Les professions et les métiers
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-12', 'Les professions et les métiers', '💼', 'Las profesiones y los oficios', 12, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le / la comptable","translation":"accountant","translations":{"es":"contable"}},{"id":"2","word":"un acteur / une actrice","translation":"actor / actress","translations":{"es":"actor / actriz"}},{"id":"3","word":"un architecte","translation":"architect","translations":{"es":"arquitecto"}},{"id":"4","word":"un avocat / une avocate","translation":"lawyer","translations":{"es":"abogado / abogada"}},{"id":"5","word":"un boucher / une bouchère","translation":"butcher","translations":{"es":"carnicero / carnicera"}},{"id":"6","word":"un chauffeur","translation":"driver","translations":{"es":"chófer / conductor"}},{"id":"7","word":"un chirurgien / une chirurgienne","translation":"surgeon","translations":{"es":"cirujano / cirujana"}},{"id":"8","word":"un coiffeur / une coiffeuse","translation":"hairdresser","translations":{"es":"peluquero / peluquera"}},{"id":"9","word":"un cuisinier / une cuisinière","translation":"cook","translations":{"es":"cocinero / cocinera"}},{"id":"10","word":"un / une dentiste","translation":"dentist","translations":{"es":"dentista"}},{"id":"11","word":"un dessinateur / une dessinatrice","translation":"illustrator / draftsman","translations":{"es":"dibujante"}},{"id":"12","word":"un électricien","translation":"electrician","translations":{"es":"electricista"}},{"id":"13","word":"un entraîneur","translation":"coach","translations":{"es":"entrenador"}},{"id":"14","word":"un épicier","translation":"grocer","translations":{"es":"tendero"}},{"id":"15","word":"un / une fleuriste","translation":"florist","translations":{"es":"florista"}},{"id":"16","word":"un infirmier / une infirmière","translation":"nurse","translations":{"es":"enfermero / enfermera"}},{"id":"17","word":"un ingénieur","translation":"engineer","translations":{"es":"ingeniero"}},{"id":"18","word":"un jardinier","translation":"gardener","translations":{"es":"jardinero"}},{"id":"19","word":"un / une journaliste","translation":"journalist","translations":{"es":"periodista"}},{"id":"20","word":"un marin","translation":"sailor","translations":{"es":"marinero"}},{"id":"21","word":"un mécanicien","translation":"mechanic","translations":{"es":"mecánico"}},{"id":"22","word":"un menuisier","translation":"carpenter","translations":{"es":"carpintero"}},{"id":"23","word":"un musicien / une musicienne","translation":"musician","translations":{"es":"músico / música"}},{"id":"24","word":"un paysan / une paysanne","translation":"farmer","translations":{"es":"campesino / campesina"}},{"id":"25","word":"un peintre","translation":"painter","translations":{"es":"pintor"}},{"id":"26","word":"un pharmacien","translation":"pharmacist","translations":{"es":"farmacéutico"}},{"id":"27","word":"un / une photographe","translation":"photographer","translations":{"es":"fotógrafo / fotógrafa"}},{"id":"28","word":"un / une pilote","translation":"pilot","translations":{"es":"piloto"}},{"id":"29","word":"un plombier","translation":"plumber","translations":{"es":"fontanero / plomero"}},{"id":"30","word":"un policier / une policière","translation":"police officer","translations":{"es":"policía"}},{"id":"31","word":"un pompier","translation":"firefighter","translations":{"es":"bombero"}},{"id":"32","word":"un / une psychologue","translation":"psychologist","translations":{"es":"psicólogo / psicóloga"}},{"id":"33","word":"un / une secrétaire","translation":"secretary","translations":{"es":"secretario / secretaria"}},{"id":"34","word":"un serveur / une serveuse","translation":"waiter / waitress","translations":{"es":"camarero / camarera"}},{"id":"35","word":"un vendeur / une vendeuse","translation":"salesperson","translations":{"es":"vendedor / vendedora"}},{"id":"36","word":"un / une vétérinaire","translation":"veterinarian","translations":{"es":"veterinario / veterinaria"}},{"id":"37","word":"un écrivain","translation":"writer","translations":{"es":"escritor"}},{"id":"38","word":"un chanteur / une chanteuse","translation":"singer","translations":{"es":"cantante"}},{"id":"39","word":"un agent de voyage","translation":"travel agent","translations":{"es":"agente de viajes"}}],"grammar":[{"structure":"féminin des professions","example":"un acteur / une actrice, un chanteur / une chanteuse","en":"Feminine forms of jobs","es":"Femenino de las profesiones"},{"structure":"futur simple","example":"Tu seras reçu par le meilleur chirurgien. / Je serai dessinateur.","en":"Simple future","es":"Futuro simple"},{"structure":"conditionnel","example":"J''aimerais être écologiste. / Tu devrais être poète.","en":"Conditional (wishes, advice)","es":"Condicional (deseos, consejos)"},{"structure":"vouloir que + subjonctif","example":"Mon père voudrait que je sois médecin.","en":"Wanting someone to do something","es":"Querer que alguien haga algo"},{"structure":"si + imparfait → conditionnel","example":"Que se passerait-il si je décidais de devenir chanteur ?","en":"Hypothesis","es":"Hipótesis"},{"structure":"passé composé / imparfait","example":"J''ai été serveur. / Je travaille depuis que j''étais petit.","en":"Past tenses","es":"Tiempos del pasado"},{"structure":"voix passive","example":"Un marin a été surpris par la tempête.","en":"Passive voice","es":"Voz pasiva"},{"structure":"c''est … qui","example":"C''est notre agent de voyage qui l''a trouvé.","en":"Cleft sentences (emphasis)","es":"Frases enfáticas"},{"structure":"être sur le point de","example":"J''étais sur le point de me noyer.","en":"\"To be about to\"","es":"«Estar a punto de»"}],"tips":[{"en":"No article before a job after \"être\": \"Il est médecin\" (not \"un médecin\"). But \"C''est un bon médecin\" with an adjective.","es":"Sin artículo delante de una profesión después de «être»: «Il est médecin» (no «un médecin»). Pero «C''est un bon médecin» con adjetivo."},{"en":"Feminine endings: -eur → -euse (vendeuse), -teur → -trice (actrice), -ien → -ienne (musicienne). Many are now also used as is: \"une médecin\", \"une professeure\".","es":"Terminaciones femeninas: -eur → -euse (vendeuse), -teur → -trice (actrice), -ien → -ienne (musicienne). Muchas se usan hoy tal cual: «une médecin», «une professeure»."},{"en":"\"Qu''est-ce que tu fais dans la vie ?\" is the natural way to ask someone''s job.","es":"«Qu''est-ce que tu fais dans la vie ?» es la forma natural de preguntar la profesión."},{"en":"\"Aller chez le coiffeur / le médecin\" — use \"chez\" with people, \"à\" with places: \"à la banque\".","es":"«Aller chez le coiffeur / le médecin»: «chez» con personas, «à» con lugares: «à la banque»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Tu es une bonne dentiste et il est un excellent médecin.","translation":"You are a good dentist and he is an excellent doctor.","translations":{"es":"Eres una buena dentista y él es un médico excelente."}},{"phrase":"Tu seras reçu par le meilleur chirurgien.","translation":"You will be seen by the best surgeon.","translations":{"es":"Te atenderá el mejor cirujano."}},{"phrase":"Les infirmières aident les médecins.","translation":"Nurses help doctors.","translations":{"es":"Las enfermeras ayudan a los médicos."}},{"phrase":"Les pompiers sont très importants pour la ville.","translation":"Firefighters are very important for the city.","translations":{"es":"Los bomberos son muy importantes para la ciudad."}},{"phrase":"Tes cheveux sont trop longs : va chez le coiffeur !","translation":"Your hair is too long: go to the hairdresser!","translations":{"es":"Tienes el pelo demasiado largo: ¡ve a la peluquería!"}},{"phrase":"Papa, tu es le meilleur cuisinier du monde.","translation":"Dad, you are the best cook in the world.","translations":{"es":"Papá, eres el mejor cocinero del mundo."}},{"phrase":"Victor Hugo est un grand écrivain.","translation":"Victor Hugo is a great writer.","translations":{"es":"Victor Hugo es un gran escritor."}},{"phrase":"C''est notre agent de voyage qui a trouvé cet hôtel.","translation":"It was our travel agent who found this hotel.","translations":{"es":"Fue nuestro agente de viajes quien encontró este hotel."}},{"phrase":"Le plombier répare les tuyaux de la maison.","translation":"The plumber repairs the pipes in the house.","translations":{"es":"El fontanero repara las tuberías de la casa."}},{"phrase":"L''architecte dessine le bâtiment que l''ingénieur construit.","translation":"The architect designs the building that the engineer builds.","translations":{"es":"El arquitecto diseña el edificio que construye el ingeniero."}},{"phrase":"Il n''y a plus de lumière : appelle l''électricien.","translation":"There''s no more light: call the electrician.","translations":{"es":"Se fue la luz: llama al electricista."}},{"phrase":"La météorologue a annoncé de la pluie pour demain.","translation":"The meteorologist forecast rain for tomorrow.","translations":{"es":"La meteoróloga ha anunciado lluvia para mañana."}},{"phrase":"J''étais sur le point de me noyer quand le sauveteur m''a sorti de l''eau.","translation":"I was about to drown when the lifeguard pulled me out of the water.","translations":{"es":"Estaba a punto de ahogarme cuando el socorrista me sacó del agua."}},{"phrase":"Qu''est-ce que tu fais dans la vie ? — Je suis comptable.","translation":"What do you do for a living? — I am an accountant.","translations":{"es":"¿A qué te dedicas? — Soy contable."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Which sentence is correct?","options":["Elle est une avocate.","Elle est la avocate.","Elle est de avocate.","Elle est avocate."],"correct":3,"explanation":"No article after \"être\" + job (without adjective).","translations":{"es":{"question":"¿Qué frase es correcta?","explanation":"Sin artículo tras «être» + profesión (sin adjetivo)."}}},{"id":"2","question":"What is the feminine of \"acteur\"?","options":["acteure","acteuse","actresse","actrice"],"correct":3,"explanation":"-teur → -trice.","translations":{"es":{"question":"¿Cuál es el femenino de «acteur»?","explanation":"-teur → -trice."}}},{"id":"3","question":"Who repairs your car?","options":["le menuisier","le plombier","l''électricien","le mécanicien"],"correct":3,"explanation":"Le plombier = pipes, le menuisier = wood, l''électricien = electricity.","translations":{"es":{"question":"¿Quién repara tu coche?","explanation":"Le plombier = tuberías, le menuisier = madera, l''électricien = electricidad."}}},{"id":"4","question":"Complete: \"Ma mère voudrait que je ___ vétérinaire.\"","options":["serai","serais","suis","sois"],"correct":3,"explanation":"\"Vouloir que\" + subjunctive: être → que je sois.","translations":{"es":{"question":"Completa: «Ma mère voudrait que je ___ vétérinaire.»","explanation":"«Vouloir que» + subjuntivo: être → que je sois."}}},{"id":"5","question":"Complete: \"Que se passerait-il si je ___ de devenir chanteur ?\"","options":["déciderai","décide","déciderais","décidais"],"correct":3,"explanation":"Si + imparfait, then conditional (\"se passerait\").","translations":{"es":{"question":"Completa: «Que se passerait-il si je ___ de devenir chanteur ?»","explanation":"Si + imperfecto y luego condicional («se passerait»)."}}},{"id":"6","question":"How do you give advice: \"You should be a poet\"?","options":["Tu étais poète.","Tu seras poète.","Tu dois être poète.","Tu devrais être poète."],"correct":3,"explanation":"Conditional of \"devoir\" = should.","translations":{"es":{"question":"¿Cómo das un consejo: «Deberías ser poeta»?","explanation":"Condicional de «devoir» = debería."}}},{"id":"7","question":"\"J''étais sur le point de partir.\" What does it mean?","options":["I was on the way back.","I left at the point.","I had just left.","I was about to leave."],"correct":3,"explanation":"\"Être sur le point de\" + infinitive = to be about to.","translations":{"es":{"question":"«J''étais sur le point de partir.» ¿Qué significa?","explanation":"«Être sur le point de» + infinitivo = estar a punto de.","options":["Estaba de vuelta.","Me fui al punto.","Me acababa de ir.","Estaba a punto de irme."]}}},{"id":"8","question":"Where do you go to get a haircut?","options":["chez la coiffure","au coiffeur","à la coiffeuse","chez le coiffeur"],"correct":3,"explanation":"\"Chez\" + person.","translations":{"es":{"question":"¿Adónde vas a cortarte el pelo?","explanation":"«Chez» + persona."}}}]}'::jsonb, 3),
  ('story', 'Quel métier choisir ?', '{"text":"Je m''appelle Lina, j''ai dix-sept ans et je me demande ce que je ferai plus tard. J''aimerais être biologiste marine, mais mon père voudrait que je sois avocate et ma mère voudrait que je devienne pharmacienne, comme elle. Ma meilleure amie dit que je serai une bonne photographe, parce que je prends toujours de belles photos. Mon grand-père pense que je devrais être écrivain, car j''invente des histoires depuis que j''étais petite. L''été dernier, j''ai été serveuse dans un café du port, et l''année d''avant, j''ai aidé un jardinier du quartier. C''est là que j''ai découvert que j''aime travailler dehors. Que se passerait-il si je décidais de faire un métier que personne n''a imaginé pour moi ? Je ne sais pas. Je veux seulement un travail qui me plaise et qui soit utile. Je voudrais que les océans soient plus propres pour les générations futures. Et si un jour je change d''avis, je pourrai toujours apprendre autre chose !","translation":"My name is Lina, I''m seventeen and I wonder what I''ll do later. I would like to be a marine biologist, but my father would like me to be a lawyer and my mother would like me to become a pharmacist, like her. My best friend says I''ll be a good photographer, because I always take beautiful pictures. My grandfather thinks I should be a writer, because I''ve been making up stories since I was little. Last summer, I was a waitress in a café at the harbor, and the year before, I helped a gardener in the neighborhood. That''s where I discovered that I like working outdoors. What would happen if I decided to do a job nobody imagined for me? I don''t know. I just want a job that I like and that is useful. I would like the oceans to be cleaner for future generations. And if one day I change my mind, I''ll always be able to learn something else!","translations":{"es":"Me llamo Lina, tengo diecisiete años y me pregunto qué haré en el futuro. Me gustaría ser bióloga marina, pero mi padre querría que fuera abogada y mi madre querría que me hiciera farmacéutica, como ella. Mi mejor amiga dice que seré una buena fotógrafa, porque siempre hago fotos bonitas. Mi abuelo piensa que debería ser escritora, porque invento historias desde que era pequeña. El verano pasado fui camarera en un café del puerto y, el año anterior, ayudé a un jardinero del barrio. Fue ahí donde descubrí que me gusta trabajar al aire libre. ¿Qué pasaría si decidiera dedicarme a algo que nadie ha imaginado para mí? No lo sé. Solo quiero un trabajo que me guste y que sea útil. Me gustaría que los océanos estuvieran más limpios para las generaciones futuras. ¡Y si un día cambio de opinión, siempre podré aprender otra cosa!"},"highlighted_words":["ferai","J''aimerais","voudrait que je sois","serai","devrais","j''étais petite","j''ai été serveuse","C''est là que","si je décidais","qui me plaise"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Elle","est","infirmière","à","l''hôpital"],"translation":"She is a nurse at the hospital","translations":{"es":"Es enfermera en el hospital"}},{"words":["Tu","devrais","être","écrivain"],"translation":"You should be a writer","translations":{"es":"Deberías ser escritor"}},{"words":["Mon","père","voudrait","que","je","sois","médecin"],"translation":"My father would like me to be a doctor","translations":{"es":"Mi padre querría que fuera médico"}},{"words":["Va","chez","le","coiffeur"],"translation":"Go to the hairdresser","translations":{"es":"Ve a la peluquería"}},{"words":["C''est","le","pompier","qui","m''a","aidé"],"translation":"It was the firefighter who helped me","translations":{"es":"Fue el bombero quien me ayudó"}},{"words":["J''ai","été","serveur","l''été","dernier"],"translation":"I was a waiter last summer","translations":{"es":"Fui camarero el verano pasado"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I am an engineer","translations":{"es":"Soy ingeniero"},"answer":"Je suis ingénieur"},{"prompt":"She is a salesperson","translations":{"es":"Es vendedora"},"answer":"Elle est vendeuse"},{"prompt":"What do you do for a living?","translations":{"es":"¿A qué te dedicas?"},"answer":"Qu''est-ce que tu fais dans la vie ?"},{"prompt":"I would like to be a photographer","translations":{"es":"Me gustaría ser fotógrafo"},"answer":"J''aimerais être photographe"},{"prompt":"Call the electrician","translations":{"es":"Llama al electricista"},"answer":"Appelle l''électricien"},{"prompt":"The mechanic repairs the car","translations":{"es":"El mecánico repara el coche"},"answer":"Le mécanicien répare la voiture"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 13: La maison : pièces et meubles
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-13', 'La maison : pièces et meubles', '🛋️', 'La casa: habitaciones y muebles', 13, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la porte","translation":"the door","translations":{"es":"la puerta"}},{"id":"2","word":"la fenêtre","translation":"the window","translations":{"es":"la ventana"}},{"id":"3","word":"le couloir","translation":"the hallway","translations":{"es":"el pasillo"}},{"id":"4","word":"la chambre principale","translation":"the master bedroom","translations":{"es":"el dormitorio principal"}},{"id":"5","word":"le sous-sol","translation":"the basement","translations":{"es":"el sótano"}},{"id":"6","word":"le grenier","translation":"the attic","translations":{"es":"el desván"}},{"id":"7","word":"l''escalier","translation":"the stairs","translations":{"es":"la escalera"}},{"id":"8","word":"le rez-de-chaussée","translation":"the ground floor","translations":{"es":"la planta baja"}},{"id":"9","word":"l''étage","translation":"the floor (level)","translations":{"es":"la planta / el piso"}},{"id":"10","word":"le balcon","translation":"the balcony","translations":{"es":"el balcón"}},{"id":"11","word":"la terrasse","translation":"the terrace","translations":{"es":"la terraza"}},{"id":"12","word":"le jardin","translation":"the garden","translations":{"es":"el jardín"}},{"id":"13","word":"la pelouse","translation":"the lawn","translations":{"es":"el césped"}},{"id":"14","word":"le sol","translation":"the floor","translations":{"es":"el suelo"}},{"id":"15","word":"le mur","translation":"the wall","translations":{"es":"la pared"}},{"id":"16","word":"le plafond","translation":"the ceiling","translations":{"es":"el techo"}},{"id":"17","word":"le toit","translation":"the roof","translations":{"es":"el tejado"}},{"id":"18","word":"le fauteuil","translation":"the armchair","translations":{"es":"el sillón"}},{"id":"19","word":"la table basse","translation":"the coffee table","translations":{"es":"la mesa baja"}},{"id":"20","word":"la lampe","translation":"the lamp","translations":{"es":"la lámpara"}},{"id":"21","word":"l''étagère","translation":"the shelf","translations":{"es":"el estante"}},{"id":"22","word":"le rideau","translation":"the curtain","translations":{"es":"la cortina"}},{"id":"23","word":"la cheminée","translation":"the fireplace","translations":{"es":"la chimenea"}},{"id":"24","word":"l''interrupteur","translation":"the light switch","translations":{"es":"el interruptor"}},{"id":"25","word":"la table de nuit","translation":"the bedside table","translations":{"es":"la mesita de noche"}},{"id":"26","word":"l''armoire","translation":"the wardrobe","translations":{"es":"el armario"}},{"id":"27","word":"le placard","translation":"the cupboard","translations":{"es":"el armario empotrado / la alacena"}},{"id":"28","word":"le tiroir","translation":"the drawer","translations":{"es":"el cajón"}},{"id":"29","word":"l''oreiller","translation":"the pillow","translations":{"es":"la almohada"}},{"id":"30","word":"le coussin","translation":"the cushion","translations":{"es":"el cojín"}},{"id":"31","word":"la couverture","translation":"the blanket","translations":{"es":"la manta"}},{"id":"32","word":"la baignoire","translation":"the bathtub","translations":{"es":"la bañera"}},{"id":"33","word":"la douche","translation":"the shower","translations":{"es":"la ducha"}},{"id":"34","word":"le lavabo","translation":"the washbasin","translations":{"es":"el lavabo"}},{"id":"35","word":"le robinet","translation":"the tap","translations":{"es":"el grifo"}},{"id":"36","word":"le miroir","translation":"the mirror","translations":{"es":"el espejo"}},{"id":"37","word":"le congélateur","translation":"the freezer","translations":{"es":"el congelador"}},{"id":"38","word":"le four","translation":"the oven","translations":{"es":"el horno"}},{"id":"39","word":"l''évier","translation":"the kitchen sink","translations":{"es":"el fregadero"}},{"id":"40","word":"la poubelle","translation":"the trash can","translations":{"es":"el cubo de la basura"}},{"id":"41","word":"le sèche-linge","translation":"the dryer","translations":{"es":"la secadora"}},{"id":"42","word":"le chauffage","translation":"the heating","translations":{"es":"la calefacción"}}],"grammar":[{"structure":"impératif + pronom","example":"Mets-le dans le tiroir. / Éteins la lampe.","en":"Imperative with object pronouns","es":"Imperativo con pronombres"},{"structure":"se trouver","example":"Ton médicament se trouve sur la table de nuit.","en":"Locating things","es":"Ubicar objetos"},{"structure":"si + présent → futur","example":"Si tu descends, tu trouveras le sous-sol.","en":"Real condition (future)","es":"Condición real (futuro)"},{"structure":"passé composé / imparfait","example":"Nous avons déménagé. / On ne pouvait pas inviter plus de vingt personnes.","en":"Event vs. past situation","es":"Hecho puntual frente a situación pasada"},{"structure":"pronom relatif « dont »","example":"Le jardin dont ma mère est tombée amoureuse…","en":"Relative pronoun \"dont\"","es":"Pronombre relativo «dont»"},{"structure":"manquer à","example":"Vous me manquez.","en":"\"I miss you\" (inverted structure)","es":"«Los extraño» (estructura invertida)"},{"structure":"futur simple","example":"Elle sera sèche dans une minute. / Je prendrai un bain.","en":"Simple future","es":"Futuro simple"}],"tips":[{"en":"\"Manquer\" is inverted: \"Tu me manques\" = I miss you (literally \"you are missing to me\").","es":"«Manquer» funciona al revés: «Tu me manques» = te echo de menos (literalmente «me faltas»)."},{"en":"\"Le rez-de-chaussée\" is the ground floor; \"le premier étage\" is the floor above it.","es":"«Le rez-de-chaussée» es la planta baja; «le premier étage» es la planta de arriba."},{"en":"With the affirmative imperative, the pronoun goes after the verb with a hyphen: \"Mets-le\", \"Donne-moi\".","es":"Con el imperativo afirmativo, el pronombre va detrás del verbo con guion: «Mets-le», «Donne-moi»."},{"en":"\"Une cuisinière\" is both a (female) cook and a cooker/stove.","es":"«Une cuisinière» es a la vez una cocinera y una cocina (el electrodoméstico)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Voici ma maison. Entre !","translation":"Here is my house. Come in!","translations":{"es":"Esta es mi casa. ¡Pasa!"}},{"phrase":"Ouvrez la porte et fermez la fenêtre.","translation":"Open the door and close the window.","translations":{"es":"Abran la puerta y cierren la ventana."}},{"phrase":"Éteins la lampe, s''il te plaît.","translation":"Turn off the lamp, please.","translations":{"es":"Apaga la lámpara, por favor."}},{"phrase":"La vue de la terrasse est magnifique.","translation":"The view from the terrace is magnificent.","translations":{"es":"La vista desde la terraza es magnífica."}},{"phrase":"Garde le fromage au réfrigérateur.","translation":"Keep the cheese in the fridge.","translations":{"es":"Guarda el queso en el refrigerador."}},{"phrase":"La salle de bains est à droite.","translation":"The bathroom is on the right.","translations":{"es":"El baño está a la derecha."}},{"phrase":"L''interrupteur est près de la cheminée.","translation":"The light switch is near the fireplace.","translations":{"es":"El interruptor está cerca de la chimenea."}},{"phrase":"Si tu descends, tu trouveras le sous-sol.","translation":"If you go down, you''ll find the basement.","translations":{"es":"Si bajas, encontrarás el sótano."}},{"phrase":"Ton médicament se trouve sur la table de nuit.","translation":"Your medicine is on the bedside table.","translations":{"es":"Tu medicamento está en la mesita de noche."}},{"phrase":"Mets cette casserole dans l''évier.","translation":"Put this pan in the sink.","translations":{"es":"Pon esta cacerola en el fregadero."}},{"phrase":"Baisse le volume, la musique est trop forte !","translation":"Turn down the volume, the music is too loud!","translations":{"es":"¡Baja el volumen, la música está demasiado alta!"}},{"phrase":"Mets ta chemise dans le sèche-linge : elle sera sèche dans un moment.","translation":"Put your shirt in the dryer: it''ll be dry in a moment.","translations":{"es":"Mete tu camisa en la secadora: estará seca en un momento."}},{"phrase":"Qui a si bien nettoyé le four ? — C''est ma mère qui l''a fait.","translation":"Who cleaned the oven so well? — My mother did.","translations":{"es":"¿Quién ha limpiado tan bien el horno? — Lo ha hecho mi madre."}},{"phrase":"Tu vas prendre une douche ? — Non, je prendrai un bain.","translation":"Are you going to take a shower? — No, I will take a bath.","translations":{"es":"¿Te vas a duchar? — No, me daré un baño."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Where do you keep ice cream?","options":["dans le four","dans le tiroir","dans le congélateur","dans l''évier"],"correct":2,"explanation":"Le congélateur keeps things frozen.","translations":{"es":{"question":"¿Dónde guardas el helado?","explanation":"Le congélateur mantiene las cosas congeladas."}}},{"id":"2","question":"What is \"le grenier\"?","options":["the attic","the hallway","the basement","the garage"],"correct":0,"explanation":"The basement is \"le sous-sol\".","translations":{"es":{"question":"¿Qué es «le grenier»?","explanation":"El sótano es «le sous-sol».","options":["el desván","el pasillo","el sótano","el garaje"]}}},{"id":"3","question":"Put the pronoun in the right place: \"Put it in the drawer!\"","options":["Mets-le dans le tiroir !","Mets dans le tiroir le !","Le mets dans le tiroir !","Mets le dans le tiroir !"],"correct":0,"explanation":"Affirmative imperative: verb + hyphen + pronoun.","translations":{"es":{"question":"Coloca bien el pronombre: «¡Ponlo en el cajón!»","explanation":"Imperativo afirmativo: verbo + guion + pronombre."}}},{"id":"4","question":"Complete: \"Si tu descends, tu ___ le sous-sol.\"","options":["as trouvé","trouveras","trouverais","trouvais"],"correct":1,"explanation":"Si + present → future.","translations":{"es":{"question":"Completa: «Si tu descends, tu ___ le sous-sol.»","explanation":"Si + presente → futuro."}}},{"id":"5","question":"How do you say \"I miss you\" in French?","options":["Tu me manques.","Tu manques à toi.","Je te manque.","Je manque toi."],"correct":0,"explanation":"The person you miss is the subject: \"Tu me manques\".","translations":{"es":{"question":"¿Cómo se dice «Te echo de menos» en francés?","explanation":"La persona a la que echas de menos es el sujeto: «Tu me manques»."}}},{"id":"6","question":"Which sentence describes a past situation (imparfait)?","options":["Il n''y avait pas de place pour tout le monde.","Nous avons déménagé en mai.","J''ai ouvert la fenêtre.","Ma mère a choisi la chambre."],"correct":0,"explanation":"Imparfait = background or ongoing situation; passé composé = a specific event.","translations":{"es":{"question":"¿Qué frase describe una situación pasada (imperfecto)?","explanation":"Imperfecto = situación de fondo; passé composé = un hecho puntual."}}},{"id":"7","question":"\"Le rez-de-chaussée\" is…","options":["the first floor up","the ground floor","the garden","the roof"],"correct":1,"explanation":"Floors above are \"le premier étage\", \"le deuxième étage\"…","translations":{"es":{"question":"«Le rez-de-chaussée» es…","explanation":"Las plantas de arriba son «le premier étage», «le deuxième étage»…","options":["el primer piso","la planta baja","el jardín","el tejado"]}}},{"id":"8","question":"Where do you wash the dishes?","options":["dans l''évier","dans le lavabo","dans la douche","dans la baignoire"],"correct":0,"explanation":"L''évier is in the kitchen; le lavabo is in the bathroom.","translations":{"es":{"question":"¿Dónde friegas los platos?","explanation":"L''évier está en la cocina; le lavabo, en el baño."}}}]}'::jsonb, 3),
  ('story', 'Lettre à Inès', '{"text":"Chère Inès, je t''écris pour te parler de notre nouvelle maison. Nous avons déménagé à Annecy le mois dernier, dans un quartier très calme près du lac. Comment ça va à Grenoble ? Vous me manquez beaucoup ! Laisse-moi tout te raconter. Au rez-de-chaussée, il y a un grand salon avec une cheminée, la cuisine, la salle à manger et un garage. Les murs du salon sont peints en vert clair. Derrière la maison, il y a un jardin dont ma mère est tombée amoureuse tout de suite, avec des pommiers et beaucoup de fleurs. À l''étage se trouve la chambre de mes parents, avec une salle de bains et un petit balcon. Mon frère a choisi la chambre la plus grande, mais elle n''a pas de vue. Moi, j''ai une petite chambre sous le toit, avec une fenêtre qui donne sur les montagnes. Tu te souviens de nos fêtes dans l''ancien appartement ? On ne pouvait pas inviter plus de dix personnes, parce qu''il n''y avait pas de place. Maintenant, ce ne sera plus un problème ! Si tu viens cet été, tu dormiras dans la chambre d''amis. J''attends ta visite avec impatience. Bises, Margaux.","translation":"Dear Inès, I''m writing to tell you about our new house. We moved to Annecy last month, to a very quiet neighborhood near the lake. How are things in Grenoble? I miss you all a lot! Let me tell you everything. On the ground floor, there is a large living room with a fireplace, the kitchen, the dining room and a garage. The living room walls are painted light green. Behind the house, there is a garden my mother fell in love with right away, with apple trees and lots of flowers. Upstairs is my parents'' bedroom, with a bathroom and a small balcony. My brother chose the biggest bedroom, but it has no view. As for me, I have a small room under the roof, with a window that looks out on the mountains. Do you remember our parties in the old apartment? We couldn''t invite more than ten people, because there wasn''t enough room. Now it won''t be a problem anymore! If you come this summer, you''ll sleep in the guest room. I can''t wait for your visit. Love, Margaux.","translations":{"es":"Querida Inès: te escribo para hablarte de nuestra nueva casa. Nos mudamos a Annecy el mes pasado, a un barrio muy tranquilo cerca del lago. ¿Qué tal todo en Grenoble? ¡Los extraño mucho! Déjame que te lo cuente todo. En la planta baja hay un salón grande con chimenea, la cocina, el comedor y un garaje. Las paredes del salón están pintadas de verde claro. Detrás de la casa hay un jardín del que mi madre se enamoró enseguida, con manzanos y muchas flores. Arriba está el dormitorio de mis padres, con un baño y un pequeño balcón. Mi hermano eligió el dormitorio más grande, pero no tiene vistas. Yo tengo una habitación pequeña bajo el tejado, con una ventana que da a las montañas. ¿Te acuerdas de nuestras fiestas en el antiguo piso? No podíamos invitar a más de diez personas porque no había sitio. ¡Ahora ya no será un problema! Si vienes este verano, dormirás en la habitación de invitados. Espero tu visita con impaciencia. Besos, Margaux."},"highlighted_words":["Nous avons déménagé","Vous me manquez","rez-de-chaussée","cheminée","dont","se trouve","balcon","toit","On ne pouvait pas","il n''y avait pas","Si tu viens","dormiras"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Ouvre","les","rideaux"],"translation":"Open the curtains","translations":{"es":"Abre las cortinas"}},{"words":["Le","chat","est","sous","le","lit"],"translation":"The cat is under the bed","translations":{"es":"El gato está debajo de la cama"}},{"words":["Mets-le","dans","le","tiroir"],"translation":"Put it in the drawer","translations":{"es":"Ponlo en el cajón"}},{"words":["Tu","me","manques","beaucoup"],"translation":"I miss you a lot","translations":{"es":"Te echo mucho de menos"}},{"words":["La","salle","de","bains","est","à","droite"],"translation":"The bathroom is on the right","translations":{"es":"El baño está a la derecha"}},{"words":["Si","tu","viens","tu","dormiras","ici"],"translation":"If you come you''ll sleep here","translations":{"es":"Si vienes, dormirás aquí"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Close the door","translations":{"es":"Cierra la puerta"},"answer":"Ferme la porte"},{"prompt":"The cake is in the oven","translations":{"es":"El pastel está en el horno"},"answer":"Le gâteau est dans le four"},{"prompt":"Sit in the armchair","translations":{"es":"Siéntate en el sillón"},"answer":"Assieds-toi dans le fauteuil"},{"prompt":"We have moved","translations":{"es":"Nos hemos mudado"},"answer":"Nous avons déménagé"},{"prompt":"The floor is dirty","translations":{"es":"El suelo está sucio"},"answer":"Le sol est sale"},{"prompt":"Turn off the light","translations":{"es":"Apaga la luz"},"answer":"Éteins la lumière"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 14: Les animaux
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-14', 'Les animaux', '🦊', 'Los animales', 14, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"une fourmi","translation":"an ant","translations":{"es":"una hormiga"}},{"id":"2","word":"une abeille","translation":"a bee","translations":{"es":"una abeja"}},{"id":"3","word":"une araignée","translation":"a spider","translations":{"es":"una araña"}},{"id":"4","word":"un papillon","translation":"a butterfly","translations":{"es":"una mariposa"}},{"id":"5","word":"une mouche","translation":"a fly","translations":{"es":"una mosca"}},{"id":"6","word":"une coccinelle","translation":"a ladybug","translations":{"es":"una mariquita"}},{"id":"7","word":"un escargot","translation":"a snail","translations":{"es":"un caracol"}},{"id":"8","word":"un oiseau","translation":"a bird","translations":{"es":"un pájaro"}},{"id":"9","word":"un aigle","translation":"an eagle","translations":{"es":"un águila"}},{"id":"10","word":"une chouette","translation":"an owl","translations":{"es":"una lechuza"}},{"id":"11","word":"un perroquet","translation":"a parrot","translations":{"es":"un loro"}},{"id":"12","word":"un canard","translation":"a duck","translations":{"es":"un pato"}},{"id":"13","word":"une poule","translation":"a hen","translations":{"es":"una gallina"}},{"id":"14","word":"un coq","translation":"a rooster","translations":{"es":"un gallo"}},{"id":"15","word":"un poussin","translation":"a chick","translations":{"es":"un pollito"}},{"id":"16","word":"une vache","translation":"a cow","translations":{"es":"una vaca"}},{"id":"17","word":"un veau","translation":"a calf","translations":{"es":"un ternero"}},{"id":"18","word":"un taureau","translation":"a bull","translations":{"es":"un toro"}},{"id":"19","word":"un cheval","translation":"a horse","translations":{"es":"un caballo"}},{"id":"20","word":"un âne","translation":"a donkey","translations":{"es":"un burro"}},{"id":"21","word":"un cochon","translation":"a pig","translations":{"es":"un cerdo"}},{"id":"22","word":"un mouton","translation":"a sheep","translations":{"es":"una oveja"}},{"id":"23","word":"une chèvre","translation":"a goat","translations":{"es":"una cabra"}},{"id":"24","word":"un lapin","translation":"a rabbit","translations":{"es":"un conejo"}},{"id":"25","word":"un chat / un chaton","translation":"a cat / a kitten","translations":{"es":"un gato / un gatito"}},{"id":"26","word":"un chien / un chiot","translation":"a dog / a puppy","translations":{"es":"un perro / un cachorro"}},{"id":"27","word":"une souris","translation":"a mouse","translations":{"es":"un ratón"}},{"id":"28","word":"un écureuil","translation":"a squirrel","translations":{"es":"una ardilla"}},{"id":"29","word":"un renard","translation":"a fox","translations":{"es":"un zorro"}},{"id":"30","word":"un loup","translation":"a wolf","translations":{"es":"un lobo"}},{"id":"31","word":"un ours","translation":"a bear","translations":{"es":"un oso"}},{"id":"32","word":"un cerf","translation":"a deer","translations":{"es":"un ciervo"}},{"id":"33","word":"un singe","translation":"a monkey","translations":{"es":"un mono"}},{"id":"34","word":"un lion","translation":"a lion","translations":{"es":"un león"}},{"id":"35","word":"un tigre","translation":"a tiger","translations":{"es":"un tigre"}},{"id":"36","word":"un éléphant","translation":"an elephant","translations":{"es":"un elefante"}},{"id":"37","word":"une girafe","translation":"a giraffe","translations":{"es":"una jirafa"}},{"id":"38","word":"un zèbre","translation":"a zebra","translations":{"es":"una cebra"}},{"id":"39","word":"un chameau","translation":"a camel","translations":{"es":"un camello"}},{"id":"40","word":"un serpent","translation":"a snake","translations":{"es":"una serpiente"}},{"id":"41","word":"une tortue","translation":"a turtle","translations":{"es":"una tortuga"}},{"id":"42","word":"un crocodile","translation":"a crocodile","translations":{"es":"un cocodrilo"}},{"id":"43","word":"un poisson","translation":"a fish","translations":{"es":"un pez"}},{"id":"44","word":"un dauphin","translation":"a dolphin","translations":{"es":"un delfín"}},{"id":"45","word":"une baleine","translation":"a whale","translations":{"es":"una ballena"}},{"id":"46","word":"un requin","translation":"a shark","translations":{"es":"un tiburón"}},{"id":"47","word":"un phoque","translation":"a seal","translations":{"es":"una foca"}},{"id":"48","word":"une chauve-souris","translation":"a bat","translations":{"es":"un murciélago"}},{"id":"49","word":"un mammifère","translation":"a mammal","translations":{"es":"un mamífero"}}],"grammar":[{"structure":"pluriels irréguliers","example":"un cheval → des chevaux, un oiseau → des oiseaux","en":"Irregular plurals","es":"Plurales irregulares"},{"structure":"superlatif","example":"La baleine est l''animal le plus grand du monde.","en":"Superlatives","es":"Superlativos"},{"structure":"voix passive","example":"Beaucoup de baleines ont été tuées. / Les tigres sont chassés.","en":"Passive voice (present and past)","es":"Voz pasiva (presente y pasado)"},{"structure":"il faut / on devrait + infinitif","example":"Il faut respecter les animaux. / Tout cela devrait finir.","en":"Necessity and advice","es":"Necesidad y consejo"},{"structure":"ressembler à / être comme","example":"Tu ressembles à un singe ! / Tu es comme un singe.","en":"Comparisons with animals","es":"Comparaciones con animales"},{"structure":"imparfait","example":"Quand j''étais petit, j''avais un poney.","en":"Imperfect (past situation)","es":"Imperfecto (situación pasada)"},{"structure":"passé composé","example":"Le crapaud a mangé la mouche.","en":"Past tense","es":"Pretérito perfecto"}],"tips":[{"en":"Nouns in -al usually make -aux in the plural: un animal → des animaux, un cheval → des chevaux.","es":"Los sustantivos en -al suelen hacer el plural en -aux: un animal → des animaux, un cheval → des chevaux."},{"en":"Many animals have one gender for both sexes: \"une girafe\", \"un éléphant\", \"une souris\".","es":"Muchos animales tienen un solo género para ambos sexos: «une girafe», «un éléphant», «une souris»."},{"en":"Animal idioms: \"avoir une faim de loup\" (to be starving), \"être malin comme un singe\" (very clever), \"poser un lapin\" (to stand someone up).","es":"Expresiones: «avoir une faim de loup» (tener un hambre feroz), «être malin comme un singe» (ser muy listo), «poser un lapin» (dar plantón)."},{"en":"\"Faire du cheval\" = to ride a horse.","es":"«Faire du cheval» = montar a caballo."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Les girafes ont un long cou.","translation":"Giraffes have a long neck.","translations":{"es":"Las jirafas tienen el cuello largo."}},{"phrase":"Les dauphins sont intelligents.","translation":"Dolphins are intelligent.","translations":{"es":"Los delfines son inteligentes."}},{"phrase":"Les chats sont silencieux et rapides.","translation":"Cats are silent and fast.","translations":{"es":"Los gatos son silenciosos y rápidos."}},{"phrase":"Les lamas viennent des Andes.","translation":"Llamas come from the Andes.","translations":{"es":"Las llamas vienen de los Andes."}},{"phrase":"Tu ne peux pas rester tranquille ? Tu es comme un singe !","translation":"Can''t you keep still? You''re like a monkey!","translations":{"es":"¿No puedes estarte quieto? ¡Pareces un mono!"}},{"phrase":"Il y a une souris dans la cuisine !","translation":"There''s a mouse in the kitchen!","translations":{"es":"¡Hay un ratón en la cocina!"}},{"phrase":"Les chauves-souris ont leur propre radar.","translation":"Bats have their own radar.","translations":{"es":"Los murciélagos tienen su propio radar."}},{"phrase":"Les tigres, comme les lions, sont des animaux sauvages.","translation":"Tigers, like lions, are wild animals.","translations":{"es":"Los tigres, como los leones, son animales salvajes."}},{"phrase":"La laine vient des moutons.","translation":"Wool comes from sheep.","translations":{"es":"La lana viene de las ovejas."}},{"phrase":"Quand j''étais petite, j''avais un poney.","translation":"When I was little, I had a pony.","translations":{"es":"Cuando era pequeña, tenía un poni."}},{"phrase":"Les koalas sont une espèce menacée.","translation":"Koalas are an endangered species.","translations":{"es":"Los koalas son una especie amenazada."}},{"phrase":"La baleine bleue est l''animal le plus grand du monde.","translation":"The blue whale is the largest animal in the world.","translations":{"es":"La ballena azul es el animal más grande del mundo."}},{"phrase":"Tu sais faire du cheval ? — Oui, mais je dois encore pratiquer.","translation":"Can you ride a horse? — Yes, but I still need to practice.","translations":{"es":"¿Sabes montar a caballo? — Sí, pero todavía tengo que practicar."}},{"phrase":"Les loups hurlent les nuits de pleine lune.","translation":"Wolves howl on full-moon nights.","translations":{"es":"Los lobos aúllan las noches de luna llena."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"What is the plural of \"cheval\"?","options":["chevales","chevaux","chevals","chevaus"],"correct":1,"explanation":"-al → -aux.","translations":{"es":{"question":"¿Cuál es el plural de «cheval»?","explanation":"-al → -aux."}}},{"id":"2","question":"Which is the largest animal in the world?","options":["la baleine bleue","la girafe","l''éléphant","le requin"],"correct":0,"explanation":"The blue whale is larger than any dinosaur.","translations":{"es":{"question":"¿Cuál es el animal más grande del mundo?","explanation":"La ballena azul es más grande que cualquier dinosaurio."}}},{"id":"3","question":"Passive voice: \"Hunters kill tigers\" → ?","options":["Les tigres sont tués par les chasseurs.","Les tigres ont tué les chasseurs.","Les tigres tuent les chasseurs.","Les chasseurs sont tués par les tigres."],"correct":0,"explanation":"Passive: être + past participle + par.","translations":{"es":{"question":"Voz pasiva: «Los cazadores matan tigres» → ?","explanation":"Pasiva: être + participio + par."}}},{"id":"4","question":"What does \"faire du cheval\" mean?","options":["to make a horse","to ride a horse","to feed a horse","to buy a horse"],"correct":1,"explanation":"Faire du + sport/activity: faire du vélo, faire du ski.","translations":{"es":{"question":"¿Qué significa «faire du cheval»?","explanation":"Faire du + deporte o actividad: faire du vélo, faire du ski.","options":["hacer un caballo","montar a caballo","dar de comer a un caballo","comprar un caballo"]}}},{"id":"5","question":"Which animal is a mammal?","options":["le dauphin","le requin","le crocodile","l''aigle"],"correct":0,"explanation":"Dolphins and whales are mammals, not fish.","translations":{"es":{"question":"¿Qué animal es un mamífero?","explanation":"Los delfines y las ballenas son mamíferos, no peces."}}},{"id":"6","question":"\"J''ai une faim de loup.\" What does it mean?","options":["I''m starving.","I''m afraid of wolves.","I want to eat a wolf.","I''m not hungry."],"correct":0,"explanation":"Literally \"a wolf''s hunger\".","translations":{"es":{"question":"«J''ai une faim de loup.» ¿Qué significa?","explanation":"Literalmente «un hambre de lobo».","options":["Tengo un hambre feroz.","Tengo miedo de los lobos.","Quiero comerme un lobo.","No tengo hambre."]}}},{"id":"7","question":"Complete: \"Quand j''étais petit, j''___ un chien.\"","options":["ai eu","avais","aurai","aurais"],"correct":1,"explanation":"Imparfait for a past situation that lasted.","translations":{"es":{"question":"Completa: «Quand j''étais petit, j''___ un chien.»","explanation":"Imperfecto para una situación pasada que duraba."}}},{"id":"8","question":"Which baby animal is \"un chiot\"?","options":["a chick","a kitten","a puppy","a calf"],"correct":2,"explanation":"Chaton = kitten, poussin = chick, veau = calf.","translations":{"es":{"question":"¿Qué cría es «un chiot»?","explanation":"Chaton = gatito, poussin = pollito, veau = ternero.","options":["un pollito","un gatito","un cachorro","un ternero"]}}}]}'::jsonb, 3),
  ('story', 'Une journée au refuge', '{"text":"Samedi dernier, Hugo a passé la journée comme bénévole dans un refuge pour animaux sauvages, près de Toulouse. Le directeur lui a expliqué que beaucoup d''animaux sont blessés par les voitures ou trouvés dans des pièges. Le matin, Hugo a nourri un jeune renard et deux écureuils. « Ce renard a été sauvé il y a un mois. Il était très maigre », a dit la vétérinaire. L''après-midi, ils ont soigné une chouette qui ne pouvait plus voler, puis ils ont libéré un hérisson dans la forêt. « Quand j''étais enfant, je pensais que les animaux sauvages étaient dangereux », raconte Hugo. « Maintenant, je sais qu''ils ont plus peur de nous que nous d''eux. » Avant de partir, il a vu une tortue qui ressemblait à une petite pierre. Selon le directeur, il faut respecter la place de chaque animal sur la Terre, car nous faisons tous partie de la même chaîne. Hugo reviendra samedi prochain, c''est sûr !","translation":"Last Saturday, Hugo spent the day as a volunteer at a wildlife shelter near Toulouse. The director explained to him that many animals are injured by cars or found in traps. In the morning, Hugo fed a young fox and two squirrels. “This fox was rescued a month ago. It was very thin,” said the vet. In the afternoon, they treated an owl that couldn''t fly anymore, then they released a hedgehog into the forest. “When I was a child, I thought wild animals were dangerous,” Hugo says. “Now I know they are more afraid of us than we are of them.” Before leaving, he saw a turtle that looked like a little stone. According to the director, we must respect every animal''s place on Earth, because we are all part of the same chain. Hugo will come back next Saturday, that''s for sure!","translations":{"es":"El sábado pasado, Hugo pasó el día como voluntario en un refugio de fauna salvaje cerca de Toulouse. El director le explicó que muchos animales son heridos por los coches o encontrados en trampas. Por la mañana, Hugo dio de comer a un zorro joven y a dos ardillas. «Este zorro fue rescatado hace un mes. Estaba muy flaco», dijo la veterinaria. Por la tarde curaron a una lechuza que ya no podía volar y luego soltaron a un erizo en el bosque. «Cuando era niño, pensaba que los animales salvajes eran peligrosos», cuenta Hugo. «Ahora sé que nos tienen más miedo ellos a nosotros que nosotros a ellos.» Antes de irse, vio una tortuga que parecía una piedrecita. Según el director, hay que respetar el lugar de cada animal en la Tierra, porque todos formamos parte de la misma cadena. ¡Hugo volverá el sábado que viene, seguro!"},"highlighted_words":["sont blessés","trouvés","renard","écureuils","a été sauvé","chouette","Quand j''étais enfant","tortue","ressemblait à","il faut respecter"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Les","girafes","ont","un","long","cou"],"translation":"Giraffes have a long neck","translations":{"es":"Las jirafas tienen el cuello largo"}},{"words":["Il","y","a","une","souris","dans","la","cuisine"],"translation":"There''s a mouse in the kitchen","translations":{"es":"Hay un ratón en la cocina"}},{"words":["Les","chevaux","courent","très","vite"],"translation":"Horses run very fast","translations":{"es":"Los caballos corren muy rápido"}},{"words":["Ce","renard","a","été","sauvé"],"translation":"This fox was rescued","translations":{"es":"Este zorro fue rescatado"}},{"words":["Il","faut","respecter","les","animaux"],"translation":"We must respect animals","translations":{"es":"Hay que respetar a los animales"}},{"words":["Quand","j''étais","petit","j''avais","un","chat"],"translation":"When I was little I had a cat","translations":{"es":"Cuando era pequeño tenía un gato"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Do you have a pet?","translations":{"es":"¿Tienes una mascota?"},"answer":"As-tu un animal ?"},{"prompt":"I have two dogs","translations":{"es":"Tengo dos perros"},"answer":"J''ai deux chiens"},{"prompt":"Dolphins are intelligent","translations":{"es":"Los delfines son inteligentes"},"answer":"Les dauphins sont intelligents"},{"prompt":"The lion is a wild animal","translations":{"es":"El león es un animal salvaje"},"answer":"Le lion est un animal sauvage"},{"prompt":"I''m starving","translations":{"es":"Tengo un hambre feroz"},"answer":"J''ai une faim de loup"},{"prompt":"The birds are singing","translations":{"es":"Los pájaros cantan"},"answer":"Les oiseaux chantent"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 15: Les aliments et les boissons
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-15', 'Les aliments et les boissons', '🥖', 'Los alimentos y las bebidas', 15, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le petit déjeuner","translation":"breakfast","translations":{"es":"el desayuno"}},{"id":"2","word":"le déjeuner","translation":"lunch","translations":{"es":"el almuerzo"}},{"id":"3","word":"le dîner","translation":"dinner","translations":{"es":"la cena"}},{"id":"4","word":"le dessert","translation":"dessert","translations":{"es":"el postre"}},{"id":"5","word":"le pain","translation":"bread","translations":{"es":"el pan"}},{"id":"6","word":"la baguette","translation":"the baguette","translations":{"es":"la baguette / la barra de pan"}},{"id":"7","word":"le beurre","translation":"butter","translations":{"es":"la mantequilla"}},{"id":"8","word":"le fromage","translation":"cheese","translations":{"es":"el queso"}},{"id":"9","word":"le jambon","translation":"ham","translations":{"es":"el jamón"}},{"id":"10","word":"les lardons","translation":"bacon bits","translations":{"es":"los taquitos de beicon"}},{"id":"11","word":"les œufs","translation":"eggs","translations":{"es":"los huevos"}},{"id":"12","word":"l''omelette","translation":"the omelet","translations":{"es":"la tortilla francesa"}},{"id":"13","word":"la crêpe","translation":"the crepe","translations":{"es":"la crepe"}},{"id":"14","word":"le riz","translation":"rice","translations":{"es":"el arroz"}},{"id":"15","word":"la soupe","translation":"soup","translations":{"es":"la sopa"}},{"id":"16","word":"la salade","translation":"salad / lettuce","translations":{"es":"la ensalada / la lechuga"}},{"id":"17","word":"le bœuf","translation":"beef","translations":{"es":"la carne de res"}},{"id":"18","word":"le porc","translation":"pork","translations":{"es":"el cerdo"}},{"id":"19","word":"l''agneau","translation":"lamb","translations":{"es":"el cordero"}},{"id":"20","word":"le poulet","translation":"chicken","translations":{"es":"el pollo"}},{"id":"21","word":"le canard","translation":"duck","translations":{"es":"el pato"}},{"id":"22","word":"la saucisse","translation":"sausage","translations":{"es":"la salchicha"}},{"id":"23","word":"le steak","translation":"steak","translations":{"es":"el filete"}},{"id":"24","word":"le gâteau","translation":"cake","translations":{"es":"el pastel"}},{"id":"25","word":"la tarte aux pommes","translation":"apple pie","translations":{"es":"la tarta de manzana"}},{"id":"26","word":"la glace","translation":"ice cream","translations":{"es":"el helado"}},{"id":"27","word":"le yaourt","translation":"yogurt","translations":{"es":"el yogur"}},{"id":"28","word":"le biscuit","translation":"cookie","translations":{"es":"la galleta"}},{"id":"29","word":"le sel","translation":"salt","translations":{"es":"la sal"}},{"id":"30","word":"le poivre","translation":"pepper","translations":{"es":"la pimienta"}},{"id":"31","word":"l''huile","translation":"oil","translations":{"es":"el aceite"}},{"id":"32","word":"le vinaigre","translation":"vinegar","translations":{"es":"el vinagre"}},{"id":"33","word":"la moutarde","translation":"mustard","translations":{"es":"la mostaza"}},{"id":"34","word":"le sucre","translation":"sugar","translations":{"es":"el azúcar"}},{"id":"35","word":"l''eau minérale","translation":"mineral water","translations":{"es":"el agua mineral"}},{"id":"36","word":"le jus d''orange","translation":"orange juice","translations":{"es":"el jugo de naranja"}},{"id":"37","word":"le lait","translation":"milk","translations":{"es":"la leche"}},{"id":"38","word":"le café","translation":"coffee","translations":{"es":"el café"}},{"id":"39","word":"le thé","translation":"tea","translations":{"es":"el té"}},{"id":"40","word":"la bière","translation":"beer","translations":{"es":"la cerveza"}},{"id":"41","word":"le vin","translation":"wine","translations":{"es":"el vino"}},{"id":"42","word":"le cidre","translation":"cider","translations":{"es":"la sidra"}},{"id":"43","word":"la fourchette","translation":"fork","translations":{"es":"el tenedor"}},{"id":"44","word":"le couteau","translation":"knife","translations":{"es":"el cuchillo"}},{"id":"45","word":"la cuillère","translation":"spoon","translations":{"es":"la cuchara"}},{"id":"46","word":"l''assiette","translation":"plate","translations":{"es":"el plato"}},{"id":"47","word":"le verre","translation":"glass","translations":{"es":"el vaso"}},{"id":"48","word":"la tasse","translation":"cup","translations":{"es":"la taza"}},{"id":"49","word":"la serviette","translation":"napkin","translations":{"es":"la servilleta"}},{"id":"50","word":"la nappe","translation":"tablecloth","translations":{"es":"el mantel"}},{"id":"51","word":"le plateau","translation":"tray","translations":{"es":"la bandeja"}},{"id":"52","word":"chaud / froid / tiède","translation":"hot / cold / lukewarm","translations":{"es":"caliente / frío / tibio"}}],"grammar":[{"structure":"articles partitifs","example":"du pain, de la crème, des œufs","en":"Partitive articles (some)","es":"Artículos partitivos"},{"structure":"négation + de","example":"Il n''y a plus de sel. / Je ne veux pas de dessert.","en":"\"de\" after a negation","es":"«de» después de la negación"},{"structure":"ne … que","example":"Elle ne boit que de l''eau.","en":"Restriction: \"only\"","es":"Restricción: «solo»"},{"structure":"impératif + pronoms","example":"Passe-moi le sel. / Donne-lui du jus. / Offre-les aux invités.","en":"Imperative with pronouns","es":"Imperativo con pronombres"},{"structure":"conditionnel de politesse","example":"Je voudrais un verre de vin. / Je préférerais un jus.","en":"Polite conditional","es":"Condicional de cortesía"},{"structure":"venir de + infinitif","example":"Ces croissants viennent de sortir du four.","en":"Recent past","es":"Pasado reciente"},{"structure":"ne cesser de + infinitif","example":"Le médecin ne cesse de me répéter que je dois faire un régime.","en":"\"to keep doing\"","es":"«no dejar de»"},{"structure":"en train de","example":"La glace est en train de fondre.","en":"Action in progress","es":"Acción en curso"}],"tips":[{"en":"Partitives: du (masc.), de la (fem.), de l'' (vowel), des (plural). After a negation they become \"de\": \"pas de pain\".","es":"Partitivos: du (masc.), de la (fem.), de l'' (vocal), des (plural). Tras una negación pasan a «de»: «pas de pain»."},{"en":"Meals: le petit déjeuner (breakfast), le déjeuner (lunch), le goûter (afternoon snack), le dîner (dinner).","es":"Comidas: le petit déjeuner (desayuno), le déjeuner (almuerzo), le goûter (merienda), le dîner (cena)."},{"en":"\"Mettre la table\" = to set the table; \"débarrasser la table\" = to clear it.","es":"«Mettre la table» = poner la mesa; «débarrasser la table» = quitarla."},{"en":"\"Être au régime\" = to be on a diet; \"végétarien(ne)\" = vegetarian.","es":"«Être au régime» = estar a dieta; «végétarien(ne)» = vegetariano/a."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"J''aime bien un bon déjeuner et un dîner léger.","translation":"I like a good lunch and a light dinner.","translations":{"es":"Me gusta un buen almuerzo y una cena ligera."}},{"phrase":"Je veux du pain avec du beurre.","translation":"I want some bread with butter.","translations":{"es":"Quiero pan con mantequilla."}},{"phrase":"La bière est faite avec de l''orge.","translation":"Beer is made from barley.","translations":{"es":"La cerveza se hace con cebada."}},{"phrase":"Je voudrais un verre de vin rouge, s''il vous plaît.","translation":"I would like a glass of red wine, please.","translations":{"es":"Quisiera una copa de vino tinto, por favor."}},{"phrase":"Mets la nappe sur la table.","translation":"Put the tablecloth on the table.","translations":{"es":"Pon el mantel en la mesa."}},{"phrase":"Cette soupe est froide !","translation":"This soup is cold!","translations":{"es":"¡Esta sopa está fría!"}},{"phrase":"Dépêche-toi, la glace est en train de fondre !","translation":"Hurry up, the ice cream is melting!","translations":{"es":"¡Date prisa, el helado se está derritiendo!"}},{"phrase":"Mélangez l''huile, le vinaigre, le sel, le poivre et la moutarde pour faire une vinaigrette.","translation":"Mix the oil, vinegar, salt, pepper and mustard to make a vinaigrette.","translations":{"es":"Mezcle el aceite, el vinagre, la sal, la pimienta y la mostaza para hacer una vinagreta."}},{"phrase":"Je ne bois que de l''eau minérale.","translation":"I only drink mineral water.","translations":{"es":"Solo bebo agua mineral."}},{"phrase":"Tu peux me passer le sel, s''il te plaît ? — Il n''y a plus de sel !","translation":"Can you pass me the salt, please? — There''s no more salt!","translations":{"es":"¿Me pasas la sal, por favor? — ¡Ya no queda sal!"}},{"phrase":"Mets les crêpes sur une assiette et offre-les aux invités.","translation":"Put the crepes on a plate and offer them to the guests.","translations":{"es":"Pon las crepes en un plato y ofréceselas a los invitados."}},{"phrase":"Tu veux de la crème dans ton café ? — Non merci, ça va comme ça.","translation":"Do you want cream in your coffee? — No thanks, it''s fine like that.","translations":{"es":"¿Quieres nata en el café? — No, gracias, así está bien."}},{"phrase":"Un apéritif avant le déjeuner ? — Je préférerais un jus de fruits.","translation":"An aperitif before lunch? — I would prefer a fruit juice.","translations":{"es":"¿Un aperitivo antes del almuerzo? — Preferiría un jugo de frutas."}},{"phrase":"Le chocolat est trop chaud ? — Non, il est tiède.","translation":"Is the hot chocolate too hot? — No, it''s lukewarm.","translations":{"es":"¿El chocolate está demasiado caliente? — No, está tibio."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Je voudrais ___ eau, s''il vous plaît.\"","options":["de la","de l''","des","du"],"correct":1,"explanation":"Before a vowel: de l''.","translations":{"es":{"question":"Completa: «Je voudrais ___ eau, s''il vous plaît.»","explanation":"Delante de vocal: de l''."}}},{"id":"2","question":"Complete: \"Je ne mange pas ___ viande.\"","options":["de","la","du","de la"],"correct":0,"explanation":"After a negation, partitives become \"de\".","translations":{"es":{"question":"Completa: «Je ne mange pas ___ viande.»","explanation":"Tras una negación, los partitivos se convierten en «de»."}}},{"id":"3","question":"\"Elle ne boit que du thé.\" What does it mean?","options":["She only drinks tea.","She never drinks tea.","She drinks a lot of tea.","She doesn''t drink tea."],"correct":0,"explanation":"\"Ne … que\" = only.","translations":{"es":{"question":"«Elle ne boit que du thé.» ¿Qué significa?","explanation":"«Ne … que» = solo.","options":["Solo bebe té.","Nunca bebe té.","Bebe mucho té.","No bebe té."]}}},{"id":"4","question":"How do you ask someone to pass you the bread (tu)?","options":["Tu me passe le pain.","Passe-moi le pain, s''il te plaît.","Passe le pain moi, s''il te plaît.","Me passe le pain, s''il te plaît."],"correct":1,"explanation":"Imperative + hyphen + moi.","translations":{"es":{"question":"¿Cómo pides a alguien que te pase el pan (tu)?","explanation":"Imperativo + guion + moi."}}},{"id":"5","question":"Which meal is \"le déjeuner\" in France?","options":["lunch","snack","dinner","breakfast"],"correct":0,"explanation":"Breakfast = le petit déjeuner.","translations":{"es":{"question":"¿Qué comida es «le déjeuner» en Francia?","explanation":"El desayuno = le petit déjeuner.","options":["el almuerzo","la merienda","la cena","el desayuno"]}}},{"id":"6","question":"Which one do you use to cut meat?","options":["la serviette","la nappe","le couteau","la cuillère"],"correct":2,"explanation":"Couteau = knife, fourchette = fork, cuillère = spoon.","translations":{"es":{"question":"¿Qué usas para cortar la carne?","explanation":"Couteau = cuchillo, fourchette = tenedor, cuillère = cuchara."}}},{"id":"7","question":"\"Les croissants viennent de sortir du four.\" Meaning?","options":["The croissants are in the oven.","The croissants will go in the oven.","The croissants have just come out of the oven.","The croissants come from the oven."],"correct":2,"explanation":"\"Venir de\" + infinitive = just happened.","translations":{"es":{"question":"«Les croissants viennent de sortir du four.» ¿Significado?","explanation":"«Venir de» + infinitivo = acaba de ocurrir.","options":["Los cruasanes están en el horno.","Los cruasanes irán al horno.","Los cruasanes acaban de salir del horno.","Los cruasanes vienen del horno."]}}},{"id":"8","question":"How do you politely say \"I would prefer a coffee\"?","options":["Je préférerai un café.","Je préférais un café.","Je préférerais un café.","Je préfère café."],"correct":2,"explanation":"Conditional: préférer → je préférerais.","translations":{"es":{"question":"¿Cómo dices con cortesía «Preferiría un café»?","explanation":"Condicional: préférer → je préférerais."}}}]}'::jsonb, 3),
  ('story', 'Le gourmand', '{"text":"Je m''appelle Gaspard Moreau, j''ai cinquante ans et je suis chauffeur de taxi à Lyon. J''adore manger, surtout quand mon mari cuisine. J''aime toutes sortes de viandes : le bœuf, le canard, l''agneau… Rien que d''en parler, j''ai faim ! Au petit déjeuner, je prends généralement deux tartines avec du beurre et de la confiture, un café au lait et un jus d''orange. Si j''ai encore faim, je mange un yaourt avec des fruits. À la pause, mes collègues et moi buvons du café et partageons des croissants qui viennent de sortir du four. À midi, je mange un sandwich au jambon et des frites. Mais mon repas préféré, c''est le dîner. Je rentre vers sept heures, je me lave les mains et je me mets à table. Nous commençons par une soupe, puis il y a de la viande avec des pommes de terre et une salade. Au dessert, mon mari me sert une part de tarte aux pommes. Le problème ? Mon médecin ne cesse de me répéter que je dois manger moins gras. Alors maintenant, le soir, je ne prends que de la salade… enfin, presque !","translation":"My name is Gaspard Moreau, I''m fifty and I''m a taxi driver in Lyon. I love eating, especially when my husband cooks. I like all kinds of meat: beef, duck, lamb… Just talking about it makes me hungry! For breakfast, I usually have two slices of bread with butter and jam, a coffee with milk and an orange juice. If I''m still hungry, I eat a yogurt with fruit. On our break, my colleagues and I drink coffee and share croissants that have just come out of the oven. At noon, I eat a ham sandwich and fries. But my favorite meal is dinner. I get home around seven, wash my hands and sit down at the table. We start with soup, then there''s meat with potatoes and a salad. For dessert, my husband serves me a slice of apple pie. The problem? My doctor keeps telling me I must eat less fat. So now, in the evening, I only have salad… well, almost!","translations":{"es":"Me llamo Gaspard Moreau, tengo cincuenta años y soy taxista en Lyon. Me encanta comer, sobre todo cuando cocina mi marido. Me gustan todo tipo de carnes: la de res, el pato, el cordero… ¡Solo de hablar de ello me entra hambre! En el desayuno suelo tomar dos tostadas con mantequilla y mermelada, un café con leche y un jugo de naranja. Si todavía tengo hambre, me como un yogur con fruta. En el descanso, mis compañeros y yo tomamos café y compartimos cruasanes recién salidos del horno. A mediodía me como un sándwich de jamón y papas fritas. Pero mi comida favorita es la cena. Vuelvo a casa hacia las siete, me lavo las manos y me siento a la mesa. Empezamos con una sopa, luego hay carne con papas y una ensalada. De postre, mi marido me sirve un trozo de tarta de manzana. ¿El problema? Mi médico no deja de repetirme que tengo que comer con menos grasa. Así que ahora, por la noche, solo tomo ensalada… bueno, ¡casi!"},"highlighted_words":["petit déjeuner","du beurre","de la confiture","Si j''ai encore faim","viennent de sortir","À midi","dîner","je me mets à table","ne cesse de","je ne prends que"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","voudrais","du","pain"],"translation":"I would like some bread","translations":{"es":"Quisiera pan"}},{"words":["Il","n''y","a","plus","de","sel"],"translation":"There''s no more salt","translations":{"es":"Ya no queda sal"}},{"words":["Passe-moi","le","sel"],"translation":"Pass me the salt","translations":{"es":"Pásame la sal"}},{"words":["Elle","ne","boit","que","de","l''eau"],"translation":"She only drinks water","translations":{"es":"Solo bebe agua"}},{"words":["La","glace","est","en","train","de","fondre"],"translation":"The ice cream is melting","translations":{"es":"El helado se está derritiendo"}},{"words":["Mets","la","table","s''il","te","plaît"],"translation":"Set the table please","translations":{"es":"Pon la mesa, por favor"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I want some cheese","translations":{"es":"Quiero queso"},"answer":"Je veux du fromage"},{"prompt":"This cake is delicious","translations":{"es":"Este pastel está delicioso"},"answer":"Ce gâteau est délicieux"},{"prompt":"I don''t want any dessert","translations":{"es":"No quiero postre"},"answer":"Je ne veux pas de dessert"},{"prompt":"I am vegetarian (f)","translations":{"es":"Soy vegetariana"},"answer":"Je suis végétarienne"},{"prompt":"I would like a glass of water","translations":{"es":"Quisiera un vaso de agua"},"answer":"Je voudrais un verre d''eau"},{"prompt":"I hate liver","translations":{"es":"Odio el hígado"},"answer":"Je déteste le foie"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 16: Les vêtements
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-16', 'Les vêtements', '👕', 'La ropa', 16, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"un anorak","translation":"a parka","translations":{"es":"un anorak"}},{"id":"2","word":"une veste","translation":"a jacket","translations":{"es":"una chaqueta"}},{"id":"3","word":"un manteau","translation":"a coat","translations":{"es":"un abrigo"}},{"id":"4","word":"un blouson","translation":"a short jacket","translations":{"es":"una cazadora"}},{"id":"5","word":"une chemise","translation":"a shirt","translations":{"es":"una camisa"}},{"id":"6","word":"un chemisier","translation":"a blouse","translations":{"es":"una blusa"}},{"id":"7","word":"un tee-shirt","translation":"a T-shirt","translations":{"es":"una camiseta"}},{"id":"8","word":"un pull","translation":"a sweater","translations":{"es":"un jersey / un suéter"}},{"id":"9","word":"un gilet","translation":"a cardigan / a vest","translations":{"es":"una chaqueta de punto / un chaleco"}},{"id":"10","word":"un pantalon","translation":"trousers","translations":{"es":"un pantalón"}},{"id":"11","word":"un jean","translation":"jeans","translations":{"es":"un vaquero / unos jeans"}},{"id":"12","word":"un short","translation":"shorts","translations":{"es":"un pantalón corto"}},{"id":"13","word":"une jupe","translation":"a skirt","translations":{"es":"una falda"}},{"id":"14","word":"une robe","translation":"a dress","translations":{"es":"un vestido"}},{"id":"15","word":"un costume","translation":"a suit","translations":{"es":"un traje"}},{"id":"16","word":"une cravate","translation":"a tie","translations":{"es":"una corbata"}},{"id":"17","word":"un nœud papillon","translation":"a bow tie","translations":{"es":"una pajarita"}},{"id":"18","word":"un pyjama","translation":"pajamas","translations":{"es":"un pijama"}},{"id":"19","word":"une robe de chambre","translation":"a bathrobe","translations":{"es":"una bata"}},{"id":"20","word":"un maillot de bain","translation":"a swimsuit","translations":{"es":"un bañador"}},{"id":"21","word":"des chaussures","translation":"shoes","translations":{"es":"zapatos"}},{"id":"22","word":"des bottes","translation":"boots","translations":{"es":"botas"}},{"id":"23","word":"des sandales","translation":"sandals","translations":{"es":"sandalias"}},{"id":"24","word":"des baskets","translation":"sneakers","translations":{"es":"zapatillas deportivas"}},{"id":"25","word":"des pantoufles","translation":"slippers","translations":{"es":"pantuflas"}},{"id":"26","word":"des chaussettes","translation":"socks","translations":{"es":"calcetines"}},{"id":"27","word":"des gants","translation":"gloves","translations":{"es":"guantes"}},{"id":"28","word":"une écharpe","translation":"a scarf","translations":{"es":"una bufanda"}},{"id":"29","word":"un bonnet","translation":"a beanie","translations":{"es":"un gorro"}},{"id":"30","word":"un chapeau","translation":"a hat","translations":{"es":"un sombrero"}},{"id":"31","word":"une casquette","translation":"a cap","translations":{"es":"una gorra"}},{"id":"32","word":"une ceinture","translation":"a belt","translations":{"es":"un cinturón"}},{"id":"33","word":"un sac à main","translation":"a handbag","translations":{"es":"un bolso"}},{"id":"34","word":"un parapluie","translation":"an umbrella","translations":{"es":"un paraguas"}},{"id":"35","word":"une poche","translation":"a pocket","translations":{"es":"un bolsillo"}},{"id":"36","word":"un bouton","translation":"a button","translations":{"es":"un botón"}},{"id":"37","word":"une fermeture éclair","translation":"a zipper","translations":{"es":"una cremallera"}},{"id":"38","word":"les manches","translation":"sleeves","translations":{"es":"las mangas"}},{"id":"39","word":"le col","translation":"the collar","translations":{"es":"el cuello"}},{"id":"40","word":"le coton","translation":"cotton","translations":{"es":"el algodón"}},{"id":"41","word":"la laine","translation":"wool","translations":{"es":"la lana"}},{"id":"42","word":"la soie","translation":"silk","translations":{"es":"la seda"}},{"id":"43","word":"le cuir","translation":"leather","translations":{"es":"el cuero"}},{"id":"44","word":"le velours","translation":"velvet","translations":{"es":"el terciopelo"}},{"id":"45","word":"coudre","translation":"to sew","translations":{"es":"coser"}}],"grammar":[{"structure":"aller à quelqu''un","example":"Ce béret te va bien. / Cette veste ne me va pas.","en":"\"To suit someone\"","es":"«Quedarle bien a alguien»"},{"structure":"en + matière","example":"une veste en cuir, un pull en laine","en":"Materials with \"en\"","es":"Materiales con «en»"},{"structure":"impératif","example":"Mets ton écharpe et tes gants !","en":"Imperative","es":"Imperativo"},{"structure":"sinon + futur proche","example":"Mets tes baskets, sinon tu vas avoir mal aux pieds.","en":"\"Otherwise\" + near future","es":"«Si no» + futuro próximo"},{"structure":"passé composé (pronominal)","example":"Ton chapeau s''est envolé ! / On m''a volé mon sac.","en":"Past tense (incl. reflexive)","es":"Pasado (incluidos los pronominales)"},{"structure":"vouloir que + subjonctif","example":"Tu veux que je le couse ?","en":"Offering with \"vouloir que\"","es":"Ofrecer con «vouloir que»"},{"structure":"pronom « en »","example":"Je n''en ai pas.","en":"\"en\" replacing a quantity","es":"«en» que sustituye una cantidad"},{"structure":"il faut + infinitif","example":"Il faut bien s''habiller pour un entretien.","en":"Necessity","es":"Necesidad"}],"tips":[{"en":"\"Porter\" = to wear; \"mettre\" = to put on; \"s''habiller\" = to get dressed.","es":"«Porter» = llevar puesto; «mettre» = ponerse; «s''habiller» = vestirse."},{"en":"\"Ça te va bien\" = it suits you. \"Ça va avec ton manteau\" = it goes with your coat.","es":"«Ça te va bien» = te queda bien. «Ça va avec ton manteau» = combina con tu abrigo."},{"en":"Materials use \"en\": \"en coton\", \"en soie\", \"en cuir\". Patterns: \"à manches courtes\", \"sans manches\".","es":"Los materiales van con «en»: «en coton», «en soie», «en cuir». Detalles: «à manches courtes», «sans manches»."},{"en":"In France, sneakers are \"des baskets\"; in Quebec, \"des espadrilles\". \"Un pantalon\" is singular (one pair of trousers).","es":"En Francia las zapatillas son «des baskets»; en Quebec, «des espadrilles». «Un pantalon» va en singular."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Ce béret te va bien.","translation":"This beret suits you.","translations":{"es":"Esta boina te queda bien."}},{"phrase":"Cette ceinture est trop grande pour moi.","translation":"This belt is too big for me.","translations":{"es":"Este cinturón me queda demasiado grande."}},{"phrase":"Le col et les manches de cette chemise sont sales.","translation":"The collar and sleeves of this shirt are dirty.","translations":{"es":"El cuello y las mangas de esta camisa están sucios."}},{"phrase":"Sa veste en cuir est superbe.","translation":"His leather jacket is superb.","translations":{"es":"Su chaqueta de cuero es preciosa."}},{"phrase":"Mets tes baskets pour courir, sinon tu vas avoir mal aux pieds.","translation":"Put on your sneakers to run, otherwise your feet will hurt.","translations":{"es":"Ponte las zapatillas para correr, si no te van a doler los pies."}},{"phrase":"Mets ton écharpe et tes gants : il fait trop froid !","translation":"Put on your scarf and gloves: it''s too cold!","translations":{"es":"Ponte la bufanda y los guantes: ¡hace demasiado frío!"}},{"phrase":"Mets ton pyjama et va dormir.","translation":"Put on your pajamas and go to sleep.","translations":{"es":"Ponte el pijama y vete a dormir."}},{"phrase":"Cette jupe se lave à la main.","translation":"This skirt must be hand-washed.","translations":{"es":"Esta falda se lava a mano."}},{"phrase":"Ton chapeau s''est envolé !","translation":"Your hat blew away!","translations":{"es":"¡Se te ha volado el sombrero!"}},{"phrase":"Au secours, on m''a volé mon sac à main !","translation":"Help, someone stole my handbag!","translations":{"es":"¡Socorro, me han robado el bolso!"}},{"phrase":"Je voudrais une robe sans manches.","translation":"I would like a sleeveless dress.","translations":{"es":"Quisiera un vestido sin mangas."}},{"phrase":"Les couleurs de ton gilet vont bien avec ton manteau.","translation":"The colors of your cardigan go well with your coat.","translations":{"es":"Los colores de tu chaqueta de punto combinan bien con tu abrigo."}},{"phrase":"Tu as perdu un bouton. Tu veux que je le couse ?","translation":"You lost a button. Do you want me to sew it on?","translations":{"es":"Has perdido un botón. ¿Quieres que te lo cosa?"}},{"phrase":"Tu peux me prêter une serviette ? — Je n''en ai pas, mais je peux te prêter une robe de chambre.","translation":"Can you lend me a towel? — I don''t have one, but I can lend you a bathrobe.","translations":{"es":"¿Me prestas una toalla? — No tengo, pero puedo prestarte una bata."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you say \"This jacket suits you\"?","options":["Cette veste est bien à toi.","Cette veste te va bien.","Tu vas bien à cette veste.","Cette veste te porte bien."],"correct":1,"explanation":"\"Aller à quelqu''un\" = to suit someone.","translations":{"es":{"question":"¿Cómo se dice «Esta chaqueta te queda bien»?","explanation":"«Aller à quelqu''un» = quedarle bien a alguien."}}},{"id":"2","question":"Complete: \"une veste ___ cuir\"","options":["en","de la","à","avec"],"correct":0,"explanation":"Materials: en cuir, en laine, en soie.","translations":{"es":{"question":"Completa: «une veste ___ cuir»","explanation":"Materiales: en cuir, en laine, en soie."}}},{"id":"3","question":"What do you wear when it rains?","options":["un imperméable","un maillot de bain","une robe de chambre","des sandales"],"correct":0,"explanation":"Also: prendre un parapluie.","translations":{"es":{"question":"¿Qué te pones cuando llueve?","explanation":"También: prendre un parapluie."}}},{"id":"4","question":"Complete: \"Mets ton manteau, ___ tu vas avoir froid.\"","options":["si","donc","sinon","mais"],"correct":2,"explanation":"\"Sinon\" = otherwise.","translations":{"es":{"question":"Completa: «Mets ton manteau, ___ tu vas avoir froid.»","explanation":"«Sinon» = si no / de lo contrario."}}},{"id":"5","question":"Which past form is correct?","options":["Mon chapeau est envolé lui.","Mon chapeau a envolé.","Mon chapeau s''est envolé.","Mon chapeau s''a envolé."],"correct":2,"explanation":"Reflexive verbs use \"être\".","translations":{"es":{"question":"¿Qué forma del pasado es correcta?","explanation":"Los verbos pronominales usan «être»."}}},{"id":"6","question":"Complete: \"Tu veux que je le ___ ?\" (coudre)","options":["cousais","couds","couse","coudrai"],"correct":2,"explanation":"\"Vouloir que\" + subjunctive: coudre → que je couse.","translations":{"es":{"question":"Completa: «Tu veux que je le ___ ?» (coudre)","explanation":"«Vouloir que» + subjuntivo: coudre → que je couse."}}},{"id":"7","question":"\"Tu as des gants ?\" — \"Non, je n''___ ai pas.\"","options":["les","leur","en","y"],"correct":2,"explanation":"\"En\" replaces \"des gants\".","translations":{"es":{"question":"«Tu as des gants ?» — «Non, je n''___ ai pas.»","explanation":"«En» sustituye a «des gants»."}}},{"id":"8","question":"What is the difference between \"mettre\" and \"porter\"?","options":["mettre = to put on, porter = to wear","porter = to put on, mettre = to take off","mettre = to wear, porter = to buy","They are the same"],"correct":0,"explanation":"\"Je mets mon manteau\" (action) / \"Je porte un manteau\" (state).","translations":{"es":{"question":"¿Qué diferencia hay entre «mettre» y «porter»?","explanation":"«Je mets mon manteau» (acción) / «Je porte un manteau» (estado).","options":["mettre = ponerse, porter = llevar puesto","porter = ponerse, mettre = quitarse","mettre = llevar, porter = comprar","Son lo mismo"]}}}]}'::jsonb, 3),
  ('story', 'La valise pour Québec', '{"text":"Théo est étudiant à Marseille. En janvier, il va passer un semestre à Québec, et il prépare sa valise. Sa mère l''aide : « Là-bas, il fait moins vingt en hiver ! Il faut que tu prennes des vêtements chauds. » Théo met dans la valise deux pulls en laine, un anorak, un bonnet, une écharpe et des gants. « Et tes bottes ? Sinon, tu vas avoir froid aux pieds ! » Pour aller à l''université, il préfère être simple : un jean, un tee-shirt et des baskets. Mais pour les présentations, il faut bien s''habiller, alors il prend aussi une chemise blanche et une veste. « Cette veste te va très bien », dit sa mère. Soudain, Théo remarque qu''il a perdu un bouton. « Tu veux que je le couse ? » demande sa mère. « Oui, merci ! » Le soir, la valise ne ferme plus. « Je crois qu''il y a trop de vêtements… », dit Théo. Sa mère rit : « Mieux vaut avoir trop chaud que trop froid ! »","translation":"Théo is a student in Marseille. In January, he is going to spend a semester in Quebec City, and he is packing his suitcase. His mother helps him: “It''s minus twenty there in winter! You need to take warm clothes.” Théo puts two wool sweaters, a parka, a beanie, a scarf and gloves in the suitcase. “And your boots? Otherwise your feet will be cold!” To go to university, he prefers to keep it simple: jeans, a T-shirt and sneakers. But for presentations, you have to dress well, so he also takes a white shirt and a jacket. “That jacket really suits you,” says his mother. Suddenly, Théo notices he has lost a button. “Do you want me to sew it on?” his mother asks. “Yes, thanks!” In the evening, the suitcase won''t close anymore. “I think there are too many clothes…,” says Théo. His mother laughs: “Better too warm than too cold!”","translations":{"es":"Théo es estudiante en Marsella. En enero va a pasar un semestre en Quebec y está haciendo la maleta. Su madre lo ayuda: «¡Allí hace veinte grados bajo cero en invierno! Tienes que llevar ropa de abrigo.» Théo mete en la maleta dos jerséis de lana, un anorak, un gorro, una bufanda y unos guantes. «¿Y tus botas? ¡Si no, se te van a enfriar los pies!» Para ir a la universidad, prefiere ir sencillo: un vaquero, una camiseta y zapatillas. Pero para las presentaciones hay que vestirse bien, así que también lleva una camisa blanca y una chaqueta. «Esa chaqueta te queda muy bien», dice su madre. De repente, Théo se da cuenta de que ha perdido un botón. «¿Quieres que te lo cosa?», pregunta su madre. «¡Sí, gracias!» Por la noche, la maleta ya no cierra. «Creo que hay demasiada ropa…», dice Théo. Su madre se ríe: «¡Más vale tener demasiado calor que demasiado frío!»"},"highlighted_words":["Il faut que tu prennes","pulls en laine","anorak","bonnet","écharpe","gants","Sinon","il faut bien s''habiller","te va très bien","Tu veux que je le couse"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Ce","chapeau","te","va","bien"],"translation":"This hat suits you","translations":{"es":"Este sombrero te queda bien"}},{"words":["Mets","ton","écharpe","et","tes","gants"],"translation":"Put on your scarf and gloves","translations":{"es":"Ponte la bufanda y los guantes"}},{"words":["J''ai","besoin","d''un","maillot","de","bain"],"translation":"I need a swimsuit","translations":{"es":"Necesito un bañador"}},{"words":["Sa","veste","est","en","cuir"],"translation":"His jacket is made of leather","translations":{"es":"Su chaqueta es de cuero"}},{"words":["Mon","chapeau","s''est","envolé"],"translation":"My hat blew away","translations":{"es":"Se me voló el sombrero"}},{"words":["Tu","veux","que","je","le","couse"],"translation":"Do you want me to sew it","translations":{"es":"¿Quieres que te lo cosa?"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I am wearing a red dress","translations":{"es":"Llevo un vestido rojo"},"answer":"Je porte une robe rouge"},{"prompt":"Put on your coat","translations":{"es":"Ponte el abrigo"},"answer":"Mets ton manteau"},{"prompt":"This jacket doesn''t suit me","translations":{"es":"Esta chaqueta no me queda bien"},"answer":"Cette veste ne me va pas"},{"prompt":"A cotton shirt","translations":{"es":"Una camisa de algodón"},"answer":"Une chemise en coton"},{"prompt":"Take the umbrella, it''s raining","translations":{"es":"Llévate el paraguas, está lloviendo"},"answer":"Prends le parapluie, il pleut"},{"prompt":"I don''t have a pocket","translations":{"es":"No tengo bolsillo"},"answer":"Je n''ai pas de poche"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 17: Les fruits et les légumes
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-17', 'Les fruits et les légumes', '🥕', 'Las frutas y las verduras', 17, true)
