insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"une pomme","translation":"an apple","translations":{"es":"una manzana"}},{"id":"2","word":"une poire","translation":"a pear","translations":{"es":"una pera"}},{"id":"3","word":"une banane","translation":"a banana","translations":{"es":"un plátano / una banana"}},{"id":"4","word":"une orange","translation":"an orange","translations":{"es":"una naranja"}},{"id":"5","word":"une mandarine","translation":"a tangerine","translations":{"es":"una mandarina"}},{"id":"6","word":"un citron","translation":"a lemon","translations":{"es":"un limón"}},{"id":"7","word":"un pamplemousse","translation":"a grapefruit","translations":{"es":"un pomelo / una toronja"}},{"id":"8","word":"une pêche","translation":"a peach","translations":{"es":"un melocotón / un durazno"}},{"id":"9","word":"un abricot","translation":"an apricot","translations":{"es":"un albaricoque"}},{"id":"10","word":"une prune","translation":"a plum","translations":{"es":"una ciruela"}},{"id":"11","word":"une cerise","translation":"a cherry","translations":{"es":"una cereza"}},{"id":"12","word":"une fraise","translation":"a strawberry","translations":{"es":"una fresa"}},{"id":"13","word":"une framboise","translation":"a raspberry","translations":{"es":"una frambuesa"}},{"id":"14","word":"une myrtille","translation":"a blueberry","translations":{"es":"un arándano"}},{"id":"15","word":"une mûre","translation":"a blackberry","translations":{"es":"una mora"}},{"id":"16","word":"le raisin","translation":"grapes","translations":{"es":"la uva"}},{"id":"17","word":"une figue","translation":"a fig","translations":{"es":"un higo"}},{"id":"18","word":"un ananas","translation":"a pineapple","translations":{"es":"una piña"}},{"id":"19","word":"une mangue","translation":"a mango","translations":{"es":"un mango"}},{"id":"20","word":"une papaye","translation":"a papaya","translations":{"es":"una papaya"}},{"id":"21","word":"un melon","translation":"a melon","translations":{"es":"un melón"}},{"id":"22","word":"une noix de coco","translation":"a coconut","translations":{"es":"un coco"}},{"id":"23","word":"un avocat","translation":"an avocado","translations":{"es":"un aguacate"}},{"id":"24","word":"une tomate","translation":"a tomato","translations":{"es":"un tomate"}},{"id":"25","word":"une carotte","translation":"a carrot","translations":{"es":"una zanahoria"}},{"id":"26","word":"une pomme de terre","translation":"a potato","translations":{"es":"una papa / una patata"}},{"id":"27","word":"un oignon","translation":"an onion","translations":{"es":"una cebolla"}},{"id":"28","word":"l''ail","translation":"garlic","translations":{"es":"el ajo"}},{"id":"29","word":"un poivron","translation":"a bell pepper","translations":{"es":"un pimiento"}},{"id":"30","word":"un concombre","translation":"a cucumber","translations":{"es":"un pepino"}},{"id":"31","word":"une courgette","translation":"a zucchini","translations":{"es":"un calabacín"}},{"id":"32","word":"une aubergine","translation":"an eggplant","translations":{"es":"una berenjena"}},{"id":"33","word":"la laitue","translation":"lettuce","translations":{"es":"la lechuga"}},{"id":"34","word":"le chou","translation":"cabbage","translations":{"es":"la col / el repollo"}},{"id":"35","word":"le chou-fleur","translation":"cauliflower","translations":{"es":"la coliflor"}},{"id":"36","word":"le brocoli","translation":"broccoli","translations":{"es":"el brócoli"}},{"id":"37","word":"les épinards","translation":"spinach","translations":{"es":"las espinacas"}},{"id":"38","word":"les petits pois","translation":"peas","translations":{"es":"los guisantes / las arvejas"}},{"id":"39","word":"les haricots verts","translation":"green beans","translations":{"es":"las judías verdes / los ejotes"}},{"id":"40","word":"les lentilles","translation":"lentils","translations":{"es":"las lentejas"}},{"id":"41","word":"les pois chiches","translation":"chickpeas","translations":{"es":"los garbanzos"}},{"id":"42","word":"le champignon","translation":"mushroom","translations":{"es":"el champiñón"}},{"id":"43","word":"le maïs","translation":"corn","translations":{"es":"el maíz"}},{"id":"44","word":"le persil","translation":"parsley","translations":{"es":"el perejil"}},{"id":"45","word":"la menthe","translation":"mint","translations":{"es":"la menta"}},{"id":"46","word":"les cacahuètes","translation":"peanuts","translations":{"es":"los cacahuetes / el maní"}},{"id":"47","word":"les amandes","translation":"almonds","translations":{"es":"las almendras"}},{"id":"48","word":"mûr / mûre","translation":"ripe","translations":{"es":"maduro / madura"}},{"id":"49","word":"pourrir","translation":"to rot","translations":{"es":"pudrirse"}}],"grammar":[{"structure":"articles partitifs","example":"des tomates, de la laitue, du concombre","en":"Partitive articles","es":"Artículos partitivos"},{"structure":"impératif (recettes)","example":"Fais une salade. Mets le chou-fleur à cuire. Mélange les petits pois avec le riz.","en":"Imperative in recipes","es":"Imperativo en recetas"},{"structure":"si + présent → futur","example":"Si tu manges des fruits et des légumes, tu auras un régime sain.","en":"Real condition","es":"Condición real"},{"structure":"futur simple","example":"Je ferai une soupe de céleri. / Tu profiteras d''une bonne santé.","en":"Simple future","es":"Futuro simple"},{"structure":"il est conseillé de / il faut + infinitif","example":"Il est conseillé de manger des fruits. / Il faut boire de l''eau.","en":"Advice and necessity","es":"Consejo y necesidad"},{"structure":"préférer / aimer plus","example":"Je préfère plutôt une pomme. / J''aime plus le chou-fleur.","en":"Expressing preferences","es":"Expresar preferencias"},{"structure":"passé composé + pronom","example":"Comment l''as-tu assaisonnée ?","en":"Past tense with object pronoun (agreement)","es":"Pasado con pronombre (concordancia)"},{"structure":"ne … pas tant de","example":"Ne mange pas tant de pistaches !","en":"\"not so much / many\"","es":"«no tanto / tantos»"}],"tips":[{"en":"With a direct object pronoun before \"avoir\", the past participle agrees: \"La salade ? Je l''ai assaisonnée.\"","es":"Con un pronombre de complemento directo antes de «avoir», el participio concuerda: «La salade ? Je l''ai assaisonnée.»"},{"en":"\"Le raisin\" is the fruit in general (grapes); \"un grain de raisin\" is one grape. \"Les raisins secs\" = raisins.","es":"«Le raisin» es la uva en general; «un grain de raisin» es una uva. «Les raisins secs» = pasas."},{"en":"\"Une pêche\" = a peach, but \"la pêche\" is also fishing. \"Un avocat\" = an avocado AND a lawyer!","es":"«Une pêche» = un melocotón, pero «la pêche» también es la pesca. «Un avocat» = un aguacate Y un abogado."},{"en":"Recipes in French often use the infinitive: \"Éplucher les carottes. Couper en dés.\"","es":"Las recetas en francés suelen usar el infinitivo: «Éplucher les carottes. Couper en dés.»"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Un jus de pomme, s''il vous plaît.","translation":"An apple juice, please.","translations":{"es":"Un jugo de manzana, por favor."}},{"phrase":"Fais une salade avec des tomates, de la laitue, du concombre et des carottes.","translation":"Make a salad with tomatoes, lettuce, cucumber and carrots.","translations":{"es":"Haz una ensalada con tomates, lechuga, pepino y zanahorias."}},{"phrase":"Je ferai une soupe de céleri ce soir.","translation":"I''ll make a celery soup tonight.","translations":{"es":"Esta noche haré una sopa de apio."}},{"phrase":"Ces mûres sont parfaites pour faire une tarte.","translation":"These blackberries are perfect for making a pie.","translations":{"es":"Estas moras son perfectas para hacer una tarta."}},{"phrase":"Tu sens l''ail !","translation":"You smell of garlic!","translations":{"es":"¡Hueles a ajo!"}},{"phrase":"Les lentilles ont beaucoup de protéines.","translation":"Lentils have a lot of protein.","translations":{"es":"Las lentejas tienen muchas proteínas."}},{"phrase":"Les mangues sont mes fruits préférés.","translation":"Mangoes are my favorite fruit.","translations":{"es":"Los mangos son mis frutas favoritas."}},{"phrase":"Les citrons et les oranges contiennent beaucoup de vitamine C.","translation":"Lemons and oranges contain a lot of vitamin C.","translations":{"es":"Los limones y las naranjas tienen mucha vitamina C."}},{"phrase":"Mets des champignons, de l''avocat et du poivron dans mon sandwich.","translation":"Put mushrooms, avocado and bell pepper in my sandwich.","translations":{"es":"Ponme champiñones, aguacate y pimiento en el sándwich."}},{"phrase":"Ces abricots sont en train de pourrir : fais-en un jus !","translation":"These apricots are going bad: make a juice with them!","translations":{"es":"Estos albaricoques se están pudriendo: ¡haz un jugo con ellos!"}},{"phrase":"Tu veux de la papaye ? — Non, je préfère plutôt une pomme.","translation":"Do you want some papaya? — No, I''d rather have an apple.","translations":{"es":"¿Quieres papaya? — No, prefiero una manzana."}},{"phrase":"Comment l''as-tu assaisonnée ? — Avec du citron, du sel, du poivre et du cumin.","translation":"How did you season it? — With lemon, salt, pepper and cumin.","translations":{"es":"¿Cómo la has aliñado? — Con limón, sal, pimienta y comino."}},{"phrase":"Tu as mal au ventre ? Attends, je t''ai préparé un thé à la menthe.","translation":"Does your stomach hurt? Wait, I made you a mint tea.","translations":{"es":"¿Te duele la barriga? Espera, te he preparado un té de menta."}},{"phrase":"Ne mange pas tant de cacahuètes !","translation":"Don''t eat so many peanuts!","translations":{"es":"¡No comas tantos cacahuetes!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Je voudrais ___ fraises.\"","options":["du","de l''","de la","des"],"correct":3,"explanation":"Plural partitive: des.","translations":{"es":{"question":"Completa: «Je voudrais ___ fraises.»","explanation":"Partitivo plural: des."}}},{"id":"2","question":"\"Un avocat\" can mean…","options":["an apricot","only a lawyer","a peach","an avocado or a lawyer"],"correct":3,"explanation":"Same word, two meanings!","translations":{"es":{"question":"«Un avocat» puede significar…","explanation":"¡Misma palabra, dos significados!","options":["un albaricoque","solo un abogado","un melocotón","un aguacate o un abogado"]}}},{"id":"3","question":"Complete: \"Si tu manges des légumes, tu ___ en bonne santé.\"","options":["étais","serais","es été","seras"],"correct":3,"explanation":"Si + present → future.","translations":{"es":{"question":"Completa: «Si tu manges des légumes, tu ___ en bonne santé.»","explanation":"Si + presente → futuro."}}},{"id":"4","question":"Which is a vegetable?","options":["la cerise","la framboise","la mangue","la courgette"],"correct":3,"explanation":"Courgette = zucchini.","translations":{"es":{"question":"¿Cuál es una verdura?","explanation":"Courgette = calabacín."}}},{"id":"5","question":"\"La salade ? Je l''ai ___.\" (assaisonner)","options":["assaisonnés","assaisonné","assaisonner","assaisonnée"],"correct":3,"explanation":"The participle agrees with \"l''\" (= la salade, feminine) placed before \"avoir\".","translations":{"es":{"question":"«La salade ? Je l''ai ___.» (assaisonner)","explanation":"El participio concuerda con «l''» (= la salade, femenino) colocado antes de «avoir»."}}},{"id":"6","question":"How do you express a preference politely?","options":["Une pomme, vite !","Donne pomme.","Je veux pas de pomme.","Je préfère plutôt une pomme."],"correct":3,"explanation":"\"Plutôt\" = rather.","translations":{"es":{"question":"¿Cómo expresas una preferencia con cortesía?","explanation":"«Plutôt» = más bien."}}},{"id":"7","question":"Which fruit is \"une myrtille\"?","options":["a raspberry","a cherry","a blackberry","a blueberry"],"correct":3,"explanation":"Mûre = blackberry, framboise = raspberry, cerise = cherry.","translations":{"es":{"question":"¿Qué fruta es «une myrtille»?","explanation":"Mûre = mora, framboise = frambuesa, cerise = cereza.","options":["una frambuesa","una cereza","una mora","un arándano"]}}},{"id":"8","question":"Complete: \"Il est conseillé ___ manger cinq fruits et légumes par jour.\"","options":["pour","que","à","de"],"correct":3,"explanation":"\"Il est conseillé de\" + infinitive.","translations":{"es":{"question":"Completa: «Il est conseillé ___ manger cinq fruits et légumes par jour.»","explanation":"«Il est conseillé de» + infinitivo."}}}]}'::jsonb, 3),
  ('story', 'Le marché du samedi', '{"text":"Tous les samedis, Amélie va au marché de son quartier, à Rennes. Elle dit toujours : « Si tu manges des fruits et des légumes de saison, tu seras en meilleure forme et tu dépenseras moins ! » Ce matin, elle achète des tomates, de la laitue, des courgettes et des oignons chez son maraîcher préféré. « Ces fraises sont bien mûres, elles viennent d''arriver », dit le vendeur. Amélie en prend une barquette. À la maison, elle prépare une ratatouille : « Coupe les aubergines et les poivrons, fais revenir l''oignon et l''ail dans l''huile d''olive, puis ajoute les tomates. » Son fils Noé goûte la sauce. « Comment l''as-tu assaisonnée ? » « Avec du sel, du poivre, du thym et du laurier. » Noé préfère les desserts. « Ne mange pas tant de fraises avant le repas ! » rit sa mère. Il est conseillé de manger des légumes variés et de boire beaucoup d''eau, mais chez Amélie, la règle d''or est simple : il faut que ce soit bon !","translation":"Every Saturday, Amélie goes to her neighborhood market in Rennes. She always says: “If you eat seasonal fruits and vegetables, you''ll be healthier and you''ll spend less!” This morning, she buys tomatoes, lettuce, zucchini and onions from her favorite vegetable grower. “These strawberries are nice and ripe, they''ve just arrived,” says the seller. Amélie takes a punnet. At home, she makes a ratatouille: “Cut the eggplants and bell peppers, fry the onion and garlic in olive oil, then add the tomatoes.” Her son Noé tastes the sauce. “How did you season it?” “With salt, pepper, thyme and bay leaf.” Noé prefers desserts. “Don''t eat so many strawberries before the meal!” his mother laughs. It''s advisable to eat a variety of vegetables and drink plenty of water, but at Amélie''s house, the golden rule is simple: it has to taste good!","translations":{"es":"Todos los sábados, Amélie va al mercado de su barrio, en Rennes. Siempre dice: «¡Si comes frutas y verduras de temporada, estarás en mejor forma y gastarás menos!». Esta mañana compra tomates, lechuga, calabacines y cebollas a su hortelano favorito. «Estas fresas están bien maduras, acaban de llegar», dice el vendedor. Amélie se lleva una cajita. En casa prepara un pisto: «Corta las berenjenas y los pimientos, sofríe la cebolla y el ajo en aceite de oliva y luego añade los tomates.» Su hijo Noé prueba la salsa. «¿Cómo la has aliñado?» «Con sal, pimienta, tomillo y laurel.» Noé prefiere los postres. «¡No comas tantas fresas antes de la comida!», se ríe su madre. Se recomienda comer verduras variadas y beber mucha agua, pero en casa de Amélie la regla de oro es sencilla: ¡tiene que estar rico!"},"highlighted_words":["Si tu manges","tu seras","des tomates","de la laitue","mûres","Coupe","ajoute","Comment l''as-tu assaisonnée","Ne mange pas tant de","Il est conseillé de","il faut que ce soit"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","mange","une","pomme","tous","les","jours"],"translation":"I eat an apple every day","translations":{"es":"Me como una manzana todos los días"}},{"words":["Fais","une","salade","avec","des","tomates"],"translation":"Make a salad with tomatoes","translations":{"es":"Haz una ensalada con tomates"}},{"words":["Les","fraises","sont","bien","mûres"],"translation":"The strawberries are nice and ripe","translations":{"es":"Las fresas están bien maduras"}},{"words":["Je","préfère","plutôt","une","poire"],"translation":"I''d rather have a pear","translations":{"es":"Prefiero una pera"}},{"words":["Ne","mange","pas","tant","de","chocolat"],"translation":"Don''t eat so much chocolate","translations":{"es":"No comas tanto chocolate"}},{"words":["Si","tu","manges","bien","tu","seras","en","forme"],"translation":"If you eat well you''ll be fit","translations":{"es":"Si comes bien, estarás en forma"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I like strawberries","translations":{"es":"Me gustan las fresas"},"answer":"J''aime les fraises"},{"prompt":"I don''t want onions","translations":{"es":"No quiero cebolla"},"answer":"Je ne veux pas d''oignons"},{"prompt":"Mangoes are my favorite fruit","translations":{"es":"Los mangos son mis frutas favoritas"},"answer":"Les mangues sont mes fruits préférés"},{"prompt":"Put mushrooms in the soup","translations":{"es":"Pon champiñones en la sopa"},"answer":"Mets des champignons dans la soupe"},{"prompt":"You smell of garlic","translations":{"es":"Hueles a ajo"},"answer":"Tu sens l''ail"},{"prompt":"An orange juice, please","translations":{"es":"Un jugo de naranja, por favor"},"answer":"Un jus d''orange, s''il vous plaît"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 18: Le sport
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-18', 'Le sport', '⚽', 'El deporte', 18, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''athlétisme","translation":"athletics","translations":{"es":"el atletismo"}},{"id":"2","word":"le football","translation":"soccer","translations":{"es":"el fútbol"}},{"id":"3","word":"le basket","translation":"basketball","translations":{"es":"el baloncesto"}},{"id":"4","word":"le volley","translation":"volleyball","translations":{"es":"el voleibol"}},{"id":"5","word":"le handball","translation":"handball","translations":{"es":"el balonmano"}},{"id":"6","word":"le rugby","translation":"rugby","translations":{"es":"el rugby"}},{"id":"7","word":"le tennis","translation":"tennis","translations":{"es":"el tenis"}},{"id":"8","word":"le tennis de table","translation":"table tennis","translations":{"es":"el tenis de mesa"}},{"id":"9","word":"le golf","translation":"golf","translations":{"es":"el golf"}},{"id":"10","word":"la boxe","translation":"boxing","translations":{"es":"el boxeo"}},{"id":"11","word":"la lutte","translation":"wrestling","translations":{"es":"la lucha"}},{"id":"12","word":"le judo","translation":"judo","translations":{"es":"el judo"}},{"id":"13","word":"la gymnastique","translation":"gymnastics","translations":{"es":"la gimnasia"}},{"id":"14","word":"la natation","translation":"swimming","translations":{"es":"la natación"}},{"id":"15","word":"le cyclisme","translation":"cycling","translations":{"es":"el ciclismo"}},{"id":"16","word":"l''alpinisme","translation":"mountaineering","translations":{"es":"el alpinismo"}},{"id":"17","word":"l''équitation","translation":"horse riding","translations":{"es":"la equitación"}},{"id":"18","word":"la voile","translation":"sailing","translations":{"es":"la vela"}},{"id":"19","word":"la planche à voile","translation":"windsurfing","translations":{"es":"el windsurf"}},{"id":"20","word":"le patinage","translation":"skating","translations":{"es":"el patinaje"}},{"id":"21","word":"les échecs","translation":"chess","translations":{"es":"el ajedrez"}},{"id":"22","word":"la pêche","translation":"fishing","translations":{"es":"la pesca"}},{"id":"23","word":"le terrain","translation":"the field / court","translations":{"es":"el campo / la cancha"}},{"id":"24","word":"le stade","translation":"the stadium","translations":{"es":"el estadio"}},{"id":"25","word":"la piscine","translation":"the swimming pool","translations":{"es":"la piscina"}},{"id":"26","word":"la piste","translation":"the track","translations":{"es":"la pista"}},{"id":"27","word":"le ballon","translation":"the ball (big)","translations":{"es":"el balón"}},{"id":"28","word":"la balle","translation":"the ball (small)","translations":{"es":"la pelota"}},{"id":"29","word":"la raquette","translation":"the racket","translations":{"es":"la raqueta"}},{"id":"30","word":"le filet","translation":"the net","translations":{"es":"la red"}},{"id":"31","word":"le casque","translation":"the helmet","translations":{"es":"el casco"}},{"id":"32","word":"le but","translation":"the goal","translations":{"es":"la portería / el gol"}},{"id":"33","word":"le gardien de but","translation":"the goalkeeper","translations":{"es":"el portero"}},{"id":"34","word":"l''arbitre","translation":"the referee","translations":{"es":"el árbitro"}},{"id":"35","word":"l''entraîneur","translation":"the coach","translations":{"es":"el entrenador"}},{"id":"36","word":"l''équipe","translation":"the team","translations":{"es":"el equipo"}},{"id":"37","word":"le joueur / la joueuse","translation":"the player","translations":{"es":"el jugador / la jugadora"}},{"id":"38","word":"le score","translation":"the score","translations":{"es":"el marcador"}},{"id":"39","word":"courir","translation":"to run","translations":{"es":"correr"}},{"id":"40","word":"nager","translation":"to swim","translations":{"es":"nadar"}},{"id":"41","word":"sauter","translation":"to jump","translations":{"es":"saltar"}},{"id":"42","word":"lancer","translation":"to throw","translations":{"es":"lanzar"}},{"id":"43","word":"attraper","translation":"to catch","translations":{"es":"atrapar"}},{"id":"44","word":"frapper","translation":"to hit","translations":{"es":"golpear"}},{"id":"45","word":"gagner","translation":"to win","translations":{"es":"ganar"}},{"id":"46","word":"perdre","translation":"to lose","translations":{"es":"perder"}},{"id":"47","word":"faire du jogging","translation":"to go jogging","translations":{"es":"hacer footing"}},{"id":"48","word":"transpirer","translation":"to sweat","translations":{"es":"sudar"}},{"id":"49","word":"blessé / blessée","translation":"injured","translations":{"es":"lesionado / lesionada"}}],"grammar":[{"structure":"jouer à / faire de","example":"jouer au tennis, jouer aux échecs / faire du vélo, faire de la natation","en":"Playing vs. doing a sport","es":"«Jugar a» frente a «practicar»"},{"structure":"impératif + pronoms","example":"Frappe la balle ! Passe-la-moi ! Avance ! Recule !","en":"Imperative in the game","es":"Imperativo en el juego"},{"structure":"voix passive","example":"Le rugby est joué partout en France.","en":"Passive voice","es":"Voz pasiva"},{"structure":"bien que + subjonctif","example":"Bien qu''ils soient violents, ces sports sont populaires.","en":"\"Although\" + subjunctive","es":"«Aunque» + subjuntivo"},{"structure":"ne … que","example":"Tu n''as besoin que d''une paire de baskets.","en":"\"only\"","es":"«solo»"},{"structure":"imparfait / présent","example":"J''essayais de te rattraper, mais tu cours trop vite !","en":"Ongoing past action","es":"Acción en curso en el pasado"},{"structure":"c''est à moi de + infinitif","example":"C''est à moi de frapper.","en":"\"It''s my turn to\"","es":"«Me toca a mí»"},{"structure":"préférer … plutôt que","example":"Je préfère le roller plutôt que la trottinette.","en":"Preferences","es":"Preferencias"}],"tips":[{"en":"\"Jouer à\" for games and ball sports (jouer au foot, aux cartes); \"faire de\" for other activities (faire du ski, de la boxe, du yoga).","es":"«Jouer à» para juegos y deportes de pelota (jouer au foot, aux cartes); «faire de» para otras actividades (faire du ski, de la boxe, du yoga)."},{"en":"\"Une balle\" is small (tennis, golf); \"un ballon\" is big (football, basketball).","es":"«Une balle» es pequeña (tenis, golf); «un ballon» es grande (fútbol, baloncesto)."},{"en":"\"Marquer un but\" = to score a goal; \"gagner / perdre un match\" = to win / lose a game; \"match nul\" = a draw.","es":"«Marquer un but» = marcar un gol; «gagner / perdre un match» = ganar / perder un partido; «match nul» = empate."},{"en":"Informal: \"s''éclater\" = to have a blast.","es":"Coloquial: «s''éclater» = pasárselo en grande."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Tu fais beaucoup d''exercice !","translation":"You do a lot of exercise!","translations":{"es":"¡Haces mucho ejercicio!"}},{"phrase":"J''aime courir tous les matins.","translation":"I like running every morning.","translations":{"es":"Me gusta correr todas las mañanas."}},{"phrase":"Mets ton casque !","translation":"Put on your helmet!","translations":{"es":"¡Ponte el casco!"}},{"phrase":"Jouons au basket !","translation":"Let''s play basketball!","translations":{"es":"¡Juguemos al baloncesto!"}},{"phrase":"Donne-moi la raquette, c''est à moi de servir.","translation":"Give me the racket, it''s my turn to serve.","translations":{"es":"Dame la raqueta, me toca sacar a mí."}},{"phrase":"Attrape la balle si tu peux !","translation":"Catch the ball if you can!","translations":{"es":"¡Atrapa la pelota si puedes!"}},{"phrase":"Il faut être patient pour jouer aux échecs.","translation":"You have to be patient to play chess.","translations":{"es":"Hay que ser paciente para jugar al ajedrez."}},{"phrase":"Le handball est très joué en Allemagne.","translation":"Handball is widely played in Germany.","translations":{"es":"El balonmano se juega mucho en Alemania."}},{"phrase":"Les enfants sont en train de sauter à la corde.","translation":"The children are skipping rope.","translations":{"es":"Los niños están saltando a la comba."}},{"phrase":"L''arbitre a été injuste !","translation":"The referee was unfair!","translations":{"es":"¡El árbitro ha sido injusto!"}},{"phrase":"On a besoin d''une autre joueuse : Clara est blessée.","translation":"We need another player: Clara is injured.","translations":{"es":"Necesitamos otra jugadora: Clara está lesionada."}},{"phrase":"As-tu pêché quelque chose ? — Deux poissons et une vieille chaussure !","translation":"Did you catch anything? — Two fish and an old shoe!","translations":{"es":"¿Has pescado algo? — ¡Dos peces y un zapato viejo!"}},{"phrase":"Tu transpires ! — J''essayais de te rattraper, mais tu cours trop vite.","translation":"You''re sweating! — I was trying to catch up with you, but you run too fast.","translations":{"es":"¡Estás sudando! — Intentaba alcanzarte, pero corres demasiado rápido."}},{"phrase":"Le stade est plein.","translation":"The stadium is full.","translations":{"es":"El estadio está lleno."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Je joue ___ tennis.\"","options":["à","le","au","du"],"correct":2,"explanation":"Jouer à + le = au.","translations":{"es":{"question":"Completa: «Je joue ___ tennis.»","explanation":"Jouer à + le = au."}}},{"id":"2","question":"Complete: \"Elle fait ___ natation.\"","options":["la","du","de la","à la"],"correct":2,"explanation":"Faire de + la = de la natation.","translations":{"es":{"question":"Completa: «Elle fait ___ natation.»","explanation":"Faire de + la = de la natation."}}},{"id":"3","question":"Which ball is used in football?","options":["un filet","une raquette","un ballon","une balle"],"correct":2,"explanation":"Big balls are \"ballons\".","translations":{"es":{"question":"¿Qué pelota se usa en el fútbol?","explanation":"Las pelotas grandes son «ballons»."}}},{"id":"4","question":"Complete: \"Bien qu''ils ___ violents, ces sports sont populaires.\"","options":["seront","soient","étaient","sont"],"correct":1,"explanation":"\"Bien que\" + subjunctive.","translations":{"es":{"question":"Completa: «Bien qu''ils ___ violents, ces sports sont populaires.»","explanation":"«Bien que» + subjuntivo."}}},{"id":"5","question":"\"Tu n''as besoin que d''une paire de baskets.\" Meaning?","options":["You only need a pair of sneakers.","You need more than sneakers.","You never need sneakers.","You don''t need sneakers."],"correct":0,"explanation":"\"Ne … que\" = only.","translations":{"es":{"question":"«Tu n''as besoin que d''une paire de baskets.» ¿Significado?","explanation":"«Ne … que» = solo.","options":["Solo necesitas unas zapatillas.","Necesitas más que zapatillas.","Nunca necesitas zapatillas.","No necesitas zapatillas."]}}},{"id":"6","question":"Who is in charge of the rules during a match?","options":["l''arbitre","le gardien de but","le joueur","l''entraîneur"],"correct":0,"explanation":"The coach trains the team; the referee controls the game.","translations":{"es":{"question":"¿Quién hace cumplir las reglas en un partido?","explanation":"El entrenador entrena al equipo; el árbitro dirige el partido."}}},{"id":"7","question":"How do you say \"Pass it to me!\" (la balle)?","options":["La passe-moi !","Passe-la-moi !","Me la passe !","Passe-moi-la !"],"correct":1,"explanation":"Order in the affirmative imperative: verb-le/la/les-moi.","translations":{"es":{"question":"¿Cómo se dice «¡Pásamela!» (la balle)?","explanation":"Orden en el imperativo afirmativo: verbo-le/la/les-moi."}}},{"id":"8","question":"\"Match nul\" means…","options":["a draw","a final","a cancelled match","a bad match"],"correct":0,"explanation":"Gagner = win, perdre = lose, match nul = draw.","translations":{"es":{"question":"«Match nul» significa…","explanation":"Gagner = ganar, perdre = perder, match nul = empate.","options":["un empate","una final","un partido cancelado","un mal partido"]}}}]}'::jsonb, 3),
  ('story', 'Le tournoi du quartier', '{"text":"Ce samedi, l''équipe de volley d''Inès joue la finale du tournoi du quartier. Malheureusement, leur entraîneur est malade. « Qui va nous diriger ? » demande Léo. « C''est à moi de le faire, je suis la capitaine », répond Inès. Avant le match, elle explique : « Bien que nos adversaires soient plus grands, nous pouvons gagner. Il faut rester calmes et jouer ensemble. » Le stade est plein. Pendant le premier set, l''autre équipe marque beaucoup de points. « Avance ! Recule ! Passe-la-moi ! » crie Inès. Au deuxième set, Clara se blesse à la cheville. « On a besoin d''une autre joueuse ! » Heureusement, la petite sœur d''Inès, qui faisait de la gymnastique quand elle était enfant, saute très haut. Elle n''a que quinze ans, mais elle est incroyable ! Score final : deux sets à un. L''arbitre siffle la fin du match. Tout le monde s''éclate. « Le sport, c''est d''abord pour s''amuser », dit Inès en souriant.","translation":"This Saturday, Inès''s volleyball team is playing the final of the neighborhood tournament. Unfortunately, their coach is ill. “Who''s going to lead us?” asks Léo. “It''s my job, I''m the captain,” answers Inès. Before the game, she explains: “Although our opponents are taller, we can win. We have to stay calm and play together.” The stadium is full. During the first set, the other team scores a lot of points. “Move forward! Move back! Pass it to me!” shouts Inès. In the second set, Clara hurts her ankle. “We need another player!” Luckily, Inès''s little sister, who did gymnastics when she was a child, jumps very high. She is only fifteen, but she''s amazing! Final score: two sets to one. The referee whistles the end of the game. Everyone has a blast. “Sport is first of all about having fun,” says Inès with a smile.","translations":{"es":"Este sábado, el equipo de voleibol de Inès juega la final del torneo del barrio. Por desgracia, su entrenador está enfermo. «¿Quién nos va a dirigir?», pregunta Léo. «Me toca a mí, soy la capitana», responde Inès. Antes del partido, explica: «Aunque nuestros rivales sean más altos, podemos ganar. Hay que mantener la calma y jugar juntos.» El estadio está lleno. Durante el primer set, el otro equipo marca muchos puntos. «¡Avanza! ¡Retrocede! ¡Pásamela!», grita Inès. En el segundo set, Clara se lesiona el tobillo. «¡Necesitamos otra jugadora!» Por suerte, la hermana pequeña de Inès, que hacía gimnasia cuando era niña, salta muy alto. Solo tiene quince años, ¡pero es increíble! Resultado final: dos sets a uno. El árbitro pita el final del partido. Todo el mundo se lo pasa en grande. «El deporte es, ante todo, para divertirse», dice Inès sonriendo."},"highlighted_words":["entraîneur","C''est à moi de","Bien que","soient","Il faut","Passe-la-moi","faisait de la gymnastique","n''a que","L''arbitre","s''éclate"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","joue","au","foot","le","samedi"],"translation":"I play soccer on Saturdays","translations":{"es":"Juego al fútbol los sábados"}},{"words":["Elle","fait","de","la","natation"],"translation":"She swims","translations":{"es":"Practica natación"}},{"words":["C''est","à","moi","de","jouer"],"translation":"It''s my turn to play","translations":{"es":"Me toca jugar a mí"}},{"words":["Il","faut","être","patient"],"translation":"You have to be patient","translations":{"es":"Hay que ser paciente"}},{"words":["Tu","n''as","besoin","que","d''un","ballon"],"translation":"You only need a ball","translations":{"es":"Solo necesitas un balón"}},{"words":["L''arbitre","a","été","injuste"],"translation":"The referee was unfair","translations":{"es":"El árbitro ha sido injusto"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Let''s play basketball","translations":{"es":"Juguemos al baloncesto"},"answer":"Jouons au basket"},{"prompt":"Put on your helmet","translations":{"es":"Ponte el casco"},"answer":"Mets ton casque"},{"prompt":"The stadium is full","translations":{"es":"El estadio está lleno"},"answer":"Le stade est plein"},{"prompt":"We won the game","translations":{"es":"Hemos ganado el partido"},"answer":"Nous avons gagné le match"},{"prompt":"I like cycling","translations":{"es":"Me gusta montar en bici"},"answer":"J''aime faire du vélo"},{"prompt":"He is injured","translations":{"es":"Está lesionado"},"answer":"Il est blessé"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 19: Le monde et l'univers
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-19', 'Le monde et l''univers', '🪐', 'El mundo y el universo', 19, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''univers","translation":"the universe","translations":{"es":"el universo"}},{"id":"2","word":"l''espace","translation":"space","translations":{"es":"el espacio"}},{"id":"3","word":"la Terre","translation":"the Earth","translations":{"es":"la Tierra"}},{"id":"4","word":"le Soleil","translation":"the Sun","translations":{"es":"el Sol"}},{"id":"5","word":"la Lune","translation":"the Moon","translations":{"es":"la Luna"}},{"id":"6","word":"une planète","translation":"a planet","translations":{"es":"un planeta"}},{"id":"7","word":"une étoile","translation":"a star","translations":{"es":"una estrella"}},{"id":"8","word":"une constellation","translation":"a constellation","translations":{"es":"una constelación"}},{"id":"9","word":"le système solaire","translation":"the solar system","translations":{"es":"el sistema solar"}},{"id":"10","word":"un satellite","translation":"a satellite","translations":{"es":"un satélite"}},{"id":"11","word":"l''orbite","translation":"the orbit","translations":{"es":"la órbita"}},{"id":"12","word":"un vaisseau spatial","translation":"a spaceship","translations":{"es":"una nave espacial"}},{"id":"13","word":"un extraterrestre","translation":"an alien","translations":{"es":"un extraterrestre"}},{"id":"14","word":"un OVNI","translation":"a UFO","translations":{"es":"un ovni"}},{"id":"15","word":"l''atmosphère","translation":"the atmosphere","translations":{"es":"la atmósfera"}},{"id":"16","word":"l''air","translation":"air","translations":{"es":"el aire"}},{"id":"17","word":"l''oxygène","translation":"oxygen","translations":{"es":"el oxígeno"}},{"id":"18","word":"le ciel","translation":"the sky","translations":{"es":"el cielo"}},{"id":"19","word":"un continent","translation":"a continent","translations":{"es":"un continente"}},{"id":"20","word":"un océan","translation":"an ocean","translations":{"es":"un océano"}},{"id":"21","word":"la mer","translation":"the sea","translations":{"es":"el mar"}},{"id":"22","word":"la côte","translation":"the coast","translations":{"es":"la costa"}},{"id":"23","word":"la plage","translation":"the beach","translations":{"es":"la playa"}},{"id":"24","word":"une île","translation":"an island","translations":{"es":"una isla"}},{"id":"25","word":"une baie","translation":"a bay","translations":{"es":"una bahía"}},{"id":"26","word":"un lac","translation":"a lake","translations":{"es":"un lago"}},{"id":"27","word":"un fleuve","translation":"a (large) river","translations":{"es":"un río (que desemboca en el mar)"}},{"id":"28","word":"une rivière","translation":"a river","translations":{"es":"un río"}},{"id":"29","word":"la rive","translation":"the bank / shore","translations":{"es":"la orilla"}},{"id":"30","word":"une montagne","translation":"a mountain","translations":{"es":"una montaña"}},{"id":"31","word":"une colline","translation":"a hill","translations":{"es":"una colina"}},{"id":"32","word":"une vallée","translation":"a valley","translations":{"es":"un valle"}},{"id":"33","word":"une plaine","translation":"a plain","translations":{"es":"una llanura"}},{"id":"34","word":"un désert","translation":"a desert","translations":{"es":"un desierto"}},{"id":"35","word":"une grotte","translation":"a cave","translations":{"es":"una cueva"}},{"id":"36","word":"un rocher","translation":"a rock","translations":{"es":"una roca"}},{"id":"37","word":"le marais","translation":"the marsh","translations":{"es":"el pantano"}},{"id":"38","word":"l''horizon","translation":"the horizon","translations":{"es":"el horizonte"}},{"id":"39","word":"le paysage","translation":"the landscape","translations":{"es":"el paisaje"}},{"id":"40","word":"la marée","translation":"the tide","translations":{"es":"la marea"}},{"id":"41","word":"le niveau de la mer","translation":"sea level","translations":{"es":"el nivel del mar"}},{"id":"42","word":"un tremblement de terre","translation":"an earthquake","translations":{"es":"un terremoto"}},{"id":"43","word":"une tornade","translation":"a tornado","translations":{"es":"un tornado"}},{"id":"44","word":"une catastrophe","translation":"a disaster","translations":{"es":"una catástrofe"}},{"id":"45","word":"l''ombre","translation":"the shadow / shade","translations":{"es":"la sombra"}},{"id":"46","word":"profond / profonde","translation":"deep","translations":{"es":"profundo / profunda"}},{"id":"47","word":"sombre","translation":"dark","translations":{"es":"oscuro"}},{"id":"48","word":"brillant / brillante","translation":"bright / shiny","translations":{"es":"brillante"}}],"grammar":[{"structure":"superlatif","example":"Le Sahara est le plus grand désert chaud du monde.","en":"Superlatives","es":"Superlativos"},{"structure":"gérondif (en + participe présent)","example":"En regardant autour de nous, nous trouverons des merveilles.","en":"Gerund: \"by / while doing\"","es":"Gerundio: «al / mientras»"},{"structure":"participe présent","example":"des montagnes formant une chaîne, des baleines sautant hors de l''eau","en":"Present participle","es":"Participio presente"},{"structure":"voix passive","example":"La Terre est menacée par la pollution.","en":"Passive voice","es":"Voz pasiva"},{"structure":"croire + infinitif passé","example":"Je crois avoir vu un OVNI hier soir.","en":"\"I think I saw…\"","es":"«Creo haber visto…»"},{"structure":"se produire (passé composé)","example":"Une catastrophe s''est produite hier soir.","en":"Reflexive verb in the past","es":"Verbo pronominal en pasado"},{"structure":"afin de + infinitif","example":"Il faut agir afin de protéger la planète.","en":"\"In order to\"","es":"«Con el fin de»"},{"structure":"espérons que + indicatif","example":"Espérons que la science nous aidera.","en":"\"Let''s hope that\"","es":"«Esperemos que» (con indicativo en francés)"}],"tips":[{"en":"Our solar system has eight planets: Mercure, Vénus, la Terre, Mars, Jupiter, Saturne, Uranus, Neptune. Pluton has been a dwarf planet since 2006.","es":"Nuestro sistema solar tiene ocho planetas: Mercure, Vénus, la Terre, Mars, Jupiter, Saturne, Uranus, Neptune. Plutón es un planeta enano desde 2006."},{"en":"\"Un fleuve\" flows into the sea; \"une rivière\" flows into another river.","es":"«Un fleuve» desemboca en el mar; «une rivière» desemboca en otro río."},{"en":"In French schools, people often count five continents (Afrique, Amérique, Asie, Europe, Océanie), sometimes six or seven.","es":"En los colegios franceses se suelen contar cinco continentes (Afrique, Amérique, Asie, Europe, Océanie), a veces seis o siete."},{"en":"\"Espérer que\" takes the indicative, unlike Spanish: \"J''espère qu''il viendra.\"","es":"«Espérer que» va con indicativo, a diferencia del español: «J''espère qu''il viendra.»"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"L''air de la montagne est pur.","translation":"The mountain air is pure.","translations":{"es":"El aire de la montaña es puro."}},{"phrase":"Le Sahara est le plus grand désert chaud du monde.","translation":"The Sahara is the largest hot desert in the world.","translations":{"es":"El Sáhara es el desierto cálido más grande del mundo."}},{"phrase":"L''océan est plein de mystères et de beauté.","translation":"The ocean is full of mystery and beauty.","translations":{"es":"El océano está lleno de misterios y belleza."}},{"phrase":"La Lune est le seul satellite naturel de la Terre.","translation":"The Moon is Earth''s only natural satellite.","translations":{"es":"La Luna es el único satélite natural de la Tierra."}},{"phrase":"Une catastrophe s''est produite hier soir quand une tornade a frappé la côte.","translation":"A disaster happened last night when a tornado hit the coast.","translations":{"es":"Anoche se produjo una catástrofe cuando un tornado golpeó la costa."}},{"phrase":"Le ciel est rempli d''étoiles.","translation":"The sky is full of stars.","translations":{"es":"El cielo está lleno de estrellas."}},{"phrase":"La marée monte, sortez de l''eau, les enfants !","translation":"The tide is coming in, get out of the water, kids!","translations":{"es":"¡La marea está subiendo, salgan del agua, niños!"}},{"phrase":"Je crois avoir vu un OVNI hier soir !","translation":"I think I saw a UFO last night!","translations":{"es":"¡Creo haber visto un ovni anoche!"}},{"phrase":"Faisons du jogging le long de la rive.","translation":"Let''s go jogging along the riverbank.","translations":{"es":"Hagamos footing por la orilla."}},{"phrase":"Elle était assise sur un rocher dans la vallée.","translation":"She was sitting on a rock in the valley.","translations":{"es":"Estaba sentada en una roca en el valle."}},{"phrase":"Combien de temps la Terre met-elle pour tourner sur elle-même ? — Vingt-quatre heures.","translation":"How long does the Earth take to rotate? — Twenty-four hours.","translations":{"es":"¿Cuánto tarda la Tierra en girar sobre sí misma? — Veinticuatro horas."}},{"phrase":"La Grande Ourse est une constellation.","translation":"The Big Dipper is a constellation.","translations":{"es":"La Osa Mayor es una constelación."}},{"phrase":"L''atmosphère protège la Terre des rayons du soleil.","translation":"The atmosphere protects the Earth from the sun''s rays.","translations":{"es":"La atmósfera protege la Tierra de los rayos del sol."}},{"phrase":"Il fait sombre ici. Allume la lumière !","translation":"It''s dark in here. Turn on the light!","translations":{"es":"Aquí está oscuro. ¡Enciende la luz!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How many planets are there in our solar system?","options":["neuf","sept","huit","dix"],"correct":2,"explanation":"Pluton is a dwarf planet since 2006.","translations":{"es":{"question":"¿Cuántos planetas hay en nuestro sistema solar?","explanation":"Plutón es un planeta enano desde 2006."}}},{"id":"2","question":"What is \"un fleuve\"?","options":["a river that flows into the sea","a stream in the mountains","a lake","a waterfall"],"correct":0,"explanation":"La Seine and la Loire are \"fleuves\".","translations":{"es":{"question":"¿Qué es «un fleuve»?","explanation":"El Sena y el Loira son «fleuves».","options":["un río que desemboca en el mar","un arroyo de montaña","un lago","una cascada"]}}},{"id":"3","question":"Complete: \"___ regardant le ciel, j''ai vu une étoile filante.\"","options":["En","Pour","Par","Dans"],"correct":0,"explanation":"Gerund: en + present participle.","translations":{"es":{"question":"Completa: «___ regardant le ciel, j''ai vu une étoile filante.»","explanation":"Gerundio: en + participio presente."}}},{"id":"4","question":"How do you say \"I think I saw a UFO\"?","options":["Je crois que j''avais vu un OVNI demain.","Je crois avoir vu un OVNI.","Je crois voir un OVNI hier.","Je crois un OVNI vu."],"correct":1,"explanation":"Croire + past infinitive (avoir + past participle).","translations":{"es":{"question":"¿Cómo se dice «Creo haber visto un ovni»?","explanation":"Croire + infinitivo compuesto (avoir + participio)."}}},{"id":"5","question":"Complete: \"J''espère qu''il ___ beau demain.\"","options":["fera","faisait","fasse","ferait"],"correct":0,"explanation":"\"Espérer que\" takes the indicative (here the future).","translations":{"es":{"question":"Completa: «J''espère qu''il ___ beau demain.»","explanation":"«Espérer que» lleva indicativo (aquí el futuro)."}}},{"id":"6","question":"Passive: \"Pollution threatens the Earth\" → ?","options":["La Terre est menacée par la pollution.","La Terre menace la pollution.","La pollution est menacée par la Terre.","La Terre a menacé la pollution."],"correct":0,"explanation":"être + past participle + par.","translations":{"es":{"question":"Pasiva: «La contaminación amenaza la Tierra» → ?","explanation":"être + participio + par."}}},{"id":"7","question":"What is \"une grotte\"?","options":["a hill","a cave","a bay","a marsh"],"correct":1,"explanation":"Also \"une caverne\".","translations":{"es":{"question":"¿Qué es «une grotte»?","explanation":"También «une caverne».","options":["una colina","una cueva","una bahía","un pantano"]}}},{"id":"8","question":"Complete: \"Il faut agir ___ protéger la planète.\"","options":["afin de","afin que","parce que","bien que"],"correct":0,"explanation":"\"Afin de\" + infinitive; \"afin que\" + subjunctive.","translations":{"es":{"question":"Completa: «Il faut agir ___ protéger la planète.»","explanation":"«Afin de» + infinitivo; «afin que» + subjuntivo."}}}]}'::jsonb, 3),
  ('story', 'Une nuit à l''observatoire', '{"text":"Pendant les vacances, Jules et sa grand-mère passent une nuit à l''observatoire du Pic du Midi, dans les Pyrénées. En montant en téléphérique, ils voient le paysage changer : les vallées, les lacs, puis les montagnes couvertes de neige. Au sommet, l''air est pur et le ciel est rempli d''étoiles. Une astronome leur montre Jupiter et ses satellites, puis Saturne et ses anneaux. « Saturne est la planète la plus belle du système solaire », dit-elle. Jules regarde la Lune : « On dirait un désert plein de rochers ! » Plus tard, il crie : « Je crois avoir vu un OVNI ! » L''astronome rit : « C''est la Station spatiale internationale. Elle fait le tour de la Terre en quatre-vingt-dix minutes environ. » Avant de dormir, sa grand-mère lui explique que la Terre est menacée par la pollution et qu''il faut agir afin de la protéger. « Espérons que les scientifiques trouveront des solutions », dit Jules. « Et toi aussi, peut-être, un jour ! » répond sa grand-mère.","translation":"During the holidays, Jules and his grandmother spend a night at the Pic du Midi observatory, in the Pyrenees. Going up by cable car, they see the landscape change: the valleys, the lakes, then the snow-covered mountains. At the top, the air is pure and the sky is full of stars. An astronomer shows them Jupiter and its satellites, then Saturn and its rings. “Saturn is the most beautiful planet in the solar system,” she says. Jules looks at the Moon: “It looks like a desert full of rocks!” Later, he shouts: “I think I saw a UFO!” The astronomer laughs: “That''s the International Space Station. It goes around the Earth in about ninety minutes.” Before going to sleep, his grandmother explains that the Earth is threatened by pollution and that we must act in order to protect it. “Let''s hope scientists will find solutions,” says Jules. “And maybe you too, one day!” his grandmother answers.","translations":{"es":"Durante las vacaciones, Jules y su abuela pasan una noche en el observatorio del Pic du Midi, en los Pirineos. Al subir en teleférico, ven cambiar el paisaje: los valles, los lagos y luego las montañas cubiertas de nieve. En la cima, el aire es puro y el cielo está lleno de estrellas. Una astrónoma les enseña Júpiter y sus satélites, y luego Saturno y sus anillos. «Saturno es el planeta más bonito del sistema solar», dice. Jules mira la Luna: «¡Parece un desierto lleno de rocas!». Más tarde, grita: «¡Creo haber visto un ovni!». La astrónoma se ríe: «Es la Estación Espacial Internacional. Da la vuelta a la Tierra en unos noventa minutos.» Antes de dormir, su abuela le explica que la Tierra está amenazada por la contaminación y que hay que actuar para protegerla. «Esperemos que los científicos encuentren soluciones», dice Jules. «¡Y tú también, quizás, algún día!», responde su abuela."},"highlighted_words":["En montant","paysage","rempli d''étoiles","satellites","la plus belle","désert","Je crois avoir vu","est menacée par","afin de","Espérons que"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Le","ciel","est","rempli","d''étoiles"],"translation":"The sky is full of stars","translations":{"es":"El cielo está lleno de estrellas"}},{"words":["La","Lune","tourne","autour","de","la","Terre"],"translation":"The Moon goes around the Earth","translations":{"es":"La Luna gira alrededor de la Tierra"}},{"words":["Je","crois","avoir","vu","une","étoile","filante"],"translation":"I think I saw a shooting star","translations":{"es":"Creo haber visto una estrella fugaz"}},{"words":["Le","Nil","est","un","très","long","fleuve"],"translation":"The Nile is a very long river","translations":{"es":"El Nilo es un río muy largo"}},{"words":["En","marchant","sur","la","plage","j''ai","trouvé","un","coquillage"],"translation":"While walking on the beach I found a shell","translations":{"es":"Paseando por la playa encontré una concha"}},{"words":["Il","faut","protéger","notre","planète"],"translation":"We must protect our planet","translations":{"es":"Hay que proteger nuestro planeta"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"A desert island","translations":{"es":"Una isla desierta"},"answer":"Une île déserte"},{"prompt":"The tide is coming in","translations":{"es":"La marea está subiendo"},"answer":"La marée monte"},{"prompt":"It''s the highest mountain","translations":{"es":"Es la montaña más alta"},"answer":"C''est la plus haute montagne"},{"prompt":"Would you like to travel in space?","translations":{"es":"¿Te gustaría viajar al espacio?"},"answer":"Aimerais-tu voyager dans l''espace ?"},{"prompt":"There was an earthquake","translations":{"es":"Hubo un terremoto"},"answer":"Il y a eu un tremblement de terre"},{"prompt":"The landscape is magnificent","translations":{"es":"El paisaje es magnífico"},"answer":"Le paysage est magnifique"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 20: La ville
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-20', 'La ville', '🏙️', 'La ciudad', 20, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la ville","translation":"the city / town","translations":{"es":"la ciudad"}},{"id":"2","word":"le quartier","translation":"the neighborhood","translations":{"es":"el barrio"}},{"id":"3","word":"le centre-ville","translation":"downtown","translations":{"es":"el centro"}},{"id":"4","word":"un immeuble","translation":"a building (apartments)","translations":{"es":"un edificio (de viviendas)"}},{"id":"5","word":"un bâtiment","translation":"a building","translations":{"es":"un edificio"}},{"id":"6","word":"un gratte-ciel","translation":"a skyscraper","translations":{"es":"un rascacielos"}},{"id":"7","word":"un appartement","translation":"an apartment","translations":{"es":"un apartamento"}},{"id":"8","word":"la rue","translation":"the street","translations":{"es":"la calle"}},{"id":"9","word":"l''avenue","translation":"the avenue","translations":{"es":"la avenida"}},{"id":"10","word":"la place","translation":"the square","translations":{"es":"la plaza"}},{"id":"11","word":"le trottoir","translation":"the sidewalk","translations":{"es":"la acera"}},{"id":"12","word":"le piéton","translation":"the pedestrian","translations":{"es":"el peatón"}},{"id":"13","word":"le feu","translation":"the traffic light","translations":{"es":"el semáforo"}},{"id":"14","word":"un pâté de maisons","translation":"a block","translations":{"es":"una manzana / una cuadra"}},{"id":"15","word":"la circulation","translation":"traffic","translations":{"es":"el tráfico"}},{"id":"16","word":"un embouteillage","translation":"a traffic jam","translations":{"es":"un atasco"}},{"id":"17","word":"l''arrêt de bus","translation":"the bus stop","translations":{"es":"la parada de autobús"}},{"id":"18","word":"le bus","translation":"the bus","translations":{"es":"el autobús"}},{"id":"19","word":"le camion","translation":"the truck","translations":{"es":"el camión"}},{"id":"20","word":"la moto","translation":"the motorbike","translations":{"es":"la moto"}},{"id":"21","word":"le parking","translation":"the parking lot","translations":{"es":"el aparcamiento"}},{"id":"22","word":"la banque","translation":"the bank","translations":{"es":"el banco"}},{"id":"23","word":"la poste","translation":"the post office","translations":{"es":"correos"}},{"id":"24","word":"l''hôpital","translation":"the hospital","translations":{"es":"el hospital"}},{"id":"25","word":"la pharmacie","translation":"the pharmacy","translations":{"es":"la farmacia"}},{"id":"26","word":"l''église","translation":"the church","translations":{"es":"la iglesia"}},{"id":"27","word":"le cinéma","translation":"the cinema","translations":{"es":"el cine"}},{"id":"28","word":"le théâtre","translation":"the theater","translations":{"es":"el teatro"}},{"id":"29","word":"le musée","translation":"the museum","translations":{"es":"el museo"}},{"id":"30","word":"la bibliothèque","translation":"the library","translations":{"es":"la biblioteca"}},{"id":"31","word":"le commissariat","translation":"the police station","translations":{"es":"la comisaría"}},{"id":"32","word":"l''école","translation":"the school","translations":{"es":"la escuela"}},{"id":"33","word":"le marché","translation":"the market","translations":{"es":"el mercado"}},{"id":"34","word":"le supermarché","translation":"the supermarket","translations":{"es":"el supermercado"}},{"id":"35","word":"la boutique","translation":"the shop","translations":{"es":"la tienda"}},{"id":"36","word":"le parc","translation":"the park","translations":{"es":"el parque"}},{"id":"37","word":"les habitants","translation":"the inhabitants","translations":{"es":"los habitantes"}},{"id":"38","word":"le bruit","translation":"noise","translations":{"es":"el ruido"}},{"id":"39","word":"bruyant / bruyante","translation":"noisy","translations":{"es":"ruidoso / ruidosa"}},{"id":"40","word":"la pollution","translation":"pollution","translations":{"es":"la contaminación"}},{"id":"41","word":"dangereux / dangereuse","translation":"dangerous","translations":{"es":"peligroso / peligrosa"}},{"id":"42","word":"sûr / sûre","translation":"safe","translations":{"es":"seguro / segura"}},{"id":"43","word":"les alentours","translation":"the surroundings","translations":{"es":"los alrededores"}},{"id":"44","word":"le nord / le sud","translation":"north / south","translations":{"es":"el norte / el sur"}},{"id":"45","word":"l''est / l''ouest","translation":"east / west","translations":{"es":"el este / el oeste"}}],"grammar":[{"structure":"impératif (itinéraire)","example":"Prenez le bus 59, descendez rue Voltaire, puis tournez à droite.","en":"Giving directions","es":"Dar indicaciones"},{"structure":"devoir (obligation / conseil)","example":"Les voitures doivent s''arrêter. / Les piétons devraient marcher sur le trottoir.","en":"Must / should","es":"Deber / debería"},{"structure":"voix passive (passé, futur proche)","example":"Cette église a été construite en 1880. / Ces immeubles vont être démolis.","en":"Passive in the past and near future","es":"Pasiva en pasado y futuro próximo"},{"structure":"imparfait / présent","example":"Avant, ce quartier était calme ; maintenant, il est bruyant.","en":"Before vs. now","es":"Antes frente a ahora"},{"structure":"pronom « y »","example":"J''aime la ville : on y trouve de tout.","en":"\"y\" replacing a place","es":"«y» que sustituye un lugar"},{"structure":"il y a + durée","example":"Ma famille s''est installée ici il y a cent ans.","en":"\"ago\"","es":"«hace» (tiempo)"},{"structure":"pendant + durée","example":"J''ai attendu le bus pendant une heure.","en":"Duration","es":"Duración"},{"structure":"malgré + nom","example":"Malgré le bruit, j''aime la ville.","en":"\"Despite\"","es":"«A pesar de»"}],"tips":[{"en":"Directions: \"tout droit\" (straight ahead), \"à droite / à gauche\", \"au coin de la rue\", \"en face de\", \"à côté de\", \"au feu\" (at the traffic light).","es":"Indicaciones: «tout droit» (todo recto), «à droite / à gauche», «au coin de la rue», «en face de», «à côté de», «au feu» (en el semáforo)."},{"en":"\"Le feu\" = the traffic light (and also fire). \"Un pâté de maisons\" = a block.","es":"«Le feu» = el semáforo (y también el fuego). «Un pâté de maisons» = una manzana / cuadra."},{"en":"\"Il y a\" + duration = ago: \"il y a deux ans\". \"Depuis\" = since / for (still true now).","es":"«Il y a» + duración = hace: «il y a deux ans». «Depuis» = desde / desde hace (sigue siendo cierto)."},{"en":"Cardinal points: le nord, le sud, l''est, l''ouest.","es":"Puntos cardinales: le nord, le sud, l''est, l''ouest."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Les piétons devraient marcher sur le trottoir.","translation":"Pedestrians should walk on the sidewalk.","translations":{"es":"Los peatones deberían caminar por la acera."}},{"phrase":"Quand le feu est rouge, les voitures doivent s''arrêter.","translation":"When the light is red, cars must stop.","translations":{"es":"Cuando el semáforo está en rojo, los coches deben detenerse."}},{"phrase":"À l''aéroport, s''il vous plaît.","translation":"To the airport, please.","translations":{"es":"Al aeropuerto, por favor."}},{"phrase":"La banque fermera à seize heures.","translation":"The bank will close at 4 p.m.","translations":{"es":"El banco cerrará a las cuatro de la tarde."}},{"phrase":"La pharmacie est à deux rues d''ici.","translation":"The pharmacy is two streets from here.","translations":{"es":"La farmacia está a dos calles de aquí."}},{"phrase":"Cette église a été construite en 1880.","translation":"This church was built in 1880.","translations":{"es":"Esta iglesia fue construida en 1880."}},{"phrase":"J''ai attendu le bus pendant une heure !","translation":"I waited for the bus for an hour!","translations":{"es":"¡Esperé el autobús durante una hora!"}},{"phrase":"Ces vieux immeubles vont être démolis.","translation":"These old buildings are going to be demolished.","translations":{"es":"Estos edificios viejos van a ser demolidos."}},{"phrase":"Avant, cet hôtel était propre ; maintenant, il est bruyant et sale.","translation":"This hotel used to be clean; now it is noisy and dirty.","translations":{"es":"Antes este hotel estaba limpio; ahora es ruidoso y sucio."}},{"phrase":"Le restaurant est en face de la poste.","translation":"The restaurant is opposite the post office.","translations":{"es":"El restaurante está enfrente de correos."}},{"phrase":"Savez-vous où se trouve l''hôpital ? — Au feu, tournez à droite et vous le verrez.","translation":"Do you know where the hospital is? — At the light, turn right and you will see it.","translations":{"es":"¿Sabe dónde está el hospital? — En el semáforo, gire a la derecha y lo verá."}},{"phrase":"Pour aller au musée ? — Prenez le bus 59 et descendez rue Voltaire.","translation":"How do I get to the museum? — Take bus 59 and get off at rue Voltaire.","translations":{"es":"¿Para ir al museo? — Tome el autobús 59 y bájese en la calle Voltaire."}},{"phrase":"Tu es arrivé dix minutes en retard ! — Il y avait un embouteillage.","translation":"You arrived ten minutes late! — There was a traffic jam.","translations":{"es":"¡Llegaste diez minutos tarde! — Había un atasco."}},{"phrase":"Tu habites en ville ? — Non, je préfère habiter à la campagne.","translation":"Do you live in the city? — No, I prefer living in the countryside.","translations":{"es":"¿Vives en la ciudad? — No, prefiero vivir en el campo."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"What does \"le feu\" mean in \"Tournez à droite au feu\"?","options":["the fire","the traffic light","the corner","the bridge"],"correct":1,"explanation":"In the street, \"le feu\" is the traffic light.","translations":{"es":{"question":"¿Qué significa «le feu» en «Tournez à droite au feu»?","explanation":"En la calle, «le feu» es el semáforo.","options":["el fuego","el semáforo","la esquina","el puente"]}}},{"id":"2","question":"Passive past: \"They built this church in 1880\" → ?","options":["Cette église est construire en 1880.","Cette église a construit en 1880.","Cette église a été construite en 1880.","Cette église était construisait en 1880."],"correct":2,"explanation":"avoir été + past participle (agreement with the subject).","translations":{"es":{"question":"Pasiva en pasado: «Construyeron esta iglesia en 1880» → ?","explanation":"avoir été + participio (concuerda con el sujeto)."}}},{"id":"3","question":"Complete: \"J''aime le marché : j''___ vais tous les samedis.\"","options":["le","en","y","lui"],"correct":2,"explanation":"\"Y\" replaces a place (au marché).","translations":{"es":{"question":"Completa: «J''aime le marché : j''___ vais tous les samedis.»","explanation":"«Y» sustituye un lugar (au marché)."}}},{"id":"4","question":"\"Ma famille s''est installée ici il y a cent ans.\" Meaning?","options":["There are a hundred people in my family.","My family will settle here in a hundred years.","My family settled here a hundred years ago.","My family has a hundred-year-old house."],"correct":2,"explanation":"\"Il y a\" + duration = ago.","translations":{"es":{"question":"«Ma famille s''est installée ici il y a cent ans.» ¿Significado?","explanation":"«Il y a» + duración = hace.","options":["Hay cien personas en mi familia.","Mi familia se instalará aquí dentro de cien años.","Mi familia se instaló aquí hace cien años.","Mi familia tiene una casa centenaria."]}}},{"id":"5","question":"Which sentence gives advice (not an obligation)?","options":["Les piétons doivent être prudents.","Les piétons sont prudents.","Les piétons devraient être prudents.","Les piétons seront prudents."],"correct":2,"explanation":"Conditional of \"devoir\" = should.","translations":{"es":{"question":"¿Qué frase da un consejo (no una obligación)?","explanation":"Condicional de «devoir» = debería."}}},{"id":"6","question":"Where do you go to borrow books?","options":["à la bibliothèque","à la poste","à la librairie","au musée"],"correct":0,"explanation":"False friend: \"la librairie\" is a bookshop.","translations":{"es":{"question":"¿Adónde vas a tomar prestados libros?","explanation":"Falso amigo: «la librairie» es una librería (tienda)."}}},{"id":"7","question":"Complete: \"___ le bruit, j''adore Paris.\"","options":["Parce que","Malgré","Bien que","Depuis"],"correct":1,"explanation":"\"Malgré\" + noun; \"bien que\" + subjunctive clause.","translations":{"es":{"question":"Completa: «___ le bruit, j''adore Paris.»","explanation":"«Malgré» + sustantivo; «bien que» + oración en subjuntivo."}}},{"id":"8","question":"What is \"un embouteillage\"?","options":["a parking lot","a traffic jam","a bottle shop","a crossroads"],"correct":1,"explanation":"Also \"un bouchon\" (informal).","translations":{"es":{"question":"¿Qué es «un embouteillage»?","explanation":"También «un bouchon» (coloquial).","options":["un aparcamiento","un atasco","una tienda de botellas","un cruce"]}}}]}'::jsonb, 3),
  ('story', 'Le premier jour de Sami à Lyon', '{"text":"Sami vient d''arriver à Lyon pour son nouveau travail. Il habite dans un petit appartement au cinquième étage d''un vieil immeuble, dans le quartier de la Croix-Rousse. Ce matin, il veut découvrir la ville. Il demande à une voisine : « Excusez-moi, pour aller au musée des Beaux-Arts ? » « Descendez la rue jusqu''à la place, prenez le métro ligne C, puis marchez tout droit pendant cinq minutes. Le musée est en face de l''hôtel de ville, vous ne pouvez pas le manquer. » Dans le métro, Sami regarde le plan. Il y a beaucoup de monde et de bruit. Le musée est magnifique : il a été construit il y a plus de trois cents ans. L''après-midi, il se promène le long du Rhône. Une dame âgée lui raconte : « Avant, ce quartier était plein d''usines ; maintenant, il y a des parcs et des cafés. » Le soir, Sami est fatigué, mais content. Malgré la circulation et les embouteillages, il aime déjà Lyon : on y trouve de tout !","translation":"Sami has just arrived in Lyon for his new job. He lives in a small apartment on the fifth floor of an old building, in the Croix-Rousse neighborhood. This morning, he wants to explore the city. He asks a neighbor: “Excuse me, how do I get to the Fine Arts Museum?” “Go down the street to the square, take metro line C, then walk straight ahead for five minutes. The museum is opposite the town hall, you can''t miss it.” In the metro, Sami looks at the map. There are a lot of people and a lot of noise. The museum is magnificent: it was built more than three hundred years ago. In the afternoon, he walks along the Rhône. An elderly lady tells him: “This area used to be full of factories; now there are parks and cafés.” In the evening, Sami is tired but happy. Despite the traffic and the jams, he already loves Lyon: you can find everything there!","translations":{"es":"Sami acaba de llegar a Lyon por su nuevo trabajo. Vive en un pequeño apartamento en el quinto piso de un edificio antiguo, en el barrio de la Croix-Rousse. Esta mañana quiere descubrir la ciudad. Le pregunta a una vecina: «Disculpe, ¿para ir al Museo de Bellas Artes?» «Baje la calle hasta la plaza, tome el metro línea C y luego camine todo recto durante cinco minutos. El museo está enfrente del ayuntamiento, no tiene pérdida.» En el metro, Sami mira el plano. Hay mucha gente y mucho ruido. El museo es magnífico: fue construido hace más de trescientos años. Por la tarde pasea por la orilla del Ródano. Una señora mayor le cuenta: «Antes este barrio estaba lleno de fábricas; ahora hay parques y cafés.» Por la noche, Sami está cansado pero contento. A pesar del tráfico y los atascos, ya le encanta Lyon: ¡allí se encuentra de todo!"},"highlighted_words":["vient d''arriver","immeuble","quartier","Descendez","prenez","tout droit","en face de","a été construit","il y a","Avant","était","Malgré","on y trouve"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Tournez","à","gauche","au","feu"],"translation":"Turn left at the traffic light","translations":{"es":"Gire a la izquierda en el semáforo"}},{"words":["J''habite","dans","un","appartement"],"translation":"I live in an apartment","translations":{"es":"Vivo en un apartamento"}},{"words":["La","banque","est","en","face","du","parc"],"translation":"The bank is opposite the park","translations":{"es":"El banco está enfrente del parque"}},{"words":["Cette","église","a","été","construite","en","1880"],"translation":"This church was built in 1880","translations":{"es":"Esta iglesia fue construida en 1880"}},{"words":["Il","y","avait","un","embouteillage"],"translation":"There was a traffic jam","translations":{"es":"Había un atasco"}},{"words":["J''aime","Paris","malgré","le","bruit"],"translation":"I love Paris despite the noise","translations":{"es":"Me encanta París a pesar del ruido"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Where is the bus stop?","translations":{"es":"¿Dónde está la parada de autobús?"},"answer":"Où est l''arrêt de bus ?"},{"prompt":"Go straight ahead","translations":{"es":"Siga todo recto"},"answer":"Allez tout droit"},{"prompt":"It''s a dangerous neighborhood","translations":{"es":"Es un barrio peligroso"},"answer":"C''est un quartier dangereux"},{"prompt":"The pharmacy is on the corner","translations":{"es":"La farmacia está en la esquina"},"answer":"La pharmacie est au coin de la rue"},{"prompt":"I prefer the countryside","translations":{"es":"Prefiero el campo"},"answer":"Je préfère la campagne"},{"prompt":"The market is full of people","translations":{"es":"El mercado está lleno de gente"},"answer":"Le marché est plein de gens"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 21: L'heure, le temps et les mesures
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-21', 'L''heure, le temps et les mesures', '⏱️', 'La hora, el tiempo y las medidas', 21, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''heure","translation":"the hour / the time","translations":{"es":"la hora"}},{"id":"2","word":"la minute","translation":"the minute","translations":{"es":"el minuto"}},{"id":"3","word":"la seconde","translation":"the second","translations":{"es":"el segundo"}},{"id":"4","word":"une demi-heure","translation":"half an hour","translations":{"es":"media hora"}},{"id":"5","word":"un quart d''heure","translation":"a quarter of an hour","translations":{"es":"un cuarto de hora"}},{"id":"6","word":"pile","translation":"sharp (time)","translations":{"es":"en punto"}},{"id":"7","word":"la montre","translation":"the watch","translations":{"es":"el reloj (de pulsera)"}},{"id":"8","word":"l''horloge","translation":"the clock","translations":{"es":"el reloj (de pared)"}},{"id":"9","word":"le réveil","translation":"the alarm clock","translations":{"es":"el despertador"}},{"id":"10","word":"les aiguilles","translation":"the hands (of a clock)","translations":{"es":"las agujas"}},{"id":"11","word":"les piles","translation":"batteries","translations":{"es":"las pilas"}},{"id":"12","word":"à l''heure","translation":"on time","translations":{"es":"puntual"}},{"id":"13","word":"en retard","translation":"late","translations":{"es":"tarde / con retraso"}},{"id":"14","word":"en avance","translation":"early","translations":{"es":"temprano / con antelación"}},{"id":"15","word":"le matin","translation":"morning","translations":{"es":"la mañana"}},{"id":"16","word":"le soir","translation":"evening","translations":{"es":"la noche"}},{"id":"17","word":"hier soir","translation":"last night","translations":{"es":"anoche"}},{"id":"18","word":"autrefois","translation":"in the past","translations":{"es":"antiguamente"}},{"id":"19","word":"de temps en temps","translation":"from time to time","translations":{"es":"de vez en cuando"}},{"id":"20","word":"quelquefois","translation":"sometimes","translations":{"es":"a veces"}},{"id":"21","word":"tout le temps","translation":"all the time","translations":{"es":"todo el tiempo"}},{"id":"22","word":"à plein temps / à mi-temps","translation":"full-time / part-time","translations":{"es":"a tiempo completo / a media jornada"}},{"id":"23","word":"les heures supplémentaires","translation":"overtime","translations":{"es":"las horas extra"}},{"id":"24","word":"le décalage horaire","translation":"jet lag / time difference","translations":{"es":"el desfase horario"}},{"id":"25","word":"le mètre","translation":"the meter","translations":{"es":"el metro"}},{"id":"26","word":"le centimètre","translation":"the centimeter","translations":{"es":"el centímetro"}},{"id":"27","word":"le kilomètre","translation":"the kilometer","translations":{"es":"el kilómetro"}},{"id":"28","word":"le kilo","translation":"the kilo","translations":{"es":"el kilo"}},{"id":"29","word":"le gramme","translation":"the gram","translations":{"es":"el gramo"}},{"id":"30","word":"le litre","translation":"the liter","translations":{"es":"el litro"}},{"id":"31","word":"le mètre carré","translation":"the square meter","translations":{"es":"el metro cuadrado"}},{"id":"32","word":"le poids","translation":"the weight","translations":{"es":"el peso"}},{"id":"33","word":"peser","translation":"to weigh","translations":{"es":"pesar"}},{"id":"34","word":"mesurer","translation":"to measure / to be (height)","translations":{"es":"medir"}},{"id":"35","word":"la taille","translation":"the size / the height / the waist","translations":{"es":"la talla / la estatura / la cintura"}},{"id":"36","word":"la longueur","translation":"the length","translations":{"es":"la longitud"}},{"id":"37","word":"la largeur","translation":"the width","translations":{"es":"la anchura"}},{"id":"38","word":"la hauteur","translation":"the height","translations":{"es":"la altura"}},{"id":"39","word":"le thermomètre","translation":"the thermometer","translations":{"es":"el termómetro"}},{"id":"40","word":"la température","translation":"the temperature","translations":{"es":"la temperatura"}},{"id":"41","word":"le degré","translation":"the degree","translations":{"es":"el grado"}},{"id":"42","word":"long / longue","translation":"long","translations":{"es":"largo / larga"}},{"id":"43","word":"court / courte","translation":"short","translations":{"es":"corto / corta"}},{"id":"44","word":"large","translation":"wide","translations":{"es":"ancho"}},{"id":"45","word":"mince","translation":"thin","translations":{"es":"delgado"}}],"grammar":[{"structure":"dire l''heure","example":"Il est midi et demi. / Il est dix heures moins cinq. / Il est quatre heures pile.","en":"Telling the time","es":"Decir la hora"},{"structure":"avancer / retarder","example":"Ta montre a dix minutes d''avance. / Elle retarde de deux heures.","en":"Fast or slow clocks","es":"Relojes adelantados o atrasados"},{"structure":"depuis + présent","example":"Je t''attends depuis une demi-heure.","en":"Ongoing action since / for","es":"Acción que dura desde hace"},{"structure":"après avoir + participe passé","example":"Je me suis couché après avoir lu le livre.","en":"\"After having done\"","es":"«Después de haber»"},{"structure":"devoir au passé composé (probabilité)","example":"J''ai dû oublier de changer les piles.","en":"\"I must have…\"","es":"«Debí de…»"},{"structure":"il faut que + subjonctif","example":"Il faut que la robe soit prête demain.","en":"Necessity + subjunctive","es":"Necesidad + subjuntivo"},{"structure":"mesurer / peser / faire … de long","example":"Elle mesure 1,80 m. Ça pèse deux kilos. La table fait 70 cm de large.","en":"Measurements","es":"Medidas"},{"structure":"il est temps de + infinitif","example":"Il est temps de partir.","en":"\"It''s time to\"","es":"«Es hora de»"}],"tips":[{"en":"In everyday speech: \"deux heures et quart\" (2:15), \"deux heures et demie\" (2:30), \"trois heures moins le quart\" (2:45). Officially, the 24-hour clock is used: \"quatorze heures trente\".","es":"En el habla cotidiana: «deux heures et quart» (2:15), «deux heures et demie» (2:30), «trois heures moins le quart» (2:45). En lo oficial se usa el formato de 24 horas: «quatorze heures trente»."},{"en":"\"Midi et demi\" and \"minuit et demi\" (no -e), but \"une heure et demie\".","es":"«Midi et demi» y «minuit et demi» (sin -e), pero «une heure et demie»."},{"en":"\"Le temps\" = time AND weather; \"une fois\" = one time (occurrence); \"l''heure\" = the clock time.","es":"«Le temps» = el tiempo (duración Y clima); «une fois» = una vez; «l''heure» = la hora."},{"en":"\"Une livre\" = half a kilo (500 g) in France, and also the British pound.","es":"«Une livre» = medio kilo (500 g) en Francia, y también la libra esterlina."},{"en":"\"Le décalage horaire\" = jet lag / time difference.","es":"«Le décalage horaire» = el desfase horario / la diferencia horaria."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Il est temps de se lever !","translation":"It''s time to get up!","translations":{"es":"¡Es hora de levantarse!"}},{"phrase":"Hier soir, je me suis couché après avoir lu un chapitre.","translation":"Last night, I went to bed after reading a chapter.","translations":{"es":"Anoche me acosté después de haber leído un capítulo."}},{"phrase":"Cent centimètres font un mètre.","translation":"A hundred centimeters make a meter.","translations":{"es":"Cien centímetros son un metro."}},{"phrase":"Quelle heure est-il ? — Il est midi et demi.","translation":"What time is it? — It is half past twelve.","translations":{"es":"¿Qué hora es? — Son las doce y media."}},{"phrase":"Il est dix heures moins cinq.","translation":"It is five to ten.","translations":{"es":"Son las diez menos cinco."}},{"phrase":"Ta montre a deux heures de retard.","translation":"Your watch is two hours slow.","translations":{"es":"Tu reloj va dos horas atrasado."}},{"phrase":"On se verra à midi.","translation":"We''ll see each other at noon.","translations":{"es":"Nos veremos a mediodía."}},{"phrase":"Je me lève à six heures et quart tous les matins.","translation":"I get up at a quarter past six every morning.","translations":{"es":"Me levanto a las seis y cuarto todas las mañanas."}},{"phrase":"Achète un litre de lait et une livre de sucre, s''il te plaît.","translation":"Buy a liter of milk and a pound of sugar, please.","translations":{"es":"Compra un litro de leche y medio kilo de azúcar, por favor."}},{"phrase":"Elle mesure un mètre quatre-vingts.","translation":"She is 1.80 m tall.","translations":{"es":"Mide un metro ochenta."}},{"phrase":"Ta montre ne marche pas ? — Non, j''ai dû oublier de changer les piles.","translation":"Your watch isn''t working? — No, I must have forgotten to change the batteries.","translations":{"es":"¿Tu reloj no funciona? — No, debí de olvidarme de cambiar las pilas."}},{"phrase":"Je t''attends depuis une demi-heure ! Qu''est-ce qui s''est passé ?","translation":"I''ve been waiting for you for half an hour! What happened?","translations":{"es":"¡Te estoy esperando desde hace media hora! ¿Qué ha pasado?"}},{"phrase":"Cet appartement fait quatre-vingts mètres carrés.","translation":"This apartment is eighty square meters.","translations":{"es":"Este apartamento tiene ochenta metros cuadrados."}},{"phrase":"Combien mesure cette table ? — Soixante-dix centimètres de large et un mètre vingt de long.","translation":"How big is this table? — Seventy centimeters wide and 1.20 m long.","translations":{"es":"¿Cuánto mide esta mesa? — Setenta centímetros de ancho y un metro veinte de largo."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you say 2:45 in everyday French?","options":["trois heures et quart","deux heures et quart","trois heures moins le quart","deux heures moins le quart"],"correct":2,"explanation":"Moins le quart = quarter to.","translations":{"es":{"question":"¿Cómo se dice 2:45 en el francés cotidiano?","explanation":"Moins le quart = menos cuarto."}}},{"id":"2","question":"Which is correct?","options":["Il est midi et moitié.","Il est midi demi.","Il est midi et demi.","Il est midi et demie."],"correct":2,"explanation":"\"Midi\" is masculine: \"et demi\".","translations":{"es":{"question":"¿Cuál es correcta?","explanation":"«Midi» es masculino: «et demi»."}}},{"id":"3","question":"\"Ma montre avance de dix minutes.\" Meaning?","options":["I am ten minutes early.","My watch stopped ten minutes ago.","My watch is ten minutes fast.","My watch is ten minutes slow."],"correct":2,"explanation":"Avancer = to be fast; retarder = to be slow.","translations":{"es":{"question":"«Ma montre avance de dix minutes.» ¿Significado?","explanation":"Avancer = adelantarse; retarder = atrasarse.","options":["Llego diez minutos antes.","Mi reloj se paró hace diez minutos.","Mi reloj va diez minutos adelantado.","Mi reloj va diez minutos atrasado."]}}},{"id":"4","question":"Complete: \"Je t''attends ___ vingt minutes.\"","options":["il y a","depuis","pour","pendant"],"correct":1,"explanation":"\"Depuis\" + present = still waiting now.","translations":{"es":{"question":"Completa: «Je t''attends ___ vingt minutes.»","explanation":"«Depuis» + presente = todavía esperando."}}},{"id":"5","question":"Complete: \"Je me suis couché après ___ lu le livre.\"","options":["ai","avoir","avais","être"],"correct":1,"explanation":"Après + past infinitive.","translations":{"es":{"question":"Completa: «Je me suis couché après ___ lu le livre.»","explanation":"Après + infinitivo compuesto."}}},{"id":"6","question":"\"J''ai dû oublier mes clés.\" What does it express?","options":["a probable past fact","a wish","an order","a future obligation"],"correct":0,"explanation":"Devoir in the passé composé often means \"must have\".","translations":{"es":{"question":"«J''ai dû oublier mes clés.» ¿Qué expresa?","explanation":"«Devoir» en passé composé suele significar «debí de».","options":["un hecho pasado probable","un deseo","una orden","una obligación futura"]}}},{"id":"7","question":"Complete: \"Il faut que la robe ___ prête demain.\"","options":["sera","soit","serait","est"],"correct":1,"explanation":"\"Il faut que\" + subjunctive.","translations":{"es":{"question":"Completa: «Il faut que la robe ___ prête demain.»","explanation":"«Il faut que» + subjuntivo."}}},{"id":"8","question":"How much is \"une livre\" in a French market?","options":["100 grammes","500 grammes","250 grammes","1 kilo"],"correct":1,"explanation":"Une livre = half a kilo.","translations":{"es":{"question":"¿Cuánto es «une livre» en un mercado francés?","explanation":"Une livre = medio kilo."}}}]}'::jsonb, 3),
  ('story', 'Chaque minute compte', '{"text":"Je m''appelle Clémence Roy et je suis pâtissière dans un grand hôtel à Paris. Dans mon métier, le temps et les mesures sont essentiels. Si une recette demande deux cent cinquante grammes de farine et un demi-litre de lait, je dois tout peser exactement. Il faut aussi que la température du four soit parfaite : cent quatre-vingts degrés, pas un de plus ! Je me lève tous les jours à quatre heures et quart, mais quelquefois, je n''entends pas mon réveil. Hier, j''ai dû oublier de changer les piles, et je suis arrivée vingt minutes en retard ! Ce mois-ci, nous préparons un gâteau de mariage de un mètre cinquante de haut. Le chef m''attend depuis ce matin pour la décoration. De temps en temps, je voyage pour des concours à l''étranger. Après avoir passé dix heures dans l''avion, le décalage horaire est terrible. Mais j''adore mon travail : quand je vois le sourire des clients, je sais que chaque minute compte.","translation":"My name is Clémence Roy and I''m a pastry chef in a big hotel in Paris. In my job, time and measurements are essential. If a recipe calls for two hundred and fifty grams of flour and half a liter of milk, I have to weigh everything exactly. The oven temperature also has to be perfect: a hundred and eighty degrees, not one more! I get up every day at a quarter past four, but sometimes I don''t hear my alarm clock. Yesterday, I must have forgotten to change the batteries, and I arrived twenty minutes late! This month, we are making a wedding cake one meter fifty tall. The chef has been waiting for me since this morning for the decoration. From time to time, I travel abroad for competitions. After spending ten hours on the plane, the jet lag is terrible. But I love my job: when I see the customers'' smiles, I know every minute counts.","translations":{"es":"Me llamo Clémence Roy y soy pastelera en un gran hotel de París. En mi oficio, el tiempo y las medidas son esenciales. Si una receta pide doscientos cincuenta gramos de harina y medio litro de leche, tengo que pesarlo todo con exactitud. También hace falta que la temperatura del horno sea perfecta: ¡ciento ochenta grados, ni uno más! Me levanto todos los días a las cuatro y cuarto, pero a veces no oigo el despertador. Ayer debí de olvidarme de cambiar las pilas, ¡y llegué veinte minutos tarde! Este mes estamos preparando un pastel de boda de un metro cincuenta de alto. El chef me está esperando desde esta mañana para la decoración. De vez en cuando viajo al extranjero para concursos. Después de pasar diez horas en el avión, el desfase horario es terrible. Pero me encanta mi trabajo: cuando veo la sonrisa de los clientes, sé que cada minuto cuenta."},"highlighted_words":["grammes","demi-litre","peser","Il faut aussi que","soit","degrés","quatre heures et quart","j''ai dû oublier","en retard","depuis","Après avoir passé","décalage horaire"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Il","est","deux","heures","et","demie"],"translation":"It is half past two","translations":{"es":"Son las dos y media"}},{"words":["Ma","montre","a","dix","minutes","de","retard"],"translation":"My watch is ten minutes slow","translations":{"es":"Mi reloj va diez minutos atrasado"}},{"words":["Je","t''attends","depuis","une","heure"],"translation":"I''ve been waiting for you for an hour","translations":{"es":"Te espero desde hace una hora"}},{"words":["Il","est","temps","de","partir"],"translation":"It''s time to leave","translations":{"es":"Es hora de irse"}},{"words":["Elle","mesure","un","mètre","soixante"],"translation":"She is one meter sixty tall","translations":{"es":"Mide un metro sesenta"}},{"words":["Je","suis","arrivé","en","retard"],"translation":"I arrived late","translations":{"es":"Llegué tarde"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"What time is it?","translations":{"es":"¿Qué hora es?"},"answer":"Quelle heure est-il ?"},{"prompt":"It is midnight","translations":{"es":"Es medianoche"},"answer":"Il est minuit"},{"prompt":"How much do you weigh?","translations":{"es":"¿Cuánto pesas?"},"answer":"Combien pèses-tu ?"},{"prompt":"From time to time","translations":{"es":"De vez en cuando"},"answer":"De temps en temps"},{"prompt":"It''s four o''clock sharp","translations":{"es":"Son las cuatro en punto"},"answer":"Il est quatre heures pile"},{"prompt":"It weighs two kilos","translations":{"es":"Pesa dos kilos"},"answer":"Ça pèse deux kilos"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 22: Les vacances
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-22', 'Les vacances', '🏖️', 'Las vacaciones', 22, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"les vacances","translation":"the holidays / vacation","translations":{"es":"las vacaciones"}},{"id":"2","word":"la plage","translation":"the beach","translations":{"es":"la playa"}},{"id":"3","word":"le sable","translation":"sand","translations":{"es":"la arena"}},{"id":"4","word":"la vague","translation":"the wave","translations":{"es":"la ola"}},{"id":"5","word":"la mer","translation":"the sea","translations":{"es":"el mar"}},{"id":"6","word":"la piscine","translation":"the swimming pool","translations":{"es":"la piscina"}},{"id":"7","word":"nager","translation":"to swim","translations":{"es":"nadar"}},{"id":"8","word":"bronzé / bronzée","translation":"tanned","translations":{"es":"bronceado / bronceada"}},{"id":"9","word":"la crème solaire","translation":"sunscreen","translations":{"es":"el protector solar"}},{"id":"10","word":"les lunettes de soleil","translation":"sunglasses","translations":{"es":"las gafas de sol"}},{"id":"11","word":"le parasol","translation":"the beach umbrella","translations":{"es":"la sombrilla"}},{"id":"12","word":"le château de sable","translation":"sandcastle","translations":{"es":"el castillo de arena"}},{"id":"13","word":"le seau","translation":"the bucket","translations":{"es":"el cubo"}},{"id":"14","word":"le camping","translation":"campsite / camping","translations":{"es":"el camping"}},{"id":"15","word":"la tente","translation":"the tent","translations":{"es":"la tienda de campaña"}},{"id":"16","word":"le sac de couchage","translation":"the sleeping bag","translations":{"es":"el saco de dormir"}},{"id":"17","word":"la caravane","translation":"the caravan","translations":{"es":"la caravana"}},{"id":"18","word":"la valise","translation":"the suitcase","translations":{"es":"la maleta"}},{"id":"19","word":"le passeport","translation":"the passport","translations":{"es":"el pasaporte"}},{"id":"20","word":"voyager","translation":"to travel","translations":{"es":"viajar"}},{"id":"21","word":"conduire","translation":"to drive","translations":{"es":"conducir / manejar"}},{"id":"22","word":"prendre l''avion","translation":"to fly","translations":{"es":"tomar el avión"}},{"id":"23","word":"visiter","translation":"to visit (a place)","translations":{"es":"visitar"}},{"id":"24","word":"parcourir","translation":"to travel around","translations":{"es":"recorrer"}},{"id":"25","word":"se reposer","translation":"to rest","translations":{"es":"descansar"}},{"id":"26","word":"s''amuser","translation":"to have fun","translations":{"es":"divertirse"}},{"id":"27","word":"s''ennuyer","translation":"to be bored","translations":{"es":"aburrirse"}},{"id":"28","word":"faire la fête","translation":"to party","translations":{"es":"ir de fiesta"}},{"id":"29","word":"faire des achats","translation":"to go shopping","translations":{"es":"ir de compras"}},{"id":"30","word":"la glace","translation":"ice cream","translations":{"es":"el helado"}},{"id":"31","word":"les glaçons","translation":"ice cubes","translations":{"es":"los cubitos de hielo"}},{"id":"32","word":"ensoleillé / ensoleillée","translation":"sunny","translations":{"es":"soleado / soleada"}},{"id":"33","word":"il y a du vent","translation":"it''s windy","translations":{"es":"hace viento"}},{"id":"34","word":"il pleut","translation":"it''s raining","translations":{"es":"llueve"}},{"id":"35","word":"ennuyeux / ennuyeuse","translation":"boring","translations":{"es":"aburrido / aburrida"}},{"id":"36","word":"génial","translation":"great / awesome","translations":{"es":"genial"}}],"grammar":[{"structure":"futur proche / futur simple","example":"Je vais parcourir la Bretagne. / Je resterai à la maison. / Nous dormirons sous la tente.","en":"Talking about plans","es":"Hablar de planes"},{"structure":"superlatif","example":"C''est la plage la plus belle de la région. / C''est la journée la plus chaude de l''année.","en":"Superlatives","es":"Superlativos"},{"structure":"pronoms possessifs","example":"Mes enfants font des châteaux de sable ; les miens jouent dans les vagues.","en":"Possessive pronouns (le mien, les miens…)","es":"Pronombres posesivos (el mío, los míos…)"},{"structure":"conditionnel","example":"Ça serait parfait ! / On pourrait aller danser.","en":"Conditional (suggestions)","es":"Condicional (sugerencias)"},{"structure":"pronoms « y » et « en »","example":"J''aimerais y aller. / Des lunettes ? En voulez-vous une paire ?","en":"\"y\" and \"en\"","es":"«y» y «en»"},{"structure":"imparfait (souvenir, intention)","example":"Tu adorais ça. / J''allais oublier ! / Je voulais savoir si…","en":"Imperfect for memories and politeness","es":"Imperfecto para recuerdos y cortesía"},{"structure":"avoir envie de","example":"J''ai très envie de te voir.","en":"\"To feel like / to really want\"","es":"«Tener ganas de»"}],"tips":[{"en":"\"Partir en vacances\" = to go on holiday; \"être en vacances\" = to be on holiday. \"Les vacances\" is always plural.","es":"«Partir en vacances» = irse de vacaciones; «être en vacances» = estar de vacaciones. «Les vacances» va siempre en plural."},{"en":"\"Il pleut à verse / des cordes\" = it''s pouring.","es":"«Il pleut à verse / des cordes» = llueve a cántaros."},{"en":"\"J''allais oublier !\" = I almost forgot! (imparfait of \"aller\" + infinitive).","es":"«J''allais oublier !» = ¡Casi se me olvida! (imperfecto de «aller» + infinitivo)."},{"en":"\"Sortir en boîte\" = to go clubbing (informal).","es":"«Sortir en boîte» = salir de discotecas (coloquial)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"C''était un jour ensoleillé : il n''y avait pas un nuage.","translation":"It was a sunny day: there wasn''t a cloud.","translations":{"es":"Era un día soleado: no había ni una nube."}},{"phrase":"Il pleut à verse !","translation":"It''s pouring!","translations":{"es":"¡Llueve a cántaros!"}},{"phrase":"C''est la plage la plus belle de la région.","translation":"It''s the most beautiful beach in the region.","translations":{"es":"Es la playa más bonita de la región."}},{"phrase":"Il y a beaucoup de vent, prends un pull.","translation":"It''s very windy, take a sweater.","translations":{"es":"Hace mucho viento, llévate un jersey."}},{"phrase":"C''est la journée la plus chaude de l''année !","translation":"It''s the hottest day of the year!","translations":{"es":"¡Es el día más caluroso del año!"}},{"phrase":"Que vas-tu faire pendant les vacances ? — Je vais parcourir la Bretagne.","translation":"What are you going to do during the holidays? — I''m going to travel around Brittany.","translations":{"es":"¿Qué vas a hacer en vacaciones? — Voy a recorrer Bretaña."}},{"phrase":"Moi, je resterai à la maison : j''ai beaucoup de travail.","translation":"As for me, I''ll stay home: I have a lot of work.","translations":{"es":"Yo me quedaré en casa: tengo mucho trabajo."}},{"phrase":"Nous dormirons sous la tente.","translation":"We will sleep in the tent.","translations":{"es":"Dormiremos en la tienda de campaña."}},{"phrase":"Mes enfants font des châteaux de sable ; les miens jouent avec les vagues.","translation":"My children are building sandcastles; mine are playing in the waves.","translations":{"es":"Mis hijos hacen castillos de arena; los míos juegan con las olas."}},{"phrase":"Tu es bronzé ! D''où viens-tu ? — J''étais en vacances en Corse.","translation":"You''re tanned! Where have you been? — I was on holiday in Corsica.","translations":{"es":"¡Estás bronceado! ¿De dónde vienes? — Estaba de vacaciones en Córcega."}},{"phrase":"Vous êtes allés à Nice en voiture ? — Non, on a pris l''avion.","translation":"Did you drive to Nice? — No, we flew.","translations":{"es":"¿Fueron a Niza en coche? — No, tomamos el avión."}},{"phrase":"Tu voudrais une glace ? — Ça serait parfait, il fait très chaud !","translation":"Would you like an ice cream? — That would be perfect, it''s very hot!","translations":{"es":"¿Quieres un helado? — ¡Sería perfecto, hace mucho calor!"}},{"phrase":"Je vends des lunettes de soleil. En voulez-vous une paire ?","translation":"I sell sunglasses. Would you like a pair?","translations":{"es":"Vendo gafas de sol. ¿Quiere un par?"}},{"phrase":"La ville est ennuyeuse pendant les vacances. — C''est toi qui t''ennuies !","translation":"The city is boring during the holidays. — You''re the one who''s bored!","translations":{"es":"La ciudad es aburrida en vacaciones. — ¡Eres tú quien se aburre!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Which sentence is about a near future plan?","options":["J''ai visité Rome.","Je visiterais Rome.","Je vais visiter Rome.","Je visitais Rome."],"correct":2,"explanation":"Aller + infinitive = near future.","translations":{"es":{"question":"¿Qué frase habla de un plan en futuro próximo?","explanation":"Aller + infinitivo = futuro próximo."}}},{"id":"2","question":"Complete: \"Tes enfants sont à la plage ? Les ___ sont à la piscine.\"","options":["miens","moi","mes","mien"],"correct":0,"explanation":"Possessive pronoun, masculine plural: les miens.","translations":{"es":{"question":"Completa: «Tes enfants sont à la plage ? Les ___ sont à la piscine.»","explanation":"Pronombre posesivo, masculino plural: les miens."}}},{"id":"3","question":"Complete: \"Londres ? J''aimerais ___ aller.\"","options":["y","là","en","le"],"correct":0,"explanation":"\"Y\" replaces a place.","translations":{"es":{"question":"Completa: «Londres ? J''aimerais ___ aller.»","explanation":"«Y» sustituye un lugar."}}},{"id":"4","question":"\"J''allais oublier !\" means…","options":["I never forget!","I almost forgot!","I will forget!","I forgot yesterday!"],"correct":1,"explanation":"Imparfait of \"aller\" + infinitive.","translations":{"es":{"question":"«J''allais oublier !» significa…","explanation":"Imperfecto de «aller» + infinitivo.","options":["¡Nunca olvido!","¡Casi se me olvida!","¡Lo olvidaré!","¡Lo olvidé ayer!"]}}},{"id":"5","question":"How do you suggest \"We could go dancing\"?","options":["On pouvait aller danser demain.","On pourrait aller danser.","On peut allé danser.","On pourra danser hier."],"correct":1,"explanation":"Conditional of \"pouvoir\" for suggestions.","translations":{"es":{"question":"¿Cómo sugieres «Podríamos ir a bailar»?","explanation":"Condicional de «pouvoir» para sugerencias."}}},{"id":"6","question":"What do you sleep in when camping?","options":["un sac de couchage","un seau","une valise","un parasol"],"correct":0,"explanation":"Sac de couchage = sleeping bag.","translations":{"es":{"question":"¿En qué duermes cuando acampas?","explanation":"Sac de couchage = saco de dormir."}}},{"id":"7","question":"Complete: \"C''est la journée ___ chaude de l''année.\"","options":["plus","la plus","très","le plus"],"correct":1,"explanation":"Superlative: la plus + adjective + de.","translations":{"es":{"question":"Completa: «C''est la journée ___ chaude de l''année.»","explanation":"Superlativo: la plus + adjetivo + de."}}},{"id":"8","question":"\"J''ai envie de te voir.\" Meaning?","options":["I''m jealous of you.","I really want to see you.","I have to see you.","I saw you."],"correct":1,"explanation":"\"Avoir envie de\" = to feel like / to want. (False friend!)","translations":{"es":{"question":"«J''ai envie de te voir.» ¿Significado?","explanation":"«Avoir envie de» = tener ganas de. (¡Falso amigo de «envidia»!)","options":["Te tengo envidia.","Tengo ganas de verte.","Tengo que verte.","Te vi."]}}}]}'::jsonb, 3),
  ('story', 'Lettre à Lucie', '{"text":"Chère Lucie, ça y est, j''ai enfin fini mes examens et j''ai très envie de te voir ! Ma mère m''a dit que je dois refaire mon passeport cette semaine pour pouvoir partir à Lisbonne samedi prochain. Il fait beau là-bas en ce moment ? À vrai dire, ça m''est égal : tout ce que je veux, c''est être avec toi. Je voudrais visiter le vieux quartier de l''Alfama, les musées et la tour de Belém. Et j''aimerais aussi passer quelques jours sur les plages de l''Algarve. On pourrait louer une voiture et dormir au camping, comme l''été dernier en Bretagne, tu te souviens ? Le soir de mon arrivée, on pourrait sortir dîner et écouter du fado. Tu me manques beaucoup ! Ah, j''allais oublier : Mathis m''a parlé d''un petit marché où on vend les meilleurs pastéis de nata de la ville. J''aimerais y aller le premier matin. Je voulais aussi savoir si tu as encore ton vieux sac de couchage, parce que le mien est cassé. Je t''apporterai des caramels au beurre salé : je sais que tu adorais ça quand on était petites. À très bientôt ! Bisous, Manon.","translation":"Dear Lucie, that''s it, I''ve finally finished my exams and I really want to see you! My mother told me I have to renew my passport this week so I can leave for Lisbon next Saturday. Is the weather nice there at the moment? To be honest, I don''t mind: all I want is to be with you. I would like to visit the old Alfama district, the museums and the Belém Tower. And I would also like to spend a few days on the beaches of the Algarve. We could rent a car and sleep at a campsite, like last summer in Brittany, remember? On the evening I arrive, we could go out for dinner and listen to some fado. I miss you a lot! Oh, I almost forgot: Mathis told me about a little market where they sell the best pastéis de nata in town. I would like to go there the first morning. I also wanted to know if you still have your old sleeping bag, because mine is broken. I''ll bring you some salted-butter caramels: I know you loved them when we were little. See you very soon! Love, Manon.","translations":{"es":"Querida Lucie: ¡por fin he terminado los exámenes y tengo muchas ganas de verte! Mi madre me ha dicho que tengo que renovar el pasaporte esta semana para poder irme a Lisboa el sábado que viene. ¿Hace buen tiempo allí ahora? A decir verdad, me da igual: lo único que quiero es estar contigo. Me gustaría visitar el viejo barrio de la Alfama, los museos y la torre de Belém. Y también me gustaría pasar unos días en las playas del Algarve. Podríamos alquilar un coche y dormir en un camping, como el verano pasado en Bretaña, ¿te acuerdas? La noche que llegue, podríamos salir a cenar y escuchar fado. ¡Te extraño mucho! Ah, casi se me olvida: Mathis me ha hablado de un pequeño mercado donde venden los mejores pastéis de nata de la ciudad. Me gustaría ir la primera mañana. También quería saber si todavía tienes tu viejo saco de dormir, porque el mío está roto. Te llevaré caramelos de mantequilla salada: sé que te encantaban cuando éramos pequeñas. ¡Hasta muy pronto! Besos, Manon."},"highlighted_words":["j''ai très envie de","je dois","Je voudrais","j''aimerais","On pourrait","Tu me manques","j''allais oublier","les meilleurs","y aller","Je voulais aussi savoir","le mien","tu adorais"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","vais","partir","en","vacances"],"translation":"I''m going to go on holiday","translations":{"es":"Me voy a ir de vacaciones"}},{"words":["Nous","dormirons","sous","la","tente"],"translation":"We will sleep in the tent","translations":{"es":"Dormiremos en la tienda de campaña"}},{"words":["C''est","la","plus","belle","plage"],"translation":"It''s the most beautiful beach","translations":{"es":"Es la playa más bonita"}},{"words":["On","pourrait","aller","nager"],"translation":"We could go swimming","translations":{"es":"Podríamos ir a nadar"}},{"words":["J''ai","très","envie","de","te","voir"],"translation":"I really want to see you","translations":{"es":"Tengo muchas ganas de verte"}},{"words":["Le","mien","est","cassé"],"translation":"Mine is broken","translations":{"es":"El mío está roto"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"It''s pouring","translations":{"es":"Llueve a cántaros"},"answer":"Il pleut à verse"},{"prompt":"Let''s go swimming","translations":{"es":"Vamos a nadar"},"answer":"Allons nager"},{"prompt":"I need a swimsuit","translations":{"es":"Necesito un bañador"},"answer":"J''ai besoin d''un maillot de bain"},{"prompt":"You are tanned","translations":{"es":"Estás bronceado"},"answer":"Tu es bronzé"},{"prompt":"I will stay home","translations":{"es":"Me quedaré en casa"},"answer":"Je resterai à la maison"},{"prompt":"That would be perfect","translations":{"es":"Sería perfecto"},"answer":"Ça serait parfait"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 23: Les saisons et la météo
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-23', 'Les saisons et la météo', '🌦️', 'Las estaciones y el tiempo', 23, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le printemps","translation":"spring","translations":{"es":"la primavera"}},{"id":"2","word":"l''été","translation":"summer","translations":{"es":"el verano"}},{"id":"3","word":"l''automne","translation":"autumn / fall","translations":{"es":"el otoño"}},{"id":"4","word":"l''hiver","translation":"winter","translations":{"es":"el invierno"}},{"id":"5","word":"la saison","translation":"the season","translations":{"es":"la estación"}},{"id":"6","word":"le climat","translation":"the climate","translations":{"es":"el clima"}},{"id":"7","word":"la météo","translation":"the weather forecast","translations":{"es":"el pronóstico del tiempo"}},{"id":"8","word":"le soleil","translation":"the sun","translations":{"es":"el sol"}},{"id":"9","word":"ensoleillé / ensoleillée","translation":"sunny","translations":{"es":"soleado / soleada"}},{"id":"10","word":"le nuage","translation":"the cloud","translations":{"es":"la nube"}},{"id":"11","word":"nuageux / nuageuse","translation":"cloudy","translations":{"es":"nublado / nublada"}},{"id":"12","word":"dégagé / dégagée","translation":"clear (sky)","translations":{"es":"despejado / despejada"}},{"id":"13","word":"la pluie","translation":"rain","translations":{"es":"la lluvia"}},{"id":"14","word":"pleuvoir","translation":"to rain","translations":{"es":"llover"}},{"id":"15","word":"la neige","translation":"snow","translations":{"es":"la nieve"}},{"id":"16","word":"neiger","translation":"to snow","translations":{"es":"nevar"}},{"id":"17","word":"la glace","translation":"ice","translations":{"es":"el hielo"}},{"id":"18","word":"geler","translation":"to freeze","translations":{"es":"helar"}},{"id":"19","word":"gelé / gelée","translation":"frozen","translations":{"es":"congelado / congelada"}},{"id":"20","word":"fondre","translation":"to melt","translations":{"es":"derretirse"}},{"id":"21","word":"le brouillard","translation":"fog","translations":{"es":"la niebla"}},{"id":"22","word":"la brume","translation":"mist","translations":{"es":"la bruma"}},{"id":"23","word":"le vent","translation":"wind","translations":{"es":"el viento"}},{"id":"24","word":"l''orage","translation":"thunderstorm","translations":{"es":"la tormenta"}},{"id":"25","word":"la tempête","translation":"the storm","translations":{"es":"la tempestad"}},{"id":"26","word":"le tonnerre","translation":"thunder","translations":{"es":"el trueno"}},{"id":"27","word":"l''éclair","translation":"lightning flash","translations":{"es":"el relámpago"}},{"id":"28","word":"la foudre","translation":"lightning (strike)","translations":{"es":"el rayo"}},{"id":"29","word":"l''arc-en-ciel","translation":"rainbow","translations":{"es":"el arcoíris"}},{"id":"30","word":"l''inondation","translation":"flood","translations":{"es":"la inundación"}},{"id":"31","word":"l''ouragan","translation":"hurricane","translations":{"es":"el huracán"}},{"id":"32","word":"les dégâts","translation":"damage","translations":{"es":"los daños"}},{"id":"33","word":"le degré","translation":"degree","translations":{"es":"el grado"}},{"id":"34","word":"la chaleur","translation":"heat","translations":{"es":"el calor"}},{"id":"35","word":"chaud / chaude","translation":"hot","translations":{"es":"caliente / caluroso"}},{"id":"36","word":"froid / froide","translation":"cold","translations":{"es":"frío / fría"}},{"id":"37","word":"frais / fraîche","translation":"cool / fresh","translations":{"es":"fresco / fresca"}},{"id":"38","word":"doux / douce","translation":"mild","translations":{"es":"templado / suave"}},{"id":"39","word":"humide","translation":"humid / damp","translations":{"es":"húmedo"}},{"id":"40","word":"sec / sèche","translation":"dry","translations":{"es":"seco / seca"}},{"id":"41","word":"mouillé / mouillée","translation":"wet","translations":{"es":"mojado / mojada"}},{"id":"42","word":"trempé / trempée","translation":"soaked","translations":{"es":"empapado / empapada"}},{"id":"43","word":"frileux / frileuse","translation":"sensitive to cold","translations":{"es":"friolero / friolera"}},{"id":"44","word":"se calmer","translation":"to calm down","translations":{"es":"calmarse"}},{"id":"45","word":"avoir peur","translation":"to be afraid","translations":{"es":"tener miedo"}},{"id":"46","word":"le parapluie","translation":"the umbrella","translations":{"es":"el paraguas"}},{"id":"47","word":"la couverture","translation":"the blanket","translations":{"es":"la manta"}}],"grammar":[{"structure":"expressions de la météo","example":"Il fait froid. Il pleut. Il y a du brouillard. Le ciel est dégagé.","en":"Weather expressions","es":"Expresiones del tiempo"},{"structure":"futur simple","example":"Ce mois-ci, le temps sera terrible. / L''avion n''arrivera pas à l''heure.","en":"Forecasts with the future","es":"Previsiones con el futuro"},{"structure":"impératif (négatif)","example":"Calme-toi. Ne sors pas ! Ferme les fenêtres.","en":"Imperative","es":"Imperativo"},{"structure":"passé composé / imparfait (récit)","example":"Je marchais sous la pluie quand j''ai levé la tête.","en":"Narrating: background vs. event","es":"Narrar: fondo frente a hecho"},{"structure":"plus-que-parfait","example":"J''étais triste parce que j''avais raté mon train.","en":"Past perfect (had done)","es":"Pluscuamperfecto (había hecho)"},{"structure":"comme si + plus-que-parfait","example":"C''était comme si nous nous étions toujours connus.","en":"\"As if\" + past perfect","es":"«Como si» + pluscuamperfecto"},{"structure":"conditionnel (futur dans le passé)","example":"Je ne savais pas que cet homme serait mon mari.","en":"Future in the past","es":"Futuro en el pasado"},{"structure":"il y a + durée","example":"Je l''ai rencontré il y a dix ans.","en":"\"ago\"","es":"«hace» (tiempo)"}],"tips":[{"en":"Most weather expressions use \"il fait\": il fait beau / chaud / froid / frais / doux. But: il pleut, il neige, il y a du vent / du brouillard.","es":"La mayoría de las expresiones del tiempo usan «il fait»: il fait beau / chaud / froid / frais / doux. Pero: il pleut, il neige, il y a du vent / du brouillard."},{"en":"Seasons: \"au printemps\", but \"en été\", \"en automne\", \"en hiver\".","es":"Estaciones: «au printemps», pero «en été», «en automne», «en hiver»."},{"en":"\"Frileux / frileuse\" = someone who feels the cold easily.","es":"«Frileux / frileuse» = friolero / friolera."},{"en":"\"Trempé\" = soaked; \"être trempé jusqu''aux os\" = to be soaked to the bone.","es":"«Trempé» = empapado; «être trempé jusqu''aux os» = estar calado hasta los huesos."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Dans certains pays, il y a quatre saisons : le printemps, l''été, l''automne et l''hiver.","translation":"In some countries, there are four seasons: spring, summer, autumn and winter.","translations":{"es":"En algunos países hay cuatro estaciones: primavera, verano, otoño e invierno."}},{"phrase":"L''hiver est la saison la plus froide.","translation":"Winter is the coldest season.","translations":{"es":"El invierno es la estación más fría."}},{"phrase":"Le ciel est dégagé.","translation":"The sky is clear.","translations":{"es":"El cielo está despejado."}},{"phrase":"Une inondation en Bretagne a laissé beaucoup de gens sans abri.","translation":"A flood in Brittany left many people homeless.","translations":{"es":"Una inundación en Bretaña dejó a mucha gente sin hogar."}},{"phrase":"Quand le soleil et la pluie sont ensemble, l''arc-en-ciel apparaît.","translation":"When sun and rain come together, the rainbow appears.","translations":{"es":"Cuando el sol y la lluvia coinciden, aparece el arcoíris."}},{"phrase":"Cet éclair m''a fait peur ! — Calme-toi.","translation":"That lightning scared me! — Calm down.","translations":{"es":"¡Ese relámpago me ha asustado! — Cálmate."}},{"phrase":"Je suis gelée, allume le chauffage !","translation":"I''m freezing, turn on the heating!","translations":{"es":"¡Estoy congelada, enciende la calefacción!"}},{"phrase":"Ce mois-ci, le temps sera terrible à cause d''un vent froid du nord.","translation":"This month, the weather will be terrible because of a cold north wind.","translations":{"es":"Este mes el tiempo será terrible por un viento frío del norte."}},{"phrase":"On dirait qu''il va pleuvoir. — Bien sûr, nous sommes en novembre !","translation":"It looks like it''s going to rain. — Of course, it''s November!","translations":{"es":"Parece que va a llover. — ¡Claro, estamos en noviembre!"}},{"phrase":"Ne sors pas : il y a un mètre de neige !","translation":"Don''t go out: there''s a meter of snow!","translations":{"es":"No salgas: ¡hay un metro de nieve!"}},{"phrase":"Il y a du vent. Ferme les fenêtres, sinon mes papiers vont s''envoler.","translation":"It''s windy. Close the windows, otherwise my papers will blow away.","translations":{"es":"Hace viento. Cierra las ventanas, si no mis papeles van a salir volando."}},{"phrase":"L''avion n''arrivera pas à l''heure à cause de la tempête.","translation":"The plane won''t arrive on time because of the storm.","translations":{"es":"El avión no llegará a su hora por la tormenta."}},{"phrase":"Est-ce qu''il y a eu beaucoup de dégâts ? — Non, heureusement.","translation":"Was there a lot of damage? — No, luckily.","translations":{"es":"¿Hubo muchos daños? — No, por suerte."}},{"phrase":"Tu es trempé ! — Il pleuvait à verse et j''avais oublié mon parapluie.","translation":"You''re soaked! — It was pouring and I had forgotten my umbrella.","translations":{"es":"¡Estás empapado! — Llovía a cántaros y me había olvidado el paraguas."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"En hiver, il ___ froid.\"","options":["a","y a","est","fait"],"correct":3,"explanation":"Il fait froid / chaud / beau.","translations":{"es":{"question":"Completa: «En hiver, il ___ froid.»","explanation":"Il fait froid / chaud / beau."}}},{"id":"2","question":"Which season takes \"au\"?","options":["l''hiver","l''automne","l''été","le printemps"],"correct":3,"explanation":"Au printemps, but en été, en automne, en hiver.","translations":{"es":{"question":"¿Qué estación lleva «au»?","explanation":"Au printemps, pero en été, en automne, en hiver."}}},{"id":"3","question":"Which sentence uses the plus-que-parfait?","options":["J''oublierai mon parapluie.","J''oubliais mon parapluie.","J''ai oublié mon parapluie.","J''avais oublié mon parapluie."],"correct":3,"explanation":"Plus-que-parfait = imparfait of avoir/être + past participle.","translations":{"es":{"question":"¿Qué frase usa el plus-que-parfait?","explanation":"Plus-que-parfait = imperfecto de avoir/être + participio."}}},{"id":"4","question":"Complete: \"Je marchais sous la pluie quand je l''___.\"","options":["voyais","verrai","avais vue","ai vue"],"correct":3,"explanation":"Background (imparfait) interrupted by an event (passé composé).","translations":{"es":{"question":"Completa: «Je marchais sous la pluie quand je l''___.»","explanation":"Fondo (imperfecto) interrumpido por un hecho (passé composé)."}}},{"id":"5","question":"\"Je ne savais pas qu''elle serait ma femme.\" What does \"serait\" express?","options":["a polite request","an order","a present hypothesis","the future seen from the past"],"correct":3,"explanation":"The conditional can express a \"future in the past\".","translations":{"es":{"question":"«Je ne savais pas qu''elle serait ma femme.» ¿Qué expresa «serait»?","explanation":"El condicional puede expresar un «futuro en el pasado».","options":["una petición cortés","una orden","una hipótesis presente","el futuro visto desde el pasado"]}}},{"id":"6","question":"What is \"le brouillard\"?","options":["drizzle","thunder","hail","fog"],"correct":3,"explanation":"Brume = mist (lighter).","translations":{"es":{"question":"¿Qué es «le brouillard»?","explanation":"Brume = bruma (más ligera).","options":["la llovizna","el trueno","el granizo","la niebla"]}}},{"id":"7","question":"Complete: \"C''était comme si nous nous ___ toujours connus.\"","options":["sommes","soyons","serions","étions"],"correct":3,"explanation":"\"Comme si\" + plus-que-parfait (or imparfait).","translations":{"es":{"question":"Completa: «C''était comme si nous nous ___ toujours connus.»","explanation":"«Comme si» + plus-que-parfait (o imperfecto)."}}},{"id":"8","question":"Someone who is always cold is…","options":["trempé","doux","sec","frileux"],"correct":3,"explanation":"Frileux / frileuse.","translations":{"es":{"question":"Alguien que siempre tiene frío es…","explanation":"Frileux / frileuse."}}}]}'::jsonb, 3),
  ('story', 'L''abribus', '{"text":"J''ai rencontré mon mari il y a douze ans, un soir d''automne, à Lyon. Ce jour-là, il pleuvait à verse et il y avait beaucoup de vent. J''étais de mauvaise humeur, parce que j''avais raté mon train et j''avais oublié mon parapluie. J''ai couru jusqu''à un abribus pour me protéger de l''orage. Un homme était déjà là, trempé jusqu''aux os. Tout à coup, un éclair a illuminé le ciel et le tonnerre a été si fort que j''ai crié. Il a ri, puis il m''a dit : « Calmez-vous, l''orage ne durera pas. » Nous avons commencé à parler de tout et de rien. C''était comme si nous nous étions toujours connus. Quand la pluie s''est arrêtée, un arc-en-ciel est apparu au-dessus du Rhône. Il m''a invitée à boire un chocolat chaud. À ce moment-là, je ne savais pas que cet inconnu serait l''homme de ma vie. Depuis, peu importe le temps qu''il fait : quand je le regarde, le ciel est toujours dégagé.","translation":"I met my husband twelve years ago, one autumn evening, in Lyon. That day, it was pouring and very windy. I was in a bad mood, because I had missed my train and I had forgotten my umbrella. I ran to a bus shelter to protect myself from the storm. A man was already there, soaked to the bone. Suddenly, a flash of lightning lit up the sky and the thunder was so loud that I screamed. He laughed, then said to me: “Calm down, the storm won''t last.” We started talking about everything and nothing. It was as if we had always known each other. When the rain stopped, a rainbow appeared over the Rhône. He invited me for a hot chocolate. At that moment, I didn''t know that this stranger would be the love of my life. Since then, whatever the weather: when I look at him, the sky is always clear.","translations":{"es":"Conocí a mi marido hace doce años, una tarde de otoño, en Lyon. Ese día llovía a cántaros y hacía mucho viento. Yo estaba de mal humor porque había perdido el tren y me había olvidado el paraguas. Corrí hasta una parada de autobús para protegerme de la tormenta. Ya había un hombre allí, calado hasta los huesos. De repente, un relámpago iluminó el cielo y el trueno fue tan fuerte que grité. Él se rio y luego me dijo: «Cálmese, la tormenta no durará.» Empezamos a hablar de todo y de nada. Era como si nos hubiéramos conocido siempre. Cuando paró la lluvia, apareció un arcoíris sobre el Ródano. Me invitó a tomar un chocolate caliente. En ese momento no sabía que aquel desconocido sería el hombre de mi vida. Desde entonces, haga el tiempo que haga, cuando lo miro, el cielo siempre está despejado."},"highlighted_words":["il y a douze ans","d''automne","il pleuvait à verse","vent","j''avais raté","j''avais oublié","orage","trempé","éclair","tonnerre","Calmez-vous","ne durera pas","comme si nous nous étions","arc-en-ciel","serait","dégagé"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Il","fait","très","froid","aujourd''hui"],"translation":"It''s very cold today","translations":{"es":"Hoy hace mucho frío"}},{"words":["Le","ciel","est","dégagé"],"translation":"The sky is clear","translations":{"es":"El cielo está despejado"}},{"words":["J''avais","oublié","mon","parapluie"],"translation":"I had forgotten my umbrella","translations":{"es":"Me había olvidado el paraguas"}},{"words":["Ne","sors","pas","il","neige"],"translation":"Don''t go out it''s snowing","translations":{"es":"No salgas, está nevando"}},{"words":["Au","printemps","il","fait","doux"],"translation":"In spring the weather is mild","translations":{"es":"En primavera hace buen tiempo"}},{"words":["Une","tempête","arrive"],"translation":"A storm is coming","translations":{"es":"Se acerca una tormenta"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"It''s raining a lot","translations":{"es":"Llueve mucho"},"answer":"Il pleut beaucoup"},{"prompt":"I''m freezing","translations":{"es":"Estoy congelado"},"answer":"Je suis gelé"},{"prompt":"You are soaked","translations":{"es":"Estás empapado"},"answer":"Tu es trempé"},{"prompt":"Winter is the coldest season","translations":{"es":"El invierno es la estación más fría"},"answer":"L''hiver est la saison la plus froide"},{"prompt":"It''s foggy","translations":{"es":"Hay niebla"},"answer":"Il y a du brouillard"},{"prompt":"Calm down","translations":{"es":"Cálmate"},"answer":"Calme-toi"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 24: L'art et les musées
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-24', 'L''art et les musées', '🏛️', 'El arte y los museos', 24, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''art","translation":"art","translations":{"es":"el arte"}},{"id":"2","word":"le musée","translation":"the museum","translations":{"es":"el museo"}},{"id":"3","word":"l''exposition","translation":"the exhibition","translations":{"es":"la exposición"}},{"id":"4","word":"la galerie","translation":"the gallery","translations":{"es":"la galería"}},{"id":"5","word":"le tableau","translation":"the painting","translations":{"es":"el cuadro"}},{"id":"6","word":"la peinture","translation":"painting / paint","translations":{"es":"la pintura"}},{"id":"7","word":"la toile","translation":"the canvas","translations":{"es":"el lienzo"}},{"id":"8","word":"le dessin","translation":"the drawing","translations":{"es":"el dibujo"}},{"id":"9","word":"la sculpture","translation":"the sculpture","translations":{"es":"la escultura"}},{"id":"10","word":"la statue","translation":"the statue","translations":{"es":"la estatua"}},{"id":"11","word":"la reproduction","translation":"the reproduction","translations":{"es":"la reproducción"}},{"id":"12","word":"la lithographie","translation":"the lithograph","translations":{"es":"la litografía"}},{"id":"13","word":"la céramique","translation":"ceramics","translations":{"es":"la cerámica"}},{"id":"14","word":"l''orfèvrerie","translation":"goldsmithing","translations":{"es":"la orfebrería"}},{"id":"15","word":"le bronze","translation":"bronze","translations":{"es":"el bronce"}},{"id":"16","word":"l''or","translation":"gold","translations":{"es":"el oro"}},{"id":"17","word":"l''argent","translation":"silver","translations":{"es":"la plata"}},{"id":"18","word":"la pierre","translation":"stone","translations":{"es":"la piedra"}},{"id":"19","word":"le métal","translation":"metal","translations":{"es":"el metal"}},{"id":"20","word":"le monument","translation":"the monument","translations":{"es":"el monumento"}},{"id":"21","word":"la cathédrale","translation":"the cathedral","translations":{"es":"la catedral"}},{"id":"22","word":"l''église","translation":"the church","translations":{"es":"la iglesia"}},{"id":"23","word":"la chapelle","translation":"the chapel","translations":{"es":"la capilla"}},{"id":"24","word":"l''abbaye","translation":"the abbey","translations":{"es":"la abadía"}},{"id":"25","word":"le monastère","translation":"the monastery","translations":{"es":"el monasterio"}},{"id":"26","word":"le cloître","translation":"the cloister","translations":{"es":"el claustro"}},{"id":"27","word":"le palais","translation":"the palace","translations":{"es":"el palacio"}},{"id":"28","word":"le château","translation":"the castle","translations":{"es":"el castillo"}},{"id":"29","word":"la tour","translation":"the tower","translations":{"es":"la torre"}},{"id":"30","word":"le clocher","translation":"the bell tower","translations":{"es":"el campanario"}},{"id":"31","word":"le dôme","translation":"the dome","translations":{"es":"la cúpula"}},{"id":"32","word":"la colonne","translation":"the column","translations":{"es":"la columna"}},{"id":"33","word":"la voûte","translation":"the vault","translations":{"es":"la bóveda"}},{"id":"34","word":"le sarcophage","translation":"the sarcophagus","translations":{"es":"el sarcófago"}},{"id":"35","word":"la dynastie","translation":"the dynasty","translations":{"es":"la dinastía"}},{"id":"36","word":"le guide","translation":"the guide","translations":{"es":"el guía"}},{"id":"37","word":"la brochure","translation":"the brochure","translations":{"es":"el folleto"}},{"id":"38","word":"le guichet","translation":"the ticket office","translations":{"es":"la taquilla"}},{"id":"39","word":"l''entrée","translation":"entry / ticket","translations":{"es":"la entrada"}},{"id":"40","word":"le gardien","translation":"the museum guard","translations":{"es":"el vigilante"}},{"id":"41","word":"ouvert / ouverte","translation":"open","translations":{"es":"abierto / abierta"}},{"id":"42","word":"fermé / fermée","translation":"closed","translations":{"es":"cerrado / cerrada"}},{"id":"43","word":"gratuit / gratuite","translation":"free","translations":{"es":"gratuito / gratuita"}}],"grammar":[{"structure":"en + matière","example":"Cette sculpture est en bronze. / Le sarcophage est en or.","en":"Materials","es":"Materiales"},{"structure":"voix passive","example":"La tour a été construite en pierre.","en":"Passive voice","es":"Voz pasiva"},{"structure":"futur simple","example":"Le musée ouvrira ses portes à neuf heures.","en":"Simple future","es":"Futuro simple"},{"structure":"imparfait / passé composé","example":"Autrefois, l''art servait la religion. / Les artistes ont commencé à l''utiliser autrement.","en":"Past habit vs. change","es":"Hábito pasado frente a cambio"},{"structure":"se rendre compte de","example":"Les rois se sont rendu compte du pouvoir de l''art.","en":"\"To realize\"","es":"«Darse cuenta de»"},{"structure":"ne … que","example":"L''art n''est pas que de la peinture.","en":"\"not only / just\"","es":"«no solo»"},{"structure":"pronom « y »","example":"Il y a un monastère sur la colline ; je vais t''y emmener.","en":"\"y\" with a place","es":"«y» con un lugar"},{"structure":"conditionnel de politesse","example":"Pourriez-vous me dire quand ouvre la cathédrale ?","en":"Polite conditional","es":"Condicional de cortesía"}],"tips":[{"en":"Many French museums are free on the first Sunday of the month, and often for EU residents under 26.","es":"Muchos museos franceses son gratuitos el primer domingo del mes, y a menudo para residentes de la UE menores de 26 años."},{"en":"\"Le guichet\" = ticket office; \"une entrée / un billet\" = a ticket; \"tarif réduit\" = reduced price.","es":"«Le guichet» = la taquilla; «une entrée / un billet» = una entrada; «tarif réduit» = precio reducido."},{"en":"\"Un tableau\" = a painting (the object); \"la peinture\" = paint or painting (the art).","es":"«Un tableau» = un cuadro (el objeto); «la peinture» = la pintura (material o arte)."},{"en":"\"Se rendre compte\" does not agree in the passé composé: \"elles se sont rendu compte\".","es":"«Se rendre compte» no concuerda en el passé composé: «elles se sont rendu compte»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Nous nous sommes mariés dans cette chapelle.","translation":"We got married in this chapel.","translations":{"es":"Nos casamos en esta capilla."}},{"phrase":"Cette sculpture est en bronze.","translation":"This sculpture is made of bronze.","translations":{"es":"Esta escultura es de bronce."}},{"phrase":"Le plan est peut-être dans la brochure.","translation":"The map is maybe in the brochure.","translations":{"es":"Quizás el plano está en el folleto."}},{"phrase":"Samedi, il y a une exposition de lithographies.","translation":"On Saturday, there is an exhibition of lithographs.","translations":{"es":"El sábado hay una exposición de litografías."}},{"phrase":"Le plus grand monument de la ville se trouve dans le centre.","translation":"The biggest monument in the city is in the center.","translations":{"es":"El monumento más grande de la ciudad está en el centro."}},{"phrase":"Le monastère est fermé pour travaux de restauration.","translation":"The monastery is closed for restoration work.","translations":{"es":"El monasterio está cerrado por obras de restauración."}},{"phrase":"Le musée ouvrira ses portes à neuf heures.","translation":"The museum will open at nine.","translations":{"es":"El museo abrirá sus puertas a las nueve."}},{"phrase":"La tour a été construite en pierre.","translation":"The tower was built of stone.","translations":{"es":"La torre fue construida en piedra."}},{"phrase":"Les Romains ont bâti des colonnes incroyables.","translation":"The Romans built incredible columns.","translations":{"es":"Los romanos construyeron columnas increíbles."}},{"phrase":"Pourrais-tu me montrer les principaux musées de la ville ? — Bien sûr, allons-y !","translation":"Could you show me the main museums in the city? — Of course, let''s go!","translations":{"es":"¿Podrías enseñarme los principales museos de la ciudad? — ¡Claro, vamos!"}},{"phrase":"Quel genre de peinture est-ce ? — C''est un peintre surréaliste.","translation":"What kind of painting is it? — It''s a surrealist painter.","translations":{"es":"¿Qué tipo de pintura es? — Es un pintor surrealista."}},{"phrase":"Où se trouve le guichet ? — Au coin. Combien d''entrées voulez-vous ?","translation":"Where is the ticket office? — In the corner. How many tickets would you like?","translations":{"es":"¿Dónde está la taquilla? — En la esquina. ¿Cuántas entradas quiere?"}},{"phrase":"Désolé, ces entrées gratuites ne sont valables que le matin.","translation":"Sorry, these free tickets are only valid in the morning.","translations":{"es":"Lo siento, estas entradas gratuitas solo son válidas por la mañana."}},{"phrase":"Il y a un vieux monastère sur la colline. Je vais t''y emmener.","translation":"There''s an old monastery on the hill. I''ll take you there.","translations":{"es":"Hay un viejo monasterio en la colina. Te voy a llevar."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Cette statue est ___ marbre.\"","options":["avec","en","du","de la"],"correct":1,"explanation":"Materials: en bronze, en or, en pierre.","translations":{"es":{"question":"Completa: «Cette statue est ___ marbre.»","explanation":"Materiales: en bronze, en or, en pierre."}}},{"id":"2","question":"Passive: \"They built the tower in 1200\" → ?","options":["La tour a été construite en 1200.","La tour est construisait en 1200.","La tour était construire en 1200.","La tour a construit en 1200."],"correct":0,"explanation":"avoir été + past participle (agrees with \"la tour\").","translations":{"es":{"question":"Pasiva: «Construyeron la torre en 1200» → ?","explanation":"avoir été + participio (concuerda con «la tour»)."}}},{"id":"3","question":"Where do you buy museum tickets?","options":["au guichet","à la voûte","au cloître","au clocher"],"correct":0,"explanation":"Le guichet = the ticket office.","translations":{"es":{"question":"¿Dónde compras las entradas del museo?","explanation":"Le guichet = la taquilla."}}},{"id":"4","question":"\"L''art n''est pas que de la peinture.\" Meaning?","options":["Painting is not art.","Art is not only painting.","Art is only painting.","Art is not painting."],"correct":1,"explanation":"\"Ne … pas que\" = not only.","translations":{"es":{"question":"«L''art n''est pas que de la peinture.» ¿Significado?","explanation":"«Ne … pas que» = no solo.","options":["La pintura no es arte.","El arte no es solo pintura.","El arte es solo pintura.","El arte no es pintura."]}}},{"id":"5","question":"Complete: \"Le monastère ? Je vais t''___ emmener.\"","options":["lui","y","le","en"],"correct":1,"explanation":"\"Y\" replaces a place.","translations":{"es":{"question":"Completa: «Le monastère ? Je vais t''___ emmener.»","explanation":"«Y» sustituye un lugar."}}},{"id":"6","question":"What is \"un tableau\" in a museum?","options":["a ticket","a statue","a painting","a table"],"correct":2,"explanation":"Une table = a table.","translations":{"es":{"question":"¿Qué es «un tableau» en un museo?","explanation":"Une table = una mesa.","options":["una entrada","una estatua","un cuadro","una mesa"]}}},{"id":"7","question":"Which sentence describes a past habit?","options":["L''art sert la religion.","L''art servira la religion.","Autrefois, l''art servait la religion.","L''art a servi la religion en 1200."],"correct":2,"explanation":"Imparfait for habits and long situations in the past.","translations":{"es":{"question":"¿Qué frase describe un hábito pasado?","explanation":"Imperfecto para hábitos y situaciones largas del pasado."}}},{"id":"8","question":"How do you politely ask when the cathedral opens?","options":["La cathédrale ouvre quand, vite ?","Dis-moi la cathédrale.","Pourriez-vous me dire quand ouvre la cathédrale ?","Quand ouvre la cathédrale, toi ?"],"correct":2,"explanation":"Conditional \"pourriez-vous\" = could you.","translations":{"es":{"question":"¿Cómo preguntas con cortesía cuándo abre la catedral?","explanation":"Condicional «pourriez-vous» = ¿podría usted?"}}}]}'::jsonb, 3),
  ('story', 'Une visite au musée', '{"text":"Dimanche dernier, Emma a emmené son petit frère Nathan au musée d''Orsay, à Paris. C''était le premier dimanche du mois, alors l''entrée était gratuite. Au guichet, il y avait une longue file d''attente. Le musée se trouve dans une ancienne gare, qui a été construite pour l''Exposition universelle de 1900. « Autrefois, les trains arrivaient ici », explique Emma. Ils ont admiré les tableaux impressionnistes, puis les sculptures en bronze et en marbre. Devant un tableau de Monet, Nathan a demandé : « Pourquoi les peintres peignaient-ils toujours la même cathédrale ? » Un guide a souri : « Monet voulait montrer la lumière à différents moments de la journée. » Emma s''est rendu compte que son frère s''intéressait vraiment à l''art. « L''art n''est pas que de la peinture, lui a-t-elle dit. C''est aussi la musique, le cinéma, la danse… » À la sortie, Nathan a voulu acheter une reproduction pour sa chambre. « La semaine prochaine, il y a une exposition de photos au Centre Pompidou. Je vais t''y emmener ! » a promis Emma.","translation":"Last Sunday, Emma took her little brother Nathan to the Musée d''Orsay in Paris. It was the first Sunday of the month, so admission was free. At the ticket office, there was a long queue. The museum is in a former train station, which was built for the 1900 World''s Fair. “Trains used to arrive here,” Emma explains. They admired the Impressionist paintings, then the bronze and marble sculptures. In front of a Monet painting, Nathan asked: “Why did painters always paint the same cathedral?” A guide smiled: “Monet wanted to show the light at different times of the day.” Emma realized that her brother was really interested in art. “Art isn''t only painting,” she told him. “It''s also music, cinema, dance…” At the exit, Nathan wanted to buy a print for his bedroom. “Next week, there''s a photo exhibition at the Centre Pompidou. I''ll take you there!” Emma promised.","translations":{"es":"El domingo pasado, Emma llevó a su hermano pequeño Nathan al museo de Orsay, en París. Era el primer domingo del mes, así que la entrada era gratuita. En la taquilla había una larga cola. El museo está en una antigua estación, que fue construida para la Exposición Universal de 1900. «Antes los trenes llegaban aquí», explica Emma. Admiraron los cuadros impresionistas y luego las esculturas de bronce y de mármol. Delante de un cuadro de Monet, Nathan preguntó: «¿Por qué los pintores pintaban siempre la misma catedral?». Un guía sonrió: «Monet quería mostrar la luz en distintos momentos del día.» Emma se dio cuenta de que a su hermano le interesaba de verdad el arte. «El arte no es solo pintura», le dijo. «También es la música, el cine, la danza…» A la salida, Nathan quiso comprar una reproducción para su habitación. «La semana que viene hay una exposición de fotos en el Centro Pompidou. ¡Te llevaré!», le prometió Emma."},"highlighted_words":["guichet","a été construite","Autrefois","tableaux","sculptures en bronze","cathédrale","s''est rendu compte","n''est pas que","reproduction","exposition","t''y emmener"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Cette","statue","est","en","bronze"],"translation":"This statue is made of bronze","translations":{"es":"Esta estatua es de bronce"}},{"words":["Le","musée","ouvrira","à","neuf","heures"],"translation":"The museum will open at nine","translations":{"es":"El museo abrirá a las nueve"}},{"words":["La","cathédrale","a","été","construite","en","pierre"],"translation":"The cathedral was built of stone","translations":{"es":"La catedral fue construida en piedra"}},{"words":["L''entrée","est","gratuite","le","dimanche"],"translation":"Entry is free on Sundays","translations":{"es":"La entrada es gratuita los domingos"}},{"words":["Je","vais","t''y","emmener"],"translation":"I''ll take you there","translations":{"es":"Te llevaré allí"}},{"words":["Où","se","trouve","le","guichet"],"translation":"Where is the ticket office","translations":{"es":"¿Dónde está la taquilla?"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"The museum is closed","translations":{"es":"El museo está cerrado"},"answer":"Le musée est fermé"},{"prompt":"I love this painting","translations":{"es":"Me encanta este cuadro"},"answer":"J''adore ce tableau"},{"prompt":"Two tickets, please","translations":{"es":"Dos entradas, por favor"},"answer":"Deux entrées, s''il vous plaît"},{"prompt":"We need a guide","translations":{"es":"Necesitamos un guía"},"answer":"Nous avons besoin d''un guide"},{"prompt":"It''s a free exhibition","translations":{"es":"Es una exposición gratuita"},"answer":"C''est une exposition gratuite"},{"prompt":"The castle is magnificent","translations":{"es":"El castillo es magnífico"},"answer":"Le château est magnifique"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 25: Les transports
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-25', 'Les transports', '🚆', 'Los transportes', 25, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la voiture","translation":"the car","translations":{"es":"el coche / el carro"}},{"id":"2","word":"le bus","translation":"the bus","translations":{"es":"el autobús"}},{"id":"3","word":"l''autocar","translation":"the coach","translations":{"es":"el autocar"}},{"id":"4","word":"le camion","translation":"the truck","translations":{"es":"el camión"}},{"id":"5","word":"la moto","translation":"the motorbike","translations":{"es":"la moto"}},{"id":"6","word":"le vélo","translation":"the bicycle","translations":{"es":"la bicicleta"}},{"id":"7","word":"le taxi","translation":"the taxi","translations":{"es":"el taxi"}},{"id":"8","word":"le métro","translation":"the subway","translations":{"es":"el metro"}},{"id":"9","word":"le train","translation":"the train","translations":{"es":"el tren"}},{"id":"10","word":"le chemin de fer","translation":"the railway","translations":{"es":"el ferrocarril"}},{"id":"11","word":"l''avion","translation":"the plane","translations":{"es":"el avión"}},{"id":"12","word":"le vol","translation":"the flight","translations":{"es":"el vuelo"}},{"id":"13","word":"le bateau","translation":"the boat","translations":{"es":"el barco"}},{"id":"14","word":"le canot","translation":"the canoe / small boat","translations":{"es":"la canoa / el bote"}},{"id":"15","word":"le port","translation":"the port","translations":{"es":"el puerto"}},{"id":"16","word":"l''aéroport","translation":"the airport","translations":{"es":"el aeropuerto"}},{"id":"17","word":"la gare","translation":"the train station","translations":{"es":"la estación de tren"}},{"id":"18","word":"la station de métro","translation":"the subway station","translations":{"es":"la estación de metro"}},{"id":"19","word":"la station-service","translation":"the gas station","translations":{"es":"la gasolinera"}},{"id":"20","word":"l''essence","translation":"gas / petrol","translations":{"es":"la gasolina"}},{"id":"21","word":"l''autoroute","translation":"the highway","translations":{"es":"la autopista"}},{"id":"22","word":"la voie","translation":"the lane / the track","translations":{"es":"el carril / la vía"}},{"id":"23","word":"le conducteur / la conductrice","translation":"the driver","translations":{"es":"el conductor / la conductora"}},{"id":"24","word":"le permis de conduire","translation":"driver''s license","translations":{"es":"el carné de conducir"}},{"id":"25","word":"la ceinture de sécurité","translation":"seat belt","translations":{"es":"el cinturón de seguridad"}},{"id":"26","word":"le frein","translation":"the brake","translations":{"es":"el freno"}},{"id":"27","word":"freiner","translation":"to brake","translations":{"es":"frenar"}},{"id":"28","word":"conduire","translation":"to drive","translations":{"es":"conducir / manejar"}},{"id":"29","word":"doubler","translation":"to overtake","translations":{"es":"adelantar"}},{"id":"30","word":"traverser","translation":"to cross","translations":{"es":"cruzar"}},{"id":"31","word":"louer","translation":"to rent","translations":{"es":"alquilar"}},{"id":"32","word":"décoller","translation":"to take off","translations":{"es":"despegar"}},{"id":"33","word":"atterrir","translation":"to land","translations":{"es":"aterrizar"}},{"id":"34","word":"le billet","translation":"the ticket","translations":{"es":"el billete / el boleto"}},{"id":"35","word":"un aller-retour","translation":"a return ticket","translations":{"es":"un billete de ida y vuelta"}},{"id":"36","word":"l''horaire","translation":"the timetable","translations":{"es":"el horario"}},{"id":"37","word":"la distance","translation":"the distance","translations":{"es":"la distancia"}},{"id":"38","word":"loin / près","translation":"far / near","translations":{"es":"lejos / cerca"}},{"id":"39","word":"rapide / lent","translation":"fast / slow","translations":{"es":"rápido / lento"}},{"id":"40","word":"vite / lentement","translation":"quickly / slowly","translations":{"es":"deprisa / despacio"}},{"id":"41","word":"la vitesse","translation":"speed","translations":{"es":"la velocidad"}}],"grammar":[{"structure":"pronoms démonstratifs","example":"Est-ce que celle-ci est ta voiture ?","en":"Demonstrative pronouns (celui-ci, celle-là…)","es":"Pronombres demostrativos"},{"structure":"comparatif","example":"Le taxi est plus lent et plus cher que le métro. / Le train est moins cher que l''avion.","en":"Comparatives","es":"Comparativos"},{"structure":"impératif (nous / tu)","example":"Louons une voiture ! / Regarde des deux côtés avant de traverser.","en":"Imperative","es":"Imperativo"},{"structure":"avant de + infinitif","example":"Regarde avant de traverser.","en":"\"Before doing\"","es":"«Antes de»"},{"structure":"être sur le point de","example":"Nous sommes sur le point d''atterrir.","en":"\"About to\"","es":"«A punto de»"},{"structure":"plus-que-parfait","example":"J''ai dit au revoir aux gens qui avaient pris soin de moi.","en":"Past perfect","es":"Pluscuamperfecto"},{"structure":"gérondif","example":"Je suis resté un an en travaillant sur un ferry.","en":"Gerund","es":"Gerundio"},{"structure":"pour que + subjonctif","example":"Nous aidons les enfants pour qu''ils puissent voyager.","en":"\"So that\" + subjunctive","es":"«Para que» + subjuntivo"},{"structure":"se mettre à + infinitif","example":"Je me suis mis à faire des traductions.","en":"\"To start doing\"","es":"«Ponerse a»"}],"tips":[{"en":"Transport + \"en\" when you are inside: en voiture, en bus, en train, en avion, en métro. But \"à\" for what you ride on: à pied, à vélo, à moto, à cheval.","es":"Transporte + «en» cuando vas dentro: en voiture, en bus, en train, en avion, en métro. Pero «à» si vas encima: à pied, à vélo, à moto, à cheval."},{"en":"\"Un aller simple\" = one-way ticket; \"un aller-retour\" = return ticket.","es":"«Un aller simple» = billete de ida; «un aller-retour» = billete de ida y vuelta."},{"en":"\"Griller / brûler un feu rouge\" = to run a red light. \"Le permis de conduire\" = driver''s license.","es":"«Griller / brûler un feu rouge» = saltarse un semáforo en rojo. «Le permis de conduire» = el carné de conducir."},{"en":"\"Décoller\" = to take off; \"atterrir\" = to land.","es":"«Décoller» = despegar; «atterrir» = aterrizar."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Est-ce que celle-ci est ta voiture ?","translation":"Is this one your car?","translations":{"es":"¿Este es tu coche?"}},{"phrase":"Où va ce bus ? — À la gare.","translation":"Where does this bus go? — To the station.","translations":{"es":"¿Adónde va este autobús? — A la estación."}},{"phrase":"Regarde des deux côtés de la rue avant de traverser.","translation":"Look both ways before crossing the street.","translations":{"es":"Mira a ambos lados de la calle antes de cruzar."}},{"phrase":"J''ai perdu mon permis de conduire !","translation":"I lost my driver''s license!","translations":{"es":"¡He perdido el carné de conducir!"}},{"phrase":"Arrête-toi à la station-service, on n''a plus d''essence.","translation":"Stop at the gas station, we''re out of gas.","translations":{"es":"Para en la gasolinera, nos hemos quedado sin gasolina."}},{"phrase":"Appuie sur le bouton pour descendre au prochain arrêt.","translation":"Press the button to get off at the next stop.","translations":{"es":"Pulsa el botón para bajar en la próxima parada."}},{"phrase":"L''avion est en train de décoller.","translation":"The plane is taking off.","translations":{"es":"El avión está despegando."}},{"phrase":"C''est mieux si tu prends le métro : le taxi est plus lent et plus cher.","translation":"It''s better if you take the subway: the taxi is slower and more expensive.","translations":{"es":"Es mejor que tomes el metro: el taxi es más lento y más caro."}},{"phrase":"Le train est souvent moins cher que l''avion.","translation":"The train is often cheaper than the plane.","translations":{"es":"El tren suele ser más barato que el avión."}},{"phrase":"Louons une voiture pour le week-end !","translation":"Let''s rent a car for the weekend!","translations":{"es":"¡Alquilemos un coche para el fin de semana!"}},{"phrase":"Deux billets pour le vol 300 à destination de Genève, s''il vous plaît.","translation":"Two tickets for flight 300 to Geneva, please.","translations":{"es":"Dos billetes para el vuelo 300 con destino a Ginebra, por favor."}},{"phrase":"Vos papiers, s''il vous plaît. — Qu''est-ce que j''ai fait ? — Vous avez grillé le feu rouge.","translation":"Your papers, please. — What did I do? — You ran the red light.","translations":{"es":"Su documentación, por favor. — ¿Qué he hecho? — Se ha saltado el semáforo en rojo."}},{"phrase":"Attachez vos ceintures : nous sommes sur le point d''atterrir.","translation":"Fasten your seat belts: we are about to land.","translations":{"es":"Abróchense los cinturones: estamos a punto de aterrizar."}},{"phrase":"Ne t''arrête jamais sur la voie ferrée !","translation":"Never stop on the railway track!","translations":{"es":"¡No te detengas nunca en la vía del tren!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Je vais au travail ___ vélo.\"","options":["en","à","dans","par"],"correct":1,"explanation":"À vélo, à pied, à moto; but en voiture, en train.","translations":{"es":{"question":"Completa: «Je vais au travail ___ vélo.»","explanation":"À vélo, à pied, à moto; pero en voiture, en train."}}},{"id":"2","question":"Complete: \"Nous partons ___ train.\"","options":["en","à","au","par le"],"correct":0,"explanation":"En train, en avion, en bus.","translations":{"es":{"question":"Completa: «Nous partons ___ train.»","explanation":"En train, en avion, en bus."}}},{"id":"3","question":"What does \"atterrir\" mean?","options":["to land","to take off","to brake","to overtake"],"correct":0,"explanation":"Décoller = to take off.","translations":{"es":{"question":"¿Qué significa «atterrir»?","explanation":"Décoller = despegar.","options":["aterrizar","despegar","frenar","adelantar"]}}},{"id":"4","question":"Which ticket lets you come back?","options":["un aller simple","un horaire","un aller-retour","un vol"],"correct":2,"explanation":"Aller simple = one way.","translations":{"es":{"question":"¿Qué billete te permite volver?","explanation":"Aller simple = solo ida."}}},{"id":"5","question":"Complete: \"Le métro est ___ cher ___ le taxi.\"","options":["moins … de","plus … de","moins … que","aussi … comme"],"correct":2,"explanation":"Comparative: moins / plus / aussi … que.","translations":{"es":{"question":"Completa: «Le métro est ___ cher ___ le taxi.»","explanation":"Comparativo: moins / plus / aussi … que."}}},{"id":"6","question":"Complete: \"J''ai remercié les gens qui ___ soin de moi.\"","options":["prenaient","ont pris","avaient pris","prendront"],"correct":2,"explanation":"Plus-que-parfait: an action before another past action.","translations":{"es":{"question":"Completa: «J''ai remercié les gens qui ___ soin de moi.»","explanation":"Pluscuamperfecto: una acción anterior a otra pasada."}}},{"id":"7","question":"Complete: \"Nous les aidons pour qu''ils ___ voyager.\"","options":["peuvent","pourront","puissent","pouvaient"],"correct":2,"explanation":"\"Pour que\" + subjunctive.","translations":{"es":{"question":"Completa: «Nous les aidons pour qu''ils ___ voyager.»","explanation":"«Pour que» + subjuntivo."}}},{"id":"8","question":"Which demonstrative fits: \"Tu préfères quelle voiture ? — ___.\"","options":["Ceux-ci","Celle-ci","Celui-ci","Cette-ci"],"correct":1,"explanation":"Voiture is feminine singular: celle-ci.","translations":{"es":{"question":"¿Qué demostrativo encaja: «¿Qué coche prefieres? — ___.»","explanation":"Voiture es femenino singular: celle-ci."}}}]}'::jsonb, 3),
  ('story', 'Le grand voyage de Malik', '{"text":"Je m''appelle Malik Benali. Quand j''avais dix-neuf ans, j''ai décidé de quitter Marseille pour découvrir le monde. Mes parents étaient inquiets, mais ils m''ont laissé partir. D''abord, j''ai pris un ferry pour la Corse et je suis resté là-bas un an en travaillant sur les bateaux du port. En même temps, j''économisais de l''argent pour mon prochain voyage. Quand le jour du départ est arrivé, j''ai dit au revoir aux pêcheurs qui avaient pris soin de moi. Ensuite, j''ai traversé l''Europe en train : c''est moins cher que l''avion et on voit des paysages magnifiques. Un soir, à Lisbonne, j''étais en train de jouer de la guitare dans la rue quand une femme m''a proposé un travail de guide pour des touristes. Comme j''avais appris l''espagnol et l''anglais pendant mes voyages, je me suis mis à faire aussi des traductions. Plus tard, je suis parti au Canada en avion. Aujourd''hui, j''ai une petite agence de voyages à Montréal. Nous organisons des séjours pour des jeunes qui n''ont pas beaucoup d''argent, pour qu''ils puissent, eux aussi, découvrir le monde.","translation":"My name is Malik Benali. When I was nineteen, I decided to leave Marseille to discover the world. My parents were worried, but they let me go. First, I took a ferry to Corsica and stayed there for a year, working on the boats in the harbor. At the same time, I was saving money for my next trip. When the day of departure came, I said goodbye to the fishermen who had taken care of me. Then, I crossed Europe by train: it''s cheaper than flying and you see magnificent landscapes. One evening in Lisbon, I was playing the guitar in the street when a woman offered me a job as a tour guide. As I had learned Spanish and English during my travels, I also started doing translations. Later, I flew to Canada. Today, I have a small travel agency in Montreal. We organize trips for young people who don''t have much money, so that they too can discover the world.","translations":{"es":"Me llamo Malik Benali. Cuando tenía diecinueve años, decidí dejar Marsella para descubrir el mundo. Mis padres estaban preocupados, pero me dejaron ir. Primero tomé un ferry a Córcega y me quedé allí un año trabajando en los barcos del puerto. Al mismo tiempo, ahorraba dinero para mi próximo viaje. Cuando llegó el día de la partida, me despedí de los pescadores que me habían cuidado. Después crucé Europa en tren: es más barato que el avión y se ven paisajes magníficos. Una noche, en Lisboa, estaba tocando la guitarra en la calle cuando una mujer me ofreció un trabajo de guía turístico. Como había aprendido español e inglés durante mis viajes, me puse a hacer también traducciones. Más tarde me fui a Canadá en avión. Hoy tengo una pequeña agencia de viajes en Montreal. Organizamos estancias para jóvenes que no tienen mucho dinero, para que ellos también puedan descubrir el mundo."},"highlighted_words":["ferry","en travaillant","avaient pris soin","en train","moins cher que","j''étais en train de","j''avais appris","je me suis mis à","en avion","pour qu''ils puissent"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","vais","au","travail","en","métro"],"translation":"I go to work by subway","translations":{"es":"Voy al trabajo en metro"}},{"words":["Le","train","est","moins","cher","que","l''avion"],"translation":"The train is cheaper than the plane","translations":{"es":"El tren es más barato que el avión"}},{"words":["Regarde","avant","de","traverser"],"translation":"Look before crossing","translations":{"es":"Mira antes de cruzar"}},{"words":["L''avion","est","sur","le","point","d''atterrir"],"translation":"The plane is about to land","translations":{"es":"El avión está a punto de aterrizar"}},{"words":["Louons","une","voiture"],"translation":"Let''s rent a car","translations":{"es":"Alquilemos un coche"}},{"words":["Attache","ta","ceinture"],"translation":"Fasten your seat belt","translations":{"es":"Abróchate el cinturón"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Where is the train station?","translations":{"es":"¿Dónde está la estación de tren?"},"answer":"Où est la gare ?"},{"prompt":"A return ticket to Lyon","translations":{"es":"Un billete de ida y vuelta a Lyon"},"answer":"Un aller-retour pour Lyon"},{"prompt":"I go on foot","translations":{"es":"Voy a pie"},"answer":"Je vais à pied"},{"prompt":"We''re out of gas","translations":{"es":"Nos hemos quedado sin gasolina"},"answer":"On n''a plus d''essence"},{"prompt":"You drive too fast","translations":{"es":"Conduces demasiado rápido"},"answer":"Tu conduis trop vite"},{"prompt":"The plane is taking off","translations":{"es":"El avión despega"},"answer":"L''avion décolle"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 26: La musique et les instruments
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-26', 'La musique et les instruments', '🎻', 'La música y los instrumentos', 26, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la musique","translation":"music","translations":{"es":"la música"}},{"id":"2","word":"l''instrument","translation":"the instrument","translations":{"es":"el instrumento"}},{"id":"3","word":"le piano","translation":"the piano","translations":{"es":"el piano"}},{"id":"4","word":"le piano à queue","translation":"the grand piano","translations":{"es":"el piano de cola"}},{"id":"5","word":"la guitare","translation":"the guitar","translations":{"es":"la guitarra"}},{"id":"6","word":"la basse","translation":"the bass","translations":{"es":"el bajo"}},{"id":"7","word":"le violon","translation":"the violin","translations":{"es":"el violín"}},{"id":"8","word":"le violoncelle","translation":"the cello","translations":{"es":"el violonchelo"}},{"id":"9","word":"la harpe","translation":"the harp","translations":{"es":"el arpa"}},{"id":"10","word":"la flûte","translation":"the flute","translations":{"es":"la flauta"}},{"id":"11","word":"la clarinette","translation":"the clarinet","translations":{"es":"el clarinete"}},{"id":"12","word":"la trompette","translation":"the trumpet","translations":{"es":"la trompeta"}},{"id":"13","word":"le saxophone","translation":"the saxophone","translations":{"es":"el saxofón"}},{"id":"14","word":"l''accordéon","translation":"the accordion","translations":{"es":"el acordeón"}},{"id":"15","word":"l''harmonica","translation":"the harmonica","translations":{"es":"la armónica"}},{"id":"16","word":"l''orgue","translation":"the organ","translations":{"es":"el órgano"}},{"id":"17","word":"la batterie","translation":"the drums","translations":{"es":"la batería"}},{"id":"18","word":"le tambour","translation":"the drum","translations":{"es":"el tambor"}},{"id":"19","word":"les cymbales","translation":"the cymbals","translations":{"es":"los platillos"}},{"id":"20","word":"l''orchestre","translation":"the orchestra","translations":{"es":"la orquesta"}},{"id":"21","word":"le groupe","translation":"the band","translations":{"es":"el grupo / la banda"}},{"id":"22","word":"la fanfare","translation":"the brass band","translations":{"es":"la charanga"}},{"id":"23","word":"la chorale","translation":"the choir","translations":{"es":"el coro"}},{"id":"24","word":"le concert","translation":"the concert","translations":{"es":"el concierto"}},{"id":"25","word":"l''opéra","translation":"the opera","translations":{"es":"la ópera"}},{"id":"26","word":"le conservatoire","translation":"the music school","translations":{"es":"el conservatorio"}},{"id":"27","word":"le chanteur / la chanteuse","translation":"the singer","translations":{"es":"el cantante / la cantante"}},{"id":"28","word":"le / la pianiste","translation":"the pianist","translations":{"es":"el / la pianista"}},{"id":"29","word":"le musicien / la musicienne","translation":"the musician","translations":{"es":"el músico / la música"}},{"id":"30","word":"la chanson","translation":"the song","translations":{"es":"la canción"}},{"id":"31","word":"chanter","translation":"to sing","translations":{"es":"cantar"}},{"id":"32","word":"danser","translation":"to dance","translations":{"es":"bailar"}},{"id":"33","word":"enregistrer","translation":"to record","translations":{"es":"grabar"}},{"id":"34","word":"le disque","translation":"the record","translations":{"es":"el disco"}},{"id":"35","word":"la radio","translation":"the radio","translations":{"es":"la radio"}},{"id":"36","word":"le son","translation":"the sound","translations":{"es":"el sonido"}},{"id":"37","word":"allumer","translation":"to turn on","translations":{"es":"encender"}},{"id":"38","word":"éteindre","translation":"to turn off","translations":{"es":"apagar"}},{"id":"39","word":"classique","translation":"classical","translations":{"es":"clásica"}},{"id":"40","word":"le jazz","translation":"jazz","translations":{"es":"el jazz"}},{"id":"41","word":"symphonique","translation":"symphonic","translations":{"es":"sinfónico"}}],"grammar":[{"structure":"jouer de + instrument","example":"Je joue du piano, de la guitare et de l''harmonica.","en":"Playing an instrument","es":"Tocar un instrumento"},{"structure":"imparfait (habitudes)","example":"Ma mère était danseuse. On allait voir ses spectacles. Il nous chantait des chansons.","en":"Past habits","es":"Hábitos pasados"},{"structure":"depuis + présent","example":"Je suis des cours de piano depuis l''âge de cinq ans.","en":"Ongoing since","es":"Desde hace / desde"},{"structure":"passé composé","example":"J''ai signé un contrat avec l''orchestre et j''y ai joué pendant deux ans.","en":"Completed actions","es":"Acciones terminadas"},{"structure":"gérondif","example":"Nous voyageons en nous amusant et en donnant du bonheur.","en":"Gerund (manner)","es":"Gerundio (modo)"},{"structure":"conditionnel","example":"J''aimerais être dans un groupe de jazz. / Serait-il difficile de jouer du violoncelle ?","en":"Wishes and polite questions","es":"Deseos y preguntas corteses"},{"structure":"ne … aucun","example":"Combien d''instruments joues-tu ? — Aucun.","en":"\"None\"","es":"«Ninguno»"},{"structure":"futur simple","example":"L''orchestre symphonique arrivera bientôt.","en":"Simple future","es":"Futuro simple"}],"tips":[{"en":"\"Jouer DE\" an instrument (jouer du violon) but \"jouer À\" a game or sport (jouer au foot).","es":"«Jouer DE» un instrumento (jouer du violon), pero «jouer À» un juego o deporte (jouer au foot)."},{"en":"\"Un groupe\" = a band; \"une fanfare\" = a brass band; \"une chorale\" = a choir.","es":"«Un groupe» = una banda; «une fanfare» = una charanga; «une chorale» = un coro."},{"en":"\"Allumer / éteindre la radio\" = to turn on / off the radio. \"Monter / baisser le son\" = to turn the volume up / down.","es":"«Allumer / éteindre la radio» = encender / apagar la radio. «Monter / baisser le son» = subir / bajar el volumen."},{"en":"The Fête de la musique takes place every 21 June in France: free concerts everywhere!","es":"La Fête de la musique se celebra cada 21 de junio en Francia: ¡conciertos gratuitos por todas partes!"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"L''accordéon est très utilisé dans la musique populaire.","translation":"The accordion is widely used in folk music.","translations":{"es":"El acordeón se usa mucho en la música popular."}},{"phrase":"As-tu étudié au conservatoire ? — Oui, pendant cinq ans.","translation":"Did you study at the conservatory? — Yes, for five years.","translations":{"es":"¿Estudiaste en el conservatorio? — Sí, durante cinco años."}},{"phrase":"Quel genre de musique te plaît ? — La musique classique.","translation":"What kind of music do you like? — Classical music.","translations":{"es":"¿Qué tipo de música te gusta? — La música clásica."}},{"phrase":"Serait-il difficile de jouer du violoncelle ? — Il faut être patient.","translation":"Would it be difficult to play the cello? — You have to be patient.","translations":{"es":"¿Sería difícil tocar el violonchelo? — Hay que ser paciente."}},{"phrase":"Je joue du piano et de la batterie.","translation":"I play the piano and the drums.","translations":{"es":"Toco el piano y la batería."}},{"phrase":"Peux-tu me prêter ton micro ? Je dois enregistrer le concert.","translation":"Can you lend me your microphone? I have to record the concert.","translations":{"es":"¿Me prestas tu micrófono? Tengo que grabar el concierto."}},{"phrase":"L''orchestre symphonique arrivera bientôt à Paris.","translation":"The symphony orchestra will arrive in Paris soon.","translations":{"es":"La orquesta sinfónica llegará pronto a París."}},{"phrase":"Combien d''instruments joues-tu ? — Aucun. — Je pensais que tu jouais de la flûte !","translation":"How many instruments do you play? — None. — I thought you played the flute!","translations":{"es":"¿Cuántos instrumentos tocas? — Ninguno. — ¡Pensaba que tocabas la flauta!"}},{"phrase":"Nous formons un groupe, mais nous avons besoin d''une chanteuse.","translation":"We are starting a band, but we need a singer.","translations":{"es":"Estamos formando un grupo, pero necesitamos una cantante."}},{"phrase":"La harpe a un son merveilleux.","translation":"The harp has a wonderful sound.","translations":{"es":"El arpa tiene un sonido maravilloso."}},{"phrase":"Arrête de jouer des cymbales, j''ai mal à la tête !","translation":"Stop playing the cymbals, I have a headache!","translations":{"es":"¡Deja de tocar los platillos, me duele la cabeza!"}},{"phrase":"Peux-tu éteindre la radio ? — Dans une minute, c''est ma chanson préférée !","translation":"Can you turn off the radio? — In a minute, it''s my favorite song!","translations":{"es":"¿Puedes apagar la radio? — ¡En un minuto, es mi canción favorita!"}},{"phrase":"J''ai deux places pour le concert. Tu veux venir avec moi ?","translation":"I have two tickets for the concert. Do you want to come with me?","translations":{"es":"Tengo dos entradas para el concierto. ¿Quieres venir conmigo?"}},{"phrase":"J''aimerais jouer dans un groupe de jazz.","translation":"I would like to play in a jazz band.","translations":{"es":"Me gustaría tocar en un grupo de jazz."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Elle joue ___ violon.\"","options":["au","de","le","du"],"correct":3,"explanation":"Jouer de + le = du.","translations":{"es":{"question":"Completa: «Elle joue ___ violon.»","explanation":"Jouer de + le = du."}}},{"id":"2","question":"Complete: \"Il joue ___ guitare.\"","options":["la","à la","du","de la"],"correct":3,"explanation":"Jouer de + la = de la.","translations":{"es":{"question":"Completa: «Il joue ___ guitare.»","explanation":"Jouer de + la = de la."}}},{"id":"3","question":"Which sentence describes a habit in the past?","options":["Mon père nous chantera une chanson.","Mon père nous a chanté une chanson hier.","Mon père nous chante une chanson.","Mon père nous chantait des chansons."],"correct":3,"explanation":"Imparfait for repeated past actions.","translations":{"es":{"question":"¿Qué frase describe un hábito pasado?","explanation":"Imperfecto para acciones repetidas en el pasado."}}},{"id":"4","question":"Complete: \"Je joue du piano ___ dix ans.\" (and still do)","options":["pendant","il y a","pour","depuis"],"correct":3,"explanation":"Depuis + present for something still going on.","translations":{"es":{"question":"Completa: «Je joue du piano ___ dix ans.» (y sigo)","explanation":"Depuis + presente para algo que continúa."}}},{"id":"5","question":"\"Combien d''instruments joues-tu ? — Aucun.\" Meaning?","options":["Only one.","All of them.","Some.","None."],"correct":3,"explanation":"\"Aucun\" = none.","translations":{"es":{"question":"«Combien d''instruments joues-tu ? — Aucun.» ¿Significado?","explanation":"«Aucun» = ninguno.","options":["Solo uno.","Todos.","Algunos.","Ninguno."]}}},{"id":"6","question":"Where do you study music professionally?","options":["au disque","à la fanfare","à l''opéra","au conservatoire"],"correct":3,"explanation":"Le conservatoire = music school.","translations":{"es":{"question":"¿Dónde se estudia música de forma profesional?","explanation":"Le conservatoire = el conservatorio."}}},{"id":"7","question":"Which is a percussion instrument?","options":["le violon","la harpe","la flûte","la batterie"],"correct":3,"explanation":"La batterie, le tambour, les cymbales.","translations":{"es":{"question":"¿Cuál es un instrumento de percusión?","explanation":"La batterie, le tambour, les cymbales."}}},{"id":"8","question":"Complete: \"On voyage en ___ et en donnant du bonheur.\"","options":["s''amuser","amusé","amusant","s''amusant"],"correct":3,"explanation":"Gerund of a reflexive verb: en s''amusant.","translations":{"es":{"question":"Completa: «On voyage en ___ et en donnant du bonheur.»","explanation":"Gerundio de un verbo pronominal: en s''amusant."}}}]}'::jsonb, 3),
  ('story', 'La batteuse', '{"text":"Je m''appelle Jade et j''ai toujours voulu être musicienne. Je joue de la batterie depuis l''âge de huit ans. Dans ma famille, tout le monde aime la musique. Mon grand-père jouait de l''accordéon dans les bals de village. Le dimanche, nous allions chez lui et il nous jouait de vieilles chansons pendant que ma grand-mère dansait dans la cuisine. Ma mère, elle, chantait dans une chorale, et souvent, nous écoutions du jazz à la radio. Après le lycée, je suis entrée au conservatoire de Lyon, où j''ai appris le solfège et les percussions classiques. Pendant deux ans, j''ai joué des timbales dans l''orchestre symphonique de la ville. Un jour, des amis qui voulaient former un groupe de rock m''ont demandé de les rejoindre : ils n''avaient pas de batteur ! J''ai accepté tout de suite. Depuis, nous voyageons dans toute la France en nous amusant et en donnant du bonheur au public. J''aimerais un jour jouer à l''Olympia, à Paris. Et mon grand-père viendrait sûrement avec son accordéon !","translation":"My name is Jade and I''ve always wanted to be a musician. I''ve been playing the drums since I was eight. In my family, everyone loves music. My grandfather used to play the accordion at village dances. On Sundays, we would go to his house and he would play us old songs while my grandmother danced in the kitchen. My mother sang in a choir, and we often listened to jazz on the radio. After high school, I entered the Lyon conservatory, where I learned music theory and classical percussion. For two years, I played the timpani in the city''s symphony orchestra. One day, some friends who wanted to start a rock band asked me to join them: they didn''t have a drummer! I accepted right away. Since then, we travel all over France having fun and bringing happiness to the audience. One day I would like to play at the Olympia in Paris. And my grandfather would surely come with his accordion!","translations":{"es":"Me llamo Jade y siempre he querido ser música. Toco la batería desde los ocho años. En mi familia a todos les gusta la música. Mi abuelo tocaba el acordeón en los bailes del pueblo. Los domingos íbamos a su casa y nos tocaba canciones antiguas mientras mi abuela bailaba en la cocina. Mi madre, por su parte, cantaba en un coro y a menudo escuchábamos jazz en la radio. Después del instituto entré en el conservatorio de Lyon, donde aprendí solfeo y percusión clásica. Durante dos años toqué los timbales en la orquesta sinfónica de la ciudad. Un día, unos amigos que querían formar un grupo de rock me pidieron que me uniera a ellos: ¡no tenían batería! Acepté enseguida. Desde entonces viajamos por toda Francia divirtiéndonos y dando felicidad al público. Me gustaría tocar algún día en el Olympia de París. ¡Y seguro que mi abuelo vendría con su acordeón!"},"highlighted_words":["Je joue de la batterie depuis","jouait de l''accordéon","nous allions","chantait","conservatoire","j''ai joué","orchestre symphonique","en nous amusant","en donnant","J''aimerais","viendrait"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","joue","du","piano","depuis","dix","ans"],"translation":"I''ve been playing the piano for ten years","translations":{"es":"Toco el piano desde hace diez años"}},{"words":["Elle","chante","dans","une","chorale"],"translation":"She sings in a choir","translations":{"es":"Canta en un coro"}},{"words":["Mon","grand-père","jouait","de","l''accordéon"],"translation":"My grandfather used to play the accordion","translations":{"es":"Mi abuelo tocaba el acordeón"}},{"words":["J''aimerais","jouer","dans","un","groupe"],"translation":"I would like to play in a band","translations":{"es":"Me gustaría tocar en un grupo"}},{"words":["Éteins","la","radio","s''il","te","plaît"],"translation":"Turn off the radio please","translations":{"es":"Apaga la radio, por favor"}},{"words":["Il","faut","être","patient"],"translation":"You have to be patient","translations":{"es":"Hay que ser paciente"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I play the guitar","translations":{"es":"Toco la guitarra"},"answer":"Je joue de la guitare"},{"prompt":"It''s my favorite song","translations":{"es":"Es mi canción favorita"},"answer":"C''est ma chanson préférée"},{"prompt":"You sing very well","translations":{"es":"Cantas muy bien"},"answer":"Tu chantes très bien"},{"prompt":"Turn on the radio","translations":{"es":"Enciende la radio"},"answer":"Allume la radio"},{"prompt":"I like classical music","translations":{"es":"Me gusta la música clásica"},"answer":"J''aime la musique classique"},{"prompt":"She plays the violin","translations":{"es":"Toca el violín"},"answer":"Elle joue du violon"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 27: Les fleurs et le jardin
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-27', 'Les fleurs et le jardin', '🌷', 'Las flores y el jardín', 27, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la fleur","translation":"the flower","translations":{"es":"la flor"}},{"id":"2","word":"le bouquet","translation":"the bouquet","translations":{"es":"el ramo"}},{"id":"3","word":"la rose","translation":"the rose","translations":{"es":"la rosa"}},{"id":"4","word":"la tulipe","translation":"the tulip","translations":{"es":"el tulipán"}},{"id":"5","word":"l''œillet","translation":"the carnation","translations":{"es":"el clavel"}},{"id":"6","word":"la marguerite","translation":"the daisy","translations":{"es":"la margarita"}},{"id":"7","word":"le tournesol","translation":"the sunflower","translations":{"es":"el girasol"}},{"id":"8","word":"la violette","translation":"the violet","translations":{"es":"la violeta"}},{"id":"9","word":"l''orchidée","translation":"the orchid","translations":{"es":"la orquídea"}},{"id":"10","word":"le lys","translation":"the lily","translations":{"es":"el lirio / la azucena"}},{"id":"11","word":"l''iris","translation":"the iris","translations":{"es":"el iris"}},{"id":"12","word":"le muguet","translation":"lily of the valley","translations":{"es":"el lirio de los valles / el muguete"}},{"id":"13","word":"le jasmin","translation":"jasmine","translations":{"es":"el jazmín"}},{"id":"14","word":"l''hortensia","translation":"the hydrangea","translations":{"es":"la hortensia"}},{"id":"15","word":"le géranium","translation":"the geranium","translations":{"es":"el geranio"}},{"id":"16","word":"le dahlia","translation":"the dahlia","translations":{"es":"la dalia"}},{"id":"17","word":"le chrysanthème","translation":"the chrysanthemum","translations":{"es":"el crisantemo"}},{"id":"18","word":"l''azalée","translation":"the azalea","translations":{"es":"la azalea"}},{"id":"19","word":"le camélia","translation":"the camellia","translations":{"es":"la camelia"}},{"id":"20","word":"le magnolia","translation":"the magnolia","translations":{"es":"la magnolia"}},{"id":"21","word":"le mimosa","translation":"mimosa","translations":{"es":"la mimosa"}},{"id":"22","word":"la pivoine","translation":"the peony","translations":{"es":"la peonía"}},{"id":"23","word":"le narcisse","translation":"the narcissus / daffodil","translations":{"es":"el narciso"}},{"id":"24","word":"le lotus","translation":"the lotus","translations":{"es":"el loto"}},{"id":"25","word":"le nénuphar","translation":"the water lily","translations":{"es":"el nenúfar"}},{"id":"26","word":"le cactus","translation":"the cactus","translations":{"es":"el cactus"}},{"id":"27","word":"la graine","translation":"the seed","translations":{"es":"la semilla"}},{"id":"28","word":"le pot de fleurs","translation":"the flowerpot","translations":{"es":"la maceta"}},{"id":"29","word":"la pelle","translation":"the shovel","translations":{"es":"la pala"}},{"id":"30","word":"l''arrosoir","translation":"the watering can","translations":{"es":"la regadera"}},{"id":"31","word":"le pétale","translation":"the petal","translations":{"es":"el pétalo"}},{"id":"32","word":"la tige","translation":"the stem","translations":{"es":"el tallo"}},{"id":"33","word":"fleurir","translation":"to bloom","translations":{"es":"florecer"}},{"id":"34","word":"pousser","translation":"to grow","translations":{"es":"crecer"}},{"id":"35","word":"semer","translation":"to sow","translations":{"es":"sembrar"}},{"id":"36","word":"planter","translation":"to plant","translations":{"es":"plantar"}},{"id":"37","word":"arroser","translation":"to water","translations":{"es":"regar"}},{"id":"38","word":"cueillir","translation":"to pick","translations":{"es":"recoger / coger"}},{"id":"39","word":"le parfum","translation":"the scent","translations":{"es":"el perfume / el aroma"}},{"id":"40","word":"le / la fleuriste","translation":"the florist","translations":{"es":"el / la florista"}}],"grammar":[{"structure":"impératif + pronom (COI)","example":"Offre-lui des iris, elle les adore ! / Offrons-lui des œillets.","en":"Imperative with indirect object","es":"Imperativo con complemento indirecto"},{"structure":"en train de","example":"Le cactus est en train de fleurir.","en":"Action in progress","es":"Acción en curso"},{"structure":"accord du participe passé avec avoir","example":"J''ai trouvé des graines, je les ai semées.","en":"Past participle agreement (pronoun before)","es":"Concordancia del participio (pronombre delante)"},{"structure":"discours indirect au passé","example":"François m''a dit que les clochettes étaient toxiques.","en":"Reported speech","es":"Estilo indirecto"},{"structure":"il me semble que","example":"Il me semble que les azalées aussi.","en":"\"It seems to me that\"","es":"«Me parece que»"},{"structure":"pronom « en »","example":"Des mimosas ? Nous n''en avons pas.","en":"\"en\" replacing a quantity","es":"«en» que sustituye una cantidad"},{"structure":"gérondif / participe présent","example":"en traversant le pays / des fleurs rendant la route agréable","en":"Gerund and present participle","es":"Gerundio y participio presente"},{"structure":"superlatif","example":"les plus belles couleurs","en":"Superlatives","es":"Superlativos"}],"tips":[{"en":"Flower symbolism in France: red roses = love; white = purity; yellow = friendship; chrysanthemums are for cemeteries (1 November) — never give them as a gift!","es":"Simbolismo de las flores en Francia: rosas rojas = amor; blancas = pureza; amarillas = amistad; los crisantemos son para los cementerios (1 de noviembre): ¡nunca los regales!"},{"en":"On 1 May, people give \"un brin de muguet\" (lily of the valley) for good luck. Careful: muguet is toxic if eaten, and so are azaleas.","es":"El 1 de mayo se regala «un brin de muguet» (lirio de los valles) para dar suerte. Ojo: el muguet es tóxico si se come, y las azaleas también."},{"en":"With \"avoir\", the past participle agrees with a direct object placed BEFORE: \"les roses que j''ai coupées\".","es":"Con «avoir», el participio concuerda con el complemento directo colocado DELANTE: «les roses que j''ai coupées»."},{"en":"\"Fleurir\" = to bloom; \"pousser\" = to grow; \"semer\" = to sow; \"arroser\" = to water.","es":"«Fleurir» = florecer; «pousser» = crecer; «semer» = sembrar; «arroser» = regar."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Le cactus est en train de fleurir !","translation":"The cactus is blooming!","translations":{"es":"¡El cactus está floreciendo!"}},{"phrase":"Mets des gants si tu coupes des roses.","translation":"Wear gloves if you cut roses.","translations":{"es":"Ponte guantes si cortas rosas."}},{"phrase":"Offre-lui des iris, elle les adore.","translation":"Give her irises, she loves them.","translations":{"es":"Regálale lirios, le encantan."}},{"phrase":"Marie m''a offert une rose jaune, symbole de l''amitié.","translation":"Marie gave me a yellow rose, a symbol of friendship.","translations":{"es":"Marie me regaló una rosa amarilla, símbolo de la amistad."}},{"phrase":"Sème quelques graines dans le pot de fleurs.","translation":"Sow a few seeds in the flowerpot.","translations":{"es":"Siembra algunas semillas en la maceta."}},{"phrase":"J''adore le parfum des violettes.","translation":"I love the scent of violets.","translations":{"es":"Me encanta el aroma de las violetas."}},{"phrase":"Les marguerites sont mes fleurs préférées.","translation":"Daisies are my favorite flowers.","translations":{"es":"Las margaritas son mis flores favoritas."}},{"phrase":"Les tulipes étaient les fleurs préférées de ma mère.","translation":"Tulips were my mother''s favorite flowers.","translations":{"es":"Los tulipanes eran las flores favoritas de mi madre."}},{"phrase":"François m''a dit que le muguet était toxique. — Il me semble que les azalées aussi.","translation":"François told me that lily of the valley was toxic. — I think azaleas are too.","translations":{"es":"François me dijo que el muguete era tóxico. — Me parece que las azaleas también."}},{"phrase":"Pourriez-vous me faire un bouquet d''iris ? — Désolée, nous n''en avons pas en ce moment.","translation":"Could you make me a bouquet of irises? — Sorry, we don''t have any at the moment.","translations":{"es":"¿Podría hacerme un ramo de lirios? — Lo siento, ahora mismo no tenemos."}},{"phrase":"Combien coûte une douzaine d''œillets ? — Douze euros.","translation":"How much is a dozen carnations? — Twelve euros.","translations":{"es":"¿Cuánto cuesta una docena de claveles? — Doce euros."}},{"phrase":"C''est l''anniversaire de Julie aujourd''hui ? Offrons-lui des tulipes !","translation":"Is it Julie''s birthday today? Let''s give her tulips!","translations":{"es":"¿Hoy es el cumpleaños de Julie? ¡Regalémosle tulipanes!"}},{"phrase":"J''ai trouvé des graines, je les ai semées, et des fuchsias ont poussé.","translation":"I found some seeds, I sowed them, and fuchsias grew.","translations":{"es":"Encontré unas semillas, las sembré y salieron fucsias."}},{"phrase":"Quelles fleurs veux-tu pour le bouquet de la mariée ? — Des pivoines et du jasmin.","translation":"What flowers do you want for the bride''s bouquet? — Peonies and jasmine.","translations":{"es":"¿Qué flores quieres para el ramo de la novia? — Peonías y jazmín."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Offre-___ des roses.\" (to her)","options":["la","leur","lui","elle"],"correct":2,"explanation":"Indirect object (à elle) = lui.","translations":{"es":{"question":"Completa: «Offre-___ des roses.» (a ella)","explanation":"Complemento indirecto (à elle) = lui."}}},{"id":"2","question":"Complete: \"Les graines ? Je les ai ___.\"","options":["semé","semer","semées","semés"],"correct":2,"explanation":"\"Les\" (= les graines, feminine plural) comes before \"avoir\": agreement.","translations":{"es":{"question":"Completa: «Les graines ? Je les ai ___.»","explanation":"«Les» (= les graines, femenino plural) va delante de «avoir»: concordancia."}}},{"id":"3","question":"Which flower should you NOT give as a gift in France?","options":["des pivoines","des roses","des chrysanthèmes","des tulipes"],"correct":2,"explanation":"Chrysanthemums are for graves on 1 November.","translations":{"es":{"question":"¿Qué flor NO debes regalar en Francia?","explanation":"Los crisantemos son para las tumbas el 1 de noviembre."}}},{"id":"4","question":"Reported speech: François said: \"Le muguet est toxique.\" → François m''a dit que le muguet ___ toxique.","options":["soit","était","est été","sera"],"correct":1,"explanation":"Present becomes imparfait after a past reporting verb.","translations":{"es":{"question":"Estilo indirecto: François dijo: «Le muguet est toxique.» → François m''a dit que le muguet ___ toxique.","explanation":"El presente pasa a imperfecto tras un verbo introductor en pasado."}}},{"id":"5","question":"\"Des mimosas ? Nous n''___ avons pas.\"","options":["leur","en","les","y"],"correct":1,"explanation":"\"En\" replaces \"des mimosas\".","translations":{"es":{"question":"«Des mimosas ? Nous n''___ avons pas.»","explanation":"«En» sustituye a «des mimosas»."}}},{"id":"6","question":"What does a yellow rose symbolize?","options":["friendship","purity","love","death"],"correct":0,"explanation":"Red = love, white = purity.","translations":{"es":{"question":"¿Qué simboliza una rosa amarilla?","explanation":"Roja = amor, blanca = pureza.","options":["la amistad","la pureza","el amor","la muerte"]}}},{"id":"7","question":"What does \"arroser\" mean?","options":["to bloom","to water","to sow","to pick"],"correct":1,"explanation":"You water with \"un arrosoir\".","translations":{"es":{"question":"¿Qué significa «arroser»?","explanation":"Se riega con «un arrosoir».","options":["florecer","regar","sembrar","recoger"]}}},{"id":"8","question":"What is \"un tournesol\"?","options":["a daisy","a sunflower","a cactus","a tulip"],"correct":1,"explanation":"Literally \"it turns (to the) sun\".","translations":{"es":{"question":"¿Qué es «un tournesol»?","explanation":"Literalmente «gira (hacia el) sol».","options":["una margarita","un girasol","un cactus","un tulipán"]}}}]}'::jsonb, 3),
  ('story', 'La fleuriste de la rue des Lilas', '{"text":"Depuis vingt ans, Hélène est fleuriste rue des Lilas, à Bordeaux. Au printemps, sa boutique est remplie des plus belles couleurs : des tulipes, des pivoines, du jasmin… En entrant, on sent tout de suite un parfum délicieux. Ce matin, un jeune homme timide arrive. « Bonjour, je voudrais un bouquet pour ma copine. C''est notre premier rendez-vous. » « Offrez-lui des roses rouges, c''est le symbole de l''amour ! » « Euh… ce n''est peut-être pas un peu trop ? » Hélène rit : « Alors, des roses jaunes, pour l''amitié, et quelques marguerites. » Plus tard, une vieille dame demande des chrysanthèmes. « Ma mère m''a toujours dit qu''il ne fallait jamais les offrir en cadeau », explique-t-elle. « Ils sont pour le cimetière. » L''après-midi, Hélène sème des graines dans les pots devant la vitrine. Le mois dernier, elle en a semé d''autres, et les géraniums sont déjà en train de fleurir. Il me semble qu''il n''y a pas de plus joli métier, pense-t-elle en arrosant ses fleurs.","translation":"For twenty years, Hélène has been a florist on Rue des Lilas in Bordeaux. In spring, her shop is full of the most beautiful colors: tulips, peonies, jasmine… As you walk in, you immediately smell a delicious scent. This morning, a shy young man arrives. “Hello, I''d like a bouquet for my girlfriend. It''s our first date.” “Give her red roses, the symbol of love!” “Um… isn''t that maybe a bit much?” Hélène laughs: “Then yellow roses, for friendship, and a few daisies.” Later, an old lady asks for chrysanthemums. “My mother always told me you must never give them as a gift,” she explains. “They are for the cemetery.” In the afternoon, Hélène sows seeds in the pots in front of the shop window. Last month, she sowed some others, and the geraniums are already blooming. It seems to me there''s no lovelier job, she thinks while watering her flowers.","translations":{"es":"Desde hace veinte años, Hélène es florista en la calle des Lilas, en Burdeos. En primavera, su tienda se llena de los colores más bonitos: tulipanes, peonías, jazmín… Al entrar, se nota enseguida un aroma delicioso. Esta mañana llega un joven tímido. «Buenos días, quisiera un ramo para mi novia. Es nuestra primera cita.» «Regálele rosas rojas, ¡son el símbolo del amor!» «Eh… ¿no será un poco demasiado?» Hélène se ríe: «Entonces, rosas amarillas, para la amistad, y unas margaritas.» Más tarde, una señora mayor pide crisantemos. «Mi madre siempre me decía que nunca había que regalarlos», explica. «Son para el cementerio.» Por la tarde, Hélène siembra semillas en las macetas delante del escaparate. El mes pasado sembró otras, y los geranios ya están floreciendo. Me parece que no hay oficio más bonito, piensa mientras riega sus flores."},"highlighted_words":["plus belles couleurs","En entrant","parfum","Offrez-lui","roses rouges","roses jaunes","marguerites","m''a toujours dit qu''il ne fallait","chrysanthèmes","sème des graines","en a semé","en train de fleurir","Il me semble","en arrosant"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Le","cactus","est","en","train","de","fleurir"],"translation":"The cactus is blooming","translations":{"es":"El cactus está floreciendo"}},{"words":["Offre-lui","des","tulipes"],"translation":"Give her tulips","translations":{"es":"Regálale tulipanes"}},{"words":["Les","roses","rouges","symbolisent","l''amour"],"translation":"Red roses symbolize love","translations":{"es":"Las rosas rojas simbolizan el amor"}},{"words":["Je","les","ai","semées","hier"],"translation":"I sowed them yesterday","translations":{"es":"Las sembré ayer"}},{"words":["Nous","n''en","avons","pas"],"translation":"We don''t have any","translations":{"es":"No tenemos"}},{"words":["Il","faut","arroser","les","fleurs"],"translation":"You must water the flowers","translations":{"es":"Hay que regar las flores"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I love daisies","translations":{"es":"Me encantan las margaritas"},"answer":"J''adore les marguerites"},{"prompt":"A bouquet of roses, please","translations":{"es":"Un ramo de rosas, por favor"},"answer":"Un bouquet de roses, s''il vous plaît"},{"prompt":"The sunflower is very tall","translations":{"es":"El girasol es muy alto"},"answer":"Le tournesol est très grand"},{"prompt":"Sow the seeds","translations":{"es":"Siembra las semillas"},"answer":"Sème les graines"},{"prompt":"What is your favorite flower?","translations":{"es":"¿Cuál es tu flor favorita?"},"answer":"Quelle est ta fleur préférée ?"},{"prompt":"The flowers smell good","translations":{"es":"Las flores huelen bien"},"answer":"Les fleurs sentent bon"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 28: Les rendez-vous et les visites
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-28', 'Les rendez-vous et les visites', '📅', 'Las citas y las visitas', 28, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le rendez-vous","translation":"appointment / date","translations":{"es":"la cita"}},{"id":"2","word":"la réunion","translation":"the meeting","translations":{"es":"la reunión"}},{"id":"3","word":"la visite","translation":"the visit","translations":{"es":"la visita"}},{"id":"4","word":"les heures de visite","translation":"visiting hours","translations":{"es":"el horario de visitas"}},{"id":"5","word":"rendre visite à","translation":"to visit (a person)","translations":{"es":"visitar a alguien"}},{"id":"6","word":"passer chez","translation":"to drop by","translations":{"es":"pasar por casa de"}},{"id":"7","word":"venir","translation":"to come","translations":{"es":"venir"}},{"id":"8","word":"revenir","translation":"to come back","translations":{"es":"volver"}},{"id":"9","word":"retourner","translation":"to go back","translations":{"es":"regresar"}},{"id":"10","word":"entrer","translation":"to enter","translations":{"es":"entrar"}},{"id":"11","word":"sortir","translation":"to go out","translations":{"es":"salir"}},{"id":"12","word":"rester","translation":"to stay","translations":{"es":"quedarse"}},{"id":"13","word":"accompagner","translation":"to accompany","translations":{"es":"acompañar"}},{"id":"14","word":"suivre","translation":"to follow","translations":{"es":"seguir"}},{"id":"15","word":"continuer","translation":"to continue","translations":{"es":"continuar"}},{"id":"16","word":"attendre","translation":"to wait","translations":{"es":"esperar"}},{"id":"17","word":"espérer","translation":"to hope","translations":{"es":"esperar (tener esperanza)"}},{"id":"18","word":"déposer","translation":"to drop off","translations":{"es":"dejar (a alguien en un lugar)"}},{"id":"19","word":"occupé / occupée","translation":"busy","translations":{"es":"ocupado / ocupada"}},{"id":"20","word":"libre","translation":"free","translations":{"es":"libre"}},{"id":"21","word":"content / contente","translation":"glad","translations":{"es":"contento / contenta"}},{"id":"22","word":"satisfait / satisfaite","translation":"satisfied","translations":{"es":"satisfecho / satisfecha"}},{"id":"23","word":"reconnaissant / reconnaissante","translation":"grateful","translations":{"es":"agradecido / agradecida"}},{"id":"24","word":"enchanté / enchantée","translation":"delighted (to meet you)","translations":{"es":"encantado / encantada"}},{"id":"25","word":"avoir hâte de","translation":"to look forward to","translations":{"es":"estar deseando"}},{"id":"26","word":"faire la queue","translation":"to stand in line","translations":{"es":"hacer cola"}},{"id":"27","word":"se dépêcher","translation":"to hurry","translations":{"es":"darse prisa"}},{"id":"28","word":"en tête à tête","translation":"one-on-one / in private","translations":{"es":"a solas"}},{"id":"29","word":"souvent","translation":"often","translations":{"es":"a menudo"}},{"id":"30","word":"inattendu / inattendue","translation":"unexpected","translations":{"es":"inesperado / inesperada"}},{"id":"31","word":"frapper à la porte","translation":"to knock at the door","translations":{"es":"llamar a la puerta"}},{"id":"32","word":"le livreur","translation":"the delivery man","translations":{"es":"el repartidor"}}],"grammar":[{"structure":"attendre que + subjonctif","example":"Attendez qu''ils sortent de la salle d''opération.","en":"\"Wait until\" + subjunctive","es":"«Esperar a que» + subjuntivo"},{"structure":"avant que + subjonctif","example":"Dépêche-toi avant que les visites finissent.","en":"\"Before\" + subjunctive","es":"«Antes de que» + subjuntivo"},{"structure":"il faut que / il est rare que + subjonctif","example":"Il faut que je m''habille. / Il est rare qu''une grippe dure si longtemps.","en":"Necessity and rarity + subjunctive","es":"Necesidad y rareza + subjuntivo"},{"structure":"futur simple","example":"Je serai toujours reconnaissante. / Cette fois, nous devrons arriver à l''heure.","en":"Simple future","es":"Futuro simple"},{"structure":"gérondif","example":"Je laisserai les papiers dans ton bureau en rentrant.","en":"Gerund (simultaneity)","es":"Gerundio (simultaneidad)"},{"structure":"passé composé avec être","example":"Est-ce qu''il est venu hier ? — Oui, mais il n''est pas resté longtemps.","en":"Verbs of movement with être","es":"Verbos de movimiento con être"},{"structure":"discours indirect","example":"Il m''a dit de rester allongée. / Il m''a demandé s''il pouvait entrer.","en":"Reported orders and questions","es":"Órdenes y preguntas en estilo indirecto"},{"structure":"mettre du temps à","example":"J''ai mis beaucoup de temps à arriver à la porte.","en":"\"To take time to\"","es":"«Tardar en»"}],"tips":[{"en":"\"Un rendez-vous\" can be an appointment (doctor, bank) or a date. \"Prendre rendez-vous\" = to make an appointment.","es":"«Un rendez-vous» puede ser una cita médica o de trabajo, o una cita romántica. «Prendre rendez-vous» = pedir cita."},{"en":"\"Fais comme chez toi\" = make yourself at home. \"Passer chez quelqu''un\" = to drop by someone''s place.","es":"«Fais comme chez toi» = estás en tu casa. «Passer chez quelqu''un» = pasar por casa de alguien."},{"en":"\"Faire la queue\" = to stand in line.","es":"«Faire la queue» = hacer cola."},{"en":"\"Vendredi, ça vous va ?\" = Does Friday suit you? A very useful phrase for scheduling.","es":"«Vendredi, ça vous va ?» = ¿Le viene bien el viernes? Muy útil para concertar citas."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Attendez qu''ils sortent de la salle d''opération.","translation":"Wait until they come out of surgery.","translations":{"es":"Espere a que salgan del quirófano."}},{"phrase":"Je vous serai toujours reconnaissante de votre aide.","translation":"I will always be grateful for your help.","translations":{"es":"Siempre le estaré agradecida por su ayuda."}},{"phrase":"Aujourd''hui, j''ai rendez-vous chez le dentiste.","translation":"Today, I have a dentist appointment.","translations":{"es":"Hoy tengo cita con el dentista."}},{"phrase":"Rends visite à ta grand-mère plus souvent, s''il te plaît.","translation":"Visit your grandmother more often, please.","translations":{"es":"Visita a tu abuela más a menudo, por favor."}},{"phrase":"Entre, fais comme chez toi !","translation":"Come in, make yourself at home!","translations":{"es":"¡Pasa, estás en tu casa!"}},{"phrase":"Je laisserai les papiers dans ton bureau en rentrant.","translation":"I''ll leave the papers in your office on my way home.","translations":{"es":"Dejaré los papeles en tu despacho al volver a casa."}},{"phrase":"Cette fois, nous devrons arriver à l''heure.","translation":"This time, we will have to arrive on time.","translations":{"es":"Esta vez tendremos que llegar a la hora."}},{"phrase":"Nadine te dit bonjour.","translation":"Nadine says hello.","translations":{"es":"Nadine te manda saludos."}},{"phrase":"Je dois te parler en tête à tête.","translation":"I need to talk to you in private.","translations":{"es":"Tengo que hablar contigo a solas."}},{"phrase":"Je suis allé à la banque et j''ai dû faire la queue pendant une heure.","translation":"I went to the bank and had to queue for an hour.","translations":{"es":"Fui al banco y tuve que hacer cola durante una hora."}},{"phrase":"Revenez plus tard, il est en réunion.","translation":"Come back later, he is in a meeting.","translations":{"es":"Vuelva más tarde, está en una reunión."}},{"phrase":"Pourrais-je avoir un rendez-vous jeudi ? — Désolée, il est très occupé ce jour-là. Vendredi, ça vous va ?","translation":"Could I have an appointment on Thursday? — Sorry, he is very busy that day. Does Friday suit you?","translations":{"es":"¿Podría tener cita el jueves? — Lo siento, ese día está muy ocupado. ¿Le viene bien el viernes?"}},{"phrase":"Dépêche-toi, on doit aller voir Marguerite avant que les visites finissent !","translation":"Hurry up, we have to go see Marguerite before visiting hours end!","translations":{"es":"¡Date prisa, tenemos que ir a ver a Marguerite antes de que termine el horario de visitas!"}},{"phrase":"Attends une minute, il faut que je m''habille !","translation":"Wait a minute, I have to get dressed!","translations":{"es":"¡Espera un minuto, tengo que vestirme!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Attendez qu''il ___.\"","options":["sort","sortira","sorte","sortait"],"correct":2,"explanation":"\"Attendre que\" + subjunctive.","translations":{"es":{"question":"Completa: «Attendez qu''il ___.»","explanation":"«Attendre que» + subjuntivo."}}},{"id":"2","question":"Complete: \"Partons avant qu''il ___.\"","options":["pleuvra","pleuve","pleut","pleuvait"],"correct":1,"explanation":"\"Avant que\" + subjunctive.","translations":{"es":{"question":"Completa: «Partons avant qu''il ___.»","explanation":"«Avant que» + subjuntivo."}}},{"id":"3","question":"Which auxiliary? \"Il ___ venu hier.\"","options":["est","était","a","ont"],"correct":0,"explanation":"Venir, aller, sortir, rester… use \"être\".","translations":{"es":{"question":"¿Qué auxiliar? «Il ___ venu hier.»","explanation":"Venir, aller, sortir, rester… usan «être»."}}},{"id":"4","question":"Reported question: \"Puis-je entrer ?\" → Il m''a demandé ___ il pouvait entrer.","options":["quoi","s''","que","si que"],"correct":1,"explanation":"Yes/no questions are reported with \"si\".","translations":{"es":{"question":"Pregunta indirecta: «Puis-je entrer ?» → Il m''a demandé ___ il pouvait entrer.","explanation":"Las preguntas de sí/no se introducen con «si»."}}},{"id":"5","question":"\"Fais comme chez toi.\" Meaning?","options":["Do it at your place.","Make yourself at home.","Go home.","Your house is nice."],"correct":1,"explanation":"A warm welcome.","translations":{"es":{"question":"«Fais comme chez toi.» ¿Significado?","explanation":"Una bienvenida cálida.","options":["Hazlo en tu casa.","Estás en tu casa.","Vete a casa.","Tu casa es bonita."]}}},{"id":"6","question":"How do you say \"to stand in line\"?","options":["faire la queue","faire la ligne","attendre la file","rester en ligne"],"correct":0,"explanation":"Literally \"to make the tail\".","translations":{"es":{"question":"¿Cómo se dice «hacer cola»?","explanation":"Literalmente «hacer la cola»."}}},{"id":"7","question":"Complete: \"Il est rare qu''une grippe ___ si longtemps.\"","options":["dure-t-elle","dure","durera","durait"],"correct":1,"explanation":"\"Il est rare que\" + subjunctive.","translations":{"es":{"question":"Completa: «Il est rare qu''une grippe ___ si longtemps.»","explanation":"«Il est rare que» + subjuntivo."}}},{"id":"8","question":"\"Rendre visite à\" is used for…","options":["visiting a museum","visiting a person","giving something back","making an appointment"],"correct":1,"explanation":"For places, use \"visiter\": visiter un musée.","translations":{"es":{"question":"«Rendre visite à» se usa para…","explanation":"Para lugares se usa «visiter»: visiter un musée.","options":["visitar un museo","visitar a una persona","devolver algo","pedir cita"]}}}]}'::jsonb, 3),
  ('story', 'Une visite inattendue', '{"text":"Madame Arnaud a quatre-vingts ans et elle habite seule dans un petit appartement à Nantes. Un mardi matin, en descendant de son lit, elle a glissé et elle est tombée. Elle avait très mal à la jambe et son téléphone était resté dans la cuisine. Elle a essayé de se lever, mais c''était impossible. Elle a attendu qu''un voisin passe, mais personne n''est venu. D''un moment à l''autre, quelqu''un a frappé à la porte. « Livraison ! » C''était le livreur qui apportait ses courses, comme tous les mardis. « Entrez, la porte est ouverte ! » a-t-elle crié. Le jeune homme est entré et il l''a trouvée par terre. Il lui a demandé si elle pouvait bouger la jambe, puis il lui a dit de ne pas se lever. Il a appelé les secours et il est resté avec elle jusqu''à ce que l''ambulance arrive. « Il faut que je vous remercie, vous m''avez sauvée ! » lui a-t-elle dit à l''hôpital. Depuis, chaque mardi, le livreur prend cinq minutes pour boire un café avec elle. « Je vous serai toujours reconnaissante », répète Madame Arnaud.","translation":"Mrs. Arnaud is eighty and lives alone in a small apartment in Nantes. One Tuesday morning, while getting out of bed, she slipped and fell. Her leg hurt a lot and her phone had stayed in the kitchen. She tried to get up, but it was impossible. She waited for a neighbor to come by, but nobody came. All of a sudden, someone knocked at the door. “Delivery!” It was the delivery man bringing her groceries, as every Tuesday. “Come in, the door is open!” she shouted. The young man came in and found her on the floor. He asked her if she could move her leg, then told her not to get up. He called the emergency services and stayed with her until the ambulance arrived. “I must thank you, you saved me!” she told him at the hospital. Since then, every Tuesday, the delivery man takes five minutes to have a coffee with her. “I will always be grateful to you,” Mrs. Arnaud repeats.","translations":{"es":"La señora Arnaud tiene ochenta años y vive sola en un pequeño apartamento en Nantes. Un martes por la mañana, al bajarse de la cama, resbaló y se cayó. Le dolía mucho la pierna y el teléfono se había quedado en la cocina. Intentó levantarse, pero era imposible. Esperó a que pasara algún vecino, pero no vino nadie. De repente, alguien llamó a la puerta. «¡Reparto!» Era el repartidor que le traía la compra, como todos los martes. «¡Pase, la puerta está abierta!», gritó. El joven entró y la encontró en el suelo. Le preguntó si podía mover la pierna y luego le dijo que no se levantara. Llamó a emergencias y se quedó con ella hasta que llegó la ambulancia. «¡Tengo que darle las gracias, me ha salvado!», le dijo en el hospital. Desde entonces, cada martes, el repartidor se toma cinco minutos para tomar un café con ella. «Siempre le estaré agradecida», repite la señora Arnaud."},"highlighted_words":["en descendant","elle est tombée","était resté","Elle a attendu qu''un voisin passe","personne n''est venu","a frappé à la porte","Il lui a demandé si","il lui a dit de","jusqu''à ce que","Il faut que je vous remercie","serai toujours reconnaissante"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["J''ai","rendez-vous","chez","le","médecin"],"translation":"I have a doctor''s appointment","translations":{"es":"Tengo cita con el médico"}},{"words":["Attends","qu''il","sorte"],"translation":"Wait until he comes out","translations":{"es":"Espera a que salga"}},{"words":["Il","est","venu","hier","soir"],"translation":"He came last night","translations":{"es":"Vino anoche"}},{"words":["Fais","comme","chez","toi"],"translation":"Make yourself at home","translations":{"es":"Estás en tu casa"}},{"words":["Il","m''a","demandé","si","j''étais","libre"],"translation":"He asked me if I was free","translations":{"es":"Me preguntó si estaba libre"}},{"words":["Vendredi","ça","vous","va"],"translation":"Does Friday suit you","translations":{"es":"¿Le viene bien el viernes?"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I am very busy (f)","translations":{"es":"Estoy muy ocupada"},"answer":"Je suis très occupée"},{"prompt":"Come back later","translations":{"es":"Vuelva más tarde"},"answer":"Revenez plus tard"},{"prompt":"Hurry up","translations":{"es":"Date prisa"},"answer":"Dépêche-toi"},{"prompt":"He is in a meeting","translations":{"es":"Está en una reunión"},"answer":"Il est en réunion"},{"prompt":"Nice to meet you","translations":{"es":"Encantado de conocerte"},"answer":"Enchanté de te connaître"},{"prompt":"Drop by my place tonight","translations":{"es":"Pasa por mi casa esta noche"},"answer":"Passe chez moi ce soir"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 29: Le théâtre et le cinéma
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-29', 'Le théâtre et le cinéma', '🎭', 'El teatro y el cine', 29, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le théâtre","translation":"the theater","translations":{"es":"el teatro"}},{"id":"2","word":"le cinéma","translation":"the cinema","translations":{"es":"el cine"}},{"id":"3","word":"la pièce de théâtre","translation":"the play","translations":{"es":"la obra de teatro"}},{"id":"4","word":"le film","translation":"the movie","translations":{"es":"la película"}},{"id":"5","word":"la séance","translation":"the screening","translations":{"es":"la sesión"}},{"id":"6","word":"le spectacle","translation":"the show","translations":{"es":"el espectáculo"}},{"id":"7","word":"l''acte","translation":"the act","translations":{"es":"el acto"}},{"id":"8","word":"la scène","translation":"the stage / the scene","translations":{"es":"el escenario / la escena"}},{"id":"9","word":"l''acteur / l''actrice","translation":"actor / actress","translations":{"es":"el actor / la actriz"}},{"id":"10","word":"le réalisateur / la réalisatrice","translation":"the film director","translations":{"es":"el director / la directora (de cine)"}},{"id":"11","word":"le metteur en scène","translation":"the stage director","translations":{"es":"el director de escena"}},{"id":"12","word":"la vedette","translation":"the star","translations":{"es":"la estrella"}},{"id":"13","word":"le rôle","translation":"the role","translations":{"es":"el papel"}},{"id":"14","word":"le public","translation":"the audience","translations":{"es":"el público"}},{"id":"15","word":"les applaudissements","translation":"applause","translations":{"es":"los aplausos"}},{"id":"16","word":"applaudir","translation":"to applaud","translations":{"es":"aplaudir"}},{"id":"17","word":"siffler","translation":"to whistle / to boo","translations":{"es":"silbar / abuchear"}},{"id":"18","word":"le rideau","translation":"the curtain","translations":{"es":"el telón"}},{"id":"19","word":"les coulisses","translation":"backstage","translations":{"es":"los bastidores"}},{"id":"20","word":"le décor","translation":"the set","translations":{"es":"el decorado"}},{"id":"21","word":"l''écran","translation":"the screen","translations":{"es":"la pantalla"}},{"id":"22","word":"la place","translation":"the seat","translations":{"es":"el asiento / la entrada"}},{"id":"23","word":"la rangée","translation":"the row","translations":{"es":"la fila"}},{"id":"24","word":"l''orchestre","translation":"the stalls","translations":{"es":"el patio de butacas"}},{"id":"25","word":"le balcon","translation":"the balcony","translations":{"es":"el anfiteatro"}},{"id":"26","word":"l''entracte","translation":"the intermission","translations":{"es":"el entreacto"}},{"id":"27","word":"la bande originale","translation":"the soundtrack","translations":{"es":"la banda sonora"}},{"id":"28","word":"les effets spéciaux","translation":"special effects","translations":{"es":"los efectos especiales"}},{"id":"29","word":"la comédie","translation":"comedy","translations":{"es":"la comedia"}},{"id":"30","word":"la comédie musicale","translation":"musical","translations":{"es":"el musical"}},{"id":"31","word":"le drame","translation":"drama","translations":{"es":"el drama"}},{"id":"32","word":"le documentaire","translation":"documentary","translations":{"es":"el documental"}},{"id":"33","word":"le film d''action","translation":"action movie","translations":{"es":"la película de acción"}},{"id":"34","word":"le dessin animé","translation":"cartoon","translations":{"es":"los dibujos animados"}},{"id":"35","word":"les sous-titres","translation":"subtitles","translations":{"es":"los subtítulos"}},{"id":"36","word":"le pop-corn","translation":"popcorn","translations":{"es":"las palomitas"}},{"id":"37","word":"émouvant / émouvante","translation":"moving","translations":{"es":"conmovedor / conmovedora"}},{"id":"38","word":"drôle","translation":"funny","translations":{"es":"gracioso"}},{"id":"39","word":"ennuyeux / ennuyeuse","translation":"boring","translations":{"es":"aburrido / aburrida"}}],"grammar":[{"structure":"ça te dit de + infinitif","example":"Ça te dit d''aller au cinéma ?","en":"Suggesting an activity","es":"Proponer un plan"},{"structure":"« ça a été » / passé composé","example":"Le premier acte a été ennuyeux, mais ça a été un bon spectacle.","en":"Evaluating past events","es":"Valorar hechos pasados"},{"structure":"se faire + infinitif","example":"Il s''est fait siffler par le public.","en":"Causative / passive \"se faire\"","es":"«Se faire» causativo / pasivo"},{"structure":"pronoms démonstratifs","example":"Je voulais le rôle de la princesse, pas celui de la sorcière.","en":"\"celui de / celle de\"","es":"«el de / la de»"},{"structure":"plus-que-parfait + accord","example":"Elle a mis la robe qu''elle avait achetée pour l''occasion.","en":"Past perfect with agreement","es":"Pluscuamperfecto con concordancia"},{"structure":"conditionnel (futur dans le passé)","example":"La pièce ne serait jouée qu''une seule fois.","en":"Future in the past","es":"Futuro en el pasado"},{"structure":"après avoir + participe","example":"Après avoir fini le travail, elle est allée chez le coiffeur.","en":"\"After having done\"","es":"«Después de haber»"},{"structure":"mourir d''envie de","example":"Elle mourait d''envie de voir ce spectacle.","en":"\"To be dying to\"","es":"«Morirse de ganas de»"}],"tips":[{"en":"\"Une pièce (de théâtre)\" = a play; \"un film\" = a movie; \"une séance\" = a screening; \"l''entracte\" = the intermission.","es":"«Une pièce (de théâtre)» = una obra; «un film» = una película; «une séance» = una sesión; «l''entracte» = el entreacto."},{"en":"\"VO\" (version originale) = original language with subtitles; \"VF\" = dubbed into French.","es":"«VO» (version originale) = versión original subtitulada; «VF» = doblada al francés."},{"en":"In French theaters, \"siffler\" (whistling) is a sign of disapproval, not enthusiasm!","es":"En los teatros franceses, «siffler» (silbar) es señal de desaprobación, ¡no de entusiasmo!"},{"en":"\"Rater / louper\" = to miss (informal). \"Ça m''a plu\" = I liked it.","es":"«Rater / louper» = perderse algo (coloquial). «Ça m''a plu» = me gustó."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Toutes les places sont prises.","translation":"All the seats are taken.","translations":{"es":"Todas las entradas están vendidas."}},{"phrase":"Monte sur scène, c''est ton tour !","translation":"Go on stage, it''s your turn!","translations":{"es":"¡Sal al escenario, te toca!"}},{"phrase":"C''est une grande actrice.","translation":"She is a great actress.","translations":{"es":"Es una gran actriz."}},{"phrase":"La salle est pleine.","translation":"The theater is full.","translations":{"es":"La sala está llena."}},{"phrase":"Le premier acte a été ennuyeux, mais le reste de la pièce a été très drôle.","translation":"The first act was boring, but the rest of the play was very funny.","translations":{"es":"El primer acto fue aburrido, pero el resto de la obra fue muy divertido."}},{"phrase":"Ça a été un film d''action très émouvant.","translation":"It was a very moving action film.","translations":{"es":"Fue una película de acción muy conmovedora."}},{"phrase":"Elle a gagné le prix de la meilleure réalisatrice.","translation":"She won the award for best director.","translations":{"es":"Ganó el premio a la mejor directora."}},{"phrase":"Le rideau s''est levé et la magie a commencé.","translation":"The curtain rose and the magic began.","translations":{"es":"Se levantó el telón y empezó la magia."}},{"phrase":"Il s''est fait siffler quand il a oublié son texte.","translation":"He got booed when he forgot his lines.","translations":{"es":"Lo abuchearon cuando olvidó su texto."}},{"phrase":"Ça te dit d''aller au cinéma ? — Oui, bonne idée !","translation":"Do you feel like going to the movies? — Yes, good idea!","translations":{"es":"¿Te apetece ir al cine? — ¡Sí, buena idea!"}},{"phrase":"Où veux-tu t''asseoir ? — Au milieu de la rangée.","translation":"Where do you want to sit? — In the middle of the row.","translations":{"es":"¿Dónde quieres sentarte? — En el centro de la fila."}},{"phrase":"Quel genre de film aimes-tu ? — Les comédies romantiques.","translation":"What kind of movie do you like? — Romantic comedies.","translations":{"es":"¿Qué tipo de películas te gustan? — Las comedias románticas."}},{"phrase":"Attends l''entracte pour aller aux toilettes, sinon tu vas rater la meilleure scène.","translation":"Wait for the intermission to go to the restroom, otherwise you''ll miss the best scene.","translations":{"es":"Espera al entreacto para ir al baño, si no te vas a perder la mejor escena."}},{"phrase":"Je voulais le rôle de la princesse, pas celui de la sorcière !","translation":"I wanted the role of the princess, not the witch''s!","translations":{"es":"¡Yo quería el papel de la princesa, no el de la bruja!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you suggest going to the movies informally?","options":["Va au cinéma !","Ça te dit d''aller au cinéma ?","Le cinéma est ouvert ?","Tu dois aller au cinéma."],"correct":1,"explanation":"\"Ça te dit de\" + infinitive = do you feel like…?","translations":{"es":{"question":"¿Cómo propones ir al cine de forma informal?","explanation":"«Ça te dit de» + infinitivo = ¿te apetece…?"}}},{"id":"2","question":"What is \"l''entracte\"?","options":["the entrance","the intermission","the curtain","the first act"],"correct":1,"explanation":"The break between two acts.","translations":{"es":{"question":"¿Qué es «l''entracte»?","explanation":"La pausa entre dos actos.","options":["la entrada","el entreacto","el telón","el primer acto"]}}},{"id":"3","question":"In a French theater, if the audience \"siffle\", it means they…","options":["disapprove","want an encore","are laughing","love the show"],"correct":0,"explanation":"Whistling = booing in France.","translations":{"es":{"question":"En un teatro francés, si el público «siffle», significa que…","explanation":"Silbar = abuchear en Francia.","options":["desaprueba","quiere un bis","se está riendo","le encanta el espectáculo"]}}},{"id":"4","question":"Complete: \"Elle a mis la robe qu''elle avait ___.\"","options":["acheter","achetée","achetés","acheté"],"correct":1,"explanation":"Agreement with \"que\" (= la robe) placed before \"avoir\".","translations":{"es":{"question":"Completa: «Elle a mis la robe qu''elle avait ___.»","explanation":"Concordancia con «que» (= la robe) colocado antes de «avoir»."}}},{"id":"5","question":"Complete: \"Je préfère ce rôle à ___ de la sorcière.\"","options":["cela","celui","ceux","celle"],"correct":1,"explanation":"Rôle is masculine singular: celui.","translations":{"es":{"question":"Completa: «Je préfère ce rôle à ___ de la sorcière.»","explanation":"Rôle es masculino singular: celui."}}},{"id":"6","question":"\"VO\" at the cinema means…","options":["original version (with subtitles)","VIP seats","very old film","dubbed version"],"correct":0,"explanation":"VF = dubbed into French.","translations":{"es":{"question":"«VO» en el cine significa…","explanation":"VF = doblada al francés.","options":["versión original (subtitulada)","asientos VIP","película muy antigua","versión doblada"]}}},{"id":"7","question":"Complete: \"___ avoir dîné, ils sont allés au théâtre.\"","options":["Depuis","Après","Pendant","Avant"],"correct":1,"explanation":"Après + past infinitive.","translations":{"es":{"question":"Completa: «___ avoir dîné, ils sont allés au théâtre.»","explanation":"Après + infinitivo compuesto."}}},{"id":"8","question":"\"Il s''est fait siffler.\" Meaning?","options":["He learned to whistle.","He made someone whistle.","He got booed.","He whistled."],"correct":2,"explanation":"\"Se faire\" + infinitive: something happens to the subject.","translations":{"es":{"question":"«Il s''est fait siffler.» ¿Significado?","explanation":"«Se faire» + infinitivo: algo le pasa al sujeto.","options":["Aprendió a silbar.","Hizo silbar a alguien.","Lo abuchearon.","Silbó."]}}}]}'::jsonb, 3),
  ('story', 'Le cadeau de Léa', '{"text":"Aujourd''hui, c''est le quatre-vingtième anniversaire de Robert. Sa petite-fille, Léa, a décidé de l''emmener voir une comédie musicale qu''il mourait d''envie de voir depuis des années. Elle a dû acheter les places trois mois à l''avance, parce que le spectacle ne serait joué qu''une seule fois à Toulouse et que tout le monde voulait le voir. Après avoir fini son travail, Léa est passée chez le coiffeur. Elle a mis la robe bleue qu''elle avait achetée spécialement pour l''occasion. Elle est allée chercher son grand-père vers dix-neuf heures, et ils sont arrivés au théâtre à dix-neuf heures trente. La salle était pleine. Le rideau s''est levé à vingt heures pile. L''orchestre était magnifique et les décors étaient pleins de couleurs. À l''entracte, ils ont partagé un verre de champagne. « Le premier acte a été un peu long, mais les chansons m''ont beaucoup plu », a dit Robert. Le deuxième acte a été encore meilleur : drôle, émouvant et surprenant. À la fin, le public a applaudi pendant dix minutes. « C''est le plus beau cadeau de ma vie », a murmuré Robert.","translation":"Today is Robert''s eightieth birthday. His granddaughter, Léa, decided to take him to see a musical he had been dying to see for years. She had to buy the tickets three months in advance, because the show would be performed only once in Toulouse and everyone wanted to see it. After finishing work, Léa went to the hairdresser. She put on the blue dress she had bought especially for the occasion. She picked up her grandfather around 7 p.m., and they arrived at the theater at 7:30. The theater was full. The curtain rose at 8 p.m. sharp. The orchestra was magnificent and the sets were full of color. At the intermission, they shared a glass of champagne. “The first act was a bit long, but I really liked the songs,” said Robert. The second act was even better: funny, moving and surprising. At the end, the audience applauded for ten minutes. “It''s the most beautiful gift of my life,” Robert whispered.","translations":{"es":"Hoy es el ochenta cumpleaños de Robert. Su nieta, Léa, decidió llevarlo a ver un musical que se moría de ganas de ver desde hacía años. Tuvo que comprar las entradas con tres meses de antelación, porque el espectáculo solo se representaría una vez en Toulouse y todo el mundo quería verlo. Después de terminar el trabajo, Léa pasó por la peluquería. Se puso el vestido azul que se había comprado especialmente para la ocasión. Fue a buscar a su abuelo hacia las siete de la tarde y llegaron al teatro a las siete y media. La sala estaba llena. El telón se levantó a las ocho en punto. La orquesta era magnífica y los decorados estaban llenos de color. En el entreacto compartieron una copa de champán. «El primer acto ha sido un poco largo, pero las canciones me han gustado mucho», dijo Robert. El segundo acto fue todavía mejor: divertido, conmovedor y sorprendente. Al final, el público aplaudió durante diez minutos. «Es el regalo más bonito de mi vida», murmuró Robert."},"highlighted_words":["comédie musicale","mourait d''envie de","à l''avance","ne serait joué qu''une seule fois","Après avoir fini","qu''elle avait achetée","Le rideau","l''entracte","a été","applaudi"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Ça","te","dit","d''aller","au","cinéma"],"translation":"Do you feel like going to the movies","translations":{"es":"¿Te apetece ir al cine?"}},{"words":["Toutes","les","places","sont","prises"],"translation":"All the seats are taken","translations":{"es":"Todas las entradas están vendidas"}},{"words":["C''est","une","grande","actrice"],"translation":"She is a great actress","translations":{"es":"Es una gran actriz"}},{"words":["Le","film","a","été","très","émouvant"],"translation":"The movie was very moving","translations":{"es":"La película fue muy conmovedora"}},{"words":["Attends","l''entracte"],"translation":"Wait for the intermission","translations":{"es":"Espera al entreacto"}},{"words":["La","pièce","m''a","beaucoup","plu"],"translation":"I really liked the play","translations":{"es":"La obra me gustó mucho"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"We''re going to see a comedy","translations":{"es":"Vamos a ver una comedia"},"answer":"On va voir une comédie"},{"prompt":"The theater is full","translations":{"es":"La sala está llena"},"answer":"La salle est pleine"},{"prompt":"I like action movies","translations":{"es":"Me gustan las películas de acción"},"answer":"J''aime les films d''action"},{"prompt":"The curtain rises","translations":{"es":"Se levanta el telón"},"answer":"Le rideau se lève"},{"prompt":"Two seats, please","translations":{"es":"Dos entradas, por favor"},"answer":"Deux places, s''il vous plaît"},{"prompt":"I want to be an actress","translations":{"es":"Quiero ser actriz"},"answer":"Je veux être actrice"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 30: Le téléphone
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-30', 'Le téléphone', '📞', 'El teléfono', 30, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le téléphone","translation":"the telephone","translations":{"es":"el teléfono"}},{"id":"2","word":"le portable","translation":"the mobile phone","translations":{"es":"el móvil / el celular"}},{"id":"3","word":"l''appel","translation":"the call","translations":{"es":"la llamada"}},{"id":"4","word":"appeler","translation":"to call","translations":{"es":"llamar"}},{"id":"5","word":"téléphoner à","translation":"to phone","translations":{"es":"telefonear a"}},{"id":"6","word":"répondre","translation":"to answer","translations":{"es":"contestar"}},{"id":"7","word":"sonner","translation":"to ring","translations":{"es":"sonar"}},{"id":"8","word":"décrocher","translation":"to pick up","translations":{"es":"descolgar"}},{"id":"9","word":"raccrocher","translation":"to hang up","translations":{"es":"colgar"}},{"id":"10","word":"composer un numéro","translation":"to dial a number","translations":{"es":"marcar un número"}},{"id":"11","word":"le numéro de téléphone","translation":"the phone number","translations":{"es":"el número de teléfono"}},{"id":"12","word":"l''indicatif","translation":"the area / country code","translations":{"es":"el prefijo"}},{"id":"13","word":"la ligne","translation":"the line","translations":{"es":"la línea"}},{"id":"14","word":"occupé / occupée","translation":"busy (line)","translations":{"es":"ocupado / ocupada"}},{"id":"15","word":"le répondeur","translation":"the answering machine","translations":{"es":"el contestador"}},{"id":"16","word":"la messagerie","translation":"voicemail","translations":{"es":"el buzón de voz"}},{"id":"17","word":"le message","translation":"the message","translations":{"es":"el mensaje"}},{"id":"18","word":"laisser un message","translation":"to leave a message","translations":{"es":"dejar un mensaje"}},{"id":"19","word":"le texto","translation":"the text message","translations":{"es":"el mensaje de texto"}},{"id":"20","word":"l''annuaire","translation":"the phone book","translations":{"es":"la guía telefónica"}},{"id":"21","word":"l''opérateur / l''opératrice","translation":"the operator","translations":{"es":"el operador / la operadora"}},{"id":"22","word":"le poste","translation":"the extension","translations":{"es":"la extensión"}},{"id":"23","word":"l''appel à l''étranger","translation":"the international call","translations":{"es":"la llamada internacional"}},{"id":"24","word":"urgent / urgente","translation":"urgent","translations":{"es":"urgente"}},{"id":"25","word":"la batterie","translation":"the battery","translations":{"es":"la batería"}},{"id":"26","word":"recharger","translation":"to charge","translations":{"es":"cargar"}},{"id":"27","word":"se tromper de numéro","translation":"to dial the wrong number","translations":{"es":"equivocarse de número"}},{"id":"28","word":"déménager","translation":"to move (house)","translations":{"es":"mudarse"}},{"id":"29","word":"Allô ?","translation":"Hello? (on the phone)","translations":{"es":"¿Diga? / ¿Aló?"}},{"id":"30","word":"Ne quittez pas","translation":"Hold on","translations":{"es":"No cuelgue"}}],"grammar":[{"structure":"ça fait … que","example":"Ça fait une heure que tu es au téléphone !","en":"Duration up to now","es":"Duración hasta ahora («hace … que»)"},{"structure":"impératif + pronom","example":"Réponds-y ! Laisse-le sonner. Écris-le.","en":"Imperative with pronouns","es":"Imperativo con pronombres"},{"structure":"se tromper (de)","example":"Vous vous êtes trompé de numéro.","en":"\"To get the wrong…\"","es":"«Equivocarse de»"},{"structure":"passé composé / imparfait","example":"Je suis rentrée épuisée ; ma fille était au téléphone, comme toujours.","en":"Event vs. background","es":"Hecho frente a contexto"},{"structure":"plus-que-parfait","example":"C''est ma fille qui avait envoyé mon CV.","en":"Past perfect","es":"Pluscuamperfecto"},{"structure":"jusqu''à ce que + subjonctif","example":"Elle m''a regardée jusqu''à ce que je lui demande ce qui se passait.","en":"\"Until\" + subjunctive","es":"«Hasta que» + subjuntivo"},{"structure":"discours indirect","example":"Je lui ai demandé ce qui se passait.","en":"Reported question","es":"Pregunta indirecta"},{"structure":"même si","example":"Elle parle avec ses amis même si elle les voit tous les jours.","en":"\"Even if\"","es":"«Aunque»"}],"tips":[{"en":"On the phone: \"Allô ?\" (hello), \"C''est de la part de qui ?\" (who''s calling?), \"Ne quittez pas\" (hold on), \"Je vous le passe\" (I''ll put him through).","es":"Al teléfono: «Allô ?» (¿diga?), «C''est de la part de qui ?» (¿de parte de quién?), «Ne quittez pas» (no cuelgue), «Je vous le passe» (le paso con él)."},{"en":"\"Raccrocher au nez de quelqu''un\" = to hang up on someone.","es":"«Raccrocher au nez de quelqu''un» = colgarle el teléfono a alguien."},{"en":"French phone numbers are read in pairs: 06 12 34 56 78 = \"zéro six, douze, trente-quatre, cinquante-six, soixante-dix-huit\".","es":"Los números de teléfono franceses se leen de dos en dos: 06 12 34 56 78 = «zéro six, douze, trente-quatre, cinquante-six, soixante-dix-huit»."},{"en":"\"Un portable\" = a mobile phone; \"un texto / un SMS\" = a text message; \"la messagerie\" = voicemail.","es":"«Un portable» = un móvil / celular; «un texto / un SMS» = un mensaje; «la messagerie» = el buzón de voz."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Réponds au téléphone, s''il te plaît !","translation":"Answer the phone, please!","translations":{"es":"¡Contesta el teléfono, por favor!"}},{"phrase":"La ligne est occupée.","translation":"The line is busy.","translations":{"es":"La línea está ocupada."}},{"phrase":"Les appels à l''étranger coûtent plus cher.","translation":"Calls abroad cost more.","translations":{"es":"Las llamadas al extranjero cuestan más."}},{"phrase":"Raccroche ! Ça fait plus d''une heure que tu parles.","translation":"Hang up! You''ve been talking for over an hour.","translations":{"es":"¡Cuelga! Llevas más de una hora hablando."}},{"phrase":"Mélissa, on t''appelle de l''étranger !","translation":"Mélissa, someone''s calling you from abroad!","translations":{"es":"¡Mélissa, te llaman del extranjero!"}},{"phrase":"Est-ce que je peux parler à Marie ? — Désolé, vous vous êtes trompé de numéro.","translation":"Can I speak to Marie? — Sorry, you have the wrong number.","translations":{"es":"¿Puedo hablar con Marie? — Lo siento, se ha equivocado de número."}},{"phrase":"Peux-tu me rappeler un peu plus tard ?","translation":"Can you call me back a bit later?","translations":{"es":"¿Puedes llamarme un poco más tarde?"}},{"phrase":"J''ai laissé un message sur son répondeur, mais il ne m''a pas rappelé.","translation":"I left a message on his answering machine, but he didn''t call me back.","translations":{"es":"Le dejé un mensaje en el contestador, pero no me devolvió la llamada."}},{"phrase":"Il y a un message urgent pour toi sur la ligne quatre.","translation":"There''s an urgent message for you on line four.","translations":{"es":"Hay un mensaje urgente para ti en la línea cuatro."}},{"phrase":"Elle m''a raccroché au nez !","translation":"She hung up on me!","translations":{"es":"¡Me colgó!"}},{"phrase":"Allô, qui est à l''appareil ? — C''est moi, Philippe.","translation":"Hello, who''s speaking? — It''s me, Philippe.","translations":{"es":"¿Diga? ¿Quién es? — Soy yo, Philippe."}},{"phrase":"Tu peux répondre ? — Je suis occupé, laisse-le sonner.","translation":"Can you answer? — I''m busy, let it ring.","translations":{"es":"¿Puedes contestar? — Estoy ocupado, déjalo sonar."}},{"phrase":"Tu me donnes ton numéro ? — Oui, écris-le : zéro six, douze, trente-quatre…","translation":"Will you give me your number? — Yes, write it down: 06 12 34…","translations":{"es":"¿Me das tu número? — Sí, apúntalo: cero seis, doce, treinta y cuatro…"}},{"phrase":"Je voudrais parler à Madame Durand. — Elle n''habite plus ici, elle a déménagé.","translation":"I would like to speak to Mrs. Durand. — She doesn''t live here anymore, she moved.","translations":{"es":"Quisiera hablar con la señora Durand. — Ya no vive aquí, se mudó."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"What do you say when you pick up the phone in France?","options":["Oui, merci.","Salut, ça va ?","Allô ?","Bonjour, au revoir."],"correct":2,"explanation":"\"Allô\" is only used on the phone.","translations":{"es":{"question":"¿Qué dices al descolgar el teléfono en Francia?","explanation":"«Allô» solo se usa al teléfono."}}},{"id":"2","question":"Complete: \"Ça fait une heure ___ tu parles !\"","options":["quand","pendant","que","depuis"],"correct":2,"explanation":"\"Ça fait + duration + que\" + present.","translations":{"es":{"question":"Completa: «Ça fait une heure ___ tu parles !»","explanation":"«Ça fait + duración + que» + presente."}}},{"id":"3","question":"\"Vous vous êtes trompé de numéro.\" Meaning?","options":["You forgot the number.","The number is busy.","You have the wrong number.","Your number changed."],"correct":2,"explanation":"\"Se tromper de\" + noun = to get the wrong…","translations":{"es":{"question":"«Vous vous êtes trompé de numéro.» ¿Significado?","explanation":"«Se tromper de» + sustantivo = equivocarse de…","options":["Ha olvidado el número.","El número está ocupado.","Se ha equivocado de número.","Su número ha cambiado."]}}},{"id":"4","question":"What does \"raccrocher\" mean?","options":["to dial","to hang up","to ring","to pick up"],"correct":1,"explanation":"Décrocher = to pick up.","translations":{"es":{"question":"¿Qué significa «raccrocher»?","explanation":"Décrocher = descolgar.","options":["marcar","colgar","sonar","descolgar"]}}},{"id":"5","question":"Complete: \"Elle m''a regardée jusqu''à ce que je lui ___ ce qui se passait.\"","options":["ai demandé","demande","demanderai","demandais"],"correct":1,"explanation":"\"Jusqu''à ce que\" + subjunctive.","translations":{"es":{"question":"Completa: «Elle m''a regardée jusqu''à ce que je lui ___ ce qui se passait.»","explanation":"«Jusqu''à ce que» + subjuntivo."}}},{"id":"6","question":"How do you say \"Hold on\" on the phone?","options":["Ne quittez pas.","Ne raccrochez jamais.","Restez là.","Ne partez pas."],"correct":0,"explanation":"\"Ne quittez pas\" is the standard formula.","translations":{"es":{"question":"¿Cómo se dice «No cuelgue» al teléfono?","explanation":"«Ne quittez pas» es la fórmula habitual."}}},{"id":"7","question":"How do you read 06 45 78 12 90?","options":["zéro six, quarante-cinq, soixante-dix-huit, douze, quatre-vingt-dix","six millions…","zéro six cent quarante-cinq…","zéro, six, quatre, cinq, sept, huit…"],"correct":0,"explanation":"In pairs.","translations":{"es":{"question":"¿Cómo se lee 06 45 78 12 90?","explanation":"De dos en dos."}}},{"id":"8","question":"\"Laisse-le sonner.\" What does \"le\" replace?","options":["the person","the phone","the number","the message"],"correct":1,"explanation":"Le = le téléphone.","translations":{"es":{"question":"«Laisse-le sonner.» ¿Qué sustituye «le»?","explanation":"Le = le téléphone.","options":["la persona","el teléfono","el número","el mensaje"]}}}]}'::jsonb, 3),
  ('story', 'L''appel qui a changé ma vie', '{"text":"Ma fille Chloé passe presque tout son temps libre au téléphone. Elle parle pendant des heures avec ses amies, même si elle les voit tous les jours au lycée. Il y a deux mois, j''ai perdu mon travail, et nous avons commencé à nous disputer à cause de son portable. « Ça fait trois heures que tu es au téléphone ! Raccroche ! » lui répétais-je. Un soir, je suis rentrée épuisée après une journée d''entretiens. Chloé était au téléphone, comme toujours. Je me suis énervée et j''ai crié. Elle n''a rien dit et elle m''a regardée jusqu''à ce que je lui demande ce qui se passait. Elle m''a tendu le téléphone : « Maman, sois gentille, c''est pour toi. » C''était le directeur d''une grande entreprise de la ville, le père d''une de ses amies. Il cherchait quelqu''un avec mon profil et il m''a proposé un poste ! En fait, c''était Chloé qui lui avait envoyé mon CV. Je me suis excusée auprès d''elle. Aujourd''hui, j''ai un travail que j''adore… et je ne dis plus rien quand elle est au téléphone.","translation":"My daughter Chloé spends almost all her free time on the phone. She talks for hours with her friends, even though she sees them every day at school. Two months ago, I lost my job, and we started arguing about her phone. “You''ve been on the phone for three hours! Hang up!” I kept telling her. One evening, I came home exhausted after a day of interviews. Chloé was on the phone, as always. I got angry and shouted. She didn''t say anything and looked at me until I asked her what was going on. She handed me the phone: “Mom, be nice, it''s for you.” It was the director of a big company in town, the father of one of her friends. He was looking for someone with my profile and he offered me a job! In fact, it was Chloé who had sent him my résumé. I apologized to her. Today, I have a job I love… and I don''t say anything anymore when she''s on the phone.","translations":{"es":"Mi hija Chloé pasa casi todo su tiempo libre al teléfono. Habla durante horas con sus amigas, aunque las ve todos los días en el instituto. Hace dos meses perdí mi trabajo y empezamos a discutir por su móvil. «¡Llevas tres horas al teléfono! ¡Cuelga!», le repetía. Una noche volví a casa agotada después de un día de entrevistas. Chloé estaba al teléfono, como siempre. Me enfadé y grité. Ella no dijo nada y me miró hasta que le pregunté qué pasaba. Me tendió el teléfono: «Mamá, sé amable, es para ti.» Era el director de una gran empresa de la ciudad, el padre de una de sus amigas. Buscaba a alguien con mi perfil y ¡me ofreció un puesto! De hecho, había sido Chloé quien le había enviado mi currículum. Le pedí perdón. Hoy tengo un trabajo que me encanta… y ya no digo nada cuando está al teléfono."},"highlighted_words":["même si","Il y a deux mois","Ça fait trois heures que","Raccroche","était au téléphone","jusqu''à ce que je lui demande","ce qui se passait","lui avait envoyé"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["La","ligne","est","occupée"],"translation":"The line is busy","translations":{"es":"La línea está ocupada"}},{"words":["Rappelle-moi","plus","tard"],"translation":"Call me back later","translations":{"es":"Llámame más tarde"}},{"words":["J''ai","laissé","un","message"],"translation":"I left a message","translations":{"es":"He dejado un mensaje"}},{"words":["Vous","vous","êtes","trompé","de","numéro"],"translation":"You have the wrong number","translations":{"es":"Se ha equivocado de número"}},{"words":["Ça","fait","une","heure","que","tu","parles"],"translation":"You''ve been talking for an hour","translations":{"es":"Llevas una hora hablando"}},{"words":["Elle","a","raccroché"],"translation":"She hung up","translations":{"es":"Ha colgado"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Answer the phone","translations":{"es":"Contesta el teléfono"},"answer":"Réponds au téléphone"},{"prompt":"What''s your number?","translations":{"es":"¿Cuál es tu número?"},"answer":"Quel est ton numéro ?"},{"prompt":"I''m waiting for your call","translations":{"es":"Espero tu llamada"},"answer":"J''attends ton appel"},{"prompt":"Hold on","translations":{"es":"No cuelgue"},"answer":"Ne quittez pas"},{"prompt":"You didn''t call me yesterday","translations":{"es":"No me llamaste ayer"},"answer":"Tu ne m''as pas appelé hier"},{"prompt":"My phone isn''t working","translations":{"es":"Mi móvil no funciona"},"answer":"Mon portable ne marche pas"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 31: À l'agence de voyages
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-31', 'À l''agence de voyages', '🧳', 'En la agencia de viajes', 31, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''agence de voyages","translation":"the travel agency","translations":{"es":"la agencia de viajes"}},{"id":"2","word":"l''agent de voyages","translation":"the travel agent","translations":{"es":"el agente de viajes"}},{"id":"3","word":"le voyage","translation":"the trip","translations":{"es":"el viaje"}},{"id":"4","word":"le voyage d''affaires","translation":"the business trip","translations":{"es":"el viaje de negocios"}},{"id":"5","word":"le voyage de noces","translation":"the honeymoon","translations":{"es":"la luna de miel"}},{"id":"6","word":"la croisière","translation":"the cruise","translations":{"es":"el crucero"}},{"id":"7","word":"l''aventure","translation":"adventure","translations":{"es":"la aventura"}},{"id":"8","word":"la réservation","translation":"the booking","translations":{"es":"la reserva"}},{"id":"9","word":"réserver","translation":"to book","translations":{"es":"reservar"}},{"id":"10","word":"annuler","translation":"to cancel","translations":{"es":"cancelar"}},{"id":"11","word":"l''itinéraire","translation":"the itinerary","translations":{"es":"el itinerario"}},{"id":"12","word":"le séjour","translation":"the stay","translations":{"es":"la estancia"}},{"id":"13","word":"la destination","translation":"the destination","translations":{"es":"el destino"}},{"id":"14","word":"le départ","translation":"the departure","translations":{"es":"la salida"}},{"id":"15","word":"le retour","translation":"the return","translations":{"es":"la vuelta"}},{"id":"16","word":"l''aller simple","translation":"the one-way ticket","translations":{"es":"el billete de ida"}},{"id":"17","word":"l''aller-retour","translation":"the return ticket","translations":{"es":"el billete de ida y vuelta"}},{"id":"18","word":"l''hôtel","translation":"the hotel","translations":{"es":"el hotel"}},{"id":"19","word":"le chalet","translation":"the chalet","translations":{"es":"el chalé / la cabaña"}},{"id":"20","word":"le bord de mer","translation":"the seaside","translations":{"es":"la costa"}},{"id":"21","word":"la valise","translation":"the suitcase","translations":{"es":"la maleta"}},{"id":"22","word":"les bagages","translation":"luggage","translations":{"es":"el equipaje"}},{"id":"23","word":"faire ses valises","translation":"to pack","translations":{"es":"hacer las maletas"}},{"id":"24","word":"le sac","translation":"the bag","translations":{"es":"la bolsa"}},{"id":"25","word":"le coffre","translation":"the car trunk","translations":{"es":"el maletero"}},{"id":"26","word":"à l''étranger","translation":"abroad","translations":{"es":"en el extranjero"}},{"id":"27","word":"étranger / étrangère","translation":"foreign / foreigner","translations":{"es":"extranjero / extranjera"}},{"id":"28","word":"le touriste","translation":"the tourist","translations":{"es":"el turista"}},{"id":"29","word":"l''information","translation":"information","translations":{"es":"la información"}},{"id":"30","word":"compris / comprise","translation":"included","translations":{"es":"incluido / incluida"}},{"id":"31","word":"coûter","translation":"to cost","translations":{"es":"costar"}},{"id":"32","word":"dépenser","translation":"to spend","translations":{"es":"gastar"}},{"id":"33","word":"payer","translation":"to pay","translations":{"es":"pagar"}},{"id":"34","word":"organiser","translation":"to organize","translations":{"es":"organizar"}},{"id":"35","word":"prêt / prête","translation":"ready","translations":{"es":"listo / lista"}},{"id":"36","word":"rester","translation":"to stay","translations":{"es":"quedarse"}},{"id":"37","word":"revenir","translation":"to come back","translations":{"es":"volver"}}],"grammar":[{"structure":"il faut que + subjonctif","example":"Il faut que je parte bientôt. / Il faut que je fasse mes valises.","en":"Necessity + subjunctive","es":"Necesidad + subjuntivo"},{"structure":"il nous faut + nom / infinitif","example":"Il nous faut bien organiser le voyage.","en":"\"We need\"","es":"«Necesitamos»"},{"structure":"ne … que","example":"Ce n''est qu''un voyage d''affaires.","en":"\"only\"","es":"«solo»"},{"structure":"le moins / le plus possible","example":"Nous emportons le moins de choses possible.","en":"\"As little / as much as possible\"","es":"«Lo menos / lo más posible»"},{"structure":"impératif négatif","example":"N''emporte pas l''ordinateur ! N''oublie pas de réserver le vol.","en":"Negative imperative","es":"Imperativo negativo"},{"structure":"voix passive","example":"Tout a été organisé par notre agent de voyages.","en":"Passive voice","es":"Voz pasiva"},{"structure":"ainsi / éviter de","example":"Faisons les valises à temps : ainsi, nous éviterons d''oublier quelque chose.","en":"Consequence and avoidance","es":"Consecuencia y evitar algo"},{"structure":"premièrement / deuxièmement / enfin","example":"Premièrement, cela rapproche la famille…","en":"Ordering ideas","es":"Ordenar ideas"}],"tips":[{"en":"\"Faire ses valises / ses bagages\" = to pack; \"défaire ses valises\" = to unpack.","es":"«Faire ses valises / ses bagages» = hacer las maletas; «défaire ses valises» = deshacerlas."},{"en":"\"Un voyage de noces\" = honeymoon; \"un voyage d''affaires\" = business trip; \"une croisière\" = cruise.","es":"«Un voyage de noces» = luna de miel; «un voyage d''affaires» = viaje de negocios; «une croisière» = crucero."},{"en":"Hotels: \"un lit double\" (double bed), \"deux lits simples\" (twin beds), \"petit-déjeuner compris\" (breakfast included), \"taxes comprises\" (taxes included).","es":"Hoteles: «un lit double» (cama de matrimonio), «deux lits simples» (dos camas individuales), «petit-déjeuner compris» (desayuno incluido), «taxes comprises» (impuestos incluidos)."},{"en":"\"À l''étranger\" = abroad; \"un étranger / une étrangère\" = a foreigner.","es":"«À l''étranger» = en el extranjero; «un étranger / une étrangère» = un extranjero / una extranjera."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"J''ai un long voyage qui m''attend ; il faut que je parte bientôt.","translation":"I have a long trip ahead of me; I have to leave soon.","translations":{"es":"Me espera un largo viaje; tengo que irme pronto."}},{"phrase":"Nous faisons toujours les valises la veille du départ.","translation":"We always pack the day before departure.","translations":{"es":"Siempre hacemos las maletas la víspera de la salida."}},{"phrase":"Le voyage coûte cher : il nous faut bien l''organiser.","translation":"The trip is expensive: we need to organize it well.","translations":{"es":"El viaje es caro: tenemos que organizarlo bien."}},{"phrase":"N''oublie pas de réserver notre vol !","translation":"Don''t forget to book our flight!","translations":{"es":"¡No olvides reservar nuestro vuelo!"}},{"phrase":"On dépense beaucoup d''argent quand on part en voyage.","translation":"You spend a lot of money when you travel.","translations":{"es":"Se gasta mucho dinero cuando uno se va de viaje."}},{"phrase":"Ils vivent à l''étranger depuis cinq ans.","translation":"They have been living abroad for five years.","translations":{"es":"Viven en el extranjero desde hace cinco años."}},{"phrase":"N''emporte pas l''ordinateur : c''est un voyage pour se reposer !","translation":"Don''t take the computer: it''s a trip to relax!","translations":{"es":"No te lleves el ordenador: ¡es un viaje para descansar!"}},{"phrase":"Nous avons besoin d''informations sur la Provence.","translation":"We need information about Provence.","translations":{"es":"Necesitamos información sobre la Provenza."}},{"phrase":"Un aller simple pour Bordeaux, s''il vous plaît.","translation":"A one-way ticket to Bordeaux, please.","translations":{"es":"Un billete de ida a Burdeos, por favor."}},{"phrase":"Nous voulons partir cet été. Pouvez-vous nous faire une réservation ?","translation":"We want to go away this summer. Can you make a booking for us?","translations":{"es":"Queremos irnos este verano. ¿Puede hacernos una reserva?"}},{"phrase":"Pourquoi tu ne restes pas plus longtemps au Japon ? — Parce que ce n''est qu''un voyage d''affaires.","translation":"Why aren''t you staying longer in Japan? — Because it''s only a business trip.","translations":{"es":"¿Por qué no te quedas más tiempo en Japón? — Porque solo es un viaje de negocios."}},{"phrase":"Vous voulez un lit double ? — Non, deux lits simples, s''il vous plaît.","translation":"Would you like a double bed? — No, two single beds, please.","translations":{"es":"¿Quieren una cama de matrimonio? — No, dos camas individuales, por favor."}},{"phrase":"Nous voulons partir un week-end. Que nous conseillez-vous ? — Un chalet au bord du lac.","translation":"We want to go away for a weekend. What do you recommend? — A chalet by the lake.","translations":{"es":"Queremos irnos un fin de semana. ¿Qué nos recomienda? — Un chalé a orillas del lago."}},{"phrase":"Tout a été organisé par notre agent de voyages le mois dernier.","translation":"Everything was organized by our travel agent last month.","translations":{"es":"Todo lo organizó nuestro agente de viajes el mes pasado."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Il faut que je ___ mes valises.\"","options":["fais","ferai","fasse","faisais"],"correct":2,"explanation":"Faire → que je fasse (subjunctive).","translations":{"es":{"question":"Completa: «Il faut que je ___ mes valises.»","explanation":"Faire → que je fasse (subjuntivo)."}}},{"id":"2","question":"Complete: \"Il faut que je ___ demain matin.\" (partir)","options":["partirai","parte","pars","partais"],"correct":1,"explanation":"Partir → que je parte.","translations":{"es":{"question":"Completa: «Il faut que je ___ demain matin.» (partir)","explanation":"Partir → que je parte."}}},{"id":"3","question":"\"Ce n''est qu''un voyage d''affaires.\" Meaning?","options":["It''s only a business trip.","It''s a long business trip.","It''s not a business trip.","It''s my first business trip."],"correct":0,"explanation":"\"Ne … que\" = only.","translations":{"es":{"question":"«Ce n''est qu''un voyage d''affaires.» ¿Significado?","explanation":"«Ne … que» = solo.","options":["Solo es un viaje de negocios.","Es un viaje de negocios largo.","No es un viaje de negocios.","Es mi primer viaje de negocios."]}}},{"id":"4","question":"What is \"un voyage de noces\"?","options":["a business trip","a honeymoon","a night trip","a school trip"],"correct":1,"explanation":"Les noces = the wedding.","translations":{"es":{"question":"¿Qué es «un voyage de noces»?","explanation":"Les noces = la boda.","options":["un viaje de negocios","una luna de miel","un viaje nocturno","un viaje escolar"]}}},{"id":"5","question":"How do you say \"Don''t forget your passport!\"?","options":["Ne oublie ton passeport !","N''oublie pas ton passeport !","Oublie pas ton passeport !","Tu n''oublies passeport !"],"correct":1,"explanation":"Negative imperative: ne + verb + pas.","translations":{"es":{"question":"¿Cómo se dice «¡No olvides tu pasaporte!»?","explanation":"Imperativo negativo: ne + verbo + pas."}}},{"id":"6","question":"\"Petit-déjeuner compris\" means…","options":["breakfast included","breakfast understood","breakfast extra","no breakfast"],"correct":0,"explanation":"\"Compris\" = included here.","translations":{"es":{"question":"«Petit-déjeuner compris» significa…","explanation":"Aquí «compris» = incluido.","options":["desayuno incluido","desayuno entendido","desayuno aparte","sin desayuno"]}}},{"id":"7","question":"Complete: \"Nous emportons le ___ de choses possible.\"","options":["moins","peu","moindre","minimum que"],"correct":0,"explanation":"\"Le moins … possible\" = as little as possible.","translations":{"es":{"question":"Completa: «Nous emportons le ___ de choses possible.»","explanation":"«Le moins … possible» = lo menos posible."}}},{"id":"8","question":"\"À l''étranger\" means…","options":["to a stranger","abroad","strangely","at the border"],"correct":1,"explanation":"Vivre à l''étranger = to live abroad.","translations":{"es":{"question":"«À l''étranger» significa…","explanation":"Vivre à l''étranger = vivir en el extranjero.","options":["a un desconocido","en el extranjero","de forma extraña","en la frontera"]}}}]}'::jsonb, 3),
  ('story', 'Une famille voyageuse', '{"text":"Chaque année, pour les vacances de février, notre famille part quelque part. Cette fois, nous allons au Maroc. Il y a deux mois, nous sommes allés à l''agence de voyages, et tout a été organisé par notre agente, Madame Leclerc : les billets d''avion, l''hôtel à Marrakech et une excursion dans le désert. « Il faut que vous fassiez vos valises à l''avance », nous a-t-elle conseillé. Alors, nous les faisons toujours trois jours avant le départ : ainsi, nous évitons d''oublier les choses importantes. Quand nous voyageons à l''étranger, nous nous habillons confortablement et nous emportons le moins de choses possible. Moi, j''aime visiter les sites historiques. Mon mari, lui, préfère engager un guide qui lui explique tout. Et nos enfants adorent jouer avec d''autres enfants qui leur apprennent de nouveaux jeux. Pour nous, voyager a trois avantages. Premièrement, cela rapproche la famille. Deuxièmement, nous apprenons quelques mots d''une autre langue. Et enfin, nous nous faisons des amis partout dans le monde !","translation":"Every year, for the February holidays, our family goes somewhere. This time, we''re going to Morocco. Two months ago, we went to the travel agency, and everything was organized by our agent, Mrs. Leclerc: the plane tickets, the hotel in Marrakech and an excursion into the desert. “You need to pack your suitcases in advance,” she advised us. So we always pack three days before departure: that way, we avoid forgetting important things. When we travel abroad, we dress comfortably and take as few things as possible. I like visiting historic sites. My husband prefers to hire a guide who explains everything to him. And our children love playing with other children who teach them new games. For us, traveling has three advantages. First, it brings the family closer. Second, we learn a few words of another language. And finally, we make friends all over the world!","translations":{"es":"Cada año, en las vacaciones de febrero, nuestra familia se va a algún sitio. Esta vez vamos a Marruecos. Hace dos meses fuimos a la agencia de viajes y nuestra agente, la señora Leclerc, lo organizó todo: los billetes de avión, el hotel en Marrakech y una excursión al desierto. «Tienen que hacer las maletas con antelación», nos aconsejó. Así que siempre las hacemos tres días antes de salir: de este modo evitamos olvidar las cosas importantes. Cuando viajamos al extranjero, nos vestimos cómodos y llevamos lo menos posible. A mí me gusta visitar los lugares históricos. Mi marido, en cambio, prefiere contratar a un guía que se lo explique todo. Y a nuestros hijos les encanta jugar con otros niños que les enseñan juegos nuevos. Para nosotros, viajar tiene tres ventajas. Primero, une a la familia. Segundo, aprendemos algunas palabras de otro idioma. Y por último, ¡hacemos amigos en todo el mundo!"},"highlighted_words":["l''agence de voyages","a été organisé","Il faut que vous fassiez","ainsi","nous évitons d''oublier","à l''étranger","le moins de choses possible","Premièrement","Deuxièmement","enfin"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Il","faut","que","je","fasse","mes","valises"],"translation":"I have to pack my suitcases","translations":{"es":"Tengo que hacer las maletas"}},{"words":["N''oublie","pas","de","réserver","l''hôtel"],"translation":"Don''t forget to book the hotel","translations":{"es":"No olvides reservar el hotel"}},{"words":["Ce","n''est","qu''un","voyage","d''affaires"],"translation":"It''s only a business trip","translations":{"es":"Solo es un viaje de negocios"}},{"words":["Ils","vivent","à","l''étranger"],"translation":"They live abroad","translations":{"es":"Viven en el extranjero"}},{"words":["Tout","a","été","organisé","par","l''agence"],"translation":"Everything was organized by the agency","translations":{"es":"La agencia lo organizó todo"}},{"words":["Quand","reviens-tu"],"translation":"When are you coming back","translations":{"es":"¿Cuándo vuelves?"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I would like to make a booking","translations":{"es":"Quisiera hacer una reserva"},"answer":"Je voudrais faire une réservation"},{"prompt":"Breakfast is included","translations":{"es":"El desayuno está incluido"},"answer":"Le petit-déjeuner est compris"},{"prompt":"We''re going on a cruise","translations":{"es":"Nos vamos de crucero"},"answer":"Nous partons en croisière"},{"prompt":"How much does the trip cost?","translations":{"es":"¿Cuánto cuesta el viaje?"},"answer":"Combien coûte le voyage ?"},{"prompt":"I am ready","translations":{"es":"Estoy listo"},"answer":"Je suis prêt"},{"prompt":"A one-way ticket, please","translations":{"es":"Un billete de ida, por favor"},"answer":"Un aller simple, s''il vous plaît"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 32: À l'aéroport
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-32', 'À l''aéroport', '🛫', 'En el aeropuerto', 32, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''aéroport","translation":"the airport","translations":{"es":"el aeropuerto"}},{"id":"2","word":"la compagnie aérienne","translation":"the airline","translations":{"es":"la aerolínea"}},{"id":"3","word":"l''avion","translation":"the plane","translations":{"es":"el avión"}},{"id":"4","word":"le vol","translation":"the flight","translations":{"es":"el vuelo"}},{"id":"5","word":"les arrivées","translation":"arrivals","translations":{"es":"las llegadas"}},{"id":"6","word":"les départs","translation":"departures","translations":{"es":"las salidas"}},{"id":"7","word":"le tableau des vols","translation":"the flight board","translations":{"es":"el panel de vuelos"}},{"id":"8","word":"s''enregistrer","translation":"to check in","translations":{"es":"facturar / hacer el check-in"}},{"id":"9","word":"le comptoir d''enregistrement","translation":"the check-in desk","translations":{"es":"el mostrador de facturación"}},{"id":"10","word":"la carte d''embarquement","translation":"the boarding pass","translations":{"es":"la tarjeta de embarque"}},{"id":"11","word":"l''embarquement","translation":"boarding","translations":{"es":"el embarque"}},{"id":"12","word":"embarquer","translation":"to board","translations":{"es":"embarcar"}},{"id":"13","word":"la porte","translation":"the gate","translations":{"es":"la puerta"}},{"id":"14","word":"la salle d''attente","translation":"the waiting room","translations":{"es":"la sala de espera"}},{"id":"15","word":"l''escale","translation":"the stopover","translations":{"es":"la escala"}},{"id":"16","word":"la correspondance","translation":"the connection","translations":{"es":"la conexión"}},{"id":"17","word":"annulé / annulée","translation":"cancelled","translations":{"es":"cancelado / cancelada"}},{"id":"18","word":"en retard","translation":"delayed","translations":{"es":"con retraso"}},{"id":"19","word":"les bagages","translation":"luggage","translations":{"es":"el equipaje"}},{"id":"20","word":"le bagage à main","translation":"carry-on bag","translations":{"es":"el equipaje de mano"}},{"id":"21","word":"le tapis à bagages","translation":"the baggage carousel","translations":{"es":"la cinta de equipaje"}},{"id":"22","word":"le poids","translation":"the weight","translations":{"es":"el peso"}},{"id":"23","word":"le supplément","translation":"the extra charge","translations":{"es":"el suplemento"}},{"id":"24","word":"le passeport","translation":"the passport","translations":{"es":"el pasaporte"}},{"id":"25","word":"le visa","translation":"the visa","translations":{"es":"el visado / la visa"}},{"id":"26","word":"le passager / la passagère","translation":"the passenger","translations":{"es":"el pasajero / la pasajera"}},{"id":"27","word":"atterrir","translation":"to land","translations":{"es":"aterrizar"}},{"id":"28","word":"décoller","translation":"to take off","translations":{"es":"despegar"}},{"id":"29","word":"survoler","translation":"to fly over","translations":{"es":"sobrevolar"}},{"id":"30","word":"rater","translation":"to miss","translations":{"es":"perder (un transporte)"}},{"id":"31","word":"faire la queue","translation":"to queue","translations":{"es":"hacer cola"}},{"id":"32","word":"perdre","translation":"to lose","translations":{"es":"perder"}}],"grammar":[{"structure":"passé simple","example":"Le vol fut annulé. Ils arrivèrent à une heure du matin. Je fis la queue.","en":"Literary past (passé simple)","es":"Pasado literario (passé simple)"},{"structure":"passé composé","example":"Nous nous sommes enregistrés il y a une heure. J''ai montré mon passeport.","en":"Everyday past","es":"Pasado cotidiano"},{"structure":"imparfait (habitudes)","example":"Chaque fois qu''ils voyageaient, ils avaient des problèmes.","en":"Repeated past actions","es":"Acciones pasadas repetidas"},{"structure":"venir de + infinitif","example":"L''avion vient d''atterrir.","en":"Recent past","es":"Pasado reciente"},{"structure":"faire + infinitif","example":"Le douanier m''a fait ouvrir toutes les valises.","en":"Causative \"faire\"","es":"«Hacer» + infinitivo (causativo)"},{"structure":"pronom relatif « laquelle »","example":"Je ne trouvais pas la porte à laquelle je devais aller.","en":"Relative pronoun with preposition","es":"Pronombre relativo con preposición"},{"structure":"jusqu''à ce que + subjonctif","example":"Tout allait bien jusqu''à ce qu''ils arrivent à Rome.","en":"\"Until\" + subjunctive","es":"«Hasta que» + subjuntivo"},{"structure":"après avoir + participe","example":"Après avoir vu ma nationalité, il m''a laissé passer.","en":"\"After having\"","es":"«Después de haber»"}],"tips":[{"en":"The passé simple (il fut, ils arrivèrent, je fis) is the literary past: you will read it in novels, stories and newspapers, but in conversation people use the passé composé.","es":"El passé simple (il fut, ils arrivèrent, je fis) es el pasado literario: lo leerás en novelas, cuentos y periódicos, pero al hablar se usa el passé composé."},{"en":"Airport words: \"s''enregistrer\" (to check in), \"la carte d''embarquement\" (boarding pass), \"la porte\" (gate), \"le tapis à bagages\" (baggage carousel), \"l''escale\" (stopover).","es":"En el aeropuerto: «s''enregistrer» (facturar), «la carte d''embarquement» (tarjeta de embarque), «la porte» (puerta), «le tapis à bagages» (cinta de equipaje), «l''escale» (escala)."},{"en":"\"Rater / manquer son avion\" = to miss your plane.","es":"«Rater / manquer son avion» = perder el avión."},{"en":"\"Le vol\" = the flight, but also \"the theft\"!","es":"«Le vol» = el vuelo, ¡pero también el robo!"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Nous nous sommes enregistrés il y a une heure. L''avion vient d''atterrir.","translation":"We checked in an hour ago. The plane has just landed.","translations":{"es":"Facturamos hace una hora. El avión acaba de aterrizar."}},{"phrase":"On nous a appelés pour l''embarquement il y a quinze minutes.","translation":"They called us for boarding fifteen minutes ago.","translations":{"es":"Nos llamaron para embarcar hace quince minutos."}},{"phrase":"La limite de poids était de vingt kilos par passager.","translation":"The weight limit was twenty kilos per passenger.","translations":{"es":"El límite de peso era de veinte kilos por pasajero."}},{"phrase":"On m''a demandé dix euros par kilo supplémentaire.","translation":"They charged me ten euros per extra kilo.","translations":{"es":"Me cobraron diez euros por kilo de más."}},{"phrase":"Mes valises se perdirent. Le vol fut annulé.","translation":"My suitcases got lost. The flight was cancelled.","translations":{"es":"Mis maletas se perdieron. El vuelo fue cancelado."}},{"phrase":"Je fis la queue pendant deux heures.","translation":"I queued for two hours.","translations":{"es":"Hice cola durante dos horas."}},{"phrase":"Nous avons survolé Paris il y a quelques minutes.","translation":"We flew over Paris a few minutes ago.","translations":{"es":"Sobrevolamos París hace unos minutos."}},{"phrase":"Le douanier m''a fait ouvrir toutes les valises.","translation":"The customs officer made me open all the suitcases.","translations":{"es":"El aduanero me hizo abrir todas las maletas."}},{"phrase":"J''ai laissé ma carte d''embarquement sur le comptoir !","translation":"I left my boarding pass on the counter!","translations":{"es":"¡Me dejé la tarjeta de embarque en el mostrador!"}},{"phrase":"Je ne trouvais pas la porte à laquelle je devais aller.","translation":"I couldn''t find the gate I had to go to.","translations":{"es":"No encontraba la puerta a la que tenía que ir."}},{"phrase":"J''ai dû payer un supplément pour mon chien.","translation":"I had to pay an extra charge for my dog.","translations":{"es":"Tuve que pagar un suplemento por mi perro."}},{"phrase":"Où se trouve le tapis à bagages ? — Suivez les panneaux.","translation":"Where is the baggage carousel? — Follow the signs.","translations":{"es":"¿Dónde está la cinta de equipaje? — Siga los carteles."}},{"phrase":"À quelle heure arrivèrent-ils ? — Ils arrivèrent à une heure du matin, à cause d''une tempête.","translation":"What time did they arrive? — They arrived at one in the morning, because of a storm.","translations":{"es":"¿A qué hora llegaron? — Llegaron a la una de la madrugada por una tormenta."}},{"phrase":"Tu es là depuis longtemps ? — Non, nous venons de descendre de l''avion.","translation":"Have you been here long? — No, we just got off the plane.","translations":{"es":"¿Llevas mucho tiempo aquí? — No, acabamos de bajar del avión."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"\"Le vol fut annulé.\" Which tense is \"fut\"?","options":["futur","subjunctive","imparfait","passé simple"],"correct":3,"explanation":"Être in the passé simple: il fut. In speech: \"a été\".","translations":{"es":{"question":"«Le vol fut annulé.» ¿Qué tiempo es «fut»?","explanation":"Être en passé simple: il fut. Al hablar: «a été».","options":["futuro","subjuntivo","imperfecto","passé simple"]}}},{"id":"2","question":"What is the spoken equivalent of \"ils arrivèrent\"?","options":["ils arriveront","ils arrivent","ils arrivaient","ils sont arrivés"],"correct":3,"explanation":"Passé simple → passé composé in conversation.","translations":{"es":{"question":"¿Cuál es el equivalente oral de «ils arrivèrent»?","explanation":"Passé simple → passé composé en la conversación."}}},{"id":"3","question":"Where do you get your boarding pass?","options":["à la douane","dans la salle d''attente","au tapis à bagages","au comptoir d''enregistrement"],"correct":3,"explanation":"You check in at the check-in desk.","translations":{"es":{"question":"¿Dónde obtienes la tarjeta de embarque?","explanation":"Se factura en el mostrador de facturación."}}},{"id":"4","question":"\"L''avion vient d''atterrir.\" Meaning?","options":["The plane is coming to land.","The plane came from the land.","The plane will land.","The plane has just landed."],"correct":3,"explanation":"Venir de + infinitive = recent past.","translations":{"es":{"question":"«L''avion vient d''atterrir.» ¿Significado?","explanation":"Venir de + infinitivo = pasado reciente.","options":["El avión viene a aterrizar.","El avión vino de tierra.","El avión aterrizará.","El avión acaba de aterrizar."]}}},{"id":"5","question":"\"Il m''a fait ouvrir mes valises.\" Meaning?","options":["He opened my suitcases.","He made my suitcases.","He helped me open my suitcases.","He made me open my suitcases."],"correct":3,"explanation":"Faire + infinitive = to make someone do something.","translations":{"es":{"question":"«Il m''a fait ouvrir mes valises.» ¿Significado?","explanation":"Faire + infinitivo = hacer que alguien haga algo.","options":["Abrió mis maletas.","Hizo mis maletas.","Me ayudó a abrir las maletas.","Me hizo abrir las maletas."]}}},{"id":"6","question":"Complete: \"La porte à ___ je devais aller.\"","options":["que","lequel","qui","laquelle"],"correct":3,"explanation":"Porte is feminine: à laquelle.","translations":{"es":{"question":"Completa: «La porte à ___ je devais aller.»","explanation":"Porte es femenino: à laquelle."}}},{"id":"7","question":"\"Le vol\" can mean…","options":["the pilot","only the flight","the wing","the flight or the theft"],"correct":3,"explanation":"Voler = to fly / to steal.","translations":{"es":{"question":"«Le vol» puede significar…","explanation":"Voler = volar / robar.","options":["el piloto","solo el vuelo","el ala","el vuelo o el robo"]}}},{"id":"8","question":"Which sentence describes a repeated past action?","options":["Un jour, ils perdirent leurs valises.","Ils ont perdu leurs valises hier.","Ils perdront leurs valises.","Chaque fois qu''ils voyageaient, ils perdaient leurs valises."],"correct":3,"explanation":"Imparfait for habits.","translations":{"es":{"question":"¿Qué frase describe una acción pasada repetida?","explanation":"Imperfecto para los hábitos."}}}]}'::jsonb, 3),
  ('story', 'Les voyageurs malchanceux', '{"text":"Quand nous habitions à Lille, nous avions des voisins, Bernard et Sylvie, qui adoraient voyager. Mais chaque fois qu''ils partaient, ils avaient des problèmes. Parfois, ils perdaient leurs valises ; d''autres fois, ils rataient leur correspondance et devaient dormir à l''aéroport. Quand ils revenaient, ils nous racontaient leurs aventures en riant. Un été, ils décidèrent de partir en Grèce. Tout allait bien jusqu''à ce qu''ils arrivent à l''aéroport de Rome pour leur escale. Le tableau des vols annonçait un retard de six heures. Bernard fit la queue au comptoir pendant deux heures, mais l''employée lui dit que le vol était annulé. Sylvie, qui ne trouvait plus sa carte d''embarquement, chercha partout. Finalement, ils dormirent sur des chaises dans la salle d''attente. Le lendemain, un autre avion les emmena enfin à Athènes. Mais là-bas, au tapis à bagages, leurs valises n''arrivèrent jamais ! Depuis ce voyage, Bernard et Sylvie ne partent plus qu''en train… et toujours avec un seul petit sac.","translation":"When we lived in Lille, we had neighbors, Bernard and Sylvie, who loved to travel. But every time they went away, they had problems. Sometimes they lost their suitcases; other times they missed their connection and had to sleep at the airport. When they came back, they told us about their adventures, laughing. One summer, they decided to go to Greece. Everything was fine until they arrived at Rome airport for their stopover. The flight board showed a six-hour delay. Bernard queued at the counter for two hours, but the clerk told him the flight was cancelled. Sylvie, who could no longer find her boarding pass, looked everywhere. In the end, they slept on chairs in the waiting room. The next day, another plane finally took them to Athens. But there, at the baggage carousel, their suitcases never arrived! Since that trip, Bernard and Sylvie only travel by train… and always with just one small bag.","translations":{"es":"Cuando vivíamos en Lille, teníamos unos vecinos, Bernard y Sylvie, a los que les encantaba viajar. Pero cada vez que se iban, tenían problemas. A veces perdían las maletas; otras veces perdían la conexión y tenían que dormir en el aeropuerto. Cuando volvían, nos contaban sus aventuras riéndose. Un verano decidieron irse a Grecia. Todo iba bien hasta que llegaron al aeropuerto de Roma para hacer escala. El panel de vuelos anunciaba un retraso de seis horas. Bernard hizo cola en el mostrador durante dos horas, pero la empleada le dijo que el vuelo estaba cancelado. Sylvie, que ya no encontraba su tarjeta de embarque, buscó por todas partes. Al final durmieron en unas sillas de la sala de espera. Al día siguiente, otro avión los llevó por fin a Atenas. Pero allí, en la cinta de equipaje, ¡sus maletas no llegaron nunca! Desde aquel viaje, Bernard y Sylvie solo viajan en tren… y siempre con una sola bolsa pequeña."},"highlighted_words":["chaque fois qu''ils partaient","perdaient","rataient","décidèrent","jusqu''à ce qu''ils arrivent","escale","fit la queue","dit","carte d''embarquement","chercha","dormirent","emmena","tapis à bagages","n''arrivèrent jamais"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["L''avion","vient","d''atterrir"],"translation":"The plane has just landed","translations":{"es":"El avión acaba de aterrizar"}},{"words":["Le","vol","a","été","annulé"],"translation":"The flight was cancelled","translations":{"es":"El vuelo fue cancelado"}},{"words":["J''ai","perdu","ma","carte","d''embarquement"],"translation":"I lost my boarding pass","translations":{"es":"He perdido mi tarjeta de embarque"}},{"words":["Ils","arrivèrent","très","tard"],"translation":"They arrived very late","translations":{"es":"Llegaron muy tarde"}},{"words":["Il","m''a","fait","ouvrir","ma","valise"],"translation":"He made me open my suitcase","translations":{"es":"Me hizo abrir la maleta"}},{"words":["Nous","avons","raté","notre","correspondance"],"translation":"We missed our connection","translations":{"es":"Perdimos nuestra conexión"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Where is gate twelve?","translations":{"es":"¿Dónde está la puerta doce?"},"answer":"Où est la porte douze ?"},{"prompt":"My flight is delayed","translations":{"es":"Mi vuelo tiene retraso"},"answer":"Mon vol est en retard"},{"prompt":"I have to check my suitcase","translations":{"es":"Tengo que facturar mi maleta"},"answer":"Je dois enregistrer ma valise"},{"prompt":"Here is my passport","translations":{"es":"Aquí tiene mi pasaporte"},"answer":"Voici mon passeport"},{"prompt":"I missed my plane","translations":{"es":"He perdido el avión"},"answer":"J''ai raté mon avion"},{"prompt":"The flight was cancelled (literary)","translations":{"es":"El vuelo fue cancelado (literario)"},"answer":"Le vol fut annulé"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 33: Dans l'avion
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-33', 'Dans l''avion', '✈️', 'En el avión', 33, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''avion","translation":"the plane","translations":{"es":"el avión"}},{"id":"2","word":"l''hélicoptère","translation":"the helicopter","translations":{"es":"el helicóptero"}},{"id":"3","word":"le pilote","translation":"the pilot","translations":{"es":"el piloto"}},{"id":"4","word":"le commandant de bord","translation":"the captain","translations":{"es":"el comandante"}},{"id":"5","word":"l''équipage","translation":"the crew","translations":{"es":"la tripulación"}},{"id":"6","word":"l''hôtesse de l''air / le steward","translation":"the flight attendant","translations":{"es":"la azafata / el auxiliar de vuelo"}},{"id":"7","word":"la cabine","translation":"the cabin","translations":{"es":"la cabina"}},{"id":"8","word":"le compartiment à bagages","translation":"the overhead bin","translations":{"es":"el compartimento de equipaje"}},{"id":"9","word":"le siège","translation":"the seat","translations":{"es":"el asiento"}},{"id":"10","word":"le hublot","translation":"the window (plane)","translations":{"es":"la ventanilla"}},{"id":"11","word":"le couloir","translation":"the aisle","translations":{"es":"el pasillo"}},{"id":"12","word":"l''aile","translation":"the wing","translations":{"es":"el ala"}},{"id":"13","word":"le moteur","translation":"the engine","translations":{"es":"el motor"}},{"id":"14","word":"la tour de contrôle","translation":"the control tower","translations":{"es":"la torre de control"}},{"id":"15","word":"le train d''atterrissage","translation":"the landing gear","translations":{"es":"el tren de aterrizaje"}},{"id":"16","word":"l''atterrissage","translation":"landing","translations":{"es":"el aterrizaje"}},{"id":"17","word":"le décollage","translation":"takeoff","translations":{"es":"el despegue"}},{"id":"18","word":"la classe économique","translation":"economy class","translations":{"es":"la clase turista"}},{"id":"19","word":"la première classe","translation":"first class","translations":{"es":"la primera clase"}},{"id":"20","word":"le gilet de sauvetage","translation":"the life jacket","translations":{"es":"el chaleco salvavidas"}},{"id":"21","word":"la ceinture de sécurité","translation":"the seat belt","translations":{"es":"el cinturón de seguridad"}},{"id":"22","word":"le mal de l''air","translation":"airsickness","translations":{"es":"el mareo (en avión)"}},{"id":"23","word":"les turbulences","translation":"turbulence","translations":{"es":"las turbulencias"}},{"id":"24","word":"voler","translation":"to fly","translations":{"es":"volar"}},{"id":"25","word":"atterrir","translation":"to land","translations":{"es":"aterrizar"}},{"id":"26","word":"décoller","translation":"to take off","translations":{"es":"despegar"}},{"id":"27","word":"d''urgence","translation":"emergency","translations":{"es":"de emergencia"}},{"id":"28","word":"la couverture","translation":"the blanket","translations":{"es":"la manta"}},{"id":"29","word":"le bruit","translation":"the noise","translations":{"es":"el ruido"}},{"id":"30","word":"la nausée","translation":"nausea","translations":{"es":"las náuseas"}}],"grammar":[{"structure":"futur simple (réguliers)","example":"L''avion atterrira dans dix minutes. L''hélicoptère décollera à six heures.","en":"Simple future (regular verbs)","es":"Futuro simple (verbos regulares)"},{"structure":"futur simple (irréguliers)","example":"Nous aurons un atterrissage d''urgence. Je ferai n''importe quoi. Tu seras surpris.","en":"Irregular futures (avoir → aur-, être → ser-, faire → fer-)","es":"Futuros irregulares"},{"structure":"dès que + futur","example":"Nous atterrirons dès que la tour de contrôle nous le permettra.","en":"\"As soon as\" + future","es":"«En cuanto» + futuro"},{"structure":"si + présent → futur","example":"Je paierai les billets s''ils sont en classe économique.","en":"Real condition","es":"Condición real"},{"structure":"n''est-ce pas ?","example":"C''est un bon avion, n''est-ce pas ?","en":"Tag questions","es":"Pregunta de confirmación"},{"structure":"plutôt que","example":"Pourquoi voyagez-vous en classe économique plutôt qu''en première classe ?","en":"\"Rather than\"","es":"«En lugar de»"},{"structure":"passé composé / plus-que-parfait","example":"J''avais oublié que j''avais toujours le mal de l''air.","en":"Past perfect","es":"Pluscuamperfecto"}],"tips":[{"en":"The future stem is usually the infinitive (atterrir → j''atterrirai); -re verbs drop the -e (prendre → je prendrai). Irregular stems: aur-, ser-, fer-, ir-, pourr-, devr-, viendr-, verr-.","es":"La raíz del futuro suele ser el infinitivo (atterrir → j''atterrirai); los verbos en -re pierden la -e (prendre → je prendrai). Raíces irregulares: aur-, ser-, fer-, ir-, pourr-, devr-, viendr-, verr-."},{"en":"Unlike Spanish, French uses the future after \"quand\" and \"dès que\" when talking about the future: \"Quand j''arriverai, je t''appellerai.\"","es":"A diferencia del español, el francés usa el futuro después de «quand» y «dès que» al hablar del futuro: «Quand j''arriverai, je t''appellerai.»"},{"en":"\"Le mal de l''air\" = airsickness (\"le mal de mer\" = seasickness).","es":"«Le mal de l''air» = mareo en avión («le mal de mer» = mareo en barco)."},{"en":"Cabin announcements: \"Attachez vos ceintures\", \"Redressez votre siège\", \"Les toilettes sont occupées\".","es":"Avisos en cabina: «Attachez vos ceintures», «Redressez votre siège», «Les toilettes sont occupées»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Attachez vos ceintures de sécurité, s''il vous plaît.","translation":"Please fasten your seat belts.","translations":{"es":"Abróchense el cinturón de seguridad, por favor."}},{"phrase":"Je ne prendrai pas ce petit avion : j''aurai le mal de l''air.","translation":"I won''t take that small plane: I''ll get airsick.","translations":{"es":"No tomaré esa avioneta: me voy a marear."}},{"phrase":"Mets ton sac dans le compartiment.","translation":"Put your bag in the overhead bin.","translations":{"es":"Pon tu bolso en el compartimento."}},{"phrase":"L''avion atterrira dans dix minutes.","translation":"The plane will land in ten minutes.","translations":{"es":"El avión aterrizará dentro de diez minutos."}},{"phrase":"Le mécanicien vérifiera le moteur.","translation":"The mechanic will check the engine.","translations":{"es":"El mecánico revisará el motor."}},{"phrase":"L''armée de l''air offrira un spectacle dimanche prochain.","translation":"The air force will put on a show next Sunday.","translations":{"es":"La fuerza aérea ofrecerá una exhibición el domingo que viene."}},{"phrase":"Attention, nous aurons un atterrissage d''urgence. Restez assis.","translation":"Attention, we will have an emergency landing. Stay seated.","translations":{"es":"Atención, haremos un aterrizaje de emergencia. Permanezcan sentados."}},{"phrase":"Je paierai les billets s''ils sont en classe économique.","translation":"I''ll pay for the tickets if they''re in economy class.","translations":{"es":"Pagaré los billetes si son en clase turista."}},{"phrase":"Nous atterrirons dès que la tour de contrôle nous le permettra.","translation":"We will land as soon as the control tower allows us.","translations":{"es":"Aterrizaremos en cuanto la torre de control nos lo permita."}},{"phrase":"Mademoiselle, pourriez-vous m''apporter une couverture ?","translation":"Miss, could you bring me a blanket?","translations":{"es":"Señorita, ¿podría traerme una manta?"}},{"phrase":"Ne vous inquiétez pas, madame : deux hôtesses s''occuperont de vos enfants.","translation":"Don''t worry, madam: two flight attendants will take care of your children.","translations":{"es":"No se preocupe, señora: dos azafatas cuidarán de sus hijos."}},{"phrase":"Je vais acheter un petit avion. — Tu l''achèteras vraiment ? Pour quoi faire ?","translation":"I''m going to buy a small plane. — Will you really buy it? What for?","translations":{"es":"Voy a comprar una avioneta. — ¿De verdad la comprarás? ¿Para qué?"}},{"phrase":"Tu te sens bien ? — Non, j''avais oublié que j''avais toujours la nausée en avion.","translation":"Do you feel OK? — No, I had forgotten I always feel sick on planes.","translations":{"es":"¿Te encuentras bien? — No, había olvidado que siempre me mareo en avión."}},{"phrase":"Combien de temps durera le vol ? — Le pilote dit que nous arriverons dans dix heures.","translation":"How long will the flight last? — The pilot says we will arrive in ten hours.","translations":{"es":"¿Cuánto durará el vuelo? — El piloto dice que llegaremos dentro de diez horas."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"L''avion ___ dans dix minutes.\" (atterrir)","options":["atterrirait","atterrira","atterrit","atterrissait"],"correct":1,"explanation":"Future: infinitive + -a.","translations":{"es":{"question":"Completa: «L''avion ___ dans dix minutes.» (atterrir)","explanation":"Futuro: infinitivo + -a."}}},{"id":"2","question":"What is the future of \"avoir\" with \"nous\"?","options":["nous avrons","nous aurons","nous aurions","nous avons"],"correct":1,"explanation":"Irregular stem: aur-.","translations":{"es":{"question":"¿Cuál es el futuro de «avoir» con «nous»?","explanation":"Raíz irregular: aur-."}}},{"id":"3","question":"What is the future of \"faire\" with \"je\"?","options":["je ferai","je fairai","je ferais","je fais"],"correct":0,"explanation":"Irregular stem: fer-.","translations":{"es":{"question":"¿Cuál es el futuro de «faire» con «je»?","explanation":"Raíz irregular: fer-."}}},{"id":"4","question":"Complete: \"Je t''appellerai dès que j''___.\"","options":["arrive","arriverai","arriverais","arrivais"],"correct":1,"explanation":"French uses the future after \"dès que\" when the action is in the future.","translations":{"es":{"question":"Completa: «Je t''appellerai dès que j''___.»","explanation":"El francés usa futuro tras «dès que» cuando la acción es futura."}}},{"id":"5","question":"Complete: \"Si le vol est en retard, nous ___ l''hôtel.\"","options":["appellerions","appellerons","avons appelé","appelions"],"correct":1,"explanation":"Si + present → future.","translations":{"es":{"question":"Completa: «Si le vol est en retard, nous ___ l''hôtel.»","explanation":"Si + presente → futuro."}}},{"id":"6","question":"Where do you put your bag on a plane?","options":["sur l''aile","dans le train d''atterrissage","dans le compartiment à bagages","dans la tour de contrôle"],"correct":2,"explanation":"Le compartiment = overhead bin.","translations":{"es":{"question":"¿Dónde pones tu bolso en el avión?","explanation":"Le compartiment = compartimento superior."}}},{"id":"7","question":"What is \"le hublot\"?","options":["the engine","the aisle","the plane window","the wing"],"correct":2,"explanation":"Window seat = côté hublot; aisle seat = côté couloir.","translations":{"es":{"question":"¿Qué es «le hublot»?","explanation":"Asiento de ventanilla = côté hublot; de pasillo = côté couloir.","options":["el motor","el pasillo","la ventanilla del avión","el ala"]}}},{"id":"8","question":"\"Plutôt qu''en première classe\" means…","options":["more than first class","before first class","rather than in first class","only in first class"],"correct":2,"explanation":"\"Plutôt que\" = rather than.","translations":{"es":{"question":"«Plutôt qu''en première classe» significa…","explanation":"«Plutôt que» = en lugar de.","options":["más que la primera clase","antes de la primera clase","en lugar de en primera clase","solo en primera clase"]}}}]}'::jsonb, 3),
  ('story', 'Un voisin de siège', '{"text":"« Bienvenue à bord du vol 218 à destination de Montréal. Restez assis pendant que les passagers rangent leurs bagages. Nous décollerons dans cinq minutes. Attachez vos ceintures et redressez vos sièges. Nous vous souhaitons un agréable vol. » Clara est assise côté hublot, en classe économique. À côté d''elle, un homme âgé regarde l''aile avec un grand sourire. « Excusez-moi, monsieur, quelle heure est-il ? » « Il est midi pile. C''est un bel avion, n''est-ce pas ? » Clara le regarde mieux. « Je vous connais… Vous n''êtes pas le chef Paul Morin, de la télévision ? » « Si, c''est moi ! » « Mais pourquoi voyagez-vous en classe économique plutôt qu''en première classe ? » « J''aime être près de l''aile et entendre le moteur. Et puis ici, on rencontre des gens intéressants ! » Clara rit. « Moi, je ferai n''importe quoi pour devenir cheffe un jour. » « Alors, quand nous arriverons, je vous donnerai l''adresse de mon restaurant. Si vous venez me voir, je vous montrerai la cuisine. » « Vous le ferez vraiment ? » « Bien sûr ! L''argent n''est pas tout dans la vie. »","translation":"“Welcome aboard flight 218 to Montreal. Please remain seated while passengers stow their luggage. We will take off in five minutes. Fasten your seat belts and put your seats in the upright position. We wish you a pleasant flight.” Clara is sitting by the window, in economy class. Next to her, an elderly man is looking at the wing with a big smile. “Excuse me, sir, what time is it?” “It''s noon sharp. It''s a beautiful plane, isn''t it?” Clara takes a closer look at him. “I know you… Aren''t you chef Paul Morin, from TV?” “Yes, that''s me!” “But why are you flying economy rather than first class?” “I like being near the wing and hearing the engine. And besides, you meet interesting people here!” Clara laughs. “I''ll do anything to become a chef one day.” “Then when we arrive, I''ll give you the address of my restaurant. If you come and see me, I''ll show you the kitchen.” “Will you really do that?” “Of course! Money isn''t everything in life.”","translations":{"es":"«Bienvenidos a bordo del vuelo 218 con destino a Montreal. Permanezcan sentados mientras los pasajeros guardan su equipaje. Despegaremos dentro de cinco minutos. Abróchense los cinturones y pongan el respaldo en posición vertical. Les deseamos un feliz vuelo.» Clara está sentada junto a la ventanilla, en clase turista. A su lado, un señor mayor mira el ala con una gran sonrisa. «Disculpe, señor, ¿qué hora es?» «Son las doce en punto. Es un avión precioso, ¿verdad?» Clara lo mira mejor. «Lo conozco… ¿No es usted el chef Paul Morin, el de la televisión?» «¡Sí, soy yo!» «Pero ¿por qué viaja en clase turista en lugar de en primera?» «Me gusta estar cerca del ala y oír el motor. ¡Y además aquí se conoce a gente interesante!» Clara se ríe. «Yo haré lo que sea para ser chef algún día.» «Entonces, cuando lleguemos, le daré la dirección de mi restaurante. Si viene a verme, le enseñaré la cocina.» «¿De verdad lo hará?» «¡Por supuesto! El dinero no lo es todo en la vida.»"},"highlighted_words":["décollerons","Attachez vos ceintures","hublot","classe économique","n''est-ce pas","plutôt qu''en première classe","ferai","quand nous arriverons","donnerai","Si vous venez","montrerai","ferez"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["L''avion","atterrira","bientôt"],"translation":"The plane will land soon","translations":{"es":"El avión aterrizará pronto"}},{"words":["Attachez","vos","ceintures"],"translation":"Fasten your seat belts","translations":{"es":"Abróchense los cinturones"}},{"words":["Je","voyagerai","en","classe","économique"],"translation":"I will travel in economy class","translations":{"es":"Viajaré en clase turista"}},{"words":["Nous","partirons","dès","que","possible"],"translation":"We will leave as soon as possible","translations":{"es":"Saldremos lo antes posible"}},{"words":["C''est","un","bel","avion","n''est-ce","pas"],"translation":"It''s a beautiful plane isn''t it","translations":{"es":"Es un avión precioso, ¿verdad?"}},{"words":["Je","t''appellerai","quand","j''arriverai"],"translation":"I''ll call you when I arrive","translations":{"es":"Te llamaré cuando llegue"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"The plane will take off at noon","translations":{"es":"El avión despegará a mediodía"},"answer":"L''avion décollera à midi"},{"prompt":"The restroom is occupied","translations":{"es":"El baño está ocupado"},"answer":"Les toilettes sont occupées"},{"prompt":"Could you bring me some water?","translations":{"es":"¿Podría traerme agua?"},"answer":"Pourriez-vous m''apporter de l''eau ?"},{"prompt":"I''m airsick","translations":{"es":"Estoy mareado"},"answer":"J''ai le mal de l''air"},{"prompt":"We will arrive in two hours","translations":{"es":"Llegaremos dentro de dos horas"},"answer":"Nous arriverons dans deux heures"},{"prompt":"I will do my best","translations":{"es":"Haré todo lo posible"},"answer":"Je ferai de mon mieux"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 34: L'immigration et la douane
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-34', 'L''immigration et la douane', '🛂', 'Inmigración y aduana', 34, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''immigration","translation":"immigration","translations":{"es":"la inmigración"}},{"id":"2","word":"la douane","translation":"customs","translations":{"es":"la aduana"}},{"id":"3","word":"le douanier / la douanière","translation":"customs officer","translations":{"es":"el aduanero / la aduanera"}},{"id":"4","word":"l''agent d''immigration","translation":"the immigration officer","translations":{"es":"el agente de inmigración"}},{"id":"5","word":"le contrôle des passeports","translation":"passport control","translations":{"es":"el control de pasaportes"}},{"id":"6","word":"le citoyen / la citoyenne","translation":"the citizen","translations":{"es":"el ciudadano / la ciudadana"}},{"id":"7","word":"la nationalité","translation":"nationality","translations":{"es":"la nacionalidad"}},{"id":"8","word":"l''étranger / l''étrangère","translation":"the foreigner","translations":{"es":"el extranjero / la extranjera"}},{"id":"9","word":"le passeport","translation":"the passport","translations":{"es":"el pasaporte"}},{"id":"10","word":"le visa","translation":"the visa","translations":{"es":"el visado / la visa"}},{"id":"11","word":"l''ambassade","translation":"the embassy","translations":{"es":"la embajada"}},{"id":"12","word":"le consulat","translation":"the consulate","translations":{"es":"el consulado"}},{"id":"13","word":"le titre de séjour","translation":"the residence permit","translations":{"es":"el permiso de residencia"}},{"id":"14","word":"les papiers","translation":"documents / ID","translations":{"es":"los papeles / la documentación"}},{"id":"15","word":"le document","translation":"the document","translations":{"es":"el documento"}},{"id":"16","word":"déclarer","translation":"to declare","translations":{"es":"declarar"}},{"id":"17","word":"rien à déclarer","translation":"nothing to declare","translations":{"es":"nada que declarar"}},{"id":"18","word":"cacher","translation":"to hide","translations":{"es":"esconder"}},{"id":"19","word":"vérifier","translation":"to check","translations":{"es":"verificar"}},{"id":"20","word":"fouiller","translation":"to search","translations":{"es":"registrar"}},{"id":"21","word":"le motif du voyage","translation":"the reason for travel","translations":{"es":"el motivo del viaje"}},{"id":"22","word":"le tourisme","translation":"tourism","translations":{"es":"el turismo"}},{"id":"23","word":"les études","translation":"studies","translations":{"es":"los estudios"}},{"id":"24","word":"les affaires","translation":"business / belongings","translations":{"es":"los negocios / las pertenencias"}},{"id":"25","word":"l''alcool","translation":"alcohol","translations":{"es":"el alcohol"}},{"id":"26","word":"l''appareil photo","translation":"the camera","translations":{"es":"la cámara de fotos"}},{"id":"27","word":"le séjour","translation":"the stay","translations":{"es":"la estancia"}},{"id":"28","word":"le jour férié","translation":"public holiday","translations":{"es":"el día festivo"}},{"id":"29","word":"autoriser","translation":"to allow","translations":{"es":"autorizar"}},{"id":"30","word":"interdit / interdite","translation":"forbidden","translations":{"es":"prohibido / prohibida"}},{"id":"31","word":"la file d''attente","translation":"the queue","translations":{"es":"la cola"}}],"grammar":[{"structure":"être en train de (présent)","example":"Je suis en train de faire la queue. / Elle est en train de vérifier les papiers.","en":"Action in progress (present)","es":"Acción en curso (presente)"},{"structure":"être en train de (imparfait)","example":"J''étais en train de chercher mon passeport quand on m''a appelé.","en":"Action in progress (past)","es":"Acción en curso (pasado)"},{"structure":"futur proche","example":"Ils vont aller en France après avoir réglé leurs affaires.","en":"Near future","es":"Futuro próximo"},{"structure":"après avoir + participe","example":"après avoir réglé quelques affaires","en":"\"After having done\"","es":"«Después de haber»"},{"structure":"discours indirect (si)","example":"L''agent m''a demandé si j''avais quelque chose à déclarer.","en":"Reported yes/no question","es":"Pregunta indirecta de sí/no"},{"structure":"pronoms « le » et « y »","example":"Êtes-vous citoyen français ? — Non, je ne le suis pas. / J''irai en prison ? — Non, tu n''y vas pas.","en":"\"le\" (attribute) and \"y\" (place)","es":"«le» (atributo) y «y» (lugar)"},{"structure":"il est possible que + subjonctif","example":"Il est possible qu''on l''envoie ici.","en":"Possibility + subjunctive","es":"Posibilidad + subjuntivo"},{"structure":"ne … quoi que ce soit","example":"Je ne cache quoi que ce soit.","en":"\"Anything at all\"","es":"«Nada en absoluto»"}],"tips":[{"en":"At customs: \"Avez-vous quelque chose à déclarer ?\" — \"Rien à déclarer.\" In airports, follow the green channel (nothing to declare) or the red channel (goods to declare).","es":"En la aduana: «Avez-vous quelque chose à déclarer ?» — «Rien à déclarer.» En los aeropuertos, sigue el canal verde (nada que declarar) o el rojo (mercancías que declarar)."},{"en":"\"Le titre de séjour / le permis de séjour\" = residence permit; \"le permis d''études\" = study permit (Canada).","es":"«Le titre de séjour / le permis de séjour» = permiso de residencia; «le permis d''études» = permiso de estudios (Canadá)."},{"en":"\"Être en train de\" stresses that something is happening right now; it''s very common in spoken French.","es":"«Être en train de» insiste en que algo está ocurriendo ahora mismo; es muy frecuente en el francés hablado."},{"en":"\"Vous vous moquez de moi ?\" = Are you kidding me? (formal, annoyed).","es":"«Vous vous moquez de moi ?» = ¿Se está burlando de mí? (formal, molesto)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Je suis en train de faire la queue au contrôle des passeports.","translation":"I''m queuing at passport control.","translations":{"es":"Estoy haciendo cola en el control de pasaportes."}},{"phrase":"Elle est en train de parler avec le douanier.","translation":"She is talking to the customs officer.","translations":{"es":"Está hablando con el aduanero."}},{"phrase":"Ils viennent étudier pendant un an.","translation":"They are coming to study for a year.","translations":{"es":"Vienen a estudiar durante un año."}},{"phrase":"L''agent m''a demandé si j''avais quelque chose à déclarer.","translation":"The officer asked me if I had anything to declare.","translations":{"es":"El agente me preguntó si tenía algo que declarar."}},{"phrase":"Je suis citoyen français. — Elle est étudiante étrangère.","translation":"I am a French citizen. — She is a foreign student.","translations":{"es":"Soy ciudadano francés. — Ella es estudiante extranjera."}},{"phrase":"Le motif de mon voyage, ce sont des affaires familiales.","translation":"The reason for my trip is family matters.","translations":{"es":"El motivo de mi viaje son asuntos familiares."}},{"phrase":"Montrez-moi vos papiers, s''il vous plaît.","translation":"Show me your documents, please.","translations":{"es":"Muéstreme su documentación, por favor."}},{"phrase":"Ouvrez le coffre, s''il vous plaît.","translation":"Open the trunk, please.","translations":{"es":"Abra el maletero, por favor."}},{"phrase":"Ils vont aller en France après avoir réglé quelques affaires au Canada.","translation":"They are going to go to France after sorting out a few things in Canada.","translations":{"es":"Van a ir a Francia después de haber resuelto algunos asuntos en Canadá."}},{"phrase":"Êtes-vous citoyen européen ? — Non, je ne le suis pas.","translation":"Are you an EU citizen? — No, I''m not.","translations":{"es":"¿Es usted ciudadano europeo? — No, no lo soy."}},{"phrase":"Pourquoi a-t-elle tant de valises ? — Elle est en train de déménager !","translation":"Why does she have so many suitcases? — She is moving house!","translations":{"es":"¿Por qué lleva tantas maletas? — ¡Se está mudando!"}},{"phrase":"Tu caches quelque chose dans le coffre ? — Non, je ne cache quoi que ce soit !","translation":"Are you hiding something in the trunk? — No, I''m not hiding anything at all!","translations":{"es":"¿Escondes algo en el maletero? — ¡No, no escondo nada en absoluto!"}},{"phrase":"Pourquoi va-t-il en France ? — Pour finir ses études.","translation":"Why is he going to France? — To finish his studies.","translations":{"es":"¿Por qué va a Francia? — Para terminar sus estudios."}},{"phrase":"Profitez bien de votre séjour !","translation":"Enjoy your stay!","translations":{"es":"¡Disfrute de su estancia!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Je suis en train ___ chercher mon passeport.\"","options":["à","de","pour","en"],"correct":1,"explanation":"Être en train DE + infinitive.","translations":{"es":{"question":"Completa: «Je suis en train ___ chercher mon passeport.»","explanation":"Être en train DE + infinitivo."}}},{"id":"2","question":"Complete: \"J''___ en train de dormir quand tu as appelé.\"","options":["ai été","étais","suis","serai"],"correct":1,"explanation":"Imparfait for the ongoing action in the past.","translations":{"es":{"question":"Completa: «J''___ en train de dormir quand tu as appelé.»","explanation":"Imperfecto para la acción en curso en el pasado."}}},{"id":"3","question":"Reported question: \"Avez-vous quelque chose à déclarer ?\" → Il m''a demandé…","options":["si j''avais quelque chose à déclarer","que j''avais quelque chose à déclarer","est-ce que j''ai quelque chose à déclarer","si j''ai eu quelque chose à déclarer"],"correct":0,"explanation":"Si + imparfait after a past reporting verb.","translations":{"es":{"question":"Pregunta indirecta: «Avez-vous quelque chose à déclarer ?» → Il m''a demandé…","explanation":"Si + imperfecto tras un verbo introductor en pasado."}}},{"id":"4","question":"\"Êtes-vous français ?\" — \"Non, je ne ___ suis pas.\"","options":["y","la","le","en"],"correct":2,"explanation":"\"Le\" replaces the adjective \"français\".","translations":{"es":{"question":"«Êtes-vous français ?» — «Non, je ne ___ suis pas.»","explanation":"«Le» sustituye al adjetivo «français»."}}},{"id":"5","question":"Complete: \"Il est possible qu''on l''___ ici.\"","options":["envoie-t-il","enverra","envoie","envoyait"],"correct":2,"explanation":"\"Il est possible que\" + subjunctive.","translations":{"es":{"question":"Completa: «Il est possible qu''on l''___ ici.»","explanation":"«Il est possible que» + subjuntivo."}}},{"id":"6","question":"What do you say if you have nothing to declare?","options":["Pas de passeport.","Je déclare tout.","Rien à déclarer.","Je suis en train."],"correct":2,"explanation":"Take the green channel.","translations":{"es":{"question":"¿Qué dices si no tienes nada que declarar?","explanation":"Ve por el canal verde."}}},{"id":"7","question":"Where do you apply for a visa?","options":["à l''hôtel","à la douane","à l''ambassade ou au consulat","au comptoir d''enregistrement"],"correct":2,"explanation":"Embassy or consulate.","translations":{"es":{"question":"¿Dónde solicitas un visado?","explanation":"Embajada o consulado."}}},{"id":"8","question":"\"Le motif de votre voyage ?\" — Which answer fits?","options":["La douane.","Le tourisme.","Le passeport.","Le coffre."],"correct":1,"explanation":"Motif = reason.","translations":{"es":{"question":"«Le motif de votre voyage ?» — ¿Qué respuesta encaja?","explanation":"Motif = motivo."}}}]}'::jsonb, 3),
  ('story', 'Arrivée à Montréal', '{"text":"En ce moment, Sofia est en train de parler avec une agente d''immigration à l''aéroport de Montréal. Elle vient du Chili pour étudier un an à l''université. L''agente lui demande ses papiers ; Sofia les sort de son sac. « Votre lettre d''acceptation n''est pas là », dit l''agente. « Je vous jure que je l''avais ! Je l''ai imprimée il y a une semaine… » Sofia était en train de chercher dans toutes ses poches quand elle s''est souvenue : la lettre est aussi dans ses courriels ! Elle la montre sur son téléphone. « Parfait. Il est possible qu''on vous demande l''original plus tard. Bienvenue au Canada et profitez de votre séjour ! » Ensuite, Sofia va à la douane. Un douanier lui demande si elle a quelque chose à déclarer. « Non, rien. » « Pouvez-vous ouvrir cette valise ? » Il trouve un gros fromage et deux saucissons. « C''est un cadeau pour ma famille d''accueil », explique Sofia. « Vous devez déclarer toute la nourriture, mademoiselle. » « Je ne savais pas, je suis désolée ! » Heureusement, le douanier sourit : « Cette fois, ça va. Mais la prochaine fois, lisez bien le formulaire ! »","translation":"Right now, Sofia is talking to an immigration officer at Montreal airport. She has come from Chile to study at the university for a year. The officer asks for her documents; Sofia takes them out of her bag. “Your acceptance letter isn''t here,” says the officer. “I swear I had it! I printed it a week ago…” Sofia was searching all her pockets when she remembered: the letter is also in her emails! She shows it on her phone. “Perfect. You may be asked for the original later. Welcome to Canada and enjoy your stay!” Then Sofia goes to customs. A customs officer asks her if she has anything to declare. “No, nothing.” “Can you open this suitcase?” He finds a big cheese and two dry sausages. “It''s a gift for my host family,” Sofia explains. “You must declare all food, miss.” “I didn''t know, I''m sorry!” Fortunately, the officer smiles: “This time it''s OK. But next time, read the form carefully!”","translations":{"es":"En este momento, Sofía está hablando con una agente de inmigración en el aeropuerto de Montreal. Viene de Chile para estudiar un año en la universidad. La agente le pide la documentación; Sofía la saca del bolso. «Su carta de admisión no está aquí», dice la agente. «¡Le juro que la tenía! La imprimí hace una semana…» Sofía estaba buscando en todos sus bolsillos cuando se acordó: ¡la carta también está en su correo electrónico! La enseña en el teléfono. «Perfecto. Es posible que más adelante le pidan el original. ¡Bienvenida a Canadá y disfrute de su estancia!» Después, Sofía va a la aduana. Un aduanero le pregunta si tiene algo que declarar. «No, nada.» «¿Puede abrir esta maleta?» Encuentra un queso grande y dos salchichones. «Es un regalo para mi familia de acogida», explica Sofía. «Tiene que declarar toda la comida, señorita.» «¡No lo sabía, lo siento!» Por suerte, el aduanero sonríe: «Esta vez pase. Pero la próxima vez, lea bien el formulario.»"},"highlighted_words":["est en train de parler","agente d''immigration","ses papiers","il y a une semaine","était en train de chercher","Il est possible qu''on vous demande","séjour","douane","si elle a quelque chose à déclarer","déclarer"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","suis","en","train","de","faire","la","queue"],"translation":"I''m standing in line","translations":{"es":"Estoy haciendo cola"}},{"words":["Avez-vous","quelque","chose","à","déclarer"],"translation":"Do you have anything to declare","translations":{"es":"¿Tiene algo que declarar?"}},{"words":["Montrez-moi","votre","passeport"],"translation":"Show me your passport","translations":{"es":"Muéstreme su pasaporte"}},{"words":["Il","m''a","demandé","si","j''étais","étudiant"],"translation":"He asked me if I was a student","translations":{"es":"Me preguntó si era estudiante"}},{"words":["Non","je","ne","le","suis","pas"],"translation":"No I''m not","translations":{"es":"No, no lo soy"}},{"words":["Profitez","de","votre","séjour"],"translation":"Enjoy your stay","translations":{"es":"Disfrute de su estancia"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Nothing to declare","translations":{"es":"Nada que declarar"},"answer":"Rien à déclarer"},{"prompt":"I am here for tourism","translations":{"es":"Vengo por turismo"},"answer":"Je viens pour le tourisme"},{"prompt":"Here are my documents","translations":{"es":"Aquí tiene mi documentación"},"answer":"Voici mes papiers"},{"prompt":"Open the suitcase, please","translations":{"es":"Abra la maleta, por favor"},"answer":"Ouvrez la valise, s''il vous plaît"},{"prompt":"She is checking the passports","translations":{"es":"Está revisando los pasaportes"},"answer":"Elle est en train de vérifier les passeports"},{"prompt":"I lost my visa","translations":{"es":"He perdido mi visado"},"answer":"J''ai perdu mon visa"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 35: À l'hôtel
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-35', 'À l''hôtel', '🏨', 'En el hotel', 35, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''hôtel","translation":"the hotel","translations":{"es":"el hotel"}},{"id":"2","word":"la réception","translation":"the front desk","translations":{"es":"la recepción"}},{"id":"3","word":"le / la réceptionniste","translation":"the receptionist","translations":{"es":"el / la recepcionista"}},{"id":"4","word":"le hall","translation":"the lobby","translations":{"es":"el vestíbulo"}},{"id":"5","word":"le groom / le bagagiste","translation":"the bellboy","translations":{"es":"el botones"}},{"id":"6","word":"le concierge","translation":"the concierge","translations":{"es":"el conserje"}},{"id":"7","word":"la chambre","translation":"the room","translations":{"es":"la habitación"}},{"id":"8","word":"la chambre simple / double","translation":"single / double room","translations":{"es":"la habitación individual / doble"}},{"id":"9","word":"la clé","translation":"the key","translations":{"es":"la llave"}},{"id":"10","word":"l''ascenseur","translation":"the elevator","translations":{"es":"el ascensor"}},{"id":"11","word":"l''étage","translation":"the floor","translations":{"es":"el piso"}},{"id":"12","word":"la sortie de secours","translation":"the emergency exit","translations":{"es":"la salida de emergencia"}},{"id":"13","word":"la vue","translation":"the view","translations":{"es":"la vista"}},{"id":"14","word":"la piscine","translation":"the pool","translations":{"es":"la piscina"}},{"id":"15","word":"la balançoire","translation":"the swing","translations":{"es":"el columpio"}},{"id":"16","word":"la note","translation":"the bill (hotel)","translations":{"es":"la cuenta"}},{"id":"17","word":"s''enregistrer","translation":"to check in","translations":{"es":"registrarse"}},{"id":"18","word":"régler","translation":"to pay (a bill)","translations":{"es":"pagar"}},{"id":"19","word":"les espèces","translation":"cash","translations":{"es":"el efectivo"}},{"id":"20","word":"la carte bancaire","translation":"the bank card","translations":{"es":"la tarjeta bancaria"}},{"id":"21","word":"la monnaie","translation":"change (coins)","translations":{"es":"el cambio / las monedas"}},{"id":"22","word":"réserver","translation":"to book","translations":{"es":"reservar"}},{"id":"23","word":"épeler","translation":"to spell","translations":{"es":"deletrear"}},{"id":"24","word":"accrocher","translation":"to hang","translations":{"es":"colgar"}},{"id":"25","word":"se raser","translation":"to shave","translations":{"es":"afeitarse"}},{"id":"26","word":"nager","translation":"to swim","translations":{"es":"nadar"}},{"id":"27","word":"plonger","translation":"to dive","translations":{"es":"bucear / zambullirse"}},{"id":"28","word":"rêver","translation":"to dream","translations":{"es":"soñar"}},{"id":"29","word":"le cauchemar","translation":"the nightmare","translations":{"es":"la pesadilla"}},{"id":"30","word":"sourire","translation":"to smile","translations":{"es":"sonreír"}},{"id":"31","word":"regretter","translation":"to regret","translations":{"es":"lamentar"}},{"id":"32","word":"cependant / néanmoins","translation":"however / nevertheless","translations":{"es":"sin embargo / no obstante"}},{"id":"33","word":"sans souci","translation":"without worry","translations":{"es":"sin preocupaciones"}},{"id":"34","word":"l''alarme incendie","translation":"the fire alarm","translations":{"es":"la alarma de incendios"}}],"grammar":[{"structure":"imparfait (description)","example":"J''étais dans une grande chambre. Elle me souriait. Il pleuvait.","en":"Imperfect for descriptions","es":"Imperfecto para descripciones"},{"structure":"être en train de à l''imparfait + passé composé","example":"J''étais en train de dormir quand tu m''as appelé.","en":"Interrupted action","es":"Acción interrumpida"},{"structure":"passé simple (récit)","example":"Le taxi s''arrêta devant l''entrée. Nous partîmes le lendemain.","en":"Literary past in a narrative","es":"Pasado literario en el relato"},{"structure":"pendant que / lorsque","example":"Il a monté les valises pendant que je payais le taxi.","en":"Simultaneous actions","es":"Acciones simultáneas"},{"structure":"être sur le point de","example":"Elle était sur le point de plonger quand elle a vu une méduse.","en":"\"About to\"","es":"«A punto de»"},{"structure":"se demander","example":"Je me demandais où tu étais.","en":"\"To wonder\"","es":"«Preguntarse»"},{"structure":"gérondif","example":"Il est tombé en essayant de rattraper son chapeau.","en":"Gerund","es":"Gerundio"},{"structure":"content de + infinitif passé","example":"Je suis content d''avoir changé de chambre.","en":"Glad to have done","es":"«Contento de haber»"},{"structure":"ne … personne d''autre que","example":"Il n''y avait personne d''autre que nous.","en":"\"Nobody but\"","es":"«Nadie más que»"}],"tips":[{"en":"The passé simple (il fut, ils arrivèrent, je fis) is the literary past: you will read it in novels, stories and newspapers, but in conversation people use the passé composé.","es":"El passé simple (il fut, ils arrivèrent, je fis) es el pasado literario: lo leerás en novelas, cuentos y periódicos, pero al hablar se usa el passé composé."},{"en":"Hotel phrases: \"J''ai une réservation au nom de…\", \"Une chambre avec vue sur la mer\", \"À quelle heure est le petit-déjeuner ?\", \"Je voudrais régler la note\" (to pay the bill).","es":"En el hotel: «J''ai une réservation au nom de…», «Une chambre avec vue sur la mer», «À quelle heure est le petit-déjeuner ?», «Je voudrais régler la note» (pagar la cuenta)."},{"en":"\"Le hall / la réception\" = lobby / front desk; \"le bagagiste / le groom\" = bellboy; \"le concierge\" = concierge.","es":"«Le hall / la réception» = vestíbulo / recepción; «le bagagiste / le groom» = botones; «le concierge» = conserje."},{"en":"Imparfait = what was going on (background); passé composé / passé simple = what happened (events).","es":"Imperfecto = lo que estaba pasando (fondo); passé composé / passé simple = lo que ocurrió (hechos)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Il y avait des enfants qui jouaient dans le hall.","translation":"There were children playing in the lobby.","translations":{"es":"Había niños jugando en el vestíbulo."}},{"phrase":"Nous sommes en train d''attendre le groom.","translation":"We are waiting for the bellboy.","translations":{"es":"Estamos esperando al botones."}},{"phrase":"Ils étaient en train de s''enregistrer quand nous sommes arrivés.","translation":"They were checking in when we arrived.","translations":{"es":"Se estaban registrando cuando llegamos."}},{"phrase":"J''étais en train de dormir quand tu m''as appelé.","translation":"I was sleeping when you called me.","translations":{"es":"Estaba durmiendo cuando me llamaste."}},{"phrase":"Elle ferma la fenêtre parce qu''il pleuvait.","translation":"She closed the window because it was raining.","translations":{"es":"Cerró la ventana porque llovía."}},{"phrase":"Je me demandais où tu étais.","translation":"I was wondering where you were.","translations":{"es":"Me preguntaba dónde estabas."}},{"phrase":"La vue de l''autre chambre était horrible. Je suis content d''avoir changé.","translation":"The view from the other room was horrible. I''m glad I changed.","translations":{"es":"La vista desde la otra habitación era horrible. Me alegro de haber cambiado."}},{"phrase":"Elle a réservé des places pour l''opéra pendant que tu prenais ta douche.","translation":"She booked tickets for the opera while you were taking a shower.","translations":{"es":"Reservó entradas para la ópera mientras te duchabas."}},{"phrase":"Elle était sur le point de plonger quand elle a vu une méduse.","translation":"She was about to dive when she saw a jellyfish.","translations":{"es":"Estaba a punto de tirarse al agua cuando vio una medusa."}},{"phrase":"J''étais en train de rêver de ma mère quand tu m''as réveillée.","translation":"I was dreaming about my mother when you woke me up.","translations":{"es":"Estaba soñando con mi madre cuando me despertaste."}},{"phrase":"Cet ascenseur est très lent !","translation":"This elevator is very slow!","translations":{"es":"¡Este ascensor es muy lento!"}},{"phrase":"Il dormait dans sa chambre ? — Non, il était en train de dormir au bord de la piscine.","translation":"Was he sleeping in his room? — No, he was sleeping by the pool.","translations":{"es":"¿Dormía en su habitación? — No, estaba durmiendo junto a la piscina."}},{"phrase":"Y a-t-il une autre chambre libre ? — Oui, il en reste deux au deuxième étage.","translation":"Is there another room available? — Yes, there are two left on the second floor.","translations":{"es":"¿Hay otra habitación libre? — Sí, quedan dos en el segundo piso."}},{"phrase":"J''ai une réservation au nom de Durand. Je vous épelle : D-U-R-A-N-D.","translation":"I have a reservation under the name Durand. Let me spell it: D-U-R-A-N-D.","translations":{"es":"Tengo una reserva a nombre de Durand. Se lo deletreo: D-U-R-A-N-D."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"J''___ en train de lire quand le téléphone a sonné.\"","options":["serai","étais","suis","ai été"],"correct":1,"explanation":"Imparfait for the interrupted action.","translations":{"es":{"question":"Completa: «J''___ en train de lire quand le téléphone a sonné.»","explanation":"Imperfecto para la acción interrumpida."}}},{"id":"2","question":"Which verb describes the background?","options":["Nous partîmes le lendemain.","Le taxi s''arrêta.","Il pleuvait quand nous sommes arrivés.","Nous sommes arrivés à l''hôtel."],"correct":2,"explanation":"Imparfait = background.","translations":{"es":{"question":"¿Qué verbo describe el fondo?","explanation":"Imperfecto = fondo."}}},{"id":"3","question":"\"Nous partîmes le lendemain.\" Spoken equivalent?","options":["Nous partirons le lendemain.","Nous partons le lendemain.","Nous sommes partis le lendemain.","Nous partions le lendemain."],"correct":2,"explanation":"Passé simple → passé composé.","translations":{"es":{"question":"«Nous partîmes le lendemain.» ¿Equivalente oral?","explanation":"Passé simple → passé composé."}}},{"id":"4","question":"Complete: \"Je suis content d''___ changé de chambre.\"","options":["ai","avais","avoir","être"],"correct":2,"explanation":"Past infinitive: avoir + past participle.","translations":{"es":{"question":"Completa: «Je suis content d''___ changé de chambre.»","explanation":"Infinitivo compuesto: avoir + participio."}}},{"id":"5","question":"Complete: \"Il a monté les valises ___ je payais le taxi.\"","options":["avant","depuis que","pendant que","pendant"],"correct":2,"explanation":"\"Pendant que\" + clause; \"pendant\" + noun.","translations":{"es":{"question":"Completa: «Il a monté les valises ___ je payais le taxi.»","explanation":"«Pendant que» + oración; «pendant» + sustantivo."}}},{"id":"6","question":"Who carries your luggage at a hotel?","options":["le bagagiste","le concierge","le douanier","le réceptionniste"],"correct":0,"explanation":"Also called \"le groom\".","translations":{"es":{"question":"¿Quién lleva tu equipaje en un hotel?","explanation":"También se llama «le groom»."}}},{"id":"7","question":"How do you say \"to pay the bill\" at a hotel?","options":["régler la note","faire la facture","donner le billet","payer la notice"],"correct":0,"explanation":"La note = the hotel bill.","translations":{"es":{"question":"¿Cómo se dice «pagar la cuenta» en un hotel?","explanation":"La note = la cuenta del hotel."}}},{"id":"8","question":"\"Il n''y avait personne d''autre que nous.\" Meaning?","options":["Nobody saw us.","There was nobody but us.","We were not there.","There were other people with us."],"correct":1,"explanation":"\"Ne … personne d''autre que\" = nobody except.","translations":{"es":{"question":"«Il n''y avait personne d''autre que nous.» ¿Significado?","explanation":"«Ne … personne d''autre que» = nadie más que.","options":["Nadie nos vio.","No había nadie más que nosotros.","No estábamos allí.","Había otras personas con nosotros."]}}}]}'::jsonb, 3),
  ('story', 'Une nuit agitée', '{"text":"Il pleuvait encore quand nous sommes arrivés à l''hôtel, à Marseille. Le taxi s''arrêta devant l''entrée, et le bagagiste nous ouvrit la portière. Il a monté nos valises pendant que je payais le chauffeur. À la réception, Karine a épelé notre nom et a demandé une chambre avec vue sur la mer. Le réceptionniste nous a donné la clé de la chambre 512, au cinquième étage. Quand j''ai ouvert les rideaux, la vue sur le port était magnifique. Le soir, le ciel se dégagea et nous regardâmes les étoiles depuis le balcon. Vers trois heures du matin, nous étions en train de dormir profondément quand l''alarme incendie a sonné. Nous étions sur le point de prendre l''ascenseur quand Karine a crié : « Non, l''escalier ! » En moins de deux minutes, nous étions dans le hall… en pyjama. Cependant, il n''y avait personne d''autre que nous ! Le réceptionniste, très calme, nous a expliqué que c''était une erreur du système et que cela arrivait de temps en temps. Je me demandais pourquoi les autres clients n''étaient pas descendus. Nous rîmes beaucoup, et nous partîmes le lendemain avec une belle histoire à raconter.","translation":"It was still raining when we arrived at the hotel in Marseille. The taxi stopped in front of the entrance, and the bellboy opened the door for us. He carried our suitcases up while I paid the driver. At the front desk, Karine spelled our name and asked for a room with a sea view. The receptionist gave us the key to room 512, on the fifth floor. When I opened the curtains, the view over the harbor was magnificent. In the evening, the sky cleared and we watched the stars from the balcony. Around three in the morning, we were fast asleep when the fire alarm went off. We were about to take the elevator when Karine shouted: “No, the stairs!” In less than two minutes, we were in the lobby… in our pajamas. However, there was nobody but us! The receptionist, very calm, explained that it was a system error and that it happened from time to time. I wondered why the other guests hadn''t come down. We laughed a lot, and we left the next day with a great story to tell.","translations":{"es":"Todavía llovía cuando llegamos al hotel, en Marsella. El taxi se detuvo delante de la entrada y el botones nos abrió la puerta. Subió nuestras maletas mientras yo pagaba al taxista. En recepción, Karine deletreó nuestro apellido y pidió una habitación con vistas al mar. El recepcionista nos dio la llave de la habitación 512, en el quinto piso. Cuando abrí las cortinas, la vista del puerto era magnífica. Por la noche, el cielo se despejó y miramos las estrellas desde el balcón. Hacia las tres de la madrugada, estábamos profundamente dormidos cuando sonó la alarma de incendios. Estábamos a punto de tomar el ascensor cuando Karine gritó: «¡No, la escalera!». En menos de dos minutos estábamos en el vestíbulo… en pijama. Sin embargo, ¡no había nadie más que nosotros! El recepcionista, muy tranquilo, nos explicó que era un fallo del sistema y que pasaba de vez en cuando. Yo me preguntaba por qué los demás clientes no habían bajado. Nos reímos mucho y nos fuimos al día siguiente con una buena historia que contar."},"highlighted_words":["Il pleuvait encore","s''arrêta","ouvrit","pendant que je payais","a épelé","se dégagea","nous étions en train de dormir","Nous étions sur le point de","Cependant","personne d''autre que nous","Je me demandais","rîmes","partîmes"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["J''étais","en","train","de","dormir"],"translation":"I was sleeping","translations":{"es":"Estaba durmiendo"}},{"words":["Il","pleuvait","quand","nous","sommes","arrivés"],"translation":"It was raining when we arrived","translations":{"es":"Llovía cuando llegamos"}},{"words":["Je","me","demandais","où","tu","étais"],"translation":"I was wondering where you were","translations":{"es":"Me preguntaba dónde estabas"}},{"words":["Je","voudrais","une","chambre","avec","vue"],"translation":"I would like a room with a view","translations":{"es":"Quisiera una habitación con vistas"}},{"words":["Il","n''y","avait","personne","d''autre"],"translation":"There was nobody else","translations":{"es":"No había nadie más"}},{"words":["Cet","ascenseur","est","très","lent"],"translation":"This elevator is very slow","translations":{"es":"Este ascensor es muy lento"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I have a reservation","translations":{"es":"Tengo una reserva"},"answer":"J''ai une réservation"},{"prompt":"What floor is the room on?","translations":{"es":"¿En qué piso está la habitación?"},"answer":"À quel étage est la chambre ?"},{"prompt":"I would like to pay the bill","translations":{"es":"Quisiera pagar la cuenta"},"answer":"Je voudrais régler la note"},{"prompt":"The view is magnificent","translations":{"es":"La vista es magnífica"},"answer":"La vue est magnifique"},{"prompt":"He was reading a book","translations":{"es":"Leía un libro"},"answer":"Il lisait un livre"},{"prompt":"She was smiling","translations":{"es":"Sonreía"},"answer":"Elle souriait"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 36: Aller se promener
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-36', 'Aller se promener', '🚶', 'Ir a pasear', 36, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"se promener","translation":"to go for a walk","translations":{"es":"pasear"}},{"id":"2","word":"la promenade","translation":"the walk","translations":{"es":"el paseo"}},{"id":"3","word":"marcher","translation":"to walk","translations":{"es":"caminar"}},{"id":"4","word":"dehors","translation":"outside","translations":{"es":"fuera"}},{"id":"5","word":"le matin / l''après-midi","translation":"morning / afternoon","translations":{"es":"la mañana / la tarde"}},{"id":"6","word":"la soirée","translation":"the evening","translations":{"es":"la velada / la noche"}},{"id":"7","word":"chaque","translation":"each / every","translations":{"es":"cada"}},{"id":"8","word":"emmener","translation":"to take (someone)","translations":{"es":"llevar (a alguien)"}},{"id":"9","word":"ramener","translation":"to bring back","translations":{"es":"traer de vuelta"}},{"id":"10","word":"montrer","translation":"to show","translations":{"es":"mostrar"}},{"id":"11","word":"garder","translation":"to keep / look after","translations":{"es":"guardar / cuidar"}},{"id":"12","word":"guider","translation":"to guide","translations":{"es":"guiar"}},{"id":"13","word":"faire attention à","translation":"to pay attention to","translations":{"es":"prestar atención a"}},{"id":"14","word":"oublier","translation":"to forget","translations":{"es":"olvidar"}},{"id":"15","word":"tomber","translation":"to fall","translations":{"es":"caer"}},{"id":"16","word":"se blesser","translation":"to get hurt","translations":{"es":"hacerse daño"}},{"id":"17","word":"balayer","translation":"to sweep","translations":{"es":"barrer"}},{"id":"18","word":"le balai","translation":"the broom","translations":{"es":"la escoba"}},{"id":"19","word":"transpirer","translation":"to sweat","translations":{"es":"sudar"}},{"id":"20","word":"souffler","translation":"to blow","translations":{"es":"soplar"}},{"id":"21","word":"gonfler","translation":"to inflate","translations":{"es":"inflar"}},{"id":"22","word":"le ballon","translation":"the balloon","translations":{"es":"el globo"}},{"id":"23","word":"plier","translation":"to fold / bend","translations":{"es":"doblar"}},{"id":"24","word":"appuyer","translation":"to press / lean","translations":{"es":"apoyar / pulsar"}},{"id":"25","word":"tirer","translation":"to pull","translations":{"es":"tirar"}},{"id":"26","word":"lancer","translation":"to throw","translations":{"es":"lanzar"}},{"id":"27","word":"gagner","translation":"to win","translations":{"es":"ganar"}},{"id":"28","word":"dessiner","translation":"to draw","translations":{"es":"dibujar"}},{"id":"29","word":"raconter","translation":"to tell","translations":{"es":"contar"}},{"id":"30","word":"partager","translation":"to share","translations":{"es":"compartir"}},{"id":"31","word":"se renseigner","translation":"to find out / inquire","translations":{"es":"informarse"}},{"id":"32","word":"bon marché","translation":"cheap","translations":{"es":"barato"}},{"id":"33","word":"le meilleur","translation":"the best","translations":{"es":"el mejor"}},{"id":"34","word":"la foule","translation":"the crowd","translations":{"es":"la multitud"}},{"id":"35","word":"le clown","translation":"the clown","translations":{"es":"el payaso"}},{"id":"36","word":"être au courant","translation":"to be informed","translations":{"es":"estar al tanto"}}],"grammar":[{"structure":"futur simple","example":"Demain, ils nous emmèneront au théâtre. / Tu sauras ce qu''on ressent.","en":"Simple future","es":"Futuro simple"},{"structure":"futur antérieur","example":"Elle aura oublié tout ça à la fin de la journée. / Le spectacle aura commencé quand nous arriverons.","en":"Future perfect (will have done)","es":"Futuro compuesto (habrá hecho)"},{"structure":"être en train de au futur","example":"Il sera en train de pleuvoir à ton arrivée.","en":"Future progressive","es":"Futuro progresivo («estará + gerundio»)"},{"structure":"futur proche","example":"Nous allons nous promener ce soir.","en":"Near future","es":"Futuro próximo"},{"structure":"quand / dès que + futur","example":"Qui sortira les gâteaux dès qu''ils seront prêts ?","en":"Future after time conjunctions","es":"Futuro tras conjunciones de tiempo"},{"structure":"doubles pronoms","example":"Je la leur présenterai aujourd''hui.","en":"Double object pronouns","es":"Pronombres dobles"},{"structure":"il se peut que + subjonctif","example":"Il se peut que personne ne te voie.","en":"\"It may be that\" + subjunctive","es":"«Puede que» + subjuntivo"}],"tips":[{"en":"Futur antérieur = futur of avoir/être + past participle: \"j''aurai fini\", \"elle sera partie\". It describes an action completed before another future moment.","es":"Futur antérieur = futuro de avoir/être + participio: «j''aurai fini», «elle sera partie». Describe una acción terminada antes de otro momento futuro."},{"en":"Order of double pronouns: me/te/se/nous/vous → le/la/les → lui/leur: \"Je te le donne\", \"Je la leur présente\".","es":"Orden de los pronombres dobles: me/te/se/nous/vous → le/la/les → lui/leur: «Je te le donne», «Je la leur présente»."},{"en":"\"Se plier en deux (de rire)\" = to double up with laughter.","es":"«Se plier en deux (de rire)» = partirse de risa."},{"en":"\"Être au courant\" = to know about / be informed.","es":"«Être au courant» = estar al tanto."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Allons nous promener !","translation":"Let''s go for a walk!","translations":{"es":"¡Vamos a pasear!"}},{"phrase":"Nous allons garder les enfants, c''est mieux.","translation":"We''ll look after the children, it''s better.","translations":{"es":"Cuidaremos a los niños, es mejor."}},{"phrase":"Elle aura oublié tout ça à la fin de la journée.","translation":"She will have forgotten all that by the end of the day.","translations":{"es":"Habrá olvidado todo eso al final del día."}},{"phrase":"Le spectacle aura commencé quand nous arriverons.","translation":"The show will have started when we arrive.","translations":{"es":"El espectáculo habrá empezado cuando lleguemos."}},{"phrase":"Demain, ils nous emmèneront au théâtre.","translation":"Tomorrow, they will take us to the theater.","translations":{"es":"Mañana nos llevarán al teatro."}},{"phrase":"La semaine prochaine, ils passeront « Autant en emporte le vent » au nouveau cinéma.","translation":"Next week, they will show \"Gone with the Wind\" at the new cinema.","translations":{"es":"La semana que viene pondrán «Lo que el viento se llevó» en el cine nuevo."}},{"phrase":"Cet arbre va tomber si tous ces enfants y grimpent en même temps !","translation":"This tree is going to fall if all these children climb it at the same time!","translations":{"es":"¡Este árbol se va a caer si todos esos niños se suben a la vez!"}},{"phrase":"Il sera en train de pleuvoir à ton arrivée.","translation":"It will be raining when you arrive.","translations":{"es":"Estará lloviendo cuando llegues."}},{"phrase":"Dans deux semaines, ils seront en train de dessiner pour une agence internationale.","translation":"In two weeks, they will be drawing for an international agency.","translations":{"es":"Dentro de dos semanas estarán dibujando para una agencia internacional."}},{"phrase":"Nous allons nous renseigner sur la visite guidée de samedi.","translation":"We''re going to find out about Saturday''s guided tour.","translations":{"es":"Vamos a informarnos sobre la visita guiada del sábado."}},{"phrase":"Quand vont-ils connaître ta grand-mère ? — Je la leur présenterai aujourd''hui.","translation":"When will they meet your grandmother? — I''ll introduce her to them today.","translations":{"es":"¿Cuándo van a conocer a tu abuela? — Se la presentaré hoy."}},{"phrase":"Qui sortira les gâteaux dès qu''ils seront prêts ? — Marie s''en chargera.","translation":"Who will take the cakes out as soon as they''re ready? — Marie will take care of it.","translations":{"es":"¿Quién sacará los pasteles en cuanto estén listos? — Marie se encargará."}},{"phrase":"Tu vas te promener ? — Non, je vais peindre un tableau.","translation":"Are you going for a walk? — No, I''m going to paint a picture.","translations":{"es":"¿Vas a pasear? — No, voy a pintar un cuadro."}},{"phrase":"Qui va parler à ton père quand il sera au courant ? — Mon frère.","translation":"Who will talk to your father when he finds out? — My brother.","translations":{"es":"¿Quién hablará con tu padre cuando se entere? — Mi hermano."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Quand tu arriveras, j''___ le dîner.\" (finir)","options":["ai fini","avais fini","aurai fini","finirai"],"correct":2,"explanation":"Futur antérieur: an action completed before another future action.","translations":{"es":{"question":"Completa: «Quand tu arriveras, j''___ le dîner.» (finir)","explanation":"Futur antérieur: acción terminada antes de otra acción futura."}}},{"id":"2","question":"Which tense is \"elle sera partie\"?","options":["simple future","past perfect","future perfect","conditional"],"correct":2,"explanation":"Futur of \"être\" + past participle.","translations":{"es":{"question":"¿Qué tiempo es «elle sera partie»?","explanation":"Futuro de «être» + participio.","options":["futuro simple","pluscuamperfecto","futuro compuesto","condicional"]}}},{"id":"3","question":"\"Il sera en train de pleuvoir.\" Meaning?","options":["It is going to stop raining.","It was raining.","It will be raining.","It has rained."],"correct":2,"explanation":"Être en train de in the future.","translations":{"es":{"question":"«Il sera en train de pleuvoir.» ¿Significado?","explanation":"«Être en train de» en futuro.","options":["Va a dejar de llover.","Estaba lloviendo.","Estará lloviendo.","Ha llovido."]}}},{"id":"4","question":"Complete: \"Je ___ présenterai.\" (her, to them)","options":["la leur","la lui","leur la","lui la"],"correct":0,"explanation":"Le/la/les before lui/leur.","translations":{"es":{"question":"Completa: «Je ___ présenterai.» (a ella, a ellos)","explanation":"Le/la/les antes de lui/leur."}}},{"id":"5","question":"Complete: \"Il sortira les gâteaux dès qu''ils ___ prêts.\"","options":["étaient","seront","sont","soient"],"correct":1,"explanation":"Future after \"dès que\" for a future event.","translations":{"es":{"question":"Completa: «Il sortira les gâteaux dès qu''ils ___ prêts.»","explanation":"Futuro tras «dès que» para un hecho futuro."}}},{"id":"6","question":"Complete: \"Il se peut que personne ne te ___.\"","options":["voie","voyait","voit","verra"],"correct":0,"explanation":"\"Il se peut que\" + subjunctive.","translations":{"es":{"question":"Completa: «Il se peut que personne ne te ___.»","explanation":"«Il se peut que» + subjuntivo."}}},{"id":"7","question":"\"Se plier en deux\" means…","options":["to double up with laughter","to split in two","to fold a paper","to bend down to pick something up"],"correct":0,"explanation":"Often \"se plier en deux de rire\".","translations":{"es":{"question":"«Se plier en deux» significa…","explanation":"A menudo «se plier en deux de rire».","options":["partirse de risa","dividirse en dos","doblar un papel","agacharse a recoger algo"]}}},{"id":"8","question":"Which verb means \"to take someone somewhere\"?","options":["emporter","emmener","prendre","apporter"],"correct":1,"explanation":"Emmener (people), emporter (things).","translations":{"es":{"question":"¿Qué verbo significa «llevar a alguien a un sitio»?","explanation":"Emmener (personas), emporter (cosas)."}}}]}'::jsonb, 3),
  ('story', 'Demain, au parc', '{"text":"Ce soir, Mamie raconte à son petit-fils Noé tout ce qu''ils feront demain. « D''abord, nous irons nous promener au parc de la Tête d''Or. Quand nous arriverons, les jardiniers seront en train d''arroser les fleurs. Tu verras les canards sur le lac et je te montrerai les girafes du petit zoo. À midi, nous aurons déjà marché pendant deux heures, alors nous mangerons une glace. L''après-midi, des clowns raconteront des histoires et feront rire tout le monde jusqu''à ce que les gens se plient en deux. Les enfants seront en train de gonfler des ballons et de courir partout. Tes parents nous rejoindront vers cinq heures ; à ce moment-là, tu auras sûrement déjà mangé deux crêpes ! » Noé sourit : « Et s''il pleut ? » « Il se peut qu''il pleuve un peu, mais ce n''est pas grave : nous marcherons sous la pluie. Je te montrerai le monde en un après-midi, et toi, tu partageras ton bonheur avec moi. » Noé s''endort en rêvant. Demain, il aura oublié la moitié de ce plan, mais Mamie, elle, n''oubliera rien.","translation":"Tonight, Grandma tells her grandson Noé everything they will do tomorrow. “First, we''ll go for a walk in the Tête d''Or park. When we arrive, the gardeners will be watering the flowers. You''ll see the ducks on the lake and I''ll show you the giraffes at the little zoo. By noon, we''ll already have walked for two hours, so we''ll have an ice cream. In the afternoon, clowns will tell stories and make everyone laugh until people double up. The children will be blowing up balloons and running everywhere. Your parents will join us around five; by then, you''ll surely have already eaten two crepes!” Noé smiles: “And what if it rains?” “It may rain a little, but it doesn''t matter: we''ll walk in the rain. I''ll show you the world in one afternoon, and you''ll share your happiness with me.” Noé falls asleep dreaming. Tomorrow, he''ll have forgotten half of this plan, but Grandma won''t forget anything.","translations":{"es":"Esta noche, la abuela le cuenta a su nieto Noé todo lo que harán mañana. «Primero iremos a pasear al parque de la Tête d''Or. Cuando lleguemos, los jardineros estarán regando las flores. Verás los patos en el lago y te enseñaré las jirafas del pequeño zoo. A mediodía ya habremos caminado dos horas, así que nos tomaremos un helado. Por la tarde, unos payasos contarán historias y harán reír a todo el mundo hasta que la gente se parta de risa. Los niños estarán inflando globos y corriendo por todas partes. Tus padres se reunirán con nosotros hacia las cinco; para entonces seguro que ya te habrás comido dos crepes.» Noé sonríe: «¿Y si llueve?» «Puede que llueva un poco, pero no pasa nada: caminaremos bajo la lluvia. Te enseñaré el mundo en una tarde y tú compartirás tu felicidad conmigo.» Noé se duerme soñando. Mañana habrá olvidado la mitad de este plan, pero la abuela no olvidará nada."},"highlighted_words":["nous irons nous promener","Quand nous arriverons","seront en train d''arroser","nous aurons déjà marché","se plient en deux","seront en train de gonfler","tu auras sûrement déjà mangé","Il se peut qu''il pleuve","partageras","il aura oublié"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Allons","nous","promener","au","parc"],"translation":"Let''s go for a walk in the park","translations":{"es":"Vamos a pasear al parque"}},{"words":["Quand","tu","arriveras","j''aurai","fini"],"translation":"When you arrive I''ll have finished","translations":{"es":"Cuando llegues, habré terminado"}},{"words":["Il","sera","en","train","de","pleuvoir"],"translation":"It will be raining","translations":{"es":"Estará lloviendo"}},{"words":["Je","la","leur","présenterai","demain"],"translation":"I''ll introduce her to them tomorrow","translations":{"es":"Se la presentaré mañana"}},{"words":["Nous","allons","garder","les","enfants"],"translation":"We''re going to look after the children","translations":{"es":"Vamos a cuidar a los niños"}},{"words":["Il","se","peut","qu''il","pleuve"],"translation":"It may rain","translations":{"es":"Puede que llueva"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Let''s go!","translations":{"es":"¡Vamos!"},"answer":"Allons-y !"},{"prompt":"I''m going to take the children to the park","translations":{"es":"Voy a llevar a los niños al parque"},"answer":"Je vais emmener les enfants au parc"},{"prompt":"She will have forgotten","translations":{"es":"Habrá olvidado"},"answer":"Elle aura oublié"},{"prompt":"We will walk in the rain","translations":{"es":"Caminaremos bajo la lluvia"},"answer":"Nous marcherons sous la pluie"},{"prompt":"Be careful","translations":{"es":"Ten cuidado"},"answer":"Fais attention"},{"prompt":"I''ll show you the city","translations":{"es":"Te enseñaré la ciudad"},"answer":"Je te montrerai la ville"}]}'::jsonb, 6)
) as v(type, title, content, ord);

