insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"louer","translation":"to rent","translations":{"es":"alquilar"}},{"id":"2","word":"l''agence de location","translation":"the rental agency","translations":{"es":"la agencia de alquiler"}},{"id":"3","word":"le / la responsable","translation":"the person in charge","translations":{"es":"el / la responsable"}},{"id":"4","word":"disponible","translation":"available","translations":{"es":"disponible"}},{"id":"5","word":"la voiture de luxe","translation":"luxury car","translations":{"es":"el coche de lujo"}},{"id":"6","word":"de taille moyenne","translation":"mid-size","translations":{"es":"de tamaño mediano"}},{"id":"7","word":"spacieux / spacieuse","translation":"spacious","translations":{"es":"espacioso / espaciosa"}},{"id":"8","word":"économique","translation":"economical","translations":{"es":"económico"}},{"id":"9","word":"consommer","translation":"to consume (fuel)","translations":{"es":"consumir"}},{"id":"10","word":"l''essence","translation":"gasoline / petrol","translations":{"es":"la gasolina"}},{"id":"11","word":"sans plomb","translation":"unleaded","translations":{"es":"sin plomo"}},{"id":"12","word":"le réservoir","translation":"the tank","translations":{"es":"el depósito"}},{"id":"13","word":"faire le plein","translation":"to fill up","translations":{"es":"llenar el depósito"}},{"id":"14","word":"la station-service","translation":"the gas station","translations":{"es":"la gasolinera"}},{"id":"15","word":"l''huile","translation":"oil","translations":{"es":"el aceite"}},{"id":"16","word":"le kilométrage","translation":"mileage","translations":{"es":"el kilometraje"}},{"id":"17","word":"illimité / illimitée","translation":"unlimited","translations":{"es":"ilimitado / ilimitada"}},{"id":"18","word":"l''assurance","translation":"insurance","translations":{"es":"el seguro"}},{"id":"19","word":"la caution","translation":"the deposit","translations":{"es":"la fianza"}},{"id":"20","word":"le pare-brise","translation":"the windshield","translations":{"es":"el parabrisas"}},{"id":"21","word":"le frein","translation":"the brake","translations":{"es":"el freno"}},{"id":"22","word":"freiner","translation":"to brake","translations":{"es":"frenar"}},{"id":"23","word":"accélérer","translation":"to accelerate","translations":{"es":"acelerar"}},{"id":"24","word":"le parking","translation":"the parking lot","translations":{"es":"el aparcamiento"}},{"id":"25","word":"le stationnement","translation":"parking","translations":{"es":"el estacionamiento"}},{"id":"26","word":"nettoyer","translation":"to clean","translations":{"es":"limpiar"}},{"id":"27","word":"casser","translation":"to break","translations":{"es":"romper"}},{"id":"28","word":"remplir","translation":"to fill in / fill up","translations":{"es":"rellenar / llenar"}},{"id":"29","word":"jeter un coup d''œil","translation":"to take a look","translations":{"es":"echar un vistazo"}},{"id":"30","word":"compliqué / compliquée","translation":"complicated","translations":{"es":"complicado / complicada"}},{"id":"31","word":"loin","translation":"far","translations":{"es":"lejos"}},{"id":"32","word":"devant","translation":"in front of","translations":{"es":"delante de"}},{"id":"33","word":"rendre","translation":"to return (something)","translations":{"es":"devolver"}}],"grammar":[{"structure":"passé composé + déjà / jamais / toujours","example":"Tu as déjà conduit ? — Je n''ai jamais conduit. / Ils ont toujours eu des voitures de luxe.","en":"Experiences with adverbs","es":"Experiencias con adverbios"},{"structure":"ça fait … que","example":"Ça fait des années que je voyage dans le monde.","en":"Duration up to now","es":"Duración hasta ahora"},{"structure":"bien que + subjonctif passé","example":"Bien que tu lui aies dit de ne pas conduire, il ne t''a pas écouté.","en":"\"Although\" + past subjunctive","es":"«Aunque» + subjuntivo pasado"},{"structure":"pour que + subjonctif","example":"Il a accéléré pour qu''on ne puisse pas le rattraper.","en":"\"So that\" + subjunctive","es":"«Para que» + subjuntivo"},{"structure":"relative + subjonctif","example":"J''ai besoin d''une voiture qui consomme peu et qui soit sûre.","en":"Subjunctive in a relative clause (wish)","es":"Subjuntivo en una relativa (deseo)"},{"structure":"depuis que","example":"Ils ne l''ont pas fait laver depuis qu''ils l''ont achetée.","en":"\"Since\" + clause","es":"«Desde que» + oración"},{"structure":"venir de + infinitif","example":"Marc vient d''arriver à Paris.","en":"Recent past","es":"Pasado reciente"},{"structure":"autant que / tant que","example":"Vous pouvez conduire autant que vous voulez.","en":"\"As much as\"","es":"«Tanto como»"}],"tips":[{"en":"At the rental desk: \"le kilométrage illimité\" (unlimited mileage), \"l''assurance tous risques\" (full insurance), \"la caution\" (deposit), \"rendre la voiture\" (return the car).","es":"En el mostrador de alquiler: «le kilométrage illimité» (kilometraje ilimitado), «l''assurance tous risques» (seguro a todo riesgo), «la caution» (fianza), «rendre la voiture» (devolver el coche)."},{"en":"\"Faire le plein\" = to fill up the tank; \"le réservoir est vide\" = the tank is empty; \"sans plomb\" = unleaded.","es":"«Faire le plein» = llenar el depósito; «le réservoir est vide» = el depósito está vacío; «sans plomb» = sin plomo."},{"en":"\"Jeter un coup d''œil\" = to take a quick look.","es":"«Jeter un coup d''œil» = echar un vistazo."},{"en":"Familiar: \"Occupe-toi de tes oignons !\" = Mind your own business!","es":"Coloquial: «Occupe-toi de tes oignons !» = ¡Métete en tus asuntos!"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Ils ont loué une voiture de taille moyenne.","translation":"They rented a mid-size car.","translations":{"es":"Alquilaron un coche de tamaño mediano."}},{"phrase":"Le responsable m''en a parlé.","translation":"The manager told me about it.","translations":{"es":"El responsable me habló de ello."}},{"phrase":"Ça fait des années que je voyage dans le monde.","translation":"I''ve been traveling the world for years.","translations":{"es":"Llevo años viajando por el mundo."}},{"phrase":"Il a nettoyé cette voiture dix fois cette semaine !","translation":"He has cleaned this car ten times this week!","translations":{"es":"¡Ha limpiado este coche diez veces esta semana!"}},{"phrase":"Bien que tu lui aies dit de ne pas conduire, il ne t''a pas écouté.","translation":"Although you told him not to drive, he didn''t listen to you.","translations":{"es":"Aunque le dijiste que no condujera, no te hizo caso."}},{"phrase":"Nous avons fait le plein deux fois aujourd''hui.","translation":"We filled up twice today.","translations":{"es":"Hemos llenado el depósito dos veces hoy."}},{"phrase":"Le kilométrage est illimité.","translation":"The mileage is unlimited.","translations":{"es":"El kilometraje es ilimitado."}},{"phrase":"J''ai toujours mis de l''essence sans plomb dans ma voiture.","translation":"I have always put unleaded gas in my car.","translations":{"es":"Siempre he puesto gasolina sin plomo en mi coche."}},{"phrase":"Il n''y a pas eu de voiture disponible de toute la semaine : elles ont toutes été louées.","translation":"There was no car available all week: they were all rented.","translations":{"es":"No ha habido ningún coche disponible en toda la semana: los han alquilado todos."}},{"phrase":"Il a accéléré pour qu''on ne puisse pas le rattraper.","translation":"He sped up so that we couldn''t catch up with him.","translations":{"es":"Aceleró para que no pudiéramos alcanzarlo."}},{"phrase":"Elle a déjà conduit ? — Je crois qu''elle n''est jamais montée dans une voiture !","translation":"Has she ever driven? — I think she has never even got into a car!","translations":{"es":"¿Ha conducido alguna vez? — ¡Creo que nunca se ha subido a un coche!"}},{"phrase":"Ils ont lavé la voiture récemment ? — Non, pas depuis qu''ils l''ont achetée.","translation":"Have they washed the car recently? — No, not since they bought it.","translations":{"es":"¿Han lavado el coche últimamente? — No, desde que lo compraron, no."}},{"phrase":"Tu as fait le plein ? — Non, mais un voyant m''indique quand le réservoir est vide.","translation":"Did you fill up? — No, but a light tells me when the tank is empty.","translations":{"es":"¿Has llenado el depósito? — No, pero un piloto me avisa cuando está vacío."}},{"phrase":"Le mécanicien a jeté un coup d''œil à ta voiture ? — Non, pas encore.","translation":"Has the mechanic taken a look at your car? — No, not yet.","translations":{"es":"¿El mecánico ha echado un vistazo a tu coche? — No, todavía no."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Tu as ___ conduit en France ?\" (ever)","options":["jamais","encore","toujours","déjà"],"correct":3,"explanation":"Déjà = ever / already in questions.","translations":{"es":{"question":"Completa: «Tu as ___ conduit en France ?» (alguna vez)","explanation":"Déjà = alguna vez / ya en preguntas."}}},{"id":"2","question":"Complete: \"Je n''ai ___ eu d''accident.\"","options":["toujours","encore","déjà","jamais"],"correct":3,"explanation":"Ne … jamais = never.","translations":{"es":{"question":"Completa: «Je n''ai ___ eu d''accident.»","explanation":"Ne … jamais = nunca."}}},{"id":"3","question":"Complete: \"Bien que tu lui ___ dit, il n''a pas écouté.\"","options":["auras","avais","as","aies"],"correct":3,"explanation":"\"Bien que\" + past subjunctive: que tu aies dit.","translations":{"es":{"question":"Completa: «Bien que tu lui ___ dit, il n''a pas écouté.»","explanation":"«Bien que» + subjuntivo pasado: que tu aies dit."}}},{"id":"4","question":"Complete: \"Je cherche une voiture qui ___ sûre.\"","options":["était","sera","est","soit"],"correct":3,"explanation":"Subjunctive after a wish for something not yet found.","translations":{"es":{"question":"Completa: «Je cherche une voiture qui ___ sûre.»","explanation":"Subjuntivo tras un deseo de algo que aún no se ha encontrado."}}},{"id":"5","question":"What does \"faire le plein\" mean?","options":["to clean the car","to park","to be full after eating","to fill up the tank"],"correct":3,"explanation":"Le plein = full tank.","translations":{"es":{"question":"¿Qué significa «faire le plein»?","explanation":"Le plein = depósito lleno.","options":["limpiar el coche","aparcar","estar lleno tras comer","llenar el depósito"]}}},{"id":"6","question":"\"Ça fait des années que je conduis.\" Meaning?","options":["I will drive for years.","I drove years ago.","I haven''t driven for years.","I''ve been driving for years."],"correct":3,"explanation":"Ça fait … que + present = still true.","translations":{"es":{"question":"«Ça fait des années que je conduis.» ¿Significado?","explanation":"Ça fait … que + presente = sigue siendo cierto.","options":["Conduciré durante años.","Conduje hace años.","Hace años que no conduzco.","Llevo años conduciendo."]}}},{"id":"7","question":"What is \"la caution\" at a rental agency?","options":["the key","the caution sign","the insurance","the deposit"],"correct":3,"explanation":"Money held until you return the car.","translations":{"es":{"question":"¿Qué es «la caution» en una agencia de alquiler?","explanation":"Dinero retenido hasta devolver el coche.","options":["la llave","la señal de precaución","el seguro","la fianza"]}}},{"id":"8","question":"\"Jeter un coup d''œil\" means…","options":["to throw something","to close your eyes","to hit someone","to take a quick look"],"correct":3,"explanation":"Literally \"to throw a stroke of the eye\".","translations":{"es":{"question":"«Jeter un coup d''œil» significa…","explanation":"Literalmente «lanzar un golpe de ojo».","options":["tirar algo","cerrar los ojos","pegar a alguien","echar un vistazo"]}}}]}'::jsonb, 3),
  ('story', 'À l''agence de location', '{"text":"Inès vient d''arriver à l''aéroport de Nice. Elle doit louer une voiture pour visiter la Provence. Le parking de l''agence est plein, et un employé s''approche. « Bonjour, je peux vous aider ? » « Oui, je voudrais louer une voiture pour deux semaines. » « Nous avons des voitures de luxe et des voitures plus simples. Vous avez déjà conduit en France ? » « Oui, ça fait des années que je voyage, mais je n''ai jamais conduit dans les montagnes. Comme je voyage seule, je n''ai pas besoin de beaucoup d''espace. Je cherche plutôt une voiture qui consomme peu et qui soit sûre. Qu''est-ce que vous me recommandez ? » « J''ai une petite citadine, toute neuve. Elle n''a fait que cinq cents kilomètres depuis qu''on l''a achetée. Si vous la louez plus d''une semaine, le kilométrage est illimité : vous pouvez conduire autant que vous voulez. Elle est livrée avec le plein, et vous pouvez la rendre dans n''importe quelle agence. » « Parfait ! Et l''assurance ? » « Bien qu''elle ne soit pas obligatoire, je vous conseille l''assurance tous risques. » « D''accord, je la prends ! »","translation":"Inès has just arrived at Nice airport. She has to rent a car to visit Provence. The agency''s parking lot is full, and an employee comes up to her. “Hello, can I help you?” “Yes, I''d like to rent a car for two weeks.” “We have luxury cars and simpler cars. Have you ever driven in France?” “Yes, I''ve been traveling for years, but I''ve never driven in the mountains. Since I travel alone, I don''t need much space. I''m rather looking for a car that uses little gas and is safe. What do you recommend?” “I have a small city car, brand new. It has only done five hundred kilometers since we bought it. If you rent it for more than a week, the mileage is unlimited: you can drive as much as you want. It comes with a full tank, and you can return it to any of our agencies.” “Perfect! And the insurance?” “Although it isn''t compulsory, I recommend full insurance.” “All right, I''ll take it!”","translations":{"es":"Inès acaba de llegar al aeropuerto de Niza. Tiene que alquilar un coche para visitar la Provenza. El aparcamiento de la agencia está lleno y se le acerca un empleado. «Buenos días, ¿puedo ayudarla?» «Sí, quisiera alquilar un coche para dos semanas.» «Tenemos coches de lujo y coches más sencillos. ¿Ha conducido alguna vez en Francia?» «Sí, llevo años viajando, pero nunca he conducido por la montaña. Como viajo sola, no necesito mucho espacio. Busco más bien un coche que consuma poco y que sea seguro. ¿Qué me recomienda?» «Tengo un utilitario pequeño, nuevecito. Solo ha hecho quinientos kilómetros desde que lo compramos. Si lo alquila más de una semana, el kilometraje es ilimitado: puede conducir tanto como quiera. Se entrega con el depósito lleno y puede devolverlo en cualquier agencia.» «¡Perfecto! ¿Y el seguro?» «Aunque no sea obligatorio, le aconsejo el seguro a todo riesgo.» «¡De acuerdo, me lo quedo!»"},"highlighted_words":["vient d''arriver","louer","Vous avez déjà conduit","ça fait des années que","je n''ai jamais conduit","qui soit sûre","depuis qu''on l''a achetée","kilométrage est illimité","autant que vous voulez","le plein","Bien qu''elle ne soit pas"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","voudrais","louer","une","voiture"],"translation":"I would like to rent a car","translations":{"es":"Quisiera alquilar un coche"}},{"words":["Tu","as","déjà","conduit","en","France"],"translation":"Have you ever driven in France","translations":{"es":"¿Has conducido alguna vez en Francia?"}},{"words":["Je","n''ai","jamais","eu","d''accident"],"translation":"I have never had an accident","translations":{"es":"Nunca he tenido un accidente"}},{"words":["Il","faut","faire","le","plein"],"translation":"We need to fill up","translations":{"es":"Hay que llenar el depósito"}},{"words":["Le","kilométrage","est","illimité"],"translation":"The mileage is unlimited","translations":{"es":"El kilometraje es ilimitado"}},{"words":["Ça","fait","des","années","que","je","conduis"],"translation":"I''ve been driving for years","translations":{"es":"Llevo años conduciendo"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"The car is available","translations":{"es":"El coche está disponible"},"answer":"La voiture est disponible"},{"prompt":"The tank is empty","translations":{"es":"El depósito está vacío"},"answer":"Le réservoir est vide"},{"prompt":"Where is the gas station?","translations":{"es":"¿Dónde está la gasolinera?"},"answer":"Où est la station-service ?"},{"prompt":"The windshield is broken","translations":{"es":"El parabrisas está roto"},"answer":"Le pare-brise est cassé"},{"prompt":"I''m going to return the car tomorrow","translations":{"es":"Voy a devolver el coche mañana"},"answer":"Je vais rendre la voiture demain"},{"prompt":"She has always driven carefully","translations":{"es":"Siempre ha conducido con prudencia"},"answer":"Elle a toujours conduit prudemment"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 38: Au restaurant
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-38', 'Au restaurant', '🍽️', 'En el restaurante', 38, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le restaurant","translation":"the restaurant","translations":{"es":"el restaurante"}},{"id":"2","word":"la carte","translation":"the menu","translations":{"es":"la carta"}},{"id":"3","word":"le menu","translation":"the set menu","translations":{"es":"el menú"}},{"id":"4","word":"l''entrée","translation":"the starter","translations":{"es":"el entrante"}},{"id":"5","word":"le plat principal","translation":"the main course","translations":{"es":"el plato principal"}},{"id":"6","word":"le dessert","translation":"dessert","translations":{"es":"el postre"}},{"id":"7","word":"l''apéritif","translation":"the aperitif","translations":{"es":"el aperitivo"}},{"id":"8","word":"le serveur / la serveuse","translation":"the waiter / waitress","translations":{"es":"el camarero / la camarera"}},{"id":"9","word":"le maître d''hôtel","translation":"the head waiter","translations":{"es":"el jefe de sala"}},{"id":"10","word":"l''addition","translation":"the bill","translations":{"es":"la cuenta"}},{"id":"11","word":"le pourboire","translation":"the tip","translations":{"es":"la propina"}},{"id":"12","word":"réserver une table","translation":"to book a table","translations":{"es":"reservar una mesa"}},{"id":"13","word":"commander","translation":"to order","translations":{"es":"pedir"}},{"id":"14","word":"servir","translation":"to serve","translations":{"es":"servir"}},{"id":"15","word":"goûter","translation":"to taste","translations":{"es":"probar"}},{"id":"16","word":"mélanger","translation":"to mix","translations":{"es":"mezclar"}},{"id":"17","word":"couper","translation":"to cut","translations":{"es":"cortar"}},{"id":"18","word":"brûler","translation":"to burn","translations":{"es":"quemar"}},{"id":"19","word":"mordre","translation":"to bite","translations":{"es":"morder"}},{"id":"20","word":"le plateau","translation":"the tray","translations":{"es":"la bandeja"}},{"id":"21","word":"les restes","translation":"leftovers","translations":{"es":"las sobras"}},{"id":"22","word":"avoir faim","translation":"to be hungry","translations":{"es":"tener hambre"}},{"id":"23","word":"avoir soif","translation":"to be thirsty","translations":{"es":"tener sed"}},{"id":"24","word":"le régime","translation":"the diet","translations":{"es":"la dieta"}},{"id":"25","word":"saignant / à point / bien cuit","translation":"rare / medium / well done","translations":{"es":"poco hecho / en su punto / muy hecho"}},{"id":"26","word":"délicieux / délicieuse","translation":"delicious","translations":{"es":"delicioso / deliciosa"}},{"id":"27","word":"la climatisation","translation":"air conditioning","translations":{"es":"el aire acondicionado"}},{"id":"28","word":"de retour","translation":"back","translations":{"es":"de vuelta"}},{"id":"29","word":"beurrer","translation":"to butter","translations":{"es":"untar con mantequilla"}},{"id":"30","word":"cher / chère","translation":"expensive","translations":{"es":"caro / cara"}}],"grammar":[{"structure":"plus-que-parfait","example":"Il avait réparé la climatisation et tu l''as cassée de nouveau. / Nous étions déjà venus.","en":"Past perfect","es":"Pluscuamperfecto"},{"structure":"conditionnel passé","example":"Le déjeuner aurait pu être meilleur.","en":"Past conditional (would have)","es":"Condicional compuesto (habría)"},{"structure":"si + plus-que-parfait → conditionnel passé","example":"Si tu avais fait cuire la viande plus longtemps, elle aurait été meilleure.","en":"Unreal past condition","es":"Condición irreal en el pasado"},{"structure":"passé simple (récit)","example":"Le serveur tendit l''addition. Heureusement, la bouteille n''explosa pas.","en":"Literary past","es":"Pasado literario"},{"structure":"bien que + subjonctif passé","example":"Bien que le maître d''hôtel nous ait regardés de haut, nous l''avons suivi.","en":"\"Although\" + past subjunctive","es":"«Aunque» + subjuntivo pasado"},{"structure":"jusqu''à ce que + subjonctif","example":"Elle n''avait rien mangé jusqu''à ce que tu la nourrisses.","en":"\"Until\" + subjunctive","es":"«Hasta que» + subjuntivo"},{"structure":"discours indirect au passé","example":"Il nous a demandé si nous avions réservé.","en":"Reported question (past perfect)","es":"Pregunta indirecta (pluscuamperfecto)"}],"tips":[{"en":"Unreal past: si + plus-que-parfait, then conditionnel passé: \"Si j''avais su, je serais venu.\" Never the conditional after \"si\".","es":"Pasado irreal: si + plus-que-parfait y luego conditionnel passé: «Si j''avais su, je serais venu.» Nunca condicional después de «si»."},{"en":"In a French restaurant: \"la carte\" (the menu), \"le menu\" (set menu), \"l''entrée\" (starter), \"le plat\" (main course), \"l''addition, s''il vous plaît\" (the bill).","es":"En un restaurante francés: «la carte» (la carta), «le menu» (menú del día), «l''entrée» (entrante), «le plat» (plato principal), «l''addition, s''il vous plaît» (la cuenta)."},{"en":"Steak cooking: \"bleu\" (very rare), \"saignant\" (rare), \"à point\" (medium), \"bien cuit\" (well done).","es":"Punto de la carne: «bleu» (vuelta y vuelta), «saignant» (poco hecha), «à point» (en su punto), «bien cuit» (muy hecha)."},{"en":"Tips are included in France (\"service compris\"); leaving a little extra is optional.","es":"En Francia el servicio está incluido («service compris»); dejar algo más es opcional."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Il avait réparé la climatisation et tu l''as cassée de nouveau !","translation":"He had fixed the air conditioning and you broke it again!","translations":{"es":"¡Había arreglado el aire acondicionado y lo has vuelto a romper!"}},{"phrase":"Le serveur m''avait déjà servi un dessert.","translation":"The waiter had already served me a dessert.","translations":{"es":"El camarero ya me había servido un postre."}},{"phrase":"Nous étions déjà venus dans ce restaurant.","translation":"We had already been to this restaurant.","translations":{"es":"Ya habíamos venido a este restaurante."}},{"phrase":"Le déjeuner aurait été meilleur si tu avais fait cuire la viande plus longtemps.","translation":"Lunch would have been better if you had cooked the meat longer.","translations":{"es":"El almuerzo habría estado mejor si hubieras cocinado la carne más tiempo."}},{"phrase":"Nous t''avions laissé du vin, mais il l''a bu.","translation":"We had left you some wine, but he drank it.","translations":{"es":"Te habíamos dejado vino, pero se lo bebió."}},{"phrase":"J''avais coupé la viande pour mes enfants.","translation":"I had cut the meat for my children.","translations":{"es":"Les había cortado la carne a mis hijos."}},{"phrase":"Heureusement, la bouteille n''explosa pas.","translation":"Luckily, the bottle didn''t explode.","translations":{"es":"Por suerte, la botella no explotó."}},{"phrase":"Si tu les avais servis avant, ils auraient déjà fini.","translation":"If you had served them earlier, they would already have finished.","translations":{"es":"Si los hubieras servido antes, ya habrían terminado."}},{"phrase":"Le poulet aurait brûlé si je n''avais pas éteint le four.","translation":"The chicken would have burned if I hadn''t turned off the oven.","translations":{"es":"El pollo se habría quemado si no hubiera apagado el horno."}},{"phrase":"Elle avait mangé avant de venir ? — Non, elle n''avait pas voulu.","translation":"Had she eaten before coming? — No, she hadn''t wanted to.","translations":{"es":"¿Había comido antes de venir? — No, no había querido."}},{"phrase":"Ils connaissaient ce restaurant ? — Pas jusqu''à ce que je les y emmène.","translation":"Did they know this restaurant? — Not until I took them there.","translations":{"es":"¿Conocían este restaurante? — No hasta que los llevé."}},{"phrase":"Où aviez-vous laissé les restes ? — Sur la table, mais quelqu''un les a mangés.","translation":"Where had you left the leftovers? — On the table, but someone ate them.","translations":{"es":"¿Dónde habían dejado las sobras? — En la mesa, pero alguien se las comió."}},{"phrase":"Je voudrais le steak à point, s''il vous plaît.","translation":"I would like the steak medium, please.","translations":{"es":"Quisiera el filete en su punto, por favor."}},{"phrase":"L''addition, s''il vous plaît !","translation":"The bill, please!","translations":{"es":"¡La cuenta, por favor!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Quand je suis arrivé, ils ___ déjà mangé.\"","options":["auront","avaient","auraient","ont"],"correct":1,"explanation":"Plus-que-parfait: action before another past action.","translations":{"es":{"question":"Completa: «Quand je suis arrivé, ils ___ déjà mangé.»","explanation":"Pluscuamperfecto: acción anterior a otra pasada."}}},{"id":"2","question":"Complete: \"Si tu avais réservé, nous ___ une table.\"","options":["aurons eu","aurions eu","aurions","avions eu"],"correct":1,"explanation":"Si + plus-que-parfait → conditionnel passé.","translations":{"es":{"question":"Completa: «Si tu avais réservé, nous ___ une table.»","explanation":"Si + plus-que-parfait → conditionnel passé."}}},{"id":"3","question":"Which sentence is correct?","options":["Si j''avais su, je serais venu.","Si je savais, je serais venu.","Si j''avais su, je viendrai.","Si j''aurais su, je serais venu."],"correct":0,"explanation":"Never the conditional after \"si\".","translations":{"es":{"question":"¿Qué frase es correcta?","explanation":"Nunca condicional después de «si»."}}},{"id":"4","question":"How do you order a steak \"medium\"?","options":["à point","bien cuit","bleu","saignant"],"correct":0,"explanation":"Bleu < saignant < à point < bien cuit.","translations":{"es":{"question":"¿Cómo pides un filete «en su punto»?","explanation":"Bleu < saignant < à point < bien cuit."}}},{"id":"5","question":"In France, \"le menu\" usually means…","options":["the dessert","a set menu","the bill","the full list of dishes"],"correct":1,"explanation":"The list of dishes is \"la carte\".","translations":{"es":{"question":"En Francia, «le menu» suele significar…","explanation":"La lista de platos es «la carte».","options":["el postre","un menú cerrado","la cuenta","la lista completa de platos"]}}},{"id":"6","question":"Complete: \"Bien qu''il nous ___ regardés de haut, nous sommes restés.\"","options":["ait","aura","avait","a"],"correct":0,"explanation":"\"Bien que\" + past subjunctive.","translations":{"es":{"question":"Completa: «Bien qu''il nous ___ regardés de haut, nous sommes restés.»","explanation":"«Bien que» + subjuntivo pasado."}}},{"id":"7","question":"\"La bouteille n''explosa pas.\" Which tense?","options":["passé simple","futur","plus-que-parfait","imparfait"],"correct":0,"explanation":"Spoken: \"n''a pas explosé\".","translations":{"es":{"question":"«La bouteille n''explosa pas.» ¿Qué tiempo?","explanation":"Oral: «n''a pas explosé».","options":["passé simple","futuro","pluscuamperfecto","imperfecto"]}}},{"id":"8","question":"Reported: \"Avez-vous réservé ?\" → Il nous a demandé si nous ___ réservé.","options":["aurons","aurions","avions","avons"],"correct":2,"explanation":"Passé composé → plus-que-parfait.","translations":{"es":{"question":"Indirecto: «Avez-vous réservé ?» → Il nous a demandé si nous ___ réservé.","explanation":"Passé composé → plus-que-parfait."}}}]}'::jsonb, 3),
  ('story', 'Notre premier grand restaurant', '{"text":"Nous n''avions jamais mangé dans un grand restaurant. Mais pour mon anniversaire, mon copain Théo m''a invitée au Pavillon, un restaurant très chic de Lyon où il faut être bien habillé. Nous y sommes allés avec deux amis qui, comme nous, n''avaient jamais goûté la grande cuisine française. Quand nous sommes entrés, un maître d''hôtel très élégant nous a demandé si nous avions réservé. Bien qu''il nous ait regardés de haut, nous l''avons suivi jusqu''à une table magnifique. La carte était entièrement en français gastronomique : nous n''avions rien compris, et nous n''avons pas osé poser de questions. Alors, nous avons commandé au hasard. Les plats furent délicieux, mais très petits ! À la fin, le serveur tendit l''addition à Théo. Il devint tout pâle et la montra à nos amis. Si nous avions regardé les prix avant, nous aurions choisi le menu du jour ! Nous avons dû réunir tout notre argent pour payer. Nous n''avions jamais si bien dîné… mais nous n''avions jamais payé un dîner aussi cher non plus !","translation":"We had never eaten in a fancy restaurant. But for my birthday, my boyfriend Théo invited me to Le Pavillon, a very chic restaurant in Lyon where you have to be well dressed. We went there with two friends who, like us, had never tasted fine French cuisine. When we went in, a very elegant head waiter asked us if we had booked. Although he looked down on us, we followed him to a magnificent table. The menu was entirely in gastronomic French: we hadn''t understood anything, and we didn''t dare ask questions. So we ordered at random. The dishes were delicious, but very small! At the end, the waiter handed the bill to Théo. He went completely pale and showed it to our friends. If we had looked at the prices beforehand, we would have chosen the set menu! We had to pool all our money to pay. We had never dined so well… but we had never paid so much for a dinner either!","translations":{"es":"Nunca habíamos comido en un gran restaurante. Pero, por mi cumpleaños, mi novio Théo me invitó a Le Pavillon, un restaurante muy elegante de Lyon donde hay que ir bien vestido. Fuimos con dos amigos que, como nosotros, nunca habían probado la alta cocina francesa. Cuando entramos, un jefe de sala muy elegante nos preguntó si habíamos reservado. Aunque nos miró por encima del hombro, lo seguimos hasta una mesa magnífica. La carta estaba entera en francés gastronómico: no habíamos entendido nada y no nos atrevimos a preguntar. Así que pedimos al azar. Los platos estaban deliciosos, ¡pero eran muy pequeños! Al final, el camarero le tendió la cuenta a Théo. Se puso pálido y se la enseñó a nuestros amigos. ¡Si hubiéramos mirado los precios antes, habríamos elegido el menú del día! Tuvimos que juntar todo nuestro dinero para pagar. Nunca habíamos cenado tan bien… ¡pero tampoco habíamos pagado nunca tanto por una cena!"},"highlighted_words":["Nous n''avions jamais mangé","n''avaient jamais goûté","si nous avions réservé","Bien qu''il nous ait regardés","nous n''avions rien compris","furent","tendit","devint","Si nous avions regardé","nous aurions choisi"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Nous","n''avions","jamais","mangé","ici"],"translation":"We had never eaten here","translations":{"es":"Nunca habíamos comido aquí"}},{"words":["Si","tu","avais","réservé","nous","aurions","mangé"],"translation":"If you had booked we would have eaten","translations":{"es":"Si hubieras reservado, habríamos comido"}},{"words":["L''addition","s''il","vous","plaît"],"translation":"The bill please","translations":{"es":"La cuenta, por favor"}},{"words":["Le","dîner","aurait","pu","être","meilleur"],"translation":"Dinner could have been better","translations":{"es":"La cena podría haber sido mejor"}},{"words":["Je","voudrais","le","steak","à","point"],"translation":"I would like the steak medium","translations":{"es":"Quisiera el filete en su punto"}},{"words":["Il","avait","déjà","commandé"],"translation":"He had already ordered","translations":{"es":"Ya había pedido"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"A table for four, please","translations":{"es":"Una mesa para cuatro, por favor"},"answer":"Une table pour quatre, s''il vous plaît"},{"prompt":"I''m very hungry","translations":{"es":"Tengo mucha hambre"},"answer":"J''ai très faim"},{"prompt":"It was delicious","translations":{"es":"Estaba delicioso"},"answer":"C''était délicieux"},{"prompt":"If I had known, I would have come","translations":{"es":"Si lo hubiera sabido, habría venido"},"answer":"Si j''avais su, je serais venu"},{"prompt":"We had already eaten","translations":{"es":"Ya habíamos comido"},"answer":"Nous avions déjà mangé"},{"prompt":"Service is included","translations":{"es":"El servicio está incluido"},"answer":"Le service est compris"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 39: Faire les courses et du shopping
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-39', 'Faire les courses et du shopping', '🛍️', 'Ir de compras', 39, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"faire les courses","translation":"to do the grocery shopping","translations":{"es":"hacer la compra"}},{"id":"2","word":"faire du shopping","translation":"to go shopping","translations":{"es":"ir de compras"}},{"id":"3","word":"faire du lèche-vitrine","translation":"to window-shop","translations":{"es":"mirar escaparates"}},{"id":"4","word":"le magasin","translation":"the store","translations":{"es":"la tienda"}},{"id":"5","word":"la grande surface","translation":"the hypermarket","translations":{"es":"el hipermercado"}},{"id":"6","word":"le centre commercial","translation":"the shopping mall","translations":{"es":"el centro comercial"}},{"id":"7","word":"le rayon","translation":"the department / aisle","translations":{"es":"la sección"}},{"id":"8","word":"la vitrine","translation":"the shop window","translations":{"es":"el escaparate"}},{"id":"9","word":"le vendeur / la vendeuse","translation":"the salesperson","translations":{"es":"el vendedor / la vendedora"}},{"id":"10","word":"la caisse","translation":"the checkout","translations":{"es":"la caja"}},{"id":"11","word":"acheter","translation":"to buy","translations":{"es":"comprar"}},{"id":"12","word":"choisir","translation":"to choose","translations":{"es":"elegir"}},{"id":"13","word":"essayer","translation":"to try on","translations":{"es":"probarse"}},{"id":"14","word":"la cabine d''essayage","translation":"the fitting room","translations":{"es":"el probador"}},{"id":"15","word":"la taille","translation":"size (clothes)","translations":{"es":"la talla"}},{"id":"16","word":"la pointure","translation":"shoe size","translations":{"es":"el número (de calzado)"}},{"id":"17","word":"petit / moyen / grand","translation":"small / medium / large","translations":{"es":"pequeño / mediano / grande"}},{"id":"18","word":"extra-large","translation":"extra large","translations":{"es":"extragrande"}},{"id":"19","word":"rendre / rapporter","translation":"to return (an item)","translations":{"es":"devolver"}},{"id":"20","word":"échanger","translation":"to exchange","translations":{"es":"cambiar"}},{"id":"21","word":"le ticket de caisse","translation":"the receipt","translations":{"es":"el tique de compra"}},{"id":"22","word":"les soldes","translation":"the sales","translations":{"es":"las rebajas"}},{"id":"23","word":"la réduction","translation":"the discount","translations":{"es":"el descuento"}},{"id":"24","word":"le cadeau","translation":"the gift","translations":{"es":"el regalo"}},{"id":"25","word":"les bijoux","translation":"jewelry","translations":{"es":"las joyas"}},{"id":"26","word":"lavable","translation":"washable","translations":{"es":"lavable"}},{"id":"27","word":"déteindre","translation":"to run (color)","translations":{"es":"desteñir"}},{"id":"28","word":"rétrécir","translation":"to shrink","translations":{"es":"encoger"}},{"id":"29","word":"deviner","translation":"to guess","translations":{"es":"adivinar"}},{"id":"30","word":"supposer","translation":"to suppose","translations":{"es":"suponer"}},{"id":"31","word":"attirant / attirante","translation":"attractive","translations":{"es":"atractivo / atractiva"}},{"id":"32","word":"facile","translation":"easy","translations":{"es":"fácil"}},{"id":"33","word":"puisque","translation":"since","translations":{"es":"puesto que"}},{"id":"34","word":"car","translation":"because / for","translations":{"es":"pues / porque"}}],"grammar":[{"structure":"futur antérieur","example":"Quand tu viendras nous chercher, nous aurons fait des achats pendant une heure.","en":"Future perfect","es":"Futuro compuesto"},{"structure":"quand + futur antérieur","example":"Quand tu auras décidé, on aura vendu les bijoux.","en":"Completed future actions","es":"Acciones futuras terminadas"},{"structure":"futur antérieur (probabilité)","example":"Elle aura sûrement acheté la nourriture avant ton arrivée.","en":"Probability / assumption","es":"Probabilidad / suposición"},{"structure":"conditionnel passé","example":"Tu aurais trouvé le cadeau parfait si tu avais cherché dans un autre rayon.","en":"Past conditional","es":"Condicional compuesto"},{"structure":"avant que + subjonctif","example":"Le vendeur aura vendu la robe avant que tu puisses l''acheter.","en":"\"Before\" + subjunctive","es":"«Antes de que» + subjuntivo"},{"structure":"aller à quelqu''un","example":"Ces pantalons ne lui iront pas.","en":"\"To fit / suit\"","es":"«Quedarle bien»"},{"structure":"parce que / car / puisque","example":"Je n''achète rien, puisque tout est trop cher.","en":"Giving reasons","es":"Dar razones"}],"tips":[{"en":"\"Faire les courses\" = grocery shopping; \"faire du shopping / des achats\" = clothes or other shopping; \"faire du lèche-vitrine\" = window-shopping.","es":"«Faire les courses» = hacer la compra; «faire du shopping / des achats» = ir de compras; «faire du lèche-vitrine» = mirar escaparates."},{"en":"Sizes: \"la taille\" for clothes (S, M, L), \"la pointure\" for shoes (\"Vous faites quelle pointure ?\").","es":"Tallas: «la taille» para la ropa (S, M, L), «la pointure» para el calzado («Vous faites quelle pointure ?»)."},{"en":"\"Déteindre\" = to run (colors); \"rétrécir\" = to shrink. Check the label: \"lavable en machine\".","es":"«Déteindre» = desteñir; «rétrécir» = encoger. Mira la etiqueta: «lavable en machine»."},{"en":"In France, \"les soldes\" (sales) happen twice a year, in January and in summer, on dates set by law.","es":"En Francia, «les soldes» (rebajas) se hacen dos veces al año, en enero y en verano, en fechas fijadas por ley."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Quand tu viendras nous chercher, nous aurons fait des achats pendant une heure.","translation":"When you come to pick us up, we will have been shopping for an hour.","translations":{"es":"Cuando vengas a buscarnos, habremos estado de compras una hora."}},{"phrase":"Elle aura sûrement acheté la nourriture avant ton arrivée.","translation":"She will surely have bought the food before you arrive.","translations":{"es":"Seguramente habrá comprado la comida antes de que llegues."}},{"phrase":"Il aura apporté les vêtements des enfants quand tu seras de retour.","translation":"He will have brought the children''s clothes by the time you get back.","translations":{"es":"Habrá traído la ropa de los niños cuando vuelvas."}},{"phrase":"Tu aurais trouvé le cadeau parfait si tu avais cherché dans un autre rayon.","translation":"You would have found the perfect gift if you had looked in another department.","translations":{"es":"Habrías encontrado el regalo perfecto si hubieras buscado en otra sección."}},{"phrase":"Quand tu le sortiras de la machine, la couleur aura déteint.","translation":"When you take it out of the machine, the color will have run.","translations":{"es":"Cuando lo saques de la lavadora, el color se habrá desteñido."}},{"phrase":"Après le lavage, ton tee-shirt aura rétréci.","translation":"After the wash, your T-shirt will have shrunk.","translations":{"es":"Después del lavado, tu camiseta habrá encogido."}},{"phrase":"Le vendeur aura vendu la robe avant que tu puisses l''acheter.","translation":"The salesman will have sold the dress before you can buy it.","translations":{"es":"El vendedor habrá vendido el vestido antes de que puedas comprarlo."}},{"phrase":"Nous serons de retour à la maison avant papa.","translation":"We will be back home before Dad.","translations":{"es":"Volveremos a casa antes que papá."}},{"phrase":"Auriez-vous ce tee-shirt en grande taille ? — Que pensez-vous d''un M ?","translation":"Would you have this T-shirt in a large size? — What do you think of an M?","translations":{"es":"¿Tendría esta camiseta en talla grande? — ¿Qué le parece una M?"}},{"phrase":"Tu vas acheter ce pantalon pour ton père ? — Je ne sais pas, il ne lui ira peut-être pas.","translation":"Are you going to buy these trousers for your father? — I don''t know, they may not fit him.","translations":{"es":"¿Vas a comprarle este pantalón a tu padre? — No sé, quizá no le quede bien."}},{"phrase":"Vous faites quelle pointure ? — Du trente-huit.","translation":"What shoe size are you? — A thirty-eight.","translations":{"es":"¿Qué número calza? — Un treinta y ocho."}},{"phrase":"Je voudrais rapporter ce pull. Voici le ticket de caisse.","translation":"I would like to return this sweater. Here is the receipt.","translations":{"es":"Quisiera devolver este jersey. Aquí tiene el tique."}},{"phrase":"Samedi, je vais faire du lèche-vitrine avec ma sœur.","translation":"On Saturday, I''m going window-shopping with my sister.","translations":{"es":"El sábado voy a mirar escaparates con mi hermana."}},{"phrase":"Je n''achète rien, puisque tout est trop cher.","translation":"I''m not buying anything, since everything is too expensive.","translations":{"es":"No compro nada, puesto que todo es demasiado caro."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Quand tu reviendras, j''___ les cadeaux.\" (acheter)","options":["ai acheté","aurai acheté","achèterai","aurais acheté"],"correct":1,"explanation":"Futur antérieur: completed before you come back.","translations":{"es":{"question":"Completa: «Quand tu reviendras, j''___ les cadeaux.» (acheter)","explanation":"Futur antérieur: terminado antes de que vuelvas."}}},{"id":"2","question":"\"Elle aura oublié son portefeuille.\" Here the futur antérieur expresses…","options":["an order","a probable assumption","a wish","a habit"],"correct":1,"explanation":"\"She must have forgotten her wallet.\"","translations":{"es":{"question":"«Elle aura oublié son portefeuille.» Aquí el futur antérieur expresa…","explanation":"«Se habrá olvidado la cartera.»","options":["una orden","una suposición probable","un deseo","un hábito"]}}},{"id":"3","question":"Complete: \"Tu ___ le cadeau si tu avais cherché ailleurs.\"","options":["aurais trouvé","aurai trouvé","avais trouvé","trouverais"],"correct":0,"explanation":"Si + plus-que-parfait → conditionnel passé.","translations":{"es":{"question":"Completa: «Tu ___ le cadeau si tu avais cherché ailleurs.»","explanation":"Si + plus-que-parfait → conditionnel passé."}}},{"id":"4","question":"What do you ask for shoes?","options":["Quelle pointure ?","Quelle taille ?","Quel numéro de téléphone ?","Quelle mesure ?"],"correct":0,"explanation":"Pointure = shoe size.","translations":{"es":{"question":"¿Qué preguntas para los zapatos?","explanation":"Pointure = número de calzado."}}},{"id":"5","question":"What happens to a wool sweater washed too hot?","options":["Il grandit.","Il rétrécit.","Il brille.","Il sèche."],"correct":1,"explanation":"Rétrécir = to shrink.","translations":{"es":{"question":"¿Qué le pasa a un jersey de lana lavado demasiado caliente?","explanation":"Rétrécir = encoger."}}},{"id":"6","question":"Complete: \"Il aura vendu la robe avant que tu ___ l''acheter.\"","options":["pourras","peux","puisses","pouvais"],"correct":2,"explanation":"\"Avant que\" + subjunctive.","translations":{"es":{"question":"Completa: «Il aura vendu la robe avant que tu ___ l''acheter.»","explanation":"«Avant que» + subjuntivo."}}},{"id":"7","question":"\"Faire du lèche-vitrine\" means…","options":["to buy a lot","to clean windows","to window-shop","to lick ice cream"],"correct":2,"explanation":"Literally \"to lick the windows\"!","translations":{"es":{"question":"«Faire du lèche-vitrine» significa…","explanation":"¡Literalmente «lamer los escaparates»!","options":["comprar mucho","limpiar ventanas","mirar escaparates","chupar un helado"]}}},{"id":"8","question":"Complete: \"Ce pantalon ne lui ___ pas.\" (fit him)","options":["allera","va aller à","ira","ira à"],"correct":2,"explanation":"Aller → il ira (future).","translations":{"es":{"question":"Completa: «Ce pantalon ne lui ___ pas.» (le quedará bien)","explanation":"Aller → il ira (futuro)."}}}]}'::jsonb, 3),
  ('story', 'Ma sœur et les soldes', '{"text":"Demain, c''est le premier jour des soldes, et ma sœur Zoé va faire du shopping. Si je ne fais pas attention, elle aura dépensé tout son salaire avant midi ! Les vendeuses l''adorent… ou plutôt, elles adorent sa carte bancaire. Je crois qu''elle oublie tout quand elle entre dans un centre commercial. Elle achète beaucoup de vêtements, mais comme elle ne lit jamais les étiquettes, les couleurs déteignent et les pulls rétrécissent. Parfois, elle ne sait pas quoi choisir, alors elle prend tout. Ma grand-mère dit qu''elle était exactement pareille quand elle était jeune. Moi, demain à midi, j''irai dans deux magasins et j''achèterai peut-être un tee-shirt. Zoé, par contre, aura parcouru tout le centre commercial et aura rempli trois sacs. Quand je rentrerai, elle aura déjà essayé tous ses nouveaux vêtements devant le miroir. Le bon côté ? Quand elle se fatigue de ses vêtements, elle me les donne. Le problème, c''est qu''ils ne me vont presque jamais ! Si elle m''avait demandé ma taille, elle aurait pu m''acheter quelque chose. Bon, allons faire les soldes !","translation":"Tomorrow is the first day of the sales, and my sister Zoé is going shopping. If I''m not careful, she''ll have spent her whole salary before noon! The salespeople love her… or rather, they love her bank card. I think she forgets everything when she walks into a shopping mall. She buys a lot of clothes, but since she never reads the labels, the colors run and the sweaters shrink. Sometimes she doesn''t know what to choose, so she takes everything. My grandmother says she was exactly the same when she was young. As for me, tomorrow at noon, I''ll go to two stores and maybe buy a T-shirt. Zoé, on the other hand, will have gone through the whole mall and filled three bags. When I get home, she''ll already have tried on all her new clothes in front of the mirror. The good side? When she gets tired of her clothes, she gives them to me. The problem is that they almost never fit me! If she had asked me my size, she could have bought me something. Well, let''s go to the sales!","translations":{"es":"Mañana es el primer día de rebajas y mi hermana Zoé va a ir de compras. ¡Si no tengo cuidado, se habrá gastado todo el sueldo antes de mediodía! Las vendedoras la adoran… o más bien adoran su tarjeta bancaria. Creo que se olvida de todo cuando entra en un centro comercial. Compra mucha ropa, pero como nunca lee las etiquetas, los colores destiñen y los jerséis encogen. A veces no sabe qué elegir, así que se lo lleva todo. Mi abuela dice que ella era exactamente igual cuando era joven. Yo, mañana a mediodía, iré a dos tiendas y quizá me compre una camiseta. Zoé, en cambio, habrá recorrido todo el centro comercial y habrá llenado tres bolsas. Cuando yo vuelva, ya se habrá probado toda su ropa nueva delante del espejo. ¿Lo bueno? Cuando se cansa de su ropa, me la da. El problema es que casi nunca me queda bien. Si me hubiera preguntado mi talla, podría haberme comprado algo. Bueno, ¡vamos de rebajas!"},"highlighted_words":["soldes","elle aura dépensé","déteignent","rétrécissent","aura parcouru","aura rempli","Quand je rentrerai","aura déjà essayé","ne me vont presque jamais","Si elle m''avait demandé","aurait pu"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Quand","tu","arriveras","j''aurai","fini","mes","achats"],"translation":"When you arrive I''ll have finished my shopping","translations":{"es":"Cuando llegues, habré terminado mis compras"}},{"words":["Ce","pantalon","ne","te","va","pas"],"translation":"These trousers don''t suit you","translations":{"es":"Este pantalón no te queda bien"}},{"words":["Je","voudrais","rapporter","cette","robe"],"translation":"I would like to return this dress","translations":{"es":"Quisiera devolver este vestido"}},{"words":["Vous","faites","quelle","pointure"],"translation":"What shoe size are you","translations":{"es":"¿Qué número calza?"}},{"words":["Mon","pull","a","rétréci"],"translation":"My sweater has shrunk","translations":{"es":"Mi jersey ha encogido"}},{"words":["Allons","faire","du","lèche-vitrine"],"translation":"Let''s go window-shopping","translations":{"es":"Vamos a mirar escaparates"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Can I try it on?","translations":{"es":"¿Me lo puedo probar?"},"answer":"Je peux l''essayer ?"},{"prompt":"Do you have a smaller size?","translations":{"es":"¿Tiene una talla más pequeña?"},"answer":"Avez-vous une taille plus petite ?"},{"prompt":"It''s on sale","translations":{"es":"Está rebajado"},"answer":"C''est en solde"},{"prompt":"Where are the fitting rooms?","translations":{"es":"¿Dónde están los probadores?"},"answer":"Où sont les cabines d''essayage ?"},{"prompt":"She will have bought everything","translations":{"es":"Lo habrá comprado todo"},"answer":"Elle aura tout acheté"},{"prompt":"I do the grocery shopping on Saturdays","translations":{"es":"Hago la compra los sábados"},"answer":"Je fais les courses le samedi"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 40: Une soirée dehors
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-40', 'Une soirée dehors', '🪩', 'Una noche de salida', 40, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"sortir","translation":"to go out","translations":{"es":"salir"}},{"id":"2","word":"la soirée","translation":"the evening / party","translations":{"es":"la velada / la fiesta"}},{"id":"3","word":"la fête","translation":"the party","translations":{"es":"la fiesta"}},{"id":"4","word":"la boîte de nuit","translation":"the nightclub","translations":{"es":"la discoteca"}},{"id":"5","word":"le club","translation":"the club","translations":{"es":"el club"}},{"id":"6","word":"le bar","translation":"the bar","translations":{"es":"el bar"}},{"id":"7","word":"danser","translation":"to dance","translations":{"es":"bailar"}},{"id":"8","word":"chanter","translation":"to sing","translations":{"es":"cantar"}},{"id":"9","word":"prendre un verre","translation":"to have a drink","translations":{"es":"tomar algo"}},{"id":"10","word":"passer chercher","translation":"to pick up","translations":{"es":"pasar a recoger"}},{"id":"11","word":"le taxi","translation":"the taxi","translations":{"es":"el taxi"}},{"id":"12","word":"le chauffeur","translation":"the driver","translations":{"es":"el conductor"}},{"id":"13","word":"la limousine","translation":"the limousine","translations":{"es":"la limusina"}},{"id":"14","word":"inviter","translation":"to invite","translations":{"es":"invitar"}},{"id":"15","word":"partager","translation":"to share","translations":{"es":"compartir"}},{"id":"16","word":"parier","translation":"to bet","translations":{"es":"apostar"}},{"id":"17","word":"prêter","translation":"to lend","translations":{"es":"prestar"}},{"id":"18","word":"apprendre","translation":"to learn / teach","translations":{"es":"aprender / enseñar"}},{"id":"19","word":"enseigner","translation":"to teach","translations":{"es":"enseñar"}},{"id":"20","word":"renoncer","translation":"to give up","translations":{"es":"renunciar"}},{"id":"21","word":"supporter","translation":"to stand / put up with","translations":{"es":"soportar"}},{"id":"22","word":"casser","translation":"to break","translations":{"es":"romper"}},{"id":"23","word":"briller","translation":"to shine","translations":{"es":"brillar"}},{"id":"24","word":"libre","translation":"free","translations":{"es":"libre"}},{"id":"25","word":"avoir honte","translation":"to be ashamed","translations":{"es":"tener vergüenza"}},{"id":"26","word":"s''ennuyer","translation":"to be bored","translations":{"es":"aburrirse"}},{"id":"27","word":"se retrouver","translation":"to meet up","translations":{"es":"quedar / reunirse"}},{"id":"28","word":"le bal de fin d''année","translation":"the prom","translations":{"es":"el baile de fin de curso"}},{"id":"29","word":"puni / punie","translation":"grounded / punished","translations":{"es":"castigado / castigada"}},{"id":"30","word":"rentrer tard","translation":"to come home late","translations":{"es":"volver tarde"}},{"id":"31","word":"gâcher","translation":"to spoil","translations":{"es":"estropear"}}],"grammar":[{"structure":"aller (imparfait) + infinitif","example":"J''allais sortir quand elle est tombée malade.","en":"\"Was going to\" (plan that didn''t happen)","es":"«Iba a» (plan que no se cumplió)"},{"structure":"… mais + passé composé","example":"Elle allait devenir chanteuse, mais elle a eu un accident.","en":"Interrupted intentions","es":"Intenciones interrumpidas"},{"structure":"passé simple (récit)","example":"Sa voix sonna au bout du fil et elle m''invita.","en":"Literary past","es":"Pasado literario"},{"structure":"se rendre compte que","example":"Je me suis rendu compte que j''avais besoin d''argent.","en":"\"To realize that\"","es":"«Darse cuenta de que»"},{"structure":"plus-que-parfait","example":"Mon ami avait déjà prévu qu''on irait en boîte.","en":"Past perfect","es":"Pluscuamperfecto"},{"structure":"si + imparfait (passé)","example":"Ils allaient casser la porte si le club n''ouvrait pas.","en":"Condition in a past context","es":"Condición en contexto pasado"},{"structure":"s''en ficher (familier)","example":"Elle s''en fiche de tout ça.","en":"\"Not to care\" (informal)","es":"«Importarle un pepino» (coloquial)"}],"tips":[{"en":"\"J''allais + infinitive\" describes something you were about to do or planned to do in the past — often followed by \"mais…\" or \"quand…\".","es":"«J''allais + infinitivo» describe algo que ibas a hacer o tenías planeado en el pasado; suele ir seguido de «mais…» o «quand…»."},{"en":"Night out vocabulary: \"sortir en boîte\" (to go clubbing), \"le videur\" (bouncer), \"prendre un verre\" (to have a drink), \"rentrer tard\" (to come home late).","es":"Vocabulario de salida: «sortir en boîte» (ir de discoteca), «le videur» (portero), «prendre un verre» (tomar algo), «rentrer tard» (volver tarde)."},{"en":"\"S''en ficher\" / \"s''en moquer\" = not to care (informal but polite enough). \"Je m''en fiche !\" = I don''t care!","es":"«S''en ficher» / «s''en moquer» = importar poco (coloquial pero aceptable). «Je m''en fiche !» = ¡Me da igual!"},{"en":"\"Passer prendre / chercher quelqu''un\" = to pick someone up.","es":"«Passer prendre / chercher quelqu''un» = pasar a recoger a alguien."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"On allait sortir quand elle est tombée malade.","translation":"We were going to go out when she fell ill.","translations":{"es":"Íbamos a salir cuando se puso enferma."}},{"phrase":"J''allais passer te chercher.","translation":"I was going to pick you up.","translations":{"es":"Iba a pasar a buscarte."}},{"phrase":"Ils allaient l''inviter en boîte, mais ils n''avaient pas assez d''argent.","translation":"They were going to invite her to a club, but they didn''t have enough money.","translations":{"es":"Iban a invitarla a la discoteca, pero no tenían suficiente dinero."}},{"phrase":"Elle allait devenir chanteuse, mais elle a eu un accident.","translation":"She was going to become a singer, but she had an accident.","translations":{"es":"Iba a ser cantante, pero tuvo un accidente."}},{"phrase":"J''allais te prêter la voiture pour la fête, mais maintenant tu es punie !","translation":"I was going to lend you the car for the party, but now you''re grounded!","translations":{"es":"Iba a prestarte el coche para la fiesta, ¡pero ahora estás castigada!"}},{"phrase":"Le chauffeur allait nous ramener, mais ma copine a décidé d''aller danser.","translation":"The driver was going to take us home, but my girlfriend decided to go dancing.","translations":{"es":"El conductor iba a llevarnos a casa, pero mi novia decidió ir a bailar."}},{"phrase":"Il allait chanter ce soir, mais il a mal à la gorge.","translation":"He was going to sing tonight, but he has a sore throat.","translations":{"es":"Iba a cantar esta noche, pero le duele la garganta."}},{"phrase":"Allez, appelle un taxi !","translation":"Come on, call a taxi!","translations":{"es":"¡Venga, llama a un taxi!"}},{"phrase":"J''allais abandonner, mais je me suis rendu compte que j''avais besoin de ce travail.","translation":"I was going to give up, but I realized I needed this job.","translations":{"es":"Iba a rendirme, pero me di cuenta de que necesitaba este trabajo."}},{"phrase":"Tu allais danser ce soir ? — Oui, mais je suis trop fatiguée.","translation":"Were you going to go dancing tonight? — Yes, but I''m too tired.","translations":{"es":"¿Ibas a ir a bailar esta noche? — Sí, pero estoy demasiado cansada."}},{"phrase":"Où est-ce qu''ils allaient se retrouver ? — À minuit, dans un bar du centre.","translation":"Where were they going to meet? — At midnight, in a bar downtown.","translations":{"es":"¿Dónde iban a quedar? — A medianoche, en un bar del centro."}},{"phrase":"On n''allait pas rester dans ce bar ? — Non, je m''y ennuyais.","translation":"Weren''t we going to stay in that bar? — No, I was bored there.","translations":{"es":"¿No íbamos a quedarnos en ese bar? — No, me aburría allí."}},{"phrase":"Tu n''as pas eu honte d''aller seul au bal ? — Si, mais je me suis bien amusé.","translation":"Weren''t you embarrassed to go to the prom alone? — Yes, but I had a great time.","translations":{"es":"¿No te dio vergüenza ir solo al baile? — Sí, pero me lo pasé muy bien."}},{"phrase":"Elle s''en fiche de tout ça.","translation":"She doesn''t care about all that.","translations":{"es":"Le da igual todo eso."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"\"J''allais sortir quand il a appelé.\" Meaning?","options":["I will go out when he calls.","I went out when he called.","I had gone out when he called.","I was about to go out when he called."],"correct":3,"explanation":"Imparfait of \"aller\" + infinitive = was going to.","translations":{"es":{"question":"«J''allais sortir quand il a appelé.» ¿Significado?","explanation":"Imperfecto de «aller» + infinitivo = iba a.","options":["Saldré cuando llame.","Salí cuando llamó.","Había salido cuando llamó.","Iba a salir cuando llamó."]}}},{"id":"2","question":"Complete: \"Elle ___ chanter, mais elle a perdu sa voix.\"","options":["est allée","ira","va","allait"],"correct":3,"explanation":"Intention in the past that didn''t happen.","translations":{"es":{"question":"Completa: «Elle ___ chanter, mais elle a perdu sa voix.»","explanation":"Intención pasada que no se cumplió."}}},{"id":"3","question":"Complete: \"Je me suis rendu compte que j''___ mes clés.\"","options":["oublie","oublierai","ai oublié","avais oublié"],"correct":3,"explanation":"Plus-que-parfait: before the moment of realizing.","translations":{"es":{"question":"Completa: «Je me suis rendu compte que j''___ mes clés.»","explanation":"Plus-que-parfait: antes del momento de darse cuenta."}}},{"id":"4","question":"\"Sortir en boîte\" means…","options":["to take a taxi","to go shopping","to go out of a box","to go clubbing"],"correct":3,"explanation":"Une boîte (de nuit) = a nightclub.","translations":{"es":{"question":"«Sortir en boîte» significa…","explanation":"Une boîte (de nuit) = una discoteca.","options":["tomar un taxi","ir de compras","salir de una caja","ir de discoteca"]}}},{"id":"5","question":"\"Je passe te chercher à huit heures.\" Meaning?","options":["I''ll pass by you at eight.","I''ll wait for you at eight.","I''ll look for you at eight.","I''ll pick you up at eight."],"correct":3,"explanation":"Passer chercher = to pick up.","translations":{"es":{"question":"«Je passe te chercher à huit heures.» ¿Significado?","explanation":"Passer chercher = pasar a recoger.","options":["Pasaré junto a ti a las ocho.","Te esperaré a las ocho.","Te buscaré a las ocho.","Paso a buscarte a las ocho."]}}},{"id":"6","question":"Which sentence uses the passé simple?","options":["Elle allait m''inviter.","Elle m''a invité.","Elle m''invitait.","Elle m''invita."],"correct":3,"explanation":"Inviter → elle invita.","translations":{"es":{"question":"¿Qué frase usa el passé simple?","explanation":"Inviter → elle invita."}}},{"id":"7","question":"\"Je m''en fiche.\" Meaning?","options":["I''m sorry.","I''m leaving.","I''m afraid.","I don''t care."],"correct":3,"explanation":"Informal but not vulgar.","translations":{"es":{"question":"«Je m''en fiche.» ¿Significado?","explanation":"Coloquial pero no vulgar.","options":["Lo siento.","Me voy.","Tengo miedo.","Me da igual."]}}},{"id":"8","question":"Complete: \"Tu n''as pas eu honte ? — ___, un peu.\"","options":["Oui","Pas","Non","Si"],"correct":3,"explanation":"\"Si\" contradicts a negative question.","translations":{"es":{"question":"Completa: «Tu n''as pas eu honte ? — ___, un peu.»","explanation":"«Si» contradice una pregunta negativa."}}}]}'::jsonb, 3),
  ('story', 'La soirée qui a mal commencé', '{"text":"J''ai rencontré Camille il y a un mois au cours de théâtre, et j''avais très envie de l''inviter. Mais je ne savais ni quoi lui dire ni où l''emmener. Samedi dernier, j''allais sortir avec des copains dans un bar près de chez moi. J''allais monter dans le bus quand mon téléphone sonna : c''était elle ! Elle m''invita à l''anniversaire d''une amie. J''allais mettre une chemise élégante, mais je me suis rappelé qu''elle s''en fiche de ce genre de choses. Alors, j''ai mis un jean et un pull, et je suis passé la chercher. La fête était géniale, mais vers minuit, les voisins se plaignirent du bruit. Tout le monde pensait que la soirée allait se terminer. Heureusement, une amie de Camille avait déjà réservé une table dans une boîte de nuit du centre. Nous allions y aller tous les deux, et finalement, tout le groupe nous a suivis ! Le seul problème : en descendant les escaliers, je suis tombé et je me suis tordu la cheville. J''ai gâché la soirée, et j''ai pensé qu''elle n''allait plus jamais me parler. Mais cette nuit-là, elle resta avec moi aux urgences et elle rit avec moi de toute cette histoire. Aujourd''hui, c''est ma copine.","translation":"I met Camille a month ago at drama class, and I really wanted to ask her out. But I knew neither what to say nor where to take her. Last Saturday, I was going to go out with some friends to a bar near my place. I was about to get on the bus when my phone rang: it was her! She invited me to a friend''s birthday party. I was going to wear a smart shirt, but I remembered she doesn''t care about that kind of thing. So I put on jeans and a sweater, and went to pick her up. The party was great, but around midnight, the neighbors complained about the noise. Everyone thought the evening was going to end. Fortunately, a friend of Camille''s had already booked a table at a club downtown. The two of us were going to go, and in the end the whole group followed us! The only problem: going down the stairs, I fell and twisted my ankle. I ruined the evening, and I thought she would never speak to me again. But that night, she stayed with me at the ER and laughed with me about the whole thing. Today, she''s my girlfriend.","translations":{"es":"Conocí a Camille hace un mes en la clase de teatro y tenía muchas ganas de invitarla a salir. Pero no sabía ni qué decirle ni adónde llevarla. El sábado pasado iba a salir con unos amigos a un bar cerca de mi casa. Iba a subirme al autobús cuando sonó mi teléfono: ¡era ella! Me invitó al cumpleaños de una amiga. Iba a ponerme una camisa elegante, pero me acordé de que a ella le dan igual esas cosas. Así que me puse un vaquero y un jersey y pasé a buscarla. La fiesta estuvo genial, pero hacia medianoche los vecinos se quejaron del ruido. Todo el mundo pensaba que la noche se iba a acabar. Por suerte, una amiga de Camille ya había reservado una mesa en una discoteca del centro. Íbamos a ir los dos solos y, al final, ¡nos siguió todo el grupo! El único problema: bajando las escaleras, me caí y me torcí el tobillo. Estropeé la noche y pensé que no volvería a hablarme nunca. Pero esa noche se quedó conmigo en urgencias y se rio conmigo de toda la historia. Hoy es mi novia."},"highlighted_words":["j''allais sortir","J''allais monter","sonna","invita","J''allais mettre","s''en fiche","se plaignirent","allait se terminer","avait déjà réservé","Nous allions y aller","J''ai gâché","n''allait plus jamais","resta"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["J''allais","sortir","quand","tu","as","appelé"],"translation":"I was going to go out when you called","translations":{"es":"Iba a salir cuando llamaste"}},{"words":["Elle","allait","chanter","mais","elle","était","malade"],"translation":"She was going to sing but she was ill","translations":{"es":"Iba a cantar, pero estaba enferma"}},{"words":["Je","passe","te","chercher","à","huit","heures"],"translation":"I''ll pick you up at eight","translations":{"es":"Paso a buscarte a las ocho"}},{"words":["On","va","sortir","en","boîte"],"translation":"We''re going clubbing","translations":{"es":"Vamos a ir de discoteca"}},{"words":["Je","me","suis","rendu","compte","que","c''était","tard"],"translation":"I realized it was late","translations":{"es":"Me di cuenta de que era tarde"}},{"words":["Elle","s''en","fiche"],"translation":"She doesn''t care","translations":{"es":"Le da igual"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Call a taxi","translations":{"es":"Llama a un taxi"},"answer":"Appelle un taxi"},{"prompt":"I was going to invite you","translations":{"es":"Iba a invitarte"},"answer":"J''allais t''inviter"},{"prompt":"Shall we have a drink?","translations":{"es":"¿Tomamos algo?"},"answer":"On prend un verre ?"},{"prompt":"I was bored","translations":{"es":"Me aburría"},"answer":"Je m''ennuyais"},{"prompt":"They were going to dance","translations":{"es":"Iban a bailar"},"answer":"Ils allaient danser"},{"prompt":"I came home late","translations":{"es":"Volví tarde"},"answer":"Je suis rentré tard"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 41: Trouver un logement
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-41', 'Trouver un logement', '🔑', 'Encontrar un lugar para vivir', 41, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le logement","translation":"housing / accommodation","translations":{"es":"la vivienda"}},{"id":"2","word":"l''appartement","translation":"the apartment","translations":{"es":"el apartamento"}},{"id":"3","word":"le studio","translation":"the studio","translations":{"es":"el estudio"}},{"id":"4","word":"l''immeuble","translation":"the apartment building","translations":{"es":"el edificio"}},{"id":"5","word":"la résidence","translation":"the residential complex","translations":{"es":"el complejo residencial"}},{"id":"6","word":"la petite annonce","translation":"the classified ad","translations":{"es":"el anuncio clasificado"}},{"id":"7","word":"l''agence immobilière","translation":"the real estate agency","translations":{"es":"la agencia inmobiliaria"}},{"id":"8","word":"l''agent immobilier","translation":"the real estate agent","translations":{"es":"el agente inmobiliario"}},{"id":"9","word":"le propriétaire","translation":"the landlord / owner","translations":{"es":"el propietario / el casero"}},{"id":"10","word":"le locataire","translation":"the tenant","translations":{"es":"el inquilino"}},{"id":"11","word":"le loyer","translation":"the rent","translations":{"es":"el alquiler"}},{"id":"12","word":"les charges","translation":"utilities / service charges","translations":{"es":"los gastos (comunidad, suministros)"}},{"id":"13","word":"compris / comprise","translation":"included","translations":{"es":"incluido / incluida"}},{"id":"14","word":"la caution","translation":"the deposit","translations":{"es":"la fianza"}},{"id":"15","word":"le bail","translation":"the lease","translations":{"es":"el contrato de alquiler"}},{"id":"16","word":"meublé / meublée","translation":"furnished","translations":{"es":"amueblado / amueblada"}},{"id":"17","word":"la moquette","translation":"the carpet","translations":{"es":"la moqueta"}},{"id":"18","word":"l''électricité","translation":"electricity","translations":{"es":"la electricidad"}},{"id":"19","word":"le gaz","translation":"gas","translations":{"es":"el gas"}},{"id":"20","word":"le voisin / la voisine","translation":"the neighbor","translations":{"es":"el vecino / la vecina"}},{"id":"21","word":"le quartier","translation":"the neighborhood","translations":{"es":"el barrio"}},{"id":"22","word":"proche","translation":"near","translations":{"es":"cercano"}},{"id":"23","word":"bruyant / bruyante","translation":"noisy","translations":{"es":"ruidoso / ruidosa"}},{"id":"24","word":"calme","translation":"quiet","translations":{"es":"tranquilo"}},{"id":"25","word":"déménager","translation":"to move (house)","translations":{"es":"mudarse"}},{"id":"26","word":"emménager","translation":"to move in","translations":{"es":"instalarse"}},{"id":"27","word":"visiter","translation":"to view (a flat)","translations":{"es":"visitar"}},{"id":"28","word":"louer","translation":"to rent","translations":{"es":"alquilar"}},{"id":"29","word":"démolir","translation":"to demolish","translations":{"es":"derribar"}},{"id":"30","word":"exigeant / exigeante","translation":"demanding","translations":{"es":"exigente"}},{"id":"31","word":"la poubelle","translation":"the trash can","translations":{"es":"el cubo de basura"}}],"grammar":[{"structure":"n''est-ce pas ? (tous les temps)","example":"Tu habites en ville, n''est-ce pas ? / Ils vont déménager, n''est-ce pas ? / Tu as dû verser une caution, n''est-ce pas ?","en":"Tag questions in every tense","es":"Preguntas de confirmación en todos los tiempos"},{"structure":"être en train de (passé)","example":"Elle était en train de chercher un appartement depuis un mois.","en":"Ongoing past action","es":"Acción en curso en el pasado"},{"structure":"depuis + présent","example":"Elle le cherche depuis longtemps.","en":"Ongoing since","es":"Desde hace"},{"structure":"pronoms démonstratifs","example":"Celui-là est bien. / Qu''est-ce que tu penses de celui-ci ?","en":"celui-ci / celui-là","es":"Este / aquel"},{"structure":"plus-que-parfait","example":"Je l''avais vue, mais l''endroit ne m''a pas plu.","en":"Past perfect","es":"Pluscuamperfecto"},{"structure":"j''ai bien peur que","example":"Ils vont démolir l''immeuble ? — J''ai bien peur que oui.","en":"\"I''m afraid so\"","es":"«Me temo que sí»"},{"structure":"comparatif","example":"Tu es plus exigeant que moi.","en":"Comparatives","es":"Comparativos"},{"structure":"pronom « en » + quantité","example":"Il y en a quatre. / Je n''en ai pas encore trouvé un.","en":"\"en\" with numbers","es":"«en» con cantidades"}],"tips":[{"en":"Housing: \"le loyer\" (rent), \"les charges\" (utilities/fees), \"charges comprises\" (utilities included), \"la caution / le dépôt de garantie\" (deposit), \"meublé\" (furnished).","es":"Vivienda: «le loyer» (alquiler), «les charges» (gastos de comunidad / suministros), «charges comprises» (gastos incluidos), «la caution / le dépôt de garantie» (fianza), «meublé» (amueblado)."},{"en":"In French ads: \"T2 / F2\" = 2 main rooms (living room + 1 bedroom); \"RDC\" = ground floor; \"m²\" = square meters.","es":"En los anuncios: «T2 / F2» = 2 piezas principales (salón + 1 dormitorio); «RDC» = planta baja; «m²» = metros cuadrados."},{"en":"\"N''est-ce pas ?\" works with any tense and person; in speech people often just say \"… non ?\" or \"… hein ?\".","es":"«N''est-ce pas ?» funciona con cualquier tiempo y persona; al hablar se dice a menudo «… non ?» o «… hein ?»."},{"en":"\"Le propriétaire\" = landlord; \"le locataire\" = tenant; \"l''agent immobilier\" = real estate agent.","es":"«Le propriétaire» = el casero; «le locataire» = el inquilino; «l''agent immobilier» = el agente inmobiliario."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Tu habites dans un appartement, n''est-ce pas ? — Oui, au centre-ville.","translation":"You live in an apartment, don''t you? — Yes, downtown.","translations":{"es":"Vives en un apartamento, ¿verdad? — Sí, en el centro."}},{"phrase":"Elle cherche une maison, n''est-ce pas ? — Oui, elle la cherche depuis longtemps.","translation":"She''s looking for a house, isn''t she? — Yes, she''s been looking for a long time.","translations":{"es":"Está buscando una casa, ¿verdad? — Sí, la busca desde hace tiempo."}},{"phrase":"Cet appartement est meublé, n''est-ce pas ? — Oui, c''est pour ça qu''il est bien.","translation":"This apartment is furnished, isn''t it? — Yes, that''s why it''s good.","translations":{"es":"Este apartamento está amueblado, ¿verdad? — Sí, por eso está bien."}},{"phrase":"Tu n''as pas vu l''annonce ? — Si, je l''avais vue, mais l''endroit ne m''a pas plu.","translation":"Didn''t you see the ad? — Yes, I had seen it, but I didn''t like the place.","translations":{"es":"¿No viste el anuncio? — Sí, lo había visto, pero el sitio no me gustó."}},{"phrase":"Tu as habité à Montpellier, n''est-ce pas ? — Non, je n''ai jamais habité là-bas.","translation":"You lived in Montpellier, didn''t you? — No, I''ve never lived there.","translations":{"es":"Viviste en Montpellier, ¿verdad? — No, nunca he vivido allí."}},{"phrase":"Ils vont déménager le mois prochain, n''est-ce pas ? — Non, je crois que c''est demain !","translation":"They''re going to move next month, aren''t they? — No, I think it''s tomorrow!","translations":{"es":"Se van a mudar el mes que viene, ¿verdad? — ¡No, creo que es mañana!"}},{"phrase":"Les charges sont comprises dans le loyer, n''est-ce pas ? — Non. — Alors c''est trop cher.","translation":"Utilities are included in the rent, aren''t they? — No. — Then it''s too expensive.","translations":{"es":"Los gastos están incluidos en el alquiler, ¿verdad? — No. — Entonces es demasiado caro."}},{"phrase":"Votre immeuble va bientôt être démoli, n''est-ce pas ? — J''ai bien peur que oui.","translation":"Your building will soon be demolished, won''t it? — I''m afraid so.","translations":{"es":"Su edificio va a ser derribado pronto, ¿verdad? — Me temo que sí."}},{"phrase":"Tu as dû verser une caution, n''est-ce pas ? — Oui, deux mois de loyer.","translation":"You had to pay a deposit, didn''t you? — Yes, two months'' rent.","translations":{"es":"Tuviste que dejar una fianza, ¿verdad? — Sí, dos meses de alquiler."}},{"phrase":"Son appartement a trois salles de bains, n''est-ce pas ? — Je crois qu''il y en a quatre !","translation":"His apartment has three bathrooms, doesn''t it? — I think there are four!","translations":{"es":"Su apartamento tiene tres baños, ¿verdad? — ¡Creo que tiene cuatro!"}},{"phrase":"La poubelle est pleine, n''est-ce pas ? — Non, je viens de la sortir.","translation":"The trash is full, isn''t it? — No, I just took it out.","translations":{"es":"La basura está llena, ¿verdad? — No, acabo de sacarla."}},{"phrase":"Ils allaient acheter une maison, n''est-ce pas ? — Oui, mais ils ont changé d''avis.","translation":"They were going to buy a house, weren''t they? — Yes, but they changed their minds.","translations":{"es":"Iban a comprar una casa, ¿verdad? — Sí, pero cambiaron de opinión."}},{"phrase":"Celui-là me plaît. Il n''a qu''une salle de bains, mais le reste est parfait.","translation":"I like that one. It only has one bathroom, but the rest is perfect.","translations":{"es":"Ese me gusta. Solo tiene un baño, pero el resto es perfecto."}},{"phrase":"Mon voisin est de mauvaise humeur à cause de la fête de vendredi, n''est-ce pas ? — Oui, je crois.","translation":"My neighbor is in a bad mood because of Friday''s party, isn''t he? — Yes, I think so.","translations":{"es":"Mi vecino está de mal humor por la fiesta del viernes, ¿verdad? — Sí, creo que sí."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"What is \"le loyer\"?","options":["the rent","the deposit","the landlord","the lawyer"],"correct":0,"explanation":"Le loyer = monthly rent.","translations":{"es":{"question":"¿Qué es «le loyer»?","explanation":"Le loyer = alquiler mensual.","options":["el alquiler","la fianza","el casero","el abogado"]}}},{"id":"2","question":"\"Charges comprises\" means…","options":["extra charges","utilities included","no charges allowed","charges understood"],"correct":1,"explanation":"Charges = utilities / service fees.","translations":{"es":{"question":"«Charges comprises» significa…","explanation":"Charges = gastos de suministros o comunidad.","options":["cargos adicionales","gastos incluidos","sin cargos","cargos entendidos"]}}},{"id":"3","question":"Which tag question is correct?","options":["Tu as déménagé, n''est-ce pas ?","Tu as déménagé, pas vrai n''est ?","Tu as déménagé, est-ce pas ?","Tu as déménagé, n''as-tu pas ?"],"correct":0,"explanation":"\"N''est-ce pas\" never changes.","translations":{"es":{"question":"¿Qué pregunta de confirmación es correcta?","explanation":"«N''est-ce pas» no cambia nunca."}}},{"id":"4","question":"Complete: \"Elle cherche un appartement ___ un mois.\"","options":["depuis","dans","il y a","pendant"],"correct":0,"explanation":"Depuis + present: still looking.","translations":{"es":{"question":"Completa: «Elle cherche un appartement ___ un mois.»","explanation":"Depuis + presente: sigue buscando."}}},{"id":"5","question":"\"Il y en a quatre.\" What does \"en\" replace?","options":["an adjective","a noun with a quantity (e.g., bathrooms)","a person","a place"],"correct":1,"explanation":"\"En\" + number replaces a counted noun.","translations":{"es":{"question":"«Il y en a quatre.» ¿Qué sustituye «en»?","explanation":"«En» + número sustituye un sustantivo contado.","options":["un adjetivo","un sustantivo con cantidad (p. ej., baños)","una persona","un lugar"]}}},{"id":"6","question":"Who pays the rent?","options":["le voisin","le locataire","l''agent immobilier","le propriétaire"],"correct":1,"explanation":"Locataire = tenant; propriétaire = landlord.","translations":{"es":{"question":"¿Quién paga el alquiler?","explanation":"Locataire = inquilino; propriétaire = casero."}}},{"id":"7","question":"\"J''ai bien peur que oui.\" Meaning?","options":["I''m afraid so.","I hope so.","I''m afraid not.","I''m very scared."],"correct":0,"explanation":"Opposite: \"J''ai bien peur que non.\"","translations":{"es":{"question":"«J''ai bien peur que oui.» ¿Significado?","explanation":"Lo contrario: «J''ai bien peur que non.»","options":["Me temo que sí.","Eso espero.","Me temo que no.","Tengo mucho miedo."]}}},{"id":"8","question":"Complete: \"Tu es plus exigeant ___ moi.\"","options":["à","comme","que","de"],"correct":2,"explanation":"Plus … que.","translations":{"es":{"question":"Completa: «Tu es plus exigeant ___ moi.»","explanation":"Plus … que."}}}]}'::jsonb, 3),
  ('story', 'L''appartement idéal', '{"text":"Ça faisait un mois que Yanis était en train de chercher un appartement à Lyon, et il n''avait rien trouvé. Un jour, il a croisé son amie Nadia au café. « Tu cherches toujours un logement, n''est-ce pas ? » « Oui, je suis encore en train de chercher, parce que je n''en ai pas trouvé un avec tout ce que je veux. » « Et qu''est-ce que tu veux, exactement ? » « Deux chambres, deux salles de bains, charges comprises, meublé, pas trop de caution… et des voisins calmes ! » Nadia a ri : « Tu veux tout ! Un appartement comme ça, c''est très difficile à trouver. Mais j''ai vu des petites annonces qui pourraient t''intéresser. Regarde. » « Celui-ci a l''air bien, n''est-ce pas ? » « Oui, mais il est en plein centre, c''est un peu bruyant. » « Et celui-là ? Le quartier est plus calme, n''est-ce pas ? » « Oui, mais on dit qu''ils vont bientôt démolir l''immeuble. — J''ai bien peur que oui. » Finalement, Nadia en montre un troisième : « Il n''a qu''une salle de bains, mais tout le reste est parfait. » « Bon… il est un peu petit pour moi, non ? » « Tu es vraiment plus exigeant que moi ! Moi, je l''aurais pris tout de suite. » Le lendemain, Yanis a signé le bail.","translation":"Yanis had been looking for an apartment in Lyon for a month, and he hadn''t found anything. One day, he ran into his friend Nadia at a café. “You''re still looking for a place, aren''t you?” “Yes, I''m still looking, because I haven''t found one with everything I want.” “And what do you want, exactly?” “Two bedrooms, two bathrooms, utilities included, furnished, not too big a deposit… and quiet neighbors!” Nadia laughed: “You want everything! An apartment like that is very hard to find. But I''ve seen some ads that might interest you. Look.” “This one looks good, doesn''t it?” “Yes, but it''s right in the center, it''s a bit noisy.” “And that one? The neighborhood is quieter, isn''t it?” “Yes, but they say they''re going to demolish the building soon. — I''m afraid so.” Finally, Nadia shows him a third one: “It only has one bathroom, but everything else is perfect.” “Well… it''s a bit small for me, isn''t it?” “You''re really more demanding than I am! I would have taken it right away.” The next day, Yanis signed the lease.","translations":{"es":"Yanis llevaba un mes buscando apartamento en Lyon y no había encontrado nada. Un día se cruzó con su amiga Nadia en el café. «Sigues buscando piso, ¿verdad?» «Sí, todavía estoy buscando, porque no he encontrado ninguno con todo lo que quiero.» «¿Y qué quieres exactamente?» «Dos dormitorios, dos baños, gastos incluidos, amueblado, sin mucha fianza… ¡y vecinos tranquilos!» Nadia se rio: «¡Lo quieres todo! Un piso así es muy difícil de encontrar. Pero he visto unos anuncios que podrían interesarte. Mira.» «Este tiene buena pinta, ¿verdad?» «Sí, pero está en pleno centro, es un poco ruidoso.» «¿Y aquel? El barrio es más tranquilo, ¿verdad?» «Sí, pero dicen que pronto van a derribar el edificio. — Me temo que sí.» Al final, Nadia le enseña un tercero: «Solo tiene un baño, pero todo lo demás es perfecto.» «Bueno… es un poco pequeño para mí, ¿no?» «¡De verdad eres más exigente que yo! Yo lo habría alquilado enseguida.» Al día siguiente, Yanis firmó el contrato."},"highlighted_words":["était en train de chercher","n''est-ce pas","je suis encore en train de chercher","je n''en ai pas trouvé un","charges comprises","meublé","caution","petites annonces","Celui-ci","celui-là","J''ai bien peur que oui","plus exigeant que moi","bail"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Tu","habites","en","ville","n''est-ce","pas"],"translation":"You live in town don''t you","translations":{"es":"Vives en la ciudad, ¿verdad?"}},{"words":["Les","charges","sont","comprises"],"translation":"Utilities are included","translations":{"es":"Los gastos están incluidos"}},{"words":["Elle","cherche","un","appartement","depuis","un","mois"],"translation":"She''s been looking for an apartment for a month","translations":{"es":"Busca piso desde hace un mes"}},{"words":["Celui-là","est","trop","petit"],"translation":"That one is too small","translations":{"es":"Aquel es demasiado pequeño"}},{"words":["J''ai","bien","peur","que","oui"],"translation":"I''m afraid so","translations":{"es":"Me temo que sí"}},{"words":["Ils","vont","déménager","demain"],"translation":"They''re going to move tomorrow","translations":{"es":"Se van a mudar mañana"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"The apartment is furnished","translations":{"es":"El apartamento está amueblado"},"answer":"L''appartement est meublé"},{"prompt":"How much is the rent?","translations":{"es":"¿Cuánto es el alquiler?"},"answer":"Combien est le loyer ?"},{"prompt":"I''m looking for a studio","translations":{"es":"Busco un estudio"},"answer":"Je cherche un studio"},{"prompt":"My neighbors are noisy","translations":{"es":"Mis vecinos son ruidosos"},"answer":"Mes voisins sont bruyants"},{"prompt":"We have moved","translations":{"es":"Nos hemos mudado"},"answer":"Nous avons déménagé"},{"prompt":"There are two (of them)","translations":{"es":"Hay dos"},"answer":"Il y en a deux"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 42: À la laverie
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-42', 'À la laverie', '🧺', 'En la lavandería', 42, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la laverie","translation":"the laundromat","translations":{"es":"la lavandería"}},{"id":"2","word":"le pressing","translation":"the dry cleaner","translations":{"es":"la tintorería"}},{"id":"3","word":"le linge","translation":"laundry / linen","translations":{"es":"la ropa (para lavar)"}},{"id":"4","word":"faire la lessive","translation":"to do the laundry","translations":{"es":"hacer la colada"}},{"id":"5","word":"la lessive","translation":"detergent","translations":{"es":"el detergente"}},{"id":"6","word":"l''eau de Javel","translation":"bleach","translations":{"es":"la lejía"}},{"id":"7","word":"le savon","translation":"soap","translations":{"es":"el jabón"}},{"id":"8","word":"la machine à laver","translation":"the washing machine","translations":{"es":"la lavadora"}},{"id":"9","word":"le sèche-linge","translation":"the dryer","translations":{"es":"la secadora"}},{"id":"10","word":"le lavage","translation":"the wash","translations":{"es":"el lavado"}},{"id":"11","word":"le cycle","translation":"the cycle","translations":{"es":"el ciclo"}},{"id":"12","word":"le linge blanc / de couleur","translation":"whites / colors","translations":{"es":"la ropa blanca / de color"}},{"id":"13","word":"laver","translation":"to wash","translations":{"es":"lavar"}},{"id":"14","word":"sécher","translation":"to dry","translations":{"es":"secar"}},{"id":"15","word":"repasser","translation":"to iron","translations":{"es":"planchar"}},{"id":"16","word":"plier","translation":"to fold","translations":{"es":"doblar"}},{"id":"17","word":"accumuler","translation":"to pile up","translations":{"es":"acumular"}},{"id":"18","word":"la monnaie","translation":"change (coins)","translations":{"es":"el cambio / las monedas"}},{"id":"19","word":"la pièce","translation":"the coin","translations":{"es":"la moneda"}},{"id":"20","word":"le billet","translation":"the banknote","translations":{"es":"el billete"}},{"id":"21","word":"la fente","translation":"the coin slot","translations":{"es":"la ranura"}},{"id":"22","word":"rembourser","translation":"to pay back","translations":{"es":"devolver (dinero)"}},{"id":"23","word":"prêter","translation":"to lend","translations":{"es":"prestar"}},{"id":"24","word":"appartenir à","translation":"to belong to","translations":{"es":"pertenecer a"}},{"id":"25","word":"tomber en panne","translation":"to break down","translations":{"es":"averiarse"}},{"id":"26","word":"le pourboire","translation":"the tip","translations":{"es":"la propina"}},{"id":"27","word":"de mauvaise humeur","translation":"in a bad mood","translations":{"es":"de mal humor"}},{"id":"28","word":"s''habituer à","translation":"to get used to","translations":{"es":"acostumbrarse a"}}],"grammar":[{"structure":"pronoms relatifs qui / que","example":"Le linge qui est dans cette machine est à moi. / La fille que tu as invitée…","en":"Relative pronouns (subject / object)","es":"Pronombres relativos (sujeto / objeto)"},{"structure":"pronom relatif où","example":"La laverie où je lave mon linge coûte peu.","en":"Relative \"where\"","es":"Relativo «donde»"},{"structure":"celui / celle / ceux qui / que","example":"La meilleure laverie est celle qui est en face. / Ce sont ceux qui t''ont pris la monnaie.","en":"Demonstrative + relative","es":"Demostrativo + relativo"},{"structure":"futur simple (devoir, avoir)","example":"Tu auras besoin de monnaie. / Tu devras laver ton linge.","en":"Simple future","es":"Futuro simple"},{"structure":"éviter que + subjonctif","example":"Une tasse de lessive, pour éviter que la machine tombe en panne.","en":"\"To avoid\" + subjunctive","es":"«Evitar que» + subjuntivo"},{"structure":"qu''est-ce que tu veux que je fasse ?","example":"Qu''est-ce que tu veux que je fasse ?","en":"Vouloir que + subjunctive","es":"Querer que + subjuntivo"},{"structure":"avoir l''habitude de","example":"La laverie où ma mère avait l''habitude d''aller.","en":"\"To be used to\"","es":"«Soler / tener la costumbre de»"}],"tips":[{"en":"\"Qui\" is the subject of the next verb; \"que\" is the object: \"la machine QUI tourne\" / \"la machine QUE j''utilise\".","es":"«Qui» es el sujeto del verbo siguiente; «que» es el objeto: «la machine QUI tourne» / «la machine QUE j''utilise»."},{"en":"\"La laverie (automatique)\" = laundromat; \"le pressing\" = dry cleaner; \"la blanchisserie\" = laundry service.","es":"«La laverie (automatique)» = lavandería de autoservicio; «le pressing» = tintorería; «la blanchisserie» = servicio de lavandería."},{"en":"\"Faire la lessive\" = to do the laundry; \"la lessive\" is also the detergent. \"L''eau de Javel\" = bleach.","es":"«Faire la lessive» = hacer la colada; «la lessive» también es el detergente. «L''eau de Javel» = la lejía."},{"en":"\"Faire de la monnaie\" = to get change; \"Vous avez de la monnaie ?\" = Do you have change?","es":"«Faire de la monnaie» = conseguir cambio; «Vous avez de la monnaie ?» = ¿Tiene cambio?"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Je dois aller à la laverie pour laver mon linge.","translation":"I have to go to the laundromat to wash my clothes.","translations":{"es":"Tengo que ir a la lavandería a lavar la ropa."}},{"phrase":"Tu auras besoin de monnaie.","translation":"You will need change.","translations":{"es":"Necesitarás monedas."}},{"phrase":"Le linge qui est dans cette machine m''appartient.","translation":"The laundry in this machine belongs to me.","translations":{"es":"La ropa que está en esta lavadora es mía."}},{"phrase":"Elle a accumulé du linge pendant un mois.","translation":"She let her laundry pile up for a month.","translations":{"es":"Ha acumulado ropa durante un mes."}},{"phrase":"Ce sont ceux qui t''ont pris la monnaie sur la table.","translation":"They are the ones who took the change from the table.","translations":{"es":"Son los que te quitaron las monedas de la mesa."}},{"phrase":"La fille qui vient de me demander du savon, c''est celle que je t''ai dit d''inviter.","translation":"The girl who just asked me for soap is the one I told you to invite.","translations":{"es":"La chica que me acaba de pedir jabón es la que te dije que invitaras."}},{"phrase":"La laverie où je lave mon linge coûte seulement trois euros la machine.","translation":"The laundromat where I wash my clothes costs only three euros per load.","translations":{"es":"La lavandería donde lavo la ropa cuesta solo tres euros por lavadora."}},{"phrase":"La meilleure laverie, c''est celle qui est en face.","translation":"The best laundromat is the one opposite.","translations":{"es":"La mejor lavandería es la que está enfrente."}},{"phrase":"Il y a du linge de couleur dans cette machine : ne mets pas d''eau de Javel !","translation":"There are colored clothes in this machine: don''t put in bleach!","translations":{"es":"Hay ropa de color en esta lavadora: ¡no le eches lejía!"}},{"phrase":"Mets deux euros dans la fente pour utiliser le sèche-linge.","translation":"Put two euros in the slot to use the dryer.","translations":{"es":"Mete dos euros en la ranura para usar la secadora."}},{"phrase":"Combien de lessive tu mets ? — Une tasse, pour éviter que la machine tombe en panne.","translation":"How much detergent do you put in? — One cup, to avoid the machine breaking down.","translations":{"es":"¿Cuánto detergente pones? — Una taza, para evitar que la lavadora se averíe."}},{"phrase":"À qui appartient ce linge ? — À la fille qui vient de te demander de la monnaie.","translation":"Whose laundry is this? — The girl''s who just asked you for change.","translations":{"es":"¿De quién es esta ropa? — De la chica que te acaba de pedir monedas."}},{"phrase":"J''étais à la laverie où ma mère avait l''habitude d''aller.","translation":"I was at the laundromat my mother used to go to.","translations":{"es":"Estaba en la lavandería adonde solía ir mi madre."}},{"phrase":"C''est celui qu''on a lavé deux fois ?","translation":"Is it the one we washed twice?","translations":{"es":"¿Es el que lavamos dos veces?"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"La machine ___ est au coin est en panne.\"","options":["qui","où","que","dont"],"correct":0,"explanation":"\"Qui\" = subject of \"est\".","translations":{"es":{"question":"Completa: «La machine ___ est au coin est en panne.»","explanation":"«Qui» = sujeto de «est»."}}},{"id":"2","question":"Complete: \"Le pull ___ tu as lavé a rétréci.\"","options":["qui","que","où","quoi"],"correct":1,"explanation":"\"Que\" = object of \"as lavé\".","translations":{"es":{"question":"Completa: «Le pull ___ tu as lavé a rétréci.»","explanation":"«Que» = objeto de «as lavé»."}}},{"id":"3","question":"Complete: \"La laverie ___ je vais est près d''ici.\"","options":["où","qui","que","dont"],"correct":0,"explanation":"\"Où\" for places.","translations":{"es":{"question":"Completa: «La laverie ___ je vais est près d''ici.»","explanation":"«Où» para lugares."}}},{"id":"4","question":"Complete: \"La meilleure, c''est ___ qui est en face.\" (la laverie)","options":["celle","celui","ceux","celles"],"correct":0,"explanation":"Laverie is feminine singular.","translations":{"es":{"question":"Completa: «La meilleure, c''est ___ qui est en face.» (la laverie)","explanation":"Laverie es femenino singular."}}},{"id":"5","question":"Complete: \"Qu''est-ce que tu veux que je ___ ?\"","options":["fais","fasse","ferai","faisais"],"correct":1,"explanation":"Vouloir que + subjunctive.","translations":{"es":{"question":"Completa: «Qu''est-ce que tu veux que je ___ ?»","explanation":"Vouloir que + subjuntivo."}}},{"id":"6","question":"What is \"le pressing\"?","options":["the iron","the dryer","the dry cleaner","the detergent"],"correct":2,"explanation":"Laverie = self-service laundromat.","translations":{"es":{"question":"¿Qué es «le pressing»?","explanation":"Laverie = lavandería de autoservicio.","options":["la plancha","la secadora","la tintorería","el detergente"]}}},{"id":"7","question":"What should you NOT put with colored clothes?","options":["de l''eau","de la lessive","de l''eau de Javel","du linge"],"correct":2,"explanation":"Bleach discolors fabrics.","translations":{"es":{"question":"¿Qué NO debes echar con la ropa de color?","explanation":"La lejía decolora los tejidos."}}},{"id":"8","question":"\"Faire de la monnaie\" means…","options":["to make money","to print coins","to get change","to save money"],"correct":2,"explanation":"To earn money = gagner de l''argent.","translations":{"es":{"question":"«Faire de la monnaie» significa…","explanation":"Ganar dinero = gagner de l''argent.","options":["ganar dinero","acuñar monedas","conseguir cambio","ahorrar dinero"]}}}]}'::jsonb, 3),
  ('story', 'Jour de lessive', '{"text":"« Sami, tu vas faire la lessive aujourd''hui ? » demande Léo. « Oui, j''irai à la laverie qui vient d''ouvrir au coin de la rue. C''est celle où il y a du wifi. » « Tu peux laver mon linge aussi ? » « Pourquoi tu ne viens pas avec moi ? Pendant que les machines tournent, on pourra discuter. » « Je ne peux pas, je dois finir un exposé. » « Bon. Alors, j''aurai besoin d''argent pour acheter plus de lessive et de monnaie pour les machines. Tu me dois déjà dix euros, tu te souviens ? » « Je sais… Ça me coûte plus cher que prévu ! » « Tu as accumulé du linge pendant trois semaines. Qu''est-ce que tu veux que je fasse ? Ce sont tes chaussettes qui sentent mauvais, pas les miennes ! » Léo rit. « D''accord, prends ce dont tu as besoin. Laisse-moi juste cinq euros. » « Et mon pourboire ? » « Tu sais quoi ? Je vais venir avec toi et je travaillerai à la laverie. Comme ça, tu ne seras pas de mauvaise humeur. » « Je ne suis pas de mauvaise humeur ! Je dois juste m''habituer à vivre avec quelqu''un qui ne fait jamais sa lessive. »","translation":"“Sami, are you doing the laundry today?” asks Léo. “Yes, I''ll go to the laundromat that just opened on the corner. It''s the one with wifi.” “Can you wash my clothes too?” “Why don''t you come with me? While the machines are running, we can chat.” “I can''t, I have to finish a presentation.” “OK. Then I''ll need money to buy more detergent and change for the machines. You already owe me ten euros, remember?” “I know… It''s costing me more than I expected!” “You let your laundry pile up for three weeks. What do you want me to do? It''s your socks that smell, not mine!” Léo laughs. “All right, take what you need. Just leave me five euros.” “And my tip?” “You know what? I''ll come with you and work at the laundromat. That way, you won''t be in a bad mood.” “I''m not in a bad mood! I just have to get used to living with someone who never does his laundry.”","translations":{"es":"«Sami, ¿vas a hacer la colada hoy?», pregunta Léo. «Sí, iré a la lavandería que acaban de abrir en la esquina. Es la que tiene wifi.» «¿Puedes lavar mi ropa también?» «¿Por qué no vienes conmigo? Mientras dan vueltas las lavadoras, podemos charlar.» «No puedo, tengo que terminar una exposición.» «Bueno. Entonces necesitaré dinero para comprar más detergente y monedas para las máquinas. Ya me debes diez euros, ¿te acuerdas?» «Lo sé… ¡Me está saliendo más caro de lo previsto!» «Has acumulado ropa durante tres semanas. ¿Qué quieres que haga? ¡Son tus calcetines los que huelen mal, no los míos!» Léo se ríe. «Vale, coge lo que necesites. Solo déjame cinco euros.» «¿Y mi propina?» «¿Sabes qué? Voy contigo y trabajaré en la lavandería. Así no estarás de mal humor.» «¡No estoy de mal humor! Solo tengo que acostumbrarme a vivir con alguien que nunca hace la colada.»"},"highlighted_words":["faire la lessive","la laverie qui vient","C''est celle où","j''aurai besoin","monnaie","tu as accumulé","Qu''est-ce que tu veux que je fasse","Ce sont tes chaussettes qui","de mauvaise humeur","m''habituer","quelqu''un qui ne fait jamais"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Le","linge","qui","est","ici","est","à","moi"],"translation":"The laundry here is mine","translations":{"es":"La ropa que está aquí es mía"}},{"words":["C''est","celle","que","je","préfère"],"translation":"It''s the one I prefer","translations":{"es":"Es la que prefiero"}},{"words":["Tu","auras","besoin","de","monnaie"],"translation":"You will need change","translations":{"es":"Necesitarás monedas"}},{"words":["La","laverie","où","je","vais","est","propre"],"translation":"The laundromat I go to is clean","translations":{"es":"La lavandería adonde voy está limpia"}},{"words":["Qu''est-ce","que","tu","veux","que","je","fasse"],"translation":"What do you want me to do","translations":{"es":"¿Qué quieres que haga?"}},{"words":["Je","dois","faire","la","lessive"],"translation":"I have to do the laundry","translations":{"es":"Tengo que hacer la colada"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Do you have change?","translations":{"es":"¿Tiene cambio?"},"answer":"Avez-vous de la monnaie ?"},{"prompt":"My laundry is dry","translations":{"es":"Mi ropa está seca"},"answer":"Mon linge est sec"},{"prompt":"The machine is broken","translations":{"es":"La máquina está averiada"},"answer":"La machine est en panne"},{"prompt":"They''re the ones I was looking for","translations":{"es":"Son los que buscaba"},"answer":"Ce sont ceux que je cherchais"},{"prompt":"I don''t have any soap","translations":{"es":"No tengo jabón"},"answer":"Je n''ai pas de savon"},{"prompt":"You owe me ten euros","translations":{"es":"Me debes diez euros"},"answer":"Tu me dois dix euros"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 43: Aller à l'université
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-43', 'Aller à l''université', '🎓', 'Ir a la universidad', 43, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''université / la fac","translation":"university","translations":{"es":"la universidad"}},{"id":"2","word":"la faculté","translation":"the faculty","translations":{"es":"la facultad"}},{"id":"3","word":"l''étudiant / l''étudiante","translation":"the student","translations":{"es":"el estudiante / la estudiante"}},{"id":"4","word":"le camarade de classe","translation":"the classmate","translations":{"es":"el compañero de clase"}},{"id":"5","word":"le professeur","translation":"the professor","translations":{"es":"el profesor"}},{"id":"6","word":"le cours","translation":"the class / course","translations":{"es":"la clase / el curso"}},{"id":"7","word":"la matière","translation":"the subject","translations":{"es":"la asignatura"}},{"id":"8","word":"le semestre","translation":"the semester","translations":{"es":"el semestre"}},{"id":"9","word":"l''emploi du temps","translation":"the timetable","translations":{"es":"el horario"}},{"id":"10","word":"s''inscrire","translation":"to enroll","translations":{"es":"matricularse"}},{"id":"11","word":"l''inscription","translation":"enrollment","translations":{"es":"la matrícula"}},{"id":"12","word":"l''admission","translation":"admission","translations":{"es":"la admisión"}},{"id":"13","word":"le dossier","translation":"the application file","translations":{"es":"el expediente / la solicitud"}},{"id":"14","word":"le délai","translation":"the deadline","translations":{"es":"el plazo"}},{"id":"15","word":"rendre","translation":"to hand in","translations":{"es":"entregar"}},{"id":"16","word":"l''examen","translation":"the exam","translations":{"es":"el examen"}},{"id":"17","word":"passer un examen","translation":"to take an exam","translations":{"es":"presentarse a un examen"}},{"id":"18","word":"réussir","translation":"to pass / succeed","translations":{"es":"aprobar / tener éxito"}},{"id":"19","word":"rater","translation":"to fail","translations":{"es":"suspender"}},{"id":"20","word":"le rattrapage","translation":"the resit","translations":{"es":"la recuperación"}},{"id":"21","word":"la note","translation":"the grade","translations":{"es":"la nota"}},{"id":"22","word":"la moyenne","translation":"the average / pass mark","translations":{"es":"la media / el aprobado"}},{"id":"23","word":"le diplôme","translation":"the degree / diploma","translations":{"es":"el título"}},{"id":"24","word":"obtenir son diplôme","translation":"to graduate","translations":{"es":"graduarse"}},{"id":"25","word":"le certificat","translation":"the certificate","translations":{"es":"el certificado"}},{"id":"26","word":"le laboratoire","translation":"the laboratory","translations":{"es":"el laboratorio"}},{"id":"27","word":"la bibliothèque","translation":"the library","translations":{"es":"la biblioteca"}},{"id":"28","word":"la conférence","translation":"the lecture","translations":{"es":"la conferencia"}},{"id":"29","word":"le cahier","translation":"the notebook","translations":{"es":"el cuaderno"}},{"id":"30","word":"le travail de groupe","translation":"group work","translations":{"es":"el trabajo en grupo"}},{"id":"31","word":"l''exposé","translation":"the presentation","translations":{"es":"la exposición"}},{"id":"32","word":"assister à","translation":"to attend","translations":{"es":"asistir a"}},{"id":"33","word":"rattraper","translation":"to catch up","translations":{"es":"recuperar / ponerse al día"}},{"id":"34","word":"le conseiller","translation":"the advisor","translations":{"es":"el orientador"}},{"id":"35","word":"motivé / motivée","translation":"motivated","translations":{"es":"motivado / motivada"}},{"id":"36","word":"attentif / attentive","translation":"attentive","translations":{"es":"atento / atenta"}}],"grammar":[{"structure":"pouvoir / devoir (présent)","example":"Ils doivent être attentifs. / Je dois m''inscrire à cinq matières au minimum.","en":"Must / can","es":"Deber / poder"},{"structure":"conditionnel (conseil, possibilité)","example":"Tu devrais étudier. / La bibliothèque pourrait être fermée.","en":"Should / could","es":"Debería / podría"},{"structure":"conditionnel passé","example":"J''aurais pu aller à la bibliothèque. / Tu aurais pu t''inscrire plus tôt.","en":"Could have / should have","es":"Habría podido / podrías haber"},{"structure":"devoir (probabilité)","example":"Il doit être ici. / Marie doit être à la bibliothèque.","en":"Must (probability)","es":"Deber de (probabilidad)"},{"structure":"devoir à l''imparfait","example":"Ils devaient donner une conférence.","en":"Was supposed to","es":"Se suponía que / tenían que"},{"structure":"avoir intérêt à","example":"Nous avons intérêt à commencer aujourd''hui.","en":"\"Had better\"","es":"«Más vale que / nos conviene»"},{"structure":"avant que + subjonctif","example":"Pas avant que j''aie terminé le cours.","en":"\"Before\" + subjunctive","es":"«Antes de que» + subjuntivo"},{"structure":"préférer … à …","example":"Nous préférons travailler en groupe à travailler seuls.","en":"Preferring one thing to another","es":"Preferir una cosa a otra"}],"tips":[{"en":"French grades are out of 20; 10/20 is usually the pass mark. \"Avoir la moyenne\" = to pass.","es":"En Francia las notas son sobre 20; normalmente se aprueba con 10/20. «Avoir la moyenne» = aprobar."},{"en":"\"Passer un examen\" = to TAKE an exam; \"réussir un examen\" = to PASS; \"rater / échouer à un examen\" = to fail.","es":"«Passer un examen» = presentarse a un examen; «réussir un examen» = aprobar; «rater / échouer à un examen» = suspender."},{"en":"\"La fac\" = informal for university; \"le rattrapage\" = resit exam; \"le / la conseiller(ère) d''orientation\" = academic advisor.","es":"«La fac» = la universidad (coloquial); «le rattrapage» = examen de recuperación; «le / la conseiller(ère) d''orientation» = orientador."},{"en":"\"Un devoir\" = homework; \"un exposé\" = class presentation; \"un mémoire\" = thesis.","es":"«Un devoir» = deberes / trabajo; «un exposé» = exposición oral; «un mémoire» = tesina / trabajo de fin de estudios."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"J''aurais pu aller à la bibliothèque.","translation":"I could have gone to the library.","translations":{"es":"Podría haber ido a la biblioteca."}},{"phrase":"Elles pourraient être en cours.","translation":"They might be in class.","translations":{"es":"Podrían estar en clase."}},{"phrase":"Tu devrais étudier davantage.","translation":"You should study more.","translations":{"es":"Deberías estudiar más."}},{"phrase":"Ils devaient s''inscrire aujourd''hui.","translation":"They were supposed to enroll today.","translations":{"es":"Tenían que matricularse hoy."}},{"phrase":"Arrivez à l''heure, sinon le professeur ne vous laissera pas entrer.","translation":"Arrive on time, otherwise the professor won''t let you in.","translations":{"es":"Lleguen a tiempo, si no el profesor no los dejará entrar."}},{"phrase":"Elle ne peut pas rater géologie, sinon elle devra refaire le semestre.","translation":"She can''t fail geology, otherwise she will have to repeat the semester.","translations":{"es":"No puede suspender Geología, si no tendrá que repetir el semestre."}},{"phrase":"Tu aurais pu t''inscrire plus tôt !","translation":"You could have enrolled earlier!","translations":{"es":"¡Podrías haberte matriculado antes!"}},{"phrase":"Ils ne peuvent pas s''inscrire sans leur carte d''identité.","translation":"They can''t enroll without their ID card.","translations":{"es":"No pueden matricularse sin su documento de identidad."}},{"phrase":"Nous préférons travailler en groupe à travailler seuls.","translation":"We prefer working in a group to working alone.","translations":{"es":"Preferimos trabajar en grupo a trabajar solos."}},{"phrase":"Je devrais réussir l''examen, j''ai beaucoup révisé hier soir.","translation":"I should pass the exam, I studied a lot last night.","translations":{"es":"Debería aprobar el examen, repasé mucho anoche."}},{"phrase":"Où est Marie ? — Elle doit être à la bibliothèque.","translation":"Where is Marie? — She must be at the library.","translations":{"es":"¿Dónde está Marie? — Debe de estar en la biblioteca."}},{"phrase":"Je peux sortir ? — Non, pas avant que j''aie terminé le cours.","translation":"Can I go out? — No, not before I have finished the class.","translations":{"es":"¿Puedo salir? — No, no antes de que haya terminado la clase."}},{"phrase":"Tu t''es inscrite à temps ? — Non, j''ai dû payer un supplément.","translation":"Did you enroll on time? — No, I had to pay an extra fee.","translations":{"es":"¿Te matriculaste a tiempo? — No, tuve que pagar un recargo."}},{"phrase":"Si tu ne respectes pas le délai, tu ne pourras pas passer l''examen.","translation":"If you don''t meet the deadline, you won''t be able to take the exam.","translations":{"es":"Si no cumples el plazo, no podrás presentarte al examen."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"How do you give advice: \"You should study\"?","options":["Tu devras étudier.","Tu dois étudier.","Tu as dû étudier.","Tu devrais étudier."],"correct":3,"explanation":"Conditional of devoir = should.","translations":{"es":{"question":"¿Cómo das un consejo: «Deberías estudiar»?","explanation":"Condicional de devoir = deberías."}}},{"id":"2","question":"\"J''aurais pu venir.\" Meaning?","options":["I was able to come.","I came.","I will be able to come.","I could have come."],"correct":3,"explanation":"Conditionnel passé of pouvoir.","translations":{"es":{"question":"«J''aurais pu venir.» ¿Significado?","explanation":"Conditionnel passé de pouvoir.","options":["Pude venir.","Vine.","Podré venir.","Podría haber venido."]}}},{"id":"3","question":"\"Elle doit être à la bibliothèque.\" What does \"doit\" express?","options":["a wish","obligation","the future","probability"],"correct":3,"explanation":"She is probably at the library.","translations":{"es":{"question":"«Elle doit être à la bibliothèque.» ¿Qué expresa «doit»?","explanation":"Probablemente está en la biblioteca.","options":["un deseo","obligación","el futuro","probabilidad"]}}},{"id":"4","question":"\"Passer un examen\" means…","options":["to skip an exam","to pass an exam","to write an exam","to take an exam"],"correct":3,"explanation":"To pass = réussir.","translations":{"es":{"question":"«Passer un examen» significa…","explanation":"Aprobar = réussir.","options":["saltarse un examen","aprobar un examen","redactar un examen","presentarse a un examen"]}}},{"id":"5","question":"Complete: \"Pas avant que j''___ fini.\"","options":["ai","avais","aurai","aie"],"correct":3,"explanation":"\"Avant que\" + past subjunctive.","translations":{"es":{"question":"Completa: «Pas avant que j''___ fini.»","explanation":"«Avant que» + subjuntivo pasado."}}},{"id":"6","question":"\"Nous avons intérêt à commencer.\" Meaning?","options":["We''re interested in starting.","We started with interest.","We won''t start.","We''d better start."],"correct":3,"explanation":"\"Avoir intérêt à\" = had better.","translations":{"es":{"question":"«Nous avons intérêt à commencer.» ¿Significado?","explanation":"«Avoir intérêt à» = más vale que.","options":["Nos interesa empezar como tema.","Empezamos con interés.","No empezaremos.","Más vale que empecemos."]}}},{"id":"7","question":"In France, what is the usual pass mark?","options":["60/100","5/10","7/10","10/20"],"correct":3,"explanation":"Grades are out of 20.","translations":{"es":{"question":"En Francia, ¿cuál es la nota habitual para aprobar?","explanation":"Las notas son sobre 20."}}},{"id":"8","question":"Complete: \"Ils ___ donner une conférence, mais ils sont malades.\"","options":["devront","ont dû","doivent","devaient"],"correct":3,"explanation":"Imparfait of devoir = were supposed to.","translations":{"es":{"question":"Completa: «Ils ___ donner une conférence, mais ils sont malades.»","explanation":"Imperfecto de devoir = se suponía que."}}}]}'::jsonb, 3),
  ('story', 'Le projet de groupe', '{"text":"« Écoutez, nous devons rendre le projet vendredi », dit Clara à son groupe. « Il compte pour quarante pour cent de la note finale. » « Et on dit que ce professeur note très sévèrement les derniers travaux », ajoute Mehdi. « Qu''est-ce qu''on fait ? » « Nous avons intérêt à commencer aujourd''hui. Comme ça, nous aurons aussi le temps de réviser pour l''examen. On peut se retrouver chez moi cet après-midi. » « D''accord. J''ai vraiment besoin d''une bonne note, sinon je devrai repasser la matière au rattrapage. » « Moi, je ne suis pas très motivé par ce sujet », soupire Lucas. « J''aurais dû choisir un autre cours. Je crois que je vais devoir refaire le semestre : mes résultats n''ont pas été bons. » « Le problème, c''est que pour ce projet, nous devions étudier le chapitre dix, et le professeur ne l''a pas expliqué ! » « Si nous commençons maintenant, nous pourrons nous renseigner à la bibliothèque. Je suis sûre que nous réussirons. » « Vous pourriez commencer sans moi ? Je dois assister à un cours au laboratoire. Je vous rejoins après. » « Pas de problème. Tu devrais nous trouver à la bibliothèque. »","translation":"“Listen, we have to hand in the project on Friday,” Clara tells her group. “It counts for forty percent of the final grade.” “And they say this professor grades the final assignments very harshly,” Mehdi adds. “What do we do?” “We''d better start today. That way, we''ll also have time to review for the exam. We can meet at my place this afternoon.” “OK. I really need a good grade, otherwise I''ll have to resit the subject.” “I''m not very motivated by this topic,” sighs Lucas. “I should have chosen another course. I think I''m going to have to repeat the semester: my results haven''t been good.” “The problem is that for this project we were supposed to study chapter ten, and the professor didn''t explain it!” “If we start now, we can look it up at the library. I''m sure we''ll succeed.” “Could you start without me? I have to attend a class at the lab. I''ll join you afterwards.” “No problem. You should find us at the library.”","translations":{"es":"«Escuchen, tenemos que entregar el proyecto el viernes», le dice Clara a su grupo. «Cuenta un cuarenta por ciento de la nota final.» «Y dicen que este profesor corrige con mucha dureza los últimos trabajos», añade Mehdi. «¿Qué hacemos?» «Más vale que empecemos hoy. Así también tendremos tiempo de repasar para el examen. Podemos quedar en mi casa esta tarde.» «Vale. Necesito de verdad una buena nota, si no tendré que ir a la recuperación de la asignatura.» «A mí no me motiva mucho este tema», suspira Lucas. «Debería haber elegido otro curso. Creo que voy a tener que repetir el semestre: mis resultados no han sido buenos.» «¡El problema es que para este proyecto teníamos que estudiar el capítulo diez, y el profesor no lo explicó!» «Si empezamos ahora, podremos informarnos en la biblioteca. Estoy segura de que lo conseguiremos.» «¿Podrían empezar sin mí? Tengo que asistir a una clase en el laboratorio. Me reúno con ustedes después.» «No hay problema. Deberías encontrarnos en la biblioteca.»"},"highlighted_words":["nous devons rendre","note","Nous avons intérêt à","sinon je devrai","rattrapage","J''aurais dû","refaire le semestre","nous devions étudier","nous pourrons","Vous pourriez","Tu devrais"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Tu","devrais","étudier","plus"],"translation":"You should study more","translations":{"es":"Deberías estudiar más"}},{"words":["J''aurais","pu","venir","plus","tôt"],"translation":"I could have come earlier","translations":{"es":"Podría haber venido antes"}},{"words":["Elle","doit","être","à","la","bibliothèque"],"translation":"She must be at the library","translations":{"es":"Debe de estar en la biblioteca"}},{"words":["Je","dois","m''inscrire","avant","lundi"],"translation":"I have to enroll before Monday","translations":{"es":"Tengo que matricularme antes del lunes"}},{"words":["Nous","avons","intérêt","à","commencer"],"translation":"We''d better start","translations":{"es":"Más vale que empecemos"}},{"words":["J''ai","réussi","l''examen"],"translation":"I passed the exam","translations":{"es":"Aprobé el examen"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I have to hand in my homework","translations":{"es":"Tengo que entregar mi trabajo"},"answer":"Je dois rendre mon devoir"},{"prompt":"I failed the exam","translations":{"es":"Suspendí el examen"},"answer":"J''ai raté l''examen"},{"prompt":"What is your grade?","translations":{"es":"¿Cuál es tu nota?"},"answer":"Quelle est ta note ?"},{"prompt":"He will graduate in June","translations":{"es":"Se va a graduar en junio"},"answer":"Il va obtenir son diplôme en juin"},{"prompt":"The library might be closed","translations":{"es":"La biblioteca podría estar cerrada"},"answer":"La bibliothèque pourrait être fermée"},{"prompt":"Arrive on time","translations":{"es":"Llega a tiempo"},"answer":"Arrive à l''heure"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 44: Le colocataire
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-44', 'Le colocataire', '🛏️', 'El compañero de piso', 44, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le / la colocataire","translation":"the roommate","translations":{"es":"el / la compañero/a de piso"}},{"id":"2","word":"la colocation","translation":"flat-sharing","translations":{"es":"el piso compartido"}},{"id":"3","word":"la résidence universitaire","translation":"the student residence","translations":{"es":"la residencia universitaria"}},{"id":"4","word":"l''ami / l''amie","translation":"the friend","translations":{"es":"el amigo / la amiga"}},{"id":"5","word":"l''amitié","translation":"friendship","translations":{"es":"la amistad"}},{"id":"6","word":"le caractère","translation":"personality / temper","translations":{"es":"el carácter"}},{"id":"7","word":"la personnalité","translation":"personality","translations":{"es":"la personalidad"}},{"id":"8","word":"l''intimité","translation":"privacy","translations":{"es":"la intimidad"}},{"id":"9","word":"privé / privée","translation":"private","translations":{"es":"privado / privada"}},{"id":"10","word":"partager","translation":"to share","translations":{"es":"compartir"}},{"id":"11","word":"échanger","translation":"to exchange","translations":{"es":"intercambiar"}},{"id":"12","word":"se disputer","translation":"to argue","translations":{"es":"discutir / pelearse"}},{"id":"13","word":"s''excuser","translation":"to apologize","translations":{"es":"disculparse"}},{"id":"14","word":"les excuses","translation":"apologies","translations":{"es":"las disculpas"}},{"id":"15","word":"pardonner","translation":"to forgive","translations":{"es":"perdonar"}},{"id":"16","word":"faire confiance à","translation":"to trust","translations":{"es":"confiar en"}},{"id":"17","word":"rappeler","translation":"to remind","translations":{"es":"recordar"}},{"id":"18","word":"aider","translation":"to help","translations":{"es":"ayudar"}},{"id":"19","word":"cuisiner","translation":"to cook","translations":{"es":"cocinar"}},{"id":"20","word":"faire la fête","translation":"to party","translations":{"es":"ir de fiesta"}},{"id":"21","word":"se détendre","translation":"to relax","translations":{"es":"relajarse"}},{"id":"22","word":"se concentrer","translation":"to concentrate","translations":{"es":"concentrarse"}},{"id":"23","word":"les notes","translation":"notes / grades","translations":{"es":"los apuntes / las notas"}},{"id":"24","word":"heureux / heureuse","translation":"happy","translations":{"es":"feliz"}},{"id":"25","word":"triste","translation":"sad","translations":{"es":"triste"}},{"id":"26","word":"la tristesse","translation":"sadness","translations":{"es":"la tristeza"}},{"id":"27","word":"découragé / découragée","translation":"discouraged","translations":{"es":"desanimado / desanimada"}},{"id":"28","word":"encouragé / encouragée","translation":"encouraged","translations":{"es":"animado / animada"}},{"id":"29","word":"somnambule","translation":"sleepwalker","translations":{"es":"sonámbulo / sonámbula"}},{"id":"30","word":"l''alcool","translation":"alcohol","translations":{"es":"el alcohol"}}],"grammar":[{"structure":"si + présent → présent (vérités générales)","example":"S''il se dispute, il s''excuse toujours. / Si je suis seule, je me repose.","en":"General truths and habits","es":"Verdades generales y hábitos"},{"structure":"lorsque / quand + présent","example":"Elle cuisine uniquement lorsqu''elle n''a pas cours.","en":"\"When / whenever\"","es":"«Cuando»"},{"structure":"si + présent → futur","example":"Si on n''arrive pas à se concentrer à la maison, nous étudierons à la bibliothèque.","en":"Real condition (future)","es":"Condición real (futuro)"},{"structure":"impératif négatif (être)","example":"Ne sois pas triste.","en":"Negative imperative of être","es":"Imperativo negativo de être"},{"structure":"faire confiance à","example":"Je te fais complètement confiance.","en":"\"To trust\"","es":"«Confiar en»"},{"structure":"rappeler (qqch / qqn) à qqn","example":"Mon colocataire me rappelle mon frère. / Tu lui as rappelé de faire le ménage ?","en":"\"To remind\"","es":"«Recordar a / parecerse a»"},{"structure":"imparfait + passé composé","example":"J''essayais d''être gentille, mais elle ne m''a pas parlé.","en":"Background vs. event","es":"Fondo frente a hecho"}],"tips":[{"en":"\"Un colocataire / une colocataire\" (informal: \"un coloc\") shares an apartment; \"un camarade de chambre\" shares a room.","es":"«Un colocataire / une colocataire» (coloquial: «un coloc») comparte piso; «un camarade de chambre» comparte habitación."},{"en":"\"Rappeler quelqu''un à quelqu''un\" = to remind (resemble): \"Il me rappelle mon frère.\" \"Rappeler à quelqu''un de faire quelque chose\" = to remind someone to do something.","es":"«Rappeler quelqu''un à quelqu''un» = recordar (parecerse): «Il me rappelle mon frère.» «Rappeler à quelqu''un de faire quelque chose» = recordarle a alguien que haga algo."},{"en":"\"Faire confiance à quelqu''un\" (not \"confier en\"): \"Je lui fais confiance.\"","es":"«Faire confiance à quelqu''un» (no «confier en»): «Je lui fais confiance.»"},{"en":"\"Somnambule\" = sleepwalker; \"l''intimité\" = privacy.","es":"«Somnambule» = sonámbulo; «l''intimité» = la intimidad."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Je me sens encouragé si tu es mon ami.","translation":"I feel encouraged if you are my friend.","translations":{"es":"Me siento animado si eres mi amigo."}},{"phrase":"Elle cuisine très bien si quelqu''un l''aide.","translation":"She cooks very well if someone helps her.","translations":{"es":"Cocina muy bien si alguien la ayuda."}},{"phrase":"S''il se dispute avec quelqu''un, il s''excuse toujours.","translation":"If he argues with someone, he always apologizes.","translations":{"es":"Si discute con alguien, siempre pide perdón."}},{"phrase":"Elle oublie toujours de faire la vaisselle si tu ne le lui rappelles pas.","translation":"She always forgets to do the dishes if you don''t remind her.","translations":{"es":"Siempre se olvida de fregar si no se lo recuerdas."}},{"phrase":"Si on n''arrive pas à se concentrer à la maison, nous étudierons à la bibliothèque.","translation":"If we can''t concentrate at home, we''ll study at the library.","translations":{"es":"Si no conseguimos concentrarnos en casa, estudiaremos en la biblioteca."}},{"phrase":"Si tu es triste, je suis triste aussi.","translation":"If you''re sad, I''m sad too.","translations":{"es":"Si tú estás triste, yo también."}},{"phrase":"J''aime faire la fête, mais pas dans mon appartement !","translation":"I like partying, but not in my apartment!","translations":{"es":"Me gusta la fiesta, ¡pero no en mi piso!"}},{"phrase":"Elle étudie seulement si elle a un examen important.","translation":"She only studies if she has an important exam.","translations":{"es":"Solo estudia si tiene un examen importante."}},{"phrase":"C''est une vraie amitié si tu lui fais complètement confiance.","translation":"It''s a true friendship if you trust her completely.","translations":{"es":"Es una amistad de verdad si confías plenamente en ella."}},{"phrase":"Si nous avons un examen, nous partageons nos notes.","translation":"If we have an exam, we share our notes.","translations":{"es":"Si tenemos un examen, compartimos los apuntes."}},{"phrase":"Ne sois pas triste !","translation":"Don''t be sad!","translations":{"es":"¡No estés triste!"}},{"phrase":"Mon colocataire me rappelle mon frère.","translation":"My roommate reminds me of my brother.","translations":{"es":"Mi compañero de piso me recuerda a mi hermano."}},{"phrase":"Tu me pardonnes ? — Je te pardonne toujours si tu promets de ne pas recommencer.","translation":"Do you forgive me? — I always forgive you if you promise not to do it again.","translations":{"es":"¿Me perdonas? — Siempre te perdono si prometes no volver a hacerlo."}},{"phrase":"Où étudies-tu ? — Chez moi, quand il n''y a personne.","translation":"Where do you study? — At home, when there''s nobody there.","translations":{"es":"¿Dónde estudias? — En casa, cuando no hay nadie."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"S''il fait beau, nous ___ toujours au parc.\" (habit)","options":["allons","irons","allions","irions"],"correct":0,"explanation":"General truth/habit: si + present → present.","translations":{"es":{"question":"Completa: «S''il fait beau, nous ___ toujours au parc.» (hábito)","explanation":"Verdad general / hábito: si + presente → presente."}}},{"id":"2","question":"Complete: \"Si tu as besoin d''aide, je t''___.\" (future)","options":["aiderais","ai aidé","aiderai","aidais"],"correct":2,"explanation":"Si + present → future.","translations":{"es":{"question":"Completa: «Si tu as besoin d''aide, je t''___.» (futuro)","explanation":"Si + presente → futuro."}}},{"id":"3","question":"How do you say \"I trust you\"?","options":["J''ai confiance de toi.","Je confie en toi.","Je te fais confiance.","Je te confiance."],"correct":2,"explanation":"\"Faire confiance à quelqu''un\".","translations":{"es":{"question":"¿Cómo se dice «Confío en ti»?","explanation":"«Faire confiance à quelqu''un»."}}},{"id":"4","question":"\"Il me rappelle mon frère.\" Meaning?","options":["He calls me brother.","He calls my brother back.","He reminds me of my brother.","He remembers my brother."],"correct":2,"explanation":"Rappeler qqn à qqn = to remind (resemble).","translations":{"es":{"question":"«Il me rappelle mon frère.» ¿Significado?","explanation":"Rappeler qqn à qqn = recordar (parecerse).","options":["Me llama hermano.","Le devuelve la llamada a mi hermano.","Me recuerda a mi hermano.","Se acuerda de mi hermano."]}}},{"id":"5","question":"Negative imperative of \"être\" (tu):","options":["Ne es pas triste.","Ne soit pas triste.","Ne sois pas triste.","N''être pas triste."],"correct":2,"explanation":"Être → sois (tu), soyons, soyez.","translations":{"es":{"question":"Imperativo negativo de «être» (tu):","explanation":"Être → sois (tu), soyons, soyez."}}},{"id":"6","question":"What is \"un colocataire\"?","options":["a neighbor","a roommate / flatmate","a landlord","a colleague"],"correct":1,"explanation":"Informal: un coloc.","translations":{"es":{"question":"¿Qué es «un colocataire»?","explanation":"Coloquial: un coloc.","options":["un vecino","un compañero de piso","un casero","un compañero de trabajo"]}}},{"id":"7","question":"Complete: \"Elle cuisine uniquement ___ elle a le temps.\"","options":["lorsqu''","pour qu''","pendant","depuis"],"correct":0,"explanation":"\"Lorsque\" = when (whenever).","translations":{"es":{"question":"Completa: «Elle cuisine uniquement ___ elle a le temps.»","explanation":"«Lorsque» = cuando."}}},{"id":"8","question":"\"L''intimité\" means…","options":["interest","privacy","intimidation","friendship"],"correct":1,"explanation":"Respecter l''intimité de quelqu''un = to respect someone''s privacy.","translations":{"es":{"question":"«L''intimité» significa…","explanation":"Respecter l''intimité de quelqu''un = respetar la intimidad de alguien.","options":["el interés","la intimidad","la intimidación","la amistad"]}}}]}'::jsonb, 3),
  ('story', 'Sommes-nous amies ?', '{"text":"J''ai emménagé dans une résidence universitaire à Grenoble il y a un mois, et ma colocataire, Anaïs, ne m''aimait pas du tout. Être colocataires ne veut pas forcément dire être amies. J''essayais d''être gentille et de partager mes repas, mais elle préférait rester dans sa chambre. Elle sort seulement si elle a une fête, et elle étudie uniquement lorsqu''elle a un examen important. Hier soir, à onze heures, je l''ai trouvée dans la cuisine, découragée, devant un énorme livre de chimie. « Tu as un examen demain ? » « Oui… J''aurais dû commencer plus tôt. S''il reste un chapitre à étudier, je ne dors pas de la nuit ! » « Je peux t''aider, si tu veux. Avant, je voulais être professeure de chimie. » Elle m''a regardée, surprise. « Tu ferais ça pour moi ? » « Bien sûr ! Si j''explique quelque chose à quelqu''un, je le comprends mieux moi aussi. » « Merci… Je suis une bonne élève si j''ai un bon professeur. » « Alors, ne sois pas triste : tu apprendras vite. » Nous avons étudié jusqu''à deux heures du matin. Ce matin, Anaïs m''a laissé un croissant sur la table avec un petit mot : « Merci, coloc ! »","translation":"I moved into a student residence in Grenoble a month ago, and my roommate, Anaïs, didn''t like me at all. Being roommates doesn''t necessarily mean being friends. I tried to be nice and share my meals, but she preferred to stay in her room. She only goes out if there''s a party, and she only studies when she has an important exam. Last night at eleven, I found her in the kitchen, discouraged, in front of a huge chemistry book. “Do you have an exam tomorrow?” “Yes… I should have started earlier. If there''s a chapter left to study, I don''t sleep all night!” “I can help you, if you want. I used to want to be a chemistry teacher.” She looked at me, surprised. “You''d do that for me?” “Of course! If I explain something to someone, I understand it better myself.” “Thanks… I''m a good student if I have a good teacher.” “Then don''t be sad: you''ll learn quickly.” We studied until two in the morning. This morning, Anaïs left me a croissant on the table with a little note: “Thanks, roomie!”","translations":{"es":"Me mudé a una residencia universitaria en Grenoble hace un mes y a mi compañera, Anaïs, no le caía nada bien. Ser compañeras de piso no significa necesariamente ser amigas. Yo intentaba ser amable y compartir mis comidas, pero ella prefería quedarse en su cuarto. Solo sale si hay una fiesta y solo estudia cuando tiene un examen importante. Anoche, a las once, la encontré en la cocina, desanimada, delante de un libro enorme de química. «¿Tienes examen mañana?» «Sí… Debería haber empezado antes. ¡Si me queda un capítulo por estudiar, no duermo en toda la noche!» «Puedo ayudarte, si quieres. Antes quería ser profesora de química.» Me miró sorprendida. «¿Harías eso por mí?» «¡Claro! Si le explico algo a alguien, lo entiendo mejor yo también.» «Gracias… Soy buena alumna si tengo un buen profesor.» «Entonces no estés triste: aprenderás rápido.» Estudiamos hasta las dos de la madrugada. Esta mañana, Anaïs me ha dejado un cruasán en la mesa con una notita: «¡Gracias, compi!»"},"highlighted_words":["colocataire","J''essayais","si elle a une fête","lorsqu''elle a un examen","découragée","S''il reste un chapitre","si tu veux","Si j''explique","si j''ai un bon professeur","ne sois pas triste","coloc"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["S''il","pleut","je","reste","à","la","maison"],"translation":"If it rains I stay home","translations":{"es":"Si llueve, me quedo en casa"}},{"words":["Ne","sois","pas","triste"],"translation":"Don''t be sad","translations":{"es":"No estés triste"}},{"words":["Je","te","fais","confiance"],"translation":"I trust you","translations":{"es":"Confío en ti"}},{"words":["Mon","colocataire","me","rappelle","mon","frère"],"translation":"My roommate reminds me of my brother","translations":{"es":"Mi compañero de piso me recuerda a mi hermano"}},{"words":["Si","tu","veux","je","peux","t''aider"],"translation":"If you want I can help you","translations":{"es":"Si quieres, puedo ayudarte"}},{"words":["Il","s''excuse","toujours"],"translation":"He always apologizes","translations":{"es":"Siempre pide perdón"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"You are my best friend","translations":{"es":"Eres mi mejor amigo"},"answer":"Tu es mon meilleur ami"},{"prompt":"I forgive you","translations":{"es":"Te perdono"},"answer":"Je te pardonne"},{"prompt":"We share an apartment","translations":{"es":"Compartimos un piso"},"answer":"Nous partageons un appartement"},{"prompt":"They argue often","translations":{"es":"Discuten a menudo"},"answer":"Ils se disputent souvent"},{"prompt":"If I''m alone, I rest","translations":{"es":"Si estoy sola, descanso"},"answer":"Si je suis seule, je me repose"},{"prompt":"Remind me to do the dishes","translations":{"es":"Recuérdame fregar los platos"},"answer":"Rappelle-moi de faire la vaisselle"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 45: L'amour et le mariage
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-45', 'L''amour et le mariage', '💍', 'El amor y el matrimonio', 45, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''amour","translation":"love","translations":{"es":"el amor"}},{"id":"2","word":"aimer","translation":"to love","translations":{"es":"amar / querer"}},{"id":"3","word":"tomber amoureux de","translation":"to fall in love with","translations":{"es":"enamorarse de"}},{"id":"4","word":"être amoureux / amoureuse","translation":"to be in love","translations":{"es":"estar enamorado / enamorada"}},{"id":"5","word":"le petit ami / la petite amie","translation":"boyfriend / girlfriend","translations":{"es":"el novio / la novia"}},{"id":"6","word":"le fiancé / la fiancée","translation":"fiancé / fiancée","translations":{"es":"el prometido / la prometida"}},{"id":"7","word":"se fiancer","translation":"to get engaged","translations":{"es":"comprometerse"}},{"id":"8","word":"se marier avec","translation":"to marry","translations":{"es":"casarse con"}},{"id":"9","word":"le mariage","translation":"marriage / wedding","translations":{"es":"el matrimonio / la boda"}},{"id":"10","word":"l''alliance","translation":"the wedding ring","translations":{"es":"la alianza"}},{"id":"11","word":"le mari / la femme","translation":"husband / wife","translations":{"es":"el marido / la mujer"}},{"id":"12","word":"divorcer","translation":"to divorce","translations":{"es":"divorciarse"}},{"id":"13","word":"embrasser","translation":"to kiss","translations":{"es":"besar"}},{"id":"14","word":"serrer dans ses bras","translation":"to hug","translations":{"es":"abrazar"}},{"id":"15","word":"flirter","translation":"to flirt","translations":{"es":"coquetear"}},{"id":"16","word":"tromper","translation":"to cheat on","translations":{"es":"engañar"}},{"id":"17","word":"trahir","translation":"to betray","translations":{"es":"traicionar"}},{"id":"18","word":"jurer","translation":"to swear","translations":{"es":"jurar"}},{"id":"19","word":"promettre","translation":"to promise","translations":{"es":"prometer"}},{"id":"20","word":"pardonner","translation":"to forgive","translations":{"es":"perdonar"}},{"id":"21","word":"se disputer","translation":"to argue","translations":{"es":"pelearse"}},{"id":"22","word":"communiquer","translation":"to communicate","translations":{"es":"comunicarse"}},{"id":"23","word":"la confiance","translation":"trust","translations":{"es":"la confianza"}},{"id":"24","word":"le respect","translation":"respect","translations":{"es":"el respeto"}},{"id":"25","word":"le bonheur","translation":"happiness","translations":{"es":"la felicidad"}},{"id":"26","word":"le cœur","translation":"the heart","translations":{"es":"el corazón"}},{"id":"27","word":"l''âme","translation":"the soul","translations":{"es":"el alma"}},{"id":"28","word":"pleurer","translation":"to cry","translations":{"es":"llorar"}},{"id":"29","word":"sourire","translation":"to smile","translations":{"es":"sonreír"}},{"id":"30","word":"manquer à","translation":"to be missed by","translations":{"es":"echar de menos (estructura invertida)"}},{"id":"31","word":"regretter","translation":"to regret","translations":{"es":"lamentar / arrepentirse"}},{"id":"32","word":"jaloux / jalouse","translation":"jealous","translations":{"es":"celoso / celosa"}},{"id":"33","word":"déprimé / déprimée","translation":"depressed","translations":{"es":"deprimido / deprimida"}},{"id":"34","word":"le conte de fées","translation":"fairy tale","translations":{"es":"el cuento de hadas"}}],"grammar":[{"structure":"si + présent → futur","example":"Si tu me pardonnes, je te promets que tout ira mieux.","en":"Real condition (future)","es":"Condición real (futuro)"},{"structure":"si + présent → futur proche","example":"Si tu continues avec cette attitude, tu vas la perdre.","en":"Condition + near future","es":"Condición + futuro próximo"},{"structure":"futurs irréguliers","example":"Je mourrai, tu iras, elle saura, nous ferons, il faudra","en":"Irregular future stems","es":"Raíces irregulares del futuro"},{"structure":"manquer à","example":"Tu m''as manqué toute la journée.","en":"\"To miss someone\" (inverted)","es":"«Echar de menos» (estructura invertida)"},{"structure":"ne pas vouloir que + subjonctif","example":"Je ne veux pas que mes enfants se sentent seuls.","en":"Wishes + subjunctive","es":"Deseos + subjuntivo"},{"structure":"plus-que-parfait + conditionnel","example":"J''avais pensé que notre amour serait pour toujours.","en":"Past expectation","es":"Expectativa en el pasado"},{"structure":"même si","example":"Il regarde son téléphone même quand il est avec moi.","en":"\"Even if / even when\"","es":"«Aunque / incluso cuando»"}],"tips":[{"en":"\"Tomber amoureux / amoureuse de quelqu''un\" = to fall in love with someone; \"demander quelqu''un en mariage\" = to propose.","es":"«Tomber amoureux / amoureuse de quelqu''un» = enamorarse de alguien; «demander quelqu''un en mariage» = pedir matrimonio."},{"en":"\"Tromper\" = to cheat on; \"se tromper\" = to be mistaken. Careful!","es":"«Tromper» = engañar (ser infiel); «se tromper» = equivocarse. ¡Cuidado!"},{"en":"\"Tu me manques\" = I miss you (literally \"you are missing to me\").","es":"«Tu me manques» = te echo de menos (literalmente «me faltas»)."},{"en":"\"Les contes de fées\" = fairy tales; \"pleurer à chaudes larmes\" = to cry one''s eyes out.","es":"«Les contes de fées» = cuentos de hadas; «pleurer à chaudes larmes» = llorar a lágrima viva."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Si tu continues avec cette attitude, tu vas la perdre.","translation":"If you keep up that attitude, you''re going to lose her.","translations":{"es":"Si sigues con esa actitud, la vas a perder."}},{"phrase":"S''ils ne communiquent pas, ils vont bientôt divorcer.","translation":"If they don''t communicate, they''ll soon divorce.","translations":{"es":"Si no se comunican, pronto se divorciarán."}},{"phrase":"Nous serons heureux si nous oublions cet incident.","translation":"We will be happy if we forget this incident.","translations":{"es":"Seremos felices si olvidamos este incidente."}},{"phrase":"S''il promet quelque chose, il le fait.","translation":"If he promises something, he does it.","translations":{"es":"Si promete algo, lo cumple."}},{"phrase":"Elle m''appellera si elle se sent seule.","translation":"She''ll call me if she feels lonely.","translations":{"es":"Me llamará si se siente sola."}},{"phrase":"Je te croirai si tu le jures.","translation":"I''ll believe you if you swear it.","translations":{"es":"Te creeré si lo juras."}},{"phrase":"Si tu me pardonnes, je te promets que tout ira mieux.","translation":"If you forgive me, I promise everything will be better.","translations":{"es":"Si me perdonas, te prometo que todo irá mejor."}},{"phrase":"Si tu te maries, je ferai la plus grande fête du monde !","translation":"If you get married, I''ll throw the biggest party in the world!","translations":{"es":"¡Si te casas, haré la fiesta más grande del mundo!"}},{"phrase":"Je me sentirai seule si tu ne me serres pas dans tes bras.","translation":"I''ll feel lonely if you don''t hug me.","translations":{"es":"Me sentiré sola si no me abrazas."}},{"phrase":"Tu iras au mariage ? — J''irai si ma femme vient avec moi.","translation":"Will you go to the wedding? — I''ll go if my wife comes with me.","translations":{"es":"¿Irás a la boda? — Iré si mi mujer viene conmigo."}},{"phrase":"Tu es en train de tomber amoureux d''elle ? — Si elle continue à me regarder comme ça, oui !","translation":"Are you falling in love with her? — If she keeps looking at me like that, yes!","translations":{"es":"¿Te estás enamorando de ella? — ¡Si sigue mirándome así, sí!"}},{"phrase":"Tu m''as manqué toute la journée.","translation":"I missed you all day.","translations":{"es":"Te he echado de menos todo el día."}},{"phrase":"Pourquoi es-tu si triste ? — Le mariage est annulé.","translation":"Why are you so sad? — The wedding is cancelled.","translations":{"es":"¿Por qué estás tan triste? — La boda se ha cancelado."}},{"phrase":"J''ai toujours rêvé de me marier avec toi.","translation":"I''ve always dreamed of marrying you.","translations":{"es":"Siempre he soñado con casarme contigo."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Si tu me le demandes, je ___ oui.\"","options":["disais","dirais","dirai","ai dit"],"correct":2,"explanation":"Si + present → future.","translations":{"es":{"question":"Completa: «Si tu me le demandes, je ___ oui.»","explanation":"Si + presente → futuro."}}},{"id":"2","question":"Complete: \"Si elle part, je ___.\" (mourir, future)","options":["mourirai","mourais","mourrai","meurs"],"correct":2,"explanation":"Irregular future: mourr-.","translations":{"es":{"question":"Completa: «Si elle part, je ___.» (mourir, futuro)","explanation":"Futuro irregular: mourr-."}}},{"id":"3","question":"How do you say \"I miss you\"?","options":["Je manque toi.","Je te manque.","Tu me manques.","Tu manques moi."],"correct":2,"explanation":"The person missed is the subject.","translations":{"es":{"question":"¿Cómo se dice «Te echo de menos»?","explanation":"La persona añorada es el sujeto."}}},{"id":"4","question":"\"Tromper quelqu''un\" means…","options":["to cheat on someone","to trust someone","to be mistaken","to marry someone"],"correct":0,"explanation":"\"Se tromper\" = to be mistaken.","translations":{"es":{"question":"«Tromper quelqu''un» significa…","explanation":"«Se tromper» = equivocarse.","options":["engañar a alguien","confiar en alguien","equivocarse","casarse con alguien"]}}},{"id":"5","question":"Complete: \"Je ne veux pas que mes enfants ___ tristes.\"","options":["seront","soient","sont","étaient"],"correct":1,"explanation":"Vouloir que + subjunctive.","translations":{"es":{"question":"Completa: «Je ne veux pas que mes enfants ___ tristes.»","explanation":"Vouloir que + subjuntivo."}}},{"id":"6","question":"Complete: \"J''avais pensé que notre amour ___ éternel.\"","options":["est","serait","sera","soit"],"correct":1,"explanation":"Future in the past = conditional.","translations":{"es":{"question":"Completa: «J''avais pensé que notre amour ___ éternel.»","explanation":"Futuro en el pasado = condicional."}}},{"id":"7","question":"\"Demander quelqu''un en mariage\" means…","options":["to propose to someone","to ask about a marriage","to invite someone to a wedding","to divorce"],"correct":0,"explanation":"He proposed = il l''a demandée en mariage.","translations":{"es":{"question":"«Demander quelqu''un en mariage» significa…","explanation":"Le pidió matrimonio = il l''a demandée en mariage.","options":["pedirle matrimonio a alguien","preguntar por un matrimonio","invitar a alguien a una boda","divorciarse"]}}},{"id":"8","question":"What is \"une alliance\"?","options":["a wedding","a wedding ring","an engagement party","a fiancé"],"correct":1,"explanation":"Also \"an alliance\" in politics.","translations":{"es":{"question":"¿Qué es «une alliance»?","explanation":"También «una alianza» en política.","options":["una boda","una alianza (anillo)","una fiesta de compromiso","un prometido"]}}}]}'::jsonb, 3),
  ('story', 'Cher journal', '{"text":"Lyon, le 12 mars. Cher journal, ces derniers temps, je suis triste. Hugo, mon fiancé, est parti travailler à Montréal il y a six mois, et j''ai l''impression qu''il ne m''aime plus comme avant. Nous nous disputons à chaque appel. Il regarde son téléphone même quand nous parlons en vidéo. Il ne me dit plus « Tu me manques ». J''avais pensé que notre amour serait plus fort que la distance. Il dit qu''il a besoin de temps pour lui. Je crois que je pleurerai toute la nuit si j''apprends qu''il est amoureux de quelqu''un d''autre. Je ne sais pas quoi faire. Ma mère dit que si nous ne communiquons pas mieux, nous allons nous séparer. Mais je l''aime encore. Je ne veux pas que mes amis aient pitié de moi : je suis une femme forte. J''ai beaucoup pleuré, et maintenant, je veux sourire à nouveau. Demain, je l''appellerai et je lui dirai tout ce que je ressens. S''il m''aime vraiment, il m''écoutera. Et s''il ne m''aime plus… eh bien, je survivrai. Ce n''est pas un conte de fées, c''est la vie.","translation":"Lyon, March 12. Dear diary, lately I''ve been sad. Hugo, my fiancé, left to work in Montreal six months ago, and I feel like he doesn''t love me the way he used to. We argue on every call. He looks at his phone even when we''re on video. He doesn''t say “I miss you” anymore. I had thought our love would be stronger than the distance. He says he needs time for himself. I think I''ll cry all night if I find out he''s in love with someone else. I don''t know what to do. My mother says that if we don''t communicate better, we''re going to break up. But I still love him. I don''t want my friends to feel sorry for me: I''m a strong woman. I''ve cried a lot, and now I want to smile again. Tomorrow, I''ll call him and tell him everything I feel. If he really loves me, he''ll listen. And if he doesn''t love me anymore… well, I''ll survive. It''s not a fairy tale, it''s life.","translations":{"es":"Lyon, 12 de marzo. Querido diario: últimamente estoy triste. Hugo, mi prometido, se fue a trabajar a Montreal hace seis meses y tengo la impresión de que ya no me quiere como antes. Discutimos en cada llamada. Mira el móvil incluso cuando hablamos por videollamada. Ya no me dice «Te echo de menos». Había pensado que nuestro amor sería más fuerte que la distancia. Dice que necesita tiempo para él. Creo que lloraré toda la noche si me entero de que está enamorado de otra persona. No sé qué hacer. Mi madre dice que si no nos comunicamos mejor, nos vamos a separar. Pero todavía lo quiero. No quiero que mis amigos me tengan lástima: soy una mujer fuerte. He llorado mucho y ahora quiero volver a sonreír. Mañana lo llamaré y le diré todo lo que siento. Si de verdad me quiere, me escuchará. Y si ya no me quiere… bueno, sobreviviré. No es un cuento de hadas, es la vida."},"highlighted_words":["fiancé","il y a six mois","Nous nous disputons","même quand","Tu me manques","serait plus fort","je pleurerai","si j''apprends","amoureux","si nous ne communiquons pas","nous allons nous séparer","Je ne veux pas que mes amis aient","S''il m''aime vraiment","m''écoutera","conte de fées"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Si","tu","m''aimes","tu","resteras"],"translation":"If you love me you''ll stay","translations":{"es":"Si me quieres, te quedarás"}},{"words":["Tu","me","manques","beaucoup"],"translation":"I miss you a lot","translations":{"es":"Te echo mucho de menos"}},{"words":["Ils","vont","se","marier","en","juin"],"translation":"They''re going to get married in June","translations":{"es":"Se van a casar en junio"}},{"words":["Je","te","le","promets"],"translation":"I promise you","translations":{"es":"Te lo prometo"}},{"words":["Elle","est","tombée","amoureuse","de","lui"],"translation":"She fell in love with him","translations":{"es":"Se enamoró de él"}},{"words":["Si","tu","pars","je","pleurerai"],"translation":"If you leave I''ll cry","translations":{"es":"Si te vas, lloraré"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I love you","translations":{"es":"Te quiero"},"answer":"Je t''aime"},{"prompt":"Will you marry me?","translations":{"es":"¿Quieres casarte conmigo?"},"answer":"Veux-tu m''épouser ?"},{"prompt":"They got divorced","translations":{"es":"Se divorciaron"},"answer":"Ils ont divorcé"},{"prompt":"I forgive you","translations":{"es":"Te perdono"},"answer":"Je te pardonne"},{"prompt":"I missed you","translations":{"es":"Te he echado de menos"},"answer":"Tu m''as manqué"},{"prompt":"I swear","translations":{"es":"Lo juro"},"answer":"Je le jure"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 46: Chercher un emploi
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-46', 'Chercher un emploi', '💼', 'Buscar trabajo', 46, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''emploi","translation":"the job / employment","translations":{"es":"el empleo"}},{"id":"2","word":"le travail","translation":"work / job","translations":{"es":"el trabajo"}},{"id":"3","word":"l''agence pour l''emploi","translation":"the employment agency","translations":{"es":"la agencia de empleo"}},{"id":"4","word":"l''offre d''emploi","translation":"the job offer","translations":{"es":"la oferta de empleo"}},{"id":"5","word":"le CV","translation":"the résumé","translations":{"es":"el currículum"}},{"id":"6","word":"la lettre de motivation","translation":"the cover letter","translations":{"es":"la carta de presentación"}},{"id":"7","word":"l''entretien d''embauche","translation":"the job interview","translations":{"es":"la entrevista de trabajo"}},{"id":"8","word":"embaucher / engager","translation":"to hire","translations":{"es":"contratar"}},{"id":"9","word":"le chef du personnel","translation":"the HR manager","translations":{"es":"el jefe de personal"}},{"id":"10","word":"l''expérience","translation":"experience","translations":{"es":"la experiencia"}},{"id":"11","word":"les références","translation":"references","translations":{"es":"las referencias"}},{"id":"12","word":"la recommandation","translation":"the recommendation","translations":{"es":"la recomendación"}},{"id":"13","word":"le profil","translation":"the profile","translations":{"es":"el perfil"}},{"id":"14","word":"les compétences","translation":"skills","translations":{"es":"las competencias"}},{"id":"15","word":"le talent","translation":"talent","translations":{"es":"el talento"}},{"id":"16","word":"à plein temps","translation":"full-time","translations":{"es":"a tiempo completo"}},{"id":"17","word":"à mi-temps","translation":"part-time","translations":{"es":"a media jornada"}},{"id":"18","word":"temporaire","translation":"temporary","translations":{"es":"temporal"}},{"id":"19","word":"le salaire","translation":"the salary","translations":{"es":"el sueldo"}},{"id":"20","word":"la commission","translation":"the commission","translations":{"es":"la comisión"}},{"id":"21","word":"l''augmentation","translation":"the raise","translations":{"es":"el aumento"}},{"id":"22","word":"la promotion","translation":"the promotion","translations":{"es":"el ascenso"}},{"id":"23","word":"l''assurance","translation":"insurance","translations":{"es":"el seguro"}},{"id":"24","word":"la retraite","translation":"retirement","translations":{"es":"la jubilación"}},{"id":"25","word":"prendre sa retraite","translation":"to retire","translations":{"es":"jubilarse"}},{"id":"26","word":"démissionner","translation":"to resign","translations":{"es":"dimitir"}},{"id":"27","word":"licencier","translation":"to fire","translations":{"es":"despedir"}},{"id":"28","word":"l''arrêt maladie","translation":"sick leave","translations":{"es":"la baja por enfermedad"}},{"id":"29","word":"former","translation":"to train","translations":{"es":"formar"}},{"id":"30","word":"la formation","translation":"training","translations":{"es":"la formación"}},{"id":"31","word":"taper (à l''ordinateur)","translation":"to type","translations":{"es":"teclear"}},{"id":"32","word":"bilingue","translation":"bilingual","translations":{"es":"bilingüe"}},{"id":"33","word":"disponible","translation":"available","translations":{"es":"disponible"}},{"id":"34","word":"l''ambiance","translation":"the atmosphere","translations":{"es":"el ambiente"}},{"id":"35","word":"têtu / têtue","translation":"stubborn","translations":{"es":"testarudo / testaruda"}},{"id":"36","word":"ambitieux / ambitieuse","translation":"ambitious","translations":{"es":"ambicioso / ambiciosa"}}],"grammar":[{"structure":"si + imparfait → conditionnel","example":"S''il trouvait du travail, il gagnerait plus d''argent.","en":"Hypothesis (unreal present)","es":"Hipótesis (presente irreal)"},{"structure":"si j''étais toi / lui…","example":"Si j''étais lui, je démissionnerais.","en":"Giving advice with \"si j''étais\"","es":"Aconsejar con «si yo fuera»"},{"structure":"questions au conditionnel","example":"Qu''est-ce que tu ferais si tu n''avais pas de travail ?","en":"Hypothetical questions","es":"Preguntas hipotéticas"},{"structure":"conditionnel des verbes irréguliers","example":"je serais, j''aurais, je ferais, je pourrais, je saurais","en":"Irregular conditional stems","es":"Raíces irregulares del condicional"},{"structure":"conditionnel passé","example":"Il aurait pu se reposer un peu.","en":"Past conditional","es":"Condicional compuesto"},{"structure":"aller (imparfait) + infinitif","example":"Il semblait qu''il allait avoir une promotion.","en":"Was going to","es":"Iba a"},{"structure":"afin de / pour + infinitif","example":"Il économise afin de profiter de sa retraite.","en":"Purpose","es":"Finalidad"}],"tips":[{"en":"Hypothesis: \"si\" + imparfait, then conditional. NEVER the conditional after \"si\": \"Si j''avais (not aurais) le temps…\".","es":"Hipótesis: «si» + imperfecto, luego condicional. NUNCA condicional después de «si»: «Si j''avais (no aurais) le temps…»."},{"en":"Job vocabulary: \"le CV\" (résumé), \"la lettre de motivation\" (cover letter), \"l''entretien d''embauche\" (job interview), \"le CDI / le CDD\" (permanent / fixed-term contract).","es":"Vocabulario laboral: «le CV» (currículum), «la lettre de motivation» (carta de presentación), «l''entretien d''embauche» (entrevista de trabajo), «le CDI / le CDD» (contrato indefinido / temporal)."},{"en":"\"Démissionner\" = to resign; \"être licencié / renvoyé\" = to be fired; \"prendre sa retraite\" = to retire; \"un arrêt maladie\" = sick leave.","es":"«Démissionner» = dimitir; «être licencié / renvoyé» = ser despedido; «prendre sa retraite» = jubilarse; «un arrêt maladie» = baja por enfermedad."},{"en":"\"Gagner sa vie\" = to earn a living; \"un salaire\" = a salary; \"une augmentation\" = a raise.","es":"«Gagner sa vie» = ganarse la vida; «un salaire» = un sueldo; «une augmentation» = un aumento."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"S''il trouvait du travail, il gagnerait plus d''argent.","translation":"If he found work, he''d earn more money.","translations":{"es":"Si encontrara trabajo, ganaría más dinero."}},{"phrase":"Elle aurait sûrement le poste si on lui faisait passer un entretien.","translation":"She would surely get the job if they gave her an interview.","translations":{"es":"Seguramente conseguiría el puesto si le hicieran una entrevista."}},{"phrase":"Si je savais taper plus vite, j''aurais un meilleur travail.","translation":"If I could type faster, I would have a better job.","translations":{"es":"Si supiera teclear más rápido, tendría un trabajo mejor."}},{"phrase":"Je démissionnerais si je n''avais pas autant de dettes.","translation":"I would resign if I didn''t have so many debts.","translations":{"es":"Dimitiría si no tuviera tantas deudas."}},{"phrase":"Si on vendait plus, on toucherait plus de commissions.","translation":"If we sold more, we would get more commission.","translations":{"es":"Si vendiéramos más, cobraríamos más comisiones."}},{"phrase":"Si elle avait de l''expérience, le chef du personnel la choisirait.","translation":"If she had experience, the HR manager would choose her.","translations":{"es":"Si tuviera experiencia, el jefe de personal la elegiría."}},{"phrase":"S''il le voulait, il pourrait avoir un meilleur poste.","translation":"If he wanted to, he could have a better position.","translations":{"es":"Si quisiera, podría tener un puesto mejor."}},{"phrase":"S''il parlait anglais, l''agence lui trouverait un emploi.","translation":"If he spoke English, the agency would find him a job.","translations":{"es":"Si hablara inglés, la agencia le encontraría un empleo."}},{"phrase":"J''organiserais très bien les archives si tu me donnais plus de temps.","translation":"I would organize the files very well if you gave me more time.","translations":{"es":"Organizaría muy bien el archivo si me dieras más tiempo."}},{"phrase":"Qu''est-ce que tu ferais si tu n''avais pas de travail ? — J''en chercherais un autre.","translation":"What would you do if you didn''t have a job? — I''d look for another one.","translations":{"es":"¿Qué harías si no tuvieras trabajo? — Buscaría otro."}},{"phrase":"Où trouverais-tu un travail temporaire si tu n''étais pas bilingue ?","translation":"Where would you find a temporary job if you weren''t bilingual?","translations":{"es":"¿Dónde encontrarías un trabajo temporal si no fueras bilingüe?"}},{"phrase":"Que feriez-vous si vous étiez à sa place ? — Si j''étais lui, je démissionnerais.","translation":"What would you do in his place? — If I were him, I would resign.","translations":{"es":"¿Qué haría usted en su lugar? — Si yo fuera él, dimitiría."}},{"phrase":"J''ai un entretien d''embauche demain à dix heures.","translation":"I have a job interview tomorrow at ten.","translations":{"es":"Tengo una entrevista de trabajo mañana a las diez."}},{"phrase":"Il a envoyé son CV et une lettre de motivation.","translation":"He sent his résumé and a cover letter.","translations":{"es":"Envió su currículum y una carta de presentación."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Si j''___ riche, je voyagerais.\"","options":["suis","serai","étais","serais"],"correct":2,"explanation":"Si + imparfait → conditional.","translations":{"es":{"question":"Completa: «Si j''___ riche, je voyagerais.»","explanation":"Si + imperfecto → condicional."}}},{"id":"2","question":"Complete: \"S''il avait le temps, il ___ une formation.\"","options":["faisait","ferait","fasse","fera"],"correct":1,"explanation":"Conditional of faire: ferait.","translations":{"es":{"question":"Completa: «S''il avait le temps, il ___ une formation.»","explanation":"Condicional de faire: ferait."}}},{"id":"3","question":"Which sentence is correct?","options":["Si j''avais de l''argent, j''achèterais une maison.","Si j''avais de l''argent, j''achèterai une maison.","Si j''ai de l''argent, j''achèterais une maison.","Si j''aurais de l''argent, j''achèterais une maison."],"correct":0,"explanation":"Si + imparfait → conditionnel présent.","translations":{"es":{"question":"¿Qué frase es correcta?","explanation":"Si + imperfecto → condicional presente."}}},{"id":"4","question":"How do you give advice using \"si\"?","options":["Si j''étais toi, je demanderais une augmentation.","Si je serais toi, je demanderais une augmentation.","Si j''étais toi, je demanderai une augmentation.","Si je suis toi, je demande une augmentation."],"correct":0,"explanation":"\"Si j''étais toi\" + conditional.","translations":{"es":{"question":"¿Cómo das un consejo usando «si»?","explanation":"«Si j''étais toi» + condicional."}}},{"id":"5","question":"What is \"un entretien d''embauche\"?","options":["a salary raise","a job interview","a resignation letter","a maintenance job"],"correct":1,"explanation":"Embaucher = to hire.","translations":{"es":{"question":"¿Qué es «un entretien d''embauche»?","explanation":"Embaucher = contratar.","options":["un aumento de sueldo","una entrevista de trabajo","una carta de dimisión","un trabajo de mantenimiento"]}}},{"id":"6","question":"\"Démissionner\" means…","options":["to be promoted","to resign","to retire","to be fired"],"correct":1,"explanation":"Être licencié = to be fired.","translations":{"es":{"question":"«Démissionner» significa…","explanation":"Être licencié = ser despedido.","options":["ser ascendido","dimitir","jubilarse","ser despedido"]}}},{"id":"7","question":"Complete: \"Qu''est-ce que tu ___ à ma place ?\"","options":["ferais","fais","faisais","feras"],"correct":0,"explanation":"Hypothetical question: conditional.","translations":{"es":{"question":"Completa: «Qu''est-ce que tu ___ à ma place ?»","explanation":"Pregunta hipotética: condicional."}}},{"id":"8","question":"What is a \"CDI\" in France?","options":["a resignation","a permanent contract","an internship","a temporary contract"],"correct":1,"explanation":"CDD = fixed-term contract.","translations":{"es":{"question":"¿Qué es un «CDI» en Francia?","explanation":"CDD = contrato temporal.","options":["una dimisión","un contrato indefinido","unas prácticas","un contrato temporal"]}}}]}'::jsonb, 3),
  ('story', 'Sarah a besoin de souffler', '{"text":"Sarah est ingénieure dans une grande entreprise à Toulouse. Elle a un bon salaire, mais l''ambiance au bureau est terrible. Elle a d''excellentes références et beaucoup d''expérience ; sinon, comment gagnerait-elle autant ? Moi, je travaille dans une agence pour l''emploi, et je lui ai promis de l''aider. Mais en ce moment, il n''y a pas de poste disponible dans son domaine. La semaine dernière, il semblait qu''elle allait avoir une promotion, mais un collègue avec plus d''ancienneté l''a obtenue. Elle a pensé à demander un arrêt maladie ; comme ça, elle aurait pu se reposer un peu. Mais son chef a besoin d''elle pour un projet important. Que feriez-vous si vous étiez à sa place ? Si j''étais elle, je démissionnerais. Elle a trente-cinq ans, et elle a économisé beaucoup d''argent pour acheter une maison à la campagne. Mais Sarah est têtue et ambitieuse : elle préfère rester afin de profiter tranquillement de sa retraite plus tard. Je crois que si on est fort, rien ne peut nous éloigner de nos objectifs. C''est pour ça que j''admire Sarah, même si je ne ferais jamais comme elle !","translation":"Sarah is an engineer at a large company in Toulouse. She has a good salary, but the atmosphere at the office is terrible. She has excellent references and a lot of experience; otherwise, how would she earn so much? I work at an employment agency, and I promised to help her. But at the moment, there''s no position available in her field. Last week, it looked like she was going to get a promotion, but a colleague with more seniority got it. She thought of asking for sick leave; that way she could have rested a bit. But her boss needs her for an important project. What would you do in her place? If I were her, I would resign. She''s thirty-five, and she has saved a lot of money to buy a house in the countryside. But Sarah is stubborn and ambitious: she prefers to stay so she can enjoy her retirement peacefully later. I believe that if you''re strong, nothing can take you away from your goals. That''s why I admire Sarah, even if I would never do what she does!","translations":{"es":"Sarah es ingeniera en una gran empresa de Toulouse. Tiene un buen sueldo, pero el ambiente en la oficina es terrible. Tiene excelentes referencias y mucha experiencia; si no, ¿cómo ganaría tanto? Yo trabajo en una agencia de empleo y le prometí ayudarla. Pero ahora mismo no hay ningún puesto disponible en su campo. La semana pasada parecía que iba a conseguir un ascenso, pero se lo dieron a un compañero con más antigüedad. Pensó en pedir la baja por enfermedad; así habría podido descansar un poco. Pero su jefe la necesita para un proyecto importante. ¿Qué haría usted en su lugar? Si yo fuera ella, dimitiría. Tiene treinta y cinco años y ha ahorrado mucho dinero para comprarse una casa en el campo. Pero Sarah es testaruda y ambiciosa: prefiere quedarse para disfrutar tranquilamente de su jubilación más adelante. Creo que si uno es fuerte, nada puede alejarlo de sus objetivos. Por eso admiro a Sarah, ¡aunque yo nunca haría lo mismo!"},"highlighted_words":["salaire","ambiance","références","comment gagnerait-elle","agence pour l''emploi","allait avoir une promotion","arrêt maladie","elle aurait pu","Que feriez-vous si vous étiez","Si j''étais elle, je démissionnerais","afin de profiter","retraite","ferais"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Si","j''avais","le","temps","je","lirais","plus"],"translation":"If I had time I would read more","translations":{"es":"Si tuviera tiempo, leería más"}},{"words":["Si","j''étais","toi","je","démissionnerais"],"translation":"If I were you I would resign","translations":{"es":"Si yo fuera tú, dimitiría"}},{"words":["Qu''est-ce","que","tu","ferais","à","ma","place"],"translation":"What would you do in my place","translations":{"es":"¿Qué harías en mi lugar?"}},{"words":["J''ai","un","entretien","demain"],"translation":"I have an interview tomorrow","translations":{"es":"Tengo una entrevista mañana"}},{"words":["Il","a","envoyé","son","CV"],"translation":"He sent his résumé","translations":{"es":"Envió su currículum"}},{"words":["Elle","gagnerait","plus","si","elle","parlait","anglais"],"translation":"She would earn more if she spoke English","translations":{"es":"Ganaría más si hablara inglés"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I''m looking for a job","translations":{"es":"Busco trabajo"},"answer":"Je cherche un emploi"},{"prompt":"He resigned","translations":{"es":"Ha dimitido"},"answer":"Il a démissionné"},{"prompt":"If I were rich, I wouldn''t work","translations":{"es":"Si fuera rico, no trabajaría"},"answer":"Si j''étais riche, je ne travaillerais pas"},{"prompt":"She works part-time","translations":{"es":"Trabaja a media jornada"},"answer":"Elle travaille à mi-temps"},{"prompt":"What is the salary?","translations":{"es":"¿Cuál es el sueldo?"},"answer":"Quel est le salaire ?"},{"prompt":"He is going to retire","translations":{"es":"Se va a jubilar"},"answer":"Il va prendre sa retraite"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 47: Parler avec son chef et ses collègues
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-47', 'Parler avec son chef et ses collègues', '🤝', 'Hablar con el jefe y los compañeros', 47, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le chef / la cheffe","translation":"the boss","translations":{"es":"el jefe / la jefa"}},{"id":"2","word":"le directeur / la directrice","translation":"the director","translations":{"es":"el director / la directora"}},{"id":"3","word":"le supérieur","translation":"the superior","translations":{"es":"el superior"}},{"id":"4","word":"le subordonné","translation":"the subordinate","translations":{"es":"el subordinado"}},{"id":"5","word":"le superviseur","translation":"the supervisor","translations":{"es":"el supervisor"}},{"id":"6","word":"le collègue","translation":"the colleague","translations":{"es":"el compañero de trabajo"}},{"id":"7","word":"le personnel","translation":"the staff","translations":{"es":"el personal"}},{"id":"8","word":"l''équipe","translation":"the team","translations":{"es":"el equipo"}},{"id":"9","word":"les employés","translation":"the employees","translations":{"es":"los empleados"}},{"id":"10","word":"les ouvriers","translation":"the workers","translations":{"es":"los obreros"}},{"id":"11","word":"l''autorité","translation":"authority","translations":{"es":"la autoridad"}},{"id":"12","word":"diriger","translation":"to manage / lead","translations":{"es":"dirigir"}},{"id":"13","word":"superviser","translation":"to supervise","translations":{"es":"supervisar"}},{"id":"14","word":"déléguer","translation":"to delegate","translations":{"es":"delegar"}},{"id":"15","word":"collaborer","translation":"to collaborate","translations":{"es":"colaborar"}},{"id":"16","word":"coopérer","translation":"to cooperate","translations":{"es":"cooperar"}},{"id":"17","word":"organiser","translation":"to organize","translations":{"es":"organizar"}},{"id":"18","word":"résoudre","translation":"to solve","translations":{"es":"resolver"}},{"id":"19","word":"la tâche","translation":"the task","translations":{"es":"la tarea"}},{"id":"20","word":"la note de service","translation":"the memo","translations":{"es":"la circular"}},{"id":"21","word":"la réunion","translation":"the meeting","translations":{"es":"la reunión"}},{"id":"22","word":"l''instruction","translation":"the instruction","translations":{"es":"la instrucción"}},{"id":"23","word":"l''erreur","translation":"the mistake","translations":{"es":"el error"}},{"id":"24","word":"efficace","translation":"efficient / effective","translations":{"es":"eficaz"}},{"id":"25","word":"productif / productive","translation":"productive","translations":{"es":"productivo / productiva"}},{"id":"26","word":"la production","translation":"production","translations":{"es":"la producción"}},{"id":"27","word":"la qualité","translation":"quality","translations":{"es":"la calidad"}},{"id":"28","word":"récompenser","translation":"to reward","translations":{"es":"recompensar"}},{"id":"29","word":"la prime","translation":"the bonus","translations":{"es":"la prima / el bono"}},{"id":"30","word":"faire grève","translation":"to go on strike","translations":{"es":"hacer huelga"}},{"id":"31","word":"la grève","translation":"the strike","translations":{"es":"la huelga"}},{"id":"32","word":"faire faillite","translation":"to go bankrupt","translations":{"es":"quebrar"}},{"id":"33","word":"être renvoyé","translation":"to be fired","translations":{"es":"ser despedido"}}],"grammar":[{"structure":"si + plus-que-parfait → conditionnel passé","example":"Si tu nous en avais parlé plus tôt, nous aurions pu nous organiser.","en":"Unreal past (3rd conditional)","es":"Irreal en el pasado (tercer tipo)"},{"structure":"conditionnel passé négatif","example":"Si les ouvriers n''avaient pas fait grève, le superviseur n''aurait pas démissionné.","en":"Negative unreal past","es":"Irreal pasado negativo"},{"structure":"questions au conditionnel passé","example":"Qu''aurais-tu fait si Jean n''avait pas résolu le problème ?","en":"Hypothetical questions about the past","es":"Preguntas hipotéticas sobre el pasado"},{"structure":"condition mixte","example":"Si vous aviez plus de formation, nous gagnerions tous plus d''argent.","en":"Mixed condition (present result)","es":"Condición mixta (resultado presente)"},{"structure":"ça fait … que","example":"Ça fait des mois qu''on n''envoie plus de notes de service.","en":"Duration up to now","es":"Duración hasta ahora"},{"structure":"grâce à / à cause de","example":"Grâce à vos efforts… / À cause de cette erreur…","en":"Positive vs. negative cause","es":"Causa positiva frente a negativa"},{"structure":"ne … pas … mais","example":"Nous ne travaillons pas pour un chef, mais pour nous-mêmes.","en":"\"Not … but\"","es":"«No … sino»"}],"tips":[{"en":"3rd conditional: si + plus-que-parfait, then conditionnel passé: \"Si j''avais su, je ne serais pas venu.\"","es":"Tercer tipo: si + plus-que-parfait, luego conditionnel passé: «Si j''avais su, je ne serais pas venu.»"},{"en":"Office words: \"le / la supérieur(e)\" (boss), \"le / la subordonné(e)\", \"la note de service\" (memo), \"la réunion\" (meeting), \"déléguer\" (to delegate), \"faire grève\" (to strike).","es":"En la oficina: «le / la supérieur(e)» (superior), «le / la subordonné(e)», «la note de service» (circular), «la réunion» (reunión), «déléguer» (delegar), «faire grève» (hacer huelga)."},{"en":"\"Efficace\" = effective (gets results); \"efficient\" is less common in French — \"efficace\" covers both.","es":"«Efficace» = eficaz; «efficient» se usa poco en francés: «efficace» cubre ambos sentidos."},{"en":"\"Grâce à\" for good causes, \"à cause de\" for bad ones: \"grâce à toi\" / \"à cause de la pluie\".","es":"«Grâce à» para causas positivas, «à cause de» para negativas: «grâce à toi» / «à cause de la pluie»."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Si tu nous en avais parlé plus tôt, nous aurions pu nous organiser.","translation":"If you had told us earlier, we could have organized ourselves.","translations":{"es":"Si nos lo hubieras dicho antes, podríamos habernos organizado."}},{"phrase":"S''il avait formé une équipe, nous aurions fini plus tôt.","translation":"If he had formed a team, we would have finished earlier.","translations":{"es":"Si hubiera formado un equipo, habríamos terminado antes."}},{"phrase":"Ils auraient résolu le problème s''ils avaient été bien supervisés.","translation":"They would have solved the problem if they had been well supervised.","translations":{"es":"Habrían resuelto el problema si hubieran estado bien supervisados."}},{"phrase":"Elle aurait pu recevoir une prime si elle n''avait pas commis cette erreur.","translation":"She could have received a bonus if she hadn''t made that mistake.","translations":{"es":"Podría haber recibido una prima si no hubiera cometido ese error."}},{"phrase":"Si j''avais reçu la note de service, j''aurais su qu''il fallait travailler plus.","translation":"If I had received the memo, I would have known I had to work harder.","translations":{"es":"Si hubiera recibido la circular, habría sabido que había que trabajar más."}},{"phrase":"Si les ouvriers n''avaient pas fait grève, le superviseur n''aurait pas démissionné.","translation":"If the workers hadn''t gone on strike, the supervisor wouldn''t have resigned.","translations":{"es":"Si los obreros no hubieran hecho huelga, el supervisor no habría dimitido."}},{"phrase":"S''il avait été bien formé, il n''aurait pas été renvoyé.","translation":"If he had been well trained, he wouldn''t have been fired.","translations":{"es":"Si lo hubieran formado bien, no lo habrían despedido."}},{"phrase":"Si vous aviez tous collaboré, la production aurait été meilleure.","translation":"If you had all collaborated, production would have been better.","translations":{"es":"Si todos hubieran colaborado, la producción habría sido mejor."}},{"phrase":"Le produit aurait pu se vendre dans le monde entier si l''entreprise n''avait pas fait faillite.","translation":"The product could have sold worldwide if the company hadn''t gone bankrupt.","translations":{"es":"El producto podría haberse vendido en todo el mundo si la empresa no hubiera quebrado."}},{"phrase":"Qu''aurais-tu fait si Jean n''avait pas résolu ce problème ? — J''aurais été renvoyé !","translation":"What would you have done if Jean hadn''t solved that problem? — I would have been fired!","translations":{"es":"¿Qué habrías hecho si Jean no hubiera resuelto ese problema? — ¡Me habrían despedido!"}},{"phrase":"Qui aurait organisé l''équipe si tu ne l''avais pas fait ? — Personne.","translation":"Who would have organized the team if you hadn''t? — Nobody.","translations":{"es":"¿Quién habría organizado el equipo si no lo hubieras hecho tú? — Nadie."}},{"phrase":"Il faut savoir déléguer les tâches.","translation":"You have to know how to delegate tasks.","translations":{"es":"Hay que saber delegar las tareas."}},{"phrase":"Nous avons une réunion avec la directrice à quinze heures.","translation":"We have a meeting with the director at 3 p.m.","translations":{"es":"Tenemos una reunión con la directora a las tres de la tarde."}},{"phrase":"Grâce à votre travail, nous avons gagné la confiance de nos clients.","translation":"Thanks to your work, we''ve earned our customers'' trust.","translations":{"es":"Gracias a su trabajo, nos hemos ganado la confianza de nuestros clientes."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Si j''avais su, je ___ venu.\"","options":["serais","serai","aurais","suis"],"correct":0,"explanation":"Venir takes être: je serais venu.","translations":{"es":{"question":"Completa: «Si j''avais su, je ___ venu.»","explanation":"Venir lleva être: je serais venu."}}},{"id":"2","question":"Complete: \"Si vous ___ collaboré, nous aurions fini.\"","options":["aurez","aviez","auriez","avez"],"correct":1,"explanation":"Si + plus-que-parfait.","translations":{"es":{"question":"Completa: «Si vous ___ collaboré, nous aurions fini.»","explanation":"Si + plus-que-parfait."}}},{"id":"3","question":"Which sentence is a 3rd conditional (unreal past)?","options":["S''il avait étudié, il aurait réussi.","S''il étudie, il réussit.","S''il étudie, il réussira.","S''il étudiait, il réussirait."],"correct":0,"explanation":"Plus-que-parfait + conditionnel passé.","translations":{"es":{"question":"¿Qué frase es del tercer tipo (irreal pasado)?","explanation":"Plus-que-parfait + conditionnel passé."}}},{"id":"4","question":"Mixed condition: \"Si tu avais écouté hier, tu ___ la réponse maintenant.\"","options":["saurais","aurais su","savais","sauras"],"correct":0,"explanation":"Past condition, present result → conditionnel présent.","translations":{"es":{"question":"Condición mixta: «Si tu avais écouté hier, tu ___ la réponse maintenant.»","explanation":"Condición pasada, resultado presente → condicional presente."}}},{"id":"5","question":"\"Faire grève\" means…","options":["to go bankrupt","to go on strike","to get a bonus","to make a mistake"],"correct":1,"explanation":"Faire faillite = to go bankrupt.","translations":{"es":{"question":"«Faire grève» significa…","explanation":"Faire faillite = quebrar.","options":["quebrar","hacer huelga","cobrar una prima","cometer un error"]}}},{"id":"6","question":"Complete: \"___ ton aide, nous avons fini à temps.\"","options":["À cause de","Grâce à","Sans","Malgré"],"correct":1,"explanation":"Positive cause: grâce à.","translations":{"es":{"question":"Completa: «___ ton aide, nous avons fini à temps.»","explanation":"Causa positiva: grâce à."}}},{"id":"7","question":"Complete: \"Nous ne travaillons pas pour un chef, ___ pour nous-mêmes.\"","options":["mais","sinon","donc","ou"],"correct":0,"explanation":"\"Ne … pas … mais\" = not … but.","translations":{"es":{"question":"Completa: «Nous ne travaillons pas pour un chef, ___ pour nous-mêmes.»","explanation":"«Ne … pas … mais» = no … sino."}}},{"id":"8","question":"What is \"une note de service\"?","options":["a tip","a bill","an internal memo","a service grade"],"correct":2,"explanation":"Used to inform all employees.","translations":{"es":{"question":"¿Qué es «une note de service»?","explanation":"Sirve para informar a todos los empleados.","options":["una propina","una factura","una circular interna","una nota de servicio"]}}}]}'::jsonb, 3),
  ('story', 'Lettre aux employés', '{"text":"Chers employés, je suis très satisfaite de votre travail et je suis fière de vous. Il y a un an, notre petite boulangerie de Nantes était en difficulté. Si nous n''avions pas changé notre organisation, nous aurions sûrement fait faillite. Comment aurions-nous atteint un tel niveau de qualité si vous n''aviez pas été aussi efficaces et motivés ? Je dois avouer qu''au début, je ne pensais pas que la formation résoudrait nos problèmes. Maintenant, j''en suis certaine. Si nous n''avions pas formé de nouvelles équipes, nous n''aurions jamais ouvert notre deuxième magasin. Et si vous aviez encore plus de formation, nous gagnerions tous plus d''argent ! Aujourd''hui, l''entreprise est plus organisée que jamais. Ça fait des mois qu''on n''envoie plus de notes de service, parce que nous avons compris une chose : nous ne travaillons pas pour une cheffe, mais pour nous-mêmes. Grâce à vos efforts, nous avons gagné la confiance de nos clients. Pour vous remercier, chacun recevra une prime à la fin du mois. Continuons sur cette voie ! Merci. Madame Hélène Declerc, directrice.","translation":"Dear employees, I am very pleased with your work and I am proud of you. A year ago, our little bakery in Nantes was struggling. If we hadn''t changed our organization, we would surely have gone bankrupt. How would we have reached such a level of quality if you hadn''t been so efficient and motivated? I must admit that at first, I didn''t think training would solve our problems. Now I''m certain of it. If we hadn''t formed new teams, we would never have opened our second shop. And if you had even more training, we would all earn more money! Today, the company is more organized than ever. We haven''t sent memos for months, because we have understood one thing: we don''t work for a boss, but for ourselves. Thanks to your efforts, we have earned our customers'' trust. To thank you, everyone will receive a bonus at the end of the month. Let''s keep going this way! Thank you. Mrs. Hélène Declerc, director.","translations":{"es":"Queridos empleados: estoy muy satisfecha con su trabajo y orgullosa de ustedes. Hace un año, nuestra pequeña panadería de Nantes pasaba dificultades. Si no hubiéramos cambiado nuestra organización, seguramente habríamos quebrado. ¿Cómo habríamos alcanzado semejante nivel de calidad si ustedes no hubieran sido tan eficaces y estado tan motivados? Debo confesar que al principio no pensaba que la formación fuera a resolver nuestros problemas. Ahora estoy segura. Si no hubiéramos formado nuevos equipos, nunca habríamos abierto nuestra segunda tienda. ¡Y si tuvieran todavía más formación, todos ganaríamos más dinero! Hoy la empresa está más organizada que nunca. Hace meses que ya no enviamos circulares, porque hemos entendido una cosa: no trabajamos para una jefa, sino para nosotros mismos. Gracias a sus esfuerzos, nos hemos ganado la confianza de nuestros clientes. Para darles las gracias, todos recibirán una prima a fin de mes. ¡Sigamos por este camino! Gracias. Sra. Hélène Declerc, directora."},"highlighted_words":["Si nous n''avions pas changé","nous aurions sûrement fait faillite","Comment aurions-nous atteint","si vous n''aviez pas été","résoudrait","Si nous n''avions pas formé","nous n''aurions jamais ouvert","si vous aviez encore plus","nous gagnerions","Ça fait des mois qu''on","mais pour nous-mêmes","Grâce à","prime"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Si","j''avais","su","je","serais","venu"],"translation":"If I had known I would have come","translations":{"es":"Si lo hubiera sabido, habría venido"}},{"words":["Nous","aurions","fini","plus","tôt"],"translation":"We would have finished earlier","translations":{"es":"Habríamos terminado antes"}},{"words":["Il","faut","savoir","déléguer"],"translation":"You have to know how to delegate","translations":{"es":"Hay que saber delegar"}},{"words":["Grâce","à","vous","nous","avons","réussi"],"translation":"Thanks to you we succeeded","translations":{"es":"Gracias a ustedes lo hemos conseguido"}},{"words":["Les","ouvriers","ont","fait","grève"],"translation":"The workers went on strike","translations":{"es":"Los obreros hicieron huelga"}},{"words":["Qu''aurais-tu","fait","à","ma","place"],"translation":"What would you have done in my place","translations":{"es":"¿Qué habrías hecho en mi lugar?"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"We have a meeting","translations":{"es":"Tenemos una reunión"},"answer":"Nous avons une réunion"},{"prompt":"I made a mistake","translations":{"es":"Cometí un error"},"answer":"J''ai fait une erreur"},{"prompt":"If you had called me, I would have helped you","translations":{"es":"Si me hubieras llamado, te habría ayudado"},"answer":"Si tu m''avais appelé, je t''aurais aidé"},{"prompt":"He was fired","translations":{"es":"Lo despidieron"},"answer":"Il a été renvoyé"},{"prompt":"The team is very efficient","translations":{"es":"El equipo es muy eficaz"},"answer":"L''équipe est très efficace"},{"prompt":"Thank you for your work","translations":{"es":"Gracias por su trabajo"},"answer":"Merci pour votre travail"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 48: À la banque
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-48', 'À la banque', '🏦', 'En el banco', 48, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la banque","translation":"the bank","translations":{"es":"el banco"}},{"id":"2","word":"l''agence","translation":"the branch","translations":{"es":"la sucursal"}},{"id":"3","word":"le guichet","translation":"the counter","translations":{"es":"la ventanilla"}},{"id":"4","word":"le caissier / la caissière","translation":"the teller","translations":{"es":"el cajero / la cajera"}},{"id":"5","word":"le conseiller bancaire","translation":"the bank advisor","translations":{"es":"el asesor bancario"}},{"id":"6","word":"le compte courant","translation":"the current account","translations":{"es":"la cuenta corriente"}},{"id":"7","word":"le compte épargne","translation":"the savings account","translations":{"es":"la cuenta de ahorro"}},{"id":"8","word":"ouvrir un compte","translation":"to open an account","translations":{"es":"abrir una cuenta"}},{"id":"9","word":"le solde","translation":"the balance","translations":{"es":"el saldo"}},{"id":"10","word":"le relevé de compte","translation":"the bank statement","translations":{"es":"el extracto bancario"}},{"id":"11","word":"être à découvert","translation":"to be overdrawn","translations":{"es":"estar en descubierto"}},{"id":"12","word":"le chèque","translation":"the check","translations":{"es":"el cheque"}},{"id":"13","word":"le chéquier","translation":"the checkbook","translations":{"es":"el talonario"}},{"id":"14","word":"encaisser","translation":"to cash","translations":{"es":"cobrar"}},{"id":"15","word":"déposer","translation":"to deposit","translations":{"es":"ingresar"}},{"id":"16","word":"le dépôt","translation":"the deposit","translations":{"es":"el ingreso"}},{"id":"17","word":"retirer","translation":"to withdraw","translations":{"es":"sacar / retirar"}},{"id":"18","word":"le retrait","translation":"the withdrawal","translations":{"es":"la retirada"}},{"id":"19","word":"le distributeur","translation":"the ATM","translations":{"es":"el cajero automático"}},{"id":"20","word":"les espèces","translation":"cash","translations":{"es":"el efectivo"}},{"id":"21","word":"le virement","translation":"the transfer","translations":{"es":"la transferencia"}},{"id":"22","word":"virer / transférer","translation":"to transfer","translations":{"es":"transferir"}},{"id":"23","word":"la carte bancaire / de crédit","translation":"the bank / credit card","translations":{"es":"la tarjeta bancaria / de crédito"}},{"id":"24","word":"le code","translation":"the PIN","translations":{"es":"el PIN"}},{"id":"25","word":"le plafond","translation":"the limit","translations":{"es":"el límite"}},{"id":"26","word":"le prêt","translation":"the loan","translations":{"es":"el préstamo"}},{"id":"27","word":"le crédit","translation":"credit","translations":{"es":"el crédito"}},{"id":"28","word":"les intérêts","translation":"interest","translations":{"es":"los intereses"}},{"id":"29","word":"épargner / économiser","translation":"to save","translations":{"es":"ahorrar"}},{"id":"30","word":"la signature","translation":"the signature","translations":{"es":"la firma"}},{"id":"31","word":"signer","translation":"to sign","translations":{"es":"firmar"}},{"id":"32","word":"le formulaire","translation":"the form","translations":{"es":"el formulario"}},{"id":"33","word":"remplir","translation":"to fill in","translations":{"es":"rellenar"}},{"id":"34","word":"les antécédents","translation":"history / record","translations":{"es":"el historial"}},{"id":"35","word":"refuser","translation":"to refuse","translations":{"es":"rechazar"}},{"id":"36","word":"faire faillite","translation":"to go bankrupt","translations":{"es":"quebrar"}}],"grammar":[{"structure":"quand / lorsque + futur","example":"Lorsqu''ils feront le virement, il partira en voyage. / Quand tu encaisseras le chèque, on te demandera ta carte d''identité.","en":"Future after \"when\"","es":"Futuro después de «cuando»"},{"structure":"si + présent → futur","example":"Si on me refuse le crédit, je devrai chercher une autre banque.","en":"Real condition","es":"Condición real"},{"structure":"quand + futur antérieur","example":"Vous pourrez choisir votre code lorsque vous aurez reçu votre carte.","en":"Completed future action","es":"Acción futura terminada"},{"structure":"avant que + (ne) + subjonctif","example":"Appelle-les avant qu''il n''ait tout dépensé.","en":"\"Before\" + subjunctive (expletive ne)","es":"«Antes de que» + subjuntivo (ne expletivo)"},{"structure":"pour que + subjonctif","example":"J''ai besoin d''argent sur mon compte pour qu''elle me paie.","en":"\"So that\" + subjunctive","es":"«Para que» + subjuntivo"},{"structure":"à chaque fois que / lorsque + présent","example":"Je vais au distributeur à chaque fois que je n''ai plus d''espèces.","en":"Repeated actions","es":"Acciones repetidas"},{"structure":"après avoir + participe","example":"Après avoir envoyé ma demande, j''ai reçu une réponse.","en":"\"After having done\"","es":"«Después de haber»"}],"tips":[{"en":"In French, use the future after \"quand / lorsque / dès que\" when talking about the future: \"Quand j''aurai l''argent, je paierai.\" (Spanish uses the subjunctive here.)","es":"En francés se usa el futuro después de «quand / lorsque / dès que» cuando se habla del futuro: «Quand j''aurai l''argent, je paierai.» (En español se usa el subjuntivo.)"},{"en":"Banking words: \"le compte courant\" (current account), \"le compte épargne\" (savings account), \"le RIB\" (bank details), \"le virement\" (transfer), \"être à découvert\" (to be overdrawn).","es":"Vocabulario bancario: «le compte courant» (cuenta corriente), «le compte épargne» (cuenta de ahorro), «le RIB» (datos bancarios), «le virement» (transferencia), «être à découvert» (estar en descubierto)."},{"en":"\"Le distributeur (automatique)\" or \"le DAB\" = ATM; \"retirer de l''argent\" = to withdraw money; \"le code\" = PIN.","es":"«Le distributeur (automatique)» o «le DAB» = cajero automático; «retirer de l''argent» = sacar dinero; «le code» = PIN."},{"en":"\"Encaisser un chèque\" = to cash a check; \"un chèque sans provision\" = a bounced check.","es":"«Encaisser un chèque» = cobrar un cheque; «un chèque sans provision» = un cheque sin fondos."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Il a toujours des problèmes quand il ouvre un compte.","translation":"He always has problems when he opens an account.","translations":{"es":"Siempre tiene problemas cuando abre una cuenta."}},{"phrase":"Si elle encaisse ce chèque, il sera à découvert.","translation":"If she cashes this check, he will be overdrawn.","translations":{"es":"Si ella cobra este cheque, él quedará en descubierto."}},{"phrase":"Lorsqu''ils feront le virement, il partira en voyage.","translation":"When they make the transfer, he will go on a trip.","translations":{"es":"Cuando hagan la transferencia, se irá de viaje."}},{"phrase":"Quand tu encaisseras le chèque, on te demandera ta carte d''identité.","translation":"When you cash the check, they will ask for your ID.","translations":{"es":"Cuando cobres el cheque, te pedirán el documento de identidad."}},{"phrase":"Si je veux retirer plus de mille euros, je dois aller à mon agence.","translation":"If I want to withdraw more than a thousand euros, I have to go to my branch.","translations":{"es":"Si quiero sacar más de mil euros, tengo que ir a mi sucursal."}},{"phrase":"La banque vérifiera tes antécédents lorsque tu demanderas un prêt.","translation":"The bank will check your history when you apply for a loan.","translations":{"es":"El banco revisará tu historial cuando pidas un préstamo."}},{"phrase":"Nous pourrions économiser si nous ne dépassions pas le plafond de la carte.","translation":"We could save if we didn''t exceed the card limit.","translations":{"es":"Podríamos ahorrar si no superáramos el límite de la tarjeta."}},{"phrase":"Le compte est à découvert quand les dépenses sont supérieures au solde.","translation":"The account is overdrawn when spending is higher than the balance.","translations":{"es":"La cuenta está en descubierto cuando los gastos superan el saldo."}},{"phrase":"Tu vas faire le dépôt ? — Je le ferai si mon père me donne le chèque.","translation":"Are you going to make the deposit? — I''ll do it if my father gives me the check.","translations":{"es":"¿Vas a hacer el ingreso? — Lo haré si mi padre me da el cheque."}},{"phrase":"Appelle-les avant qu''il n''ait tout dépensé !","translation":"Call them before he has spent everything!","translations":{"es":"¡Llámalos antes de que se lo haya gastado todo!"}},{"phrase":"Je vais au distributeur à chaque fois que je n''ai plus d''espèces.","translation":"I go to the ATM every time I run out of cash.","translations":{"es":"Voy al cajero cada vez que me quedo sin efectivo."}},{"phrase":"Je voyagerai quand ma situation financière sera meilleure.","translation":"I will travel when my financial situation is better.","translations":{"es":"Viajaré cuando mi situación económica sea mejor."}},{"phrase":"Elle lit toujours les contrats quand il s''agit d''une grosse somme.","translation":"She always reads contracts when it''s a large sum.","translations":{"es":"Siempre lee los contratos cuando se trata de una suma importante."}},{"phrase":"Vous pourrez choisir votre code lorsque vous aurez reçu votre carte.","translation":"You will be able to choose your PIN once you have received your card.","translations":{"es":"Podrá elegir su PIN cuando haya recibido la tarjeta."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Quand tu ___ à la banque, demande un relevé.\"","options":["irais","ailles","vas","iras"],"correct":3,"explanation":"Future after \"quand\" when the action is in the future.","translations":{"es":{"question":"Completa: «Quand tu ___ à la banque, demande un relevé.»","explanation":"Futuro tras «quand» cuando la acción es futura."}}},{"id":"2","question":"Spanish says \"Cuando tenga dinero\"; French says…","options":["Quand j''aie de l''argent","Quand j''aurais de l''argent","Quand j''ai eu de l''argent","Quand j''aurai de l''argent"],"correct":3,"explanation":"French uses the future, not the subjunctive.","translations":{"es":{"question":"En español se dice «Cuando tenga dinero»; en francés…","explanation":"El francés usa el futuro, no el subjuntivo."}}},{"id":"3","question":"Complete: \"Vous choisirez votre code quand vous ___ votre carte.\"","options":["receviez","recevez","avez reçu","aurez reçu"],"correct":3,"explanation":"Futur antérieur: first you receive the card.","translations":{"es":{"question":"Completa: «Vous choisirez votre code quand vous ___ votre carte.»","explanation":"Futur antérieur: primero se recibe la tarjeta."}}},{"id":"4","question":"\"Être à découvert\" means…","options":["to be rich","to be discovered","to open an account","to be overdrawn"],"correct":3,"explanation":"Your balance is negative.","translations":{"es":{"question":"«Être à découvert» significa…","explanation":"El saldo es negativo.","options":["ser rico","ser descubierto","abrir una cuenta","estar en descubierto"]}}},{"id":"5","question":"Where do you withdraw cash 24/7?","options":["au guichet","au relevé","au chéquier","au distributeur"],"correct":3,"explanation":"Also called \"le DAB\".","translations":{"es":{"question":"¿Dónde sacas efectivo a cualquier hora?","explanation":"También se llama «le DAB»."}}},{"id":"6","question":"Complete: \"Appelle-le avant qu''il ___ tout dépensé.\"","options":["n''a","n''avait","n''aura","n''ait"],"correct":3,"explanation":"\"Avant que\" + subjunctive (often with expletive \"ne\").","translations":{"es":{"question":"Completa: «Appelle-le avant qu''il ___ tout dépensé.»","explanation":"«Avant que» + subjuntivo (a menudo con «ne» expletivo)."}}},{"id":"7","question":"What is \"un virement\"?","options":["a withdrawal","a check","a loan","a bank transfer"],"correct":3,"explanation":"Virer de l''argent = to transfer money.","translations":{"es":{"question":"¿Qué es «un virement»?","explanation":"Virer de l''argent = transferir dinero.","options":["una retirada","un cheque","un préstamo","una transferencia"]}}},{"id":"8","question":"Complete: \"J''ai besoin d''argent pour qu''elle me ___.\"","options":["paye-t-elle","paiera","payait","paie"],"correct":3,"explanation":"\"Pour que\" + subjunctive.","translations":{"es":{"question":"Completa: «J''ai besoin d''argent pour qu''elle me ___.»","explanation":"«Pour que» + subjuntivo."}}}]}'::jsonb, 3),
  ('story', 'Un prêt pour un café', '{"text":"Inès rêve d''ouvrir un petit café à Bordeaux. Après avoir envoyé une demande de prêt en ligne, elle a reçu un message de sa banque qui lui demandait de venir à l''agence la plus proche avec ses trois derniers relevés de compte et une lettre de son ancien employeur. Quand elle est arrivée, la caissière lui a dit d''aller au bureau du conseiller. « Bonjour, Madame Laurent. Asseyez-vous, je vous en prie. Nous devons remplir ces formulaires et vérifier vos antécédents bancaires. » « D''accord, commençons. » « Il y a un petit problème. Sur votre relevé de mars, il y a un retrait de deux mille euros, et votre compte a été à découvert pendant dix jours. » « Oui, mais c''était pour payer un cours de pâtisserie. Mon frère m''a fait un virement la semaine suivante. » Le conseiller vérifie sur son écran. « Vous avez raison. Dans ce cas, si vous signez ici, nous pourrons vous accorder le prêt. Quand nous aurons reçu tous les documents, l''argent sera viré sur votre compte. » « Merci beaucoup ! Je pourrai vous inviter à prendre un café quand j''aurai ouvert ! »","translation":"Inès dreams of opening a small café in Bordeaux. After sending a loan application online, she received a message from her bank asking her to come to the nearest branch with her last three bank statements and a letter from her former employer. When she arrived, the teller told her to go to the advisor''s office. “Hello, Ms. Laurent. Please sit down. We need to fill in these forms and check your banking history.” “All right, let''s start.” “There''s a small problem. On your March statement, there''s a withdrawal of two thousand euros, and your account was overdrawn for ten days.” “Yes, but that was to pay for a pastry course. My brother made a transfer to me the following week.” The advisor checks on his screen. “You''re right. In that case, if you sign here, we''ll be able to grant you the loan. When we have received all the documents, the money will be transferred to your account.” “Thank you very much! I''ll be able to invite you for a coffee once I''ve opened!”","translations":{"es":"Inès sueña con abrir un pequeño café en Burdeos. Después de enviar una solicitud de préstamo por internet, recibió un mensaje de su banco en el que le pedían que fuera a la sucursal más cercana con sus tres últimos extractos y una carta de su antiguo empleador. Cuando llegó, la cajera le dijo que fuera al despacho del asesor. «Buenos días, señora Laurent. Siéntese, por favor. Tenemos que rellenar estos formularios y revisar su historial bancario.» «De acuerdo, empecemos.» «Hay un pequeño problema. En su extracto de marzo hay una retirada de dos mil euros, y su cuenta estuvo en descubierto diez días.» «Sí, pero era para pagar un curso de repostería. Mi hermano me hizo una transferencia la semana siguiente.» El asesor lo comprueba en la pantalla. «Tiene razón. En ese caso, si firma aquí, podremos concederle el préstamo. Cuando hayamos recibido todos los documentos, el dinero se transferirá a su cuenta.» «¡Muchas gracias! ¡Podré invitarlo a un café cuando haya abierto!»"},"highlighted_words":["Après avoir envoyé","agence","relevés de compte","caissière","antécédents bancaires","retrait","à découvert","virement","si vous signez","Quand nous aurons reçu","sera viré","quand j''aurai ouvert"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","voudrais","ouvrir","un","compte"],"translation":"I would like to open an account","translations":{"es":"Quisiera abrir una cuenta"}},{"words":["Quand","tu","iras","à","la","banque","appelle-moi"],"translation":"When you go to the bank call me","translations":{"es":"Cuando vayas al banco, llámame"}},{"words":["Mon","compte","est","à","découvert"],"translation":"My account is overdrawn","translations":{"es":"Mi cuenta está en descubierto"}},{"words":["Je","dois","retirer","de","l''argent"],"translation":"I have to withdraw money","translations":{"es":"Tengo que sacar dinero"}},{"words":["Il","a","fait","un","virement","hier"],"translation":"He made a transfer yesterday","translations":{"es":"Hizo una transferencia ayer"}},{"words":["Signez","ici","s''il","vous","plaît"],"translation":"Sign here please","translations":{"es":"Firme aquí, por favor"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Where is the ATM?","translations":{"es":"¿Dónde está el cajero?"},"answer":"Où est le distributeur ?"},{"prompt":"What is my balance?","translations":{"es":"¿Cuál es mi saldo?"},"answer":"Quel est mon solde ?"},{"prompt":"I would like to cash this check","translations":{"es":"Quisiera cobrar este cheque"},"answer":"Je voudrais encaisser ce chèque"},{"prompt":"I forgot my PIN","translations":{"es":"He olvidado mi PIN"},"answer":"J''ai oublié mon code"},{"prompt":"I will pay when I can","translations":{"es":"Pagaré cuando pueda"},"answer":"Je paierai quand je pourrai"},{"prompt":"Fill in this form","translations":{"es":"Rellene este formulario"},"answer":"Remplissez ce formulaire"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 49: Chez le médecin
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-49', 'Chez le médecin', '🩺', 'En el médico', 49, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le médecin","translation":"the doctor","translations":{"es":"el médico"}},{"id":"2","word":"le / la spécialiste","translation":"the specialist","translations":{"es":"el / la especialista"}},{"id":"3","word":"l''infirmier / l''infirmière","translation":"the nurse","translations":{"es":"el enfermero / la enfermera"}},{"id":"4","word":"le cabinet médical","translation":"the doctor''s office","translations":{"es":"la consulta"}},{"id":"5","word":"les urgences","translation":"the ER","translations":{"es":"urgencias"}},{"id":"6","word":"l''hôpital","translation":"the hospital","translations":{"es":"el hospital"}},{"id":"7","word":"la pharmacie","translation":"the pharmacy","translations":{"es":"la farmacia"}},{"id":"8","word":"l''ordonnance","translation":"the prescription","translations":{"es":"la receta"}},{"id":"9","word":"le médicament","translation":"the medicine","translations":{"es":"el medicamento"}},{"id":"10","word":"le comprimé","translation":"the tablet","translations":{"es":"la pastilla"}},{"id":"11","word":"la gélule","translation":"the capsule","translations":{"es":"la cápsula"}},{"id":"12","word":"le sirop","translation":"the syrup","translations":{"es":"el jarabe"}},{"id":"13","word":"l''aspirine","translation":"aspirin","translations":{"es":"la aspirina"}},{"id":"14","word":"la piqûre","translation":"the shot","translations":{"es":"la inyección"}},{"id":"15","word":"le vaccin","translation":"the vaccine","translations":{"es":"la vacuna"}},{"id":"16","word":"le pansement","translation":"the bandage / dressing","translations":{"es":"la venda / el apósito"}},{"id":"17","word":"le plâtre","translation":"the cast","translations":{"es":"la escayola"}},{"id":"18","word":"les points de suture","translation":"stitches","translations":{"es":"los puntos"}},{"id":"19","word":"les symptômes","translation":"symptoms","translations":{"es":"los síntomas"}},{"id":"20","word":"la fièvre","translation":"fever","translations":{"es":"la fiebre"}},{"id":"21","word":"la grippe","translation":"the flu","translations":{"es":"la gripe"}},{"id":"22","word":"le rhume","translation":"the cold","translations":{"es":"el resfriado"}},{"id":"23","word":"l''allergie","translation":"the allergy","translations":{"es":"la alergia"}},{"id":"24","word":"allergique","translation":"allergic","translations":{"es":"alérgico"}},{"id":"25","word":"l''infection","translation":"the infection","translations":{"es":"la infección"}},{"id":"26","word":"la blessure","translation":"the wound","translations":{"es":"la herida"}},{"id":"27","word":"la douleur","translation":"the pain","translations":{"es":"el dolor"}},{"id":"28","word":"tousser","translation":"to cough","translations":{"es":"toser"}},{"id":"29","word":"éternuer","translation":"to sneeze","translations":{"es":"estornudar"}},{"id":"30","word":"vomir","translation":"to vomit","translations":{"es":"vomitar"}},{"id":"31","word":"avoir des vertiges","translation":"to feel dizzy","translations":{"es":"marearse"}},{"id":"32","word":"s''évanouir","translation":"to faint","translations":{"es":"desmayarse"}},{"id":"33","word":"les frissons","translation":"chills","translations":{"es":"los escalofríos"}},{"id":"34","word":"saigner","translation":"to bleed","translations":{"es":"sangrar"}},{"id":"35","word":"examiner","translation":"to examine","translations":{"es":"examinar"}},{"id":"36","word":"diagnostiquer","translation":"to diagnose","translations":{"es":"diagnosticar"}},{"id":"37","word":"guérir","translation":"to cure / heal","translations":{"es":"curar"}},{"id":"38","word":"se remettre","translation":"to recover","translations":{"es":"recuperarse"}},{"id":"39","word":"se reposer","translation":"to rest","translations":{"es":"descansar"}},{"id":"40","word":"la santé","translation":"health","translations":{"es":"la salud"}},{"id":"41","word":"stressé / stressée","translation":"stressed","translations":{"es":"estresado / estresada"}}],"grammar":[{"structure":"à moins que + subjonctif","example":"Tu ne peux pas t''approcher du chat à moins que tu prennes tes comprimés.","en":"\"Unless\" + subjunctive","es":"«A menos que» + subjuntivo"},{"structure":"sinon + futur","example":"Prends ton médicament, sinon le médecin te donnera un traitement plus fort.","en":"\"Otherwise\" + future","es":"«Si no» + futuro"},{"structure":"il faut que + subjonctif","example":"Il faut que tu ailles voir un spécialiste.","en":"Necessity + subjunctive","es":"Necesidad + subjuntivo"},{"structure":"même si + indicatif","example":"Même si tu te reposes, tu dois prendre les médicaments.","en":"\"Even if\"","es":"«Aunque / incluso si»"},{"structure":"si + présent → futur","example":"Il ira mieux si on l''emmène à l''hôpital.","en":"Real condition","es":"Condición real"},{"structure":"dès que + passé composé","example":"Dès que je suis sorti de l''hôpital, je me suis senti fatigué.","en":"\"As soon as\" (past)","es":"«En cuanto» (pasado)"},{"structure":"discours indirect au passé","example":"Il m''a dit que j''avais la grippe et que je pouvais tomber malade si je ne me reposais pas.","en":"Reported speech","es":"Estilo indirecto"},{"structure":"passé simple (récit)","example":"Il me parla quelques minutes et me conseilla de partir en vacances.","en":"Literary past","es":"Pasado literario"}],"tips":[{"en":"\"À moins que\" takes the subjunctive (often with \"ne\" in formal French): \"à moins qu''il (ne) pleuve\".","es":"«À moins que» va con subjuntivo (a menudo con «ne» en francés formal): «à moins qu''il (ne) pleuve»."},{"en":"At the doctor: \"J''ai mal à…\", \"J''ai de la fièvre\", \"Je tousse\", \"J''ai des vertiges\", \"Je suis allergique à…\". The doctor writes \"une ordonnance\" (prescription).","es":"En el médico: «J''ai mal à…», «J''ai de la fièvre», «Je tousse», «J''ai des vertiges», «Je suis allergique à…». El médico escribe «une ordonnance» (receta)."},{"en":"\"Le médecin traitant\" = family doctor; \"les urgences\" = the ER; \"la carte Vitale\" = French health insurance card.","es":"«Le médecin traitant» = médico de cabecera; «les urgences» = urgencias; «la carte Vitale» = tarjeta sanitaria francesa."},{"en":"\"Un comprimé / une gélule\" = a tablet / capsule; \"le sirop\" = cough syrup; \"une piqûre\" = a shot.","es":"«Un comprimé / une gélule» = una pastilla / cápsula; «le sirop» = el jarabe; «une piqûre» = una inyección."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Tu ne peux pas t''approcher du chat à moins que tu prennes tes comprimés contre l''allergie.","translation":"You can''t go near the cat unless you take your allergy tablets.","translations":{"es":"No puedes acercarte al gato a menos que te tomes las pastillas para la alergia."}},{"phrase":"Mets un pansement sur cette blessure, même si elle ne saigne plus.","translation":"Put a bandage on that wound, even if it isn''t bleeding anymore.","translations":{"es":"Ponte una venda en esa herida, aunque ya no sangre."}},{"phrase":"Prends ton médicament, sinon le médecin te donnera un traitement plus fort.","translation":"Take your medicine, otherwise the doctor will give you a stronger treatment.","translations":{"es":"Tómate el medicamento, si no el médico te dará un tratamiento más fuerte."}},{"phrase":"Il faut faire cette piqûre, sinon tu auras encore des vertiges.","translation":"You need this shot, otherwise you''ll still feel dizzy.","translations":{"es":"Hay que ponerte esta inyección, si no seguirás mareado."}},{"phrase":"Il ira mieux si on l''emmène à l''hôpital.","translation":"He''ll get better if we take him to the hospital.","translations":{"es":"Mejorará si lo llevamos al hospital."}},{"phrase":"Il faut que tu ailles voir un spécialiste.","translation":"You need to see a specialist.","translations":{"es":"Tienes que ir a un especialista."}},{"phrase":"Sa blessure ne guérira pas à moins qu''elle arrête de marcher.","translation":"Her wound won''t heal unless she stops walking.","translations":{"es":"Su herida no se curará a menos que deje de caminar."}},{"phrase":"Dès que je suis sorti de l''hôpital, je me suis senti fatigué.","translation":"As soon as I left the hospital, I felt tired.","translations":{"es":"En cuanto salí del hospital, me sentí cansado."}},{"phrase":"Les enfants peuvent s''empoisonner s''ils jouent avec les produits ménagers.","translation":"Children can poison themselves if they play with cleaning products.","translations":{"es":"Los niños pueden intoxicarse si juegan con los productos de limpieza."}},{"phrase":"Je peux aller au lycée aujourd''hui ? — Non, tu n''iras pas mieux si tu ne te reposes pas.","translation":"Can I go to school today? — No, you won''t get better if you don''t rest.","translations":{"es":"¿Puedo ir al instituto hoy? — No, no mejorarás si no descansas."}},{"phrase":"Mon bébé est faible. — Quels sont les symptômes ? — Fièvre, mal de gorge et vomissements.","translation":"My baby is weak. — What are the symptoms? — Fever, sore throat and vomiting.","translations":{"es":"Mi bebé está débil. — ¿Cuáles son los síntomas? — Fiebre, dolor de garganta y vómitos."}},{"phrase":"Le médecin lui a dit de mettre une crème pour l''allergie.","translation":"The doctor told him to put on an allergy cream.","translations":{"es":"El médico le dijo que se pusiera una crema para la alergia."}},{"phrase":"Pourquoi n''est-elle pas tombée malade ? — Le médecin l''avait vaccinée.","translation":"Why didn''t she get sick? — The doctor had vaccinated her.","translations":{"es":"¿Por qué no se puso enferma? — El médico la había vacunado."}},{"phrase":"Je suis allergique à la pénicilline.","translation":"I am allergic to penicillin.","translations":{"es":"Soy alérgico a la penicilina."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Tu ne guériras pas à moins que tu te ___.\"","options":["reposes","reposerais","reposais","reposeras"],"correct":0,"explanation":"\"À moins que\" + subjunctive.","translations":{"es":{"question":"Completa: «Tu ne guériras pas à moins que tu te ___.»","explanation":"«À moins que» + subjuntivo."}}},{"id":"2","question":"Complete: \"Il faut que tu ___ chez le médecin.\"","options":["allais","ailles","iras","vas"],"correct":1,"explanation":"Aller → que tu ailles.","translations":{"es":{"question":"Completa: «Il faut que tu ___ chez le médecin.»","explanation":"Aller → que tu ailles."}}},{"id":"3","question":"Complete: \"Prends ce sirop, ___ ta toux ne passera pas.\"","options":["sinon","à moins","même si","si"],"correct":0,"explanation":"\"Sinon\" = otherwise.","translations":{"es":{"question":"Completa: «Prends ce sirop, ___ ta toux ne passera pas.»","explanation":"«Sinon» = si no."}}},{"id":"4","question":"What does the doctor give you to take to the pharmacy?","options":["un plâtre","une piqûre","une ordonnance","un pansement"],"correct":2,"explanation":"L''ordonnance = prescription.","translations":{"es":{"question":"¿Qué te da el médico para llevar a la farmacia?","explanation":"L''ordonnance = receta."}}},{"id":"5","question":"Reported: \"Vous avez la grippe.\" → Il m''a dit que j''___ la grippe.","options":["aie","aurai","avais","ai"],"correct":2,"explanation":"Present → imparfait in reported speech.","translations":{"es":{"question":"Indirecto: «Vous avez la grippe.» → Il m''a dit que j''___ la grippe.","explanation":"Presente → imperfecto en estilo indirecto."}}},{"id":"6","question":"\"Avoir des vertiges\" means…","options":["to faint","to cough","to feel dizzy","to have a fever"],"correct":2,"explanation":"S''évanouir = to faint.","translations":{"es":{"question":"«Avoir des vertiges» significa…","explanation":"S''évanouir = desmayarse.","options":["desmayarse","toser","marearse","tener fiebre"]}}},{"id":"7","question":"Complete: \"Même si tu ___ mieux, continue le traitement.\"","options":["iras","allais","vas","ailles"],"correct":2,"explanation":"\"Même si\" + indicative.","translations":{"es":{"question":"Completa: «Même si tu ___ mieux, continue le traitement.»","explanation":"«Même si» + indicativo."}}},{"id":"8","question":"Where do you go in an emergency?","options":["au cabinet","aux urgences","chez le dentiste","à la pharmacie"],"correct":1,"explanation":"Les urgences = ER.","translations":{"es":{"question":"¿Adónde vas en una emergencia?","explanation":"Les urgences = urgencias."}}}]}'::jsonb, 3),
  ('story', 'Trop de stress', '{"text":"Depuis quelques semaines, Margaux se sent faible et fatiguée, même si elle dort toute la nuit. Quand elle était adolescente, elle avait souvent mal à la tête et elle s''évanouissait parfois. Mais maintenant, c''est pire : elle a des frissons et des vertiges presque tous les jours. La semaine dernière, elle est allée voir son médecin traitant. Il lui a dit qu''elle avait sûrement un virus et lui a fait une ordonnance, mais les médicaments n''ont rien changé. Avant-hier, elle est allée voir un spécialiste, qui lui a fait faire des analyses. Il n''a rien trouvé. Heureusement, son amie Chloé, qui est psychologue, l''a appelée par hasard pour prendre de ses nouvelles. Margaux lui a raconté ses symptômes, et Chloé lui a proposé de passer la voir. Margaux pensait qu''elle allait l''examiner, mais Chloé lui parla seulement quelques minutes et lui conseilla de partir à la montagne. « Tu es folle ? » a répondu Margaux. « Non, tu es stressée. Si tu ne te reposes pas, tu vas vraiment tomber malade. À moins que tu préfères continuer comme ça ? » Margaux ne sait pas si c''est vrai, mais c''est une excellente excuse pour prendre des vacances !","translation":"For a few weeks now, Margaux has been feeling weak and tired, even though she sleeps all night. When she was a teenager, she often had headaches and sometimes fainted. But now it''s worse: she has chills and dizzy spells almost every day. Last week, she went to see her family doctor. He told her she probably had a virus and wrote her a prescription, but the medicine didn''t change anything. The day before yesterday, she went to see a specialist, who had some tests done. He found nothing. Luckily, her friend Chloé, who is a psychologist, called her by chance to see how she was. Margaux told her about her symptoms, and Chloé suggested she come over. Margaux thought she was going to examine her, but Chloé only talked to her for a few minutes and advised her to go to the mountains. “Are you crazy?” Margaux replied. “No, you''re stressed. If you don''t rest, you''ll really get sick. Unless you''d rather keep going like this?” Margaux doesn''t know if it''s true, but it''s an excellent excuse to take a vacation!","translations":{"es":"Desde hace unas semanas, Margaux se siente débil y cansada, aunque duerme toda la noche. Cuando era adolescente, a menudo le dolía la cabeza y a veces se desmayaba. Pero ahora es peor: tiene escalofríos y mareos casi todos los días. La semana pasada fue a ver a su médico de cabecera. Le dijo que seguramente tenía un virus y le hizo una receta, pero los medicamentos no cambiaron nada. Anteayer fue a un especialista, que le mandó hacer unos análisis. No encontró nada. Por suerte, su amiga Chloé, que es psicóloga, la llamó por casualidad para saber cómo estaba. Margaux le contó sus síntomas y Chloé le propuso que fuera a verla. Margaux pensaba que iba a examinarla, pero Chloé solo le habló unos minutos y le aconsejó irse a la montaña. «¿Estás loca?», respondió Margaux. «No, estás estresada. Si no descansas, vas a enfermar de verdad. ¿A menos que prefieras seguir así?» Margaux no sabe si es verdad, ¡pero es una excusa excelente para tomarse unas vacaciones!"},"highlighted_words":["même si elle dort","s''évanouissait","frissons","vertiges","médecin traitant","Il lui a dit qu''elle avait","ordonnance","spécialiste","symptômes","parla","conseilla","stressée","Si tu ne te reposes pas","À moins que tu préfères"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["J''ai","mal","à","la","gorge"],"translation":"I have a sore throat","translations":{"es":"Me duele la garganta"}},{"words":["Il","faut","que","tu","te","reposes"],"translation":"You need to rest","translations":{"es":"Tienes que descansar"}},{"words":["Prends","ce","médicament","sinon","tu","seras","malade"],"translation":"Take this medicine otherwise you''ll be sick","translations":{"es":"Tómate este medicamento, si no te pondrás enfermo"}},{"words":["Je","suis","allergique","aux","chats"],"translation":"I am allergic to cats","translations":{"es":"Soy alérgico a los gatos"}},{"words":["Elle","ira","mieux","à","moins","qu''elle","sorte"],"translation":"She''ll get better unless she goes out","translations":{"es":"Mejorará a menos que salga"}},{"words":["Le","médecin","m''a","fait","une","ordonnance"],"translation":"The doctor wrote me a prescription","translations":{"es":"El médico me hizo una receta"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I have a fever","translations":{"es":"Tengo fiebre"},"answer":"J''ai de la fièvre"},{"prompt":"I cough a lot","translations":{"es":"Toso mucho"},"answer":"Je tousse beaucoup"},{"prompt":"Where is the pharmacy?","translations":{"es":"¿Dónde está la farmacia?"},"answer":"Où est la pharmacie ?"},{"prompt":"I have a doctor''s appointment","translations":{"es":"Tengo cita con el médico"},"answer":"J''ai rendez-vous chez le médecin"},{"prompt":"Rest","translations":{"es":"Descanse"},"answer":"Reposez-vous"},{"prompt":"He fainted","translations":{"es":"Se desmayó"},"answer":"Il s''est évanoui"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 50: Envoyer des lettres et des colis
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-50', 'Envoyer des lettres et des colis', '✉️', 'Enviar cartas y paquetes', 50, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la poste","translation":"the post office","translations":{"es":"correos"}},{"id":"2","word":"le facteur / la factrice","translation":"the mail carrier","translations":{"es":"el cartero / la cartera"}},{"id":"3","word":"le courrier","translation":"mail","translations":{"es":"el correo"}},{"id":"4","word":"la lettre","translation":"the letter","translations":{"es":"la carta"}},{"id":"5","word":"la lettre recommandée","translation":"registered letter","translations":{"es":"la carta certificada"}},{"id":"6","word":"la carte postale","translation":"the postcard","translations":{"es":"la postal"}},{"id":"7","word":"le colis","translation":"the parcel","translations":{"es":"el paquete"}},{"id":"8","word":"l''enveloppe","translation":"the envelope","translations":{"es":"el sobre"}},{"id":"9","word":"le timbre","translation":"the stamp","translations":{"es":"el sello"}},{"id":"10","word":"timbrer","translation":"to stamp","translations":{"es":"poner sello"}},{"id":"11","word":"l''adresse","translation":"the address","translations":{"es":"la dirección"}},{"id":"12","word":"le code postal","translation":"the postcode","translations":{"es":"el código postal"}},{"id":"13","word":"l''expéditeur","translation":"the sender","translations":{"es":"el remitente"}},{"id":"14","word":"le destinataire","translation":"the recipient","translations":{"es":"el destinatario"}},{"id":"15","word":"la boîte aux lettres","translation":"the mailbox","translations":{"es":"el buzón"}},{"id":"16","word":"envoyer","translation":"to send","translations":{"es":"enviar"}},{"id":"17","word":"recevoir","translation":"to receive","translations":{"es":"recibir"}},{"id":"18","word":"poster","translation":"to mail","translations":{"es":"echar al correo"}},{"id":"19","word":"livrer","translation":"to deliver","translations":{"es":"entregar"}},{"id":"20","word":"la livraison","translation":"the delivery","translations":{"es":"la entrega"}},{"id":"21","word":"peser","translation":"to weigh","translations":{"es":"pesar"}},{"id":"22","word":"la balance","translation":"the scale","translations":{"es":"la báscula"}},{"id":"23","word":"lourd / lourde","translation":"heavy","translations":{"es":"pesado / pesada"}},{"id":"24","word":"léger / légère","translation":"light","translations":{"es":"ligero / ligera"}},{"id":"25","word":"par avion","translation":"by airmail","translations":{"es":"por avión"}},{"id":"26","word":"en express","translation":"express","translations":{"es":"urgente"}},{"id":"27","word":"fragile","translation":"fragile","translations":{"es":"frágil"}},{"id":"28","word":"le carton","translation":"the cardboard box","translations":{"es":"la caja de cartón"}},{"id":"29","word":"déménager","translation":"to move (house)","translations":{"es":"mudarse"}},{"id":"30","word":"signer","translation":"to sign","translations":{"es":"firmar"}}],"grammar":[{"structure":"après que + indicatif","example":"Il m''appellera après qu''il aura reçu le colis. / Je l''ai envoyé après que nous avons parlé.","en":"\"After\" + indicative (not subjunctive!)","es":"«Después de que» + indicativo (¡no subjuntivo!)"},{"structure":"imparfait + passé composé","example":"Pendant qu''il envoyait la lettre, il s''est rendu compte qu''il avait oublié l''adresse.","en":"Ongoing action interrupted","es":"Acción en curso interrumpida"},{"structure":"pendant que / quand + imparfait","example":"Le facteur a sonné pendant qu''elle dormait.","en":"Background action","es":"Acción de fondo"},{"structure":"passé simple (récit)","example":"Le facteur frappa à la porte et lui donna un colis.","en":"Literary past","es":"Pasado literario"},{"structure":"être en train d''être + participe","example":"Le colis est en train d''être livré.","en":"Passive in progress","es":"Pasiva en curso"},{"structure":"avant de + infinitif","example":"Signe les papiers avant de les envoyer.","en":"\"Before doing\"","es":"«Antes de»"},{"structure":"s''assurer que + indicatif","example":"Avant de poster la lettre, assure-toi que l''adresse est bien écrite.","en":"\"Make sure that\" + indicative","es":"«Asegurarse de que» + indicativo"},{"structure":"plus-que-parfait","example":"Il avait informé tous ses collègues de son départ.","en":"Past perfect","es":"Pluscuamperfecto"}],"tips":[{"en":"\"Après que\" takes the INDICATIVE in correct French (\"après qu''il est parti\"), even though many people use the subjunctive by analogy with \"avant que\".","es":"«Après que» va con INDICATIVO en el francés correcto («après qu''il est parti»), aunque mucha gente usa el subjuntivo por analogía con «avant que»."},{"en":"At the post office: \"un timbre\" (stamp), \"un colis\" (parcel), \"une lettre recommandée\" (registered letter), \"le code postal\" (postcode), \"l''expéditeur / le destinataire\" (sender / recipient).","es":"En correos: «un timbre» (sello), «un colis» (paquete), «une lettre recommandée» (carta certificada), «le code postal» (código postal), «l''expéditeur / le destinataire» (remitente / destinatario)."},{"en":"\"La Poste\" is the French postal service; \"le facteur / la factrice\" is the mail carrier.","es":"«La Poste» es el servicio postal francés; «le facteur / la factrice» es el cartero / la cartera."},{"en":"\"Poster une lettre\" = to mail a letter; \"la boîte aux lettres\" = the mailbox.","es":"«Poster une lettre» = echar una carta al correo; «la boîte aux lettres» = el buzón."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Il m''appellera après qu''il aura reçu le colis.","translation":"He will call me after he has received the parcel.","translations":{"es":"Me llamará después de que haya recibido el paquete."}},{"phrase":"Pendant qu''il postait la lettre, il s''est rendu compte qu''il avait oublié l''adresse.","translation":"While he was mailing the letter, he realized he had forgotten the address.","translations":{"es":"Mientras echaba la carta, se dio cuenta de que había olvidado la dirección."}},{"phrase":"Signe les papiers avant de les envoyer.","translation":"Sign the papers before sending them.","translations":{"es":"Firma los papeles antes de enviarlos."}},{"phrase":"Pendant que le facteur travaillait, on lui a volé sa camionnette.","translation":"While the mail carrier was working, his van was stolen.","translations":{"es":"Mientras el cartero trabajaba, le robaron la furgoneta."}},{"phrase":"Quand elle fermait l''enveloppe, elle a vu la lettre sur la table.","translation":"As she was sealing the envelope, she saw the letter on the table.","translations":{"es":"Cuando cerraba el sobre, vio la carta en la mesa."}},{"phrase":"Après qu''il est parti en vacances, tous les cadeaux d''anniversaire sont arrivés.","translation":"After he left on vacation, all the birthday presents arrived.","translations":{"es":"Después de que se fue de vacaciones, llegaron todos los regalos de cumpleaños."}},{"phrase":"Le facteur frappa à la porte pendant qu''elle dormait.","translation":"The mail carrier knocked at the door while she was sleeping.","translations":{"es":"El cartero llamó a la puerta mientras ella dormía."}},{"phrase":"Je suis sûre que le colis est en train d''être livré en ce moment.","translation":"I''m sure the parcel is being delivered right now.","translations":{"es":"Seguro que el paquete se está entregando ahora mismo."}},{"phrase":"Après avoir comparé les prix, j''ai décidé de t''envoyer le colis par avion.","translation":"After comparing prices, I decided to send you the parcel by airmail.","translations":{"es":"Después de comparar precios, decidí enviarte el paquete por avión."}},{"phrase":"Avant de poster la lettre, assure-toi que l''adresse est bien écrite.","translation":"Before mailing the letter, make sure the address is written correctly.","translations":{"es":"Antes de echar la carta, asegúrate de que la dirección está bien escrita."}},{"phrase":"Quand est-ce que tu as envoyé le colis ? — Je l''ai envoyé après que nous avons parlé.","translation":"When did you send the parcel? — I sent it after we talked.","translations":{"es":"¿Cuándo enviaste el paquete? — Lo envié después de que habláramos."}},{"phrase":"Elle faisait la vaisselle quand la lettre est arrivée.","translation":"She was doing the dishes when the letter arrived.","translations":{"es":"Estaba fregando cuando llegó la carta."}},{"phrase":"Combien t''a coûté le timbre ? — Ils ont pesé le colis sur la balance.","translation":"How much did the stamp cost you? — They weighed the parcel on the scale.","translations":{"es":"¿Cuánto te costó el sello? — Pesaron el paquete en la báscula."}},{"phrase":"En combien de temps une lettre arrive-t-elle au Japon ? — Environ une semaine.","translation":"How long does a letter take to get to Japan? — About a week.","translations":{"es":"¿Cuánto tarda una carta en llegar a Japón? — Una semana más o menos."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Which is correct in standard French?","options":["Après qu''il est parti, j''ai pleuré.","Après qu''il parte, j''ai pleuré.","Après qu''il soit parti, j''ai pleuré.","Après qu''il partirait, j''ai pleuré."],"correct":0,"explanation":"\"Après que\" + indicative.","translations":{"es":{"question":"¿Cuál es correcta en francés estándar?","explanation":"«Après que» + indicativo."}}},{"id":"2","question":"Complete: \"Il t''appellera après qu''il ___ le colis.\"","options":["recevait","aura reçu","ait reçu","reçoive"],"correct":1,"explanation":"Future context: futur antérieur.","translations":{"es":{"question":"Completa: «Il t''appellera après qu''il ___ le colis.»","explanation":"Contexto futuro: futur antérieur."}}},{"id":"3","question":"Complete: \"Pendant que je ___, le facteur a sonné.\"","options":["dorme","dormais","ai dormi","dormirai"],"correct":1,"explanation":"Background action: imparfait.","translations":{"es":{"question":"Completa: «Pendant que je ___, le facteur a sonné.»","explanation":"Acción de fondo: imperfecto."}}},{"id":"4","question":"Complete: \"Assure-toi que l''adresse ___ correcte.\"","options":["est","soit","était","serait"],"correct":0,"explanation":"\"S''assurer que\" + indicative.","translations":{"es":{"question":"Completa: «Assure-toi que l''adresse ___ correcte.»","explanation":"«S''assurer que» + indicativo."}}},{"id":"5","question":"What is \"le destinataire\"?","options":["the sender","the recipient","the stamp","the destination city"],"correct":1,"explanation":"L''expéditeur = the sender.","translations":{"es":{"question":"¿Qué es «le destinataire»?","explanation":"L''expéditeur = el remitente.","options":["el remitente","el destinatario","el sello","la ciudad de destino"]}}},{"id":"6","question":"\"Le colis est en train d''être livré.\" Meaning?","options":["The parcel was delivered.","The parcel is being delivered.","The parcel is a book.","The parcel will be delivered."],"correct":1,"explanation":"Passive in progress.","translations":{"es":{"question":"«Le colis est en train d''être livré.» ¿Significado?","explanation":"Pasiva en curso.","options":["El paquete fue entregado.","El paquete se está entregando.","El paquete es un libro.","El paquete será entregado."]}}},{"id":"7","question":"What do you put on an envelope to pay for postage?","options":["un timbre","un colis","un carton","une balance"],"correct":0,"explanation":"Un timbre = a stamp.","translations":{"es":{"question":"¿Qué pones en un sobre para pagar el envío?","explanation":"Un timbre = un sello."}}},{"id":"8","question":"\"Le facteur frappa à la porte.\" Which tense?","options":["présent","imparfait","passé simple","passé composé"],"correct":2,"explanation":"Spoken: \"a frappé\".","translations":{"es":{"question":"«Le facteur frappa à la porte.» ¿Qué tiempo?","explanation":"Oral: «a frappé».","options":["presente","imperfecto","passé simple","passé composé"]}}}]}'::jsonb, 3),
  ('story', 'Le grand déménagement', '{"text":"Nora travaillait à Lille, mais elle n''aimait pas vivre si loin de sa famille, qui habite à Marseille. Elle en avait assez de passer par la poste chaque fois qu''elle voulait envoyer un cadeau à ses neveux. Un jour, elle trouva un bon poste à Marseille et elle donna sa démission. Avant de partir, elle s''organisa pour envoyer ses cartons par La Poste, ce qui était moins cher que de payer un supplément de bagages dans le train. Pendant qu''elle fermait le dernier colis, son chef l''appela pour lui demander de rester. Il lui proposa un meilleur salaire. Elle refusa poliment, mais il lui dit que les portes resteraient ouvertes si elle revenait. Alors qu''elle marchait vers le taxi, la factrice lui donna une lettre. Nora fut surprise : elle avait informé tout le monde de son déménagement. C''était sa sœur, Samia, qui lui avait écrit avant de savoir la nouvelle : « Ne viens pas tout de suite, je vais me marier en juin et je veux que tu m''aides à tout préparer ici, à Marseille ! » Nora éclata de rire : elle arriverait juste à temps. Deux jours après qu''elle est arrivée, tous ses cartons étaient déjà là.","translation":"Nora worked in Lille, but she didn''t like living so far from her family, who live in Marseille. She was tired of going through the post office every time she wanted to send a gift to her nephews. One day, she found a good job in Marseille and resigned. Before leaving, she arranged to send her boxes by post, which was cheaper than paying for extra luggage on the train. While she was sealing the last parcel, her boss called to ask her to stay. He offered her a better salary. She politely refused, but he told her the doors would remain open if she came back. As she was walking to the taxi, the mail carrier handed her a letter. Nora was surprised: she had told everyone about her move. It was her sister, Samia, who had written to her before hearing the news: “Don''t come right away, I''m getting married in June and I want you to help me prepare everything here, in Marseille!” Nora burst out laughing: she would arrive just in time. Two days after she arrived, all her boxes were already there.","translations":{"es":"Nora trabajaba en Lille, pero no le gustaba vivir tan lejos de su familia, que vive en Marsella. Estaba harta de pasar por correos cada vez que quería enviarles un regalo a sus sobrinos. Un día encontró un buen puesto en Marsella y presentó su dimisión. Antes de irse, se organizó para enviar sus cajas por correo, lo que era más barato que pagar un suplemento de equipaje en el tren. Mientras cerraba el último paquete, su jefe la llamó para pedirle que se quedara. Le ofreció un sueldo mejor. Ella lo rechazó con educación, pero él le dijo que las puertas seguirían abiertas si volvía. Mientras caminaba hacia el taxi, la cartera le entregó una carta. Nora se sorprendió: había informado a todo el mundo de su mudanza. Era su hermana, Samia, que le había escrito antes de saber la noticia: «No vengas todavía, me caso en junio y quiero que me ayudes a prepararlo todo aquí, en Marsella.» Nora se echó a reír: llegaría justo a tiempo. Dos días después de que llegó, todas sus cajas ya estaban allí."},"highlighted_words":["travaillait","trouva","Avant de partir","Pendant qu''elle fermait","l''appela","resteraient","Alors qu''elle marchait","factrice","avait informé","lui avait écrit","après qu''elle est arrivée","cartons"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","voudrais","envoyer","ce","colis"],"translation":"I would like to send this parcel","translations":{"es":"Quisiera enviar este paquete"}},{"words":["Il","a","oublié","d''écrire","l''adresse"],"translation":"He forgot to write the address","translations":{"es":"Olvidó escribir la dirección"}},{"words":["Le","facteur","est","passé","pendant","que","je","dormais"],"translation":"The mail carrier came while I was sleeping","translations":{"es":"El cartero pasó mientras dormía"}},{"words":["Signe","avant","de","l''envoyer"],"translation":"Sign before sending it","translations":{"es":"Firma antes de enviarlo"}},{"words":["Je","t''appellerai","après","que","je","l''aurai","reçu"],"translation":"I''ll call you after I''ve received it","translations":{"es":"Te llamaré después de haberlo recibido"}},{"words":["Combien","coûte","un","timbre"],"translation":"How much is a stamp","translations":{"es":"¿Cuánto cuesta un sello?"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Where is the mailbox?","translations":{"es":"¿Dónde está el buzón?"},"answer":"Où est la boîte aux lettres ?"},{"prompt":"I received your postcard","translations":{"es":"He recibido tu postal"},"answer":"J''ai reçu ta carte postale"},{"prompt":"The parcel is fragile","translations":{"es":"El paquete es frágil"},"answer":"Le colis est fragile"},{"prompt":"A registered letter, please","translations":{"es":"Una carta certificada, por favor"},"answer":"Une lettre recommandée, s''il vous plaît"},{"prompt":"The parcel arrived yesterday","translations":{"es":"El paquete llegó ayer"},"answer":"Le colis est arrivé hier"},{"prompt":"By airmail, please","translations":{"es":"Por avión, por favor"},"answer":"Par avion, s''il vous plaît"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 51: Partir en croisière
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-51', 'Partir en croisière', '🛳️', 'Hacer un crucero', 51, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la croisière","translation":"the cruise","translations":{"es":"el crucero"}},{"id":"2","word":"le bateau","translation":"the boat / ship","translations":{"es":"el barco"}},{"id":"3","word":"le paquebot","translation":"the cruise ship / liner","translations":{"es":"el transatlántico"}},{"id":"4","word":"l''équipage","translation":"the crew","translations":{"es":"la tripulación"}},{"id":"5","word":"le capitaine","translation":"the captain","translations":{"es":"el capitán"}},{"id":"6","word":"la cabine","translation":"the cabin","translations":{"es":"el camarote"}},{"id":"7","word":"le pont","translation":"the deck","translations":{"es":"la cubierta"}},{"id":"8","word":"la proue","translation":"the bow","translations":{"es":"la proa"}},{"id":"9","word":"la poupe","translation":"the stern","translations":{"es":"la popa"}},{"id":"10","word":"le hublot","translation":"the porthole","translations":{"es":"el ojo de buey"}},{"id":"11","word":"la passerelle","translation":"the gangway / bridge","translations":{"es":"la pasarela / el puente de mando"}},{"id":"12","word":"l''hélice","translation":"the propeller","translations":{"es":"la hélice"}},{"id":"13","word":"l''ancre","translation":"the anchor","translations":{"es":"el ancla"}},{"id":"14","word":"lever l''ancre","translation":"to weigh anchor","translations":{"es":"levar anclas"}},{"id":"15","word":"le port","translation":"the port","translations":{"es":"el puerto"}},{"id":"16","word":"le quai","translation":"the dock","translations":{"es":"el muelle"}},{"id":"17","word":"naviguer","translation":"to sail","translations":{"es":"navegar"}},{"id":"18","word":"le canot de sauvetage","translation":"the lifeboat","translations":{"es":"el bote salvavidas"}},{"id":"19","word":"le gilet de sauvetage","translation":"the life jacket","translations":{"es":"el chaleco salvavidas"}},{"id":"20","word":"la tempête","translation":"the storm","translations":{"es":"la tormenta"}},{"id":"21","word":"couler","translation":"to sink","translations":{"es":"hundirse"}},{"id":"22","word":"le naufrage","translation":"the shipwreck","translations":{"es":"el naufragio"}},{"id":"23","word":"se noyer","translation":"to drown","translations":{"es":"ahogarse"}},{"id":"24","word":"le mal de mer","translation":"seasickness","translations":{"es":"el mareo"}},{"id":"25","word":"le requin","translation":"the shark","translations":{"es":"el tiburón"}},{"id":"26","word":"le dauphin","translation":"the dolphin","translations":{"es":"el delfín"}},{"id":"27","word":"l''iceberg","translation":"the iceberg","translations":{"es":"el iceberg"}},{"id":"28","word":"la salle de bal","translation":"the ballroom","translations":{"es":"el salón de baile"}},{"id":"29","word":"la piscine","translation":"the pool","translations":{"es":"la piscina"}},{"id":"30","word":"la salle de sport","translation":"the gym","translations":{"es":"el gimnasio"}},{"id":"31","word":"vide","translation":"empty","translations":{"es":"vacío"}},{"id":"32","word":"suffisant / suffisante","translation":"enough / sufficient","translations":{"es":"suficiente"}},{"id":"33","word":"le radar","translation":"the radar","translations":{"es":"el radar"}},{"id":"34","word":"la côte","translation":"the coast","translations":{"es":"la costa"}},{"id":"35","word":"peu profond","translation":"shallow","translations":{"es":"poco profundo"}}],"grammar":[{"structure":"futur simple","example":"Ils partiront en croisière pour deux semaines. / Quand le bateau arrivera au port, nous serons séparés.","en":"Simple future","es":"Futuro simple"},{"structure":"passé composé / imparfait","example":"Il y a eu une tempête hier soir. / Les enfants jouaient sur le pont.","en":"Event vs. background","es":"Hecho frente a fondo"},{"structure":"plus-que-parfait (récit)","example":"Nous avions attendu toute notre vie pour faire une croisière. / Nous avions économisé.","en":"Past perfect for background","es":"Pluscuamperfecto para el contexto"},{"structure":"passé simple (récit)","example":"Le ciel se couvrit, une tempête commença et les gens eurent peur.","en":"Literary past","es":"Pasado literario"},{"structure":"il y a + durée","example":"On l''a vu dans la salle de jeux il y a une minute.","en":"\"ago\"","es":"«hace» (tiempo)"},{"structure":"ne … aucun","example":"Le radar n''enregistre aucun objet étrange.","en":"\"No / not any\"","es":"«Ningún»"},{"structure":"afin de / grâce à","example":"L''équipage essayait de dégager le pont afin de faire son travail. / Grâce aux canots de sauvetage…","en":"Purpose and positive cause","es":"Finalidad y causa positiva"}],"tips":[{"en":"The passé simple (il commença, ils eurent peur) is the literary past used in written stories; in conversation, use the passé composé.","es":"El passé simple (il commença, ils eurent peur) es el pasado literario de los relatos escritos; al hablar se usa el passé composé."},{"en":"Ship words: \"la proue\" (bow), \"la poupe\" (stern), \"le pont\" (deck), \"la cabine\" (cabin), \"le hublot\" (porthole), \"le canot de sauvetage\" (lifeboat), \"le gilet de sauvetage\" (life jacket).","es":"En el barco: «la proue» (proa), «la poupe» (popa), «le pont» (cubierta), «la cabine» (camarote), «le hublot» (ojo de buey), «le canot de sauvetage» (bote salvavidas), «le gilet de sauvetage» (chaleco salvavidas)."},{"en":"\"Lever l''ancre\" = to weigh anchor (l''ancre = anchor; l''encre = ink!).","es":"«Lever l''ancre» = levar anclas (l''ancre = ancla; ¡l''encre = tinta!)."},{"en":"\"Le mal de mer\" = seasickness; \"faire naufrage\" = to be shipwrecked; \"couler\" = to sink.","es":"«Le mal de mer» = mareo; «faire naufrage» = naufragar; «couler» = hundirse."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Nous partons en croisière !","translation":"We''re going on a cruise!","translations":{"es":"¡Nos vamos de crucero!"}},{"phrase":"Elle nage très bien. Moi, je ne sais pas nager.","translation":"She swims very well. I can''t swim.","translations":{"es":"Ella nada muy bien. Yo no sé nadar."}},{"phrase":"Ils partiront en croisière pendant deux semaines.","translation":"They will go on a cruise for two weeks.","translations":{"es":"Se irán de crucero dos semanas."}},{"phrase":"Je t''attends sur le pont.","translation":"I''ll wait for you on deck.","translations":{"es":"Te espero en la cubierta."}},{"phrase":"On se retrouve dans la salle de bal à vingt heures pile.","translation":"Let''s meet in the ballroom at 8 p.m. sharp.","translations":{"es":"Nos vemos en el salón de baile a las ocho en punto."}},{"phrase":"La salle à manger est pleine : mangeons plutôt sur la terrasse.","translation":"The dining room is full: let''s eat on the terrace instead.","translations":{"es":"El comedor está lleno: mejor comamos en la terraza."}},{"phrase":"On l''a vu dans la salle de jeux il y a une minute.","translation":"He was seen in the game room a minute ago.","translations":{"es":"Lo vieron en la sala de juegos hace un minuto."}},{"phrase":"Il y a eu une tempête hier soir.","translation":"There was a storm last night.","translations":{"es":"Anoche hubo una tormenta."}},{"phrase":"Il n''y a pas assez de canots de sauvetage !","translation":"There aren''t enough lifeboats!","translations":{"es":"¡No hay suficientes botes salvavidas!"}},{"phrase":"Elle a passé des heures à regarder la mer par le hublot.","translation":"She spent hours looking at the sea through the porthole.","translations":{"es":"Se pasó horas mirando el mar por el ojo de buey."}},{"phrase":"Le capitaine nous a mariés sur le bateau.","translation":"The captain married us on the ship.","translations":{"es":"El capitán nos casó en el barco."}},{"phrase":"Pourquoi le canot ne s''approche-t-il pas de la côte ? — Parce que c''est peu profond.","translation":"Why isn''t the boat getting closer to the coast? — Because it''s shallow.","translations":{"es":"¿Por qué no se acerca el bote a la costa? — Porque hay poca profundidad."}},{"phrase":"Tu as vu les dauphins ? Ils nageaient devant la proue !","translation":"Did you see the dolphins? They were swimming in front of the bow!","translations":{"es":"¿Viste los delfines? ¡Nadaban delante de la proa!"}},{"phrase":"Tu aimerais faire une croisière ? — Oui, mais j''ai le mal de mer.","translation":"Would you like to go on a cruise? — Yes, but I get seasick.","translations":{"es":"¿Te gustaría hacer un crucero? — Sí, pero me mareo."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"What is \"la poupe\"?","options":["the stern (back)","the deck","the bow (front)","the cabin"],"correct":0,"explanation":"La proue = the front.","translations":{"es":{"question":"¿Qué es «la poupe»?","explanation":"La proue = la parte delantera.","options":["la popa (parte trasera)","la cubierta","la proa (parte delantera)","el camarote"]}}},{"id":"2","question":"\"Lever l''ancre\" means…","options":["to raise the flag","to weigh anchor","to write with ink","to sink"],"correct":1,"explanation":"L''ancre (anchor) ≠ l''encre (ink).","translations":{"es":{"question":"«Lever l''ancre» significa…","explanation":"L''ancre (ancla) ≠ l''encre (tinta).","options":["izar la bandera","levar anclas","escribir con tinta","hundirse"]}}},{"id":"3","question":"Which sentence gives the background of a story?","options":["Une tempête commença.","Nous avions économisé pendant des années.","Le bateau coula.","On nous sauva."],"correct":1,"explanation":"Plus-que-parfait sets the earlier background.","translations":{"es":{"question":"¿Qué frase da el contexto de un relato?","explanation":"El pluscuamperfecto da el contexto anterior."}}},{"id":"4","question":"\"Les gens eurent peur.\" Spoken equivalent?","options":["Les gens ont eu peur.","Les gens avaient peur.","Les gens auront peur.","Les gens ont peur."],"correct":0,"explanation":"Passé simple → passé composé.","translations":{"es":{"question":"«Les gens eurent peur.» ¿Equivalente oral?","explanation":"Passé simple → passé composé."}}},{"id":"5","question":"Complete: \"Quand le bateau ___ au port, nous descendrons.\"","options":["arrive","arrivera","arrivait","arriverait"],"correct":1,"explanation":"Future after \"quand\".","translations":{"es":{"question":"Completa: «Quand le bateau ___ au port, nous descendrons.»","explanation":"Futuro tras «quand»."}}},{"id":"6","question":"What do you wear in an emergency at sea?","options":["un hublot","une hélice","un gilet de sauvetage","une ancre"],"correct":2,"explanation":"Life jacket.","translations":{"es":{"question":"¿Qué te pones en una emergencia en el mar?","explanation":"Chaleco salvavidas."}}},{"id":"7","question":"Complete: \"Le radar n''enregistre ___ objet.\"","options":["rien","pas","aucun","jamais"],"correct":2,"explanation":"Ne … aucun + noun.","translations":{"es":{"question":"Completa: «Le radar n''enregistre ___ objet.»","explanation":"Ne … aucun + sustantivo."}}},{"id":"8","question":"\"Le mal de mer\" is…","options":["pollution","a sea monster","seasickness","a wave"],"correct":2,"explanation":"Avoir le mal de mer.","translations":{"es":{"question":"«Le mal de mer» es…","explanation":"Avoir le mal de mer.","options":["la contaminación","un monstruo marino","el mareo","una ola"]}}}]}'::jsonb, 3),
  ('story', 'La croisière dans les fjords', '{"text":"Mon mari et moi avions attendu toute notre vie pour faire une croisière. Quand il prit sa retraite, le moment arriva enfin. Nos enfants étaient grands, et ils n''avaient pas voulu nous accompagner. Nous avions économisé pendant des années pour faire un voyage de deux semaines dans les fjords de Norvège. Notre cabine était spacieuse et les lits étaient confortables. Tous les matins, nous marchions sur le pont, et le soir, nous dansions sur de vieilles chansons dans la salle de bal. Tout allait bien. Mais un soir, le ciel se couvrit et une terrible tempête commença. On nous demanda de retourner dans nos cabines. Tout à coup, les lumières s''éteignirent et les moteurs s''arrêtèrent. Les passagers eurent peur et commencèrent à crier. Les enfants pleuraient, et l''équipage essayait de garder tout le monde calme afin de faire son travail. Le capitaine annonça qu''il fallait mettre les gilets de sauvetage. Heureusement, il y avait assez de canots pour tout le monde, mais ce ne fut pas nécessaire : deux heures plus tard, les moteurs repartirent. Le lendemain, la mer était calme et des dauphins nageaient devant la proue. Quelle aventure !","translation":"My husband and I had waited our whole lives to go on a cruise. When he retired, the moment finally came. Our children were grown up, and they hadn''t wanted to come with us. We had saved for years for a two-week trip in the fjords of Norway. Our cabin was spacious and the beds were comfortable. Every morning we walked on the deck, and in the evening we danced to old songs in the ballroom. Everything was going well. But one evening, the sky clouded over and a terrible storm began. We were asked to go back to our cabins. Suddenly, the lights went out and the engines stopped. The passengers got scared and started shouting. Children were crying, and the crew was trying to keep everyone calm so they could do their job. The captain announced that we had to put on life jackets. Fortunately, there were enough lifeboats for everyone, but they weren''t needed: two hours later, the engines started again. The next day, the sea was calm and dolphins were swimming in front of the bow. What an adventure!","translations":{"es":"Mi marido y yo habíamos esperado toda la vida para hacer un crucero. Cuando él se jubiló, por fin llegó el momento. Nuestros hijos ya eran mayores y no habían querido acompañarnos. Habíamos ahorrado durante años para un viaje de dos semanas por los fiordos de Noruega. Nuestro camarote era espacioso y las camas, cómodas. Todas las mañanas paseábamos por la cubierta y, por la noche, bailábamos canciones antiguas en el salón de baile. Todo iba bien. Pero una noche el cielo se cubrió y empezó una tormenta terrible. Nos pidieron que volviéramos a los camarotes. De repente, se apagaron las luces y se pararon los motores. Los pasajeros tuvieron miedo y empezaron a gritar. Los niños lloraban y la tripulación intentaba mantener la calma de todos para poder hacer su trabajo. El capitán anunció que había que ponerse los chalecos salvavidas. Por suerte había botes suficientes para todos, pero no hizo falta: dos horas después, los motores arrancaron de nuevo. Al día siguiente el mar estaba en calma y unos delfines nadaban delante de la proa. ¡Menuda aventura!"},"highlighted_words":["avions attendu","prit sa retraite","n''avaient pas voulu","avions économisé","cabine","pont","salle de bal","se couvrit","commença","eurent peur","afin de","gilets de sauvetage","canots","proue"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Nous","partons","en","croisière"],"translation":"We''re going on a cruise","translations":{"es":"Nos vamos de crucero"}},{"words":["Je","ne","sais","pas","nager"],"translation":"I can''t swim","translations":{"es":"No sé nadar"}},{"words":["Il","y","a","eu","une","tempête","hier"],"translation":"There was a storm yesterday","translations":{"es":"Ayer hubo una tormenta"}},{"words":["Les","dauphins","nageaient","devant","la","proue"],"translation":"The dolphins were swimming in front of the bow","translations":{"es":"Los delfines nadaban delante de la proa"}},{"words":["J''ai","le","mal","de","mer"],"translation":"I''m seasick","translations":{"es":"Estoy mareado"}},{"words":["Mettez","vos","gilets","de","sauvetage"],"translation":"Put on your life jackets","translations":{"es":"Pónganse los chalecos salvavidas"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Where is my cabin?","translations":{"es":"¿Dónde está mi camarote?"},"answer":"Où est ma cabine ?"},{"prompt":"The ship leaves at noon","translations":{"es":"El barco sale a mediodía"},"answer":"Le bateau part à midi"},{"prompt":"See you on deck","translations":{"es":"Nos vemos en la cubierta"},"answer":"On se voit sur le pont"},{"prompt":"The ship sank","translations":{"es":"El barco se hundió"},"answer":"Le bateau a coulé"},{"prompt":"The sea is calm","translations":{"es":"El mar está en calma"},"answer":"La mer est calme"},{"prompt":"I''m afraid of sharks","translations":{"es":"Tengo miedo de los tiburones"},"answer":"J''ai peur des requins"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 52: Voyager en train
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-52', 'Voyager en train', '🚂', 'Viajar en tren', 52, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le train","translation":"the train","translations":{"es":"el tren"}},{"id":"2","word":"la gare","translation":"the train station","translations":{"es":"la estación"}},{"id":"3","word":"le quai","translation":"the platform","translations":{"es":"el andén"}},{"id":"4","word":"la voie (ferrée)","translation":"the track","translations":{"es":"la vía"}},{"id":"5","word":"le wagon","translation":"the car / coach","translations":{"es":"el vagón"}},{"id":"6","word":"le wagon-lit","translation":"the sleeper car","translations":{"es":"el coche cama"}},{"id":"7","word":"la couchette","translation":"the berth","translations":{"es":"la litera"}},{"id":"8","word":"le compartiment","translation":"the compartment","translations":{"es":"el compartimento"}},{"id":"9","word":"le wagon-restaurant","translation":"the dining car","translations":{"es":"el vagón restaurante"}},{"id":"10","word":"le contrôleur","translation":"the ticket inspector","translations":{"es":"el revisor"}},{"id":"11","word":"le conducteur","translation":"the train driver","translations":{"es":"el maquinista"}},{"id":"12","word":"le panneau d''affichage","translation":"the departures board","translations":{"es":"el panel de información"}},{"id":"13","word":"le retard","translation":"the delay","translations":{"es":"el retraso"}},{"id":"14","word":"la correspondance","translation":"the connection","translations":{"es":"el transbordo"}},{"id":"15","word":"le chariot à bagages","translation":"the luggage cart","translations":{"es":"el carrito de equipaje"}},{"id":"16","word":"les objets trouvés","translation":"lost and found","translations":{"es":"objetos perdidos"}},{"id":"17","word":"la consigne","translation":"left luggage","translations":{"es":"la consigna"}},{"id":"18","word":"monter dans","translation":"to get on","translations":{"es":"subir a"}},{"id":"19","word":"descendre de","translation":"to get off","translations":{"es":"bajar de"}},{"id":"20","word":"dérailler","translation":"to derail","translations":{"es":"descarrilar"}},{"id":"21","word":"se renverser","translation":"to overturn","translations":{"es":"volcar"}},{"id":"22","word":"se détacher","translation":"to come loose","translations":{"es":"soltarse"}},{"id":"23","word":"égaré / égarée","translation":"lost","translations":{"es":"extraviado / extraviada"}},{"id":"24","word":"l''obscurité","translation":"darkness","translations":{"es":"la oscuridad"}},{"id":"25","word":"le courage","translation":"courage","translations":{"es":"el valor"}},{"id":"26","word":"mal à l''aise","translation":"uncomfortable","translations":{"es":"incómodo"}},{"id":"27","word":"la dame","translation":"the lady","translations":{"es":"la señora"}},{"id":"28","word":"l''enfant","translation":"the child","translations":{"es":"el niño"}},{"id":"29","word":"le pire","translation":"the worst","translations":{"es":"lo peor"}},{"id":"30","word":"cacher","translation":"to hide","translations":{"es":"esconder"}},{"id":"31","word":"blessé / blessée","translation":"injured","translations":{"es":"herido / herida"}}],"grammar":[{"structure":"adjectifs démonstratifs","example":"Cette dame, ces femmes, cet enfant, ce train","en":"Demonstrative adjectives","es":"Adjetivos demostrativos"},{"structure":"démonstratif + relatif","example":"Cette femme qui est au bureau des objets trouvés est ma belle-sœur. / Ce n''est pas celui où elles doivent voyager.","en":"Demonstratives with relative clauses","es":"Demostrativos con relativas"},{"structure":"superlatif","example":"Le train est le moyen de transport le plus courant en Europe.","en":"Superlatives","es":"Superlativos"},{"structure":"futur","example":"Le train partira dans dix minutes. / Je le ferai quand le bureau sera vide.","en":"Simple future","es":"Futuro simple"},{"structure":"passé simple (récit)","example":"Le train partit tard et s''arrêta au milieu de la nuit.","en":"Literary past","es":"Pasado literario"},{"structure":"plus-que-parfait + accord","example":"C''était la femme que j''avais remarquée sur le quai.","en":"Past perfect with agreement","es":"Pluscuamperfecto con concordancia"},{"structure":"afin que + subjonctif","example":"Nous avons distribué des couvertures afin que les gens se reposent.","en":"\"So that\" + subjunctive","es":"«Para que» + subjuntivo"}],"tips":[{"en":"The passé simple (il commença, ils eurent peur) is the literary past used in written stories; in conversation, use the passé composé.","es":"El passé simple (il commença, ils eurent peur) es el pasado literario de los relatos escritos; al hablar se usa el passé composé."},{"en":"Train words: \"le quai\" (platform), \"la voie\" (track), \"le wagon / la voiture\" (car), \"la couchette\" (berth), \"le TGV\" (high-speed train), \"composter\" (to validate a paper ticket).","es":"En el tren: «le quai» (andén), «la voie» (vía), «le wagon / la voiture» (vagón), «la couchette» (litera), «le TGV» (tren de alta velocidad), «composter» (validar un billete de papel)."},{"en":"\"Cet\" is used before a masculine noun starting with a vowel or mute h: \"cet enfant\", \"cet homme\".","es":"«Cet» se usa delante de un sustantivo masculino que empieza por vocal o h muda: «cet enfant», «cet homme»."},{"en":"\"Les objets trouvés\" = lost and found; \"la consigne\" = left-luggage office.","es":"«Les objets trouvés» = objetos perdidos; «la consigne» = consigna."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Il y a des vaches sur la voie ferrée !","translation":"There are cows on the railway track!","translations":{"es":"¡Hay vacas en la vía del tren!"}},{"phrase":"Les couchettes sont toutes réservées.","translation":"The berths are all booked.","translations":{"es":"Las literas están todas reservadas."}},{"phrase":"Elle était sur le quai avec ses trois chiens.","translation":"She was on the platform with her three dogs.","translations":{"es":"Estaba en el andén con sus tres perros."}},{"phrase":"Cette femme qui est aux objets trouvés est ma belle-sœur.","translation":"That woman at the lost and found is my sister-in-law.","translations":{"es":"Esa mujer que está en objetos perdidos es mi cuñada."}},{"phrase":"Ces femmes montent dans un wagon qui n''est pas celui où elles doivent voyager.","translation":"Those women are getting on a car that isn''t the one they''re supposed to travel in.","translations":{"es":"Esas mujeres se suben a un vagón que no es en el que deben viajar."}},{"phrase":"Les dames d''abord.","translation":"Ladies first.","translations":{"es":"Las damas primero."}},{"phrase":"Cette dame dort sur ma couchette !","translation":"That lady is sleeping in my berth!","translations":{"es":"¡Esa señora está durmiendo en mi litera!"}},{"phrase":"Cet enfant me rend fou !","translation":"This child is driving me crazy!","translations":{"es":"¡Este niño me está volviendo loco!"}},{"phrase":"Je veux les deux places côté fenêtre.","translation":"I want the two window seats.","translations":{"es":"Quiero los dos asientos de ventanilla."}},{"phrase":"Le train partira dans dix minutes.","translation":"The train will leave in ten minutes.","translations":{"es":"El tren saldrá dentro de diez minutos."}},{"phrase":"Le train est le moyen de transport le plus courant en Europe.","translation":"The train is the most common means of transport in Europe.","translations":{"es":"El tren es el medio de transporte más común en Europa."}},{"phrase":"Le train que tu attends est en retard.","translation":"The train you are waiting for is late.","translations":{"es":"El tren que esperas lleva retraso."}},{"phrase":"Tu as regardé le panneau d''affichage ? — Non, il m''a dit qu''il arrivait à dix heures.","translation":"Did you check the board? — No, he told me he was arriving at ten.","translations":{"es":"¿Has mirado el panel? — No, me dijo que llegaba a las diez."}},{"phrase":"Où est ton bagage ? — Je ne sais pas, je le demanderai à la consigne quand il n''y aura plus personne.","translation":"Where''s your luggage? — I don''t know, I''ll ask at left luggage when there''s no one left.","translations":{"es":"¿Dónde está tu equipaje? — No lo sé, lo preguntaré en la consigna cuando no haya nadie."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"___ enfant est très sage.\"","options":["Cet","Ces","Cette","Ce"],"correct":0,"explanation":"Masculine + vowel: cet.","translations":{"es":{"question":"Completa: «___ enfant est très sage.»","explanation":"Masculino + vocal: cet."}}},{"id":"2","question":"Complete: \"___ dames attendent le train.\"","options":["Cet","Ces","Ce","Cettes"],"correct":1,"explanation":"Plural: ces.","translations":{"es":{"question":"Completa: «___ dames attendent le train.»","explanation":"Plural: ces."}}},{"id":"3","question":"Where do you wait for the train?","options":["au wagon-lit","sur le quai","dans la consigne","sur la voie"],"correct":1,"explanation":"Le quai = platform.","translations":{"es":{"question":"¿Dónde esperas el tren?","explanation":"Le quai = andén."}}},{"id":"4","question":"Complete: \"C''est la femme que j''avais ___ sur le quai.\"","options":["remarqués","remarquer","remarquée","remarqué"],"correct":2,"explanation":"Agreement with \"que\" (la femme) before avoir.","translations":{"es":{"question":"Completa: «C''est la femme que j''avais ___ sur le quai.»","explanation":"Concordancia con «que» (la femme) antes de avoir."}}},{"id":"5","question":"Complete: \"Le TGV est le train ___ rapide de France.\"","options":["la plus","très","le plus","plus"],"correct":2,"explanation":"Superlative: le plus + adjective + de.","translations":{"es":{"question":"Completa: «Le TGV est le train ___ rapide de France.»","explanation":"Superlativo: le plus + adjetivo + de."}}},{"id":"6","question":"\"Les objets trouvés\" is…","options":["the waiting room","the ticket office","lost and found","a shop"],"correct":2,"explanation":"Where you look for lost items.","translations":{"es":{"question":"«Les objets trouvés» es…","explanation":"Donde buscas cosas perdidas.","options":["la sala de espera","la taquilla","objetos perdidos","una tienda"]}}},{"id":"7","question":"Complete: \"Il a distribué des couvertures afin que les gens ___.\"","options":["se reposeront","se reposaient","se reposent","se reposent-ils"],"correct":2,"explanation":"\"Afin que\" + subjunctive.","translations":{"es":{"question":"Completa: «Il a distribué des couvertures afin que les gens ___.»","explanation":"«Afin que» + subjuntivo."}}},{"id":"8","question":"\"Le train partit tard.\" Which tense?","options":["passé simple","imparfait","futur","présent"],"correct":0,"explanation":"Spoken: \"est parti\".","translations":{"es":{"question":"«Le train partit tard.» ¿Qué tiempo?","explanation":"Oral: «est parti».","options":["passé simple","imperfecto","futuro","presente"]}}}]}'::jsonb, 3),
  ('story', 'Une nuit dans le train', '{"text":"En décembre, Antoine prit le train de nuit de Paris à Nice pour passer Noël chez ses parents. Sur le quai, il avait remarqué une jeune femme aux cheveux roux qui portait un énorme sac à dos et un violon. Le train partit tard le soir. Vers deux heures du matin, il s''arrêta brusquement au milieu de nulle part : un arbre était tombé sur la voie à cause de la tempête. Les lumières s''éteignirent. Dans l''obscurité, certains passagers avaient peur et imaginaient le pire. Antoine sortit dans le couloir avec sa lampe de poche. C''est là qu''il retrouva la jeune femme qu''il avait remarquée sur le quai. Elle s''appelait Léna et elle était musicienne. Ensemble, ils aidèrent le contrôleur à distribuer des couvertures afin que les familles se reposent. Puis Léna sortit son violon et joua quelques chansons de Noël. Les enfants arrêtèrent de pleurer et tout le monde se mit à chanter. Le train repartit à l''aube, avec six heures de retard. En arrivant à Nice, Léna donna son numéro à Antoine. « C''est le meilleur retard de ma vie », pensa-t-il.","translation":"In December, Antoine took the night train from Paris to Nice to spend Christmas with his parents. On the platform, he had noticed a red-haired young woman carrying a huge backpack and a violin. The train left late in the evening. Around two in the morning, it stopped suddenly in the middle of nowhere: a tree had fallen on the track because of the storm. The lights went out. In the dark, some passengers were scared and imagined the worst. Antoine went out into the corridor with his flashlight. That''s where he found the young woman he had noticed on the platform. Her name was Léna and she was a musician. Together, they helped the ticket inspector hand out blankets so that families could rest. Then Léna took out her violin and played a few Christmas songs. The children stopped crying and everyone started singing. The train set off again at dawn, six hours late. When they arrived in Nice, Léna gave Antoine her number. “It''s the best delay of my life,” he thought.","translations":{"es":"En diciembre, Antoine tomó el tren nocturno de París a Niza para pasar la Navidad con sus padres. En el andén se había fijado en una joven pelirroja que llevaba una mochila enorme y un violín. El tren salió tarde por la noche. Hacia las dos de la madrugada se detuvo de golpe en medio de la nada: había caído un árbol en la vía por la tormenta. Se apagaron las luces. En la oscuridad, algunos pasajeros tenían miedo y se imaginaban lo peor. Antoine salió al pasillo con su linterna. Fue allí donde se encontró con la joven en la que se había fijado en el andén. Se llamaba Léna y era música. Juntos ayudaron al revisor a repartir mantas para que las familias pudieran descansar. Luego Léna sacó su violín y tocó unas canciones de Navidad. Los niños dejaron de llorar y todo el mundo se puso a cantar. El tren volvió a arrancar al amanecer, con seis horas de retraso. Al llegar a Niza, Léna le dio su número a Antoine. «Es el mejor retraso de mi vida», pensó."},"highlighted_words":["prit le train","quai","avait remarqué","partit","s''arrêta","était tombé sur la voie","s''éteignirent","le pire","qu''il avait remarquée","aidèrent le contrôleur","afin que les familles se reposent","retard"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Le","train","partira","dans","dix","minutes"],"translation":"The train will leave in ten minutes","translations":{"es":"El tren saldrá dentro de diez minutos"}},{"words":["Cette","dame","est","sur","ma","couchette"],"translation":"That lady is in my berth","translations":{"es":"Esa señora está en mi litera"}},{"words":["Le","train","est","en","retard"],"translation":"The train is late","translations":{"es":"El tren lleva retraso"}},{"words":["On","se","retrouve","sur","le","quai"],"translation":"Let''s meet on the platform","translations":{"es":"Nos vemos en el andén"}},{"words":["Cet","enfant","a","perdu","sa","mère"],"translation":"This child has lost his mother","translations":{"es":"Este niño ha perdido a su madre"}},{"words":["Je","voudrais","une","place","côté","fenêtre"],"translation":"I would like a window seat","translations":{"es":"Quisiera un asiento de ventanilla"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Which platform does the train leave from?","translations":{"es":"¿De qué andén sale el tren?"},"answer":"De quel quai part le train ?"},{"prompt":"A ticket to Nice, please","translations":{"es":"Un billete para Niza, por favor"},"answer":"Un billet pour Nice, s''il vous plaît"},{"prompt":"The train is two hours late","translations":{"es":"El tren lleva dos horas de retraso"},"answer":"Le train a deux heures de retard"},{"prompt":"I lost my suitcase","translations":{"es":"He perdido mi maleta"},"answer":"J''ai perdu ma valise"},{"prompt":"This train goes directly to Paris","translations":{"es":"Este tren va directo a París"},"answer":"Ce train va directement à Paris"},{"prompt":"I slept badly","translations":{"es":"He dormido mal"},"answer":"J''ai mal dormi"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 53: Au bar
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-53', 'Au bar', '🍸', 'En el bar', 53, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le bar","translation":"the bar","translations":{"es":"el bar"}},{"id":"2","word":"le pub","translation":"the pub","translations":{"es":"el pub"}},{"id":"3","word":"le comptoir","translation":"the counter","translations":{"es":"la barra"}},{"id":"4","word":"le barman / la barmaid","translation":"the bartender","translations":{"es":"el camarero / la camarera"}},{"id":"5","word":"la boisson","translation":"the drink","translations":{"es":"la bebida"}},{"id":"6","word":"la bière","translation":"beer","translations":{"es":"la cerveza"}},{"id":"7","word":"un demi","translation":"a small draft beer","translations":{"es":"una caña"}},{"id":"8","word":"le vin","translation":"wine","translations":{"es":"el vino"}},{"id":"9","word":"le cocktail","translation":"the cocktail","translations":{"es":"el cóctel"}},{"id":"10","word":"le whisky","translation":"whisky","translations":{"es":"el whisky"}},{"id":"11","word":"l''alcool","translation":"alcohol","translations":{"es":"el alcohol"}},{"id":"12","word":"le degré","translation":"the proof / degree","translations":{"es":"el grado"}},{"id":"13","word":"fort / forte","translation":"strong","translations":{"es":"fuerte"}},{"id":"14","word":"doux / douce","translation":"sweet / mild","translations":{"es":"dulce / suave"}},{"id":"15","word":"le goût","translation":"taste","translations":{"es":"el sabor / el gusto"}},{"id":"16","word":"goûter","translation":"to taste","translations":{"es":"probar"}},{"id":"17","word":"trinquer / porter un toast","translation":"to toast","translations":{"es":"brindar"}},{"id":"18","word":"Santé !","translation":"Cheers!","translations":{"es":"¡Salud!"}},{"id":"19","word":"la tournée","translation":"the round","translations":{"es":"la ronda"}},{"id":"20","word":"offrir","translation":"to offer / buy (a drink)","translations":{"es":"invitar"}},{"id":"21","word":"l''enterrement de vie de garçon","translation":"the bachelor party","translations":{"es":"la despedida de soltero"}},{"id":"22","word":"ivre / soûl","translation":"drunk","translations":{"es":"borracho"}},{"id":"23","word":"s''enivrer","translation":"to get drunk","translations":{"es":"emborracharse"}},{"id":"24","word":"la gueule de bois","translation":"the hangover","translations":{"es":"la resaca"}},{"id":"25","word":"alcoolique","translation":"alcoholic","translations":{"es":"alcohólico"}},{"id":"26","word":"le temps libre","translation":"free time","translations":{"es":"el tiempo libre"}},{"id":"27","word":"ennuyeux / ennuyeuse","translation":"boring","translations":{"es":"aburrido / aburrida"}},{"id":"28","word":"calme / tranquille","translation":"quiet","translations":{"es":"tranquilo"}},{"id":"29","word":"enceinte","translation":"pregnant","translations":{"es":"embarazada"}},{"id":"30","word":"la grossesse","translation":"pregnancy","translations":{"es":"el embarazo"}},{"id":"31","word":"de mauvaise humeur","translation":"in a bad mood","translations":{"es":"de mal humor"}},{"id":"32","word":"avoir sommeil","translation":"to be sleepy","translations":{"es":"tener sueño"}},{"id":"33","word":"se rendre compte","translation":"to realize","translations":{"es":"darse cuenta"}}],"grammar":[{"structure":"impératif (nous)","example":"Prenons une bière fraîche ! Portons un toast !","en":"Let''s…","es":"Imperativo con «nous»"},{"structure":"imparfait (description)","example":"J''étais seul au comptoir. / Elle avait un grand verre à la main.","en":"Imperfect for descriptions","es":"Imperfecto para descripciones"},{"structure":"être en train de (passé)","example":"Il était en train de devenir agressif.","en":"Ongoing change in the past","es":"Cambio en curso en el pasado"},{"structure":"comme si + imparfait","example":"Il buvait du whisky comme si c''était de l''eau.","en":"\"As if\" + imperfect","es":"«Como si» + imperfecto"},{"structure":"pour que / éviter que + subjonctif","example":"Elle essayait de le convaincre pour qu''il n''aille plus au bar.","en":"Purpose / avoidance + subjunctive","es":"Finalidad / evitar + subjuntivo"},{"structure":"depuis + présent","example":"Sa femme est enceinte depuis six mois.","en":"Ongoing since","es":"Desde hace"},{"structure":"se rendre compte que","example":"Il s''est rendu compte qu''il pouvait faire du mal à ceux qu''il aimait.","en":"\"To realize\"","es":"«Darse cuenta de que»"},{"structure":"passé simple (récit)","example":"La situation devint pire. Il commença à retourner au bar.","en":"Literary past","es":"Pasado literario"}],"tips":[{"en":"The passé simple (il commença, ils eurent peur) is the literary past used in written stories; in conversation, use the passé composé.","es":"El passé simple (il commença, ils eurent peur) es el pasado literario de los relatos escritos; al hablar se usa el passé composé."},{"en":"At the bar: \"un demi\" (a small draft beer), \"un verre de vin\", \"une carafe d''eau\" (free tap water), \"C''est ma tournée !\" (This round is on me!), \"Santé !\" (Cheers!).","es":"En el bar: «un demi» (una caña), «un verre de vin», «une carafe d''eau» (agua del grifo gratis), «C''est ma tournée !» (¡Esta ronda la pago yo!), «Santé !» (¡Salud!)."},{"en":"\"Un enterrement de vie de garçon / de jeune fille\" = bachelor / bachelorette party.","es":"«Un enterrement de vie de garçon / de jeune fille» = despedida de soltero / soltera."},{"en":"\"La gueule de bois\" = hangover (informal). \"Être ivre / soûl\" = to be drunk.","es":"«La gueule de bois» = la resaca (coloquial). «Être ivre / soûl» = estar borracho."},{"en":"\"C''est offert par la maison\" = it''s on the house.","es":"«C''est offert par la maison» = invita la casa."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Prenons une bière fraîche !","translation":"Let''s have a cold beer!","translations":{"es":"¡Tomemos una cerveza fría!"}},{"phrase":"C''est un petit bar très tranquille.","translation":"It''s a very quiet little bar.","translations":{"es":"Es un barecito muy tranquilo."}},{"phrase":"Cette chanson n''est pas bien pour danser.","translation":"This song isn''t good for dancing.","translations":{"es":"Esta canción no es buena para bailar."}},{"phrase":"J''étais seul, debout au comptoir.","translation":"I was alone, standing at the counter.","translations":{"es":"Estaba solo, de pie en la barra."}},{"phrase":"Il était en train de parler avec cette grande fille.","translation":"He was talking with that tall girl.","translations":{"es":"Estaba hablando con esa chica alta."}},{"phrase":"Le barman lui a servi une boisson très forte.","translation":"The bartender served him a very strong drink.","translations":{"es":"El camarero le sirvió una bebida muy fuerte."}},{"phrase":"Il n''est pas venu à mon enterrement de vie de garçon.","translation":"He didn''t come to my bachelor party.","translations":{"es":"No vino a mi despedida de soltero."}},{"phrase":"Portons un toast au futur marié !","translation":"Let''s toast the groom-to-be!","translations":{"es":"¡Brindemos por el futuro novio!"}},{"phrase":"Il buvait du whisky comme si c''était de l''eau.","translation":"He was drinking whisky as if it were water.","translations":{"es":"Bebía whisky como si fuera agua."}},{"phrase":"J''ai une terrible gueule de bois.","translation":"I have a terrible hangover.","translations":{"es":"Tengo una resaca terrible."}},{"phrase":"En Angleterre, les bars s''appellent des pubs.","translation":"In England, bars are called pubs.","translations":{"es":"En Inglaterra, los bares se llaman pubs."}},{"phrase":"Tu veux une boisson ? — Pas d''alcool, merci. Je prendrai un verre d''eau.","translation":"Do you want a drink? — No alcohol, thanks. I''ll have a glass of water.","translations":{"es":"¿Quieres algo de beber? — Sin alcohol, gracias. Tomaré un vaso de agua."}},{"phrase":"Tout le monde a à boire ? — Commandez, c''est offert par la maison !","translation":"Does everyone have a drink? — Order, it''s on the house!","translations":{"es":"¿Todo el mundo tiene bebida? — ¡Pidan, invita la casa!"}},{"phrase":"Je n''aime pas les fêtes où on boit trop.","translation":"I don''t like parties where people drink too much.","translations":{"es":"No me gustan las fiestas en las que se bebe demasiado."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"What is \"un demi\" in a French bar?","options":["a small draft beer","half a bottle of wine","a glass of water","half a cocktail"],"correct":0,"explanation":"About 25 cl.","translations":{"es":{"question":"¿Qué es «un demi» en un bar francés?","explanation":"Unos 25 cl.","options":["una caña","media botella de vino","un vaso de agua","medio cóctel"]}}},{"id":"2","question":"How do you say \"Cheers!\"?","options":["Bon appétit !","Santé !","Bonne chance !","Félicitations !"],"correct":1,"explanation":"Also \"À la vôtre !\" / \"À la tienne !\".","translations":{"es":{"question":"¿Cómo se dice «¡Salud!»?","explanation":"También «À la vôtre !» / «À la tienne !»."}}},{"id":"3","question":"Complete: \"Il buvait comme si c''___ de l''eau.\"","options":["est","serait","était","soit"],"correct":2,"explanation":"\"Comme si\" + imparfait.","translations":{"es":{"question":"Completa: «Il buvait comme si c''___ de l''eau.»","explanation":"«Comme si» + imperfecto."}}},{"id":"4","question":"Complete: \"Elle faisait tout pour qu''il n''___ plus au bar.\"","options":["irait","allait","aille","ira"],"correct":2,"explanation":"\"Pour que\" + subjunctive.","translations":{"es":{"question":"Completa: «Elle faisait tout pour qu''il n''___ plus au bar.»","explanation":"«Pour que» + subjuntivo."}}},{"id":"5","question":"\"La gueule de bois\" means…","options":["a wooden mouth","a bar fight","a hangover","a strong drink"],"correct":2,"explanation":"Informal expression.","translations":{"es":{"question":"«La gueule de bois» significa…","explanation":"Expresión coloquial.","options":["una boca de madera","una pelea de bar","una resaca","una bebida fuerte"]}}},{"id":"6","question":"Complete: \"Sa femme est enceinte ___ six mois.\"","options":["dans","depuis","pendant","il y a"],"correct":1,"explanation":"Depuis + present.","translations":{"es":{"question":"Completa: «Sa femme est enceinte ___ six mois.»","explanation":"Depuis + presente."}}},{"id":"7","question":"\"C''est offert par la maison.\" Meaning?","options":["It''s on the house.","It''s for the owner.","It''s a house party.","It''s homemade."],"correct":0,"explanation":"Free, paid by the bar.","translations":{"es":{"question":"«C''est offert par la maison.» ¿Significado?","explanation":"Gratis, lo paga el bar.","options":["Invita la casa.","Es para el dueño.","Es una fiesta en casa.","Es casero."]}}},{"id":"8","question":"Imperative \"nous\": \"Let''s have a drink!\"","options":["Prenons un verre !","Nous prenons un verre !","Prends un verre !","Prenez un verre !"],"correct":0,"explanation":"Imperative of prendre with nous: prenons.","translations":{"es":{"question":"Imperativo «nous»: «¡Tomemos algo!»","explanation":"Imperativo de prendre con nous: prenons."}}}]}'::jsonb, 3),
  ('story', 'Un ami en difficulté', '{"text":"Mon meilleur ami, Julien, passait presque tout son temps libre dans les bars de la ville. Au début, c''était juste pour s''amuser avec les copains. Mais petit à petit, la situation devint pire : il buvait du whisky comme si c''était de l''eau, et il était en train de devenir quelqu''un d''autre. Il y a un an, il s''est marié avec Claire, une femme très gentille qui essayait de le convaincre pour qu''il n''aille plus au bar tous les soirs. Pendant quelques mois, ça a marché. Mais ensuite, il commença à retourner à ses vieilles habitudes. Claire est enceinte depuis six mois, et elle était très inquiète. Un soir, elle avait préparé un dîner spécial pour lui annoncer que c''était une fille. Elle l''attendit jusqu''à minuit. Julien n''est jamais arrivé : il s''était endormi sur une chaise du bar. C''est moi qui suis allé le chercher. Le lendemain matin, avec une terrible gueule de bois, il a vu le dîner froid sur la table et le petit mot de Claire. Il s''est enfin rendu compte qu''il pouvait faire du mal aux personnes qu''il aimait à cause de l''alcool. Depuis trois mois, il ne boit plus une goutte, et il va à un groupe de soutien. Je suis fier de lui.","translation":"My best friend, Julien, used to spend almost all his free time in the bars around town. At first, it was just to have fun with friends. But little by little, the situation got worse: he drank whisky as if it were water, and he was turning into someone else. A year ago, he married Claire, a very kind woman who tried to persuade him to stop going to the bar every night. For a few months, it worked. But then he started going back to his old habits. Claire is six months pregnant, and she was very worried. One evening, she had prepared a special dinner to tell him it was a girl. She waited for him until midnight. Julien never came: he had fallen asleep on a chair in the bar. I was the one who went to get him. The next morning, with a terrible hangover, he saw the cold dinner on the table and Claire''s little note. He finally realized that he could hurt the people he loved because of alcohol. He hasn''t had a drop for three months, and he goes to a support group. I''m proud of him.","translations":{"es":"Mi mejor amigo, Julien, pasaba casi todo su tiempo libre en los bares de la ciudad. Al principio era solo para divertirse con los amigos. Pero poco a poco la situación empeoró: bebía whisky como si fuera agua y se estaba convirtiendo en otra persona. Hace un año se casó con Claire, una mujer muy amable que intentaba convencerlo para que no fuera al bar todas las noches. Durante unos meses funcionó. Pero luego empezó a volver a sus viejas costumbres. Claire está embarazada de seis meses y estaba muy preocupada. Una noche había preparado una cena especial para anunciarle que era una niña. Lo esperó hasta medianoche. Julien no llegó nunca: se había quedado dormido en una silla del bar. Fui yo quien fue a buscarlo. A la mañana siguiente, con una resaca terrible, vio la cena fría en la mesa y la notita de Claire. Por fin se dio cuenta de que podía hacer daño a las personas que quería por culpa del alcohol. Hace tres meses que no prueba ni una gota y va a un grupo de apoyo. Estoy orgulloso de él."},"highlighted_words":["temps libre","devint pire","comme si c''était de l''eau","était en train de devenir","pour qu''il n''aille plus","commença","enceinte depuis six mois","attendit","s''était endormi","gueule de bois","s''est enfin rendu compte","Depuis trois mois"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Prenons","une","bière"],"translation":"Let''s have a beer","translations":{"es":"Tomemos una cerveza"}},{"words":["C''est","ma","tournée"],"translation":"This round is on me","translations":{"es":"Esta ronda la pago yo"}},{"words":["J''étais","seul","au","comptoir"],"translation":"I was alone at the counter","translations":{"es":"Estaba solo en la barra"}},{"words":["Il","buvait","comme","si","c''était","de","l''eau"],"translation":"He drank as if it were water","translations":{"es":"Bebía como si fuera agua"}},{"words":["Portons","un","toast"],"translation":"Let''s make a toast","translations":{"es":"Brindemos"}},{"words":["Je","ne","bois","pas","d''alcool"],"translation":"I don''t drink alcohol","translations":{"es":"No bebo alcohol"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Cheers!","translations":{"es":"¡Salud!"},"answer":"Santé !"},{"prompt":"A small beer, please","translations":{"es":"Una caña, por favor"},"answer":"Un demi, s''il vous plaît"},{"prompt":"I have a hangover","translations":{"es":"Tengo resaca"},"answer":"J''ai la gueule de bois"},{"prompt":"I''ll have a glass of water","translations":{"es":"Tomaré un vaso de agua"},"answer":"Je prendrai un verre d''eau"},{"prompt":"It''s on the house","translations":{"es":"Invita la casa"},"answer":"C''est offert par la maison"},{"prompt":"This bar is very quiet","translations":{"es":"Este bar es muy tranquilo"},"answer":"Ce bar est très calme"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 54: Le magasin de photo
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-54', 'Le magasin de photo', '📷', 'La tienda de fotografía', 54, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''appareil photo","translation":"the camera","translations":{"es":"la cámara de fotos"}},{"id":"2","word":"l''appareil photo numérique","translation":"the digital camera","translations":{"es":"la cámara digital"}},{"id":"3","word":"le caméscope","translation":"the camcorder","translations":{"es":"la videocámara"}},{"id":"4","word":"l''objectif","translation":"the lens","translations":{"es":"el objetivo"}},{"id":"5","word":"le zoom","translation":"the zoom","translations":{"es":"el zoom"}},{"id":"6","word":"le filtre","translation":"the filter","translations":{"es":"el filtro"}},{"id":"7","word":"le flash","translation":"the flash","translations":{"es":"el flash"}},{"id":"8","word":"le trépied","translation":"the tripod","translations":{"es":"el trípode"}},{"id":"9","word":"le posemètre","translation":"the light meter","translations":{"es":"el fotómetro"}},{"id":"10","word":"la pellicule","translation":"the film roll","translations":{"es":"el carrete"}},{"id":"11","word":"le négatif","translation":"the negative","translations":{"es":"el negativo"}},{"id":"12","word":"la diapositive","translation":"the slide","translations":{"es":"la diapositiva"}},{"id":"13","word":"le projecteur","translation":"the projector","translations":{"es":"el proyector"}},{"id":"14","word":"l''écran","translation":"the screen","translations":{"es":"la pantalla"}},{"id":"15","word":"la pile","translation":"the battery","translations":{"es":"la pila"}},{"id":"16","word":"la carte mémoire","translation":"the memory card","translations":{"es":"la tarjeta de memoria"}},{"id":"17","word":"prendre une photo","translation":"to take a photo","translations":{"es":"hacer una foto"}},{"id":"18","word":"développer","translation":"to develop","translations":{"es":"revelar"}},{"id":"19","word":"imprimer","translation":"to print","translations":{"es":"imprimir"}},{"id":"20","word":"régler","translation":"to adjust","translations":{"es":"ajustar"}},{"id":"21","word":"faire la mise au point","translation":"to focus","translations":{"es":"enfocar"}},{"id":"22","word":"le premier plan","translation":"the foreground","translations":{"es":"el primer plano"}},{"id":"23","word":"l''arrière-plan","translation":"the background","translations":{"es":"el fondo"}},{"id":"24","word":"le paysage","translation":"the landscape","translations":{"es":"el paisaje"}},{"id":"25","word":"le portrait","translation":"the portrait","translations":{"es":"el retrato"}},{"id":"26","word":"en noir et blanc","translation":"in black and white","translations":{"es":"en blanco y negro"}},{"id":"27","word":"en couleur","translation":"in color","translations":{"es":"en color"}},{"id":"28","word":"flou / floue","translation":"blurry","translations":{"es":"borroso / borrosa"}},{"id":"29","word":"net / nette","translation":"sharp","translations":{"es":"nítido / nítida"}},{"id":"30","word":"clair / sombre","translation":"bright / dark","translations":{"es":"claro / oscuro"}},{"id":"31","word":"meilleur / meilleure","translation":"better / best","translations":{"es":"mejor"}},{"id":"32","word":"mieux","translation":"better (adverb)","translations":{"es":"mejor (adverbio)"}},{"id":"33","word":"le / la photographe","translation":"the photographer","translations":{"es":"el / la fotógrafo/a"}}],"grammar":[{"structure":"comparatif","example":"Cette photo est plus claire que l''autre. / Son trépied a coûté moins cher.","en":"Comparatives (plus / moins / aussi … que)","es":"Comparativos"},{"structure":"superlatif","example":"C''est la plus jolie des photos. / Ce fut le plus beau voyage de notre vie.","en":"Superlatives","es":"Superlativos"},{"structure":"meilleur / mieux","example":"Ton appareil est bon, mais le mien est meilleur. / Elle photographie mieux que moi.","en":"Better (adjective vs. adverb)","es":"Mejor (adjetivo frente a adverbio)"},{"structure":"pronoms possessifs","example":"le mien, la tienne, les nôtres","en":"Possessive pronouns","es":"Pronombres posesivos"},{"structure":"superlatif + subjonctif","example":"C''est la meilleure photographe que je connaisse.","en":"Subjunctive after a superlative","es":"Subjuntivo tras un superlativo"},{"structure":"attendre que / vouloir que + subjonctif","example":"On attendra que le ciel soit plus dégagé. / Quel type de photos veux-tu que je prenne ?","en":"Subjunctive after waiting / wanting","es":"Subjuntivo tras esperar / querer"},{"structure":"voix passive","example":"Le posemètre est utilisé pour mesurer la lumière.","en":"Passive voice","es":"Voz pasiva"}],"tips":[{"en":"\"Meilleur\" is an adjective (un meilleur appareil); \"mieux\" is an adverb (il photographie mieux). Never \"plus bon\".","es":"«Meilleur» es adjetivo (un meilleur appareil); «mieux» es adverbio (il photographie mieux). Nunca «plus bon»."},{"en":"Photo words: \"l''appareil photo\" (camera), \"l''objectif\" (lens), \"le trépied\" (tripod), \"la mise au point\" (focus), \"le premier plan\" (foreground), \"flou\" (blurry).","es":"Fotografía: «l''appareil photo» (cámara), «l''objectif» (objetivo), «le trépied» (trípode), «la mise au point» (enfoque), «le premier plan» (primer plano), «flou» (borroso)."},{"en":"\"Prendre une photo\" = to take a photo; \"développer une pellicule\" = to develop a film; \"imprimer\" = to print.","es":"«Prendre une photo» = hacer una foto; «développer une pellicule» = revelar un carrete; «imprimer» = imprimir."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Achetons un appareil photo !","translation":"Let''s buy a camera!","translations":{"es":"¡Compremos una cámara!"}},{"phrase":"Ton appareil est bon, mais le mien est meilleur.","translation":"Your camera is good, but mine is better.","translations":{"es":"Tu cámara es buena, pero la mía es mejor."}},{"phrase":"Sa photo est plus grande que la mienne.","translation":"Her photo is bigger than mine.","translations":{"es":"Su foto es más grande que la mía."}},{"phrase":"Cette photo est plus claire que l''autre.","translation":"This photo is brighter than the other.","translations":{"es":"Esta foto es más clara que la otra."}},{"phrase":"Cette pile dure plus longtemps que l''autre.","translation":"This battery lasts longer than the other.","translations":{"es":"Esta pila dura más que la otra."}},{"phrase":"Mon appareil est plus récent que le tien.","translation":"My camera is newer than yours.","translations":{"es":"Mi cámara es más nueva que la tuya."}},{"phrase":"Son trépied a coûté moins cher.","translation":"His tripod cost less.","translations":{"es":"Su trípode costó menos."}},{"phrase":"Approche-toi de l''appareil, je ne te vois pas bien.","translation":"Come closer to the camera, I can''t see you well.","translations":{"es":"Acércate a la cámara, no te veo bien."}},{"phrase":"Prends la photo sans le flash.","translation":"Take the photo without the flash.","translations":{"es":"Haz la foto sin flash."}},{"phrase":"Tu peux mettre son visage au premier plan ? — Oui, c''est ce que je voulais faire.","translation":"Can you put her face in the foreground? — Yes, that''s what I wanted to do.","translations":{"es":"¿Puedes poner su cara en primer plano? — Sí, es lo que quería hacer."}},{"phrase":"Où je mets le trépied ? — À côté de cet arbre, la vue sera meilleure.","translation":"Where do I put the tripod? — Next to that tree, the view will be better.","translations":{"es":"¿Dónde pongo el trípode? — Al lado de ese árbol, la vista será mejor."}},{"phrase":"Quand prendras-tu ces photos ? — On attendra que le ciel soit plus dégagé.","translation":"When will you take these photos? — We''ll wait until the sky is clearer.","translations":{"es":"¿Cuándo harás estas fotos? — Esperaremos a que el cielo esté más despejado."}},{"phrase":"Parmi ces trois photos, laquelle est la plus jolie ? — Celle de droite.","translation":"Of these three photos, which is the prettiest? — The one on the right.","translations":{"es":"De estas tres fotos, ¿cuál es la más bonita? — La de la derecha."}},{"phrase":"C''est une bonne photographe ? — C''est la meilleure que je connaisse.","translation":"Is she a good photographer? — She''s the best I know.","translations":{"es":"¿Es buena fotógrafa? — Es la mejor que conozco."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Mon appareil est ___ que le tien.\"","options":["mieux","plus bon","le meilleur","meilleur"],"correct":3,"explanation":"\"Bon\" → \"meilleur\" (never \"plus bon\").","translations":{"es":{"question":"Completa: «Mon appareil est ___ que le tien.»","explanation":"«Bon» → «meilleur» (nunca «plus bon»)."}}},{"id":"2","question":"Complete: \"Elle photographie ___ que moi.\"","options":["meilleur","plus bien","meilleure","mieux"],"correct":3,"explanation":"Adverb: bien → mieux.","translations":{"es":{"question":"Completa: «Elle photographie ___ que moi.»","explanation":"Adverbio: bien → mieux."}}},{"id":"3","question":"Complete: \"Ta photo est belle, mais ___ est plus nette.\" (mine)","options":["le mien","ma","les miennes","la mienne"],"correct":3,"explanation":"Photo is feminine: la mienne.","translations":{"es":{"question":"Completa: «Ta photo est belle, mais ___ est plus nette.» (la mía)","explanation":"Photo es femenino: la mienne."}}},{"id":"4","question":"Complete: \"C''est le meilleur photographe que je ___.\"","options":["connaissais","connaîtrai","connais","connaisse"],"correct":3,"explanation":"Subjunctive after a superlative.","translations":{"es":{"question":"Completa: «C''est le meilleur photographe que je ___.»","explanation":"Subjuntivo tras un superlativo."}}},{"id":"5","question":"Complete: \"On attendra que le ciel ___ dégagé.\"","options":["sera","était","est","soit"],"correct":3,"explanation":"\"Attendre que\" + subjunctive.","translations":{"es":{"question":"Completa: «On attendra que le ciel ___ dégagé.»","explanation":"«Attendre que» + subjuntivo."}}},{"id":"6","question":"What is \"un trépied\"?","options":["a flash","a film","a lens","a tripod"],"correct":3,"explanation":"Three feet to hold the camera.","translations":{"es":{"question":"¿Qué es «un trépied»?","explanation":"Tres patas para sujetar la cámara.","options":["un flash","un carrete","un objetivo","un trípode"]}}},{"id":"7","question":"\"Flou\" means…","options":["sharp","colorful","bright","blurry"],"correct":3,"explanation":"Opposite: net.","translations":{"es":{"question":"«Flou» significa…","explanation":"Lo contrario: net.","options":["nítido","colorido","luminoso","borroso"]}}},{"id":"8","question":"Complete: \"C''est la ___ belle photo de l''album.\"","options":["très","meilleure","mieux","plus"],"correct":3,"explanation":"Superlative: la plus + adjective + de.","translations":{"es":{"question":"Completa: «C''est la ___ belle photo de l''album.»","explanation":"Superlativo: la plus + adjetivo + de."}}}]}'::jsonb, 3),
  ('story', 'Le voyage le plus photogénique', '{"text":"Ma sœur et moi sommes parties en Islande pour photographier les paysages les plus spectaculaires d''Europe. Le seul problème, c''est qu''à l''arrivée, la compagnie aérienne avait perdu nos bagages, avec tout notre matériel dedans ! Il ne nous restait que nos passeports et un peu d''argent. D''un côté, nous avions de la chance d''être là ; de l''autre, c''était vraiment difficile. Nous avons dû racheter un appareil photo, un trépied, des cartes mémoire, des piles… et des vêtements chauds. Pendant trois jours, nous avons cherché le meilleur matériel, mais quand il était de bonne qualité, il était trop cher. Finalement, un vieux photographe de Reykjavik nous a vendu son appareil : « C''est le meilleur que vous puissiez trouver ici », nous a-t-il dit. Il avait raison. Nous avons pris des photos de cascades plus hautes que des immeubles, de glaciers plus bleus que le ciel et d''aurores boréales magnifiques. Ce fut le plus beau voyage de notre vie. Et nos valises ? Elles sont arrivées le dernier jour… mais nous avons gardé l''appareil du vieux photographe. Il est meilleur que l''ancien !","translation":"My sister and I went to Iceland to photograph the most spectacular landscapes in Europe. The only problem was that when we arrived, the airline had lost our luggage, with all our equipment inside! We only had our passports and a bit of money left. On the one hand, we were lucky to be there; on the other, it was really hard. We had to buy a new camera, a tripod, memory cards, batteries… and warm clothes. For three days, we looked for the best equipment, but when it was good quality, it was too expensive. Finally, an old photographer in Reykjavik sold us his camera: “It''s the best one you can find here,” he told us. He was right. We took photos of waterfalls taller than buildings, glaciers bluer than the sky, and magnificent northern lights. It was the most beautiful trip of our lives. And our suitcases? They arrived on the last day… but we kept the old photographer''s camera. It''s better than the old one!","translations":{"es":"Mi hermana y yo nos fuimos a Islandia para fotografiar los paisajes más espectaculares de Europa. El único problema fue que, al llegar, la aerolínea había perdido nuestro equipaje, ¡con todo el material dentro! Solo nos quedaban los pasaportes y un poco de dinero. Por un lado, teníamos suerte de estar allí; por otro, era muy difícil. Tuvimos que volver a comprar una cámara, un trípode, tarjetas de memoria, pilas… y ropa de abrigo. Durante tres días buscamos el mejor material, pero cuando era de buena calidad, era demasiado caro. Al final, un viejo fotógrafo de Reikiavik nos vendió su cámara: «Es la mejor que pueden encontrar aquí», nos dijo. Tenía razón. Hicimos fotos de cascadas más altas que edificios, de glaciares más azules que el cielo y de auroras boreales magníficas. Fue el viaje más bonito de nuestra vida. ¿Y nuestras maletas? Llegaron el último día… pero nos quedamos con la cámara del viejo fotógrafo. ¡Es mejor que la antigua!"},"highlighted_words":["les paysages les plus spectaculaires","avait perdu","Il ne nous restait que","appareil photo","trépied","le meilleur matériel","le meilleur que vous puissiez trouver","plus hautes que","plus bleus que","le plus beau voyage","meilleur que l''ancien"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Mon","appareil","est","meilleur","que","le","tien"],"translation":"My camera is better than yours","translations":{"es":"Mi cámara es mejor que la tuya"}},{"words":["C''est","la","plus","belle","photo"],"translation":"It''s the most beautiful photo","translations":{"es":"Es la foto más bonita"}},{"words":["Prends","la","photo","sans","flash"],"translation":"Take the photo without flash","translations":{"es":"Haz la foto sin flash"}},{"words":["Elle","photographie","mieux","que","moi"],"translation":"She photographs better than me","translations":{"es":"Fotografía mejor que yo"}},{"words":["Attendons","que","le","soleil","sorte"],"translation":"Let''s wait for the sun to come out","translations":{"es":"Esperemos a que salga el sol"}},{"words":["Cette","photo","est","floue"],"translation":"This photo is blurry","translations":{"es":"Esta foto está borrosa"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Smile!","translations":{"es":"¡Sonrían!"},"answer":"Souriez !"},{"prompt":"I would like to print these photos","translations":{"es":"Quisiera imprimir estas fotos"},"answer":"Je voudrais imprimer ces photos"},{"prompt":"My photo is sharper than yours","translations":{"es":"Mi foto es más nítida que la tuya"},"answer":"Ma photo est plus nette que la tienne"},{"prompt":"It''s the best camera","translations":{"es":"Es la mejor cámara"},"answer":"C''est le meilleur appareil"},{"prompt":"The flash isn''t working","translations":{"es":"El flash no funciona"},"answer":"Le flash ne marche pas"},{"prompt":"Take a photo of us","translations":{"es":"Haznos una foto"},"answer":"Prends une photo de nous"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 55: Les grands magasins
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-55', 'Les grands magasins', '🛒', 'Los grandes almacenes', 55, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le grand magasin","translation":"the department store","translations":{"es":"los grandes almacenes"}},{"id":"2","word":"le centre commercial","translation":"the mall","translations":{"es":"el centro comercial"}},{"id":"3","word":"la boutique","translation":"the shop","translations":{"es":"la tienda"}},{"id":"4","word":"le rayon","translation":"the department","translations":{"es":"la sección"}},{"id":"5","word":"l''acheteur / l''acheteuse","translation":"the shopper","translations":{"es":"el comprador / la compradora"}},{"id":"6","word":"le vendeur / la vendeuse","translation":"the salesperson","translations":{"es":"el vendedor / la vendedora"}},{"id":"7","word":"la marchandise","translation":"goods","translations":{"es":"la mercancía"}},{"id":"8","word":"le prix","translation":"the price","translations":{"es":"el precio"}},{"id":"9","word":"la remise / la réduction","translation":"the discount","translations":{"es":"el descuento"}},{"id":"10","word":"les soldes","translation":"the sales","translations":{"es":"las rebajas"}},{"id":"11","word":"bon marché","translation":"cheap","translations":{"es":"barato"}},{"id":"12","word":"cher / chère","translation":"expensive","translations":{"es":"caro / cara"}},{"id":"13","word":"comparer","translation":"to compare","translations":{"es":"comparar"}},{"id":"14","word":"choisir","translation":"to choose","translations":{"es":"elegir"}},{"id":"15","word":"porter","translation":"to carry / wear","translations":{"es":"llevar"}},{"id":"16","word":"peser","translation":"to weigh","translations":{"es":"pesar"}},{"id":"17","word":"lourd / lourde","translation":"heavy","translations":{"es":"pesado / pesada"}},{"id":"18","word":"le sac","translation":"the bag","translations":{"es":"la bolsa"}},{"id":"19","word":"le porte-monnaie","translation":"the coin purse","translations":{"es":"el monedero"}},{"id":"20","word":"l''argent liquide","translation":"cash","translations":{"es":"el efectivo"}},{"id":"21","word":"importer","translation":"to import","translations":{"es":"importar"}},{"id":"22","word":"augmenter / monter","translation":"to go up","translations":{"es":"subir"}},{"id":"23","word":"baisser","translation":"to go down","translations":{"es":"bajar"}},{"id":"24","word":"se dépêcher","translation":"to hurry","translations":{"es":"darse prisa"}},{"id":"25","word":"le voleur / la voleuse","translation":"the thief","translations":{"es":"el ladrón / la ladrona"}},{"id":"26","word":"le vol à l''étalage","translation":"shoplifting","translations":{"es":"el hurto en tiendas"}},{"id":"27","word":"le vigile","translation":"the security guard","translations":{"es":"el guardia de seguridad"}},{"id":"28","word":"la caméra de surveillance","translation":"the security camera","translations":{"es":"la cámara de vigilancia"}},{"id":"29","word":"le code-barres","translation":"the barcode","translations":{"es":"el código de barras"}},{"id":"30","word":"rapidement","translation":"quickly","translations":{"es":"rápidamente"}},{"id":"31","word":"souvent","translation":"often","translations":{"es":"a menudo"}},{"id":"32","word":"honnêtement","translation":"honestly","translations":{"es":"honestamente"}},{"id":"33","word":"complètement","translation":"completely","translations":{"es":"completamente"}},{"id":"34","word":"heureusement","translation":"fortunately","translations":{"es":"afortunadamente"}},{"id":"35","word":"étonnant / étonnante","translation":"surprising","translations":{"es":"sorprendente"}},{"id":"36","word":"charmant / charmante","translation":"charming","translations":{"es":"encantador / encantadora"}}],"grammar":[{"structure":"adverbes en -ment","example":"rapidement, honnêtement, complètement, heureusement","en":"Adverbs ending in -ment","es":"Adverbios en -mente"},{"structure":"place de l''adverbe au passé composé","example":"J''ai souvent acheté mes vêtements ici. / Elle a vite choisi.","en":"Adverb placement","es":"Posición del adverbio"},{"structure":"comparatif","example":"Ces sandales sont moins lourdes que les tiennes. / C''est plus cher ici qu''ailleurs.","en":"Comparatives","es":"Comparativos"},{"structure":"pronom « en »","example":"Il y a plein de chemises : choisis-en une !","en":"\"en\" with quantities","es":"«en» con cantidades"},{"structure":"si / lorsque + futur","example":"Si tu achètes cette veste maintenant, tu dépenseras moins.","en":"Conditions and time","es":"Condiciones y tiempo"},{"structure":"sans que + subjonctif","example":"Ils sortent sans que personne ne s''en aperçoive.","en":"\"Without\" + subjunctive","es":"«Sin que» + subjuntivo"},{"structure":"pronom relatif « dont »","example":"des jeunes, dont la plupart avaient seize ans","en":"\"dont\" (of whom / whose)","es":"«dont» (de los cuales)"}],"tips":[{"en":"Adverbs: feminine adjective + -ment (heureuse → heureusement). Adjectives in -ant / -ent → -amment / -emment (constant → constamment, récent → récemment).","es":"Adverbios: adjetivo femenino + -ment (heureuse → heureusement). Los adjetivos en -ant / -ent → -amment / -emment (constant → constamment, récent → récemment)."},{"en":"In the passé composé, short adverbs go between \"avoir/être\" and the participle: \"J''ai bien mangé\", \"Il a déjà payé\".","es":"En el passé composé, los adverbios cortos van entre «avoir/être» y el participio: «J''ai bien mangé», «Il a déjà payé»."},{"en":"\"Le grand magasin\" = department store (Galeries Lafayette); \"la grande surface\" = hypermarket; \"le centre commercial\" = mall.","es":"«Le grand magasin» = gran almacén (Galeries Lafayette); «la grande surface» = hipermercado; «le centre commercial» = centro comercial."},{"en":"\"Le vol à l''étalage\" = shoplifting; \"le vigile\" = security guard.","es":"«Le vol à l''étalage» = hurto en tiendas; «le vigile» = guardia de seguridad."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"En ce moment, elle est en train de faire du shopping.","translation":"Right now, she''s out shopping.","translations":{"es":"Ahora mismo está de compras."}},{"phrase":"Il va souvent au centre commercial.","translation":"He often goes to the mall.","translations":{"es":"Va a menudo al centro comercial."}},{"phrase":"J''ai souvent acheté mes vêtements dans ce magasin.","translation":"I have often bought my clothes in this store.","translations":{"es":"He comprado a menudo mi ropa en esta tienda."}},{"phrase":"Il y a beaucoup de modèles : choisis-en un maintenant !","translation":"There are lots of models: choose one now!","translations":{"es":"Hay muchos modelos: ¡elige uno ya!"}},{"phrase":"Cette chemise a été en solde longtemps, mais personne ne l''a achetée.","translation":"This shirt was on sale for a long time, but nobody bought it.","translations":{"es":"Esta camisa estuvo rebajada mucho tiempo, pero nadie la compró."}},{"phrase":"Là-bas, ils m''ont demandé plus cher que dans les autres magasins.","translation":"There, they charged me more than in other stores.","translations":{"es":"Allí me cobraron más que en las otras tiendas."}},{"phrase":"Les prix ont augmenté rapidement.","translation":"Prices went up quickly.","translations":{"es":"Los precios subieron rápidamente."}},{"phrase":"Ces sandales sont moins lourdes que les tiennes.","translation":"These sandals are lighter than yours.","translations":{"es":"Estas sandalias pesan menos que las tuyas."}},{"phrase":"Il vaut mieux faire les courses demain : aujourd''hui, il y a trop de monde.","translation":"It''s better to go shopping tomorrow: today there are too many people.","translations":{"es":"Es mejor ir de compras mañana: hoy hay demasiada gente."}},{"phrase":"Si tu achètes rapidement cette veste, tu dépenseras moins.","translation":"If you buy this jacket quickly, you''ll spend less.","translations":{"es":"Si compras rápido esta chaqueta, gastarás menos."}},{"phrase":"Heureusement, il a acheté la bonne taille.","translation":"Fortunately, he bought the right size.","translations":{"es":"Afortunadamente, compró la talla correcta."}},{"phrase":"Comment as-tu pu acheter un manteau si grand ? — Il était très bon marché !","translation":"How could you buy such a big coat? — It was very cheap!","translations":{"es":"¿Cómo pudiste comprar un abrigo tan grande? — ¡Era muy barato!"}},{"phrase":"Tu as comparé les prix ? — Oui, il y a une grande différence.","translation":"Did you compare the prices? — Yes, there''s a big difference.","translations":{"es":"¿Has comparado los precios? — Sí, hay una gran diferencia."}},{"phrase":"Dépêche-toi, il n''y aura plus rien à midi !","translation":"Hurry up, there won''t be anything left by noon!","translations":{"es":"¡Date prisa, a mediodía no quedará nada!"}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"What is the adverb of \"heureux\"?","options":["heureusment","heureux-ment","heureusement","heureuxment"],"correct":2,"explanation":"Feminine (heureuse) + -ment.","translations":{"es":{"question":"¿Cuál es el adverbio de «heureux»?","explanation":"Femenino (heureuse) + -ment."}}},{"id":"2","question":"What is the adverb of \"récent\"?","options":["récamment","récentment","récemment","récentement"],"correct":2,"explanation":"-ent → -emment.","translations":{"es":{"question":"¿Cuál es el adverbio de «récent»?","explanation":"-ent → -emment."}}},{"id":"3","question":"Where does \"souvent\" go? \"J''ai ___ acheté ___ ici.\"","options":["Souvent j''ai acheté ici souvent.","J''ai souvent acheté ici.","J''souvent ai acheté ici.","J''ai acheté souvent ici."],"correct":1,"explanation":"Short adverbs go between auxiliary and participle.","translations":{"es":{"question":"¿Dónde va «souvent»? «J''ai ___ acheté ___ ici.»","explanation":"Los adverbios cortos van entre el auxiliar y el participio."}}},{"id":"4","question":"Complete: \"Des chemises ? Choisis-___ une.\"","options":["en","y","la","les"],"correct":0,"explanation":"\"En\" + number.","translations":{"es":{"question":"Completa: «Des chemises ? Choisis-___ une.»","explanation":"«En» + número."}}},{"id":"5","question":"Complete: \"Il est sorti sans que personne ne le ___.\"","options":["verra","voie","voyait","voit"],"correct":1,"explanation":"\"Sans que\" + subjunctive.","translations":{"es":{"question":"Completa: «Il est sorti sans que personne ne le ___.»","explanation":"«Sans que» + subjuntivo."}}},{"id":"6","question":"Complete: \"Ces sandales sont ___ lourdes que les tiennes.\" (lighter)","options":["très","moins","aussi","plus"],"correct":1,"explanation":"Moins … que = less … than.","translations":{"es":{"question":"Completa: «Ces sandales sont ___ lourdes que les tiennes.» (pesan menos)","explanation":"Moins … que = menos … que."}}},{"id":"7","question":"\"Le vol à l''étalage\" is…","options":["shoplifting","a discount","a window display","a flight sale"],"correct":0,"explanation":"L''étalage = display.","translations":{"es":{"question":"«Le vol à l''étalage» es…","explanation":"L''étalage = el expositor.","options":["el hurto en tiendas","un descuento","un escaparate","una venta de vuelos"]}}},{"id":"8","question":"What is \"un grand magasin\"?","options":["a department store","a market","a big magazine","a big warehouse"],"correct":0,"explanation":"E.g., Galeries Lafayette.","translations":{"es":{"question":"¿Qué es «un grand magasin»?","explanation":"P. ej., Galeries Lafayette.","options":["unos grandes almacenes","un mercado","una revista grande","un gran almacén de mercancías"]}}}]}'::jsonb, 3),
  ('story', 'Le vigile', '{"text":"Je m''appelle Marc et je suis vigile dans un grand magasin de Lyon. Chaque jour, je surveille les rayons pour éviter les vols à l''étalage. Les voleurs font semblant de regarder les vêtements, puis ils cachent rapidement quelque chose dans leur sac ou sous leur manteau. Parfois, ils réussissent à sortir sans que personne ne s''en aperçoive. Il est étonnant de voir combien de jeunes sont arrêtés chaque mois, dont la plupart ont entre quinze et dix-sept ans. Souvent, ils ne volent pas par besoin, mais à cause de la pression de leurs amis : ils veulent avoir les mêmes baskets ou le même téléphone que les autres. Hier, j''ai arrêté un garçon qui avait caché un tee-shirt sous son pull. Il était complètement terrorisé. Au lieu d''appeler immédiatement la police, j''ai parlé longtemps avec lui. Il m''a avoué honnêtement qu''il voulait juste impressionner sa bande. Le magasin a installé des caméras et des codes-barres, mais je crois que le plus important, c''est de parler aux jeunes. Il faut leur faire comprendre qu''on n''a pas besoin de voler pour être accepté. Heureusement, ce garçon est revenu aujourd''hui… pour payer le tee-shirt !","translation":"My name is Marc and I''m a security guard in a department store in Lyon. Every day, I watch the departments to prevent shoplifting. Thieves pretend to look at the clothes, then quickly hide something in their bag or under their coat. Sometimes they manage to get out without anyone noticing. It''s surprising how many young people are caught every month, most of whom are between fifteen and seventeen. Often, they don''t steal out of need, but because of pressure from their friends: they want the same sneakers or the same phone as the others. Yesterday, I stopped a boy who had hidden a T-shirt under his sweater. He was completely terrified. Instead of calling the police right away, I talked with him for a long time. He honestly admitted that he just wanted to impress his group. The store has installed cameras and barcodes, but I think the most important thing is to talk to young people. We have to make them understand that you don''t need to steal to be accepted. Fortunately, that boy came back today… to pay for the T-shirt!","translations":{"es":"Me llamo Marc y soy guardia de seguridad en unos grandes almacenes de Lyon. Cada día vigilo las secciones para evitar los hurtos. Los ladrones fingen mirar la ropa y luego esconden rápidamente algo en la bolsa o bajo el abrigo. A veces consiguen salir sin que nadie se dé cuenta. Es sorprendente cuántos jóvenes son detenidos cada mes, la mayoría de los cuales tienen entre quince y diecisiete años. A menudo no roban por necesidad, sino por la presión de sus amigos: quieren tener las mismas zapatillas o el mismo móvil que los demás. Ayer detuve a un chico que había escondido una camiseta bajo el jersey. Estaba completamente aterrorizado. En lugar de llamar inmediatamente a la policía, hablé largo rato con él. Me confesó con honestidad que solo quería impresionar a su grupo. La tienda ha instalado cámaras y códigos de barras, pero creo que lo más importante es hablar con los jóvenes. Hay que hacerles entender que no hace falta robar para ser aceptado. Afortunadamente, ese chico ha vuelto hoy… ¡a pagar la camiseta!"},"highlighted_words":["vigile","grand magasin","vols à l''étalage","rapidement","sans que personne ne s''en aperçoive","étonnant","dont la plupart","Souvent","complètement","immédiatement","longtemps","honnêtement","codes-barres","Heureusement"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["J''ai","souvent","acheté","ici"],"translation":"I have often bought here","translations":{"es":"He comprado aquí a menudo"}},{"words":["Les","prix","ont","augmenté","rapidement"],"translation":"Prices went up quickly","translations":{"es":"Los precios subieron rápidamente"}},{"words":["Choisis-en","une"],"translation":"Choose one","translations":{"es":"Elige una"}},{"words":["C''est","moins","cher","qu''ailleurs"],"translation":"It''s cheaper than elsewhere","translations":{"es":"Es más barato que en otros sitios"}},{"words":["Heureusement","il","a","payé"],"translation":"Fortunately he paid","translations":{"es":"Afortunadamente, pagó"}},{"words":["Il","est","sorti","sans","que","personne","ne","le","voie"],"translation":"He left without anyone seeing him","translations":{"es":"Salió sin que nadie lo viera"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Where is the shoe department?","translations":{"es":"¿Dónde está la sección de zapatos?"},"answer":"Où est le rayon des chaussures ?"},{"prompt":"There are sales","translations":{"es":"Hay rebajas"},"answer":"Il y a des soldes"},{"prompt":"It''s too expensive","translations":{"es":"Es demasiado caro"},"answer":"C''est trop cher"},{"prompt":"I''m paying cash","translations":{"es":"Pago en efectivo"},"answer":"Je paie en liquide"},{"prompt":"Hurry up","translations":{"es":"Date prisa"},"answer":"Dépêche-toi"},{"prompt":"She speaks honestly","translations":{"es":"Habla con honestidad"},"answer":"Elle parle honnêtement"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 56: Chez le coiffeur
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-56', 'Chez le coiffeur', '💇', 'En la peluquería', 56, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le coiffeur / la coiffeuse","translation":"the hairdresser","translations":{"es":"el peluquero / la peluquera"}},{"id":"2","word":"le salon de coiffure","translation":"the hair salon","translations":{"es":"la peluquería"}},{"id":"3","word":"l''institut de beauté","translation":"the beauty salon","translations":{"es":"el centro de estética"}},{"id":"4","word":"la coupe de cheveux","translation":"the haircut","translations":{"es":"el corte de pelo"}},{"id":"5","word":"la coiffure","translation":"the hairstyle","translations":{"es":"el peinado"}},{"id":"6","word":"le brushing","translation":"the blow-dry","translations":{"es":"el secado con cepillo"}},{"id":"7","word":"la teinture","translation":"the hair dye","translations":{"es":"el tinte"}},{"id":"8","word":"les mèches","translation":"highlights","translations":{"es":"las mechas"}},{"id":"9","word":"frisé / bouclé","translation":"curly","translations":{"es":"rizado"}},{"id":"10","word":"raide","translation":"straight (hair)","translations":{"es":"liso"}},{"id":"11","word":"court / long","translation":"short / long","translations":{"es":"corto / largo"}},{"id":"12","word":"le shampoing","translation":"shampoo","translations":{"es":"el champú"}},{"id":"13","word":"l''après-shampoing","translation":"conditioner","translations":{"es":"el acondicionador"}},{"id":"14","word":"le sèche-cheveux","translation":"the hair dryer","translations":{"es":"el secador"}},{"id":"15","word":"la brosse","translation":"the brush","translations":{"es":"el cepillo"}},{"id":"16","word":"le peigne","translation":"the comb","translations":{"es":"el peine"}},{"id":"17","word":"les ciseaux","translation":"scissors","translations":{"es":"las tijeras"}},{"id":"18","word":"le rasoir","translation":"the razor","translations":{"es":"la cuchilla de afeitar"}},{"id":"19","word":"le miroir","translation":"the mirror","translations":{"es":"el espejo"}},{"id":"20","word":"la manucure","translation":"manicure","translations":{"es":"la manicura"}},{"id":"21","word":"la pédicure","translation":"pedicure","translations":{"es":"la pedicura"}},{"id":"22","word":"le vernis à ongles","translation":"nail polish","translations":{"es":"el esmalte de uñas"}},{"id":"23","word":"la lime à ongles","translation":"nail file","translations":{"es":"la lima de uñas"}},{"id":"24","word":"le coupe-ongles","translation":"nail clipper","translations":{"es":"el cortaúñas"}},{"id":"25","word":"épiler","translation":"to wax / pluck","translations":{"es":"depilar"}},{"id":"26","word":"la cire","translation":"wax","translations":{"es":"la cera"}},{"id":"27","word":"les sourcils","translation":"eyebrows","translations":{"es":"las cejas"}},{"id":"28","word":"le mascara","translation":"mascara","translations":{"es":"el rímel"}},{"id":"29","word":"le rouge à lèvres","translation":"lipstick","translations":{"es":"el pintalabios"}},{"id":"30","word":"le maquillage","translation":"makeup","translations":{"es":"el maquillaje"}},{"id":"31","word":"se faire masser","translation":"to get a massage","translations":{"es":"hacerse un masaje"}},{"id":"32","word":"le magazine","translation":"the magazine","translations":{"es":"la revista"}},{"id":"33","word":"pâle","translation":"pale","translations":{"es":"pálido"}},{"id":"34","word":"irrégulier / irrégulière","translation":"uneven","translations":{"es":"irregular"}}],"grammar":[{"structure":"se faire + infinitif","example":"Elle s''est fait couper les cheveux. / Je voudrais me faire faire une manucure.","en":"Having something done","es":"«Hacerse» algo (que otro lo hace)"},{"structure":"voix passive","example":"Les massages sont faits par Pierre. / Elle a été maquillée par Robert.","en":"Passive voice","es":"Voz pasiva"},{"structure":"vouloir que + subjonctif","example":"Je veux que vous me laviez les cheveux.","en":"Wanting someone to do something","es":"Querer que alguien haga algo"},{"structure":"il vaut mieux que + subjonctif","example":"Il vaut mieux que tu te coupes les cheveux.","en":"\"It''s better that\"","es":"«Es mejor que»"},{"structure":"accord du participe avec COD","example":"Qui t''a coupé les cheveux ? — Jean me les a coupés.","en":"Participle agreement with pronoun","es":"Concordancia del participio con pronombre"},{"structure":"depuis + présent","example":"Le salon est ouvert depuis un an.","en":"Ongoing since","es":"Desde hace"},{"structure":"venir de + infinitif","example":"Je viens de me faire masser.","en":"Recent past","es":"Pasado reciente"}],"tips":[{"en":"\"Se faire + infinitive\" = to have something done by someone else: \"Je me suis fait couper les cheveux\" (not \"J''ai coupé mes cheveux\", which means you did it yourself).","es":"«Se faire + infinitivo» = que otra persona te haga algo: «Je me suis fait couper les cheveux» (no «J''ai coupé mes cheveux», que significa que te los cortaste tú)."},{"en":"With body parts, French uses the article + a reflexive or indirect pronoun: \"Elle se lave les cheveux\", \"Il me coupe les cheveux\".","es":"Con partes del cuerpo, el francés usa el artículo + un pronombre: «Elle se lave les cheveux», «Il me coupe les cheveux»."},{"en":"At the hairdresser: \"une coupe\" (haircut), \"un brushing\" (blow-dry), \"une couleur / une teinture\" (dye), \"des mèches\" (highlights), \"rafraîchir\" (to trim).","es":"En la peluquería: «une coupe» (corte), «un brushing» (secado con cepillo), «une couleur / une teinture» (tinte), «des mèches» (mechas), «rafraîchir» (sanear las puntas)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Bienvenue au salon de coiffure !","translation":"Welcome to the hair salon!","translations":{"es":"¡Bienvenidos a la peluquería!"}},{"phrase":"D''abord, je veux que vous me laviez les cheveux.","translation":"First, I want you to wash my hair.","translations":{"es":"Primero, quiero que me lave el pelo."}},{"phrase":"Tes ongles seront très jolis.","translation":"Your nails will be very pretty.","translations":{"es":"Tus uñas quedarán muy bonitas."}},{"phrase":"Il vaut mieux que tu te coupes les cheveux.","translation":"You''d better get your hair cut.","translations":{"es":"Es mejor que te cortes el pelo."}},{"phrase":"Le salon est ouvert depuis un an.","translation":"The salon has been open for a year.","translations":{"es":"La peluquería lleva un año abierta."}},{"phrase":"Elle veut se faire épiler les sourcils à la cire.","translation":"She wants to have her eyebrows waxed.","translations":{"es":"Quiere depilarse las cejas con cera."}},{"phrase":"Les massages sont faits par Pierre.","translation":"Massages are done by Pierre.","translations":{"es":"Los masajes los hace Pierre."}},{"phrase":"Elle a été maquillée par une professionnelle.","translation":"Her makeup was done by a professional.","translations":{"es":"La maquilló una profesional."}},{"phrase":"Le sèche-cheveux est cassé.","translation":"The hair dryer is broken.","translations":{"es":"El secador está roto."}},{"phrase":"Les ciseaux ont disparu !","translation":"The scissors have disappeared!","translations":{"es":"¡Las tijeras han desaparecido!"}},{"phrase":"Qu''est-ce que vous aimeriez ? — J''aimerais me faire faire une manucure.","translation":"What would you like? — I would like a manicure.","translations":{"es":"¿Qué desea? — Me gustaría hacerme la manicura."}},{"phrase":"Tu es vraiment détendue ! — Je viens de me faire masser.","translation":"You''re really relaxed! — I just had a massage.","translations":{"es":"¡Estás muy relajada! — Me acaban de dar un masaje."}},{"phrase":"Qui t''a coupé les cheveux ? — Jean me les a coupés.","translation":"Who cut your hair? — Jean cut it for me.","translations":{"es":"¿Quién te ha cortado el pelo? — Me lo ha cortado Jean."}},{"phrase":"Quand vas-tu te faire couper les cheveux ? — Je le ferai demain.","translation":"When are you going to get your hair cut? — I''ll do it tomorrow.","translations":{"es":"¿Cuándo vas a cortarte el pelo? — Lo haré mañana."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"\"Je me suis fait couper les cheveux.\" Who cut the hair?","options":["someone else (a hairdresser)","nobody","I did it myself","my hair fell out"],"correct":0,"explanation":"\"Se faire + infinitive\" = someone else does it.","translations":{"es":{"question":"«Je me suis fait couper les cheveux.» ¿Quién cortó el pelo?","explanation":"«Se faire + infinitivo» = lo hace otra persona.","options":["otra persona (un peluquero)","nadie","yo mismo","se me cayó el pelo"]}}},{"id":"2","question":"Complete: \"Je veux que vous me ___ les cheveux.\"","options":["laverez","laviez","lavez","laviez-vous"],"correct":1,"explanation":"Vouloir que + subjunctive.","translations":{"es":{"question":"Completa: «Je veux que vous me ___ les cheveux.»","explanation":"Vouloir que + subjuntivo."}}},{"id":"3","question":"Passive: \"Pierre fait les massages.\" → ?","options":["Pierre est fait par les massages.","Les massages sont faits par Pierre.","Les massages font Pierre.","Les massages sont fait par Pierre."],"correct":1,"explanation":"Agreement: faits (masc. plural).","translations":{"es":{"question":"Pasiva: «Pierre fait les massages.» → ?","explanation":"Concordancia: faits (masculino plural)."}}},{"id":"4","question":"Complete: \"Les cheveux ? Jean me les a ___.\"","options":["coupés","coupé","coupées","couper"],"correct":0,"explanation":"Agreement with \"les\" (= les cheveux, masc. plural).","translations":{"es":{"question":"Completa: «Les cheveux ? Jean me les a ___.»","explanation":"Concordancia con «les» (= les cheveux, masculino plural)."}}},{"id":"5","question":"How do you say \"I wash my hair\"?","options":["Je lave mes cheveux à moi.","Je me lave les cheveux.","Je me lave mes cheveux.","Je lave les cheveux de moi."],"correct":1,"explanation":"Reflexive + article with body parts.","translations":{"es":{"question":"¿Cómo se dice «Me lavo el pelo»?","explanation":"Pronominal + artículo con partes del cuerpo."}}},{"id":"6","question":"What are \"des mèches\"?","options":["scissors","highlights","curls","wigs"],"correct":1,"explanation":"Faire des mèches = to get highlights.","translations":{"es":{"question":"¿Qué son «des mèches»?","explanation":"Faire des mèches = hacerse mechas.","options":["tijeras","mechas","rizos","pelucas"]}}},{"id":"7","question":"Complete: \"Il vaut mieux que tu ___ chez le coiffeur.\"","options":["ailles","vas","iras","allais"],"correct":0,"explanation":"\"Il vaut mieux que\" + subjunctive.","translations":{"es":{"question":"Completa: «Il vaut mieux que tu ___ chez le coiffeur.»","explanation":"«Il vaut mieux que» + subjuntivo."}}},{"id":"8","question":"\"Je viens de me faire masser.\" Meaning?","options":["I came to give a massage.","I''m going to get a massage.","I just had a massage.","I massage myself."],"correct":2,"explanation":"Venir de = recent past.","translations":{"es":{"question":"«Je viens de me faire masser.» ¿Significado?","explanation":"Venir de = pasado reciente.","options":["He venido a dar un masaje.","Me van a dar un masaje.","Me acaban de dar un masaje.","Me masajeo yo solo."]}}}]}'::jsonb, 3),
  ('story', 'La pire coupe de ma vie', '{"text":"« Bonsoir, madame. Qu''est-ce que vous aimeriez faire aujourd''hui ? » « Je voudrais me faire couper les cheveux, mais juste un peu. » « Vous voulez aussi que je vous fasse un shampoing ? » « Oui, pourquoi pas. Je ne viens pas souvent ici, mais on m''a dit que c''était bien. » « Vous vous êtes déjà fait faire une couleur ? » « Oui, d''ailleurs, j''aimerais bien essayer quelque chose de différent. » « Je suis très doué pour les couleurs ! Si vous voulez, je vous la fais. » « D''accord, je vous fais confiance. » Une heure plus tard, Léa se regarde dans le miroir. « Mon Dieu ! Qu''est-ce que vous avez fait ? Mes cheveux sont orange ! » « Euh… au moins, c''est original. Laissez-moi les couper un peu, ça ira mieux. » Dix minutes après : « Pourquoi me les avez-vous coupés si court ? Et de façon si irrégulière ! » « Mais vous m''avez dit que vous vouliez du changement ! » « Je vous ai dit que je ne voulais pas changer beaucoup ! » Léa sort du salon en mettant un bonnet. Le lendemain, elle s''est fait faire une nouvelle couleur… dans un autre salon.","translation":"“Good evening, madam. What would you like to have done today?” “I''d like to have my hair cut, but just a little.” “Would you also like me to give you a shampoo?” “Yes, why not. I don''t come here often, but I was told it was good.” “Have you ever had your hair colored?” “Yes, actually, I''d like to try something different.” “I''m very good at color! If you want, I''ll do it for you.” “All right, I trust you.” An hour later, Léa looks at herself in the mirror. “Oh my God! What have you done? My hair is orange!” “Um… at least it''s original. Let me cut it a bit, it''ll look better.” Ten minutes later: “Why did you cut it so short? And so unevenly!” “But you told me you wanted a change!” “I told you I didn''t want to change much!” Léa leaves the salon putting on a beanie. The next day, she had a new color done… in another salon.","translations":{"es":"«Buenas tardes, señora. ¿Qué le gustaría hacerse hoy?» «Quisiera cortarme el pelo, pero solo un poco.» «¿Quiere también que le lave la cabeza?» «Sí, ¿por qué no? No vengo a menudo, pero me han dicho que está bien.» «¿Se ha teñido alguna vez?» «Sí; de hecho, me gustaría probar algo diferente.» «¡Se me dan muy bien los tintes! Si quiere, se lo hago.» «De acuerdo, confío en usted.» Una hora después, Léa se mira en el espejo. «¡Dios mío! ¿Qué ha hecho? ¡Tengo el pelo naranja!» «Eh… al menos es original. Déjeme cortárselo un poco, quedará mejor.» Diez minutos después: «¿Por qué me lo ha cortado tan corto? ¡Y tan irregular!» «¡Pero usted me dijo que quería un cambio!» «¡Le dije que no quería cambiar mucho!» Léa sale de la peluquería poniéndose un gorro. Al día siguiente se hizo un tinte nuevo… en otra peluquería."},"highlighted_words":["me faire couper les cheveux","Vous voulez aussi que je vous fasse","shampoing","Vous vous êtes déjà fait faire une couleur","je vous fais confiance","miroir","Laissez-moi les couper","me les avez-vous coupés","irrégulière","elle s''est fait faire"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","me","suis","fait","couper","les","cheveux"],"translation":"I had my hair cut","translations":{"es":"Me he cortado el pelo (en la peluquería)"}},{"words":["Je","veux","que","vous","me","laviez","les","cheveux"],"translation":"I want you to wash my hair","translations":{"es":"Quiero que me lave el pelo"}},{"words":["Le","salon","est","ouvert","depuis","un","an"],"translation":"The salon has been open for a year","translations":{"es":"La peluquería lleva un año abierta"}},{"words":["Elle","a","été","maquillée","par","une","amie"],"translation":"Her makeup was done by a friend","translations":{"es":"La maquilló una amiga"}},{"words":["Je","viens","de","me","faire","masser"],"translation":"I just had a massage","translations":{"es":"Me acaban de dar un masaje"}},{"words":["Jean","me","les","a","coupés"],"translation":"Jean cut them for me","translations":{"es":"Me lo ha cortado Jean"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Just a little, please","translations":{"es":"Solo un poco, por favor"},"answer":"Juste un peu, s''il vous plaît"},{"prompt":"I would like a manicure","translations":{"es":"Me gustaría hacerme la manicura"},"answer":"J''aimerais une manucure"},{"prompt":"The hair dryer is broken","translations":{"es":"El secador está roto"},"answer":"Le sèche-cheveux est cassé"},{"prompt":"It''s too short!","translations":{"es":"¡Está demasiado corto!"},"answer":"C''est trop court !"},{"prompt":"She has curly hair","translations":{"es":"Tiene el pelo rizado"},"answer":"Elle a les cheveux bouclés"},{"prompt":"I would like to make an appointment","translations":{"es":"Quisiera pedir cita"},"answer":"Je voudrais prendre rendez-vous"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 57: À la bijouterie
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-57', 'À la bijouterie', '💎', 'En la joyería', 57, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la bijouterie","translation":"the jewelry store","translations":{"es":"la joyería"}},{"id":"2","word":"le bijoutier / la bijoutière","translation":"the jeweler","translations":{"es":"el joyero / la joyera"}},{"id":"3","word":"les bijoux","translation":"jewelry","translations":{"es":"las joyas"}},{"id":"4","word":"la bague","translation":"the ring","translations":{"es":"el anillo"}},{"id":"5","word":"l''alliance","translation":"the wedding ring","translations":{"es":"la alianza"}},{"id":"6","word":"le solitaire","translation":"the solitaire ring","translations":{"es":"el solitario"}},{"id":"7","word":"le collier","translation":"the necklace","translations":{"es":"el collar"}},{"id":"8","word":"le bracelet","translation":"the bracelet","translations":{"es":"la pulsera"}},{"id":"9","word":"les boucles d''oreilles","translation":"earrings","translations":{"es":"los pendientes / los aretes"}},{"id":"10","word":"le pendentif","translation":"the pendant","translations":{"es":"el colgante"}},{"id":"11","word":"le médaillon","translation":"the locket","translations":{"es":"el medallón"}},{"id":"12","word":"la breloque","translation":"the charm","translations":{"es":"el dije"}},{"id":"13","word":"la montre","translation":"the watch","translations":{"es":"el reloj"}},{"id":"14","word":"le diamant","translation":"diamond","translations":{"es":"el diamante"}},{"id":"15","word":"le rubis","translation":"ruby","translations":{"es":"el rubí"}},{"id":"16","word":"l''émeraude","translation":"emerald","translations":{"es":"la esmeralda"}},{"id":"17","word":"l''opale","translation":"opal","translations":{"es":"el ópalo"}},{"id":"18","word":"l''or","translation":"gold","translations":{"es":"el oro"}},{"id":"19","word":"l''argent","translation":"silver","translations":{"es":"la plata"}},{"id":"20","word":"précieux / précieuse","translation":"precious","translations":{"es":"precioso (valioso)"}},{"id":"21","word":"lourd / léger","translation":"heavy / light","translations":{"es":"pesado / ligero"}},{"id":"22","word":"briller","translation":"to shine","translations":{"es":"brillar"}},{"id":"23","word":"nettoyer","translation":"to clean","translations":{"es":"limpiar"}},{"id":"24","word":"le perçage","translation":"the piercing","translations":{"es":"el piercing"}},{"id":"25","word":"percer","translation":"to pierce","translations":{"es":"perforar"}},{"id":"26","word":"être allergique à","translation":"to be allergic to","translations":{"es":"ser alérgico a"}},{"id":"27","word":"économiser","translation":"to save","translations":{"es":"ahorrar"}},{"id":"28","word":"le cadeau","translation":"the gift","translations":{"es":"el regalo"}},{"id":"29","word":"perdre","translation":"to lose","translations":{"es":"perder"}},{"id":"30","word":"effrayé / effrayée","translation":"frightened","translations":{"es":"asustado / asustada"}},{"id":"31","word":"la vendeuse","translation":"the saleswoman","translations":{"es":"la vendedora"}},{"id":"32","word":"demander la main de","translation":"to propose to","translations":{"es":"pedir la mano de"}}],"grammar":[{"structure":"ni … ni","example":"Je n''aime ni les rubis ni les opales.","en":"\"Neither … nor\"","es":"«Ni … ni»"},{"structure":"l''un ou l''autre / ni l''un ni l''autre / les deux","example":"Tu préfères l''or ou l''argent ? — Ni l''un ni l''autre ! / Je vais acheter les deux.","en":"Choosing between two","es":"Elegir entre dos"},{"structure":"à condition que + subjonctif","example":"Elle peut aller à la fête à condition qu''elle soit élégante.","en":"\"On condition that\" + subjunctive","es":"«Con la condición de que» + subjuntivo"},{"structure":"il faut que / pour que + subjonctif","example":"Il faut que ce soit en or. / Nettoie-les pour qu''ils brillent.","en":"Subjunctive after necessity / purpose","es":"Subjuntivo tras necesidad / finalidad"},{"structure":"plus de … que","example":"Il a plus de bagues qu''une femme.","en":"Comparing quantities","es":"Comparar cantidades"},{"structure":"plus-que-parfait + accord","example":"La bague qu''on avait vue… / l''argent que j''avais économisé","en":"Past perfect with agreement","es":"Pluscuamperfecto con concordancia"},{"structure":"passé simple (récit)","example":"Elle tomba amoureuse de cette bague. Le vendeur sourit.","en":"Literary past","es":"Pasado literario"}],"tips":[{"en":"The passé simple (il trouva, elle sourit) is the literary past of written stories; in conversation, use the passé composé.","es":"El passé simple (il trouva, elle sourit) es el pasado literario de los relatos escritos; al hablar se usa el passé composé."},{"en":"\"Ni … ni\" replaces \"pas\": \"Je n''aime ni l''or ni l''argent.\" The articles \"un / des\" disappear: \"Il n''a ni bague ni collier.\"","es":"«Ni … ni» sustituye a «pas»: «Je n''aime ni l''or ni l''argent.» Los artículos «un / des» desaparecen: «Il n''a ni bague ni collier.»"},{"en":"Jewelry: \"une bague\" (ring), \"une alliance\" (wedding ring), \"un collier\" (necklace), \"un bracelet\", \"des boucles d''oreilles\" (earrings), \"un pendentif\" (pendant).","es":"Joyería: «une bague» (anillo), «une alliance» (alianza), «un collier» (collar), «un bracelet» (pulsera), «des boucles d''oreilles» (pendientes), «un pendentif» (colgante)."},{"en":"\"Demander la main de quelqu''un\" = to ask for someone''s hand in marriage.","es":"«Demander la main de quelqu''un» = pedir la mano de alguien."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Elle a une jolie bague et un collier spectaculaire.","translation":"She has a pretty ring and a spectacular necklace.","translations":{"es":"Tiene un anillo bonito y un collar espectacular."}},{"phrase":"De l''or ou de l''argent ?","translation":"Gold or silver?","translations":{"es":"¿Oro o plata?"}},{"phrase":"J''aimerais acheter la bague et le médaillon ensemble.","translation":"I would like to buy the ring and the locket together.","translations":{"es":"Quisiera comprar el anillo y el medallón juntos."}},{"phrase":"Je n''aime ni les rubis ni les opales.","translation":"I like neither rubies nor opals.","translations":{"es":"No me gustan ni los rubíes ni los ópalos."}},{"phrase":"Cette breloque est jolie, mais elle est très lourde.","translation":"This charm is pretty, but it''s very heavy.","translations":{"es":"Este dije es bonito, pero pesa mucho."}},{"phrase":"Elle peut aller à la fête à condition qu''elle soit élégante.","translation":"She can go to the party on condition that she is elegant.","translations":{"es":"Puede ir a la fiesta con la condición de que vaya elegante."}},{"phrase":"Il a plus de bagues qu''une star de cinéma !","translation":"He has more rings than a movie star!","translations":{"es":"¡Tiene más anillos que una estrella de cine!"}},{"phrase":"Ma mère ne porte plus ni bagues ni longues boucles d''oreilles.","translation":"My mother no longer wears rings or long earrings.","translations":{"es":"Mi madre ya no lleva ni anillos ni pendientes largos."}},{"phrase":"Tu peux m''offrir ce que tu veux, mais il faut que ce soit en or !","translation":"You can give me whatever you want, but it has to be gold!","translations":{"es":"Puedes regalarme lo que quieras, ¡pero tiene que ser de oro!"}},{"phrase":"Nettoie les bijoux avec ce chiffon pour qu''ils brillent.","translation":"Clean the jewelry with this cloth so that it shines.","translations":{"es":"Limpia las joyas con este paño para que brillen."}},{"phrase":"Tu vas acheter le collier ou les boucles d''oreilles ? — Je crois que je vais acheter les deux.","translation":"Are you going to buy the necklace or the earrings? — I think I''ll buy both.","translations":{"es":"¿Vas a comprar el collar o los pendientes? — Creo que voy a comprar los dos."}},{"phrase":"Tu préfères les bagues en or ou en argent ? — Ni l''un ni l''autre.","translation":"Do you prefer gold or silver rings? — Neither.","translations":{"es":"¿Prefieres los anillos de oro o de plata? — Ni lo uno ni lo otro."}},{"phrase":"J''ai perdu le médaillon que mon père m''avait offert.","translation":"I lost the locket my father had given me.","translations":{"es":"He perdido el medallón que me había regalado mi padre."}},{"phrase":"Pourquoi tu ne portes pas ton alliance ? — Je suis allergique à certains métaux.","translation":"Why don''t you wear your wedding ring? — I''m allergic to certain metals.","translations":{"es":"¿Por qué no llevas la alianza? — Soy alérgica a algunos metales."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Je n''aime ___ l''or ___ l''argent.\"","options":["et … et","ou … ou","pas … pas","ni … ni"],"correct":3,"explanation":"Ne … ni … ni = neither … nor.","translations":{"es":{"question":"Completa: «Je n''aime ___ l''or ___ l''argent.»","explanation":"Ne … ni … ni = ni … ni."}}},{"id":"2","question":"\"Tu veux le collier ou la bague ? — Ni l''un ni l''autre.\" Meaning?","options":["Either one.","The other one.","Both.","Neither."],"correct":3,"explanation":"Both = les deux.","translations":{"es":{"question":"«Tu veux le collier ou la bague ? — Ni l''un ni l''autre.» ¿Significado?","explanation":"Los dos = les deux.","options":["Cualquiera.","El otro.","Los dos.","Ninguno de los dos."]}}},{"id":"3","question":"Complete: \"Tu peux venir à condition que tu ___ à l''heure.\"","options":["es","étais","seras","sois"],"correct":3,"explanation":"\"À condition que\" + subjunctive.","translations":{"es":{"question":"Completa: «Tu peux venir à condition que tu ___ à l''heure.»","explanation":"«À condition que» + subjuntivo."}}},{"id":"4","question":"Complete: \"Il faut que ce ___ en or.\"","options":["serait","est","sera","soit"],"correct":3,"explanation":"\"Il faut que\" + subjunctive.","translations":{"es":{"question":"Completa: «Il faut que ce ___ en or.»","explanation":"«Il faut que» + subjuntivo."}}},{"id":"5","question":"Complete: \"Il a ___ bagues que moi.\"","options":["plus des","beaucoup","plus que","plus de"],"correct":3,"explanation":"Quantities: plus de + noun + que.","translations":{"es":{"question":"Completa: «Il a ___ bagues que moi.»","explanation":"Cantidades: plus de + sustantivo + que."}}},{"id":"6","question":"What is \"une alliance\"?","options":["a necklace","a watch","a bracelet","a wedding ring"],"correct":3,"explanation":"Worn after the wedding.","translations":{"es":{"question":"¿Qué es «une alliance»?","explanation":"Se lleva tras la boda.","options":["un collar","un reloj","una pulsera","una alianza (anillo de boda)"]}}},{"id":"7","question":"Complete: \"La bague qu''on avait ___ était parfaite.\"","options":["vues","vu","voir","vue"],"correct":3,"explanation":"Agreement with \"que\" (la bague) before avoir.","translations":{"es":{"question":"Completa: «La bague qu''on avait ___ était parfaite.»","explanation":"Concordancia con «que» (la bague) antes de avoir."}}},{"id":"8","question":"Complete: \"Nettoie-les pour qu''ils ___.\"","options":["brilleront","brillent-ils","brillaient","brillent"],"correct":3,"explanation":"\"Pour que\" + subjunctive.","translations":{"es":{"question":"Completa: «Nettoie-les pour qu''ils ___.»","explanation":"«Pour que» + subjuntivo."}}}]}'::jsonb, 3),
  ('story', 'La bague de fiançailles', '{"text":"Pendant un an, j''avais économisé pour acheter une bague de fiançailles à ma copine, Inès, et lui demander sa main. Elle était tombée amoureuse d''une bague avec un petit diamant qu''on avait vue dans une bijouterie d''Annecy, pendant nos vacances. Le mois dernier, je suis retourné à Annecy afin de l''acheter. Dans la bijouterie, j''ai demandé à la vendeuse la bague qu''Inès aimait. Par chance, c''était exactement sa taille. « Vous voulez aussi un écrin ? » me demanda-t-elle. « Oui, à condition qu''il ne soit pas trop cher ! » Je suis reparti tout content. Mais dans le train du retour, je me suis endormi. En arrivant à Lyon, j''ai cherché l''écrin dans ma poche : il n''était plus là ! J''étais effrayé : j''allais perdre tout l''argent que j''avais économisé. Je n''avais ni la bague ni le ticket de caisse. Soudain, une petite fille s''approcha de moi. « Monsieur, c''est à vous ? C''était tombé sous votre siège. » Je ne pouvais ni parler ni bouger, tellement j''étais soulagé. Le soir même, j''ai demandé Inès en mariage. Elle a dit oui… et elle ne sait toujours pas que la bague a voyagé toute seule sous un siège de train !","translation":"For a year, I had saved up to buy an engagement ring for my girlfriend, Inès, and ask for her hand. She had fallen in love with a ring with a small diamond that we had seen in a jewelry store in Annecy, during our vacation. Last month, I went back to Annecy to buy it. In the store, I asked the saleswoman for the ring Inès liked. Luckily, it was exactly her size. “Would you also like a box?” she asked me. “Yes, as long as it''s not too expensive!” I left very happy. But on the train home, I fell asleep. Arriving in Lyon, I looked for the box in my pocket: it wasn''t there anymore! I was terrified: I was going to lose all the money I had saved. I had neither the ring nor the receipt. Suddenly, a little girl came up to me. “Sir, is this yours? It had fallen under your seat.” I could neither speak nor move, I was so relieved. That same evening, I asked Inès to marry me. She said yes… and she still doesn''t know the ring traveled all alone under a train seat!","translations":{"es":"Durante un año había ahorrado para comprarle un anillo de compromiso a mi novia, Inès, y pedirle la mano. Se había enamorado de un anillo con un pequeño diamante que habíamos visto en una joyería de Annecy, durante las vacaciones. El mes pasado volví a Annecy para comprarlo. En la joyería, le pedí a la vendedora el anillo que le gustaba a Inès. Por suerte, era justo de su talla. «¿Quiere también un estuche?», me preguntó. «¡Sí, con la condición de que no sea demasiado caro!» Salí contentísimo. Pero en el tren de vuelta me quedé dormido. Al llegar a Lyon, busqué el estuche en el bolsillo: ¡ya no estaba! Estaba aterrado: iba a perder todo el dinero que había ahorrado. No tenía ni el anillo ni el tique. De repente, una niña se me acercó. «Señor, ¿esto es suyo? Se había caído debajo de su asiento.» No podía ni hablar ni moverme del alivio. Esa misma noche le pedí matrimonio a Inès. Dijo que sí… ¡y todavía no sabe que el anillo viajó solito debajo de un asiento de tren!"},"highlighted_words":["j''avais économisé","demander sa main","était tombée amoureuse","qu''on avait vue","bijouterie","afin de","demanda","à condition qu''il ne soit pas","que j''avais économisé","ni la bague ni le ticket","s''approcha","ni parler ni bouger"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","n''aime","ni","l''or","ni","l''argent"],"translation":"I like neither gold nor silver","translations":{"es":"No me gustan ni el oro ni la plata"}},{"words":["Je","vais","acheter","les","deux"],"translation":"I''m going to buy both","translations":{"es":"Voy a comprar los dos"}},{"words":["Il","faut","que","ce","soit","en","or"],"translation":"It has to be gold","translations":{"es":"Tiene que ser de oro"}},{"words":["Elle","a","plus","de","bijoux","que","moi"],"translation":"She has more jewelry than me","translations":{"es":"Tiene más joyas que yo"}},{"words":["Cette","bague","brille","beaucoup"],"translation":"This ring shines a lot","translations":{"es":"Este anillo brilla mucho"}},{"words":["J''ai","perdu","mon","collier"],"translation":"I lost my necklace","translations":{"es":"He perdido mi collar"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Is it gold?","translations":{"es":"¿Es de oro?"},"answer":"C''est en or ?"},{"prompt":"I like these earrings","translations":{"es":"Me gustan estos pendientes"},"answer":"J''aime ces boucles d''oreilles"},{"prompt":"Neither one","translations":{"es":"Ninguno de los dos"},"answer":"Ni l''un ni l''autre"},{"prompt":"I would like a silver ring","translations":{"es":"Quisiera un anillo de plata"},"answer":"Je voudrais une bague en argent"},{"prompt":"She said yes","translations":{"es":"Dijo que sí"},"answer":"Elle a dit oui"},{"prompt":"It''s a gift for my mother","translations":{"es":"Es un regalo para mi madre"},"answer":"C''est un cadeau pour ma mère"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 58: La voiture
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-58', 'La voiture', '🚙', 'El coche', 58, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"la voiture","translation":"the car","translations":{"es":"el coche / el carro"}},{"id":"2","word":"le cabriolet","translation":"the convertible","translations":{"es":"el descapotable"}},{"id":"3","word":"la camionnette","translation":"the van","translations":{"es":"la furgoneta"}},{"id":"4","word":"le monospace","translation":"the minivan","translations":{"es":"el monovolumen"}},{"id":"5","word":"le volant","translation":"the steering wheel","translations":{"es":"el volante"}},{"id":"6","word":"le siège","translation":"the seat","translations":{"es":"el asiento"}},{"id":"7","word":"la ceinture de sécurité","translation":"the seat belt","translations":{"es":"el cinturón de seguridad"}},{"id":"8","word":"la boucle","translation":"the buckle","translations":{"es":"la hebilla"}},{"id":"9","word":"l''accélérateur","translation":"the accelerator","translations":{"es":"el acelerador"}},{"id":"10","word":"le frein","translation":"the brake","translations":{"es":"el freno"}},{"id":"11","word":"le frein à main","translation":"the handbrake","translations":{"es":"el freno de mano"}},{"id":"12","word":"l''embrayage","translation":"the clutch","translations":{"es":"el embrague"}},{"id":"13","word":"le levier de vitesse","translation":"the gear stick","translations":{"es":"la palanca de cambios"}},{"id":"14","word":"le moteur","translation":"the engine","translations":{"es":"el motor"}},{"id":"15","word":"le démarreur","translation":"the starter","translations":{"es":"el motor de arranque"}},{"id":"16","word":"démarrer","translation":"to start","translations":{"es":"arrancar"}},{"id":"17","word":"le capot","translation":"the hood","translations":{"es":"el capó"}},{"id":"18","word":"le coffre","translation":"the trunk","translations":{"es":"el maletero"}},{"id":"19","word":"le pare-chocs","translation":"the bumper","translations":{"es":"el parachoques"}},{"id":"20","word":"le pare-brise","translation":"the windshield","translations":{"es":"el parabrisas"}},{"id":"21","word":"les essuie-glaces","translation":"the wipers","translations":{"es":"los limpiaparabrisas"}},{"id":"22","word":"le rétroviseur","translation":"the rearview mirror","translations":{"es":"el retrovisor"}},{"id":"23","word":"les phares","translation":"the headlights","translations":{"es":"los faros"}},{"id":"24","word":"le clignotant","translation":"the turn signal","translations":{"es":"el intermitente"}},{"id":"25","word":"le klaxon","translation":"the horn","translations":{"es":"el claxon"}},{"id":"26","word":"klaxonner","translation":"to honk","translations":{"es":"tocar el claxon"}},{"id":"27","word":"le pneu","translation":"the tire","translations":{"es":"el neumático / la llanta"}},{"id":"28","word":"le pneu crevé","translation":"the flat tire","translations":{"es":"el pinchazo"}},{"id":"29","word":"la roue de secours","translation":"the spare wheel","translations":{"es":"la rueda de repuesto"}},{"id":"30","word":"le réservoir","translation":"the tank","translations":{"es":"el depósito"}},{"id":"31","word":"la boîte à gants","translation":"the glove box","translations":{"es":"la guantera"}},{"id":"32","word":"le chauffage","translation":"the heater","translations":{"es":"la calefacción"}},{"id":"33","word":"la plaque d''immatriculation","translation":"the license plate","translations":{"es":"la matrícula"}},{"id":"34","word":"l''assurance","translation":"the insurance","translations":{"es":"el seguro"}},{"id":"35","word":"la limitation de vitesse","translation":"the speed limit","translations":{"es":"el límite de velocidad"}},{"id":"36","word":"l''amende","translation":"the fine","translations":{"es":"la multa"}},{"id":"37","word":"la rayure","translation":"the scratch","translations":{"es":"el rayón"}},{"id":"38","word":"tomber en panne","translation":"to break down","translations":{"es":"averiarse"}},{"id":"39","word":"malgré","translation":"despite","translations":{"es":"a pesar de"}},{"id":"40","word":"sauf","translation":"except","translations":{"es":"excepto"}}],"grammar":[{"structure":"prépositions de lieu","example":"entre, au milieu de, devant, derrière, sous, à travers","en":"Prepositions of place","es":"Preposiciones de lugar"},{"structure":"malgré + nom / bien que + subjonctif","example":"Malgré la pluie, la camionnette n''a pas eu de problème. / Bien qu''il n''y ait pas de circulation, certains roulaient trop vite.","en":"Concession","es":"Concesión"},{"structure":"sauf / à part","example":"La voiture est bien, sauf le levier de vitesse.","en":"\"Except\"","es":"«Excepto»"},{"structure":"il y a … que","example":"Il y a vingt ans que nous avons la même voiture.","en":"Duration up to now","es":"Hace … que"},{"structure":"avant de + infinitif","example":"Avant de vérifier le moteur, essayons de démarrer encore une fois.","en":"\"Before doing\"","es":"«Antes de»"},{"structure":"être sur le point de","example":"J''étais sur le point d''avoir un accident.","en":"\"About to\"","es":"«A punto de»"},{"structure":"passé simple / imparfait (récit)","example":"Je roulais vers Paris quand le pneu éclata.","en":"Narrative tenses","es":"Tiempos del relato"}],"tips":[{"en":"The passé simple (il trouva, elle sourit) is the literary past of written stories; in conversation, use the passé composé.","es":"El passé simple (il trouva, elle sourit) es el pasado literario de los relatos escritos; al hablar se usa el passé composé."},{"en":"\"Bien que\" ALWAYS takes the subjunctive: \"bien qu''il pleuve\", \"bien qu''il n''y ait pas de circulation\" (the audio says \"bien qu''il n''y avait\", which is a common mistake).","es":"«Bien que» va SIEMPRE con subjuntivo: «bien qu''il pleuve», «bien qu''il n''y ait pas de circulation» (el audio dice «bien qu''il n''y avait», un error frecuente)."},{"en":"Car parts: \"le volant\" (steering wheel), \"le capot\" (hood), \"le coffre\" (trunk), \"le pare-chocs\" (bumper), \"le rétroviseur\" (rearview mirror), \"les essuie-glaces\" (wipers), \"le clignotant\" (turn signal).","es":"Partes del coche: «le volant» (volante), «le capot» (capó), «le coffre» (maletero), «le pare-chocs» (parachoques), «le rétroviseur» (retrovisor), «les essuie-glaces» (limpiaparabrisas), «le clignotant» (intermitente)."},{"en":"\"Avoir un accident\" (not \"s''accidenter\" in standard French); \"crever\" = to get a flat tire; \"tomber en panne\" = to break down.","es":"«Avoir un accident» (no «s''accidenter» en francés estándar); «crever» = pinchar; «tomber en panne» = averiarse."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Achetons une nouvelle voiture : il y a vingt ans que nous avons la même !","translation":"Let''s buy a new car: we''ve had the same one for twenty years!","translations":{"es":"¡Compremos un coche nuevo: hace veinte años que tenemos el mismo!"}},{"phrase":"Avant de vérifier le moteur, essayons de démarrer encore une fois.","translation":"Before checking the engine, let''s try starting it once more.","translations":{"es":"Antes de revisar el motor, intentemos arrancar otra vez."}},{"phrase":"Nous avons eu un accident, mais personne n''a été blessé : nous avions nos ceintures.","translation":"We had an accident, but nobody was hurt: we had our seat belts on.","translations":{"es":"Tuvimos un accidente, pero nadie resultó herido: llevábamos el cinturón."}},{"phrase":"Malgré la pluie, la camionnette n''a eu aucun problème.","translation":"Despite the rain, the van had no problems.","translations":{"es":"A pesar de la lluvia, la furgoneta no tuvo ningún problema."}},{"phrase":"La voiture est bien, sauf le levier de vitesse.","translation":"The car is fine, except for the gear stick.","translations":{"es":"El coche está bien, excepto la palanca de cambios."}},{"phrase":"Freine quand les feux de la voiture devant toi s''allument.","translation":"Brake when the lights of the car in front of you come on.","translations":{"es":"Frena cuando se enciendan las luces del coche de delante."}},{"phrase":"La carte est dans la boîte à gants.","translation":"The map is in the glove box.","translations":{"es":"El mapa está en la guantera."}},{"phrase":"Nous avons un pneu crevé.","translation":"We have a flat tire.","translations":{"es":"Tenemos un pinchazo."}},{"phrase":"J''étais sur le point d''avoir un accident.","translation":"I was about to have an accident.","translations":{"es":"Estuve a punto de tener un accidente."}},{"phrase":"Le frein se trouve entre l''accélérateur et l''embrayage.","translation":"The brake is between the accelerator and the clutch.","translations":{"es":"El freno está entre el acelerador y el embrague."}},{"phrase":"Je ne peux pas attacher ma ceinture : la boucle est cassée.","translation":"I can''t fasten my seat belt: the buckle is broken.","translations":{"es":"No puedo abrocharme el cinturón: la hebilla está rota."}},{"phrase":"Pourquoi ta voiture ne démarre pas ? — Le démarreur est en train de lâcher.","translation":"Why won''t your car start? — The starter is giving out.","translations":{"es":"¿Por qué no arranca tu coche? — El motor de arranque está fallando."}},{"phrase":"Pourquoi ton pare-brise est si sale ? — Mes essuie-glaces sont usés.","translation":"Why is your windshield so dirty? — My wipers are worn out.","translations":{"es":"¿Por qué tienes el parabrisas tan sucio? — Tengo los limpiaparabrisas gastados."}},{"phrase":"Elle conduit bien, mais elle oublie de mettre son clignotant.","translation":"She drives well, but she forgets to use her turn signal.","translations":{"es":"Conduce bien, pero se le olvida poner el intermitente."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Complete: \"Bien qu''il ___, nous partons.\"","options":["pleuve","pleut","pleuvra","pleuvait"],"correct":0,"explanation":"\"Bien que\" always takes the subjunctive.","translations":{"es":{"question":"Completa: «Bien qu''il ___, nous partons.»","explanation":"«Bien que» siempre lleva subjuntivo."}}},{"id":"2","question":"Complete: \"___ la neige, nous sommes arrivés à l''heure.\"","options":["Bien que","Malgré","Avant de","Sauf"],"correct":1,"explanation":"\"Malgré\" + noun.","translations":{"es":{"question":"Completa: «___ la neige, nous sommes arrivés à l''heure.»","explanation":"«Malgré» + sustantivo."}}},{"id":"3","question":"Where is the brake?","options":["sous le capot","entre l''accélérateur et l''embrayage","derrière le volant","dans le coffre"],"correct":1,"explanation":"In a manual car.","translations":{"es":{"question":"¿Dónde está el freno?","explanation":"En un coche manual."}}},{"id":"4","question":"What is \"un pneu crevé\"?","options":["a broken window","a new tire","a flat tire","a spare tire"],"correct":2,"explanation":"Crever = to puncture.","translations":{"es":{"question":"¿Qué es «un pneu crevé»?","explanation":"Crever = pinchar.","options":["una ventanilla rota","un neumático nuevo","un pinchazo","una rueda de repuesto"]}}},{"id":"5","question":"Where do you keep the map in the car?","options":["dans le capot","dans le moteur","dans la boîte à gants","dans le pare-chocs"],"correct":2,"explanation":"La boîte à gants = glove box.","translations":{"es":{"question":"¿Dónde guardas el mapa en el coche?","explanation":"La boîte à gants = guantera."}}},{"id":"6","question":"How do you say \"to have an accident\" in standard French?","options":["s''accidenter","tomber un accident","avoir un accident","faire accident"],"correct":2,"explanation":"\"S''accidenter\" is not standard.","translations":{"es":{"question":"¿Cómo se dice «tener un accidente» en francés estándar?","explanation":"«S''accidenter» no es estándar."}}},{"id":"7","question":"Complete: \"La voiture est parfaite, ___ la radio.\"","options":["pendant","malgré","sauf","bien que"],"correct":2,"explanation":"Sauf = except.","translations":{"es":{"question":"Completa: «La voiture est parfaite, ___ la radio.»","explanation":"Sauf = excepto."}}},{"id":"8","question":"What is \"le rétroviseur\"?","options":["the rearview mirror","the horn","the windshield","the trunk"],"correct":0,"explanation":"Rétro = backwards; viseur = viewer.","translations":{"es":{"question":"¿Qué es «le rétroviseur»?","explanation":"Rétro = atrás; viseur = visor.","options":["el retrovisor","el claxon","el parabrisas","el maletero"]}}}]}'::jsonb, 3),
  ('story', 'Une nuit sur la route', '{"text":"Je roulais vers Lyon pour un congrès. Bien qu''il n''y ait pas beaucoup de circulation sur l''autoroute, il pleuvait très fort et les essuie-glaces avaient du mal à nettoyer le pare-brise. Soudain, j''entendis un bruit terrible : un pneu venait d''éclater ! La voiture glissa vers la droite et je fus sur le point de perdre le contrôle. Heureusement, je réussis à m''arrêter sur la bande d''arrêt d''urgence. J''avais encore ma ceinture de sécurité et je n''étais pas blessée, mais j''avais très peur. J''ai allumé les feux de détresse et j''ai mis mon gilet jaune avant de sortir. Malgré la pluie, j''ai essayé de changer la roue, mais je n''arrivais pas à dévisser les écrous. Après vingt minutes, un camion s''est arrêté derrière moi. Le chauffeur, un homme très gentil, a sorti la roue de secours du coffre et l''a changée en dix minutes. « Vous devriez vérifier vos pneus plus souvent », m''a-t-il dit en souriant. Je suis arrivée à Lyon avec deux heures de retard, trempée mais saine et sauve. Le lendemain, l''assurance m''a remboursé un pneu neuf. Depuis, je vérifie toujours mes pneus avant de partir !","translation":"I was driving to Lyon for a conference. Although there wasn''t much traffic on the highway, it was raining very hard and the wipers were struggling to clear the windshield. Suddenly, I heard a terrible noise: a tire had just burst! The car slid to the right and I was about to lose control. Fortunately, I managed to stop on the hard shoulder. I still had my seat belt on and I wasn''t hurt, but I was very scared. I turned on the hazard lights and put on my yellow vest before getting out. Despite the rain, I tried to change the wheel, but I couldn''t undo the nuts. After twenty minutes, a truck stopped behind me. The driver, a very kind man, took the spare wheel out of the trunk and changed it in ten minutes. “You should check your tires more often,” he told me with a smile. I arrived in Lyon two hours late, soaked but safe and sound. The next day, the insurance paid for a new tire. Since then, I always check my tires before leaving!","translations":{"es":"Iba conduciendo hacia Lyon para un congreso. Aunque no había mucho tráfico en la autopista, llovía muchísimo y a los limpiaparabrisas les costaba limpiar el parabrisas. De repente oí un ruido terrible: ¡acababa de reventar un neumático! El coche se deslizó hacia la derecha y estuve a punto de perder el control. Por suerte, conseguí detenerme en el arcén. Todavía llevaba el cinturón y no estaba herida, pero tenía mucho miedo. Encendí las luces de emergencia y me puse el chaleco amarillo antes de salir. A pesar de la lluvia, intenté cambiar la rueda, pero no conseguía aflojar las tuercas. Al cabo de veinte minutos, un camión se paró detrás de mí. El conductor, un hombre muy amable, sacó la rueda de repuesto del maletero y la cambió en diez minutos. «Debería revisar los neumáticos más a menudo», me dijo sonriendo. Llegué a Lyon con dos horas de retraso, empapada pero sana y salva. Al día siguiente, el seguro me pagó un neumático nuevo. ¡Desde entonces siempre reviso los neumáticos antes de salir!"},"highlighted_words":["Je roulais","Bien qu''il n''y ait pas","essuie-glaces","pare-brise","entendis","venait d''éclater","glissa","je fus sur le point de","ceinture de sécurité","avant de sortir","Malgré la pluie","roue de secours","coffre","l''assurance"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Nous","avons","un","pneu","crevé"],"translation":"We have a flat tire","translations":{"es":"Tenemos un pinchazo"}},{"words":["Malgré","la","pluie","nous","sommes","partis"],"translation":"Despite the rain we left","translations":{"es":"A pesar de la lluvia, salimos"}},{"words":["Bien","qu''il","soit","tard","je","conduis"],"translation":"Although it''s late I''m driving","translations":{"es":"Aunque es tarde, conduzco"}},{"words":["La","carte","est","dans","la","boîte","à","gants"],"translation":"The map is in the glove box","translations":{"es":"El mapa está en la guantera"}},{"words":["Attache","ta","ceinture","avant","de","démarrer"],"translation":"Fasten your seat belt before starting","translations":{"es":"Abróchate el cinturón antes de arrancar"}},{"words":["La","voiture","est","tombée","en","panne"],"translation":"The car broke down","translations":{"es":"El coche se averió"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"Open the trunk","translations":{"es":"Abra el maletero"},"answer":"Ouvrez le coffre"},{"prompt":"The car won''t start","translations":{"es":"El coche no arranca"},"answer":"La voiture ne démarre pas"},{"prompt":"Turn on the headlights","translations":{"es":"Enciende los faros"},"answer":"Allume les phares"},{"prompt":"I had an accident","translations":{"es":"He tenido un accidente"},"answer":"J''ai eu un accident"},{"prompt":"You are driving too fast","translations":{"es":"Vas demasiado rápido"},"answer":"Tu roules trop vite"},{"prompt":"The engine is making a strange noise","translations":{"es":"El motor hace un ruido raro"},"answer":"Le moteur fait un bruit bizarre"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 59: Chez l'avocat
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-59', 'Chez l''avocat', '⚖️', 'En el abogado', 59, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"l''avocat / l''avocate","translation":"the lawyer","translations":{"es":"el abogado / la abogada"}},{"id":"2","word":"le juge","translation":"the judge","translations":{"es":"el juez"}},{"id":"3","word":"le tribunal","translation":"the court","translations":{"es":"el tribunal"}},{"id":"4","word":"le procès","translation":"the trial","translations":{"es":"el juicio"}},{"id":"5","word":"la défense","translation":"the defense","translations":{"es":"la defensa"}},{"id":"6","word":"l''accusation","translation":"the prosecution / charge","translations":{"es":"la acusación"}},{"id":"7","word":"le témoin","translation":"the witness","translations":{"es":"el testigo"}},{"id":"8","word":"la preuve","translation":"the evidence","translations":{"es":"la prueba"}},{"id":"9","word":"l''argument","translation":"the argument","translations":{"es":"el argumento"}},{"id":"10","word":"le suspect","translation":"the suspect","translations":{"es":"el sospechoso"}},{"id":"11","word":"coupable","translation":"guilty","translations":{"es":"culpable"}},{"id":"12","word":"innocent / innocente","translation":"innocent","translations":{"es":"inocente"}},{"id":"13","word":"la prison","translation":"prison","translations":{"es":"la cárcel"}},{"id":"14","word":"arrêter","translation":"to arrest","translations":{"es":"detener"}},{"id":"15","word":"dénoncer","translation":"to report / denounce","translations":{"es":"denunciar"}},{"id":"16","word":"l''enquête","translation":"the investigation","translations":{"es":"la investigación"}},{"id":"17","word":"la fraude","translation":"fraud","translations":{"es":"el fraude"}},{"id":"18","word":"le vol","translation":"theft","translations":{"es":"el robo"}},{"id":"19","word":"le délit","translation":"the offense","translations":{"es":"el delito"}},{"id":"20","word":"corrompu / corrompue","translation":"corrupt","translations":{"es":"corrupto / corrupta"}},{"id":"21","word":"la caution","translation":"bail","translations":{"es":"la fianza"}},{"id":"22","word":"le testament","translation":"the will","translations":{"es":"el testamento"}},{"id":"23","word":"l''héritage","translation":"the inheritance","translations":{"es":"la herencia"}},{"id":"24","word":"adopté / adoptée","translation":"adopted","translations":{"es":"adoptado / adoptada"}},{"id":"25","word":"la transaction","translation":"the transaction","translations":{"es":"la transacción"}},{"id":"26","word":"la dette","translation":"the debt","translations":{"es":"la deuda"}},{"id":"27","word":"cependant / pourtant","translation":"however / yet","translations":{"es":"sin embargo / no obstante"}},{"id":"28","word":"néanmoins","translation":"nevertheless","translations":{"es":"no obstante"}},{"id":"29","word":"en revanche / par contre","translation":"on the other hand","translations":{"es":"en cambio / por el contrario"}},{"id":"30","word":"en plus / de plus","translation":"moreover","translations":{"es":"además"}},{"id":"31","word":"en outre","translation":"furthermore","translations":{"es":"además (formal)"}},{"id":"32","word":"par conséquent / donc","translation":"therefore","translations":{"es":"por consiguiente / por lo tanto"}},{"id":"33","word":"de toute façon","translation":"anyway","translations":{"es":"de todos modos"}}],"grammar":[{"structure":"connecteurs d''opposition","example":"cependant, pourtant, néanmoins, en revanche, par contre","en":"Contrast connectors","es":"Conectores de oposición"},{"structure":"connecteurs d''addition","example":"en plus, de plus, en outre","en":"Adding information","es":"Conectores de adición"},{"structure":"connecteurs de conséquence","example":"donc, par conséquent, c''est pourquoi","en":"Consequence connectors","es":"Conectores de consecuencia"},{"structure":"bien que + subjonctif","example":"Bien qu''il ait dix avocats, il ira en prison.","en":"\"Although\" + subjunctive","es":"«Aunque» + subjuntivo"},{"structure":"voix passive (passé)","example":"Elle a été dénoncée sept fois, mais elle n''a jamais été arrêtée.","en":"Passive in the past","es":"Pasiva en pasado"},{"structure":"quand + futur","example":"Elle recevra l''argent quand elle aura dix-huit ans.","en":"Future after \"quand\"","es":"Futuro tras «quand»"},{"structure":"plus-que-parfait (récit)","example":"Il ne savait pas que ce collègue avait été payé pour le piéger.","en":"Past perfect","es":"Pluscuamperfecto"},{"structure":"passé simple (récit)","example":"Il accepta. Quelques semaines plus tard, il fut arrêté.","en":"Literary past","es":"Pasado literario"}],"tips":[{"en":"The passé simple (il trouva, elle sourit) is the literary past of written stories; in conversation, use the passé composé.","es":"El passé simple (il trouva, elle sourit) es el pasado literario de los relatos escritos; al hablar se usa el passé composé."},{"en":"\"En revanche\" and \"par contre\" both mean \"on the other hand\"; \"par contre\" is more informal.","es":"«En revanche» y «par contre» significan «en cambio»; «par contre» es más coloquial."},{"en":"\"Bien que\" + subjunctive (\"bien qu''il soit\"); \"même si\" + indicative (\"même s''il est\"). They mean almost the same.","es":"«Bien que» + subjuntivo («bien qu''il soit»); «même si» + indicativo («même s''il est»). Significan casi lo mismo."},{"en":"Legal words: \"l''avocat(e)\" (lawyer), \"le juge\" (judge), \"le procès\" (trial), \"le témoin\" (witness), \"la preuve\" (evidence), \"coupable / innocent\" (guilty / innocent), \"la caution\" (bail).","es":"Vocabulario jurídico: «l''avocat(e)» (abogado/a), «le juge» (juez), «le procès» (juicio), «le témoin» (testigo), «la preuve» (prueba), «coupable / innocent» (culpable / inocente), «la caution» (fianza)."}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Elle a été dénoncée sept fois, mais elle n''a jamais été arrêtée.","translation":"She was reported seven times, but she was never arrested.","translations":{"es":"La denunciaron siete veces, pero nunca la detuvieron."}},{"phrase":"C''est une bonne avocate ; par contre, son associé n''est pas honnête.","translation":"She''s a good lawyer; on the other hand, her partner isn''t honest.","translations":{"es":"Es una buena abogada; en cambio, su socio no es honrado."}},{"phrase":"Bien qu''il ait dix avocats, il ira de toute façon en prison.","translation":"Although he has ten lawyers, he''ll go to prison anyway.","translations":{"es":"Aunque tiene diez abogados, irá a la cárcel de todos modos."}},{"phrase":"Son testament dit que la maison appartient à son petit-fils. Par conséquent, elle n''aura rien.","translation":"His will says the house belongs to his grandson. Therefore, she will get nothing.","translations":{"es":"Su testamento dice que la casa pertenece a su nieto. Por consiguiente, ella no tendrá nada."}},{"phrase":"Elle recevra l''argent quand elle aura dix-huit ans ; cependant, elle touchera une pension chaque mois.","translation":"She will receive the money when she turns eighteen; however, she will get a monthly allowance.","translations":{"es":"Recibirá el dinero cuando cumpla dieciocho años; sin embargo, cobrará una pensión cada mes."}},{"phrase":"Il n''avait pas assez de preuves pour prouver son innocence. En plus, trois témoins étaient contre lui.","translation":"He didn''t have enough evidence to prove his innocence. Moreover, three witnesses were against him.","translations":{"es":"No tenía pruebas suficientes para demostrar su inocencia. Además, tres testigos estaban en su contra."}},{"phrase":"L''avocat n''avait pas de bons arguments pour la défense.","translation":"The lawyer didn''t have good arguments for the defense.","translations":{"es":"El abogado no tenía buenos argumentos para la defensa."}},{"phrase":"Tu es un bon avocat ; néanmoins, la partie adverse a une équipe excellente.","translation":"You''re a good lawyer; nevertheless, the other side has an excellent team.","translations":{"es":"Eres un buen abogado; no obstante, la parte contraria tiene un equipo excelente."}},{"phrase":"Comment ? Il a été déclaré innocent ? — Il avait un très bon avocat, donc il a gagné.","translation":"What? He was declared innocent? — He had a very good lawyer, so he won.","translations":{"es":"¿Cómo? ¿Lo declararon inocente? — Tenía un abogado muy bueno, así que ganó."}},{"phrase":"Elle a un bon avocat ? — Oui, pourtant elle est coupable.","translation":"Does she have a good lawyer? — Yes, and yet she is guilty.","translations":{"es":"¿Tiene un buen abogado? — Sí, y sin embargo es culpable."}},{"phrase":"Pourquoi a-t-on arrêté ton cousin ? — Il était impliqué dans des affaires illégales.","translation":"Why was your cousin arrested? — He was involved in illegal business.","translations":{"es":"¿Por qué detuvieron a tu primo? — Estaba metido en negocios ilegales."}},{"phrase":"Est-elle encore en prison ? — Oui, mais elle sortira bientôt.","translation":"Is she still in prison? — Yes, but she will be out soon.","translations":{"es":"¿Sigue en la cárcel? — Sí, pero saldrá pronto."}},{"phrase":"Ils ont trouvé des preuves contre lui ? — Oui, c''est pourquoi il est en prison.","translation":"Did they find evidence against him? — Yes, that''s why he''s in prison.","translations":{"es":"¿Encontraron pruebas contra él? — Sí, por eso está en la cárcel."}},{"phrase":"Elle a gagné le procès ? — Bien sûr ! En plus, elle a reçu des dommages et intérêts.","translation":"Did she win the trial? — Of course! Moreover, she received damages.","translations":{"es":"¿Ganó el juicio? — ¡Claro! Además, recibió una indemnización."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"Which connector expresses contrast?","options":["cependant","en plus","donc","par conséquent"],"correct":0,"explanation":"Cependant = however.","translations":{"es":{"question":"¿Qué conector expresa oposición?","explanation":"Cependant = sin embargo."}}},{"id":"2","question":"Which connector expresses consequence?","options":["en revanche","par conséquent","pourtant","en outre"],"correct":1,"explanation":"Par conséquent = therefore.","translations":{"es":{"question":"¿Qué conector expresa consecuencia?","explanation":"Par conséquent = por consiguiente."}}},{"id":"3","question":"Complete: \"Bien qu''il ___ innocent, il est en prison.\"","options":["est","sera","soit","était"],"correct":2,"explanation":"\"Bien que\" + subjunctive.","translations":{"es":{"question":"Completa: «Bien qu''il ___ innocent, il est en prison.»","explanation":"«Bien que» + subjuntivo."}}},{"id":"4","question":"Complete: \"Même s''il ___ innocent, il est en prison.\"","options":["serait","soit","est","sera"],"correct":2,"explanation":"\"Même si\" + indicative.","translations":{"es":{"question":"Completa: «Même s''il ___ innocent, il est en prison.»","explanation":"«Même si» + indicativo."}}},{"id":"5","question":"Passive: \"La police a arrêté le voleur.\" → ?","options":["Le voleur est arrêté la police.","Le voleur a arrêté par la police.","Le voleur a été arrêté par la police.","La police a été arrêtée par le voleur."],"correct":2,"explanation":"avoir été + participle + par.","translations":{"es":{"question":"Pasiva: «La police a arrêté le voleur.» → ?","explanation":"avoir été + participio + par."}}},{"id":"6","question":"What is \"un témoin\"?","options":["a lawyer","a witness","a judge","a thief"],"correct":1,"explanation":"He or she saw what happened.","translations":{"es":{"question":"¿Qué es «un témoin»?","explanation":"Vio lo que pasó.","options":["un abogado","un testigo","un juez","un ladrón"]}}},{"id":"7","question":"Complete: \"Elle héritera quand elle ___ majeure.\"","options":["sera","soit","est","serait"],"correct":0,"explanation":"Future after \"quand\".","translations":{"es":{"question":"Completa: «Elle héritera quand elle ___ majeure.»","explanation":"Futuro tras «quand»."}}},{"id":"8","question":"\"En revanche\" means…","options":["on the other hand","moreover","in revenge","therefore"],"correct":0,"explanation":"Synonym: par contre.","translations":{"es":{"question":"«En revanche» significa…","explanation":"Sinónimo: par contre.","options":["en cambio","además","como venganza","por lo tanto"]}}}]}'::jsonb, 3),
  ('story', 'Accusé de fraude', '{"text":"Mon frère Karim est comptable dans une grande entreprise de Marseille. Il a toujours été honnête et apprécié par ses chefs. Cependant, il y a un an, il traversa une période difficile. Bien que son travail lui plaise, son salaire ne suffisait pas à payer ses dettes. Un jour, un collègue lui proposa un moyen de s''en sortir : quelques transactions « un peu spéciales ». Karim hésita ; néanmoins, comme il était désespéré, il accepta. Il ne savait pas que ce collègue avait été payé par un directeur corrompu pour le piéger. Quelques semaines plus tard, après avoir signé des documents qui prouvaient la fraude, il fut arrêté. Il ne savait pas quoi faire, car il savait qu''il avait commis une erreur, même s''il n''avait jamais reçu d''argent. Heureusement, ses anciens chefs payèrent sa caution et lui trouvèrent une excellente avocate. Pendant l''enquête, elle découvrit que le directeur avait organisé tout le piège. Par conséquent, Karim fut libéré, et le directeur et le collègue furent condamnés. Aujourd''hui, Karim a sa propre entreprise. En plus, il aide gratuitement des gens qui ont des problèmes de dettes. Il dit toujours : « Ce ne sont pas les erreurs qui comptent, mais ce qu''on en apprend. »","translation":"My brother Karim is an accountant in a large company in Marseille. He has always been honest and well liked by his bosses. However, a year ago, he went through a difficult time. Although he liked his job, his salary wasn''t enough to pay his debts. One day, a colleague offered him a way out: a few “somewhat special” transactions. Karim hesitated; nevertheless, as he was desperate, he accepted. He didn''t know that this colleague had been paid by a corrupt director to set him up. A few weeks later, after signing documents that proved the fraud, he was arrested. He didn''t know what to do, because he knew he had made a mistake, even though he had never received any money. Fortunately, his former bosses paid his bail and found him an excellent lawyer. During the investigation, she discovered that the director had organized the whole trap. Consequently, Karim was released, and the director and the colleague were convicted. Today, Karim has his own company. Moreover, he helps people with debt problems for free. He always says: “It''s not the mistakes that count, but what you learn from them.”","translations":{"es":"Mi hermano Karim es contable en una gran empresa de Marsella. Siempre ha sido honrado y apreciado por sus jefes. Sin embargo, hace un año pasó por una época difícil. Aunque le gustaba su trabajo, su sueldo no le alcanzaba para pagar sus deudas. Un día, un compañero le propuso una salida: unas transacciones «un poco especiales». Karim dudó; no obstante, como estaba desesperado, aceptó. No sabía que a ese compañero le había pagado un director corrupto para tenderle una trampa. Unas semanas después, tras firmar unos documentos que demostraban el fraude, lo detuvieron. No sabía qué hacer, porque sabía que había cometido un error, aunque nunca había recibido dinero. Por suerte, sus antiguos jefes pagaron la fianza y le buscaron una abogada excelente. Durante la investigación, ella descubrió que el director había organizado toda la trampa. Por consiguiente, liberaron a Karim y condenaron al director y al compañero. Hoy Karim tiene su propia empresa. Además, ayuda gratis a personas con problemas de deudas. Siempre dice: «No son los errores lo que importa, sino lo que se aprende de ellos.»"},"highlighted_words":["Cependant","Bien que son travail lui plaise","dettes","proposa","néanmoins","accepta","avait été payé","corrompu","fut arrêté","même s''il n''avait jamais reçu","caution","avocate","enquête","Par conséquent","furent condamnés","En plus"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Il","a","été","déclaré","innocent"],"translation":"He was declared innocent","translations":{"es":"Lo declararon inocente"}},{"words":["Bien","qu''il","soit","riche","il","n''est","pas","heureux"],"translation":"Although he''s rich he isn''t happy","translations":{"es":"Aunque es rico, no es feliz"}},{"words":["Elle","n''a","pas","de","preuves","par","conséquent","elle","a","perdu"],"translation":"She has no evidence so she lost","translations":{"es":"No tiene pruebas, por consiguiente perdió"}},{"words":["J''ai","besoin","d''un","avocat"],"translation":"I need a lawyer","translations":{"es":"Necesito un abogado"}},{"words":["Le","témoin","a","tout","vu"],"translation":"The witness saw everything","translations":{"es":"El testigo lo vio todo"}},{"words":["Il","est","honnête","en","revanche","son","frère","ne","l''est","pas"],"translation":"He''s honest whereas his brother isn''t","translations":{"es":"Él es honrado; en cambio, su hermano no"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"He is guilty","translations":{"es":"Es culpable"},"answer":"Il est coupable"},{"prompt":"She won the trial","translations":{"es":"Ganó el juicio"},"answer":"Elle a gagné le procès"},{"prompt":"However, he lied","translations":{"es":"Sin embargo, mintió"},"answer":"Cependant, il a menti"},{"prompt":"Where is the court?","translations":{"es":"¿Dónde está el tribunal?"},"answer":"Où est le tribunal ?"},{"prompt":"He was arrested yesterday","translations":{"es":"Lo detuvieron ayer"},"answer":"Il a été arrêté hier"},{"prompt":"Moreover, he was late","translations":{"es":"Además, llegó tarde"},"answer":"En plus, il était en retard"}]}'::jsonb, 6)
) as v(type, title, content, ord);

-- Leçon 60: Les activités quotidiennes
with m as (
  insert into modules (language_code, slug, title, icon, description, order_index, is_published)
  values ('fr', 'lecon-60', 'Les activités quotidiennes', '☀️', 'Las actividades diarias', 60, true)
  returning id
)
insert into lessons (module_id, type, title, content, order_index, is_published)
select m.id, v.type, v.title, v.content, v.ord, true from m, (values
  ('vocabulary', 'Vocabulaire', '{"items":[{"id":"1","word":"le commerçant / la commerçante","translation":"the shopkeeper","translations":{"es":"el comerciante / la comerciante"}},{"id":"2","word":"l''acteur / l''actrice","translation":"actor / actress","translations":{"es":"el actor / la actriz"}},{"id":"3","word":"le vendeur / la vendeuse","translation":"salesman / saleswoman","translations":{"es":"el vendedor / la vendedora"}},{"id":"4","word":"l''étudiant / l''étudiante","translation":"student","translations":{"es":"el estudiante / la estudiante"}},{"id":"5","word":"le médecin / la médecin","translation":"doctor","translations":{"es":"el médico / la médica"}},{"id":"6","word":"le roi / la reine","translation":"king / queen","translations":{"es":"el rey / la reina"}},{"id":"7","word":"le prince / la princesse","translation":"prince / princess","translations":{"es":"el príncipe / la princesa"}},{"id":"8","word":"le duc / la duchesse","translation":"duke / duchess","translations":{"es":"el duque / la duquesa"}},{"id":"9","word":"le dieu / la déesse","translation":"god / goddess","translations":{"es":"el dios / la diosa"}},{"id":"10","word":"le veuf / la veuve","translation":"widower / widow","translations":{"es":"el viudo / la viuda"}},{"id":"11","word":"le neveu / la nièce","translation":"nephew / niece","translations":{"es":"el sobrino / la sobrina"}},{"id":"12","word":"l''oncle / la tante","translation":"uncle / aunt","translations":{"es":"el tío / la tía"}},{"id":"13","word":"le cousin / la cousine","translation":"cousin","translations":{"es":"el primo / la prima"}},{"id":"14","word":"le grand-père / la grand-mère","translation":"grandfather / grandmother","translations":{"es":"el abuelo / la abuela"}},{"id":"15","word":"le fiancé / la fiancée","translation":"fiancé / fiancée","translations":{"es":"el prometido / la prometida"}},{"id":"16","word":"le petit ami / la petite amie","translation":"boyfriend / girlfriend","translations":{"es":"el novio / la novia"}},{"id":"17","word":"le coq / la poule","translation":"rooster / hen","translations":{"es":"el gallo / la gallina"}},{"id":"18","word":"le taureau / la vache","translation":"bull / cow","translations":{"es":"el toro / la vaca"}},{"id":"19","word":"le type","translation":"the guy","translations":{"es":"el tipo"}},{"id":"20","word":"les meubles","translation":"furniture","translations":{"es":"los muebles"}},{"id":"21","word":"la chaise","translation":"the chair","translations":{"es":"la silla"}},{"id":"22","word":"se réveiller","translation":"to wake up","translations":{"es":"despertarse"}},{"id":"23","word":"se lever","translation":"to get up","translations":{"es":"levantarse"}},{"id":"24","word":"arroser","translation":"to water","translations":{"es":"regar"}},{"id":"25","word":"traire","translation":"to milk","translations":{"es":"ordeñar"}},{"id":"26","word":"rester éveillé","translation":"to stay awake","translations":{"es":"quedarse despierto"}},{"id":"27","word":"quotidien / quotidienne","translation":"daily","translations":{"es":"cotidiano / cotidiana"}},{"id":"28","word":"monotone","translation":"monotonous","translations":{"es":"monótono"}},{"id":"29","word":"passionnant / passionnante","translation":"exciting","translations":{"es":"apasionante"}},{"id":"30","word":"ennuyeux / ennuyeuse","translation":"boring","translations":{"es":"aburrido / aburrida"}},{"id":"31","word":"la routine","translation":"the routine","translations":{"es":"la rutina"}},{"id":"32","word":"tous les jours","translation":"every day","translations":{"es":"todos los días"}}],"grammar":[{"structure":"genre des noms","example":"un acteur / une actrice, un roi / une reine, un veuf / une veuve, un dieu / une déesse","en":"Masculine and feminine nouns","es":"Sustantivos masculinos y femeninos"},{"structure":"présent d''habitude","example":"Je me lève tôt tous les jours. / Le coq me réveille chaque matin.","en":"Present for routines","es":"Presente para rutinas"},{"structure":"tous / toutes les + nom","example":"tous les dimanches, toutes les nuits, une fois tous les deux jours","en":"Frequency expressions","es":"Expresiones de frecuencia"},{"structure":"conditionnel (souhait)","example":"J''aimerais avoir une vie plus passionnante.","en":"Wishes","es":"Deseos"},{"structure":"espérer que + indicatif","example":"J''espère que nous pourrons le faire bientôt.","en":"\"To hope\" + indicative","es":"«Esperar que» + indicativo"},{"structure":"afin de / pour + infinitif","example":"Je travaille afin d''économiser de l''argent.","en":"Purpose","es":"Finalidad"},{"structure":"être en train de","example":"Les meubles sont en train de s''abîmer.","en":"Ongoing action","es":"Acción en curso"}],"tips":[{"en":"Some feminines are completely different words: le roi / la reine, le coq / la poule, le parrain / la marraine, l''oncle / la tante, le neveu / la nièce.","es":"Algunos femeninos son palabras totalmente distintas: le roi / la reine, le coq / la poule, le parrain / la marraine, l''oncle / la tante, le neveu / la nièce."},{"en":"Professions are now often feminized: \"une médecin\", \"une professeure\", \"une autrice\". \"Doctoresse\" is old-fashioned.","es":"Hoy se feminizan a menudo las profesiones: «une médecin», «une professeure», «une autrice». «Doctoresse» está anticuado."},{"en":"\"Espérer que\" takes the indicative (future or present): \"J''espère que tu viendras.\" (In Spanish: \"Espero que vengas.\")","es":"«Espérer que» va con indicativo (futuro o presente): «J''espère que tu viendras.» (En español: «Espero que vengas».)"},{"en":"Congratulations! You have finished the 60 lessons. \"Félicitations, vous avez terminé le cours !\"","es":"¡Enhorabuena! Has terminado las 60 lecciones. «Félicitations, vous avez terminé le cours !»"}]}'::jsonb, 1),
  ('phrases', 'Phrases', '{"phrases":[{"phrase":"Mon père m''emmène au lycée tous les jours.","translation":"My father takes me to school every day.","translations":{"es":"Mi padre me lleva al instituto todos los días."}},{"phrase":"Ma mère a acheté un poisson.","translation":"My mother bought a fish.","translations":{"es":"Mi madre ha comprado un pescado."}},{"phrase":"Un acteur doit répéter son texte.","translation":"An actor has to rehearse his lines.","translations":{"es":"Un actor tiene que ensayar su texto."}},{"phrase":"Mon cousin me rend visite tous les dimanches.","translation":"My cousin visits me every Sunday.","translations":{"es":"Mi primo me visita todos los domingos."}},{"phrase":"Il faut arroser les fleurs une fois tous les deux jours.","translation":"You have to water the flowers once every two days.","translations":{"es":"Hay que regar las flores una vez cada dos días."}},{"phrase":"Ma grand-mère trait les vaches tous les jours à cinq heures du matin.","translation":"My grandmother milks the cows every day at 5 a.m.","translations":{"es":"Mi abuela ordeña las vacas todos los días a las cinco de la mañana."}},{"phrase":"Elles sont d''excellentes vendeuses.","translation":"They are excellent saleswomen.","translations":{"es":"Son unas vendedoras excelentes."}},{"phrase":"Ma fiancée étudie de huit heures du matin à huit heures du soir.","translation":"My fiancée studies from 8 a.m. to 8 p.m.","translations":{"es":"Mi prometida estudia de ocho de la mañana a ocho de la noche."}},{"phrase":"Les enfants restent éveillés très tard toutes les nuits.","translation":"The children stay up very late every night.","translations":{"es":"Los niños se quedan despiertos hasta muy tarde todas las noches."}},{"phrase":"La reine doit protéger son peuple. Le prince sera roi, mais seulement s''il est l''aîné.","translation":"The queen must protect her people. The prince will be king, but only if he is the eldest.","translations":{"es":"La reina debe proteger a su pueblo. El príncipe será rey, pero solo si es el mayor."}},{"phrase":"Le coq me réveille tous les jours à quatre heures pile.","translation":"The rooster wakes me up every day at four on the dot.","translations":{"es":"El gallo me despierta todos los días a las cuatro en punto."}},{"phrase":"C''est la veuve de M. Marceau ? — Oui.","translation":"Is she Mr. Marceau''s widow? — Yes.","translations":{"es":"¿Es la viuda del señor Marceau? — Sí."}},{"phrase":"Qui est Vénus ? — C''est une déesse. Et Zeus ? — C''est un dieu.","translation":"Who is Venus? — She is a goddess. And Zeus? — He is a god.","translations":{"es":"¿Quién es Venus? — Es una diosa. ¿Y Zeus? — Es un dios."}},{"phrase":"C''est ta petite amie ? — Non, c''est seulement une amie.","translation":"Is she your girlfriend? — No, she''s just a friend.","translations":{"es":"¿Es tu novia? — No, solo es una amiga."}}]}'::jsonb, 2),
  ('qa', 'Questions', '{"questions":[{"id":"1","question":"What is the feminine of \"roi\"?","options":["roiesse","royale","roie","reine"],"correct":3,"explanation":"Completely different word.","translations":{"es":{"question":"¿Cuál es el femenino de «roi»?","explanation":"Palabra totalmente distinta."}}},{"id":"2","question":"What is the feminine of \"veuf\"?","options":["veuvesse","veufe","veuffe","veuve"],"correct":3,"explanation":"-f → -ve (neuf → neuve, veuf → veuve).","translations":{"es":{"question":"¿Cuál es el femenino de «veuf»?","explanation":"-f → -ve (neuf → neuve, veuf → veuve)."}}},{"id":"3","question":"What is the feminine of \"dieu\"?","options":["dieue","divine","dieuse","déesse"],"correct":3,"explanation":"Like prince → princesse, duc → duchesse.","translations":{"es":{"question":"¿Cuál es el femenino de «dieu»?","explanation":"Como prince → princesse, duc → duchesse."}}},{"id":"4","question":"Complete: \"Il faut arroser les plantes une fois ___ les deux jours.\"","options":["tout","toutes","chaque","tous"],"correct":3,"explanation":"Tous les + plural masculine noun (jours).","translations":{"es":{"question":"Completa: «Il faut arroser les plantes une fois ___ les deux jours.»","explanation":"Tous les + sustantivo masculino plural (jours)."}}},{"id":"5","question":"Complete: \"J''espère que nous ___ partir bientôt.\"","options":["pouvions","puissions","pourrions","pourrons"],"correct":3,"explanation":"\"Espérer que\" + indicative (future).","translations":{"es":{"question":"Completa: «J''espère que nous ___ partir bientôt.»","explanation":"«Espérer que» + indicativo (futuro)."}}},{"id":"6","question":"How do you express a wish?","options":["J''aime voyager plus hier.","J''aimerai voyager hier.","J''aimais voyager demain.","J''aimerais voyager plus."],"correct":3,"explanation":"Conditional of aimer.","translations":{"es":{"question":"¿Cómo expresas un deseo?","explanation":"Condicional de aimer."}}},{"id":"7","question":"What is the feminine of \"coq\"?","options":["coque","coquette","poulette","poule"],"correct":3,"explanation":"Le coq / la poule.","translations":{"es":{"question":"¿Cuál es el femenino de «coq»?","explanation":"Le coq / la poule."}}},{"id":"8","question":"Which form is modern for a female doctor?","options":["une médecine","une doctoresse","une docteuse","une médecin"],"correct":3,"explanation":"\"Doctoresse\" is old-fashioned.","translations":{"es":{"question":"¿Qué forma es la actual para una doctora?","explanation":"«Doctoresse» está anticuado."}}}]}'::jsonb, 3),
  ('story', 'Une vie trop monotone', '{"text":"Je m''appelle Bruno et, en ce moment, je trouve ma vie un peu ennuyeuse. Tous les jours, c''est la même routine : je me réveille à six heures, j''emmène ma femme au travail, je vais à la salle de sport pendant une heure, puis je vais au bureau. Le soir, nous dînons devant la télévision et nous nous couchons tôt. Le week-end, sa mère nous appelle toutes les deux heures pour savoir ce que nous faisons, et son père est toujours en train de me chercher un « meilleur » travail. Pourtant, mon emploi me plaît. Ce n''est pas mon travail qui m''ennuie, c''est cette façon de vivre qui ne me laisse pas profiter du monde et de ses merveilles. J''aimerais avoir une vie plus passionnante : faire des randonnées avec mes amis, voyager en Europe, découvrir de nouvelles cultures avec ma femme. Alors, j''ai un plan : je vais économiser afin d''acheter un petit chalet à la montagne. Je veux vivre sous un grand ciel bleu, entouré d''oiseaux et de fleurs. Ma femme est d''accord : elle aussi veut se reposer et profiter de chaque jour de notre mariage. J''espère que nous pourrons le faire bientôt… sinon, nous allons devenir fous ! Et toi, à quoi ressemble ta journée ?","translation":"My name is Bruno and, right now, I find my life a bit boring. Every day, it''s the same routine: I wake up at six, I take my wife to work, I go to the gym for an hour, then I go to the office. In the evening, we have dinner in front of the TV and go to bed early. On weekends, her mother calls us every two hours to find out what we''re doing, and her father is always looking for a “better” job for me. And yet, I like my job. It''s not my work that bores me, it''s this way of living that doesn''t let me enjoy the world and its wonders. I''d like a more exciting life: hiking with my friends, traveling around Europe, discovering new cultures with my wife. So I have a plan: I''m going to save money to buy a little chalet in the mountains. I want to live under a big blue sky, surrounded by birds and flowers. My wife agrees: she also wants to rest and enjoy every day of our marriage. I hope we can do it soon… otherwise, we''re going to go crazy! And you, what does your day look like?","translations":{"es":"Me llamo Bruno y, en este momento, mi vida me parece un poco aburrida. Todos los días es la misma rutina: me despierto a las seis, llevo a mi mujer al trabajo, voy al gimnasio una hora y luego voy a la oficina. Por la noche cenamos delante de la tele y nos acostamos pronto. Los fines de semana, su madre nos llama cada dos horas para saber qué estamos haciendo, y su padre siempre está buscándome un trabajo «mejor». Sin embargo, mi empleo me gusta. No es el trabajo lo que me aburre, es esta forma de vivir que no me deja disfrutar del mundo y de sus maravillas. Me gustaría tener una vida más apasionante: hacer excursiones con mis amigos, viajar por Europa, descubrir nuevas culturas con mi mujer. Así que tengo un plan: voy a ahorrar para comprar una casita en la montaña. Quiero vivir bajo un gran cielo azul, rodeado de pájaros y flores. Mi mujer está de acuerdo: ella también quiere descansar y disfrutar de cada día de nuestro matrimonio. Espero que podamos hacerlo pronto… ¡si no, nos vamos a volver locos! Y tú, ¿cómo es tu día?"},"highlighted_words":["Tous les jours","routine","je me réveille","toutes les deux heures","est toujours en train de","Pourtant","J''aimerais","afin d''acheter","ma femme","J''espère que nous pourrons","sinon"]}'::jsonb, 4),
  ('arrange', 'Construis des phrases', '{"sentences":[{"words":["Je","me","lève","tôt","tous","les","jours"],"translation":"I get up early every day","translations":{"es":"Me levanto temprano todos los días"}},{"words":["Mon","cousin","vient","tous","les","dimanches"],"translation":"My cousin comes every Sunday","translations":{"es":"Mi primo viene todos los domingos"}},{"words":["J''aimerais","voyager","plus"],"translation":"I would like to travel more","translations":{"es":"Me gustaría viajar más"}},{"words":["J''espère","que","tu","viendras"],"translation":"I hope you will come","translations":{"es":"Espero que vengas"}},{"words":["La","reine","protège","son","peuple"],"translation":"The queen protects her people","translations":{"es":"La reina protege a su pueblo"}},{"words":["C''est","la","veuve","de","mon","oncle"],"translation":"She''s my uncle''s widow","translations":{"es":"Es la viuda de mi tío"}}]}'::jsonb, 5),
  ('translate', 'Traduis en français', '{"items":[{"prompt":"I wake up at six","translations":{"es":"Me despierto a las seis"},"answer":"Je me réveille à six heures"},{"prompt":"My life is monotonous","translations":{"es":"Mi vida es monótona"},"answer":"Ma vie est monotone"},{"prompt":"She''s an actress","translations":{"es":"Es actriz"},"answer":"C''est une actrice"},{"prompt":"He waters the flowers","translations":{"es":"Riega las flores"},"answer":"Il arrose les fleurs"},{"prompt":"The rooster crows every morning","translations":{"es":"El gallo canta todas las mañanas"},"answer":"Le coq chante tous les matins"},{"prompt":"Congratulations!","translations":{"es":"¡Enhorabuena!"},"answer":"Félicitations !"}]}'::jsonb, 6)
) as v(type, title, content, ord);
